window.BO3D = window.BO3D || {};
BO3D.ot = {"story":{"title":"비상 착륙","lines":[{"who":"narr","text":"시간 속을 달리던 타임머신이 덜컹 흔들리더니 비상 착륙했어요. 계기판의 불이 하나둘 꺼졌어요."},{"who":"doctor","text":"얘들아, 들리니? 나 최현 박사야. 기능이 많이 멎었지만 통신은 살아 있어. 내가 여기 현재에서 도울게."},{"who":"doctor","text":"그 시대에는 우리 부속이 없어. 그러니 그 자리에서 구할 수 있는 평범한 재료로 부속을 대신 만들자. 사건이 일어나는 자리의 물건에는 손대지 말고, 떨어진 것만 줍자."},{"who":"onwoo","text":"그리고 우리는 끝까지 지켜보는 사람이야. 본 것은 성경책에서 꼭 확인하자."}],"rule":"과거에는 아무것도 남기지 않아요. 가져오는 것은 사진과 기록, 그리고 수리에 쓸 재료뿐이에요. 기념품은 가져오지 않아요."},"eras":[{"era":1,"name":"창조와 타락","key":"creation","intro":"시간 계기판이 맨 처음 시대를 가리키고 있어. 여기서부터 차례로 가 보자.","between":["창 2:4-14","창 2:18-25","창 4:1-6:8","창 9:18-10:32"],"scenes":["OT-01","OT-02","OT-03","OT-04"]},{"era":2,"name":"족장","key":"patriarchs","intro":"계기판이 다음 시대로 넘어왔어. 장막과 길이 많은 시대라고 나오는구나.","between":["창 11:10-32","창 12:10-14:24","창 15:7-21:34","창 22:20-28:9","창 29:1-37:11","창 38:1-44:34","창 45:16-50:26"],"scenes":["OT-05","OT-06","OT-07","OT-08"]},{"era":3,"name":"출애굽","key":"exodus","intro":"이번 시대는 애굽과 광야 사이야. 모래바람 때문에 통신이 조금 끊길 수 있어.","between":["출 1:1-2:25","출 3:13-10:29","출 12:43-13:22","출 15:1-15:27","출 17:1-18:27"],"scenes":["OT-09","OT-10","OT-11","OT-12"]},{"era":4,"name":"광야","key":"wilderness","intro":"광야 시대야. 넓고 마른 땅이 계기판에 가득 잡혀.","between":["출 20:22-31:18","출 33:1-40:38","레 1:1-27:34","민 1:1-12:16","민 14:39-36:13","신 1:1-33:29"],"scenes":["OT-13","OT-14","OT-15","OT-16"]},{"era":5,"name":"가나안 정복","key":"conquest","intro":"강과 성이 보이는 시대로 넘어왔어. 재료 찾을 곳이 많겠다.","between":["수 1:1-18","수 5:1-15","수 7:1-23:16","수 24:29-33"],"scenes":["OT-17","OT-18","OT-19","OT-20"]},{"era":6,"name":"사사","key":"judges","intro":"언덕과 밭이 많은 시대야. 길을 잃지 않게 휴가 지도를 잘 적어 줘.","between":["삿 1:1-6:10","삿 6:17-40","삿 7:23-16:3","삿 17:1-21:25","룻 3:1-4:12","룻 4:18-22","삼상 1:1-8","삼상 2:1-36"],"scenes":["OT-21","OT-22","OT-23","OT-24"]},{"era":7,"name":"통일 왕국","key":"kingdom","intro":"왕이 다스리는 시대로 왔어. 성과 궁이 계기판에 잡혀.","between":["삼상 4:1-7:17","삼상 8:1-3","삼상 9:1-10:16","삼상 10:26-16:23","삼상 17:55-31:13","삼하 1:1-6:23","삼하 7:18-24:25","왕상 1:1-7:51","왕상 8:31-53","왕상 8:62-11:43"],"scenes":["OT-25","OT-26","OT-27","OT-28"]},{"era":8,"name":"분열 왕국","key":"divided","intro":"나라가 둘로 나뉜 시대라고 나와. 북쪽과 남쪽을 헷갈리지 말자.","between":["왕상 12:25-18:19","왕상 18:40-22:53","왕하 1:1-16:20","왕하 17:24-41"],"scenes":["OT-29","OT-30","OT-31","OT-32"]},{"era":9,"name":"유다와 포로","key":"exile","intro":"남쪽 유다의 시대야. 멀리 큰 강의 나라도 잡히는구나.","between":["왕하 18:1-12","왕하 20:1-21:26","왕하 23:4-24:20","왕하 25:22-30","단 1:1-5:31","단 7:1-12:13"],"scenes":["OT-33","OT-34","OT-35","OT-36"]},{"era":10,"name":"귀환","key":"return","intro":"마지막 시대야. 무너진 곳을 다시 쌓는 소리가 통신에 섞여 들려.","between":["스 2:1-3:7","스 4:1-6:13","스 6:19-10:44","에 1:1-3:15","에 5:1-6:14","에 8:1-10:3","느 1:1-2:10","느 3:1-6:14","느 6:17-7:73","느 8:13-13:31","말 1:1-2:17","말 3:2-18"],"scenes":["OT-37","OT-38","OT-39","OT-40"]}],"order":["OT-01","OT-02","OT-03","OT-04","OT-05","OT-06","OT-07","OT-08","OT-09","OT-10","OT-11","OT-12","OT-13","OT-14","OT-15","OT-16","OT-17","OT-18","OT-19","OT-20","OT-21","OT-22","OT-23","OT-24","OT-25","OT-26","OT-27","OT-28","OT-29","OT-30","OT-31","OT-32","OT-33","OT-34","OT-35","OT-36","OT-37","OT-38","OT-39","OT-40"],"scenes":{"OT-01":{"id":"OT-01","era":1,"title":"하나님이 천지를 지으심","ref":"창 1:1-2:3","place":"하나님이 지으신 하늘과 땅","review":{"required":false,"topics":[],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"창 1:1-2","focus":"deep","text":{"t1":"맨 처음에 하나님이 하늘과 땅을 지으셨어요. 땅은 아직 비어 있었고, 깊은 물 위에는 어둠이 있었어요.","t2":"태초에 하나님이 하늘과 땅을 창조하셨어요. 땅은 모양이 잡히지 않은 채 비어 있었고, 어둠이 깊은 물 위에 있었어요. 하나님의 영은 물 위에 움직이고 계셨어요.","t3":"태초에 하나님이 천지를 창조하셨다. 땅은 혼돈하고 공허했으며 어둠이 깊음 위에 있었고, 하나님의 영은 수면 위에 운행하고 계셨다."},"say":{"who":"hyu","text":"성경의 맨 처음이야. 창세기 1장 1절부터 차례대로 적어 둘게."}},{"ref":"창 1:3-5","open":"창 1:3","focus":"light","text":{"t1":"첫째 날에 하나님이 말씀하시자 무엇이 생겼는지는 성경에서 찾아봐요. 하나님은 이날 낮과 밤이라는 이름을 붙이셨어요.","t2":"하나님이 빛이 있으라고 하시자 빛이 있었어요. 그다음에 일어난 일들의 차례는 4절과 5절에서 읽어 봐요.","t3":"하나님이 빛이 있으라고 하시니 빛이 있었다. 하나님이 그 빛을 보시고 어떠하셨는지는 4절에서 직접 읽어 보자. 하나님은 빛과 어둠을 나누어 빛을 낮이라, 어둠을 밤이라 부르셨다. 저녁이 되고 아침이 되니 첫째 날이었다."},"say":{"who":"onwoo","text":"하나님이 하신 말씀은 우리가 지어내면 안 돼. 창세기 1장 3절에서 직접 읽어 보자."}},{"ref":"창 1:6-13","open":"창 1:6-11","focus":"sky_land_sea","text":{"t1":"둘째 날에 하나님은 궁창을 만드시고 하늘이라 부르셨어요. 셋째 날에는 물을 한곳에 모아 땅과 바다가 되게 하시고, 땅에서 풀과 나무가 나게 하셨어요.","t2":"둘째 날에 하나님은 궁창을 만들어 그 아래의 물과 위의 물을 나누시고, 궁창을 하늘이라 부르셨어요. 셋째 날에는 하늘 아래의 물을 한곳에 모아 뭍이 드러나게 하시고, 뭍을 땅, 모인 물을 바다라 부르셨어요. 땅은 풀과 씨 맺는 채소와 열매 맺는 나무를 냈어요.","t3":"둘째 날, 하나님은 물 가운데 궁창을 만들어 궁창 아래의 물과 궁창 위의 물을 나누시고 궁창을 하늘이라 부르셨다. 셋째 날, 하늘 아래의 물이 한곳으로 모여 뭍이 드러났고, 하나님은 뭍을 땅이라, 모인 물을 바다라 부르셨다. 땅은 풀과 씨 맺는 채소와 씨 가진 열매를 맺는 나무를 저마다 종류대로 냈다."},"say":{"who":"choeon","text":"하늘이 생기고, 땅과 바다가 나뉘고, 땅에서 풀과 나무가 났대!"}},{"ref":"창 1:14-19","open":"창 1:14-15","focus":"lights","text":{"t1":"넷째 날에 하나님은 하늘에 큰 빛 둘과 별들을 만드셨어요. 큰 빛은 낮을, 작은 빛은 밤을 맡았어요.","t2":"넷째 날에 하나님은 하늘의 궁창에 두 큰 광명을 만드셨어요. 큰 광명은 낮을, 작은 광명은 밤을 맡게 하셨고 별들도 만드셨어요. 이 빛들은 낮과 밤을 나누고 땅을 비추었어요.","t3":"넷째 날, 하나님은 하늘의 궁창에 광명들이 있어 낮과 밤을 나누고 징조와 계절과 날과 해를 이루게 하셨다. 두 큰 광명을 만들어 큰 것은 낮을, 작은 것은 밤을 주관하게 하시고 별들도 만드셨다. 그 광명들을 궁창에 두어 땅을 비추게 하셨다."},"say":{"who":"hyu","text":"넷째 날은 낮을 맡은 큰 빛, 밤을 맡은 작은 빛, 그리고 별들. 일지에 적었어."}},{"ref":"창 1:20-23","open":"창 1:22","focus":"fish_birds","text":{"t1":"다섯째 날에 하나님은 새로운 생물들을 종류대로 지으시고, 복을 주시며 많아지라고 하셨어요. 무엇을 지으셨는지는 21절에서 찾아봐요.","t2":"다섯째 날에 하나님은 큰 물고기와 물속에서 움직이는 온갖 생물, 날개 달린 온갖 새를 종류대로 창조하셨어요. 하나님은 그들에게 복을 주시며, 바닷물에 가득하고 새들도 땅에서 많아지라고 하셨어요.","t3":"다섯째 날, 하나님은 물이 생물로 가득하고 새가 땅 위 하늘의 궁창을 날게 하셨다. 큰 물고기와 물속에서 움직이는 온갖 생물, 날개 달린 온갖 새를 그 종류대로 창조하셨다. 그들에게 내리신 복의 말씀은 22절에서 직접 읽어 보자."},"say":{"who":"choeon","text":"와, 새로운 생물들이 가득해! 무엇인지 일지에 적기 전에 21절을 펴 보자."}},{"ref":"창 1:24-31","open":"창 1:26-28","focus":"animals_people","text":{"t1":"여섯째 날에 하나님은 땅의 짐승들을 만드시고, 사람을 남자와 여자로 지으셨어요. 하나님이 보시기에 모든 것이 매우 좋았어요.","t2":"여섯째 날에 하나님은 가축과 기는 것과 땅의 짐승을 종류대로 만드셨어요. 또 하나님은 자기의 형상대로 사람을 지으셨는데, 남자와 여자로 창조하셨어요. 하나님이 사람에게 무엇을 맡기셨는지는 26절과 28절에서 찾아봐요. 하나님이 지으신 모든 것을 보시니 매우 좋았어요.","t3":"여섯째 날, 하나님은 들짐승과 가축과 땅 위를 기는 것들을 저마다 종류대로 만드셨다. 그리고 자기 형상대로 사람을 지으시되 남자와 여자로 창조하셨다. 또 씨 맺는 채소와 열매 맺는 나무를 사람에게, 푸른 풀을 짐승과 새와 기는 것에게 먹을거리로 주셨다. 사람에게 내리신 복의 말씀과, 지으신 모든 것을 보시고 어떠하셨는지는 28절과 31절에 있다. 저녁이 되고 아침이 되니 여섯째 날이었다."},"say":{"who":"onwoo","text":"사람을 어떻게 지으셨는지는 창세기 1장 27절에 적혀 있어. 같이 찾아보자."}},{"ref":"창 2:1-3","focus":"seventh_day","text":{"t1":"하나님은 모든 일을 마치시고 일곱째 날에 안식하셨어요. 그리고 그날을 복 주시고 거룩하게 하셨어요.","t2":"하늘과 땅과 모든 것이 다 이루어졌어요. 하나님은 일곱째 날을 복 주시고 거룩하게 하셨어요. 왜 그날을 그렇게 하셨는지는 2장 2절과 3절에서 찾아봐요.","t3":"천지와 만물이 다 이루어졌다. 하나님은 지으시던 일을 일곱째 날에 마치시고 그날에 안식하셨다. 하나님은 일곱째 날을 복되게 하시고 거룩하게 하셨는데, 창조하며 만드시던 일을 모두 마치고 그날에 안식하셨기 때문이다."},"say":{"who":"hyu","text":"첫째 날부터 일곱째 날까지 일지에 순서대로 다 적었어."}}],"gates":{"t1":[{"type":"find","ref":"창 1:3","prompt":"성경책에서 창세기 1장 3절을 찾아 읽어 보세요.","confirm":{"prompt":"하나님이 있으라고 말씀하시자 무엇이 생겼나요?","options":[{"label":"빛","ok":true},{"label":"별들","basis":"창 1:16"},{"label":"무지개","basis":"창 9:13"}]}},{"type":"multi","ref":"창 1:21","prompt":"성경책에서 창세기 1장 21절을 찾아 읽어 보세요.","confirm":{"prompt":"다섯째 날에 하나님이 종류대로 창조하신 것을 모두 고르세요.","options":[{"label":"큰 물고기","ok":true},{"label":"뱀","basis":"창 3:1"},{"label":"물에서 움직이는 생물","ok":true},{"label":"날개 있는 새","ok":true},{"label":"두 큰 광명과 별들","basis":"창 1:16"}]}}],"t2":[{"type":"find","ref":"창 2:1-3","prompt":"성경책에서 창세기 2장 1절부터 3절까지 읽어 보세요.","confirm":{"prompt":"하나님이 일곱째 날에 복을 주시고 그날을 거룩하게 하신 까닭은 무엇인가요?","options":[{"label":"창조하며 만드시던 일을 모두 마치시고 그날에 안식하셨기 때문에","ok":true},{"label":"그날에 사람이 하나님 앞에 나아와 제사를 드리고 예배했기 때문에","basis":"본문에 없음"},{"label":"그날에 짐승들을 사람에게 데려가 이름을 짓게 하셨기 때문에","basis":"창 2:19"}]}},{"type":"order","ref":"창 1:3-5","prompt":"성경책에서 창세기 1장 3절부터 5절까지 읽고, 첫째 날에 일어난 차례대로 눌러 보세요.","items":["하나님이 빛이 있으라고 하셨다","빛을 보시고 좋다고 여기셨다","빛과 어둠을 나누셨다","빛은 낮, 어둠은 밤이라 부르셨다","저녁과 아침이 지나 첫째 날이 되었다"]}],"t3":[{"type":"find","refs":["창 1:4","창 1:10","창 1:31"],"prompt":"창세기 1장 4절, 10절, 31절을 함께 찾아 읽어 보자.","confirm":{"prompt":"하나님은 빛과 땅과 바다, 그리고 마지막에 지으신 모든 것을 보시고 어떠하다고 여기셨는가?","options":[{"label":"빛도 좋았고 땅과 바다도 좋았으며, 마지막에는 지으신 것을 모두 보시고 매우 좋다고 여기셨다","ok":true},{"label":"빛은 좋았으나 땅과 바다는 아직 좋지 않았고, 마지막에 지으신 것을 모두 보시고서야 비로소 좋다고 여기셨다","basis":"본문에 없음"},{"label":"빛도 좋았고 땅과 바다도 좋았으며, 마지막에 지으신 것도 앞의 것들처럼 그저 좋다고만 여기셨다","basis":"본문에 없음"}]}},{"type":"match","refs":["창 1:5","창 1:8","창 1:10"],"prompt":"창세기 1장 5절, 8절, 10절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"창 1:5","text":"빛은 낮, 어둠은 밤이라 부르셨다"},{"ref":"창 1:8","text":"궁창을 하늘이라 부르셨다"},{"ref":"창 1:10","text":"뭍은 땅, 모인 물은 바다라 부르셨다"}],"after":"세 곳을 이으면, 하나님은 첫째 날에 낮과 밤, 둘째 날에 하늘, 셋째 날에 땅과 바다라는 이름을 붙이셨다."}]},"cards":[{"ref":"창 1:1","title":"태초에 천지를 창조하심"},{"ref":"창 1:27","title":"하나님의 형상대로"}],"close":{"t1":{"kind":"prayer","text":"하나님, 하늘과 땅과 모든 것을 하나님이 지으셨음을 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 창세기 1장 1절부터 2장 3절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"창 1:1-2:3에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 타임머신이 비상 착륙하면서 회전축에 끼우는 작은 구슬이 빠졌어요. 지금은 타임머신 안에서 지켜보다가, 나중에 구슬 대신 쓸 것을 찾아봐요.","t2":"최현 박사예요. 비상 착륙 때 회전축에 끼우는 작은 구슬이 빠져서 타임머신이 움직이지 못해요. 이 시대에는 우리 부속이 없으니, 이곳에서 구할 수 있는 것으로 대신 만들어야 해요. 그때까지는 타임머신 안에서 지켜봐요.","t3":"최현 박사다. 비상 착륙으로 회전축의 작은 구슬이 빠져 타임머신이 멈췄고, 지금은 통신만 이어져 있다. 이 시대에는 부속을 구할 수 없으니 이곳에서 얻을 수 있는 재료로 구슬을 대신해야 한다. 그때까지는 타임머신 안에서 지켜보자."},"materials":[{"key":"seed","name":"씨앗","basis":"창 1:12","use":"단단하고 동그란 씨앗을 빠진 구슬 대신 회전축에 끼워 쓸 수 있어요.","how":"사람이 지어진 뒤에 타임머신에서 내려, 사람이 있는 곳에서 멀리 떨어진 나무 아래 땅에 떨어진 씨앗 몇 알을 줍는다. 나무에서 열매를 따지 않는다.","line":"씨앗을 주웠어! 나무 아래 땅에 떨어져 있었어."}],"companion":null,"today":[{"q":"하나님도 피곤해서 쉬셨어요?","a":{"t1":"성경은 하나님이 하시던 일을 다 마치시고 일곱째 날에 안식하셨다고 말해요. 그리고 이사야서는 땅 끝까지 지으신 하나님은 피곤하지도 지치지도 않으신다고 말해요.","t2":"창세기는 하나님이 지으시던 일을 일곱째 날에 다 마치시고 그날에 안식하셨다고 말해요. 그리고 그날을 복 주시고 거룩하게 하셨어요. 이사야서는 땅 끝까지 창조하신 여호와는 피곤하지도 지치지도 않으신다고 말해요.","t3":"창세기는 하나님이 창조하며 만드시던 일을 모두 마치시고 일곱째 날에 안식하셨으며, 그 때문에 그날을 복 주시고 거룩하게 하셨다고 말한다(창 2:2-3). 이사야서는 땅 끝까지 창조하신 영원하신 여호와는 피곤하지도 지치지도 않으신다고 말한다(사 40:28). 성경은 여기까지 말한다."},"refs":["창 2:2-3","사 40:28"]},{"q":"세상은 처음에 어떻게 생겨났어요?","a":{"t1":"성경은 맨 처음에 하나님이 하늘과 땅을 지으셨다고 말해요. 하나님이 말씀하시자 그대로 되었다고 적혀 있어요.","t2":"성경의 첫 절은 태초에 하나님이 하늘과 땅을 창조하셨다고 말해요. 창세기 1장에는 하나님이 말씀하시자 그대로 되었다는 기록이 거듭 나와요. 시편도 여호와의 말씀으로 하늘이 지어졌다고 노래해요.","t3":"성경의 첫 절은 태초에 하나님이 천지를 창조하셨다고 말한다(창 1:1). 창세기 1장은 하나님이 말씀하시자 빛이 있었고, 그 뒤에도 말씀하시는 대로 되었다고 거듭 기록한다(창 1:3, 1:9). 시편 33편도 여호와의 말씀으로 하늘이 지어졌고, 그가 말씀하시자 이루어졌다고 노래한다(시 33:6, 33:9). 성경은 여기까지 말한다."},"refs":["창 1:1","창 1:3","창 1:9","시 33:6","시 33:9"]}],"help":{"who":"돕는 상대 없음(창조의 날들을 타임머신 안에서 지켜보며, 우리 관찰 기록을 정리한다)","steps":[{"kind":"watch","after":2,"title":"타임머신 안에서 보기 · 말씀하시자 그대로 됨","basis":"창 1:9","text":{"t1":"하나님이 물은 한곳에 모이고 뭍은 드러나라고 하시자 그대로 되었어요. 하나님이 하시는 일이에요. 우리는 타임머신 안에서 지켜봐요.","t2":"하나님이 하늘 아래의 물은 한곳에 모이고 뭍은 드러나라고 말씀하시자 그대로 되었어요. 궁창을 만드실 때에도, 땅에 풀과 나무를 내라고 하실 때에도 말씀하신 대로 되었어요. 이것은 하나님이 하시는 일이에요. 우리는 손대지 않고 타임머신 안에서 지켜봐요.","t3":"하나님이 하늘 아래의 물은 한곳에 모이고 뭍은 드러나라고 하시니 그대로 되었다(1:9). 궁창을 만드실 때에도(1:7), 땅에 풀과 채소와 나무를 내라고 하실 때에도(1:11) 그대로 되었다고 적혀 있다. 이것은 하나님이 하시는 일이다. 탐험대는 타임머신 안에서 지켜본다."},"say":{"who":"hyu","text":"하나님이 말씀하시자 그대로 됐어. 일지에 적어 둘게."}},{"kind":"do","after":2,"title":"관찰 기록표 정리 · 첫째 날부터 셋째 날까지","basis":"창 1:3-13","text":{"t1":"우리는 타임머신 안에서 지금까지 본 것을 관찰 기록표에 정리해요. 날마다 생긴 것을 그날 칸에 적어요.","t2":"우리는 타임머신 안에서 첫째 날부터 셋째 날까지 지켜본 것을 관찰 기록표에 정리해요. 저녁이 되고 아침이 될 때마다 날이 바뀌었으니, 그 사이에 생긴 것을 그날 칸에 적어요.","t3":"탐험대는 타임머신 안에서 첫째 날부터 셋째 날까지 지켜본 것을 관찰 기록표에 정리한다. 본문은 날마다 저녁과 아침으로 그날을 맺는다. 그 사이에 생긴 것을 그날 칸에 옮겨 적는다."},"tasks":["첫째 날 칸에 3절에서 찾은 것 적기","둘째 날 칸에 하늘 적기","셋째 날 칸에 땅과 바다, 풀과 나무 적기"],"done":{"who":"hyu","text":"세 날의 칸을 다 채웠어. 다음 날도 지켜보자."}},{"kind":"do","after":5,"title":"관찰 기록표 정리 · 넷째 날부터 여섯째 날까지","basis":"창 1:14-31","text":{"t1":"우리는 타임머신 안에서 넷째 날부터 여섯째 날까지 본 것을 관찰 기록표에 이어서 적어요.","t2":"우리는 타임머신 안에서 넷째 날부터 여섯째 날까지 지켜본 것을 관찰 기록표에 이어서 정리해요. 무엇이 어느 날에 생겼는지 칸을 맞춰 적어요.","t3":"탐험대는 타임머신 안에서 넷째 날부터 여섯째 날까지 지켜본 것을 관찰 기록표에 이어서 정리한다. 넷째 날은 1:19, 다섯째 날은 1:23, 여섯째 날은 1:31에서 맺는다. 그 사이에 생긴 것을 그날 칸에 옮겨 적는다."},"tasks":["넷째 날 칸에 두 큰 광명과 별들 적기","다섯째 날 칸에 21절에서 찾은 것 적기","여섯째 날 칸에 짐승과 사람 적기"],"done":{"who":"onwoo","text":"여섯째 날까지 다 적었어. 맞게 적었는지 창세기 1장에서 다시 확인하자."}},{"kind":"ask","after":"gates","title":"사람을 지으신 일은 무슨 뜻이에요?","basis":"창 1:26-28","by":"최현 박사","ask":{"who":"choeon","text":"하나님이 사람을 지으시고 복을 주신 건 무슨 뜻이에요?"},"answer":{"t1":"성경은 하나님이 자기 형상대로 사람을 지으시되 남자와 여자로 지으셨다고 말해요. 그리고 그들에게 복을 주시며, 땅에 가득하고 바다와 하늘과 땅의 생물을 다스리라고 하셨어요. 성경은 여기까지 말해요.","t2":"창세기는 하나님이 사람을 만들자고 하시며, 사람이 바다의 물고기와 하늘의 새와 가축과 온 땅을 다스리게 하자고 하셨다고 말해요(1:26). 그리고 자기 형상대로 사람을 남자와 여자로 지으시고(1:27), 복을 주시며 번성하여 땅에 가득하고 모든 생물을 다스리라고 하셨어요(1:28). 형상이 무엇인지는 이 본문이 더 풀어 말하지 않아요.","t3":"창세기는 하나님이 사람을 만들자고 하시며, 그들이 바다의 물고기와 하늘의 새와 가축과 온 땅과 땅을 기는 것들을 다스리게 하자고 하셨다고 기록한다(1:26). 하나님은 자기 형상대로 사람을 지으시되 남자와 여자로 지으셨고(1:27), 그들에게 복을 주시며 번성하여 땅을 채우고 정복하며 땅 위에서 움직이는 생물을 모두 다스리라고 하셨다(1:28). 이 본문은 형상이 무엇인지 더 풀어 말하지 않는다. 성경은 여기까지 말한다."},"read":{"t1":{"type":"find","ref":"창 1:27","prompt":"성경책에서 창세기 1장 27절을 찾아 읽어 보세요.","confirm":{"prompt":"하나님은 사람을 누구의 형상대로 지으셨나요?","options":[{"label":"하나님의 형상","ok":true},{"label":"천사의 모양","basis":"본문에 없음"},{"label":"짐승의 모양","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"창 1:26-28","prompt":"성경책에서 창세기 1장 26절부터 28절까지 읽어 보세요.","confirm":{"prompt":"하나님은 무엇을 하게 하시려고 사람을 만들자고 하셨나요?","options":[{"label":"바다와 하늘과 땅의 생물을 다스리게 하시려고","ok":true},{"label":"하나님 대신 해와 별을 움직이게 하시려고","basis":"본문에 없음"},{"label":"짐승들을 모두 길들여 가축으로 삼게 하시려고","basis":"본문에 없음"}]},"inStory":"이야기에는 지으신 바다·하늘·땅의 생물이 나오지만, 사람에게 그것들을 다스리게 하신 일은 1:26·28에서만 안다(11~13세 대목 글에서 뺐다)"},"t3":{"type":"find","refs":["창 1:22","창 1:28"],"prompt":"창세기 1장 22절과 28절을 함께 찾아 읽어 보자.","confirm":{"prompt":"하나님이 물의 생물과 새에게, 그리고 사람에게 복을 주시며 하신 말씀은 각각 어떠했는가?","options":[{"label":"물의 생물과 새에게도 사람에게도 번성하라고 복을 주셨고, 사람에게는 땅을 정복하고 모든 생물을 다스리라는 말씀을 더하셨다","ok":true},{"label":"물의 생물과 새에게만 번성하라고 하셨고, 땅을 정복하고 다스리라는 말씀은 사람과 그들 모두에게 하셨다","basis":"본문에 없음"},{"label":"물의 생물과 새에게도 사람에게도 번성하라고 복을 주셨고, 땅을 정복하고 다스리라는 말씀도 모두에게 똑같이 하셨다","basis":"본문에 없음"}]}}}}]}},"has3d":false,"epic":false},"OT-02":{"id":"OT-02","era":1,"title":"에덴 동산과 사람의 범죄","ref":"창 2:15-17","place":"에덴 동산","review":{"required":true,"topics":["재앙과 심판","구약 사건의 신약적 의미(창 3:15)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"창 2:15-17","open":"창 2:16-17","focus":"garden","text":{"t1":"하나님은 사람을 에덴 동산에 두시고, 선악을 알게 하는 나무 열매만은 먹지 말라고 하셨어요. 먹는 날에는 반드시 죽는다고 하셨어요.","t2":"여호와 하나님은 사람을 에덴 동산에 두어 그곳을 다스리며 지키게 하셨어요. 동산의 여러 나무 열매는 마음대로 먹어도 된다고 하셨어요. 그러나 선악을 알게 하는 나무의 열매는 먹지 말라고 하시고, 먹는 날에는 반드시 죽는다고 하셨어요.","t3":"여호와 하나님은 그 사람을 데려다 에덴 동산에 두셨다. 그에게 맡기신 일은 15절에서 직접 읽어 보자. 그리고 동산 여러 나무의 열매는 마음대로 먹되 선악을 알게 하는 나무의 열매는 먹지 말라고 명하시며, 먹는 날에는 반드시 죽을 것이라고 하셨다."},"say":{"who":"onwoo","text":"하나님이 무엇을 명하셨는지 정확히 알아야 해. 창세기 2장 16절과 17절을 직접 읽어 보자."}},{"ref":"창 3:1-5","focus":"serpent","text":{"t1":"뱀이 여자에게, 하나님이 정말 동산 모든 나무의 열매를 먹지 말라고 하셨느냐고 물었어요. 여자가 대답하자, 뱀은 먹어도 결코 죽지 않는다고 말했어요.","t2":"뱀은 하나님이 지으신 들짐승 가운데 가장 간교했어요. 뱀은 여자에게, 하나님이 정말 동산 모든 나무의 열매를 먹지 말라고 하셨느냐고 물었어요. 여자는 동산 나무의 열매는 먹을 수 있지만 동산 가운데 있는 나무의 열매는 먹지도 만지지도 말라고 하셨다고 대답했어요. 뱀은 결코 죽지 않는다고 말했어요.","t3":"여호와 하나님이 지으신 들짐승 가운데 뱀이 가장 간교했다. 뱀은 여자에게, 하나님이 참으로 동산 모든 나무의 열매를 먹지 말라고 하셨는지 물었다. 여자는 동산 나무의 열매는 먹을 수 있으나, 동산 중앙에 있는 나무의 열매는 죽지 않도록 먹지도 만지지도 말라고 하셨다고 대답했다. 뱀은 결코 죽지 않을 것이며, 그것을 먹는 날에는 눈이 밝아져 하나님처럼 되어 선악을 알게 될 줄을 하나님이 아신다고 말했다."},"say":{"who":"choeon","text":"뱀이 여자에게 묻고 있어."}},{"ref":"창 3:6-7","focus":"tree","text":{"t1":"여자는 그 나무의 열매를 따서 먹고, 함께 있던 남편에게도 주어 그도 먹었어요. 그러자 두 사람은 자기들이 벗은 것을 알게 되었어요.","t2":"여자는 그 나무를 바라보았는데, 그 나무가 여자의 눈에 어떻게 보였는지는 6절에서 찾아봐요. 여자는 열매를 따서 먹고, 함께 있던 남편에게도 주어 그도 먹었어요. 그러자 두 사람의 눈이 밝아져 자기들이 벗은 줄을 알았고, 무화과나무 잎을 엮어 치마를 만들었어요.","t3":"여자가 그 나무를 보니 먹음직하고 보암직하며 지혜롭게 할 만큼 탐스러웠다. 여자는 그 열매를 따 먹고 자기와 함께 있던 남편에게도 주었고 그도 먹었다. 그러자 그들의 눈이 밝아져 자기들이 벗었음을 알게 되었고, 무화과나무 잎을 엮어 치마로 삼았다."},"say":{"who":"hyu","text":"여자가 먼저 먹고, 남편에게도 주었고, 그도 먹었어. 순서대로 적어 둘게."}},{"ref":"창 3:8-13","open":"창 3:9","focus":"trees","text":{"t1":"아담과 그의 아내는 하나님의 소리를 듣고 숨었는데, 어디에 숨었는지는 성경에서 찾아봐요. 하나님은 아담을 부르시며 어디 있느냐고 물으셨어요.","t2":"날이 서늘할 때 아담과 그의 아내는 동산을 거니시는 여호와 하나님의 소리를 듣고 나무 사이에 숨었어요. 하나님이 아담을 부르시자 하나님과 아담과 여자 사이에 여러 말이 오갔어요. 누가 무슨 말을 어떤 차례로 했는지는 9절부터 13절까지 읽어 봐요.","t3":"날이 서늘할 때, 그들은 동산을 거니시는 여호와 하나님의 소리를 듣고 그분의 낯을 피해 동산 나무 사이에 숨었다. 여호와 하나님은 아담을 부르시며 어디 있느냐고 물으셨다. 아담의 대답과 하나님이 이어서 물으신 말은 10절과 11절에서 직접 읽어 보자. 그 뒤 아담은 하나님이 함께 있게 하신 여자가 그 열매를 주어서 먹었다고 했고, 여자는 뱀이 꾀어서 먹었다고 했다."},"say":{"who":"choeon","text":"쉿, 두 사람이 숨었어."}},{"ref":"창 3:14-19","open":"창 3:14-19","focus":"ground","text":{"t1":"하나님은 뱀과 여자와 아담에게 차례로 말씀하셨어요. 뱀은 저주를 받아 배로 기어 다니고, 아담은 평생 수고해야 먹을 것을 얻다가 흙으로 돌아간다고 하셨어요.","t2":"여호와 하나님은 뱀에게 저주를 받아 배로 다니고 평생 흙을 먹을 것이라고 하셨어요. 또 뱀의 후손과 여자의 후손을 원수가 되게 하겠다고 하시고, 여자의 후손은 뱀의 머리를, 뱀은 그의 발꿈치를 상하게 할 것이라고 하셨어요. 여자에게는 아이를 낳는 고통이 크게 더해진다고 하셨어요. 아담에게는 땅이 그로 인해 저주를 받아, 평생 수고해야 먹을 것을 얻고 마침내 흙으로 돌아간다고 하셨어요.","t3":"여호와 하나님은 뱀에게, 이 일을 하였으니 모든 가축과 들짐승보다 더 저주를 받아 배로 다니고 사는 날 동안 흙을 먹을 것이라고 하셨다. 또 뱀과 여자를, 뱀의 후손과 여자의 후손을 원수가 되게 하겠다고 하시고, 여자의 후손은 뱀의 머리를 상하게 하고 뱀은 그의 발꿈치를 상하게 할 것이라고 하셨다. 여자에게는 잉태하는 고통을 크게 더하여 수고하며 자식을 낳을 것이고, 남편을 사모하며 남편은 그를 다스릴 것이라고 하셨다. 아담에게는 땅이 저주를 받아 가시덤불과 엉겅퀴를 낼 것이며, 그는 얼굴에 땀을 흘려야 먹을 것을 먹다가, 흙에서 취해졌으므로 마침내 흙으로 돌아갈 것이라고 하셨다. 땅이 무엇 때문에 저주를 받는다고 하셨는지는 17절에 있다."},"say":{"who":"onwoo","text":"여기는 하나님의 말씀이 길게 이어져. 창세기 3장 14절부터 19절까지 성경책에서 직접 읽어 보자."}},{"ref":"창 3:20-21","focus":"clothes","text":{"t1":"아담은 아내의 이름을 하와라고 지었어요. 하나님은 아담과 그의 아내에게 가죽옷을 지어 입히셨어요.","t2":"아담은 아내의 이름을 하와라고 지었어요. 하와가 모든 산 사람의 어머니가 되기 때문이에요. 여호와 하나님은 아담과 그의 아내를 위해 가죽옷을 지어 입히셨어요.","t3":"아담은 아내를 하와라고 이름 지었는데, 그가 모든 산 자의 어머니가 되었기 때문이다. 여호와 하나님은 아담과 그의 아내에게 가죽옷을 지어 입히셨다."},"say":{"who":"choeon","text":"하나님이 두 사람에게 가죽옷을 지어 입히셨대."}},{"ref":"창 3:22-24","open":"창 3:22","focus":"east","text":{"t1":"하나님은 사람을 에덴 동산에서 내보내셨어요. 그리고 동산 동쪽에 그룹들과 불 칼을 두어 생명나무로 가는 길을 지키게 하셨어요.","t2":"여호와 하나님은 사람을 에덴 동산에서 내보내 땅을 갈게 하셨는데, 그 까닭은 22절에서 찾아봐요. 그리고 에덴 동산 동쪽에 그룹들과 두루 도는 불 칼을 두어 생명나무로 가는 길을 지키게 하셨어요.","t3":"여호와 하나님은 사람이 선악을 알게 되어 우리 가운데 하나처럼 되었다고 하시고, 그가 손을 들어 생명나무 열매도 따 먹고 영원히 살까 한다고 하셨다. 그래서 그를 에덴 동산에서 내보내셨다. 내보내신 뒤 그에게 맡기신 일은 23절에 있다. 하나님은 그 사람을 쫓아내시고 에덴 동산 동쪽에 그룹들과 두루 도는 불 칼을 두어 생명나무로 가는 길을 지키게 하셨다."},"say":{"who":"hyu","text":"에덴 동산 동쪽. 생명나무로 가는 길을 지키게 하신 곳이라고 적어 둘게."}}],"gates":{"t1":[{"type":"find","ref":"창 3:8","prompt":"성경책에서 창세기 3장 8절을 찾아 읽어 보세요.","confirm":{"prompt":"아담과 그의 아내는 어디에 숨었나요?","options":[{"label":"동산 나무 사이","ok":true},{"label":"동굴 속","basis":"본문에 없음"},{"label":"큰 바위 뒤","basis":"본문에 없음"}]}},{"type":"multi","ref":"창 2:15","prompt":"성경책에서 창세기 2장 15절을 찾아 읽어 보세요.","confirm":{"prompt":"하나님이 사람을 에덴 동산에 두시고 맡기신 일을 모두 고르세요.","options":[{"label":"동산을 다스리기","ok":true},{"label":"양 치기","basis":"창 4:2"},{"label":"동산을 지키기","ok":true},{"label":"방주 짓기","basis":"창 6:14"},{"label":"성과 탑 쌓기","basis":"창 11:4"}]}}],"t2":[{"type":"find","ref":"창 3:6-7","prompt":"성경책에서 창세기 3장 6절과 7절을 읽어 보세요.","confirm":{"prompt":"여자가 그 나무의 열매를 따 먹은 것은 그 나무가 어떻게 보였기 때문인가요?","options":[{"label":"먹음직하고 보기에도 좋고, 지혜롭게 해 줄 만큼 탐스러워 보였기 때문에","ok":true},{"label":"열매가 금빛으로 빛나고 그 향기가 동산 가득히 퍼졌기 때문에","basis":"본문에 없음"},{"label":"그 나무가 동산 가운데에서 다른 나무들보다 높고 커 보였기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"창 3:9-13","prompt":"성경책에서 창세기 3장 9절부터 13절까지 읽고, 말을 주고받은 차례대로 눌러 보세요.","items":["하나님이 아담을 불러 어디 있느냐고 물으셨다","아담이 두려워서 숨었다고 대답했다","하나님이 먹지 말라고 한 열매를 먹었느냐고 물으셨다","아담이 여자가 주어서 먹었다고 했다","여자가 뱀이 꾀어서 먹었다고 했다"]}],"t3":[{"type":"find","refs":["창 2:15","창 3:23"],"prompt":"창세기 2장 15절과 3장 23절을 함께 찾아 읽어 보자.","confirm":{"prompt":"하나님이 사람을 두신 곳과 맡기신 일은 동산에서 내보내기 전과 뒤에 어떻게 달라졌는가?","options":[{"label":"처음에는 에덴 동산에 두어 동산을 다스리고 지키게 하셨고, 뒤에는 동산에서 내보내 그가 나온 땅을 갈게 하셨다","ok":true},{"label":"처음에는 에덴 동산에 두어 동산의 열매를 거두게 하셨고, 뒤에는 동산에서 내보내 그가 나온 땅을 갈게 하셨다","basis":"본문에 없음"},{"label":"처음에는 에덴 동산에 두어 동산을 다스리고 지키게 하셨고, 뒤에는 동산에서 내보내 양 떼를 치게 하셨다","basis":"본문에 없음"}]}},{"type":"match","refs":["창 3:7","창 3:10","창 3:21"],"prompt":"창세기 3장 7절, 10절, 21절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"창 3:7","text":"눈이 밝아져 벗은 줄 알고 무화과나무 잎으로 치마를 엮었다"},{"ref":"창 3:10","text":"아담이 벗은 몸이라 두려워서 숨었다고 대답했다"},{"ref":"창 3:21","text":"여호와 하나님이 두 사람에게 가죽옷을 입혀 주셨다"}],"after":"세 곳을 이으면, 벗은 줄을 안 두 사람은 무화과나무 잎으로 치마를 엮었고, 아담은 벗은 몸이라 두려워 숨었다고 했으며, 여호와 하나님은 그들에게 가죽옷을 지어 입히셨다."}]},"cards":[{"ref":"창 3:9","title":"아담을 부르심"},{"ref":"창 3:21","title":"가죽옷을 지어 입히심"}],"close":{"t1":{"kind":"prayer","text":"하나님, 하나님이 하신 말씀을 잘 듣고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 창세기 3장 1절부터 13절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"창 3:1-24에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 타임머신이 비상 착륙하면서 균형을 잡아 주는 무게추가 떨어져 나갔어요. 이곳에서 구할 수 있는 것으로 대신해 봐요.","t2":"최현 박사예요. 비상 착륙 때 타임머신의 균형을 잡아 주는 무게추가 떨어져 나가서 제대로 출발할 수 없어요. 이 시대에는 우리 부속이 없으니, 이곳에서 구할 수 있는 재료로 대신 만들어야 해요.","t3":"최현 박사다. 비상 착륙으로 타임머신의 균형을 잡는 무게추가 떨어져 나갔고, 지금은 통신만 이어져 있다. 이 시대에는 부속이 없으니 이곳에서 얻을 수 있는 재료로 무게추를 대신해야 한다."},"materials":[{"key":"soil","name":"흙 한 줌","basis":"창 3:23","use":"흙을 주머니에 꼭꼭 눌러 담으면 떨어져 나간 무게추 대신 쓸 수 있어요.","how":"에덴 동산 밖의 빈 땅에서 아이들이 직접 흙 한 줌을 떠 주머니에 담는다. 동산 동쪽, 생명나무로 가는 길 쪽으로는 가지 않는다.","line":"흙 한 줌을 담았어! 동산 밖 빈 땅에서 떴어."}],"companion":{"who":"아담","ref":"창 3:23","when":"after","talks":[{"ask":{"who":"choeon","text":"아까 왜 숨으셨어요?"},"answer":{"t1":"아담은 하나님의 소리를 동산에서 들었을 때, 자기가 벗은 몸이라 두려워서 숨었다고 대답했어요.","t2":"아담은 하나님께 이렇게 대답했어요. 동산에서 하나님의 소리를 들었는데, 자기가 벗은 몸이어서 두려워 숨었다고요.","t3":"아담은 하나님께, 동산에서 하나님의 소리를 들었으나 자기가 벗은 몸이었으므로 두려워 몸을 숨겼다고 대답했다."},"ref":"창 3:10","open":"창 3:10"},{"ask":{"who":"hyu","text":"그 나무의 열매는 어떻게 드시게 되었어요?"},"answer":{"t1":"아담은 하나님이 함께 있게 하신 여자가 그 나무의 열매를 주어서 먹었다고 대답했어요.","t2":"아담은 하나님께 이렇게 대답했어요. 하나님이 주셔서 자기와 함께 있게 하신 여자가 그 나무의 열매를 건네주어서 먹었다고요.","t3":"아담은 하나님께, 하나님이 자기와 함께 있도록 주신 여자가 그 나무의 열매를 자기에게 주었고 그래서 먹었다고 대답했다."},"ref":"창 3:12","open":"창 3:12"}]},"today":[{"q":"뱀이 어떻게 사람처럼 말을 할 수 있었어요?","a":{"t1":"성경은 뱀이 여자에게 말했다고 적고 있어요. 하지만 창세기는 뱀이 어떻게 말할 수 있었는지는 말하지 않아요.","t2":"창세기는 뱀이 여호와 하나님이 지으신 들짐승 가운데 가장 간교했다고 말해요. 그리고 뱀이 여자에게 묻고, 먹어도 결코 죽지 않는다고 말했다고 적어요. 하지만 뱀이 어떻게 말할 수 있었는지는 창세기가 말하지 않아요.","t3":"창세기는 뱀이 여호와 하나님이 지으신 들짐승 가운데 가장 간교했다고 소개하고, 뱀이 여자에게 묻고 결코 죽지 않을 것이라고 말했다고 기록한다(창 3:1, 3:4-5). 뱀이 어떻게 말할 수 있었는지는 창세기가 말하지 않는다. 창세기는 여기까지 말한다."},"refs":["창 3:1","창 3:4-5"]},{"q":"에덴 동산은 지금 어디에 있어요?","a":{"t1":"성경은 하나님이 에덴에 동산을 만드시고 사람을 거기에 두셨다고 말해요. 지금 그곳이 어디인지는 성경이 말하지 않아요.","t2":"성경은 여호와 하나님이 에덴에 동산을 만드셨다고 말해요. 에덴에서 강 하나가 흘러나와 비손, 기혼, 힛데겔, 유브라데 네 강으로 갈라졌다고도 적어요. 사람을 내보내신 뒤에는 동산 동쪽에 그룹들과 불 칼을 두어 생명나무로 가는 길을 지키게 하셨어요. 지금 그곳이 어디인지는 성경이 말하지 않아요.","t3":"성경은 여호와 하나님이 에덴에 동산을 만드셨고, 에덴에서 흘러나온 강이 갈라져 비손, 기혼, 힛데겔, 유브라데 네 강이 되었다고 기록한다(창 2:8, 2:10-14). 사람을 쫓아내신 뒤에는 에덴 동산 동쪽에 그룹들과 두루 도는 불 칼을 두어 생명나무로 가는 길을 지키게 하셨다(창 3:24). 지금 그곳이 어디인지는 성경이 말하지 않는다."},"refs":["창 2:8","창 2:10-14","창 3:24"]}],"help":{"who":"아담과 그의 아내(죄를 돕는 일은 없다. 곁에서 보기와 뜻 묻기, 그리고 우리 탐험 일지 정리만 한다)","steps":[{"kind":"do","after":4,"title":"탐험 일지 정리 · 누구에게 하신 말씀인가","basis":"창 3:14-19","text":{"t1":"우리는 탐험 일지를 정리해요. 하나님이 뱀과 여자와 아담에게 차례로 하신 말씀이 몇 절에 있는지 나누어 적어요.","t2":"우리는 탐험 일지를 정리해요. 여호와 하나님이 뱀과 여자와 아담에게 차례로 말씀하셨으니, 어느 절이 누구에게 하신 말씀인지 나누어 적어요. 말씀의 뜻은 우리가 지어 붙이지 않아요.","t3":"탐험대는 탐험 일지를 정리한다. 여호와 하나님은 뱀에게(3:14-15), 여자에게(3:16), 아담에게(3:17-19) 차례로 말씀하셨다. 어느 절이 누구에게 하신 말씀인지만 나누어 적고, 뜻을 지어 덧붙이지 않는다."},"tasks":["뱀 칸에 3장 14~15절 적기","여자 칸에 3장 16절 적기","아담 칸에 3장 17~19절 적기"],"done":{"who":"onwoo","text":"세 칸을 다 적었어. 말씀은 성경책 3장 14절부터 직접 읽자."}},{"kind":"watch","after":5,"title":"곁에서 보기 · 하와라는 이름","basis":"창 3:20","text":{"t1":"아담이 아내의 이름을 하와라고 지었어요. 이름을 지은 것은 아담이에요. 우리는 곁에서 지켜봐요.","t2":"아담이 아내의 이름을 하와라고 지었어요. 본문은 아담이 이 이름을 지었다고 적어요. 우리는 손대지 않고 곁에서 지켜봐요.","t3":"아담이 그 아내의 이름을 하와라고 지었다(3:20). 본문은 이름을 지은 이가 아담이라고 적는다. 탐험대는 곁에서 지켜본다. 그 이름의 까닭은 같은 절에 적혀 있다."},"say":{"who":"hyu","text":"이름을 지은 까닭은 3장 20절에 같이 적혀 있어."}},{"kind":"ask","after":"gates","title":"그 열매를 먹은 일은 무슨 뜻이에요?","basis":"창 3:11","by":"최현 박사","ask":{"who":"hyu","text":"두 사람이 그 나무의 열매를 먹은 건 무슨 뜻이에요?"},"answer":{"t1":"성경은 그 일이 하나님이 먹지 말라고 명하신 나무의 열매를 먹은 일이었다고 말해요. 그 뒤에 여호와 하나님은 사람을 에덴 동산에서 내보내셨어요.","t2":"창세기는 여호와 하나님이 선악을 알게 하는 나무의 열매는 먹지 말라고 명하셨다고 말해요(2:17). 하나님은 아담에게 먹지 말라고 명한 그 나무의 열매를 먹었느냐고 물으셨고(3:11), 아내의 말을 듣고 그 열매를 먹었으므로 땅이 그 때문에 저주를 받는다고 하셨어요(3:17). 그리고 사람을 에덴 동산에서 내보내셨어요(3:23).","t3":"창세기는 여호와 하나님이 사람에게, 동산의 나무 열매는 마음대로 먹되 선악을 알게 하는 나무의 열매는 먹지 말라고 명하셨다고 기록한다(2:16-17). 하나님은 아담에게 먹지 말라고 명한 그 나무의 열매를 먹었느냐고 물으셨고(3:11), 아내의 말을 듣고 먹지 말라 한 열매를 먹었으므로 땅이 그로 말미암아 저주를 받는다고 하셨다(3:17). 그리고 그를 에덴 동산에서 내보내셨다(3:23). 성경은 여기까지 말한다."},"read":{"t1":{"type":"find","ref":"창 3:11","prompt":"성경책에서 창세기 3장 11절을 찾아 읽어 보세요.","confirm":{"prompt":"아담이 숨은 까닭을 말하자, 하나님이 이어서 처음 물으신 것은 무엇인가요?","options":[{"label":"누가 그에게 벗었다고 알려 주었느냐고","ok":true},{"label":"여자에게 왜 그런 일을 했느냐고","basis":"창 3:13"},{"label":"누가 그에게 그 열매를 주었느냐고","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"창 3:22-23","prompt":"성경책에서 창세기 3장 22절과 23절을 읽어 보세요.","confirm":{"prompt":"여호와 하나님이 사람을 에덴 동산에서 내보내신 까닭은 무엇인가요?","options":[{"label":"사람이 생명나무의 열매도 따 먹고 영원히 살까 하셔서","ok":true},{"label":"사람이 동산을 지키는 일을 게을리했기 때문에","basis":"본문에 없음"},{"label":"사람이 생명나무를 베어 버릴까 하셔서","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["창 2:17","창 3:11","창 3:17"],"prompt":"창세기 2장 17절, 3장 11절, 17절을 함께 찾아 읽어 보자.","confirm":{"prompt":"사람이 먹은 열매는 어떤 열매였고, 하나님은 그 일을 두고 무엇을 물으시고 무엇이라 하셨는가?","options":[{"label":"하나님이 먹지 말라고 명하신 나무의 열매였고, 하나님은 그것을 먹었느냐고 물으셨으며, 그 일 때문에 땅이 저주를 받는다고 하셨다","ok":true},{"label":"하나님이 먹어도 된다고 하신 열매였는데, 뱀이 먹지 못하게 막았다","basis":"본문에 없음"},{"label":"하나님이 먹지 말라고 명하신 나무의 열매였고, 하나님은 왜 숨었느냐고 물으셨으며, 그 일 때문에 땅이 저주를 받는다고 하셨다","basis":"본문에 없음"}]}}}}]}},"has3d":false,"epic":false},"OT-03":{"id":"OT-03","era":1,"title":"노아의 방주와 무지개 언약","ref":"창 6:9-9:17","place":"방주, 아라랏 산","review":{"required":true,"topics":["재앙과 심판","구약 사건의 신약적 의미(히 11:7)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"창 6:9-12","focus":"noah","text":{"t1":"노아는 의인이었고 하나님과 동행했어요. 그때 온 땅은 하나님 앞에서 부패했고 포악함이 가득했어요.","t2":"노아는 의인이고 그 시대에 완전한 사람이었으며 하나님과 동행했어요. 그는 셈과 함과 야벳, 세 아들을 낳았어요. 그때 온 땅은 하나님 앞에서 부패해 있었어요.","t3":"노아는 의인이며 그 시대에 완전한 사람이었고 하나님과 동행했다. 그는 셈과 함과 야벳 세 아들을 낳았다. 그때 온 땅이 하나님 앞에서 부패하여 포악함이 땅에 가득했고, 하나님이 보시니 땅 위 모든 혈육 있는 자의 행위가 부패해 있었다."},"say":{"who":"hyu","text":"노아에게는 아들이 셋 있대. 이름은 6장 10절에서 찾아 적어 둘게."}},{"ref":"창 6:13-22","open":"창 6:13-21","focus":"ark","text":{"t1":"하나님은 노아에게 홍수를 일으키겠다고 하시며, 방주를 짓고 가족과 짐승들을 데리고 들어가라고 하셨어요. 노아는 명하신 대로 다 했어요.","t2":"하나님은 노아에게 모든 혈육 있는 자를 땅과 함께 멸하겠다고 하셨는데, 그 까닭은 13절에 있어요. 그리고 방주를 짓고 안팎에 역청을 칠하라고 하셨어요. 노아와는 언약을 세우겠다고 하시며, 가족과 함께 방주로 들어가고 모든 생물을 암수 한 쌍씩 데리고 들어가라고 하셨어요. 노아는 하나님이 명하신 대로 다 했어요.","t3":"하나님은 노아에게, 모든 혈육 있는 자의 포악함이 땅에 가득하여 그 끝 날이 이르렀으니 그들을 땅과 함께 멸하겠다고 하셨다. 그리고 방주를 짓되 안에 칸들을 만들고 안팎에 역청을 칠하며, 길이 삼백 규빗, 너비 오십 규빗, 높이 삼십 규빗에 창과 옆문을 내고 삼 층으로 만들라고 하셨다. 하나님은 홍수를 땅에 일으키겠다고 하셨으나, 노아에게는 따로 하신 말씀이 있었다. 그 말씀과 노아가 한 일은 18절부터 22절까지 직접 읽어 보자."},"say":{"who":"onwoo","text":"하나님이 노아에게 하신 말씀은 창세기 6장 13절부터야. 성경책에서 직접 읽어 보자."}},{"ref":"창 7:1-16","open":"창 7:1-4","focus":"ark_door","text":{"t1":"노아의 가족과 짐승들이 방주에 들어가자, 여호와께서 노아를 안에 두고 닫으셨어요. 비가 사십 일 밤낮으로 땅에 쏟아졌어요.","t2":"여호와께서는 노아에게 온 집안과 함께 방주로 들어가라고 하셨어요. 노아는 아내와 아들들과 며느리들과 함께 들어갔고, 짐승과 새와 땅에 기는 것들도 암수 둘씩 노아에게 나아와 들어갔어요. 여호와께서 노아를 안에 두고 닫으셨어요. 큰 깊음의 샘들이 터지고 하늘의 창들이 열려, 사십 일 밤낮으로 비가 쏟아졌어요.","t3":"여호와께서는 노아에게 온 집과 함께 방주로 들어가라고 하시고, 정결한 짐승과 공중의 새는 암수 일곱씩, 정결하지 않은 짐승은 암수 둘씩 데려오게 하셨으며, 이레 뒤에 사십 주야 동안 비를 내리겠다고 하셨다. 이레가 지나자 큰 깊음의 샘들이 터지고 하늘의 창들이 열려 사십 주야 비가 쏟아졌다. 바로 그날 노아와 아내, 세 아들 셈과 함과 야벳, 세 며느리가 방주로 들어갔고, 숨 쉬는 모든 생물이 둘씩 노아에게 나아와 들어갔으며, 여호와께서 그를 닫아 넣으셨다. 노아를 들어가게 하신 까닭, 그 말씀을 들은 노아가 한 일, 그날이 언제였는지는 1절, 5절, 11절에 있다."},"say":{"who":"choeon","text":"짐승들이 방주로 들어가고 있어!"}},{"ref":"창 7:17-24","focus":"water","text":{"t1":"물이 점점 불어나 방주가 물 위에 떠다녔고, 높은 산들이 어떻게 되었는지는 성경에서 찾아봐요. 노아와 방주에 함께 있던 이들만 남았어요.","t2":"홍수가 사십 일 동안 땅에 있었어요. 물이 많아져 방주가 땅에서 떠올라 물 위를 떠다녔고, 하늘 아래 높은 산들이 다 덮였어요. 땅 위에서 움직이던 생물은 다 죽었고, 노아와 방주에 함께 있던 이들만 남았어요. 물은 백오십 일 동안 땅에 넘쳤어요.","t3":"홍수가 사십 일 동안 땅에 있었고, 물이 불어나 방주가 땅에서 떠올라 물 위를 떠다녔다. 물은 땅에 더욱 넘쳤다. 땅 위에서 움직이던 생물, 곧 새와 가축과 들짐승과 땅에 기는 것과 모든 사람이 죽었다. 물은 백오십 일 동안 땅에 넘쳤다. 그때 산들이 어떻게 되었는지와 누가 남았는지는 19절과 23절에 있다."},"say":{"who":"hyu","text":"방주가 물 위에 떠 있어. 일지에 적어 둘게."}},{"ref":"창 8:1-14","focus":"dove","text":{"t1":"하나님이 노아를 기억하셔서 물이 줄었고, 방주는 아라랏 산에 머물렀어요. 노아가 내보낸 비둘기가 감람나무 새 잎을 물고 돌아왔어요.","t2":"물이 줄어들고 방주는 아라랏 산에 머물렀어요. 노아는 방주에서 새들을 내보냈어요. 물이 줄어든 까닭은 1절에, 새들을 어떤 차례로 내보냈고 새들이 어떻게 했는지는 6절부터 12절까지에 있어요.","t3":"하나님이 노아와 방주에 함께 있는 모든 들짐승과 가축을 기억하셔서 바람이 땅 위에 불게 하시니 물이 줄어들었다. 깊음의 샘들과 하늘의 창들이 닫히고 비가 그쳤으며, 일곱째 달 십칠일에는 방주가 아라랏 산 위에 머물게 되었다. 사십 일이 지나 노아는 방주의 창을 열고 까마귀를 내보냈고, 이어 비둘기를 내보냈으나 비둘기는 발 붙일 곳을 찾지 못해 돌아왔다. 이레 뒤 다시 내보낸 비둘기는 저녁때 감람나무 새 잎사귀를 물고 돌아왔고, 또 이레 뒤에 내보낸 비둘기는 돌아오지 않았다. 그 뒤 지면에서 물이 걷히고 땅이 말랐는데, 그때가 언제였는지는 13절과 14절에 있다."},"say":{"who":"choeon","text":"비둘기가 잎사귀를 물고 돌아왔어!"}},{"ref":"창 8:15-22","open":"창 8:21-22","focus":"altar","text":{"t1":"하나님이 나오라고 하시자 노아는 가족과 짐승들과 함께 방주에서 나왔어요. 그리고 여호와께 단을 쌓고 번제를 드렸어요.","t2":"하나님은 노아에게 가족과 모든 생물을 데리고 방주에서 나오라고 하셨어요. 노아는 가족과 함께 나왔고 짐승과 새들도 종류대로 나왔어요. 노아는 여호와께 단을 쌓고 정결한 짐승과 새 가운데서 골라 번제를 드렸어요. 여호와께서는 다시는 전에 한 것처럼 모든 생물을 멸하지 않겠다고 하셨어요.","t3":"하나님은 노아에게 아내와 아들들과 며느리들과 함께 방주에서 나오고, 모든 생물도 이끌어 내어 땅에서 생육하고 번성하게 하라고 하셨다. 노아와 가족이 나왔고 짐승과 기는 것과 새도 종류대로 나왔다. 노아는 여호와를 위해 단을 쌓고 정결한 짐승과 정결한 새 가운데서 골라 번제로 드렸다. 여호와께서는 그 향기를 받으셨다. 그때 마음속으로 하신 말씀은 21절에서 직접 읽어 보자. 또 땅이 있는 동안 심고 거두는 일과 추위와 더위, 여름과 겨울, 낮과 밤이 그치지 않을 것이라고 하셨다."},"say":{"who":"hyu","text":"방주에서 나온 뒤에 노아가 단을 쌓았어. 일지에 적어 둘게."}},{"ref":"창 9:1-17","open":"창 9:11-13","focus":"rainbow","text":{"t1":"하나님은 다시는 홍수로 모든 생물을 멸하지 않겠다는 언약을 세우셨어요. 그 언약의 증거로 무지개를 두셨는데, 어디에 두셨는지는 성경에서 찾아봐요.","t2":"하나님은 노아와 그의 아들들에게 복을 주시며 땅에 가득하라고 하셨어요. 그리고 노아와 그의 아들들과 그 후손, 방주에서 나온 모든 생물과 언약을 세우시고, 다시는 홍수가 모든 생물을 멸하지 않을 것이라고 하셨어요. 하나님은 무지개를 구름 속에 두시고 이것이 언약의 증거라고 하셨어요. 무지개가 구름 속에 나타나면 그 언약을 기억하겠다고 하셨어요.","t3":"하나님은 노아와 그의 아들들에게 복을 주시며 생육하고 번성하여 땅에 가득하라고 하셨다. 산 동물을 먹을거리로 주시되 고기를 그 생명인 피째 먹지는 말라고 하셨다. 이어 노아와 그의 아들들과 그 후손, 그리고 방주에서 나온 모든 생물과 언약을 세우셨는데, 그 언약의 내용은 11절에서 직접 읽어 보자. 하나님은 자기의 무지개를 구름 속에 두셨고, 그것이 하나님과 땅의 모든 생물 사이에 세우는 언약의 증거라고 하셨다. 구름이 땅을 덮을 때 무지개가 나타나면 그 영원한 언약을 기억하겠다고 하셨다."},"say":{"who":"onwoo","text":"언약의 증거가 무엇인지는 하나님의 말씀으로 적혀 있어. 창세기 9장 13절을 직접 읽어 보자."}}],"gates":{"t1":[{"type":"find","ref":"창 6:14","prompt":"성경책에서 창세기 6장 14절을 찾아 읽어 보세요.","confirm":{"prompt":"하나님은 노아에게 방주의 안과 밖에 무엇을 칠하라고 하셨나요?","options":[{"label":"역청","ok":true},{"label":"석회","basis":"신 27:2"},{"label":"기름","basis":"창 28:18"}]}},{"type":"multi","ref":"창 7:13","prompt":"성경책에서 창세기 7장 13절을 찾아 읽어 보세요.","confirm":{"prompt":"홍수가 시작된 날 노아와 함께 방주로 들어간 사람을 모두 고르세요.","options":[{"label":"셈과 함과 야벳","ok":true},{"label":"노아의 딸들","basis":"본문에 없음"},{"label":"노아의 아내","ok":true},{"label":"롯","basis":"창 12:4"},{"label":"세 며느리","ok":true}]}}],"t2":[{"type":"find","ref":"창 6:11-13","prompt":"성경책에서 창세기 6장 11절부터 13절까지 읽어 보세요.","confirm":{"prompt":"하나님이 노아에게 혈육 있는 자들을 땅과 함께 멸하겠다고 하신 까닭은 무엇인가요?","options":[{"label":"그들의 포악함이 땅에 가득했기 때문에","ok":true},{"label":"사람들이 방주를 비웃었기 때문에","basis":"본문에 없음"},{"label":"땅에 비가 너무 오래 오지 않았기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"창 8:6-12","prompt":"성경책에서 창세기 8장 6절부터 12절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["노아가 방주에 낸 창을 열었다","까마귀를 내보냈다","비둘기가 발 디딜 곳을 찾지 못해 방주로 돌아왔다","비둘기가 저녁때 감람나무 새 잎을 물고 왔다","비둘기가 다시는 돌아오지 않았다"]}],"t3":[{"type":"find","refs":["창 7:11","창 8:13","창 8:14"],"prompt":"창세기 7장 11절, 8장 13절, 14절을 함께 찾아 읽어 보자.","confirm":{"prompt":"홍수가 시작된 날과 땅이 다 마른 날은 언제인가?","options":[{"label":"홍수는 노아가 육백 세 되던 해 둘째 달 십칠일에 시작되었고, 땅은 육백일 년 둘째 달 이십칠일에 말랐다","ok":true},{"label":"홍수는 노아가 육백 세 되던 해 둘째 달 십칠일에 시작되었고, 땅은 그해 열두째 달 이십칠일에 말랐다","basis":"본문에 없음"},{"label":"홍수는 노아가 오백 세 되던 해 둘째 달 십칠일에 시작되었고, 땅은 그해 열두째 달 이십칠일에 말랐다","basis":"본문에 없음"}]}},{"type":"match","refs":["창 7:24","창 8:1","창 9:15"],"prompt":"창세기 7장 24절, 8장 1절, 9장 15절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"창 7:24","text":"물이 백오십 일 동안 땅에 넘쳤다"},{"ref":"창 8:1","text":"하나님이 노아와 방주의 짐승들을 기억하시고 바람을 불게 하셨다"},{"ref":"창 9:15","text":"하나님이 노아와 모든 생물과 세우신 언약을 기억하시겠다고 하셨다"}],"after":"세 곳을 이으면, 물이 오래 땅에 넘쳤으나 하나님이 노아를 기억하시자 물이 줄었고, 뒤에는 하나님이 세우신 언약을 기억하시겠다고 하셨다."}]},"cards":[{"ref":"창 6:22","title":"명하신 대로 다 준행함"},{"ref":"창 9:13","title":"구름 속에 둔 무지개"}],"close":{"t1":{"kind":"prayer","text":"하나님, 무지개를 볼 때 하나님이 세우신 언약을 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 창세기 9장 8절부터 17절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"창 6:9-9:17에서 새로 알게 된 사실을 한 가지 적어 보자."}},"quests":[{"part":"lens","name":"렌즈","line":"렌즈를 찾았어! 방주에서 멀찍이 떨어진 돌 틈에 끼어 있었네.","found":"탐지기가 방주 쪽을 가리켜요.","say":{"who":"hyu","text":"탐지기 바늘이 방주 쪽으로 돌아갔어. 가까이 가지는 말고 여기서 보고 적자."},"q":{"t1":{"type":"find","ref":"창 6:16","prompt":"성경책에서 창세기 6장 16절을 찾아 읽어 보세요.","confirm":{"prompt":"하나님은 방주를 몇 층으로 지으라고 하셨나요?","options":[{"label":"삼 층","ok":true},{"label":"일 층","basis":"본문에 없음"},{"label":"칠 층","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"창 6:21-22","prompt":"성경책에서 창세기 6장 21절과 22절을 읽어 보세요.","confirm":{"prompt":"하나님이 노아에게 먹을 것을 모두 가져다가 모아 두라고 하신 까닭은 무엇인가요?","options":[{"label":"노아와 짐승들이 먹을 양식이 되게 하시려고","ok":true},{"label":"이웃 사람들에게 나누어 주게 하시려고","basis":"본문에 없음"},{"label":"방주를 무겁게 해서 떠내려가지 않게 하시려고","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["창 6:22","창 7:5"],"prompt":"창세기 6장 22절과 7장 5절을 함께 찾아 읽어 보자.","confirm":{"prompt":"노아는 방주를 지으라는 명령과 방주로 들어가라는 명령을 받고 각각 어떻게 했는가?","options":[{"label":"두 번 다 하나님이 명하신 대로 모두 따라 했다","ok":true},{"label":"방주는 지었으나, 들어가라는 말씀에는 바로 따르지 않았다","basis":"본문에 없음"},{"label":"명령 가운데 자기가 옳다고 여긴 것만 골라 따랐다","basis":"본문에 없음"}]}}}},{"part":"antenna","name":"안테나","line":"안테나가 여기 있었네! 산비탈 아래쪽 돌무더기 사이야.","found":"탐지기가 물이 줄어 드러난 산봉우리 쪽을 가리켜요.","say":{"who":"choeon","text":"저기 산봉우리들이 보여! 물이 저 산들을 다 덮었었대."},"q":{"t1":{"type":"find","ref":"창 7:19","prompt":"성경책에서 창세기 7장 19절을 찾아 읽어 보세요.","confirm":{"prompt":"물이 땅에 넘쳤을 때 높은 산들은 어떻게 되었나요?","options":[{"label":"물에 다 덮였어요","ok":true},{"label":"불에 탔어요","basis":"본문에 없음"},{"label":"눈으로 하얗게 덮였어요","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"창 8:1-3","prompt":"성경책에서 창세기 8장 1절부터 3절까지 읽어 보세요.","confirm":{"prompt":"물이 줄어들기 시작한 까닭은 무엇인가요?","options":[{"label":"하나님이 노아와 방주의 짐승들을 기억하시고 땅 위에 바람이 불게 하셨기 때문에","ok":true},{"label":"노아가 방주 안에서 물을 거두어 달라고 날마다 하나님께 기도했기 때문에","basis":"본문에 없음"},{"label":"하나님이 큰 깊음의 샘들을 더 넓게 여시고 물이 땅속으로 빠지게 하셨기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["창 7:19","창 8:5"],"prompt":"창세기 7장 19절과 8장 5절을 함께 찾아 읽어 보자.","confirm":{"prompt":"홍수 때 높은 산들은 어떻게 되었고, 언제 다시 보이게 되었는가?","options":[{"label":"물이 높은 산들을 다 덮었다가, 물이 점점 줄어 열째 달 초하루에 산꼭대기들이 드러나 보였다","ok":true},{"label":"물이 높은 산들을 다 덮었다가, 첫째 달 초하루에 노아가 덮개를 걷었을 때 산꼭대기들이 처음 보였다","basis":"본문에 없음"},{"label":"물이 높은 산들을 다 덮었다가, 점점 줄어 일곱째 달 십칠일에 산꼭대기들이 드러나 보였다","basis":"본문에 없음"}]}}}},{"part":"spring","name":"용수철","line":"용수철을 찾았어! 등성이 끝 마른 땅 한쪽에 있었네.","found":"탐지기가 등성이 끝 마른 땅 쪽을 가리켜요.","say":{"who":"onwoo","text":"방주 쪽으로는 가지 말자. 방주에서 떨어진 여기가 우리 자리야."},"q":{"t1":{"type":"find","ref":"창 9:13","prompt":"성경책에서 창세기 9장 13절을 찾아 읽어 보세요.","confirm":{"prompt":"하나님은 무지개를 어디에 두셨나요?","options":[{"label":"구름 속","ok":true},{"label":"방주 지붕 위","basis":"본문에 없음"},{"label":"바다 밑","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"창 8:21-22","prompt":"성경책에서 창세기 8장 21절과 22절을 읽어 보세요.","confirm":{"prompt":"여호와께서는 땅이 있는 동안 무엇이 그치지 않을 것이라고 하셨나요?","options":[{"label":"심고 거두는 일, 추위와 더위, 여름과 겨울, 낮과 밤","ok":true},{"label":"비와 눈, 바람과 구름, 봄과 가을, 아침과 저녁","basis":"본문에 없음"},{"label":"심고 거두는 일, 해와 달과 별, 여름과 겨울, 낮과 밤","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["창 8:21","창 9:11"],"prompt":"창세기 8장 21절과 9장 11절을 함께 찾아 읽어 보자.","confirm":{"prompt":"홍수 뒤에 노아가 단을 쌓았을 때와 언약을 세우실 때, 하나님이 하신 말씀은 어떻게 이어지는가?","options":[{"label":"노아가 단을 쌓은 뒤 여호와께서 중심에 다시는 생물을 다 멸하지 않겠다고 하셨고, 노아와 그 아들들과 언약을 세우시며 다시는 홍수로 생물을 모두 멸하지 않겠다고 말씀하셨다","ok":true},{"label":"노아가 단을 쌓은 뒤 여호와께서 중심에 사람의 마음이 악하니 땅을 다시 저주하겠다고 하셨고, 언약을 세우실 때에야 다시는 홍수로 생물을 멸하지 않겠다고 하셨다","basis":"본문에 없음"},{"label":"노아가 단을 쌓은 뒤 여호와께서 중심에 사람의 마음이 악하니 땅을 다시 저주하겠다고 하셨고, 노아와 그 아들들과 언약을 세우시며 다시는 땅에 비를 내리지 않겠다고 말씀하셨다","basis":"본문에 없음"}]}}}}],"mission":{"call":{"t1":"최현 박사예요. 타임머신이 비상 착륙하면서 렌즈와 안테나와 용수철이 망가졌어요. 탐지기가 가리키는 곳에서 대신 쓸 재료를 찾아봐요.","t2":"최현 박사예요. 비상 착륙 때 렌즈와 안테나와 용수철이 망가져서 타임머신이 떠날 수 없어요. 이 시대에는 우리 부속이 없으니, 탐지기가 가리키는 곳에서 대신 쓸 재료를 하나씩 찾아야 해요.","t3":"최현 박사다. 비상 착륙으로 렌즈, 안테나, 용수철이 망가졌고 지금은 통신만 이어져 있다. 이 시대에는 부속이 없으니 탐지기가 가리키는 곳마다 재료를 구해 세 부속을 대신 만들어야 한다."},"materials":[{"key":"stone","name":"반들반들한 돌","basis":"창 8:4","use":"반들반들한 돌을 렌즈 자리에 대면 거울처럼 빛을 되비춰서 렌즈 대신 쓸 수 있어요.","how":"방주에는 가까이 가지 않고, 방주가 보이는 쪽에서 멀찍이 떨어진 돌 틈에 끼어 있는 반들반들한 돌 하나를 줍는다.","line":"반들반들한 돌을 찾았어! 방주에서 멀찍이 떨어진 돌 틈에 끼어 있었네."},{"key":"feather","name":"까마귀 깃털","basis":"창 8:7","use":"길고 곧은 깃대를 세우면 안테나 대신 쓸 수 있어요.","how":"산봉우리가 보이는 쪽, 산비탈 아래 돌무더기 사이에 떨어져 있는 까만 깃털 하나를 줍는다. 새에게 다가가거나 새를 잡지 않는다.","line":"까마귀 깃털이 여기 있었네! 산비탈 아래쪽 돌무더기 사이야."},{"key":"twig","name":"감람나무 잔가지","basis":"창 8:11","use":"푸른 잔가지는 휘었다가 다시 펴지니까, 둥글게 감아서 용수철 대신 쓸 수 있어요.","how":"방주에는 가까이 가지 않고, 물이 걷혀 마른 등성이 끝 땅 한쪽에 떨어져 있는 잔가지 하나를 줍는다. 나무에서 꺾지 않는다.","line":"감람나무 잔가지를 찾았어! 등성이 끝 마른 땅 한쪽에 있었네."}],"companion":null,"today":[{"q":"비가 아주 많이 오면, 또 온 세상이 물에 잠길 수도 있어요?","a":{"t1":"하나님은 다시는 홍수로 모든 생물을 멸하지 않겠다고 언약을 세우셨어요. 그리고 그 언약의 증거로 무지개를 구름 속에 두셨어요.","t2":"하나님은 노아와 그의 아들들과 모든 생물과 언약을 세우시고, 다시는 홍수로 모든 생물을 멸하지 않으며 땅을 잠기게 할 홍수도 다시 없을 것이라고 하셨어요. 무지개가 구름 속에 나타나면 그 언약을 기억하겠다고 하셨어요. 또 땅이 있는 동안 심고 거두는 때와 추위와 더위, 여름과 겨울, 낮과 밤이 그치지 않을 것이라고 하셨어요.","t3":"하나님은 노아와 그의 아들들과 그 후손, 방주에서 나온 모든 생물과 언약을 세우시고, 모든 생물을 다시는 홍수로 멸하지 않으며 땅을 잠기게 할 홍수가 다시 없을 것이라고 하셨다(창 9:9-11). 무지개는 그 언약의 증거이고, 하나님은 무지개를 보고 그 언약을 기억하겠다고 하셨다(창 9:13-16). 하나님이 다시 없겠다고 하신 것은 모든 생물을 멸하고 땅을 잠기게 하는 홍수다. 또 땅이 있는 동안 심고 거둠, 추위와 더위, 여름과 겨울, 낮과 밤이 그치지 않을 것이라고 하셨다(창 8:22)."},"refs":["창 8:22","창 9:9-11","창 9:13-16"]},{"q":"노아는 그 많은 짐승을 어떻게 다 모았어요?","a":{"t1":"하나님은 짐승들이 둘씩 노아에게 나아올 것이라고 하셨어요. 그리고 짐승들은 암수 둘씩 노아에게 와서 방주에 들어갔어요.","t2":"하나님은 노아에게 모든 생물을 암수 한 쌍씩 방주로 이끌어 들이라고 하시고, 그것들이 종류대로 둘씩 노아에게 나아올 것이라고 하셨어요. 성경은 짐승들이 하나님이 명하신 대로 둘씩 노아에게 와서 방주에 들어갔다고 말해요. 어떻게 왔는지는 성경이 더 말하지 않아요.","t3":"하나님은 노아에게 혈육 있는 모든 생물을 암수 한 쌍씩 방주로 이끌어 들이라고 하시고, 새와 가축과 땅에 기는 것이 종류대로 둘씩 그에게 나아올 것이라고 하셨다(창 6:19-20). 본문은 짐승들이 명하신 대로 둘씩 노아에게 와서 방주에 들어갔다고 기록한다(창 7:9, 7:15). 짐승들이 어떻게 왔는지는 성경이 더 말하지 않는다."},"refs":["창 6:19-20","창 7:9","창 7:15"]}],"help":{"who":"노아와 그의 가족(방주에서 멀리 떨어져 함께 기다리고, 방주에서 나오는 짐승들에게 길을 비켜 주며, 단은 멀리서 지켜본다)","steps":[{"kind":"stay","after":4,"title":"땅이 마르기까지","basis":"창 8:13-14","text":{"t1":"노아가 방주의 덮개를 걷고 보니 땅에 물이 걷혀 있었어요. 땅이 다 마르기까지 우리도 멀리서 함께 기다려요.","t2":"노아가 방주의 덮개를 걷고 보니 땅 위에 물이 걷혀 있었어요. 둘째 달 이십칠일에 땅이 다 말랐어요. 우리도 방주에서 멀리 떨어진 마른 땅에서 함께 기다려요.","t3":"노아는 방주의 덮개를 걷고 땅 위에서 물이 걷힌 것을 보았고, 그 뒤 땅이 말랐다. 탐험대는 방주에 다가가지 않고, 멀리 떨어진 마른 땅에서 함께 기다린다."},"wait":"멀리서 함께 기다리기","say":{"who":"choeon","text":"땅이 다 말랐어. 우리는 방주 쪽으로 가지 않고 여기서 기다릴게."}},{"kind":"do","after":5,"title":"길 비켜 주기 · 방주에서 나오는 짐승들","basis":"창 8:18-19","text":{"t1":"방주에서 짐승과 새들이 종류대로 나와요. 우리는 멀리 떨어진 마른 땅에서, 짐승들이 지나갈 길을 비켜 주며 도와요.","t2":"하나님이 나오라고 하시자 노아의 가족이 방주에서 나왔고, 짐승과 기는 것과 새들도 종류대로 나와요. 우리는 방주에 다가가지 않고, 멀리 떨어진 마른 땅에서 짐승들이 지나갈 길을 비켜 주며 도와요.","t3":"노아는 아들들과 아내와 며느리들과 함께 방주에서 나왔고(8:18), 땅 위의 짐승과 기는 것과 새도 종류대로 나왔다(8:19). 탐험대는 방주에 다가가지 않는다. 멀리 떨어진 마른 땅에서, 나오는 짐승들이 지나갈 길을 비켜 준다."},"tasks":["길에 둔 우리 짐 치우기","길 가장자리로 물러서기","짐승들이 다 지나가도록 기다리기"],"done":{"who":"choeon","text":"짐승과 새들이 종류대로 지나갔어. 우리는 길 밖에 비켜 서 있었어."}},{"kind":"watch","after":5,"title":"멀리서 보기 · 노아가 쌓은 단","basis":"창 8:20","text":{"t1":"노아가 방주에서 나와 여호와께 단을 쌓고 번제를 드렸어요. 우리는 손대지 않고 멀리서 지켜봐요.","t2":"노아가 여호와께 단을 쌓고, 정결한 짐승과 새 가운데서 골라 번제로 드렸어요. 이 일은 노아가 했어요. 우리는 손대지 않고 멀리서 지켜봐요.","t3":"노아는 여호와께 단을 쌓았고, 정결한 짐승과 정결한 새 가운데서 골라 그 단에 번제로 드렸다(8:20). 본문은 이 일을 노아가 했다고 적는다. 탐험대는 단에 다가가지 않고 멀리서 지켜본다."},"say":{"who":"hyu","text":"단을 쌓은 것은 방주에서 나온 뒤야. 8장 20절에 적혀 있어."}},{"kind":"ask","after":"gates","title":"방주에 들어간 일은 무슨 뜻이에요?","basis":"창 6:17-19","by":"최현 박사","ask":{"who":"choeon","text":"노아의 가족과 짐승들이 방주에 들어간 일은 무슨 뜻이에요?"},"answer":{"t1":"성경은 하나님이 노아와 언약을 세우겠다고 하시며, 가족과 함께 방주로 들어가라고 하셨다고 말해요. 짐승들도 노아와 함께 살아 있게 하라고 하셨어요. 성경은 여기까지 말해요.","t2":"성경은 하나님이 홍수를 땅에 일으키겠다고 하시면서도, 노아와는 언약을 세우겠다고 하셨다고 말해요(6:17-18). 노아에게 아들들과 아내와 며느리들과 함께 방주로 들어가고, 모든 생물을 암컷과 수컷 한 쌍씩 데리고 들어가 함께 살아남게 하라고 하셨어요(6:18-19). 홍수 가운데서 노아와 방주에 함께 있던 이들이 남았어요(7:23).","t3":"성경은 하나님이 홍수를 땅에 일으키겠다고 하시면서도 노아와는 자기 언약을 세우겠다고 하셨다고 기록한다(6:17-18). 하나님은 노아에게 아들들과 아내와 며느리들과 함께 방주로 들어가고, 숨 쉬는 모든 생물을 암컷과 수컷 한 쌍씩 데리고 들어가 함께 살아 있게 하라고 하셨다(6:18-19). 여호와께서는 이 세대에서 노아가 하나님 앞에 의로운 것을 보셨다고 하셨고(7:1), 홍수 가운데서 노아와, 방주에 그와 함께 있던 이들만 남았다(7:23). 성경은 여기까지 말한다."},"read":{"t1":{"type":"find","ref":"창 6:19","prompt":"성경책에서 창세기 6장 19절을 찾아 읽어 보세요.","confirm":{"prompt":"하나님은 노아에게 짐승들을 몇 마리씩 방주로 데려가라고 하셨나요?","options":[{"label":"암컷과 수컷 한 쌍씩","ok":true},{"label":"한 마리씩","basis":"본문에 없음"},{"label":"열 마리씩","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"창 6:17-19","prompt":"성경책에서 창세기 6장 17절부터 19절까지 읽어 보세요.","confirm":{"prompt":"하나님이 노아에게 짐승들을 암컷과 수컷 한 쌍씩 방주에 데려가라고 하신 까닭은 무엇인가요?","options":[{"label":"노아와 함께 생명을 보존하게 하시려고","ok":true},{"label":"노아의 양식으로 삼게 하시려고","basis":"본문에 없음"},{"label":"홍수가 끝난 뒤에 번제로 드리게 하시려고","basis":"창 8:20"}]}},"t3":{"type":"find","refs":["창 6:18","창 7:1","창 7:23"],"prompt":"창세기 6장 18절, 7장 1절, 23절을 함께 찾아 읽어 보자.","confirm":{"prompt":"노아의 집이 방주에 들어가 홍수 가운데 남은 일에 대해 성경은 무엇을 말하는가?","options":[{"label":"하나님이 노아와 언약을 세우겠다고 하시며 가족과 함께 방주로 들어가라고 하셨고, 이 세대에서 노아가 의로운 것을 보셨다고 하셨으며, 홍수 가운데서 노아와 방주에 함께 있던 이들만 남았다","ok":true},{"label":"하나님이 노아와 언약을 세우겠다고 하시며 가족과 함께 방주로 들어가라고 하셨고, 노아가 방주를 다 지은 것을 보셨다고 하셨으며, 홍수 가운데서 노아와 방주에 함께 있던 이들만 남았다","basis":"본문에 없음"},{"label":"노아의 가족은 홍수가 끝난 뒤에도 방주에서 나오지 못했다","basis":"본문에 없음"}]}}},"nt":{"ref":"히 11:7","text":"신약의 히브리서 11장 7절은 노아가 믿음으로, 아직 보지 못한 일에 대해 경고를 받고 경외함으로 방주를 준비하여 자기 집을 구원했다고 말한다."}}]}},"has3d":true,"epic":true},"OT-04":{"id":"OT-04","era":1,"title":"바벨에서 흩어짐","ref":"창 11:1-9","place":"바벨","review":{"required":false,"topics":[],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"창 11:1-2","focus":"plain","text":{"t1":"온 땅의 말이 하나였어요. 사람들은 옮겨 다니다가 어느 평지에 이르러 그곳에서 살았는데, 그 평지의 이름은 성경에서 찾아봐요.","t2":"그때는 온 땅의 언어가 하나였고 쓰는 말도 하나였어요. 사람들은 동방으로 옮겨 가다가 시날 평지를 만나 거기에서 살았어요.","t3":"그때 온 땅의 말이 어떠했는지는 1절에서 직접 읽어 보자. 사람들이 동방으로 옮겨 가다가 시날 평지를 만나 거기에 머물러 살았다."},"say":{"who":"hyu","text":"넓은 평지에 사람들이 모여 살고 있어."}},{"ref":"창 11:3","focus":"bricks","text":{"t1":"사람들은 무언가를 만들어 단단히 굽자고 했어요. 돌과 진흙 대신 무엇을 썼는지는 성경에서 찾아봐요.","t2":"사람들은 서로 벽돌을 만들어 단단히 굽자고 말했어요. 그래서 돌 대신 벽돌을 쓰고, 진흙 대신 역청을 썼어요.","t3":"그들은 서로 벽돌을 만들어 단단히 굽자고 말하고, 돌이 쓰일 자리에 벽돌을, 진흙이 쓰일 자리에 역청을 썼다."},"say":{"who":"choeon","text":"사람들이 무언가를 굽고 있어!"}},{"ref":"창 11:4","focus":"tower","text":{"t1":"사람들은 성과 탑을 쌓아 탑 꼭대기가 하늘에 닿게 하자고 했어요. 자기들의 이름을 내고, 온 땅에 흩어지지 않게 하자고 했어요.","t2":"사람들은 성과 탑을 쌓아 탑 꼭대기가 하늘에 닿게 하자고 했어요.","t3":"또 그들은 성과 탑을 쌓아 그 꼭대기가 하늘에 닿게 하자고 말했다."},"say":{"who":"hyu","text":"성과 탑을 쌓자고 했어. 그 까닭도 사람들의 말로 4절에 적혀 있어."}},{"ref":"창 11:5-7","open":"창 11:6-7","focus":"tower","text":{"t1":"여호와께서 사람들이 쌓는 성과 탑을 보시려고 내려오셨어요. 그리고 그들의 말을 뒤섞어 서로 말을 못 알아듣게 하겠다고 하셨어요.","t2":"여호와께서 내려오셨어요. 왜 내려오셨는지와 그때 하신 말씀은 5절부터 7절까지 차례대로 읽어 봐요.","t3":"여호와께서 사람들이 쌓는 성과 탑을 보시려고 내려오셨다. 여호와께서는 이 무리가 한 족속이고 언어도 하나여서 이 일을 시작했으니, 이후로는 그들이 하려는 일을 막을 수 없을 것이라고 하셨다. 이어서 그들의 언어를 어떻게 하자고 하셨는지는 7절에서 직접 읽어 보자."},"say":{"who":"onwoo","text":"하나님이 하신 말씀은 우리가 지어내면 안 돼. 창세기 11장 6절과 7절을 직접 읽어 보자."}},{"ref":"창 11:8","focus":"people","text":{"t1":"여호와께서 사람들을 거기에서 온 땅으로 흩으셨어요. 그러자 사람들이 무엇을 그만두었는지는 성경에서 찾아봐요.","t2":"여호와께서 그들을 거기에서 온 땅 위에 흩으셨어요. 그래서 사람들은 성 쌓는 일을 그쳤어요.","t3":"여호와께서 거기에서 그들을 온 땅 위에 흩으셨다. 그 뒤에 그들이 무엇을 그쳤는지는 8절에 있다."},"say":{"who":"choeon","text":"사람들이 여러 쪽으로 흩어지고 있어."}},{"ref":"창 11:9","focus":"city","text":{"t1":"그래서 그곳의 이름을 바벨이라고 했어요. 여호와께서 거기에서 온 땅의 말을 뒤섞으셨기 때문이에요.","t2":"그래서 그곳의 이름을 바벨이라고 불렀어요. 여호와께서 거기에서 온 땅의 언어를 뒤섞으시고, 사람들을 온 땅 위에 흩으셨기 때문이에요.","t3":"그러므로 그곳의 이름을 바벨이라 했다. 여호와께서는 거기에서 그들을 온 땅 위에 흩으셨다."},"say":{"who":"hyu","text":"이곳의 이름은 바벨. 왜 이런 이름이 붙었는지는 성경에 적혀 있어."}}],"gates":{"t1":[{"type":"find","ref":"창 11:2","prompt":"성경책에서 창세기 11장 2절을 찾아 읽어 보세요.","confirm":{"prompt":"사람들이 옮겨 가다가 자리 잡고 산 곳은 어느 평지인가요?","options":[{"label":"시날 평지","ok":true},{"label":"모압 평지","basis":"신 34:1"},{"label":"요단 들","basis":"창 13:10"}]}},{"type":"multi","ref":"창 11:3","prompt":"성경책에서 창세기 11장 3절을 찾아 읽어 보세요.","confirm":{"prompt":"사람들이 돌과 진흙 대신 쓴 것을 모두 고르세요.","options":[{"label":"벽돌","ok":true},{"label":"백향목","basis":"왕상 5:6"},{"label":"역청","ok":true},{"label":"짚","basis":"출 5:7"},{"label":"쇠","basis":"본문에 없음"}]}}],"t2":[{"type":"find","ref":"창 11:4-5","prompt":"성경책에서 창세기 11장 4절과 5절을 읽어 보세요.","confirm":{"prompt":"여호와께서 내려오신 까닭은 무엇인가요?","options":[{"label":"사람들이 쌓고 있는 성과 탑을 보시려고","ok":true},{"label":"사람들에게 벽돌 굽는 법을 알려 주시려고","basis":"본문에 없음"},{"label":"탑 꼭대기에 머무시려고","basis":"본문에 없음"}]}},{"type":"order","ref":"창 11:5-8","prompt":"성경책에서 창세기 11장 5절부터 8절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["여호와께서 내려오셨다","이 무리가 한 족속이고 언어도 하나라고 하셨다","이제 그들이 하려는 일을 막을 수 없겠다고 하셨다","그들의 언어를 뒤섞어 서로 못 알아듣게 하자고 하셨다","여호와께서 그들을 온 땅 위에 흩으셨다"]}],"t3":[{"type":"find","refs":["창 11:1","창 11:7"],"prompt":"창세기 11장 1절과 7절을 함께 찾아 읽어 보자.","confirm":{"prompt":"처음 사람들의 말은 어떠했고, 여호와께서는 그 말을 어떻게 하자고 하셨는가?","options":[{"label":"처음에는 온 땅의 말이 하나였는데, 여호와께서 그들의 말을 뒤섞어 서로의 말을 못 알아듣게 하자고 하셨다","ok":true},{"label":"처음에는 온 땅의 말이 하나였는데, 여호와께서 그 말을 그대로 하나로 두자고 하셨다","basis":"본문에 없음"},{"label":"사람들이 스스로 새 말을 만들자고 했다","basis":"본문에 없음"}]}},{"type":"match","refs":["창 11:2","창 11:5","창 11:9"],"prompt":"창세기 11장 2절, 5절, 9절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"창 11:2","text":"사람들이 옮겨 다니다가 시날 평지에 이르러 그곳에 살았다"},{"ref":"창 11:5","text":"여호와께서 사람들이 쌓는 성과 탑을 보시려고 내려오셨다"},{"ref":"창 11:9","text":"그곳의 이름을 바벨이라 했다"}],"after":"세 곳을 이으면, 사람들이 머물러 성과 탑을 쌓던 시날 평지에 여호와께서 내려오셨고, 그곳은 바벨이라는 이름을 얻었다."}]},"cards":[{"ref":"창 11:8","title":"온 지면에 흩으심"},{"ref":"창 11:9","title":"그 이름을 바벨이라 함"}],"close":{"t1":{"kind":"prayer","text":"하나님, 바벨에서 있었던 일을 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 창세기 11장 1절부터 9절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"창 11:1-9에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 타임머신이 비상 착륙하면서 착륙 다리의 받침이 부서져 한쪽으로 기울었어요. 이곳에서 받침 대신 쓸 것을 찾아봐요.","t2":"최현 박사예요. 비상 착륙 때 착륙 다리의 받침이 부서져서 타임머신이 한쪽으로 기울었어요. 이대로는 떠날 수 없어요. 이 시대에는 우리 부속이 없으니, 이곳에서 구할 수 있는 재료로 받침을 대신해야 해요.","t3":"최현 박사다. 비상 착륙으로 착륙 다리의 받침이 부서져 타임머신이 기울었고, 지금은 통신만 이어져 있다. 이 시대에는 부속이 없으니 이곳에서 얻을 수 있는 재료로 받침을 대신해야 한다."},"materials":[{"key":"clay","name":"진흙 한 덩이","basis":"창 11:3","use":"진흙을 뭉쳐 꼭꼭 다지면 기울어진 착륙 다리 밑에 괴어 부서진 받침 대신 쓸 수 있어요.","how":"사람들이 흩어진 뒤에, 성과 탑에서 멀리 떨어진 평지 가장자리에서 진흙 한 덩이를 손으로 떠 낸다. 사람들이 만든 것과 성과 탑에는 손대지 않는다.","line":"진흙 한 덩이를 떴어! 성에서 멀리 떨어진 평지 가장자리에서 떴어."}],"companion":null,"today":[{"q":"세상에는 왜 이렇게 여러 가지 말이 있어요?","a":{"t1":"성경은 처음에는 온 땅의 말이 하나였다고 말해요. 그런데 바벨에서 여호와께서 온 땅의 말을 뒤섞으시고, 사람들을 온 땅에 흩으셨다고 말해요.","t2":"성경은 처음에 온 땅의 언어가 하나였다고 말해요. 그런데 사람들이 시날 평지에서 성과 탑을 쌓을 때, 여호와께서 그들의 언어를 뒤섞어 서로 알아듣지 못하게 하셨어요. 그리고 그들을 거기에서 온 땅 위에 흩으셨어요. 그래서 그곳 이름을 바벨이라고 했어요.","t3":"성경은 처음에 온 땅의 언어가 하나였고 말도 하나였다고 기록한다(창 11:1). 그리고 바벨에서 여호와께서 온 땅의 언어를 혼잡하게 하여 서로 알아듣지 못하게 하시고, 그들을 거기에서 온 지면에 흩으셨다고 말한다(창 11:7-9). 성경은 여기까지 말한다."},"refs":["창 11:1","창 11:7-9"]},{"q":"그 탑은 무너졌어요? 지금도 남아 있어요?","a":{"t1":"성경은 사람들이 흩어져서 성 쌓기를 그쳤다고만 말해요. 탑이 무너졌는지, 지금 남아 있는지는 말하지 않아요.","t2":"성경은 여호와께서 사람들을 온 땅 위에 흩으시자 그들이 성 쌓는 일을 그쳤다고 말해요. 탑이 무너졌다거나 다 지어졌다는 말은 없어요. 지금 남아 있는지도 성경은 말하지 않아요.","t3":"성경은 여호와께서 그들을 거기에서 온 지면에 흩으셨으므로 그들이 성 쌓기를 그쳤다고 기록한다(창 11:8). 탑이 무너졌는지, 끝까지 지어졌는지, 지금 남아 있는지는 말하지 않는다. 성경은 여기까지 말한다."},"refs":["창 11:8"]}],"help":{"who":"시날 평지의 사람들(성과 탑을 쌓는 일은 돕지 않고 멀리서 지켜본다. 흩어져 떠날 때에는 길을 비켜 준다)","steps":[{"kind":"watch","after":2,"title":"멀리서 보기 · 성과 탑을 쌓자는 말","basis":"창 11:4","text":{"t1":"사람들이 성과 탑을 쌓자고 서로 말했어요. 우리는 그 일을 돕지 않고 멀리서 지켜봐요.","t2":"사람들이 서로 성과 탑을 쌓자고 말했어요. 우리는 그 일을 돕지 않아요. 사람들이 만든 벽돌과 역청에도 손대지 않고 멀리서 지켜봐요.","t3":"사람들은 서로 성과 탑을 쌓자고 말했다(11:4). 탐험대는 그 일을 돕지 않고, 사람들이 만든 벽돌과 역청에도 손대지 않는다(11:3). 멀리서 지켜본다. 그렇게 하자고 한 까닭은 사람들의 말로 같은 절에 적혀 있다."},"say":{"who":"choeon","text":"우리는 탑 쌓는 일에 끼지 않을 거야. 여기서 지켜보자."}},{"kind":"do","after":4,"title":"길 비켜 주기 · 흩어져 떠나는 사람들","basis":"창 11:8","text":{"t1":"여호와께서 사람들을 거기에서 온 땅으로 흩으셔서, 사람들이 떠나가요. 우리는 성과 탑에서 멀리 떨어진 평지 가장자리에서, 떠나는 사람들이 지나갈 길을 비켜 줘요.","t2":"여호와께서 사람들을 거기에서 온 땅 위에 흩으셔서, 그들은 성 쌓는 일을 그치고 떠나가요. 우리는 성과 탑에 다가가지 않고, 평지 가장자리에서 떠나는 사람들이 지나갈 길을 비켜 줘요.","t3":"여호와께서 그들을 거기에서 온 지면에 흩으셨다. 탐험대는 성과 탑에 다가가지 않고, 사람들이 만든 벽돌과 역청에도 손대지 않는다. 평지 가장자리에서, 흩어져 떠나는 사람들이 지나갈 길을 비켜 준다."},"tasks":["우리 짐을 길 밖으로 옮기기","평지 가장자리로 물러서기","사람들이 다 지나가도록 기다리기"],"done":{"who":"choeon","text":"사람들이 여러 쪽으로 떠나갔어. 우리는 길 밖에 비켜 서 있었어."}},{"kind":"ask","after":"gates","title":"흩어진 일은 무슨 뜻이에요?","basis":"창 11:8","by":"최현 박사","ask":{"who":"hyu","text":"사람들이 온 땅으로 흩어진 일은 무슨 뜻이에요?"},"answer":{"t1":"성경은 사람들이 이름을 내고 온 땅에 흩어지지 말자며 성과 탑을 쌓자고 했다고 말해요. 그런데 여호와께서 그들을 온 땅 위에 흩으셨고, 그들은 성 쌓기를 그쳤어요. 성경은 여기까지 말해요.","t2":"성경은 사람들이 탑 끝이 하늘에 닿게 하고 자기들의 이름을 내어, 온 땅에 흩어지는 것을 피하자고 말했다고 적어요(11:4). 여호와께서는 그들이 쌓는 성과 탑을 보러 내려오셨고(11:5), 그들을 온 땅 위에 흩으셨어요. 그래서 그들은 성 쌓는 일을 그쳤어요(11:8).","t3":"성경은 사람들이 성과 탑을 쌓아 탑의 끝이 하늘에 닿게 하고 자기 이름을 내어, 온 땅에 흩어지는 것을 면하자고 말했다고 기록한다(11:4). 여호와께서는 사람들이 쌓는 성과 탑을 보시려고 내려오셨고, 그들을 그곳에서 온 땅 위에 흩으셨으므로 그들이 성을 쌓던 일을 그쳤다(11:8). 성경은 여기까지 말한다."},"read":{"t1":{"type":"find","ref":"창 11:8","prompt":"성경책에서 창세기 11장 8절을 찾아 읽어 보세요.","confirm":{"prompt":"여호와께서 사람들을 흩으시자 그들은 무엇을 그쳤나요?","options":[{"label":"성을 쌓는 일","ok":true},{"label":"벽돌을 굽는 일","basis":"본문에 없음"},{"label":"양을 치는 일","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"창 11:3-4","prompt":"성경책에서 창세기 11장 3절과 4절을 읽어 보세요.","confirm":{"prompt":"사람들이 성과 탑을 쌓자고 한 까닭은 무엇인가요?","options":[{"label":"자기들의 이름을 내고, 온 땅에 흩어지는 것을 피하려고","ok":true},{"label":"하나님께 제사를 드릴 높은 단을 짓고, 그 위에서 예배하려고","basis":"본문에 없음"},{"label":"큰 물이 다시 와도 피할 수 있게 높은 곳을 만들려고","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["창 11:4","창 11:8"],"prompt":"창세기 11장 4절과 8절을 함께 찾아 읽어 보자.","confirm":{"prompt":"사람들이 성과 탑으로 하려던 일과 실제로 일어난 일은 어떻게 이어지는가?","options":[{"label":"사람들은 온 땅에 흩어지지 않으려고 성과 탑을 쌓자고 했으나, 여호와께서 그들을 온 땅 위에 흩으셨고 그들은 성 쌓기를 그쳤다","ok":true},{"label":"사람들은 온 땅에 흩어지지 않으려고 성과 탑을 쌓자고 했고, 여호와께서 그들을 흩으셨으나 남은 사람들이 탑을 끝까지 다 쌓았다","basis":"본문에 없음"},{"label":"사람들은 큰 물을 피할 곳을 만들려고 성과 탑을 쌓자고 했으나, 여호와께서 그들을 온 땅 위에 흩으셨고 그들은 성 쌓기를 그쳤다","basis":"본문에 없음"}]}}}}]}},"has3d":false,"epic":false},"OT-05":{"id":"OT-05","era":2,"title":"아브라함을 부르시고 언약을 주심","ref":"창 12:1-9","place":"하란, 벧엘 동쪽 산","review":{"required":true,"topics":["구약 사건의 신약적 의미(롬 4:3)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"창 12:1","open":"창 12:1","focus":"abram","text":{"t1":"하나님이 아브람에게 말씀하셨어요. 고향과 친척과 아버지의 집을 떠나, 하나님이 일러 주실 땅으로 가라고 하셨어요.","t2":"여호와께서 아브람에게 말씀하셨어요. 살던 땅과 친척과 아버지의 집을 떠나, 하나님이 일러 주실 땅으로 가라고 하셨어요.","t3":"여호와께서 아브람에게 그의 본토와 친척과 아버지의 집을 떠나라고 하셨다. 가야 할 곳은 하나님이 그에게 일러 주실 땅이었다."},"say":{"who":"onwoo","text":"성경은 여기서 이 사람을 아브람이라고 불러. 하나님이 하신 말씀은 창세기 12장 1절에서 직접 읽자."}},{"ref":"창 12:2-3","open":"창 12:2-3","focus":"abram","text":{"t1":"하나님은 아브람을 큰 민족이 되게 하고 복을 주겠다고 약속하셨어요.","t2":"하나님은 아브람을 큰 민족이 되게 하고, 복을 주고, 그의 이름을 크게 하겠다고 하셨어요. 땅의 모든 족속이 무엇 때문에 복을 얻을 것이라고 하셨는지는 3절에 있어요.","t3":"하나님은 아브람을 큰 민족이 되게 하고 그에게 복을 주어 이름을 크게 하겠다고 하셨고, 그가 복의 근원이 될 것이라고 하셨다. 아브람을 대하는 사람들과 땅의 모든 족속에 대해 하신 말씀은 3절에서 직접 읽어 보자."},"say":{"who":"hyu","text":"약속을 일지에 적어 둘게. 큰 민족, 복, 큰 이름."}},{"ref":"창 12:4-5","focus":"caravan","text":{"t1":"아브람은 하나님의 말씀대로 아내와 조카 롯과 함께 길을 떠나 가나안 땅에 들어갔어요. 아내의 이름은 성경에서 찾아봐요.","t2":"아브람은 여호와의 말씀을 따라 하란을 떠났어요. 그때 아브람은 일흔다섯 살이었어요. 아내 사래와 조카 롯, 하란에서 모은 재산과 사람들을 데리고 떠났는데, 어디로 향했는지는 5절에 있어요.","t3":"아브람은 하란을 떠났고 롯도 함께 갔다. 하란을 떠날 때 그의 나이는 일흔다섯이었다. 그는 아내 사래와 조카 롯, 그리고 하란에서 얻은 재산과 사람들을 모두 데리고 떠났다. 아브람이 무엇을 따라 떠났는지와, 어느 땅으로 가서 들어갔는지는 4절과 5절에 있다."},"say":{"who":"hyu","text":"하란을 떠났어. 일행이 떠난 곳을 일지에 적어 둘게."}},{"ref":"창 12:6-7","open":"창 12:7","focus":"altar","text":{"t1":"아브람이 세겜 땅의 모레 상수리나무 곁에 오자, 하나님이 나타나 이 땅을 그의 자손에게 주겠다고 하셨어요. 아브람은 그곳에 제단을 쌓았어요.","t2":"아브람은 그 땅을 지나 세겜 땅 모레 상수리나무에 이르렀어요. 그때 그 땅에는 가나안 사람이 살고 있었어요. 여호와께서 아브람에게 나타나 이 땅을 그의 자손에게 주겠다고 하셨어요. 아브람은 그곳에 제단을 쌓았는데, 누구를 위해 쌓았는지는 7절에 있어요.","t3":"아브람은 그 땅을 지나 한 곳에 이르렀다. 그때 그 땅에는 가나안 사람이 살고 있었다. 여호와께서 아브람에게 나타나 이 땅을 그의 자손에게 주겠다고 하셨다. 아브람이 이른 곳의 이름과 그곳에서 한 일은 6절과 7절에서 직접 읽어 보자."},"say":{"who":"choeon","text":"나무 곁이야. 아브람이 제단을 쌓았어."}},{"ref":"창 12:8-9","focus":"tent","text":{"t1":"아브람은 벧엘 동쪽 산으로 옮겨 장막을 치고, 거기서도 제단을 쌓아 여호와의 이름을 불렀어요. 장막의 동쪽에 무엇이 있었는지는 성경에서 찾아봐요.","t2":"아브람은 거기서 벧엘 동쪽 산으로 옮겨 장막을 쳤어요. 서쪽은 벧엘, 동쪽은 아이였어요. 그곳에서 여호와께 제단을 쌓고 여호와의 이름을 불렀어요. 그 뒤에 점점 남쪽으로 옮겨 갔어요.","t3":"아브람은 거기서 벧엘 동쪽 산으로 옮겨 장막을 쳤는데, 서쪽에는 벧엘이, 동쪽에는 아이가 있었다. 그는 그곳에 제단을 쌓았다. 그곳에서 아브람이 더 한 일과 그 뒤에 어디로 옮겨 갔는지는 8절과 9절에 있다."},"say":{"who":"hyu","text":"장막을 친 자리를 일지에 그려 둘게."}},{"ref":"창 15:1-4","open":"창 15:1","focus":"abram","text":{"t1":"그 뒤에 하나님은 아브람에게 두려워하지 말라고 하셨어요. 자식이 없다고 아뢰는 아브람에게, 그의 몸에서 태어날 사람이 뒤를 이을 것이라고 하셨어요.","t2":"이 일들 뒤에 여호와의 말씀이 환상 가운데 아브람에게 임했어요. 하나님과 아브람이 무슨 말을 어떤 차례로 주고받았는지는 1절부터 4절까지 읽어 봐요.","t3":"이 일들 뒤에 여호와의 말씀이 환상 가운데 아브람에게 임했다. 하나님은 두려워하지 말라고 하시며 자신을 아브람의 무엇이라고 하셨는데, 그 말씀은 1절에서 직접 읽어 보자. 아브람은 자기에게 자식이 없는데 무엇을 주시려는지 여쭈었고, 상속자는 다메섹 사람 엘리에셀이며 자기 집에서 자란 사람이 뒤를 잇게 될 것이라고 아뢰었다. 여호와의 말씀이 다시 임하여, 그 사람이 아니라 아브람의 몸에서 날 사람이 상속자가 될 것이라고 하셨다."},"say":{"who":"onwoo","text":"여기부터는 창세기 15장이야. 아브람이 아뢴 말과 하나님의 대답은 2절부터 4절에 있어. 성경책에서 읽어 보자."}},{"ref":"창 15:5-6","open":"창 15:5","focus":"stars","text":{"t1":"하나님은 아브람에게 하늘을 올려다보게 하시며 자손이 그와 같이 많을 것이라고 하셨고, 아브람은 여호와를 믿었어요. 하늘의 무엇을 세어 보라고 하셨는지는 성경에서 찾아봐요.","t2":"하나님은 아브람을 이끌고 밖으로 나가, 하늘을 올려다보고 별들을 셀 수 있는지 보라고 하셨어요. 그리고 아브람의 자손이 이와 같을 것이라고 하셨어요. 그 말씀을 들은 아브람이 어떻게 했고 여호와께서 그것을 어떻게 여기셨는지는 6절에 있어요.","t3":"하나님은 그를 이끌고 밖으로 나가, 하늘을 우러러 뭇별을 셀 수 있는지 보라고 하셨다. 그리고 그의 자손이 이와 같을 것이라고 하셨다. 그 말씀 앞에서 아브람이 어떻게 했고 여호와께서 그것을 어떻게 여기셨는지는 6절에서 직접 읽어 보자."},"say":{"who":"choeon","text":"와, 하늘 좀 봐!"}}],"gates":{"t1":[{"type":"find","ref":"창 12:4","prompt":"성경책에서 창세기 12장 4절을 찾아 읽어 보세요.","confirm":{"prompt":"하란을 떠날 때 아브람의 나이는 몇 살이었나요?","options":[{"label":"일흔다섯 살","ok":true},{"label":"아흔아홉 살","basis":"창 17:1"},{"label":"백 살","basis":"창 21:5"}]}},{"type":"multi","ref":"창 15:1","prompt":"성경책에서 창세기 15장 1절을 찾아 읽어 보세요.","confirm":{"prompt":"하나님은 자신이 아브람의 무엇이라고 하셨나요? 모두 고르세요.","options":[{"label":"방패","ok":true},{"label":"목자","basis":"시 23:1"},{"label":"지극히 큰 상급","ok":true},{"label":"빛","basis":"시 27:1"}]}}],"t2":[{"type":"find","ref":"창 12:2-3","prompt":"성경책에서 창세기 12장 2절과 3절을 읽어 보세요.","confirm":{"prompt":"하나님은 땅의 모든 족속이 무엇 때문에 복을 얻을 것이라고 하셨나요?","options":[{"label":"아브람으로 말미암아","ok":true},{"label":"아브람이 여호와께 제단을 쌓았기 때문에","basis":"창 12:7"},{"label":"롯이 아브람과 함께 길을 떠났기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"창 15:1-5","prompt":"성경책에서 창세기 15장 1절부터 5절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["하나님이 두려워하지 말라고 하셨다","아브람이 무엇을 주시려느냐고 여쭈었다","아브람이 집에서 자란 사람이 뒤를 이을 것이라고 아뢰었다","하나님이 아브람의 몸에서 날 사람이 뒤를 이을 것이라고 하셨다","하나님이 아브람을 밖으로 이끌고 나가 하늘을 보게 하셨다"]}],"t3":[{"type":"find","refs":["창 12:6","창 12:8","창 12:9"],"prompt":"창세기 12장 6절, 8절, 9절을 함께 찾아 읽어 보자.","confirm":{"prompt":"아브람은 이 땅에 들어와 처음 어디에 이르렀다가, 어디로 옮겨 갔는가?","options":[{"label":"모레 상수리나무가 있는 세겜 땅에 이르렀고, 거기서 벧엘 동쪽의 산에 장막을 쳤으며, 그 뒤에는 남쪽으로 조금씩 옮겨 갔다","ok":true},{"label":"벧엘 동쪽 산에서 곧바로 하란으로 돌아갔다","basis":"본문에 없음"},{"label":"모레 상수리나무가 있는 세겜 땅에 이르렀고, 거기서 벧엘 동쪽의 산에 장막을 쳤으며, 그 뒤에는 동쪽의 아이로 들어가 살았다","basis":"본문에 없음"}]}},{"type":"match","refs":["창 12:2","창 12:7","창 15:4"],"prompt":"창세기 12장 2절, 12장 7절, 15장 4절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"창 12:2","text":"아브람으로 큰 민족을 이루게 하겠다고 하셨다"},{"ref":"창 12:7","text":"이 땅을 아브람의 자손에게 주겠다고 하셨다"},{"ref":"창 15:4","text":"아브람의 몸에서 날 사람이 상속자가 되리라고 하셨다"}],"after":"세 곳을 이으면, 하나님은 아브람으로 큰 민족을 이루게 하고 이 땅을 그 자손에게 주겠다고 하셨으며, 자식이 없던 아브람에게 그의 몸에서 날 사람이 상속자가 되리라고 하셨다."}]},"cards":[{"ref":"창 12:2","title":"큰 민족과 복의 약속"},{"ref":"창 15:5","title":"하늘의 뭇별"}],"close":{"t1":{"kind":"prayer","text":"하나님, 아브람에게 하신 약속의 말씀을 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 창세기 12장 1절부터 9절까지, 그리고 15장 1절부터 6절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"창 12:1-9와 창 15:1-6에서 새로 알게 된 사실을 한 가지 적어 보자."}},"quests":[{"part":"gear","name":"톱니바퀴","line":"톱니바퀴를 찾았어! 일행이 지나온 길가에 떨어져 있었네.","found":"탐지기가 아브람 일행이 이 땅으로 들어온 길 쪽을 가리켜요.","say":{"who":"hyu","text":"탐지기 바늘이 길 쪽으로 돌아갔어. 일지에 적어 둘게."},"q":{"t1":{"type":"find","ref":"창 12:5","prompt":"성경책에서 창세기 12장 5절을 찾아 읽어 보세요.","confirm":{"prompt":"아브람과 함께 길을 떠난 아내는 누구인가요?","options":[{"label":"사래","ok":true},{"label":"하와","basis":"창 3:20"},{"label":"미리암","basis":"출 15:20"}]}},"t2":{"type":"find","ref":"창 12:4-5","prompt":"성경책에서 창세기 12장 4절과 5절을 읽어 보세요.","confirm":{"prompt":"아브람 일행은 무엇을 하려고 하란을 떠났나요?","options":[{"label":"가나안 땅에 가려고","ok":true},{"label":"애굽 땅에서 곡식을 사려고","basis":"본문에 없음"},{"label":"갈대아 우르로 돌아가려고","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["창 12:1","창 12:5"],"prompt":"창세기 12장 1절과 5절을 함께 찾아 읽어 보자.","confirm":{"prompt":"하나님이 가라고 하신 땅과 아브람이 들어간 땅은 어떻게 이어지는가?","options":[{"label":"하나님은 일러 주실 땅으로 가라고만 하셨고, 아브람은 가나안 땅을 향해 길을 떠나 끝내 그 땅에 들어갔다","ok":true},{"label":"하나님이 처음부터 그 땅의 이름을 가나안이라고 일러 주셨다","basis":"본문에 없음"},{"label":"하나님은 일러 주실 땅으로 가라고만 하셨고, 아브람은 애굽 땅을 향해 길을 떠나 그 땅에 들어갔다","basis":"창 12:10"}]}}}},{"part":"needle","name":"나침반 바늘","line":"나침반 바늘이 여기 있었네! 장막이 건너다보이는 언덕 가장자리야.","found":"탐지기가 장막 쪽을 가리켜요.","say":{"who":"onwoo","text":"언덕 가장자리까지만 가자. 장막과 제단 가까이는 가지 말자. 여기서 지켜보자."},"q":{"t1":{"type":"find","ref":"창 12:8","prompt":"성경책에서 창세기 12장 8절을 찾아 읽어 보세요.","confirm":{"prompt":"아브람이 장막을 친 곳에서 동쪽에는 어느 곳이 있었나요?","options":[{"label":"아이","ok":true},{"label":"세겜","basis":"창 12:6"},{"label":"하란","basis":"창 12:4"}]}},"t2":{"type":"find","ref":"창 12:6-7","prompt":"성경책에서 창세기 12장 6절과 7절을 읽어 보세요.","confirm":{"prompt":"아브람이 그곳에 제단을 쌓은 까닭은 무엇이라고 적혀 있나요?","options":[{"label":"자기에게 나타나 말씀하신 여호와를 위해서","ok":true},{"label":"가나안 땅을 곧바로 달라고 여호와께 구하려고","basis":"본문에 없음"},{"label":"비가 오게 해 달라고 빌려고","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["창 12:7","창 12:8"],"prompt":"창세기 12장 7절과 8절을 함께 찾아 읽어 보자.","confirm":{"prompt":"아브람이 이 땅에서 머문 곳마다 한 일은 무엇인가?","options":[{"label":"머문 곳마다 여호와를 위하여 제단을 쌓았고, 장막을 친 곳에서는 여호와의 이름을 불렀다","ok":true},{"label":"장막을 친 곳에서만 제단을 쌓았고, 처음 이른 곳에서는 아무 일도 하지 않았다","basis":"본문에 없음"},{"label":"머문 곳마다 제단을 쌓았으나, 여호와의 이름을 부른 일은 적혀 있지 않다","basis":"본문에 없음"}]}}}},{"part":"lens","name":"렌즈","line":"렌즈를 찾았어! 장막에서 떨어진 땅바닥에 있었어.","found":"탐지기가 장막에서 멀리 떨어진 언덕 위 트인 땅을 가리켜요.","say":{"who":"choeon","text":"여기서는 아래쪽 땅이 멀리까지 보여!"},"q":{"t1":{"type":"find","ref":"창 15:5","prompt":"성경책에서 창세기 15장 5절을 찾아 읽어 보세요.","confirm":{"prompt":"하나님은 아브람에게 하늘의 무엇을 셀 수 있는지 보라고 하셨나요?","options":[{"label":"별","ok":true},{"label":"구름","basis":"본문에 없음"},{"label":"달","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"창 15:1-4","prompt":"성경책에서 창세기 15장 1절부터 4절까지 읽어 보세요.","confirm":{"prompt":"아브람이 두려워하지 않아도 되는 까닭으로 하나님이 하신 말씀은 무엇인가요?","options":[{"label":"하나님이 아브람의 방패요 지극히 큰 상급이시라는 말씀","ok":true},{"label":"아브람에게 큰 군대를 주겠다는 말씀","basis":"본문에 없음"},{"label":"아브람이 다시는 길을 떠나지 않아도 된다는 말씀","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["창 12:3","창 15:1"],"prompt":"창세기 12장 3절과 15장 1절을 함께 찾아 읽어 보자.","confirm":{"prompt":"하나님은 아브람을 대하는 사람들을 어떻게 하시겠다고 하셨고, 뒤에 아브람에게 자신을 무엇이라고 하셨는가?","options":[{"label":"아브람을 축복하는 사람에게는 복을, 저주하는 사람에게는 저주를 내리겠다고 하셨고, 뒤에 자신이 아브람의 방패요 지극히 큰 상급이라고 하셨다","ok":true},{"label":"아브람을 축복하는 사람에게는 복을 내리고, 저주하는 사람도 그대로 두겠다고 하셨고, 뒤에 자신이 아브람을 이끄는 목자라고 하셨다","basis":"본문에 없음"},{"label":"아브람을 축복하는 사람에게는 복을, 저주하는 사람에게는 저주를 내리겠다고 하셨고, 뒤에 자신이 아브람의 빛이요 구원이라고 하셨다","basis":"시 27:1"}]}}}}],"mission":{"call":{"t1":"타임머신이 비상 착륙했어요! 부속 세 개가 고장 났어요. 탐지기가 가리키는 곳에서 재료를 찾아 대신 만들어요.","t2":"최현 박사예요. 타임머신이 비상 착륙하면서 부속 세 개가 망가졌어요. 그 시대에는 부속을 구할 수 없으니, 그곳에서 얻을 수 있는 재료로 대신 만들어야 해요. 탐지기가 재료가 있는 곳을 하나씩 가리켜 줄 거예요.","t3":"타임머신이 비상 착륙하면서 부속 세 개가 망가졌다. 그 시대에는 부속이 없으니 그 자리에서 얻을 수 있는 재료로 대신 만들어야 한다. 탐지기가 가리키는 곳으로 가되, 사람들의 물건과 사건이 일어나는 자리에는 손대지 않아야 한다."},"materials":[{"key":"flatstone","name":"납작한 돌","basis":"창 12:5","use":"둥글고 납작한 돌 가장자리에 홈을 파면 톱니바퀴 대신 쓸 수 있어요.","how":"아브람 일행이 지나간 뒤, 일행이 지나온 길가에 굴러 있는 둥글고 납작한 돌을 줍는다. 일행의 짐과 사람들에게는 가까이 가지 않는다.","line":"길가에서 둥글고 납작한 돌을 주웠어. 아브람 일행이 지나온 길이야."},{"key":"stonechip","name":"길쭉한 돌 조각","basis":"창 12:8","use":"길쭉한 돌 조각을 매끈하게 갈면 나침반 바늘 대신 쓸 수 있어요.","how":"장막이 건너다보이는 언덕 가장자리에 떨어져 있는 길쭉한 돌 조각을 줍는다. 장막과 제단에는 손대지 않고, 그쪽으로는 가지 않는다.","line":"장막이 건너다보이는 언덕 가장자리에서 길쭉한 돌 조각을 주웠어."},{"key":"soil","name":"흙","basis":"창 12:6","use":"흙을 얇고 동그랗게 빚어 말린 뒤 가운데에 작은 구멍을 내면, 바늘구멍 사진기처럼 렌즈 대신 쓸 수 있어요.","how":"장막과 아브람에게서 멀리 떨어진 언덕 위 트인 땅바닥에서 흙을 한 줌 뜬다.","line":"장막에서 멀리 떨어진 땅바닥에서 흙을 한 줌 떴어."}],"companion":{"who":"아브람","when":"after","ref":"창 15:1","talks":[{"ask":{"who":"hyu","text":"하나님이 두려워하지 말라고 하셨을 때, 하나님께 무엇을 여쭈었어요?"},"answer":{"t1":"아브람은 하나님께 자기에게 무엇을 주시려느냐고 여쭈었어요. 자기에게는 자식이 없다고 했어요.","t2":"아브람은 주 여호와께, 자기에게 무엇을 주시려느냐고 여쭈었어요. 그러면서 자기에게는 자식이 없다고 아뢰었어요.","t3":"아브람은 주 여호와께 자기에게 무엇을 주시려느냐고 여쭈며, 자기는 자식 없이 지내고 있다고 아뢰었다."},"ref":"창 15:2","open":"창 15:2"},{"ask":{"who":"choeon","text":"그때 누가 뒤를 이을 거라고 아뢰셨어요?"},"answer":{"t1":"아브람은 다메섹 사람 엘리에셀이 상속자라고 아뢰었어요. 하나님이 자식을 주지 않으셨으니, 집에서 자란 사람이 뒤를 이을 것이라고 했어요.","t2":"아브람은 자기 상속자가 다메섹 사람 엘리에셀이라고 아뢰었어요. 또 하나님이 자기에게 씨를 주지 않으셨으니, 자기 집에서 자란 사람이 뒤를 이을 것이라고 아뢰었어요.","t3":"아브람은 자기의 상속자가 다메섹 사람 엘리에셀이라고 아뢰었다. 또 주께서 자기에게 씨를 주지 않으셨으므로 자기 집에서 길러진 사람이 후사가 될 것이라고 아뢰었다."},"ref":"창 15:2-3","open":"창 15:3"}]},"today":[{"q":"낯선 곳으로 떠나는 게 무서울 때가 있어요. 아브람도 무서웠을까요?","a":{"t1":"성경은 아브람이 무서웠는지 말하지 않아요. 아브람은 여호와의 말씀대로 길을 떠났어요. 그 뒤에 하나님은 아브람에게 두려워하지 말라고 하셨어요.","t2":"성경은 아브람의 마음이 어땠는지 적지 않아요. 아브람이 여호와의 말씀을 따라 하란을 떠났다고만 해요. 그 뒤에 하나님은 아브람에게 두려워하지 말라고 하시며, 하나님이 아브람의 방패라고 하셨어요.","t3":"성경은 아브람의 마음이 어땠는지 적지 않는다. 아브람이 여호와의 말씀을 따라 하란을 떠났다고 말할 뿐이다(창 12:4). 그 뒤에 하나님은 아브람에게 두려워하지 말라고 하시며, 자신이 그의 방패요 지극히 큰 상급이라고 하셨다(창 15:1). 성경은 여기까지 말한다."},"refs":["창 12:4","창 15:1"]},{"q":"자손이 하늘의 별처럼 많아진다는 약속은 정말 이루어졌어요?","a":{"t1":"하나님은 아브람의 자손이 하늘의 별과 같을 것이라고 하셨어요. 나중에 모세는, 여호와께서 이스라엘 백성을 하늘의 별처럼 많게 하셨다고 말했어요.","t2":"창세기 15장에서 하나님은 아브람의 자손이 하늘의 별과 같을 것이라고 하셨어요. 나중에 모세는 이스라엘 백성에게, 애굽으로 내려간 조상은 칠십 명뿐이었지만 이제 여호와께서 백성을 하늘의 별처럼 많게 하셨다고 말했어요.","t3":"창 15:5에서 하나님은 아브람의 자손이 하늘의 뭇별과 같을 것이라고 하셨다. 신명기에서 모세는 이스라엘 백성에게, 애굽으로 내려간 조상은 칠십 명뿐이었으나 이제 여호와께서 백성을 하늘의 별처럼 많게 하셨다고 말했다(신 10:22). 성경은 여기까지 말한다."},"refs":["창 15:5","신 10:22"]}],"help":{"who":"아브람과 그 일행(일행이 지나갈 길을 비켜 주고, 장막과 제단에는 손대지 않고 언덕 가장자리에서 지켜본다)","steps":[{"kind":"do","after":2,"title":"길 비켜 주기 · 이 땅에 들어오는 일행","basis":"창 12:5","text":{"t1":"아브람 일행이 사람들과 짐을 데리고 가나안 땅에 들어와요. 우리는 일행이 지나갈 길을 비켜 주며 도와요.","t2":"아브람이 사래와 롯, 하란에서 모은 재산과 함께한 사람들을 데리고 이 땅에 들어와요. 우리는 일행에게 가까이 가지 않고, 그들이 지나갈 길을 비켜 주며 도와요.","t3":"아브람은 아내와 조카 롯, 재산과 사람들을 데리고 이 땅에 들어왔다. 탐험대는 일행의 짐과 사람들에게 가까이 가지 않고, 그들이 지나갈 길을 비켜 준다."},"tasks":["길가에 둔 우리 짐 언덕 쪽으로 옮기기","언덕 위로 물러서기","일행이 다 지나가도록 기다리기"],"done":{"who":"hyu","text":"사람들과 짐이 다 지나갔어. 일행이 지나간 길을 일지에 적어 둘게."}},{"kind":"watch","after":4,"title":"멀리서 보기 · 벧엘 동쪽 산의 제단","basis":"창 12:8","text":{"t1":"아브람이 벧엘 동쪽 산에서 여호와께 제단을 쌓아 여호와의 이름을 불렀어요. 우리는 언덕 가장자리에서 지켜봐요.","t2":"아브람이 장막을 친 곳에서 여호와께 제단을 쌓아 여호와의 이름을 불렀어요. 이 일은 아브람이 했어요. 우리는 장막과 제단에 가까이 가지 않고 언덕 가장자리에서 지켜봐요.","t3":"아브람은 벧엘 동쪽 산에 장막을 친 곳에서 제단을 쌓았다. 본문은 이 일을 아브람이 했다고 적는다. 탐험대는 장막과 제단에 가까이 가지 않고, 장막이 건너다보이는 언덕 가장자리에서 지켜본다."},"say":{"who":"hyu","text":"아브람이 이곳에서 한 일은 12장 8절에 적혀 있어. 일지에 적어 둘게."}},{"kind":"ask","after":"gates","title":"하늘을 보게 하신 일은 무슨 뜻이에요?","basis":"창 15:6","by":"최현 박사","ask":{"who":"choeon","text":"하나님이 아브람에게 하늘을 보게 하시고 약속하신 그 일은 무슨 뜻이에요?"},"answer":{"t1":"성경은 아브람이 하나님의 말씀을 듣고 여호와를 믿었다고 말해요. 여호와께서는 그것을 아브람의 의로 여기셨어요. 성경은 여기까지 말해요.","t2":"하나님은 아브람을 밖으로 이끌어 하늘의 뭇별을 보게 하시고, 그의 자손이 그와 같을 것이라고 하셨어요(15:5). 성경은 아브람은 여호와를 믿었고, 여호와께서 그것을 아브람의 의로 여기셨다고 말해요(15:6). 성경은 여기까지 말해요.","t3":"하나님은 자식이 없다고 아뢴 아브람에게, 그의 몸에서 날 사람이 상속자가 되리라고 하셨다. 그리고 그를 밖으로 이끌어 뭇별을 보게 하시며 그의 자손이 이와 같으리라고 하셨다(15:5). 성경은 아브람은 여호와를 믿었고, 여호와께서 그것을 그의 의로 여기셨다고 기록한다(15:6). 성경은 여기까지 말한다."},"read":{"t1":{"type":"find","ref":"창 15:6","prompt":"성경책에서 창세기 15장 6절을 찾아 읽어 보세요.","confirm":{"prompt":"여호와께서는 아브람이 믿은 것을 무엇으로 여기셨나요?","options":[{"label":"그의 의","ok":true},{"label":"그의 상급","basis":"본문에 없음"},{"label":"그의 재산","basis":"본문에 없음"}]},"inStory":"'그의'는 흔한 말이라 겹칠 뿐이고, 믿은 것을 의로 여기신 일은 15:6에서만 안다(8~10세 대목 글에는 없다)"},"t2":{"type":"find","ref":"창 15:4-6","prompt":"성경책에서 창세기 15장 4절부터 6절까지 읽어 보세요.","confirm":{"prompt":"여호와께서 의로 여기신 것은 아브람이 무엇을 했기 때문인가요?","options":[{"label":"여호와를 믿었기 때문에","ok":true},{"label":"제단을 두 번 쌓았기 때문에","basis":"본문에 없음"},{"label":"많은 소유를 모았기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["창 12:4","창 15:6"],"prompt":"창세기 12장 4절과 15장 6절을 함께 찾아 읽어 보자.","confirm":{"prompt":"12장과 15장에서 여호와의 말씀 앞에서 아브람은 어떻게 했다고 적혀 있는가?","options":[{"label":"12장에서는 여호와의 말씀을 따라 하란을 떠났고, 15장에서는 여호와를 믿었으며 여호와께서 그것을 그의 의로 여기셨다","ok":true},{"label":"12장에서는 롯의 말을 따라 하란을 떠났고, 15장에서는 제단을 쌓았으며 여호와께서 그것을 그의 의로 여기셨다","basis":"본문에 없음"},{"label":"12장에서는 여호와의 말씀을 따라 하란을 떠났고, 15장에서는 제단을 쌓았으며 여호와께서 그것을 그의 의로 여기셨다","basis":"본문에 없음"}]}}},"nt":{"ref":"롬 4:3","text":"신약의 로마서 4장 3절은 성경이 무엇을 말하는지 물으며, 하나님을 믿은 아브라함에게 그것이 의로 여겨졌다고 말한다."}}]}},"has3d":true,"epic":true},"OT-06":{"id":"OT-06","era":2,"title":"모리아 산의 아브라함과 이삭","ref":"창 22:1-19","place":"모리아 땅의 한 산","review":{"required":true,"topics":["구약 사건의 신약적 의미"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"창 22:1-2","open":"창 22:2","focus":"abraham","text":{"t1":"하나님이 시험하시려고 아브라함을 부르셨어요. 아들 이삭을 모리아 땅으로 데려가, 하나님이 일러 주실 산에서 번제로 드리라고 하셨어요.","t2":"그 일 뒤에 하나님은 아브라함을 시험하시려고 부르셨어요. 아브라함은 자기가 여기 있다고 대답했어요. 하나님은 아브라함에게, 그가 사랑하는 외아들 이삭을 데리고 모리아 땅으로 가서, 일러 주실 한 산에서 그를 번제로 드리라고 하셨어요.","t3":"그 일 뒤에 하나님은 아브라함을 시험하시려고 그의 이름을 부르셨고, 아브라함은 자기가 여기 있다고 대답했다. 하나님은 그가 사랑하는 독자 이삭과 함께 모리아 땅으로 가서, 일러 주실 한 산에서 그를 번제로 드리라고 하셨다."},"say":{"who":"onwoo","text":"1절은 이 일이 시험이었다고 먼저 알려 줘. 하나님이 하신 말씀은 창세기 22장 2절에서 직접 읽자."}},{"ref":"창 22:3-5","focus":"donkey","text":{"t1":"아브라함은 이삭과 사환들과 함께 길을 떠났고, 그곳이 멀리 보이자 사환들에게 나귀와 함께 기다리라고 했어요. 아침에 떠나며 한 일과 며칠째에 그곳이 보였는지는 성경에서 찾아봐요.","t2":"아브라함은 아침 일찍 일어나 나귀에 안장을 얹었어요. 두 사환과 아들 이삭을 데리고, 번제 때 쓸 나무를 쪼개어 길을 떠났어요. 사흘째 되는 날 눈을 들어 그곳을 멀리서 보았어요. 아브라함은 사환들에게 나귀와 함께 기다리라고 하고, 아이와 함께 가서 경배하고 돌아오겠다고 말했어요.","t3":"아브라함은 아침 일찍 일어나 나귀에 안장을 얹고, 두 사환과 아들 이삭을 데리고, 번제 때 쓸 나무를 쪼개어 하나님이 일러 주신 곳으로 떠났다. 사흘째 되는 날 그는 눈을 들어 그곳을 멀리서 보았다. 그는 사환들에게 나귀와 함께 그 자리에서 기다리라고 했다. 그때 자기는 무엇을 하겠다고 했는지는 5절에서 직접 읽어 보자."},"say":{"who":"hyu","text":"아브라함이 사환들에게 나귀 곁에 남아 있으라고 했어. 일지에 적어 둘게."}},{"ref":"창 22:6-8","focus":"isaac","text":{"t1":"아브라함은 번제 나무는 이삭이 지게 하고, 불과 칼은 자기가 들었어요. 이삭이 어린 양은 어디 있느냐고 묻자, 아브라함은 하나님이 준비하실 것이라고 대답했어요.","t2":"아브라함은 번제에 쓸 나무를 이삭이 지게 하고, 자기는 불과 칼을 손에 들었어요. 두 사람이 함께 걸어가며 무슨 말을 어떤 차례로 주고받았는지는 7절과 8절에서 읽어 봐요.","t3":"아브라함은 번제 나무를 아들 이삭이 지게 하고 자기는 불과 칼을 손에 들었으며, 두 사람은 함께 갔다. 이삭이 아버지를 부르자 아브라함은 자기가 여기 있다고 대답했다. 이삭은 불과 나무는 있는데 번제로 드릴 어린 양은 어디 있는지 물었고, 아브라함은 그 어린 양은 하나님이 친히 마련하실 것이라고 대답했다. 두 사람은 함께 나아갔다."},"say":{"who":"choeon","text":"이삭이 나무를 지고 가. 아브라함은 불과 칼을 들었어."}},{"ref":"창 22:9-10","focus":"altar","text":{"t1":"하나님이 일러 주신 곳에서 아브라함은 제단을 쌓아 나무를 늘어놓았어요. 그리고 이삭을 묶어 나무 위에 놓았어요.","t2":"하나님이 일러 주신 곳에 이르자, 아브라함은 그곳에 제단을 쌓고 나무를 벌여 놓았어요. 아들 이삭을 묶어 제단 나무 위에 놓았어요. 그리고 손을 내밀어 칼을 잡았어요.","t3":"하나님이 일러 주신 곳에 이르러 아브라함은 제단을 쌓고 나무를 벌여 놓았다. 그리고 아들 이삭을 묶어 제단의 나무 위에 놓은 뒤, 손을 내밀어 칼을 잡고 아들을 잡으려 했다."},"say":{"who":"hyu","text":"하나님이 일러 주신 곳에서 제단을 쌓고 나무를 놓은 순서는 9절에 있어. 일지에 적어 둘게."}},{"ref":"창 22:11-12","open":"창 22:11-12","focus":"sky","text":{"t1":"그때 하늘에서 여호와의 사자가 아브라함의 이름을 두 번 불렀어요. 사자가 무엇을 하지 말라고 했는지는 성경에서 찾아봐요.","t2":"여호와의 사자가 하늘에서 아브라함의 이름을 두 번 불렀고, 아브라함은 자기가 여기 있다고 대답했어요. 사자는 아이에게 손을 대지 말고 아무 일도 하지 말라고 했어요. 사자가 이어서 한 말은 12절에서 직접 읽어 봐요.","t3":"여호와의 사자가 하늘에서 아브라함의 이름을 거듭 불렀고, 아브라함은 자기가 여기 있다고 대답했다. 사자는 그 아이에게 손을 대지 말고 아무 일도 하지 말라고 했다. 사자가 이어서 한 말은 12절에서 직접 읽어 보자."},"say":{"who":"onwoo","text":"하늘에서 들린 말은 11절과 12절에 있어. 우리가 지어내지 말고 성경책에서 직접 읽어 보자."}},{"ref":"창 22:13-14","focus":"ram","text":{"t1":"아브라함이 보니 숫양 한 마리가 뿔이 수풀에 걸려 있었고, 아브라함은 그 숫양을 아들 대신 번제로 드렸어요. 그 땅 이름은 여호와이레라고 불렀어요.","t2":"아브라함이 눈을 들어 살펴보니, 뒤에 숫양 한 마리가 있었는데 뿔이 수풀에 걸려 있었어요. 아브라함은 가서 그 숫양을 가져다가 아들 대신 번제로 드렸어요. 아브라함은 그 땅 이름을 여호와이레라고 했어요.","t3":"아브라함이 눈을 들어 살펴보니 뒤에 숫양 한 마리가 있었는데, 뿔이 수풀에 걸려 있었다. 아브라함은 가서 그 숫양을 가져다가 아들 대신 번제로 드렸다. 그는 그 땅 이름을 여호와이레라 하였고, 그래서 지금까지도 사람들이 여호와의 산에서 준비되리라고 말한다고 성경은 적는다."},"say":{"who":"choeon","text":"수풀에 숫양 한 마리가 뿔이 걸려 있었대!"}},{"ref":"창 22:15-19","open":"창 22:16-18","focus":"abraham","text":{"t1":"여호와의 사자가 다시 아브라함을 불러, 큰 복을 주고 자손이 하늘의 별처럼 많아지게 하겠다는 여호와의 말씀을 전했어요. 아브라함은 사환들에게 돌아가 함께 브엘세바로 가서 살았어요.","t2":"여호와의 사자가 하늘에서 두 번째로 아브라함을 불러 여호와의 말씀을 전했어요. 여호와께서는 아브라함에게 큰 복을 주고 자손을 하늘의 별과 바닷가의 모래처럼 많게 하겠다고 하셨는데, 그 까닭은 16절과 18절에 있어요. 아브라함은 사환들에게 돌아가 함께 브엘세바로 가서 거기서 살았어요.","t3":"여호와의 사자가 하늘에서 두 번째로 아브라함을 불러 여호와의 말씀을 전했다. 여호와께서는 자신을 가리켜 맹세하시며 그에게 큰 복을 주고 그의 씨를 하늘의 별과 바닷가의 모래처럼 크게 번성하게 하겠다고 하셨고, 그의 씨가 대적의 성문을 차지할 것이라고 하셨다. 그렇게 하시는 까닭과 천하 만민에 대해 하신 말씀, 그 뒤 아브라함이 간 곳은 16절, 18절, 19절에 있다."},"say":{"who":"hyu","text":"여호와의 사자가 아브라함을 다시 불렀대. 일지에 적어 둘게."}}],"gates":{"t1":[{"type":"find","ref":"창 22:4","prompt":"성경책에서 창세기 22장 4절을 찾아 읽어 보세요.","confirm":{"prompt":"아브라함이 하나님이 일러 주신 곳을 멀리서 보게 된 것은 며칠째 되는 날인가요?","options":[{"label":"사흘째 되는 날","ok":true},{"label":"이레째 되는 날","basis":"본문에 없음"},{"label":"사십 일째 되는 날","basis":"본문에 없음"}]}},{"type":"multi","ref":"창 22:3","prompt":"성경책에서 창세기 22장 3절을 찾아 읽어 보세요.","confirm":{"prompt":"아브라함이 아침 일찍 일어나 한 일을 모두 고르세요.","options":[{"label":"나귀에 안장을 얹었다","ok":true},{"label":"불과 칼을 챙겼다","basis":"창 22:6"},{"label":"두 사환과 이삭을 데리고 떠났다","ok":true},{"label":"우물을 팠다","basis":"창 21:30"},{"label":"나무를 쪼개어 챙겼다","ok":true}]}}],"t2":[{"type":"find","ref":"창 22:11-12","prompt":"성경책에서 창세기 22장 11절과 12절을 읽어 보세요.","confirm":{"prompt":"여호와의 사자가 아브라함이 하나님을 경외한다는 것을 이제 알겠다고 한 까닭은 무엇인가요?","options":[{"label":"아브라함이 아들, 곧 독자라도 아끼지 않았기 때문에","ok":true},{"label":"아브라함이 사자가 부르자 곧 여기 있다고 대답했기 때문에","basis":"창 22:11"},{"label":"아브라함이 사흘 동안 쉬지 않고 걸었기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"창 22:6-8","prompt":"성경책에서 창세기 22장 6절부터 8절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["아브라함이 번제 나무를 이삭에게 지우고 불과 칼을 들었다","이삭이 아버지를 부르자 아브라함이 여기 있다고 대답했다","이삭이 번제로 드릴 어린 양이 어디 있느냐고 물었다","아브라함이 하나님이 친히 준비하실 것이라고 대답했다"]}],"t3":[{"type":"find","refs":["창 22:5","창 22:19"],"prompt":"창세기 22장 5절과 19절을 함께 찾아 읽어 보자.","confirm":{"prompt":"아브라함이 산으로 가기 전에 사환들에게 한 말과 마지막에 한 일은 어떻게 이어지는가?","options":[{"label":"사환들에게 나귀와 함께 기다리라고 하며 아이와 함께 가서 경배하고 돌아오겠다고 했고, 마지막에 사환들에게 돌아와 함께 브엘세바로 갔다","ok":true},{"label":"사환들에게 나귀와 함께 기다리라고 하며 혼자 가서 번제할 어린 양을 구해 오겠다고 했고, 마지막에 사환들에게 돌아와 함께 브엘세바로 갔다","basis":"본문에 없음"},{"label":"사환들에게 나귀와 함께 기다리라고 하며 아이와 함께 가서 경배하고 돌아오겠다고 했고, 마지막에는 사환들을 그곳에 두고 모리아 산에 머물러 살았다","basis":"본문에 없음"}]}},{"type":"match","refs":["창 22:3","창 22:6","창 22:9"],"prompt":"창세기 22장 3절, 6절, 9절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"창 22:3","text":"아브라함이 나무를 쪼개어 챙긴 뒤 길을 떠났다"},{"ref":"창 22:6","text":"그 나무를 이삭이 지게 하고, 아브라함은 불과 칼을 들었다"},{"ref":"창 22:9","text":"일러 주신 곳에 이르러 제단을 쌓아 그 위에 나무를 벌여 두었다"}],"after":"세 곳을 이으면, 아브라함이 쪼개어 챙긴 나무를 이삭이 지고 갔고, 일러 주신 곳에서 아브라함이 제단을 쌓아 그 나무를 벌여 두었다."}]},"cards":[{"ref":"창 22:8","title":"하나님이 준비하시리라"},{"ref":"창 22:14","title":"여호와이레"}],"close":{"t1":{"kind":"prayer","text":"하나님, 모리아 땅의 산에서 있었던 일을 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 창세기 22장 1절부터 19절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"창 22:1-19에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 이번에는 타임머신 덮개를 묶는 끈이 끊어졌어요. 이 근처에서 대신 쓸 재료를 찾아봐요.","t2":"최현 박사예요. 착륙하면서 타임머신 덮개를 묶는 고정 끈이 끊어졌어요. 그 시대에는 부속이 없으니, 이 근처에서 얻을 수 있는 재료로 대신 만들어야 해요.","t3":"착륙하면서 타임머신 덮개를 묶는 고정 끈이 끊어졌다. 그 시대에는 부속이 없으니 이 근처에서 얻을 수 있는 재료로 대신 만들어야 한다. 사람들의 물건과 사건이 일어나는 자리에는 손대지 않아야 한다."},"materials":[{"key":"donkeyhair","name":"나귀 털","basis":"창 22:5","use":"나귀 털을 꼬아 만든 끈은 끊어진 고정 끈 대신 쓸 수 있어요.","how":"사환들이 나귀와 함께 기다리던 자리에서 땅에 떨어진 나귀 털을 줍는다. 나귀에게서 털을 뽑지 않고, 산 위 제단 쪽으로는 가지 않는다.","line":"사환들이 나귀와 함께 기다리던 곳에서 나귀 털을 주웠어."}],"companion":{"who":"아브라함","when":"after","ref":"창 22:19","talks":[{"ask":{"who":"onwoo","text":"하나님이 처음 부르셨을 때 뭐라고 대답하셨어요?"},"answer":{"t1":"아브라함은 자기가 여기 있다고 대답했어요.","t2":"하나님이 아브라함의 이름을 부르셨어요. 그때 아브라함은 자기가 여기 있다고 대답했어요.","t3":"하나님이 그의 이름을 부르셨을 때 아브라함은 자기가 여기 있다고 대답했다."},"ref":"창 22:1","open":"창 22:1"},{"ask":{"who":"hyu","text":"산으로 가기 전에 사환들에게 뭐라고 하셨어요?"},"answer":{"t1":"아브라함은 사환들에게 나귀와 같이 이곳에 있으라고 했어요. 자기는 아이와 저쪽으로 가서 경배한 뒤 돌아오겠다고 했어요.","t2":"아브라함은 사환들에게 나귀와 함께 이곳에서 기다리라고 했어요. 그리고 자기와 아이가 저쪽으로 가서 경배한 뒤 그들에게 돌아오겠다고 말했어요.","t3":"아브라함은 사환들에게 나귀와 함께 이곳에서 기다리라고 했다. 자기는 아이와 함께 저쪽으로 가서 경배한 뒤 그들에게 돌아오겠다고 말했다."},"ref":"창 22:5","open":"창 22:5"}]},"today":[{"q":"아브라함은 이삭을 사랑하지 않았던 거예요?","a":{"t1":"성경은 아브라함이 이삭을 사랑했다고 말해요. 하나님은 이삭을 아브라함이 사랑하는 외아들이라고 부르셨어요.","t2":"하나님은 아브라함에게 말씀하시면서 이삭을 아브라함이 사랑하는 외아들이라고 부르셨어요. 그 일을 하는 동안 아브라함의 마음이 어땠는지는 성경에 적혀 있지 않아요.","t3":"창 22:2에서 하나님은 이삭을 아브라함이 사랑하는 독자라고 부르셨다. 성경은 아브라함이 이삭을 사랑했다고 말하지만, 그 일을 하는 동안 아브라함의 마음이 어땠는지는 적지 않는다."},"refs":["창 22:2"]}],"help":{"who":"두 사환(나귀와 함께 그 자리에서 기다리는 사람들)","steps":[{"kind":"stay","after":1,"title":"사환들과 함께 기다리기","basis":"창 22:5","text":{"t1":"아브라함은 사환들에게 나귀 곁에서 이곳에 머물러 있으라고 했어요. 우리도 사환들과 함께 여기서 기다려요. 산 위로는 올라가지 않아요.","t2":"아브라함은 두 사환에게 나귀를 데리고 이 자리에 머물라고 했어요. 우리도 사환들 곁에서 함께 기다려요. 번제 나무와 불과 칼에는 손대지 않고, 산 위로도 올라가지 않아요.","t3":"아브라함은 사환들에게 나귀를 데리고 그 자리에 머물러 기다리라고 했다(22:5). 아브라함은 그곳을 멀리 바라본 뒤에 이 말을 했다(22:4-5). 탐험대도 사환들 곁에서 함께 기다린다. 번제 나무와 불과 칼에는 손대지 않고, 산 위로 올라가지 않는다."},"wait":"사환들과 함께 기다리기","say":{"who":"hyu","text":"우리는 사환들과 여기 있을 거야. 산 위로는 올라가지 않아."}},{"kind":"do","after":1,"title":"나귀 곁 지키기 · 사환들과 함께","basis":"창 22:5","text":{"t1":"우리는 사환들 곁에서 나귀가 있는 자리를 함께 지켜요. 번제 나무와 불과 칼은 만지지 않아요.","t2":"아브라함은 사환들에게 나귀와 함께 이곳에서 기다리라고 했어요. 우리는 사환들 곁에서 나귀가 있는 자리를 함께 지켜요. 번제 나무와 불과 칼에는 손대지 않아요.","t3":"사환들은 나귀와 함께 그 자리에서 기다리라는 말을 들었다(22:5). 탐험대는 사환들 곁에서 나귀가 있는 자리를 함께 지킨다. 번제 나무와 불과 칼에는 손대지 않고, 산 위로 가지 않는다."},"tasks":["나귀 곁에 서 있기","나귀가 멀리 가지 않게 지켜보기","사환들과 함께 자리 지키기"],"done":{"who":"choeon","text":"나귀도 사환들도 이 자리에 그대로 있어. 우리도 여기서 기다리자."}},{"kind":"ask","after":"gates","title":"모리아 산의 일은 무슨 뜻이에요?","basis":"창 22:12","by":"최현 박사","ask":{"who":"choeon","text":"모리아 산에서 있었던 일은 무슨 뜻이에요?"},"answer":{"t1":"성경은 처음부터 이 일이 하나님께서 아브라함에게 하신 시험이었다고 말해요. 여호와의 사자는 아브라함이 아들을 아끼지 않았으니, 그가 하나님을 경외한다는 것을 이제 알겠다고 했어요.","t2":"창세기 22장은 첫 절에서 이 일이 하나님께서 아브라함에게 하신 시험이라고 밝혀요(22:1). 여호와의 사자는 아브라함이 아들, 곧 독자라도 아끼지 않았으니 그가 하나님을 경외한다는 것을 이제 알겠다고 했어요(22:12). 그리고 사자는, 여호와께서 아브라함이 말씀을 따랐으므로 큰 복을 주시겠다고 하셨다고 전했어요(22:16-18).","t3":"창세기 22장은 첫 절에서 이 일이 하나님께서 아브라함에게 하신 시험이라고 밝힌다(22:1). 여호와의 사자는 아브라함이 아들, 곧 독자라도 아끼지 않았으니 그가 하나님을 경외한다는 것을 이제 알겠다고 했다(22:12). 사자는 두 번째로 불러 여호와의 말씀을 전했는데, 여호와께서는 아브라함이 이같이 행하여 독자를 아끼지 않았으므로 크게 복을 주시고 그의 씨로 말미암아 온 세상 민족이 복을 얻게 하겠다고 하셨으며, 이는 그가 여호와의 말씀을 따랐기 때문이라고 하셨다(22:15-18). 성경은 여기까지 말한다."},"read":{"t1":{"type":"find","ref":"창 22:12","prompt":"성경책에서 창세기 22장 12절을 찾아 읽어 보세요.","confirm":{"prompt":"여호와의 사자는 아브라함에게 그 아이에게 무엇을 하지 말라고 했나요?","options":[{"label":"손을 대지 말라고","ok":true},{"label":"산에서 내려가지 말라고","basis":"본문에 없음"},{"label":"나무를 더 모으지 말라고","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"창 22:17-18","prompt":"성경책에서 창세기 22장 17절과 18절을 읽어 보세요.","confirm":{"prompt":"여호와께서 천하 만민이 아브라함의 씨로 말미암아 복을 얻을 것이라고 하시며 말씀하신 까닭은 무엇인가요?","options":[{"label":"아브라함이 여호와의 말씀을 따랐기 때문에","ok":true},{"label":"아브라함이 큰 제단을 여러 개 쌓았기 때문에","basis":"본문에 없음"},{"label":"아브라함이 사환들을 잘 돌보았기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["창 22:1","창 22:12","창 22:18"],"prompt":"창세기 22장 1절, 12절, 18절을 함께 찾아 읽어 보자.","confirm":{"prompt":"모리아 산의 일이 어떤 일이었고, 사자와 여호와께서 그 일에 대해 무엇이라고 하셨다고 성경은 말하는가?","options":[{"label":"하나님께서 아브라함에게 하신 시험이었고, 사자는 그가 독자를 아끼지 않았으니 하나님을 경외한다는 것을 안다고 했으며, 여호와께서는 그가 말씀을 따랐으므로 그의 씨로 말미암아 온 세상 민족이 복을 얻으리라고 하셨다","ok":true},{"label":"하나님께서 아브라함에게 하신 시험이었고, 사자는 그가 제단을 정성껏 쌓았으니 하나님을 경외한다는 것을 안다고 했으며, 여호와께서는 그의 씨로 말미암아 온 세상 민족이 복을 얻으리라고 하셨다","basis":"본문에 없음"},{"label":"아브라함이 스스로 생각해 낸 일이었고, 하나님은 아무 말씀도 하지 않으셨다","basis":"본문에 없음"}]}}},"nt":{"ref":"히 11:17","text":"신약의 히브리서 11장 17절은, 시험을 받은 아브라함이 믿음으로 이삭을 바쳤으며 약속을 받은 사람이면서도 독생자를 드렸다고 말한다."}}]}},"has3d":false,"epic":false},"OT-07":{"id":"OT-07","era":2,"title":"벧엘에서 야곱이 꾼 꿈","ref":"창 28:10-22","place":"브엘세바에서 하란으로 가는 길의 한 곳, 벧엘(본래 이름은 루스)","review":{"required":false,"topics":[],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"창 28:10-11","focus":"jacob","text":{"t1":"야곱은 브엘세바를 떠나 하란으로 가다가, 어느 곳에서 해가 지자 누워 잤어요. 무엇을 베개로 삼았는지는 성경에서 찾아봐요.","t2":"야곱은 브엘세바를 떠나 하란을 향해 갔어요. 한 곳에 이르러 거기서 밤을 지냈는데, 왜 그곳에서 밤을 지냈는지는 11절에 있어요. 야곱은 그곳의 돌 하나를 가져다 베개로 삼고 누워 잤어요.","t3":"야곱은 브엘세바를 떠나 하란을 향해 갔다. 한 곳에 이르렀을 때 해가 졌으므로 거기서 밤을 지내려고 그 자리에 누워 잤다. 그가 무엇을 베개로 삼았는지는 11절에서 직접 읽어 보자."},"say":{"who":"hyu","text":"브엘세바에서 하란으로 가는 길이야. 일지에 적어 둘게."}},{"ref":"창 28:12","focus":"ladder","text":{"t1":"야곱은 꿈에서 사닥다리 하나를 보았어요. 그 사닥다리가 어떠했고 그 위에 무엇이 있었는지는 성경에서 찾아봐요.","t2":"야곱은 꿈을 꾸었어요. 꿈에 보니 사닥다리가 땅 위에 서 있고 그 꼭대기는 하늘에 닿아 있었어요. 하나님의 사자들이 그 사닥다리를 오르락내리락하고 있었어요.","t3":"그는 꿈을 꾸었다. 꿈에 보니 땅 위에 선 사닥다리의 꼭대기가 하늘에 닿아 있었고, 하나님의 사자들이 그 위를 오르락내리락하고 있었다."},"say":{"who":"choeon","text":"야곱이 꿈에서 사닥다리를 보았대!"}},{"ref":"창 28:13-14","open":"창 28:13-14","focus":"ladder","text":{"t1":"여호와께서 사닥다리 위에 서서 말씀하셨어요. 야곱이 누운 땅을 야곱과 그의 자손에게 주겠다고 하셨어요.","t2":"여호와께서 그 위에 서서, 자신이 아브라함의 하나님이며 이삭의 하나님이라고 하셨어요. 야곱이 누운 땅을 야곱과 그의 자손에게 주겠다고 하셨어요. 자손이 땅의 티끌처럼 되어 동서남북으로 퍼질 것이라고 하셨어요. 땅의 모든 족속이 무엇 때문에 복을 얻을 것이라고 하셨는지는 14절에 있어요.","t3":"여호와께서 그 위에 서서, 자신이 여호와이며 야곱의 조부 아브라함의 하나님이고 이삭의 하나님이라고 하셨다. 그의 자손이 땅의 티끌처럼 되어 동서남북으로 퍼져 나갈 것이며 땅의 모든 족속이 그와 그의 자손으로 말미암아 복을 얻을 것이라고 하셨다. 야곱이 누운 땅에 대해 하신 말씀은 13절에서 직접 읽어 보자."},"say":{"who":"onwoo","text":"하나님이 하신 말씀은 우리가 지어내면 안 돼. 13절과 14절을 성경책에서 직접 읽어 보자."}},{"ref":"창 28:15","open":"창 28:15","focus":"jacob","text":{"t1":"하나님은 야곱과 함께 있겠다고 하셨어요. 야곱이 어디로 가든지 지키고, 이 땅으로 돌아오게 하겠다고 하셨어요.","t2":"하나님은 야곱과 함께 있어 그가 어디로 가든지 지키고, 이 땅으로 돌아오게 하겠다고 하셨어요. 약속한 것을 다 이루기까지 야곱을 떠나지 않겠다고 하셨어요.","t3":"하나님은 야곱과 함께 있겠다고 하시며, 말씀하신 것을 다 이루기까지 그를 떠나지 않겠다고 하셨다. 함께 있으면서 그를 어떻게 하겠다고 하셨는지는 15절에서 직접 읽어 보자."},"say":{"who":"hyu","text":"15절의 약속을 일지에 적어 둘게."}},{"ref":"창 28:16-17","focus":"jacob","text":{"t1":"야곱이 잠에서 깨어, 여호와께서 여기 계신데 자기가 몰랐다고 말했어요. 그리고 두려워했어요.","t2":"야곱은 잠에서 깨어, 여호와께서 참으로 여기 계신데 자기가 알지 못했다고 말했어요. 야곱은 두려워하며, 이곳이 하나님의 집이요 하늘의 문이라고 말했어요.","t3":"야곱은 잠에서 깨어, 여호와께서 참으로 이곳에 계신데 자기가 알지 못했다고 말했다. 그는 두려워하며, 이곳은 두려운 곳이고 다름 아닌 하나님의 집이며 하늘의 문이라고 말했다."},"say":{"who":"choeon","text":"야곱이 잠에서 깼어. 두려워하고 있어."}},{"ref":"창 28:18-19","focus":"pillar","text":{"t1":"아침 일찍 야곱은 돌 하나를 세워 기둥으로 삼고 기름을 부었어요. 그리고 그곳 이름을 벧엘이라고 불렀어요.","t2":"야곱은 아침 일찍 일어나, 베개로 삼았던 돌을 가져다 기둥으로 세우고 그 위에 기름을 부었어요. 그곳 이름을 벧엘이라고 했어요. 그 성의 본래 이름은 루스였어요.","t3":"야곱은 아침 일찍 일어나 돌 하나를 기둥으로 세웠다. 그 돌이 어떤 돌이었고 그 위에 무엇을 했는지는 18절에 있다. 그리고 그곳 이름을 벧엘이라 하였다. 그 성의 본래 이름은 루스였다."},"say":{"who":"hyu","text":"야곱이 붙인 이름은 벧엘, 본래 이름은 루스. 둘 다 적어 둘게."}},{"ref":"창 28:20-22","focus":"pillar","text":{"t1":"야곱은 하나님께 서원했어요. 하나님이 함께 계셔서 지켜 주시고 아버지 집으로 평안히 돌아가게 하시면, 여호와께서 자기의 하나님이 되실 것이라고 했어요.","t2":"야곱은 하나님께 서원했어요. 무엇을 어떤 차례로 서원했는지는 20절부터 22절까지 읽어 봐요.","t3":"야곱은 서원하여 말했다. 하나님이 자기와 함께 계셔서 가는 길에서 지켜 주시고 먹을 양식과 입을 옷을 주셔서 평안히 아버지 집으로 돌아가게 하시면, 여호와께서 자기의 하나님이 되실 것이고, 기둥으로 세운 그 돌이 하나님의 집이 될 것이며, 하나님이 주신 모든 것에서 십분의 일을 반드시 하나님께 드리겠다고 했다."},"say":{"who":"onwoo","text":"야곱이 서원한 말은 20절부터 22절까지야. 성경책에서 끝까지 읽어 보자."}}],"gates":{"t1":[{"type":"find","ref":"창 28:11","prompt":"성경책에서 창세기 28장 11절을 찾아 읽어 보세요.","confirm":{"prompt":"야곱은 무엇을 베개로 삼아 누워 잤나요?","options":[{"label":"그곳에 있던 돌","ok":true},{"label":"둘둘 만 겉옷","basis":"본문에 없음"},{"label":"양털 뭉치","basis":"본문에 없음"}]}},{"type":"multi","ref":"창 28:12","prompt":"성경책에서 창세기 28장 12절을 찾아 읽어 보세요.","confirm":{"prompt":"야곱이 꿈에서 본 것을 모두 고르세요.","options":[{"label":"땅 위에 선 사닥다리","ok":true},{"label":"사닥다리를 올라가는 야곱","basis":"본문에 없음"},{"label":"하늘에 닿은 사닥다리 꼭대기","ok":true},{"label":"불이 붙은 떨기나무","basis":"출 3:2"},{"label":"오르락내리락하는 하나님의 사자들","ok":true}]},"inStory":"사닥다리라는 이름은 이야기에 나오지만, 그것이 땅 위에 서고 꼭대기가 하늘에 닿았으며 하나님의 사자들이 오르내린 일은 28:12에서만 안다(8~10세 대목 1의 글에서 뺐다)"}],"t2":[{"type":"find","ref":"창 28:10-11","prompt":"성경책에서 창세기 28장 10절과 11절을 읽어 보세요.","confirm":{"prompt":"야곱이 그곳에서 밤을 지내게 된 까닭은 무엇인가요?","options":[{"label":"그곳에 이르렀을 때 해가 졌기 때문에","ok":true},{"label":"하나님이 그곳에 머물라고 하셨기 때문에","basis":"본문에 없음"},{"label":"그곳에 친척의 집이 있었기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"창 28:20-22","prompt":"성경책에서 창세기 28장 20절부터 22절까지 읽고, 야곱이 서원한 말의 차례대로 눌러 보세요.","items":["하나님이 가는 길에서 지켜 주시면","먹을 것과 입을 것을 주시면","평안히 아버지 집으로 돌아가게 하시면","여호와께서 자기의 하나님이 되실 것이라고 했다","받은 모든 것의 십분의 일을 드리겠다고 했다"]}],"t3":[{"type":"find","refs":["창 28:11","창 28:18"],"prompt":"창세기 28장 11절과 18절을 함께 찾아 읽어 보자.","confirm":{"prompt":"야곱이 베개로 삼은 돌은 어디에 있던 것이고, 아침에 어떻게 되었는가?","options":[{"label":"그곳에 있던 돌 하나를 가져다 베개로 삼아 누워 잤고, 아침에는 그 돌을 세워 기둥으로 삼고 기름을 부었다","ok":true},{"label":"브엘세바에서부터 가지고 온 돌을 베개로 삼았고, 아침에 그 돌을 세워 기둥으로 삼았다","basis":"본문에 없음"},{"label":"그곳에 있던 돌을 베개로 삼았고, 아침에 그 돌로 여러 개의 제단을 쌓았다","basis":"본문에 없음"}]}},{"type":"match","refs":["창 28:17","창 28:19","창 28:22"],"prompt":"창세기 28장 17절, 19절, 22절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"창 28:17","text":"야곱이 두려워하며 이곳을 하나님의 집이요 하늘의 문이라고 했다"},{"ref":"창 28:19","text":"그곳을 벧엘이라 이름 지었고, 그 성은 본래 루스였다"},{"ref":"창 28:22","text":"세워 둔 돌기둥이 하나님의 집이 되리라 하고, 받은 모든 것의 십분의 일을 바치겠다고 했다"}],"after":"세 곳을 이으면, 야곱은 그곳을 하나님의 집이라 하고 벧엘이라 이름 지었으며, 세워 둔 돌이 하나님의 집이 되리라고 서원했다."}]},"cards":[{"ref":"창 28:15","title":"어디로 가든지 지키리라"},{"ref":"창 28:17","title":"하나님의 집, 하늘의 문"}],"close":{"t1":{"kind":"prayer","text":"하나님, 야곱에게 함께 있겠다고 하신 말씀을 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 창세기 28장 10절부터 22절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"창 28:10-22에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 타임머신 문 손잡이의 꼭지가 부러졌어요. 이 근처에서 대신 쓸 재료를 찾아봐요.","t2":"최현 박사예요. 착륙하면서 타임머신 문 손잡이의 꼭지가 부러졌어요. 그 시대에는 부속이 없으니, 이 근처에서 얻을 수 있는 재료로 대신 만들어야 해요.","t3":"착륙하면서 타임머신 문 손잡이의 꼭지가 부러졌다. 그 시대에는 부속이 없으니 이 근처에서 얻을 수 있는 재료로 대신 만들어야 한다. 사람들의 물건과 사건이 일어나는 자리에는 손대지 않아야 한다."},"materials":[{"key":"pebble","name":"작은 돌멩이","basis":"창 28:10","use":"손에 쥐기 좋은 둥근 돌멩이를 부러진 손잡이 꼭지 대신 쓸 수 있어요.","how":"야곱이 머문 곳에서 멀리 떨어진, 브엘세바 쪽에서 오는 길가에 굴러 있는 작은 돌멩이를 줍는다. 야곱이 누운 곳과, 기둥으로 세운 돌에는 가까이 가지 않는다.","line":"야곱이 머문 곳에서 멀리 떨어진, 브엘세바 쪽에서 오는 길가에서 작은 돌멩이를 주웠어."}],"companion":{"who":"야곱","when":"after","ref":"창 28:18","talks":[{"ask":{"who":"choeon","text":"잠에서 깨어나서 뭐라고 하셨어요?"},"answer":{"t1":"야곱은 여호와께서 정말 여기 계신데 자기가 몰랐다고 말했어요.","t2":"야곱은 잠에서 깨어났어요. 그리고 여호와께서 참으로 이곳에 계신데 자기가 그것을 알지 못했다고 말했어요.","t3":"야곱은 잠에서 깨어, 여호와께서 참으로 이곳에 계시는데 자기가 알지 못했다고 말했다."},"ref":"창 28:16","open":"창 28:16"},{"ask":{"who":"hyu","text":"이곳이 어떤 곳이라고 하셨어요?"},"answer":{"t1":"야곱은 두려워하며, 이곳이 하나님의 집이고 하늘의 문이라고 말했어요.","t2":"야곱은 두려워하며 이곳이 두려운 곳이라고 말했어요. 다름 아닌 하나님의 집이요 하늘의 문이라고 했어요.","t3":"야곱은 두려워하며, 이곳은 두려운 곳이고 다름 아닌 하나님의 집이며 하늘의 문이라고 말했다."},"ref":"창 28:17","open":"창 28:17"},{"ask":{"who":"onwoo","text":"하나님께 무엇을 서원하셨어요?"},"answer":{"t1":"야곱은 하나님이 함께 계셔서 지켜 주시고 아버지 집으로 평안히 돌아가게 하시면, 여호와께서 자기의 하나님이 되실 것이라고 서원했어요.","t2":"야곱은, 하나님이 함께 계셔서 가는 길에서 지켜 주시고 먹을 양식과 입을 옷을 주셔서 평안히 아버지 집으로 돌아가게 하시면 여호와께서 자기의 하나님이 되실 것이라고 서원했어요. 기둥으로 세운 돌이 하나님의 집이 될 것이고, 받은 모든 것의 십분의 일을 드리겠다고 했어요.","t3":"야곱은 하나님이 자기와 함께 계셔서 가는 길에서 지켜 주시고, 먹을 양식과 입을 옷을 주셔서 평안히 아버지 집으로 돌아가게 하시면 여호와께서 자기의 하나님이 되실 것이라고 서원했다. 또 기둥으로 세운 그 돌이 하나님의 집이 될 것이며, 하나님이 주신 모든 것에서 십분의 일을 반드시 하나님께 드리겠다고 했다."},"ref":"창 28:20-22","open":"창 28:20"}]},"today":[{"q":"하나님은 야곱에게 하신 약속을 지키셨어요?","a":{"t1":"하나님은 야곱과 함께 있으면서 지키고 이 땅으로 돌아오게 하겠다고 하셨어요. 나중에 야곱은 하나님이 자기가 가는 길에서 함께하셨다고 말했어요. 그리고 야곱은 벧엘로 다시 왔어요.","t2":"벧엘에서 하나님은 야곱과 함께 있어 어디로 가든지 지키고 이 땅으로 돌아오게 하겠다고 하셨어요. 나중에 야곱은 집안 사람들에게, 자기가 어려울 때 응답하시고 가는 길에서 함께하신 하나님께 벧엘에서 제단을 쌓겠다고 말했어요. 그리고 야곱은 가나안 땅의 루스, 곧 벧엘로 갔어요.","t3":"창 28:15에서 하나님은 야곱과 함께 있어 어디로 가든지 지키고 이 땅으로 돌아오게 하겠다고 하셨다. 창세기 35장에서 야곱은 자기 집 사람들에게, 환난 날에 자기에게 응답하시고 자기가 가는 길에서 함께하신 하나님께 벧엘에서 제단을 쌓겠다고 말했다(창 35:3). 그리고 야곱은 자기와 함께한 모든 사람과 함께 가나안 땅의 루스, 곧 벧엘로 갔다(창 35:6)."},"refs":["창 28:15","창 35:3","창 35:6"]}],"help":{"who":"야곱(깨우거나 말을 걸지 않고, 돌과 기둥에 손대지 않으며 멀리서 지켜본다. 우리 쉴 자리는 멀리 떨어진 곳에 따로 마련한다)","steps":[{"kind":"do","after":0,"title":"밤 지낼 자리 마련 · 멀리 떨어진 곳에","basis":"창 28:11","text":{"t1":"해가 졌어요. 우리는 야곱이 누운 곳에서 멀리 떨어진 곳에, 우리가 밤을 지낼 자리를 마련해요.","t2":"야곱이 그곳에서 밤을 지내요. 우리는 야곱을 깨우지 않도록, 멀리 떨어진 곳에 우리가 밤을 지낼 자리를 조용히 마련해요.","t3":"야곱이 그곳에 이르렀을 때 해가 졌다(28:11). 탐험대는 야곱이 누운 곳에서 멀리 떨어진 곳에, 우리가 밤을 지낼 자리를 조용히 마련한다."},"tasks":["멀리 떨어진 자리 고르기","우리 겉옷을 깔아 자리 펴기","타임머신 불빛 줄이기"],"done":{"who":"onwoo","text":"자리를 다 폈어. 야곱을 깨우지 않게 조용히 지내자."}},{"kind":"stay","after":0,"title":"그곳에서 함께 밤 지내기","basis":"창 28:11","text":{"t1":"해가 져서 야곱이 그곳에서 밤을 지내요. 우리도 멀리 떨어진 곳에서 조용히 밤을 지내요.","t2":"야곱은 그곳에서 돌을 베개로 삼고 누워 잤어요. 우리는 야곱을 깨우지 않고, 멀리 떨어진 곳에서 조용히 밤을 지내요.","t3":"야곱이 그곳에 이르렀을 때 해가 져서 거기서 밤을 지냈다(28:11). 탐험대는 야곱을 깨우지 않고, 그가 누운 자리 곁의 것에도 손대지 않으며, 멀리 떨어진 곳에서 조용히 밤을 지낸다."},"wait":"조용히 밤 지내기","say":{"who":"choeon","text":"우리도 여기서 조용히 밤을 지낼게."}},{"kind":"watch","after":5,"title":"멀리서 보기 · 기둥으로 세운 돌","basis":"창 28:18","text":{"t1":"아침에 야곱이 돌 하나를 기둥으로 세우고 기름을 부었어요. 우리는 손대지 않고 멀리서 지켜봐요.","t2":"야곱이 아침 일찍 일어나, 베개로 삼았던 돌을 세워 기둥으로 삼고 그 위에 기름을 부었어요. 이 일은 야곱이 했어요. 우리는 돌에 가까이 가지 않고 멀리서 지켜봐요.","t3":"야곱은 아침 일찍 일어나 돌 하나를 세워 기둥으로 삼았다. 본문은 이 일을 야곱이 했다고 적는다. 탐험대는 그 돌에 가까이 가지 않고 멀리서 지켜본다."},"say":{"who":"hyu","text":"아침에 세운 돌기둥. 18절에 적혀 있어. 일지에 적어 둘게."}},{"kind":"ask","after":"gates","title":"꿈에서 하신 말씀은 무슨 뜻이에요?","basis":"창 28:13-15","by":"최현 박사","ask":{"who":"choeon","text":"야곱이 꿈에서 본 사닥다리와 들은 말씀은 무슨 뜻이에요?"},"answer":{"t1":"성경은 꿈에서 여호와께서 야곱에게, 그가 누운 땅을 그와 자손에게 주겠다고 하셨다고 말해요. 그리고 야곱과 함께 있어 어디로 가든지 지키고 이 땅으로 돌아오게 하겠다고 하셨어요. 사닥다리가 무엇을 뜻하는지는 이 본문이 더 말하지 않아요.","t2":"성경은 여호와께서 사닥다리 위에 서서, 자신이 아브라함과 이삭의 하나님이라고 하셨다고 말해요(28:13). 야곱이 누운 땅을 그와 자손에게 주고, 그 자손이 땅의 티끌처럼 되어 사방으로 퍼지게 하겠다고 하셨어요(28:13-14). 또 야곱과 함께 있어 어디로 가든지 지키고 이 땅으로 돌아오게 하겠다고 하셨어요(28:15). 사닥다리가 무엇을 뜻하는지는 이 본문이 더 말하지 않아요.","t3":"성경은 여호와께서 사닥다리 위에 서서, 자신이 여호와이며 야곱의 할아버지 아브라함과 이삭의 하나님이라고 하셨다고 기록한다(28:13). 하나님은 야곱이 누운 땅을 그와 그의 자손에게 주고, 자손이 땅의 티끌처럼 되어 사방으로 퍼지며 땅의 모든 족속이 그와 그의 자손으로 말미암아 복을 얻으리라고 하셨다(28:13-14). 또 야곱과 함께 있어 어디로 가든지 그를 지키고 이 땅으로 데려오며, 말씀하신 것을 다 이루기까지 떠나지 않겠다고 하셨다(28:15). 사닥다리와 그 위를 오르내린 하나님의 사자들이 무엇을 뜻하는지는 이 본문이 더 말하지 않는다."},"read":{"t1":{"type":"find","ref":"창 28:13","prompt":"성경책에서 창세기 28장 13절을 찾아 읽어 보세요.","confirm":{"prompt":"여호와께서는 자신을 누구의 하나님이라고 하셨나요?","options":[{"label":"아브라함과 이삭의 하나님","ok":true},{"label":"모세와 아론의 하나님","basis":"본문에 없음"},{"label":"요셉과 베냐민의 하나님","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"창 28:13-14","prompt":"성경책에서 창세기 28장 13절과 14절을 읽어 보세요.","confirm":{"prompt":"하나님은 땅의 모든 족속이 무엇 때문에 복을 얻을 것이라고 하셨나요?","options":[{"label":"야곱과 그 후손으로 말미암아","ok":true},{"label":"아브라함 한 사람으로 말미암아","basis":"창 12:3"},{"label":"그들이 벧엘에 와서 제사를 드렸기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["창 28:13","창 28:15"],"prompt":"창세기 28장 13절과 15절을 함께 찾아 읽어 보자.","confirm":{"prompt":"하나님은 야곱이 누운 땅과 야곱이 떠나는 길에 대해 무엇을 약속하셨는가?","options":[{"label":"야곱이 누운 땅을 그와 자손에게 주겠다고 하셨고, 어디로 가든지 그를 지키며 이 땅으로 다시 이끌어 오겠다고 하셨다","ok":true},{"label":"야곱이 누운 땅을 그와 자손에게 주겠다고 하셨고, 가는 길에서 먹을 것과 입을 것을 주겠다고 하셨다","basis":"창 28:20"},{"label":"그 땅에 대해서는 아무 말씀이 없으셨고, 야곱이 다시는 이 땅에 돌아오지 못할 것이라고 하셨다","basis":"본문에 없음"}]}}}}]}},"has3d":false,"epic":false},"OT-08":{"id":"OT-08","era":2,"title":"요셉이 애굽으로 팔려 가고 형들을 다시 만남","ref":"창 37:12-36","place":"헤브론 골짜기, 세겜, 도단, 애굽","review":{"required":true,"topics":["하나님의 주권과 사람의 책임(창 45:5-8)","구약 사건의 신약적 의미(행 7:9-10)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"창 37:12-17","focus":"joseph","text":{"t1":"아버지는 요셉에게, 세겜에서 양 떼를 치는 형들이 잘 있는지 보고 오라고 했어요. 요셉은 형들을 찾아 도단까지 갔어요.","t2":"형들이 세겜에서 아버지의 양 떼를 칠 때, 아버지 이스라엘은 요셉에게 형들과 양 떼가 잘 있는지 보고 와서 알려 달라고 했어요. 요셉은 헤브론 골짜기를 떠나 세겜으로 갔어요. 들에서 헤매던 요셉은 어떤 사람에게서 형들이 도단으로 가자고 하더라는 말을 듣고, 뒤따라가 도단에서 형들을 만났어요.","t3":"형들이 세겜에 가서 아버지의 양 떼를 칠 때, 이스라엘은 요셉을 형들에게 보내며 형들과 양 떼가 잘 있는지 보고 돌아와 알리라고 했다. 요셉은 헤브론 골짜기에서 떠나 세겜으로 갔다. 그가 들에서 헤매고 있을 때 어떤 사람이 무엇을 찾느냐고 물었고, 요셉은 형들을 찾고 있으니 양 치는 곳을 알려 달라고 했다. 그 사람은 형들이 도단으로 가자고 하는 말을 들었다고 했고, 요셉은 형들을 뒤따라가 도단에서 그들을 만났다."},"say":{"who":"hyu","text":"헤브론 골짜기에서 세겜으로, 세겜에서 도단으로. 요셉이 간 길을 적어 둘게. 성경은 요셉의 아버지를 37장 1절에서는 야곱, 13절에서는 이스라엘이라고 불러."}},{"ref":"창 37:18-22","focus":"brothers","text":{"t1":"형들은 멀리서 요셉이 오는 것을 보고 요셉을 해치려고 꾀했어요. 르우벤은 요셉을 구해 내려고, 해치지 말자고 말했어요.","t2":"요셉이 가까이 오기 전에 형들은 멀리서 그를 보고 죽이려고 꾀했어요. 꿈꾸는 자가 온다고 서로 말했어요. 르우벤은 그 말을 듣고, 죽이지 말고 광야의 구덩이에 던지자고 했어요. 르우벤이 왜 그렇게 말했는지는 21절과 22절에 있어요.","t3":"요셉이 가까이 오기 전에 형들은 멀리서 그를 보고 죽이기를 꾀했다. 그들은 꿈꾸는 자가 온다고 서로 말하며, 그를 죽여 구덩이에 던지자고 했다. 그 뒤에 무엇이라고 말하자고 꾀했는지는 20절에서 직접 읽어 보자. 르우벤은 이 말을 듣고 요셉을 그들의 손에서 건져 내려고, 그의 생명을 해치지 말자고 했다. 피를 흘리지 말고 광야에 있는 구덩이에 던지되 손은 대지 말라고 했는데, 이는 요셉을 건져 아버지에게 돌려보내려는 것이었다."},"say":{"who":"onwoo","text":"형들이 한 말과 르우벤이 한 말은 19절부터 22절에 있어. 성경책에서 확인하자."}},{"ref":"창 37:23-24","focus":"pit","text":{"t1":"형들은 요셉이 입은 채색옷을 벗기고, 요셉을 어딘가에 던졌어요. 그곳이 어떤 곳이었는지는 성경에서 찾아봐요.","t2":"요셉이 형들에게 이르자, 형들은 요셉이 입고 있던 채색옷을 벗겼어요. 그리고 그를 붙잡아 구덩이에 던졌어요. 그 구덩이는 빈 구덩이여서 안에 물이 없었어요.","t3":"요셉이 형들에게 이르자 형들은 그가 입고 있던 채색옷을 벗기고, 그를 붙잡아 구덩이에 던졌다. 그 구덩이는 비어 있어서 안에 물이 없었다."},"say":{"who":"choeon","text":"형들이 요셉의 채색옷을 벗겼어!"}},{"ref":"창 37:25-28","focus":"caravan","text":{"t1":"유다가 지나가던 이스마엘 사람들에게 요셉을 팔자고 했어요. 요셉은 은 스무 개에 팔려 애굽으로 가게 되었어요.","t2":"형들이 앉아 음식을 먹다가 눈을 들어 보니, 이스마엘 사람들의 무리가 길르앗에서 오고 있었어요. 낙타에는 향품과 유향과 몰약이 실려 있었고, 그들은 애굽으로 내려가는 길이었어요. 유다는 동생을 죽이지 말고 이스마엘 사람들에게 팔자고 했고, 형제들이 그 말을 따랐어요. 미디안 상인들이 지나갈 때 요셉은 구덩이에서 끌어올려져 은 스무 개에 이스마엘 사람들에게 팔렸고, 그 상인들은 요셉을 데리고 애굽으로 갔어요.","t3":"그들이 앉아 음식을 먹다가 눈을 들어 보니, 이스마엘 사람들의 무리가 길르앗에서 오고 있었다. 낙타에는 향품과 유향과 몰약이 실려 있었고, 그들은 애굽으로 내려가는 길이었다. 유다는 형제들에게, 동생을 죽이고 그 피를 감춘들 무슨 유익이 있겠느냐며 그를 이스마엘 사람들에게 팔고 손을 대지 말자고 했다. 요셉이 자기들의 동생이요 혈육이라는 것이었다. 형제들은 그 말을 따랐다. 그때 미디안 사람 상인들이 지나갔고, 요셉은 구덩이에서 끌어올려져 이스마엘 사람들에게 팔렸으며, 상인들은 그를 데리고 애굽으로 갔다. 얼마에 팔렸는지는 28절에 있다."},"say":{"who":"hyu","text":"길르앗에서 와서 애굽으로 가는 사람들이야. 일지에 적어 둘게."}},{"ref":"창 37:29-36","focus":"coat","text":{"t1":"형들은 요셉의 옷을 숫염소의 피에 적셔 아버지에게 가져갔고, 아버지는 오랫동안 슬퍼했어요. 요셉은 애굽에서 바로의 신하 보디발에게 팔렸어요.","t2":"르우벤이 구덩이에 돌아와 보니 요셉이 없었어요. 그 뒤 르우벤과 형들과 아버지 야곱이 한 일의 차례는 29절부터 34절까지 읽어 봐요. 미디안 사람들은 애굽에서 요셉을 바로의 신하 보디발에게 팔았어요.","t3":"르우벤이 구덩이에 돌아와 보니 요셉이 없었다. 그는 옷을 찢고 아우들에게 가서, 아이가 없으니 자기는 어디로 가야 하느냐고 말했다. 그들은 숫염소를 잡아 요셉의 옷을 그 피에 적시고, 그 채색옷을 아버지에게 가져가 아들의 옷인지 보라고 했다. 아버지는 그것을 알아보았고, 그때 한 말은 33절에서 직접 읽어 보자. 야곱은 자기 옷을 찢고 굵은 베를 허리에 두르고 오랫동안 아들을 위해 애통했으며, 모든 자녀가 위로해도 받아들이지 않고 울었다. 한편 미디안 사람들은 애굽에서 요셉을 바로의 신하 보디발에게 팔았다."},"say":{"who":"choeon","text":"요셉의 옷이 아버지에게 갔어."}},{"ref":"창 45:1-4","focus":"joseph","text":{"t1":"애굽에서 요셉은 형들에게 자기가 누구인지 알리며 큰 소리로 울었어요. 형들은 놀라서 대답하지 못했어요.","t2":"요셉은 곁에 선 사람들 앞에서 마음을 누를 수 없어, 모든 사람을 물러가게 했어요. 그리고 형들에게 자기를 알리며 큰 소리로 울었고, 그 소리가 애굽 사람들과 바로의 궁에 들렸어요. 요셉은 자기가 요셉이라고 말하고 아버지가 아직 살아 계신지 물었지만, 형들은 놀라서 대답하지 못했어요. 요셉은 형들을 가까이 오게 하고, 자기가 형들이 애굽에 판 아우 요셉이라고 말했어요.","t3":"요셉은 곁에서 시중드는 사람들 앞에서 자기 마음을 누르지 못하고, 소리를 질러 모든 사람을 자기 앞에서 물러가게 했다. 그가 형제들에게 자기를 알릴 때 그와 함께 있는 사람은 아무도 없었다. 요셉이 큰 소리로 우니 애굽 사람들에게 들렸고 바로의 궁에도 들렸다. 요셉은 형들에게 자기가 요셉이라고 말하고 아버지가 아직 살아 계신지 물었으나, 형들은 그 앞에서 놀라 대답하지 못했다. 요셉은 형들에게 가까이 오라고 했고, 그들이 가까이 오자 자기를 다시 밝혔다. 그때 한 말은 4절에서 직접 읽어 보자."},"say":{"who":"hyu","text":"여기부터는 창세기 45장, 애굽이야. 37장과 45장 사이의 일은 성경책 38장부터 44장에 적혀 있어."}},{"ref":"창 45:5-8","open":"창 45:5-8","focus":"joseph","text":{"t1":"요셉은 형들에게, 자기를 이곳에 판 일로 근심하지 말라고 했어요. 하나님이 생명을 구하시려고 자기를 형들보다 먼저 보내셨다고 말했어요.","t2":"요셉은 형들에게, 자기를 이곳에 판 일로 근심하지도 한탄하지도 말라고 했어요. 흉년이 이 년 동안 있었고 아직 다섯 해가 남았다고 했어요. 요셉이 왜 근심하지 말라고 했고, 자기를 이리로 보낸 이가 누구라고 했는지는 5절부터 8절까지에 있어요.","t3":"요셉은 형들에게, 자기를 이곳에 팔았다고 해서 근심하지도 한탄하지도 말라고 했다. 하나님이 생명을 구원하시려고 자기를 형들보다 앞서 보내셨다고 말했다. 그는 이 땅에 흉년이 든 지 이 년이 되었고 앞으로 다섯 해 동안은 밭을 갈지도 거두지도 못할 것이라고 했다. 또 하나님이 큰 구원으로 형들의 생명을 보존하고 그들의 후손을 세상에 남기시려고 자기를 앞서 보내셨다고 말했다. 그러면서 자기를 이리로 보낸 이가 누구라고 했는지는 8절에서 직접 읽어 보자. 하나님이 자기를 바로의 아버지로, 바로의 온 집의 주로, 애굽 온 땅을 다스리는 사람으로 삼으셨다고도 말했다."},"say":{"who":"onwoo","text":"이 대목은 요셉이 형들에게 한 말이야. 5절부터 8절까지 성경책에서 한 절씩 읽어 보자."}},{"ref":"창 45:9-15","focus":"brothers","text":{"t1":"요셉은 형들에게 어서 아버지를 모시고 오라고 했어요. 요셉이 아우 베냐민을 안고 울고 형들과도 입 맞추며 울자, 그 뒤에야 형들이 요셉과 말했어요.","t2":"요셉은 형들에게, 서둘러 아버지께 올라가서 하나님이 자기를 애굽 온 나라의 주로 세우셨다고 전하라고 했어요. 아버지와 온 가족이 고센 땅에 살며 자기와 가까이 있게 하고, 남은 다섯 해의 흉년 동안 자기가 아버지를 봉양하겠다고 했어요. 요셉은 아우 베냐민의 목을 안고 울었고 베냐민도 울었어요. 요셉이 형들과도 입 맞추며 안고 우니, 그제야 형들이 요셉과 말했어요.","t3":"요셉은 형들에게 속히 아버지께 올라가서, 하나님이 자기를 애굽 온 나라의 주로 세우셨으니 지체하지 말고 내려오시라는 말을 전하라고 했다. 아버지와 그 아들들과 손자들, 양 떼와 소 떼와 모든 소유가 고센 땅에 머물러 자기와 가까이 있게 하고, 흉년이 아직 다섯 해 남았으니 거기서 자기가 아버지를 봉양하겠다고 했다. 그는 지금 말하는 것이 자기 입임을 형들과 아우 베냐민이 눈으로 보고 있다고 했고, 애굽에서 자기가 누리는 영화와 형들이 본 모든 것을 아버지께 알리고 속히 모시고 내려오라고 했다. 요셉이 아우 베냐민의 목을 안고 울자 베냐민도 요셉의 목을 안고 울었다. 요셉은 형들과도 입 맞추고 그들을 안고 울었으며, 그 뒤에야 형들이 요셉과 말을 나누었다."},"say":{"who":"choeon","text":"요셉이 베냐민의 목을 안고 울었대. 형들도 그제야 요셉과 말했대."}}],"gates":{"t1":[{"type":"find","ref":"창 37:24","prompt":"성경책에서 창세기 37장 24절을 찾아 읽어 보세요.","confirm":{"prompt":"형들은 요셉을 어디에 던졌나요?","options":[{"label":"물이 없는 빈 구덩이","ok":true},{"label":"물살이 센 강","basis":"본문에 없음"},{"label":"사자가 있는 굴","basis":"단 6:16"}]}},{"type":"multi","ref":"창 37:25","prompt":"성경책에서 창세기 37장 25절을 찾아 읽어 보세요.","confirm":{"prompt":"이스마엘 사람들이 낙타에 싣고 가던 것을 모두 고르세요.","options":[{"label":"향품","ok":true},{"label":"곡식","basis":"창 42:25"},{"label":"유향","ok":true},{"label":"양털","basis":"본문에 없음"},{"label":"몰약","ok":true}]}}],"t2":[{"type":"find","ref":"창 37:21-22","prompt":"성경책에서 창세기 37장 21절과 22절을 읽어 보세요.","confirm":{"prompt":"르우벤이 요셉을 광야의 구덩이에 던지자고 한 까닭은 무엇인가요?","options":[{"label":"요셉을 형들의 손에서 건져 아버지에게 돌려보내려고","ok":true},{"label":"요셉을 며칠 동안 구덩이에 두어 형들에게 잘못을 빌게 하려고","basis":"본문에 없음"},{"label":"요셉을 구덩이에 가두어 꿈 이야기를 다시는 못 하게 하려고","basis":"본문에 없음"}]}},{"type":"order","ref":"창 37:29-34","prompt":"성경책에서 창세기 37장 29절부터 34절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["르우벤이 요셉이 없는 것을 보고 자기 옷을 찢었다","형들이 숫염소의 피에 요셉의 옷을 적셨다","형들이 그 옷을 아버지에게 보내 알아보게 했다","아버지가 그 옷을 알아보고 아들의 옷이라고 했다","아버지가 자기 옷을 찢고 오래도록 애통했다"]}],"t3":[{"type":"find","refs":["창 37:20","창 37:33"],"prompt":"창세기 37장 20절과 33절을 함께 찾아 읽어 보자.","confirm":{"prompt":"형들이 요셉을 두고 꾀한 말과, 옷을 본 아버지가 한 말은 어떻게 이어지는가?","options":[{"label":"형들은 악한 짐승이 요셉을 잡아먹었다고 말하자고 꾀했고, 아버지는 형들이 보낸 그 옷을 알아보고 악한 짐승이 아들을 먹었다고 말했다","ok":true},{"label":"형들은 강도들이 요셉을 해쳤다고 말하자고 꾀했고, 아버지는 그 옷을 알아보고 강도들이 아들을 해쳤다고 말했다","basis":"본문에 없음"},{"label":"아버지는 옷을 보고 요셉이 살아 있다고 말했다","basis":"본문에 없음"}]}},{"type":"match","refs":["창 37:23","창 37:29","창 37:34"],"prompt":"창세기 37장 23절, 29절, 34절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"창 37:23","text":"형들이 요셉에게서 채색옷을 벗겼다"},{"ref":"창 37:29","text":"르우벤이 구덩이로 돌아와 보니 요셉이 없어서 옷을 찢었다"},{"ref":"창 37:34","text":"아버지 야곱이 옷을 찢고 굵은 베를 두른 채 오래도록 슬퍼했다"}],"after":"세 곳을 이으면, 형들이 요셉의 채색옷을 벗겼고, 요셉이 없어진 것을 안 르우벤과 그 옷을 알아본 아버지가 저마다 자기 옷을 찢었다."}]},"cards":[{"ref":"창 37:28","title":"은 이십에 팔려 애굽으로"},{"ref":"창 45:5","title":"요셉이 형들에게 한 말"}],"close":{"t1":{"kind":"prayer","text":"하나님, 요셉과 형들의 이야기를 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 창세기 45장 1절부터 15절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"창 37:12-36과 창 45:1-15에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 타임머신의 흔들림을 막는 완충 고무가 닳아 버렸어요. 이 근처에서 대신 쓸 재료를 찾아봐요.","t2":"최현 박사예요. 착륙하면서 흔들림을 막아 주는 완충 고무가 닳아 버렸어요. 그 시대에는 부속이 없으니, 이 근처에서 얻을 수 있는 재료로 대신 만들어야 해요.","t3":"착륙하면서 흔들림을 막아 주는 완충 고무가 닳아 버렸다. 그 시대에는 부속이 없으니 이 근처에서 얻을 수 있는 재료로 대신 만들어야 한다. 사람들의 물건과 사건이 일어나는 자리에는 손대지 않아야 한다."},"materials":[{"key":"wool","name":"양털","basis":"창 37:12","use":"양털을 단단히 뭉치면 닳아 버린 완충 고무 대신 쓸 수 있어요.","how":"형들이 아버지의 양 떼를 치던 세겜의 들에서 땅에 떨어진 양털 뭉치를 줍는다. 양에게서 털을 뜯지 않는다.","line":"형들이 양 떼를 치던 세겜의 들에서 양털 뭉치를 주웠어."}],"companion":{"who":"요셉","when":"after","ref":"창 45:1","talks":[{"ask":{"who":"hyu","text":"형들을 찾아 들에서 헤매실 때, 만난 사람에게 뭐라고 하셨어요?"},"answer":{"t1":"요셉은 형들을 찾고 있다고 했어요. 형들이 양 치는 곳을 알려 달라고 했어요.","t2":"요셉은 그 사람에게 자기가 형들을 찾고 있다고 말했어요. 그리고 형들이 양 떼를 치는 곳을 가르쳐 달라고 부탁했어요.","t3":"요셉은 그 사람에게, 자기가 형들을 찾고 있으니 그들이 양을 치는 곳을 가르쳐 달라고 부탁했다."},"ref":"창 37:16","open":"창 37:16"},{"ask":{"who":"choeon","text":"형들에게 자기가 요셉이라고 밝히고 나서 무엇을 물으셨어요?"},"answer":{"t1":"요셉은 아버지가 아직 살아 계시냐고 물었어요.","t2":"요셉은 형들에게 자기가 요셉이라고 말했어요. 그리고 아버지가 아직 살아 계시냐고 물었어요.","t3":"요셉은 형들에게 자기가 요셉이라고 밝히고, 아버지가 아직 살아 계시느냐고 물었다."},"ref":"창 45:3","open":"창 45:3"},{"ask":{"who":"onwoo","text":"아버지와 가족이 어디에서 살게 하겠다고 하셨어요?"},"answer":{"t1":"요셉은 형들에게, 아버지께 고센 땅에서 자기 가까이 사시라고 전하라고 했어요. 흉년이 다섯 해 더 남았으니 거기서 아버지를 봉양하겠다고 했어요.","t2":"요셉은 형들에게, 아버지께 아들들과 손자들과 양과 소와 모든 소유와 함께 고센 땅에 살며 자기 가까이 계시라고 전하라고 했어요. 흉년이 아직 다섯 해 남았으니, 거기서 자기가 아버지를 봉양하겠다고 했어요.","t3":"요셉은 형들에게, 아버지께 아들들과 손자들과 양 떼와 소 떼와 모든 소유와 함께 고센 땅에 머물러 자기와 가까이 있으시라는 말을 전하게 했다. 흉년이 아직 다섯 해 남았으니 거기서 자기가 아버지를 봉양하겠다고 했고, 아버지와 온 집안과 모든 소유가 궁핍해지지 않게 하려는 것이라고 했다."},"ref":"창 45:10-11","open":"창 45:10"}]},"today":[{"q":"요셉은 자기를 판 형들이 밉지 않았을까요?","a":{"t1":"성경은 요셉의 속마음을 다 적지 않아요. 요셉은 마음을 누르지 못하고 소리 내어 울었어요. 그리고 형들과 입 맞추며 안고 울었어요.","t2":"성경은 요셉이 형들을 어떻게 생각했는지 다 적지 않아요. 다만 요셉이 마음을 누르지 못해 소리 내어 울었고, 형들에게 가까이 오라고 했고, 형들과 입 맞추며 안고 울었다고 적어요.","t3":"성경은 요셉이 형들을 미워했는지 말하지 않는다. 요셉이 곁에 선 사람들 앞에서 마음을 누르지 못해 그들을 모두 물러가게 한 뒤 소리 내어 울었고(창 45:1-2), 형들에게 가까이 오라고 했으며(창 45:4), 형들과 입 맞추고 안고 울었다고 적는다(창 45:15). 성경은 여기까지 말한다."},"refs":["창 45:1-2","창 45:4","창 45:15"]},{"q":"아버지 야곱은 요셉이 살아 있다는 것을 알게 되었어요?","a":{"t1":"형들이 아버지께 요셉이 살아 있다고 전했어요. 야곱은 처음에는 믿지 않다가, 요셉이 보낸 수레를 보고 기운을 차렸어요. 나중에 야곱은 고센에서 요셉을 만났어요.","t2":"형들은 가나안 땅으로 돌아가 아버지 야곱에게 요셉이 살아 있고 애굽 땅의 총리가 되었다고 전했어요. 야곱은 그 말을 믿지 못했지만, 자기를 데려가려고 요셉이 보낸 수레를 보고 기운을 되찾았어요. 야곱은 가서 요셉을 보겠다고 했고, 나중에 고센에서 요셉을 만났어요. 요셉은 아버지의 목을 안고 한참 울었어요.","t3":"형들은 가나안 땅으로 돌아가 아버지 야곱에게 요셉이 살아 있으며 애굽 땅의 총리가 되었다고 전했다. 야곱은 그 말을 믿지 못했으나, 요셉이 전한 말을 듣고, 자기를 데려가려고 요셉이 보낸 수레를 보고서야 기운을 되찾았다(창 45:25-27). 그는 죽기 전에 가서 아들을 보겠다고 했다(창 45:28). 나중에 요셉은 고센으로 올라가 아버지를 맞았고, 아버지의 목을 안고 한참 울었다(창 46:29)."},"refs":["창 45:25-28","창 46:29"]}],"help":{"who":"요셉 곁에서 시중들던 사람들(창 45:1). 37장의 일은 돕지 않는다. 45장에서는 그 사람들과 함께 물러나 밖에서 기다린다","steps":[{"kind":"do","after":5,"title":"함께 물러나기 · 시중들던 사람들과","basis":"창 45:1","text":{"t1":"요셉이 모든 사람을 물러가라고 했을 때, 우리는 시중들던 사람들 곁에서 함께 밖으로 물러났어요.","t2":"요셉은 곁에서 시중들던 사람들 앞에서 마음을 누르지 못하고, 모든 사람을 물러가게 했어요. 우리는 시중들던 사람들 곁에서, 물러가는 그들에게 길을 비켜 주며 함께 밖으로 물러났어요.","t3":"요셉은 시중드는 이들 앞에서 마음을 억누르지 못해 모든 사람을 자기 앞에서 물러가게 했다(45:1). 탐험대는 시중들던 사람들 곁에서, 물러가는 그들에게 길을 비켜 주며 함께 밖으로 물러났다. 그래서 요셉이 형제들에게 자기를 알릴 때 탐험대는 그 자리에 없었다."},"tasks":["물러가는 사람들에게 길 터 주기","시중들던 사람들과 함께 밖으로 나가기","밖에서 조용히 자리 잡기"],"done":{"who":"onwoo","text":"다 같이 밖으로 나왔어. 그때 요셉과 함께 있던 사람이 없었다는 건 45장 1절에 적혀 있어."}},{"kind":"stay","after":5,"title":"물러간 사람들과 함께 밖에서","basis":"창 45:1-2","text":{"t1":"요셉이 모든 사람을 자기 앞에서 물러가게 했어요. 우리도 물러난 사람들과 함께 밖에서 기다려요. 요셉이 우는 소리가 밖에까지 들렸어요.","t2":"요셉은 형제들에게 자기를 알릴 때, 모든 사람을 자기 앞에서 물러가게 했어요. 그래서 그 자리에는 요셉과 형제들만 있었어요. 우리도 물러난 사람들과 함께 밖에서 기다려요. 요셉이 크게 우는 소리가 애굽 사람들에게까지 들렸어요.","t3":"요셉은 모든 사람을 자기 앞에서 물러가게 한 뒤 형제들에게 자기를 알렸고, 그때 그와 함께 있는 사람은 아무도 없었다(45:1). 탐험대도 물러난 사람들과 함께 밖에서 기다린다. 요셉이 크게 우는 소리가 애굽 사람들에게 들렸고 바로의 궁에도 들렸다(45:2)."},"wait":"밖에서 함께 기다리기","say":{"who":"choeon","text":"우리는 밖에서 기다리고 있어. 안에는 요셉과 형제들만 있어."}},{"kind":"ask","after":"gates","title":"요셉이 팔려 간 일은 무슨 뜻이에요?","basis":"창 45:5-8","by":"요셉","ask":{"who":"hyu","text":"형들에게 팔려 애굽에 오신 일은 무슨 뜻이에요?"},"answer":{"t1":"요셉은 형들에게, 자기를 이곳에 팔았다고 근심하지 말라고 말했어요. 하나님이 생명을 살리시려고 자기를 형들보다 먼저 보내셨다고 했어요.","t2":"요셉은 형들에게, 자기를 이곳에 팔았다고 해서 근심하지도 한탄하지도 말라고 말했어요. 하나님이 생명을 살리시려고 자기를 형들보다 앞서 보내셨다고 했어요(45:5). 그리고 자기를 이리로 보낸 이는 형들이 아니라 하나님이시라고 말했어요(45:8).","t3":"요셉은 형들에게, 자기를 이곳에 팔았다고 근심하지도 한탄하지도 말라고 했다. 하나님이 생명을 살리시려고 자기를 형들보다 앞서 보내셨다는 것이다(45:5). 또 큰 구원으로 형들을 살리고 그 후손을 세상에 남기시려고 하나님이 자기를 앞서 보내셨다고 했고(45:7), 그러므로 자기를 이리로 보낸 이는 형들이 아니라 하나님이시며, 하나님이 자기를 바로의 아버지와 그 온 집의 주와 애굽 온 땅을 다스리는 사람으로 삼으셨다고 말했다(45:8). 요셉이 한 말은 여기까지다."},"read":{"t1":{"type":"find","ref":"창 45:7","prompt":"성경책에서 창세기 45장 7절을 찾아 읽어 보세요.","confirm":{"prompt":"요셉은 하나님이 누구의 생명을 보존하시려고 자기를 앞서 보내셨다고 말했나요?","options":[{"label":"형들의 생명","ok":true},{"label":"바로의 생명","basis":"본문에 없음"},{"label":"아버지 야곱의 생명","basis":"본문에 없음"}]},"inStory":"'형들'은 이야기 내내 나오는 말이라 겹칠 뿐이고, 하나님이 누구의 생명을 보존하시려고 요셉을 보내셨는지는 45:7에서만 안다(8~10세 대목 6의 글은 '생명'만 말한다)"},"t2":{"type":"find","ref":"창 45:5-8","prompt":"성경책에서 창세기 45장 5절부터 8절까지 읽어 보세요.","confirm":{"prompt":"요셉이 형들에게 근심하지도 한탄하지도 말라고 한 까닭은 무엇인가요?","options":[{"label":"하나님이 생명을 살리시려고 자기를 형들보다 앞서 보내셨기 때문에","ok":true},{"label":"유다가 베냐민 대신 자기가 종이 되겠다고 했기 때문에","basis":"창 44:33"},{"label":"바로가 형들의 잘못을 묻지 말고 모두 용서하라고 명했기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["창 37:28","창 45:4","창 45:8"],"prompt":"창세기 37장 28절, 45장 4절, 8절을 함께 찾아 읽어 보자.","confirm":{"prompt":"요셉이 애굽에 오게 된 일에 대해 성경과 요셉은 무엇이라고 말하는가?","options":[{"label":"요셉은 은 이십에 팔려 애굽으로 갔고, 요셉도 형들이 자기를 애굽에 팔았다고 말했으며, 그러면서도 자기를 이리로 보낸 이는 형들이 아니라 하나님이시라고 말했다","ok":true},{"label":"요셉은 팔리지 않고 스스로 애굽에 내려갔다","basis":"본문에 없음"},{"label":"요셉은 은 삼십에 팔려 애굽으로 갔고, 요셉도 형들이 자기를 애굽에 팔았다고 말했으며, 그러면서도 자기를 이리로 보낸 이는 형들이 아니라 하나님이시라고 말했다","basis":"본문에 없음"}]}}},"nt":{"ref":"행 7:9-10","text":"신약의 사도행전 7장 9절과 10절은, 조상들이 시기하여 요셉을 애굽에 팔았으나 하나님이 그와 함께 계셔서 온갖 어려움에서 건지시고 바로 앞에서 은혜와 지혜를 주셨다고 말한다."}}]}},"has3d":false,"epic":false},"OT-09":{"id":"OT-09","era":3,"title":"불붙은 떨기나무와 부르심","ref":"출 3:1-12","place":"광야 서편","review":{"required":true,"topics":["구약 사건의 신약적 의미(행 7:30-34)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"출 3:1","focus":"sheep","text":{"t1":"모세는 양 떼를 데리고 광야를 지나 큰 산까지 왔어요. 누구의 양 떼였는지는 1절에서 찾아봐요.","t2":"모세는 미디안 제사장인 장인 이드로의 양 떼를 치고 있었어요. 양 떼를 이끌고 하나님의 산 호렙에 이르렀어요.","t3":"모세는 양 떼를 치다가 호렙, 곧 하나님의 산까지 왔다. 누구의 양 떼였고 모세와 그 양 떼의 주인이 어떤 사이였는지는 2장 21절과 3장 1절을 이어 읽어 보자."},"say":{"who":"hyu","text":"저분이 모세야. 양 떼를 데리고 여기까지 왔네."}},{"ref":"출 3:2-3","focus":"bush","text":{"t1":"떨기나무에서 불이 타오르는데도 나무는 타서 없어지지 않아요. 모세는 그것을 보려고 가까이 갔어요.","t2":"떨기나무 가운데 불꽃이 일었어요. 불이 붙었는데도 나무는 타서 없어지지 않았어요. 모세는 그쪽으로 다가갔는데, 왜 갔는지는 3절에서 찾아봐요.","t3":"여호와의 사자가 떨기나무 가운데 불꽃 안에서 그에게 나타났다. 떨기나무에 불이 붙었으나 사라지지 않았고, 모세는 어찌하여 타지 않는지 보려고 그쪽으로 갔다."},"say":{"who":"choeon","text":"불이 붙었는데 나무가 타서 없어지지 않아!"}},{"ref":"출 3:4","open":"출 3:4","focus":"bush","text":{"t1":"하나님이 떨기나무 속에서 모세의 이름을 부르셨어요. 모세가 대답했어요.","t2":"하나님이 떨기나무 속에서 모세의 이름을 두 번 부르셨어요. 무엇을 보시고 부르셨는지는 4절에 있어요. 모세는 자기가 여기 있다고 대답했어요.","t3":"여호와께서 그가 보려고 오는 것을 보셨다. 하나님이 떨기나무 가운데서 그의 이름을 거듭 부르셨고, 모세는 자신이 여기 있다고 대답했다."},"say":{"who":"onwoo","text":"하나님이 하신 말씀은 우리가 지어내면 안 돼. 성경책에서 직접 읽어 보자."}},{"ref":"출 3:5","focus":"moses","text":{"t1":"하나님은 모세에게 가까이 오지 말라고 하셨어요. 발에서 무엇을 벗으라고 하셨는지는 5절에서 찾아봐요.","t2":"하나님은 모세에게 가까이 오지 말라고 하셨어요. 그리고 모세에게 하라고 하신 일과 그 까닭은 5절에서 찾아봐요.","t3":"하나님은 그가 선 곳이 거룩한 땅이라고 하셨다. 그래서 그에게 무엇을 하라고 하셨는지는 5절에서 직접 읽어 보자."},"say":{"who":"choeon","text":"하나님이 모세에게 무언가를 하라고 하셨어."}},{"ref":"출 3:6","focus":"moses","text":{"t1":"하나님은 자신이 모세의 조상들의 하나님이라고 알려 주셨고, 모세는 얼굴을 가렸어요. 그 조상들이 누구인지는 6절에서 찾아봐요.","t2":"하나님은 자신이 모세의 조상의 하나님, 곧 아브라함, 이삭, 야곱의 하나님이라고 하셨어요. 그 말씀을 들은 모세가 무엇을 했고 왜 그랬는지는 6절에서 찾아봐요.","t3":"하나님은 자신이 모세의 조상의 하나님, 곧 아브라함과 이삭과 야곱의 하나님이라고 밝히셨다. 모세는 하나님 뵙기를 두려워하여 얼굴을 가렸다."},"say":{"who":"hyu","text":"조상들의 이름이 나왔어. 일지에 적어 둘게."}},{"ref":"출 3:7-8","focus":"bush","text":{"t1":"하나님은 애굽에 있는 백성의 아픔을 보셨고, 부르짖는 소리를 들으셨다고 하셨어요.","t2":"하나님은 애굽에 있는 백성의 고통을 보셨고 부르짖음을 들으셨다고 하셨어요. 그들을 건져 내어 젖과 꿀이 흐르는 넓은 땅으로 데려가겠다고 하셨어요.","t3":"여호와께서는 애굽에 있는 자기 백성이 겪는 괴로움을 똑똑히 보셨고, 감독들 때문에 부르짖는 소리를 들으셨으며, 그들의 아픔을 아신다고 하셨다. 그들을 애굽 사람의 손에서 구해 내어 젖과 꿀이 흐르는 좋고 넓은 땅으로 데려가겠다고 하셨다."},"say":{"who":"choeon","text":"아까 애굽에서 본 그 사람들 이야기야!"}},{"ref":"출 3:10-12","open":"출 3:12","focus":"moses","text":{"t1":"하나님은 모세를 바로에게 보내겠다고 하셨어요. 모세가 자기가 누구이기에 가겠느냐고 여쭈자, 하나님이 대답하셨어요.","t2":"하나님은 모세를 바로에게 보내어 백성을 애굽에서 인도해 내게 하겠다고 하셨어요. 모세는 자기가 누구이기에 그 일을 하겠느냐고 여쭈었고, 하나님은 반드시 함께 있겠다고 하셨어요.","t3":"하나님은 모세를 바로에게 보내어 이스라엘 자손을 이끌고 애굽을 나오게 하겠다고 하셨다. 모세는 자기가 누구이기에 바로에게 가며 그 일을 하겠느냐고 아뢰었고, 하나님은 그 물음에 대답하셨다."},"say":{"who":"onwoo","text":"모세의 물음에 하나님이 어떻게 대답하셨는지, 12절에서 확인해 보자."}}],"gates":{"t1":[{"type":"find","ref":"출 3:5","prompt":"성경책에서 출애굽기 3장 5절을 찾아 읽어 보세요.","confirm":{"prompt":"하나님은 모세에게 무엇을 벗으라고 하셨나요?","options":[{"label":"신","ok":true},{"label":"겉옷","basis":"본문에 없음"},{"label":"머리쓰개","basis":"본문에 없음"}]}},{"type":"multi","ref":"출 3:6","prompt":"성경책에서 출애굽기 3장 6절을 찾아 읽어 보세요.","confirm":{"prompt":"하나님은 자신을 누구의 하나님이라고 하셨나요? 모두 고르세요.","options":[{"label":"아브라함","ok":true},{"label":"노아","basis":"본문에 없음"},{"label":"이삭","ok":true},{"label":"요셉","basis":"본문에 없음"},{"label":"야곱","ok":true}]}}],"t2":[{"type":"find","ref":"출 3:3-4","prompt":"성경책에서 출애굽기 3장 3절과 4절을 읽어 보세요.","confirm":{"prompt":"하나님이 모세의 이름을 두 번 부르신 것은 무엇을 보셨기 때문인가요?","options":[{"label":"모세가 그 광경을 보려고 발길을 돌려 오는 것을 보셨기 때문에","ok":true},{"label":"모세가 양 떼를 잃어버리고 헤매는 것을 보셨기 때문에","basis":"본문에 없음"},{"label":"모세가 떨기나무의 불을 끄려는 것을 보셨기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"출 3:2-6","prompt":"성경책에서 출애굽기 3장 2절부터 6절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["불붙은 떨기나무가 타서 없어지지 않았다","모세가 떨기나무 쪽으로 발길을 돌렸다","하나님이 모세의 이름을 두 번 부르셨다","하나님이 가까이 오지 말고 신을 벗으라고 하셨다","모세가 얼굴을 가렸다"]}],"t3":[{"type":"find","refs":["출 3:11","출 3:12"],"prompt":"출애굽기 3장 11절과 12절을 함께 찾아 읽어 보자.","confirm":{"prompt":"모세가 '내가 누구이기에' 하고 아뢰었을 때, 하나님은 무엇으로 대답하셨는가?","options":[{"label":"모세는 자기가 누구이기에 바로에게 가겠느냐고 아뢰었고, 하나님은 반드시 그와 함께 있겠다고 대답하셨다","ok":true},{"label":"모세는 기꺼이 가겠다고 아뢰었고, 하나님은 그가 말을 잘하는 사람이라고 칭찬하셨다","basis":"본문에 없음"},{"label":"모세는 자기가 누구이기에 가겠느냐고 아뢰었고, 하나님은 바로가 곧 허락할 것이라고 대답하셨다","basis":"본문에 없음"}]}},{"type":"match","refs":["출 2:24","출 3:2","출 3:6"],"prompt":"출애굽기 2장 24절, 3장 2절, 3장 6절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"출 2:24","text":"하나님이 아브라함, 이삭, 야곱과 세우신 언약을 기억하셨다"},{"ref":"출 3:2","text":"떨기나무의 불꽃 속에서 여호와의 사자가 모세에게 나타났다"},{"ref":"출 3:6","text":"하나님이 자신을 모세의 조상들의 하나님이라고 밝히셨다"}],"after":"세 곳을 이으면, 하나님은 아브라함·이삭·야곱과 세우신 언약을 기억하셨고, 떨기나무 불꽃 속에서 여호와의 사자가 모세에게 나타났으며, 하나님은 자신을 바로 그 조상들의 하나님이라고 밝히셨다."}]},"cards":[{"ref":"출 3:5","title":"거룩한 땅"},{"ref":"출 3:12","title":"함께 있겠다는 약속"}],"close":{"t1":{"kind":"prayer","text":"하나님, 모세를 부르신 이야기를 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 출애굽기 3장 1절부터 12절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"출 3:1-12에서 새로 알게 된 사실을 한 가지 적어 보자."}},"quests":[{"part":"gear","name":"톱니바퀴","line":"톱니바퀴를 찾았어! 양 떼 사이에 떨어져 있었네.","found":"탐지기가 양 떼 쪽을 가리켜요.","say":{"who":"hyu","text":"탐지기 바늘이 양 떼 쪽으로 돌아갔어. 일지에 적어 둘게."},"q":{"t1":{"type":"find","ref":"출 3:1","prompt":"성경책에서 출애굽기 3장 1절을 찾아 읽어 보세요.","confirm":{"prompt":"모세는 누구의 양 떼를 치고 있었나요?","options":[{"label":"장인 이드로의 양 떼","ok":true},{"label":"애굽 왕 바로의 양 떼","basis":"본문에 없음"},{"label":"형 아론의 양 떼","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"출 3:1-3","prompt":"성경책에서 출애굽기 3장 1절부터 3절까지 읽어 보세요.","confirm":{"prompt":"양 떼를 치던 모세가 발길을 돌려 떨기나무 쪽으로 간 까닭은 무엇인가요?","options":[{"label":"불이 붙었는데도 떨기나무가 타지 않는 큰 광경을 보려고","ok":true},{"label":"떨기나무의 불이 양 떼 쪽으로 번지지 않게 막으려고","basis":"본문에 없음"},{"label":"타지 않는 떨기나무 곁에서 양 떼를 편히 쉬게 하려고","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["출 2:21","출 3:1"],"prompt":"출애굽기 2장 21절과 3장 1절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 모세가 미디안 제사장의 양 떼를 치게 된 정황은 어떠한가?","options":[{"label":"모세는 미디안 제사장과 함께 살며 그 딸 십보라를 아내로 맞았고, 그 장인의 양 떼를 치다가 호렙, 곧 하나님의 산에 이르렀다","ok":true},{"label":"모세는 미디안 제사장의 집에 품꾼으로 들어갔지만 그 딸과 혼인하지 않았고, 그의 양 떼를 치다가 호렙, 곧 하나님의 산에 이르렀다","basis":"본문에 없음"},{"label":"모세는 미디안 제사장의 딸 십보라를 아내로 맞은 뒤 따로 나가 살며, 자기가 사들인 양 떼를 치다가 호렙, 곧 하나님의 산에 이르렀다","basis":"본문에 없음"}]}}}},{"part":"needle","name":"나침반 바늘","line":"나침반 바늘이 여기 있었네! 산으로 가는 길목이야.","found":"탐지기가 큰 산 쪽으로 난 길을 가리켜요.","say":{"who":"choeon","text":"저 큰 산 쪽이야! 성경에서 찾은 그 산이구나."},"q":{"t1":{"type":"find","ref":"출 3:1","prompt":"성경책에서 출애굽기 3장 1절을 찾아 읽어 보세요.","confirm":{"prompt":"모세는 양 떼를 이끌고 어느 산에 이르렀나요?","options":[{"label":"하나님의 산 호렙","ok":true},{"label":"갈멜 산","basis":"본문에 없음"},{"label":"시온 산","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"출 3:1-5","prompt":"성경책에서 출애굽기 3장 1절부터 5절까지 읽어 보세요.","confirm":{"prompt":"하나님의 산 호렙에서 하나님이 모세에게 신을 벗으라고 하신 까닭은 무엇인가요?","options":[{"label":"모세가 선 곳이 거룩한 땅이기 때문에","ok":true},{"label":"산길이 미끄러웠기 때문에","basis":"본문에 없음"},{"label":"신이 낡아 해어졌기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["출 3:1","출 3:12"],"prompt":"출애굽기 3장 1절과 12절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 모세가 이른 산을 두고 무엇을 알 수 있는가?","options":[{"label":"모세가 양 떼를 이끌고 이른 곳은 하나님의 산 호렙이고, 하나님은 백성이 애굽에서 나온 뒤에 하나님을 이 산에서 섬기게 되리라고 하셨다","ok":true},{"label":"모세가 양 떼를 이끌고 이른 곳은 하나님의 산 호렙이고, 하나님은 모세 혼자 이 산에 남아 하나님을 섬기게 되리라고 하셨다","basis":"본문에 없음"},{"label":"모세가 양 떼를 이끌고 이른 곳은 하나님의 산 호렙이었지만, 하나님은 백성이 애굽에서 나온 뒤에 다시는 이 산에 오지 못하리라고 하셨다","basis":"본문에 없음"}]}}}},{"part":"screw","name":"나사","line":"나사를 찾았어! 언덕 아래 우묵한 곳에 굴러 들어가 있었어.","found":"탐지기가 불빛이 어른거리는 언덕 아래를 가리켜요.","say":{"who":"onwoo","text":"언덕 아래까지만 가자. 위로 올라가지는 말자. 우리는 지켜보는 사람이야."},"q":{"t1":{"type":"find","ref":"출 3:2","prompt":"성경책에서 출애굽기 3장 2절을 찾아 읽어 보세요.","confirm":{"prompt":"떨기나무의 불꽃 속에서 모세에게 나타난 이는 누구인가요?","options":[{"label":"여호와의 사자","ok":true},{"label":"모세의 형 아론","basis":"출 4:27"},{"label":"모세의 장인 이드로","basis":"출 18:5"}]}},"t2":{"type":"find","ref":"출 3:4-6","prompt":"성경책에서 출애굽기 3장 4절부터 6절까지 읽어 보세요.","confirm":{"prompt":"떨기나무 앞에서 모세가 얼굴을 가린 까닭은 무엇인가요?","options":[{"label":"하나님 뵙기를 두려워했기 때문에","ok":true},{"label":"불빛이 너무 눈부셨기 때문에","basis":"본문에 없음"},{"label":"연기가 매웠기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["출 3:3","출 3:5"],"prompt":"출애굽기 3장 3절과 5절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 떨기나무 쪽으로 가던 모세에게 어떤 일이 있었는가?","options":[{"label":"모세는 타지 않는 떨기나무를 보려고 돌이켜 갔고, 하나님은 그에게 이리로 가까이 오지 말고 신을 벗으라고 하셨다","ok":true},{"label":"모세는 떨기나무의 불을 끄려고 그쪽으로 갔고, 하나님은 그에게 이리로 가까이 오지 말고 신을 벗으라고 하셨다","basis":"본문에 없음"},{"label":"모세는 타지 않는 떨기나무를 보려고 돌이켜 갔고, 하나님은 그에게 이리로 가까이 오지 말고 겉옷을 벗어 두라고 하셨다","basis":"본문에 없음"}]}}}}],"mission":{"call":{"t1":"최현 박사예요. 타임머신이 광야에 비상 착륙하면서 부속 세 개가 망가졌어요. 이 근처에서 대신 쓸 재료를 찾아보세요.","t2":"최현 박사예요. 타임머신이 호렙 산 가까운 광야에 비상 착륙하면서 톱니바퀴와 나침반 바늘과 나사가 망가졌어요. 이 시대에는 맞는 부속이 없으니 땅에 떨어진 것 가운데서 대신 쓸 재료를 찾아보세요. 사람의 물건에는 손대지 말아요.","t3":"최현 박사다. 타임머신이 호렙 산 가까운 광야에 비상 착륙하면서 톱니바퀴, 나침반 바늘, 나사가 망가졌다. 이 시대에는 맞는 부속이 없으니 그 자리에서 구할 수 있는 재료로 대신 만들어야 한다. 땅에 떨어진 것만 줍고, 사람의 물건과 일이 일어나는 자리에는 손대지 말자."},"materials":[{"key":"wool","name":"양털","basis":"출 3:1","use":"양털을 꼬아 끈을 만들면 톱니바퀴 대신 바퀴를 돌리는 줄로 쓸 수 있어요.","how":"양 떼가 지나간 땅바닥에 떨어진 양털 한 뭉치를 줍는다. 양을 붙잡거나 털을 뽑지 않는다.","line":"양 떼가 지나간 땅바닥에서 양털 한 뭉치를 찾았어!"},{"key":"stone","name":"돌 조각","basis":"출 3:1","use":"가늘고 뾰족한 돌 조각을 끼우면 나침반 바늘 대신 쓸 수 있어요.","how":"큰 산 쪽으로 난 길목에서 길가에 굴러 있는 돌 조각을 줍는다. 산 위로는 올라가지 않는다.","line":"큰 산으로 가는 길목에서 뾰족한 돌 조각을 찾았어!"},{"key":"horn","name":"양의 뿔 조각","basis":"출 3:1","use":"양의 뿔 조각을 깎아 끼우면 나사 대신 쓸 수 있어요.","how":"언덕 아래 우묵한 곳에 떨어져 있는 양의 뿔 조각을 줍는다. 언덕 위로 올라가지 않고, 떨기나무 쪽에는 가까이 가지 않는다.","line":"언덕 아래 우묵한 곳에서 양의 뿔 조각을 찾았어!"}],"companion":{"who":"모세","ref":"출 3:1","when":"after","talks":[{"ask":{"who":"choeon","text":"떨기나무 가운데서 하나님이 부르셨을 때, 무엇이라고 대답하셨어요?"},"answer":{"t1":"모세는 자기가 여기 있다고 대답했어요.","t2":"하나님이 떨기나무 속에서 이름을 두 번 부르시자, 모세는 자기가 여기 있다고 대답했어요.","t3":"하나님이 떨기나무 속에서 그의 이름을 거듭 부르시자, 모세는 자신이 여기 있다고 대답했다."},"ref":"출 3:4","open":"출 3:4"},{"ask":{"who":"onwoo","text":"바로에게 보내겠다는 말씀을 들으셨을 때 하나님께 무엇이라고 아뢰셨어요?"},"answer":{"t1":"모세는 자기가 누구이기에 바로에게 가겠느냐고 하나님께 여쭈었어요.","t2":"모세는 하나님께, 자기가 누구이기에 바로에게 가겠느냐고 여쭈었어요. 자기가 누구이기에 이스라엘 자손을 애굽에서 이끌어 내겠느냐고도 했어요.","t3":"모세는 하나님께, 자기가 누구이기에 바로에게 가서 이스라엘 자손을 애굽에서 이끌어 내겠느냐고 아뢰었다."},"ref":"출 3:11","open":"출 3:11"}]},"today":[{"q":"모세는 왜 신을 벗어야 했어요?","a":{"t1":"하나님은 모세가 선 곳이 거룩한 땅이라고 하셨어요. 그래서 발에서 신을 벗으라고 하셨어요.","t2":"하나님은 모세에게 가까이 오지 말고 발에서 신을 벗으라고 하셨어요. 모세가 선 곳이 거룩한 땅이기 때문이라고 하셨어요. 성경은 여기까지 말해요.","t3":"하나님은 모세에게 가까이 오지 말고 발에서 신을 벗으라고 하시며, 그가 선 곳이 거룩한 땅이라고 까닭을 밝히셨다(출 3:5). 성경은 이 장면에서 여기까지 말한다."},"refs":["출 3:5"]},{"q":"하나님은 힘들어서 부르짖는 사람의 소리를 들으실까요?","a":{"t1":"이 장면에서 하나님은 애굽에 있는 자기 백성이 부르짖는 소리를 들으셨다고 하셨어요. 그들의 아픔을 아신다고 하셨어요.","t2":"출애굽기는 이스라엘 자손이 고된 일 때문에 부르짖었고, 하나님이 그 소리를 들으셨다고 기록해요. 떨기나무 가운데서도 하나님은 애굽에 있는 자기 백성의 고통을 보셨고, 부르짖음을 들으셨고, 아픔을 아신다고 하셨어요. 성경은 이 장면에서 여기까지 말해요.","t3":"출애굽기는 이스라엘 자손이 고된 일 때문에 탄식하며 부르짖었고 그 소리가 하나님께 이르렀으며, 하나님은 그들의 탄식을 들으셨으며 아브라함과 이삭과 야곱과 세우신 언약을 기억하셨다고 기록한다(출 2:23-25). 떨기나무 가운데서 하나님은 애굽에 있는 자기 백성의 고통을 똑똑히 보셨고 감독들 때문에 부르짖는 소리를 들으셨으며 그들의 근심을 아신다고 하셨다(출 3:7, 3:9). 성경은 이 장면에서 여기까지 말한다."},"refs":["출 2:23-25","출 3:7","출 3:9"]}],"help":{"who":"모세","steps":[{"kind":"do","after":0,"title":"양 떼에게 길 비켜 주기","basis":"출 3:1","text":{"t1":"모세가 양 떼를 이끌고 광야를 지나 큰 산까지 왔어요. 우리는 양 떼 곁에서 길을 비켜 주며 도와요.","t2":"모세가 장인의 양 떼를 이끌고 광야를 지나 하나님의 산 호렙까지 왔어요. 우리는 양 떼가 잘 지나가도록 곁에서 길을 비켜 주며 도와요. 본문에 적힌 일이 아니라 탐험대 이야기예요.","t3":"모세는 양 떼를 몰고 광야를 지나 호렙, 곧 하나님의 산까지 왔다. 탐험대는 양 떼가 지나는 길 곁에서 길을 비켜 주고 길 위의 돌멩이를 치우며 돕는다. 본문에 적힌 일이 아니라 탐험대 이야기다. 양을 붙잡거나 모세의 일을 대신하지 않는다."},"tasks":["양 떼가 오는 쪽 살피기","길 위의 돌멩이 길가로 치우기","길가로 비켜서기"],"done":{"who":"hyu","text":"양 떼가 다 지나갔어. 모세가 양 떼를 이끌고 산 쪽으로 가고 있어."}},{"kind":"watch","after":1,"title":"곁에서 보기 · 타지 않는 떨기나무","basis":"출 3:2-3","text":{"t1":"떨기나무가 불타는데도 사라지지 않아요. 모세는 그것을 보려고 그쪽으로 갔어요. 우리는 멀리서 지켜봐요.","t2":"떨기나무의 불꽃 속에서 여호와의 사자가 모세에게 나타났어요. 불이 붙었는데도 나무는 사라지지 않았고, 모세는 그쪽으로 갔어요. 우리는 떨기나무 쪽으로 다가가지 않고 멀리서 지켜봐요.","t3":"떨기나무의 불꽃 속에서 여호와의 사자가 모세에게 나타났고, 불이 붙은 떨기나무는 사라지지 않았다. 모세는 그쪽으로 갔다. 탐험대는 떨기나무 쪽으로 다가가지 않고 멀리서 지켜본다."},"say":{"who":"onwoo","text":"우리는 여기까지만. 떨기나무 쪽으로는 다가가지 않을 거야."}},{"kind":"stay","after":3,"title":"언덕 아래에서 기다리기","basis":"출 3:5","text":{"t1":"하나님은 모세에게 이리로 가까이 오지 말라고 하셨어요. 우리도 떨기나무 쪽으로 가지 않고 언덕 아래에서 기다려요.","t2":"하나님은 모세에게 이리로 가까이 오지 말라고 하셨어요. 우리도 더 다가가지 않고 언덕 아래에 머물며 기다려요.","t3":"하나님은 모세가 선 곳이 거룩한 땅이라고 하셨다. 탐험대도 떨기나무 쪽으로 더 다가가지 않고 언덕 아래에 머물며 기다린다."},"wait":"언덕 아래에서 기다리기","say":{"who":"choeon","text":"우리는 여기 언덕 아래에 있을게. 더 가까이 가지 않아."}},{"kind":"ask","after":"gates","title":"떨기나무에서 부르신 일은 무슨 뜻이에요?","basis":"출 3:8-10","by":"최현 박사","ask":{"who":"hyu","text":"떨기나무에서 하나님이 모세를 부르신 일은 무슨 뜻이에요?"},"answer":{"t1":"성경은 하나님이 백성을 애굽 사람의 손에서 건져 내려고 내려오셨다고 적어요(출 3:8). 그래서 모세를 바로에게 보내어 백성을 이끌어 내게 하겠다고 하셨어요(출 3:10).","t2":"출애굽기 3장 8절에서 하나님은 내려와서 백성을 애굽 사람의 손에서 구해 내고, 젖과 꿀이 흐르는 넓고 좋은 땅으로 데려가겠다고 하셨어요. 10절에서는 모세를 바로에게 보내어, 그가 이스라엘 자손을 이끌고 애굽을 나오게 하겠다고 하셨어요. 성경은 이 장면에서 여기까지 말해요.","t3":"하나님은 친히 내려와 백성을 애굽 사람의 손에서 구해 내고, 그 땅에서 이끌어 올려 젖과 꿀이 흐르는 좋고 넓은 땅, 곧 가나안 족속과 헷 족속 등이 사는 곳으로 데려가겠다고 하셨다(출 3:8). 그리고 모세를 바로에게 보내어, 그가 하나님의 백성인 이스라엘 자손을 이끌고 애굽을 나오게 하겠다고 하셨다(출 3:10). 성경은 이 장면에서 여기까지 말한다."},"read":{"t1":{"type":"find","ref":"출 3:12","prompt":"성경책에서 출애굽기 3장 12절을 찾아 읽어 보세요.","confirm":{"prompt":"하나님은 바로에게 가는 모세와 어떻게 하겠다고 하셨나요?","options":[{"label":"반드시 함께 있겠다","ok":true},{"label":"멀리서 지켜보기만 하겠다","basis":"본문에 없음"},{"label":"모세 혼자 가게 하겠다","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"출 3:10-12","prompt":"성경책에서 출애굽기 3장 10절부터 12절까지 읽어 보세요.","confirm":{"prompt":"하나님이 백성이 애굽에서 나온 뒤 하나님을 이 산에서 섬기게 되리라고 하신 까닭은 무엇인가요?","options":[{"label":"그것이 하나님이 모세를 보내셨다는 증거가 되기 때문에","ok":true},{"label":"모세가 장인의 양 떼를 그 산에서 계속 치게 하시려고","basis":"본문에 없음"},{"label":"그것이 모세가 바로를 이길 힘을 받았다는 표가 되기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["출 3:7","출 3:10","출 3:12"],"prompt":"출애굽기 3장 7절, 10절, 12절을 함께 찾아 읽어 보자.","confirm":{"prompt":"세 곳을 이어 읽으면, 떨기나무에서 하나님이 하신 말씀은 무엇을 말하는가?","options":[{"label":"하나님은 애굽에 있는 백성의 고통을 보시고 부르짖음을 들으셨으며, 모세를 바로에게 보내어 그들을 이끌어 내게 하시고, 반드시 그와 함께 있겠다고 하셨다","ok":true},{"label":"하나님은 애굽에 있는 백성의 고통을 보시고 부르짖음을 들으셨으며, 모세를 바로에게 보내어 그들을 이끌어 내게 하시고, 모세를 애굽의 왕으로 세우겠다고 하셨다","basis":"본문에 없음"},{"label":"하나님은 애굽에 있는 백성의 고통을 보시고 부르짖음을 들으셨으며, 모세를 바로에게 보내어 그들을 이끌어 내게 하시고, 모세 혼자 그 일을 해내야 한다고 하셨다","basis":"본문에 없음"}]}}},"nt":{"ref":"행 7:30-34","text":"신약의 사도행전 7장 30~34절에서 스데반은 이 일을 다시 이야기한다. 떨기나무 불꽃 가운데 모세에게 보인 일과, 하나님이 백성의 괴로움을 보시고 그들을 구원하려고 내려오셨으며 모세를 애굽으로 보내신다고 하신 일을 전한다."}}]}},"has3d":true,"epic":true},"OT-10":{"id":"OT-10","era":3,"title":"마지막 재앙과 유월절","ref":"출 11:1-12:42","place":"애굽 땅, 라암셋에서 숙곳으로","review":{"required":true,"topics":["재앙과 심판, 장자의 죽음","구약 사건의 신약적 의미(유월절)","하나님의 주권과 사람의 책임(출 11:10)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"출 11:1-3","open":"출 11:1","focus":"moses","text":{"t1":"하나님은 애굽에 재앙을 하나 더 내리겠다고 하셨어요. 그 뒤에 바로가 백성을 내보낼 거라고 하셨어요.","t2":"하나님은 모세에게 바로와 애굽에 재앙을 하나 더 내리겠다고 하셨어요. 그 뒤에는 바로가 백성을 보낼 것이고, 보낼 때에는 아예 다 쫓아낼 것이라고 하셨어요. 또 백성이 이웃들에게 은과 금으로 된 패물을 구하게 하라고 하셨어요.","t3":"여호와께서는 모세에게 바로와 애굽에 재앙을 하나 더 내리겠다고, 그런 뒤에야 바로가 그들을 보내되 아예 쫓아낼 것이라고 하셨다. 백성의 남자와 여자가 저마다 이웃에게 은과 금으로 된 패물을 구하게 하라고도 하셨다. 여호와께서는 백성이 애굽 사람에게 은혜를 입게 하셨고, 모세는 애굽 땅에서 바로의 신하들과 백성의 눈에 매우 큰 사람으로 보였다."},"say":{"who":"hyu","text":"여기는 애굽 땅이야. 재앙이 하나 더 남았다고 하셨어. 일지에 적어 둘게."}},{"ref":"출 11:4-10","open":"출 11:4-7","focus":"pharaoh","text":{"t1":"모세는 밤중에 하나님이 애굽 가운데로 들어가시고 애굽 온 땅에 큰 울음소리가 있을 거라는 말씀을 바로에게 전했어요. 이스라엘 자손에게는 개조차 혀를 움직이지 않을 거라고 했어요.","t2":"모세는 바로에게 여호와의 말씀을 전했어요. 밤중에 여호와께서 애굽 가운데로 들어가실 것이고, 바로의 맏아들부터 여종의 맏아들까지, 그리고 가축의 처음 난 것까지 죽을 것이라고 했어요. 그러나 이스라엘 자손에게는 개조차 혀를 놀리지 않아서, 여호와께서 애굽 사람과 이스라엘을 구별하시는 줄 알게 될 것이라고 했어요. 모세는 몹시 노하여 바로 앞에서 나왔어요.","t3":"모세는 바로에게 여호와의 말씀을 전했다. 밤중에 여호와께서 애굽 가운데로 들어가실 것이며, 왕위에 앉은 바로의 맏아들부터 맷돌 뒤에 있는 여종의 맏아들까지, 또 가축의 처음 난 것까지 죽을 것이라고 했다. 애굽 온 땅에 전에도 없었고 뒤에도 없을 큰 울부짖음이 있겠으나, 이스라엘 자손에게는 사람에게든 짐승에게든 개조차 혀를 놀리지 않아 여호와께서 애굽 사람과 이스라엘을 구별하시는 줄 알게 될 것이라고 했다. 모세는 바로의 신하들이 자기에게 내려와 절하며 온 백성과 함께 나가라고 한 뒤에야 나가겠다고 말하고, 몹시 노하여 바로에게서 나왔다. 여호와께서는 모세에게 바로가 듣지 않을 것이라고 하셨다. 모세와 아론이 바로 앞에서 이 모든 기적을 행했지만 여호와께서 바로의 마음을 강퍅하게 하셨으므로 바로는 이스라엘 자손을 자기 나라에서 내보내지 않았다."},"say":{"who":"onwoo","text":"모세가 전한 여호와의 말씀은 11장 4절부터 7절에 있어. 성경책에서 직접 읽어 보자."}},{"ref":"출 12:1-11","open":"출 12:3-11","focus":"lamb","text":{"t1":"하나님은 집마다 어린 양을 잡아 그 피를 문에 바르라고 하셨어요. 피를 바를 곳과 그 밤에 먹을 것은 7절과 8절에서 찾아봐요.","t2":"하나님은 애굽 땅에서 모세와 아론에게, 이 달을 한 해의 첫 달로 삼으라고 하셨어요. 이 달 열흘에 가족마다 흠 없고 일 년 된 수컷 어린 양을 고르고, 십사일 해 질 때에 잡으라고 하셨어요. 그 피는 양을 먹을 집 문의 양쪽 기둥과 인방에 바르고, 고기는 그 밤에 불에 구워 무교병과 쓴 나물과 함께 먹으라고 하셨어요. 허리에 띠를 매고 신을 신고 지팡이를 든 채 서둘러 먹으라고 하셨어요.","t3":"여호와께서는 애굽 땅에서 모세와 아론에게 이 달을 한 해의 첫 달로 삼으라고 하셨다. 이 달 열흘에 가족마다 어린 양을 고르되, 식구가 너무 적으면 이웃과 함께 사람 수에 맞추어 고르라고 하셨다. 양이나 염소 가운데서 흠 없고 일 년 된 수컷을 골라 십사일까지 두었다가 해 질 때에 이스라엘 회중이 잡고, 그 피를 양을 먹을 집 문의 좌우 설주와 인방에 바르라고 하셨다. 그 밤에 고기를 날것이나 물에 삶은 것으로 먹지 말고 불에 구워 무교병과 쓴 나물과 함께 먹되, 아침까지 남은 것은 불사르라고 하셨다. 허리에 띠를 매고 신을 신고 지팡이를 손에 든 채 먹으라고 하셨고, 이것이 여호와의 유월절이라고 하셨다."},"say":{"who":"choeon","text":"어린 양의 피를 문에 바르라고 하셨대."}},{"ref":"출 12:12-20","open":"출 12:12-14","focus":"door","text":{"t1":"하나님은 피가 있는 집은 넘어가겠다고 하셨어요. 이 날을 대대로 지키라고 하셨어요.","t2":"하나님은 그 밤에 애굽 땅을 두루 다니며 사람이든 짐승이든 처음 난 것을 다 치겠다고 하셨어요. 이스라엘 자손의 집에 있는 피를 두고 하신 말씀은 13절에서 찾아봐요. 이 날을 기념하여 여호와의 절기로 대대에 지키고, 이레 동안 무교병을 먹으라고 하셨어요.","t3":"여호와께서는 그 밤에 애굽 땅을 두루 다니며 사람과 짐승을 가리지 않고 애굽에서 처음 난 것을 모두 치시고, 애굽의 모든 신에게도 벌을 내리겠다고 하셨다. 이스라엘 자손이 사는 집에 있는 피를 두고 하신 말씀은 13절에서 직접 읽어 보자. 이 날을 기념하여 여호와의 절기로 삼고 영원한 규례로 삼아 대대로 지키라고 하셨다. 또 첫 달 십사일 저녁에 시작하여 이십일일 저녁까지 이레 동안 무교병을 먹고, 첫날에 집에서 누룩을 없애라고 하셨다. 첫날과 일곱째 날은 성회가 되니 그 두 날에는 각 사람이 먹을 것을 마련하는 일 말고는 아무 일도 하지 말라고 하셨다."},"say":{"who":"hyu","text":"하나님이 이 날을 대대로 지키라고 하셨어. 일지에 적어 둘게."}},{"ref":"출 12:21-28","focus":"elders","text":{"t1":"모세는 장로들에게 아침까지 아무도 문밖에 나가지 말라고 전했어요. 백성은 경배하고 그대로 했어요.","t2":"모세는 이스라엘의 모든 장로를 불러, 어린 양을 잡고 우슬초 묶음을 그릇의 피에 적셔 문 인방과 양쪽 기둥에 뿌리라고 했어요. 날이 밝을 때까지 아무도 집 문밖으로 나가지 말라고 했어요. 뒷날 자녀가 이 예식의 뜻을 물으면 무엇이라고 대답하라고 했는지는 26절과 27절에서 찾아봐요. 백성은 머리 숙여 경배했고, 가서 그대로 했어요.","t3":"모세는 이스라엘의 모든 장로를 불러, 가족대로 어린 양을 골라 유월절 양으로 잡으라고 했다. 우슬초 묶음을 그릇에 담긴 피에 적셔 문 인방과 좌우 설주에 뿌리라고 했고, 날이 밝을 때까지 아무도 자기 집 문밖으로 나가지 말라고 했다. 이 일을 규례로 삼아 자손과 함께 영원히 지키고, 여호와께서 주시는 땅에 이르러서도 이 예식을 지키라고 했다. 그렇게 하라고 한 까닭과 뒷날 자녀가 이 예식의 뜻을 물을 때 할 대답은 23절과 27절에 있다. 백성은 머리 숙여 경배했고, 이스라엘 자손은 돌아가서 모세와 아론이 여호와께 받은 명령대로 했다."},"say":{"who":"choeon","text":"백성이 머리를 숙여 경배하고 있어."}},{"ref":"출 12:29-32","focus":"night","text":{"t1":"밤중에 하나님이 애굽 땅의 처음 난 것을 치셨고, 애굽에 큰 울음소리가 있었어요. 그 밤에 바로는 모세와 아론에게 떠나라고 했어요.","t2":"밤중에 여호와께서 애굽 땅의 처음 난 것을 다 치셨어요. 바로의 맏아들부터 옥에 갇힌 사람의 맏아들까지, 가축의 처음 난 것까지였어요. 그 밤에 애굽에서 이어서 일어난 일과 바로가 한 말은 30절부터 32절까지 읽어 봐요.","t3":"밤중에 여호와께서 애굽 땅의 처음 난 것을, 왕위에 앉은 바로의 맏아들부터 옥에 갇힌 사람의 맏아들까지, 또 가축의 처음 난 것까지 다 치셨다. 그 밤에 바로도, 그의 신하들도, 애굽 사람들도 모두 일어났고 애굽에 큰 울부짖음이 있었으니, 죽은 사람이 없는 집이 하나도 없었기 때문이다. 바로는 밤에 모세와 아론을 불러, 이스라엘 자손과 함께 자기 백성 가운데서 떠나 그들이 말한 대로 가서 여호와를 섬기라고 했다. 양과 소도 몰고 가라고 했고, 자기를 위하여 복을 빌어 달라고 했다."},"say":{"who":"onwoo","text":"이 밤의 일은 성경이 적은 만큼만 읽자. 12장 29절과 30절이야."}},{"ref":"출 12:33-42","focus":"road","text":{"t1":"백성은 부풀지 않은 반죽을 그릇째 싸서 메고 서둘러 떠났어요. 라암셋을 떠나 숙곳에 이르렀어요.","t2":"애굽 사람들은 백성을 재촉하여 그 땅에서 서둘러 내보내려 했어요. 백성은 아직 부풀지 않은 반죽이 담긴 그릇을 옷에 싸서 어깨에 멨고, 모세의 말대로 애굽 사람에게 은금 패물과 옷을 구했어요. 이스라엘 자손은 라암셋을 떠나 숙곳에 이르렀는데, 아이들 말고 걸어서 가는 장정만 육십만쯤이었어요. 성경은 이 밤을 여호와의 밤이라고 해요.","t3":"애굽 사람들은 자기들이 다 죽게 되었다고 하며 백성을 재촉했다. 백성은 아직 부풀지 않은 반죽이 담긴 그릇을 옷에 싸서 어깨에 멨고, 모세의 말대로 애굽 사람에게 은과 금으로 된 패물과 옷을 구했으며, 여호와께서 애굽 사람이 백성에게 은혜를 베풀어 구하는 대로 주게 하셨다. 이스라엘 자손은 라암셋을 떠나 숙곳에 이르렀는데, 아이들 외에 걸어서 가는 장정이 육십만쯤이었고 여러 족속이 섞인 많은 무리와 양과 소와 매우 많은 가축이 함께했다. 그들은 가지고 나온 반죽으로 무교병을 구웠다. 그 까닭은 39절에 있다. 이스라엘 자손이 애굽에 머문 기간은 사백삼십 년이었고, 그 기간이 끝나는 바로 그 날에 여호와의 군대가 모두 애굽 땅에서 나왔다. 이 밤은 여호와께서 그들을 애굽 땅에서 인도하여 내신 일 때문에 여호와 앞에 지킬 여호와의 밤이며, 이스라엘 자손이 대대로 지킬 밤이다."},"say":{"who":"hyu","text":"라암셋에서 숙곳까지. 떠난 곳과 이른 곳을 일지에 적어 둘게."}}],"gates":{"t1":[{"type":"find","ref":"출 12:7","prompt":"성경책에서 출애굽기 12장 7절을 찾아 읽어 보세요.","confirm":{"prompt":"어린 양의 피를 집의 어디에 바르라고 하셨나요?","options":[{"label":"문 양쪽 기둥과 문 위","ok":true},{"label":"문 아래 문지방","basis":"본문에 없음"},{"label":"문짝 한가운데","basis":"본문에 없음"}]}},{"type":"multi","ref":"출 12:8","prompt":"성경책에서 출애굽기 12장 8절을 찾아 읽어 보세요.","confirm":{"prompt":"그 밤에 함께 먹으라고 한 것을 모두 고르세요.","options":[{"label":"불에 구운 고기","ok":true},{"label":"무교병","ok":true},{"label":"꿀","basis":"본문에 없음"},{"label":"쓴 나물","ok":true},{"label":"포도주","basis":"본문에 없음"}]}}],"t2":[{"type":"find","ref":"출 12:21-23","prompt":"성경책에서 출애굽기 12장 21절부터 23절까지 읽어 보세요.","confirm":{"prompt":"아침까지 한 사람도 집 문밖에 나가지 말라고 한 까닭은 무엇인가요?","options":[{"label":"여호와께서 문에 바른 피를 보시면 그 집을 넘어가시고, 멸하는 자가 들어와 치지 못하게 하신다고 했기 때문에","ok":true},{"label":"애굽 군사들이 밤새 길을 지키다가, 문밖에 나온 이스라엘 사람을 붙잡아 간다고 했기 때문에","basis":"본문에 없음"},{"label":"그 밤에 양고기를 먹고 나서, 아침까지 남은 것은 모두 불에 살라야 한다고 했기 때문에","basis":"출 12:10"}]}},{"type":"order","ref":"출 12:29-34","prompt":"성경책에서 출애굽기 12장 29절부터 34절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["여호와께서 밤중에 애굽 땅의 처음 난 것을 치셨다","애굽에 큰 울음소리가 있었다","바로가 밤에 모세와 아론을 불러 떠나라고 했다","애굽 사람들이 백성을 서둘러 내보내려고 재촉했다","백성이 반죽 그릇을 옷에 싸서 어깨에 멨다"]}],"t3":[{"type":"find","refs":["출 12:11","출 12:33","출 12:39"],"prompt":"출애굽기 12장 11절, 33절, 39절을 함께 찾아 읽어 보자.","confirm":{"prompt":"세 곳에 공통으로 나타나는 그 밤의 모습은 무엇인가?","options":[{"label":"서두름이다. 급히 먹으라고 하셨고, 애굽 사람들은 속히 내보내려 재촉했고, 백성은 지체할 수 없었다","ok":true},{"label":"머무름이다. 모세의 말대로 집집마다 아침까지 한 사람도 문밖에 나가지 않고 집 안에 머물렀다","basis":"출 12:22"},{"label":"넉넉함이다. 백성은 배불리 먹고 쉬었으며, 길에서 먹을 양식도 넉넉히 마련해 떠났다","basis":"본문에 없음"}]}},{"type":"match","refs":["출 11:7","출 12:28","출 12:31"],"prompt":"출애굽기 11장 7절, 12장 28절, 12장 31절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"출 11:7","text":"여호와께서 애굽 사람과 이스라엘을 구별하신다고 하셨다"},{"ref":"출 12:28","text":"이스라엘 자손이 물러가 명하신 대로 행했다"},{"ref":"출 12:31","text":"바로가 밤에 모세와 아론을 불러 떠나라고 했다"}],"after":"세 곳을 이으면, 구별하겠다고 하신 말씀이 있었고 이스라엘은 명하신 대로 행했으며, 그 밤에 바로가 떠나라고 했다."}]},"cards":[{"ref":"출 12:13","title":"피를 볼 때에 넘어가심"},{"ref":"출 12:42","title":"여호와의 밤"}],"close":{"t1":{"kind":"prayer","text":"하나님, 이스라엘 자손을 애굽 땅에서 인도해 내신 밤을 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 출애굽기 12장 21절부터 28절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"출 11:1-12:42에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 타임머신이 애굽 땅에 비상 착륙하면서 공기 거름망이 찢어졌어요. 길에 떨어진 것으로 대신 쓸 재료를 찾고, 이스라엘 자손의 집에서는 피를 바르는 일만 빼고 식구들을 도와요.","t2":"최현 박사예요. 타임머신이 애굽 땅에 비상 착륙하면서 공기 거름망이 찢어졌어요. 이 시대에는 맞는 부속이 없으니 길에 떨어진 것 가운데 대신 쓸 재료를 찾아보세요. 이스라엘 자손의 집에 머물게 되면 그 집 사람들이 하는 평범한 일만 돕고, 피를 바르는 일처럼 그 집 사람이 하는 일에는 손대지 말아요.","t3":"최현 박사다. 타임머신이 애굽 땅에 비상 착륙하면서 공기 거름망이 찢어졌다. 이 시대에는 맞는 부속이 없으니 길에 떨어진 것으로 대신 만들어야 한다. 이스라엘 자손의 집에 머물게 되면 그 집 사람들이 하는 평범한 일만 돕자. 피를 바르는 일처럼 본문이 그 집 사람이 한다고 적은 일에는 손대지 않는다."},"materials":[{"key":"oxhair","name":"소털","basis":"출 12:38","use":"소털을 촘촘하게 겹쳐 넣으면 찢어진 공기 거름망 대신 쓸 수 있어요.","how":"라암셋에서 숙곳으로 가는 길가, 소 떼가 지나간 자리에 떨어진 소털 몇 가닥을 줍는다. 소를 붙잡거나 털을 뽑지 않고, 무리의 짐과 가축에는 손대지 않는다.","line":"소 떼가 지나간 길가에서 소털 몇 가닥을 찾았어!"}],"companion":{"who":"모세","ref":"출 12:21","when":"after","talks":[{"ask":{"who":"hyu","text":"그 밤에 사람들이 집 밖으로 나가도 됐어요?"},"answer":{"t1":"모세는 장로들에게, 아침까지 아무도 자기 집 문밖으로 나가지 말라고 말했어요.","t2":"모세는 이스라엘의 모든 장로를 불러, 날이 밝을 때까지 아무도 자기 집 문밖으로 나가지 말라고 했어요.","t3":"모세는 이스라엘의 모든 장로를 불러, 아침이 될 때까지 아무도 자기 집 문밖으로 나가지 말라고 일렀다."},"ref":"출 12:21-22","open":"출 12:22"},{"ask":{"who":"onwoo","text":"이 일을 언제까지 지키라고 하셨어요?"},"answer":{"t1":"모세는 이 일을 규례로 삼아 자손과 함께 영원히 지키라고 말했어요.","t2":"모세는 이 일을 규례로 삼아 자손과 함께 영원히 지키라고 했어요. 여호와께서 주시는 땅에 들어가서도 이 예식을 지키라고 했어요.","t3":"모세는 이 일을 규례로 삼아 그들과 그 자손이 영원히 지키라고 했고, 여호와께서 약속하신 대로 주시는 땅에 이르러서도 이 예식을 지키라고 했다."},"ref":"출 12:24-25","open":"출 12:24"}]},"today":[{"q":"왜 이 밤을 대대로 지키라고 했어요?","a":{"t1":"성경은 여호와께서 이스라엘 자손을 애굽 땅에서 이끌어 내신 일 때문에, 그 밤을 대대로 지키라고 말해요.","t2":"하나님은 이 날을 기념하여 여호와의 절기로 대대로 지키라고 하셨어요. 성경은 여호와께서 이스라엘 자손을 애굽 땅에서 이끌어 내신 일 때문에, 그 밤을 여호와 앞에 지킬 여호와의 밤이라고 말해요.","t3":"하나님은 이 날을 기념하여 여호와의 절기로 삼고 영원한 규례로 대대로 지키라고 하셨다(출 12:14). 무교절을 지키라고 하실 때에는, 바로 이 날에 그들의 군대를 애굽 땅에서 인도하여 내셨기 때문이라고 하셨다(출 12:17). 성경은 여호와께서 그들을 애굽 땅에서 이끌어 내신 일 때문에 그 밤이 여호와 앞에 지킬 여호와의 밤이며 이스라엘 자손이 대대로 지킬 밤이라고 말한다(출 12:42)."},"refs":["출 12:14","출 12:17","출 12:42"]}],"help":{"who":"이스라엘 자손의 한 집","steps":[{"kind":"watch","after":4,"title":"곁에서 보기 · 문에 바른 피","basis":"출 12:22","text":{"t1":"이 집 사람이 우슬초 묶음을 그릇의 피에 적셔 문에 발랐어요.","t2":"이 집 사람이 우슬초 묶음을 그릇에 담은 피에 적셔 문에 발랐어요.","t3":"이 집 사람이 우슬초 묶음을 그릇에 담은 피에 적셔 문에 발랐다. 각 집이 그렇게 하라는 말씀이 있었고, 이스라엘 자손은 그대로 행했다. 탐험대는 손대지 않고 곁에서 본다."},"say":{"who":"hyu","text":"문의 어디에 발랐는지는 12장 7절에서 확인하자."}},{"kind":"do","after":4,"title":"띠·신·지팡이 챙기기","basis":"출 12:11","text":{"t1":"우리는 이스라엘 자손의 한 집에 함께 있어요. 오늘 밤 양을 먹을 때는 띠를 매고, 신을 신고, 지팡이를 손에 들고 급히 먹으라고 하셨어요. 식구들이 챙기도록 도와요.","t2":"우리는 이스라엘 자손의 한 집에 머물고 있어요. 모세와 아론이 전한 여호와의 명령대로, 이 집 식구들은 띠를 매고 신을 신고 지팡이를 손에 든 채 급히 먹어야 해요. 챙기는 일을 도와요.","t3":"탐험대는 이스라엘 자손의 한 집에 머문다. 양을 먹을 때에는 띠를 허리에 매고, 신을 신고, 지팡이를 손에 들라는 말씀이 있었다. 식구들이 그것을 챙기도록 돕는다."},"tasks":["허리띠 건네기","신 챙겨 주기","지팡이 손에 쥐여 주기"],"done":{"who":"onwoo","text":"다 챙겼어. 띠를 매고, 신을 신고, 지팡이를 손에 쥐었어."}},{"kind":"stay","after":4,"title":"아침까지 집 안에","basis":"출 12:22-23","text":{"t1":"모세가 전한 대로, 이 집 식구들은 아침까지 문밖에 나가지 않아요. 우리도 이 집 안에서 함께 기다려요.","t2":"모세가 전한 대로, 이 집 식구들은 아침까지 한 사람도 문밖에 나가지 않아요. 우리도 피를 바른 문 안쪽에서 함께 기다려요.","t3":"아침까지 아무도 자기 집 문밖에 나가지 말라고 했다(12:22). 이 집 식구들은 그대로 문 안에 머문다. 탐험대도 피를 바른 문 안쪽에서 함께 기다린다."},"wait":"문 안에서 함께 기다리기","say":{"who":"choeon","text":"우리는 이 집 문 안에 있어. 아침까지 나가지 않을 거야."}},{"kind":"do","after":5,"title":"반죽 그릇 싸기","basis":"출 12:34","text":{"t1":"애굽 사람들이 어서 떠나라고 재촉했어요. 이 집 식구들이 반죽 그릇을 옷에 싸서 어깨에 메도록 도와요.","t2":"애굽 사람들이 재촉해서 백성은 서둘러 떠나야 했어요. 아직 부풀지 않은 반죽을 그릇째 옷에 싸서 어깨에 메는 일을 도와요.","t3":"애굽 사람들이 백성을 재촉했다. 백성은 아직 부풀지 않은 반죽을 그릇째 옷에 싸서 어깨에 메었다. 탐험대는 이 집 식구들이 짐을 꾸리는 것을 돕는다."},"tasks":["반죽 그릇 들어 주기","옷으로 싸기","어깨에 멜 수 있게 건네기"],"done":{"who":"choeon","text":"반죽이 아직 부풀지도 않았어. 그릇째 싸서 메고 떠나는구나."}},{"kind":"ask","after":"gates","title":"그 밤의 일은 무슨 뜻이에요?","basis":"출 12:26-27","by":"이 집 사람","ask":{"who":"choeon","text":"그 밤에 피를 바르고 양을 먹은 일은 무슨 뜻이에요?"},"answer":{"t1":"이 집 사람은, 뒷날 자녀가 물으면 이렇게 말하라고 모세가 전했다고 들려주었어요. 이것은 여호와의 유월절이고, 여호와께서 애굽 사람을 치실 때 이스라엘 자손의 집은 넘어가셔서 그 집들을 구원하셨다고요.","t2":"이 집 사람은, 뒷날 자녀가 이 예식의 뜻을 물으면 이렇게 대답하라고 모세가 전한 말을 들려주었어요. 이것은 여호와께 드리는 유월절 제사이고, 여호와께서 애굽 사람을 치실 때 이스라엘 자손의 집은 넘어가셔서 그 집들을 구원하셨다고요.","t3":"이 집 사람은, 뒷날 자녀가 이 예식의 뜻을 물을 때 하라고 모세가 장로들에게 전한 말을 들려주었다. 이것은 여호와께 드리는 유월절 제사이며, 여호와께서 애굽 사람을 치시던 때에 이스라엘 자손의 집들은 넘어가셔서 그 집들을 구원하셨다는 것이다."},"read":{"t1":{"type":"find","ref":"출 12:13","prompt":"성경책에서 출애굽기 12장 13절을 찾아 읽어 보세요.","confirm":{"prompt":"집에 바른 피는 그 집에 무엇이 되었나요?","options":[{"label":"표적","ok":true},{"label":"장식","basis":"본문에 없음"},{"label":"문패","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"출 12:26-27","prompt":"성경책에서 출애굽기 12장 26절과 27절을 읽어 보세요.","confirm":{"prompt":"뒷날 자녀가 이 예식의 뜻을 물으면, 무엇이라고 대답하라고 했나요?","options":[{"label":"여호와의 유월절 제사로, 애굽 사람을 치시던 때 이스라엘 집들을 넘어가 구원하셨다고","ok":true},{"label":"이레 동안 무교병을 먹는 절기로, 첫날에 집에서 누룩을 없애라고 하셨다고","basis":"출 12:15"},{"label":"먼 길을 떠나기 전에 배불리 먹는 밥으로, 광야에서 굶주리지 않게 미리 먹어 두었다고","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["출 12:13","출 12:23","출 12:27"],"prompt":"출애굽기 12장 13절, 23절, 27절을 함께 찾아 읽어 보자.","confirm":{"prompt":"세 곳을 이어 읽으면, 문에 바른 피에 대해 성경은 무엇을 말하는가?","options":[{"label":"피는 그 집의 표적이 되었고, 여호와께서 그 피를 보시고 그 문을 넘으셔서 멸하는 자가 들어오지 못했으며, 뒷날 자녀에게 그 밤에 집을 구원하셨다고 말하게 하셨다","ok":true},{"label":"피는 그 집의 표적이 되었고, 여호와께서 그 피를 보시면 멸하는 자를 보내어 그 집 문을 지키게 하셨으며, 뒷날 자녀에게 그 밤에 집을 구원하셨다고 말하게 하셨다","basis":"본문에 없음"},{"label":"피는 애굽 사람들이 보는 표시가 되었고, 여호와께서 그 피를 보시고 그 문을 넘으셔서 멸하는 자가 들어오지 못했으며, 뒷날 자녀에게 그 밤에 집을 구원하셨다고 말하게 하셨다","basis":"본문에 없음"}]}}},"nt":{"ref":"고전 5:7","text":"신약의 고린도전서 5장 7절은 그리스도를 '우리의 유월절 양'이라고 부르고, 그가 희생되셨다고 말한다. 유월절 양과 그리스도의 연결은 목사님 감수를 마친 뒤 확정한다."}}]}},"has3d":false,"epic":false},"OT-11":{"id":"OT-11","era":3,"title":"바다가 갈라지다","ref":"출 14:1-31","place":"바다와 믹돌 사이 비하히롯 앞, 바알스본 맞은편 바닷가","review":{"required":true,"topics":["하나님의 주권과 사람의 책임(출 14:4, 14:8, 14:17)","재앙과 심판(출 14:26-28)","구약 사건의 신약적 의미(히 11:29)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"출 14:1-9","open":"출 14:2","focus":"camp","text":{"t1":"하나님은 이스라엘 자손이 바닷가에 장막을 치게 하셨어요. 애굽 왕 바로는 병거와 군대를 이끌고 뒤쫓아 왔어요.","t2":"하나님은 모세에게, 이스라엘 자손이 돌이켜 바다와 믹돌 사이 비하히롯 앞 바닷가에 장막을 치게 하라고 하셨어요. 바로와 신하들은 마음이 바뀌었는데, 왜 그랬는지는 5절에서 찾아봐요. 바로는 가려 뽑은 병거 육백 대와 애굽의 모든 병거를 이끌고 뒤쫓아, 바닷가 장막 친 곳까지 따라왔어요.","t3":"여호와께서는 모세에게, 이스라엘 자손이 돌이켜 바다와 믹돌 사이 비하히롯 앞, 바알스본 맞은편 바닷가에 장막을 치게 하라고 하셨고, 이스라엘 자손은 그대로 했다. 백성이 도망했다는 말이 애굽 왕에게 전해지자 바로와 신하들은 마음이 변했다. 하나님이 바로를 두고 하신 말씀과 바로와 신하들이 한 말은 3절과 5절을 이어 읽어 보자. 바로는 자기 병거를 갖추고 백성을 데리고 나섰고, 가려 뽑은 병거 육백 대와 애굽의 모든 병거를 동원했는데 장관들이 그것을 다 거느렸다. 여호와께서 바로 왕의 마음을 강퍅하게 하셨으므로 그는 담대히 나간 이스라엘 자손의 뒤를 따랐고, 말과 병거와 마병과 군대가 바알스본 맞은편 비하히롯 곁 바닷가의 장막 친 곳에 이르렀다."},"say":{"who":"hyu","text":"바다와 믹돌 사이, 비하히롯 앞 바닷가야. 뒤에서는 애굽의 병거들이 오고 있어. 일지에 적어 둘게."}},{"ref":"출 14:10-14","focus":"people","text":{"t1":"이스라엘 자손은 뒤따라온 애굽 사람들을 보고 몹시 두려워했어요. 모세는 두려워하지 말라고 했는데, 이어서 한 말은 13절과 14절에서 찾아봐요.","t2":"바로가 가까이 오자 이스라엘 자손은 몹시 두려워하며 여호와께 부르짖었어요. 그리고 모세에게, 왜 애굽에서 이끌어 내어 광야에서 죽게 하느냐고 했어요. 모세는 두려워하지 말고 가만히 서서 여호와께서 오늘 행하시는 구원을 보라고 했어요. 여호와께서 그들을 위해 싸우실 것이니 가만히 있으라고 했어요.","t3":"바로가 가까이 올 때 이스라엘 자손은 눈을 들어 애굽 사람들이 뒤에 이른 것을 보고 몹시 두려워하여 여호와께 부르짖었다. 또 모세에게, 애굽에 묻힐 곳이 없어서 자기들을 이끌어 내어 광야에서 죽게 하느냐고 했고, 애굽에서 이미 자기들을 내버려 두라고 말하지 않았느냐고 했으며, 애굽 사람을 섬기는 편이 광야에서 죽는 것보다 낫겠다고 했다. 모세는 백성에게 두려워하지 말고 가만히 서서 여호와께서 오늘 그들을 위해 행하시는 구원을 보라고 했고, 오늘 본 애굽 사람을 다시는 영원히 보지 못할 것이라고 했다. 모세가 이어서 한 말은 14절에서 직접 읽어 보자."},"say":{"who":"choeon","text":"이스라엘 사람들이 눈을 들어 뒤쪽을 보고 있어. 애굽 사람들이 바로 뒤까지 왔어!"}},{"ref":"출 14:15-18","open":"출 14:15-16","focus":"moses","text":{"t1":"하나님은 모세에게 백성을 앞으로 나아가게 하라고 하셨어요. 지팡이를 들고 바다 위로 손을 내밀라고 하셨어요.","t2":"하나님은 모세에게 이스라엘 자손을 앞으로 나아가게 하라고 하셨어요. 그리고 지팡이를 들고 바다 위로 손을 내밀라고 하셨는데, 왜 그렇게 하라고 하셨는지는 16절에서 찾아봐요.","t3":"여호와께서는 모세에게 어찌하여 부르짖느냐고 하시며, 이스라엘 자손을 앞으로 나아가게 하라고 하셨다. 지팡이를 들고 바다 위로 손을 내밀어 바다가 갈라지게 하면 이스라엘 자손이 바다 가운데 마른 땅으로 지나갈 것이라고 하셨다. 애굽 사람들을 두고 이어서 하신 말씀은 17절과 18절에 있다."},"say":{"who":"onwoo","text":"하나님이 모세에게 하신 말씀은 14장 15절과 16절에 있어. 성경책에서 직접 읽어 보자."}},{"ref":"출 14:19-20","focus":"pillar","text":{"t1":"구름 기둥이 자리를 옮겼어요. 어디에서 어디로 옮겼는지는 19절에서 찾아봐요.","t2":"이스라엘 진 앞에서 가던 하나님의 사자가 뒤로 옮겨 갔고, 구름 기둥도 앞에서 뒤로 옮겨 갔어요. 그날 밤 애굽 진은 밤새도록 이스라엘 진에 가까이 오지 못했는데, 왜 그랬는지는 20절에서 찾아봐요.","t3":"이스라엘 진 앞에서 가던 하나님의 사자가 자리를 옮겼고, 구름 기둥도 옮겨 갔다. 구름 기둥이 어디에서 어디로 옮겨 어디에 섰는지는 19절과 20절에 있다. 그날 밤 애굽 진은 밤새도록 이스라엘 진에 가까이 오지 못했다."},"say":{"who":"hyu","text":"구름 기둥이 자리를 옮겼어. 일지에 적어 둘게."}},{"ref":"출 14:21-22","focus":"sea","text":{"t1":"모세가 손을 바다 위로 뻗자, 하나님이 밤새 큰 동풍으로 바닷물을 물리셨어요. 바다가 마른 땅이 되었고, 이스라엘 자손은 그 가운데로 걸어갔어요.","t2":"모세가 바다 위로 손을 내밀자, 여호와께서 밤이 새도록 바닷물이 물러가게 하셨어요. 무엇으로 그렇게 하셨는지는 21절에서 찾아봐요. 물이 갈라지고 바다는 마른 땅이 되었어요. 이스라엘 자손은 바다 가운데 마른 땅으로 걸어갔고, 물은 그들의 왼쪽과 오른쪽에서 벽이 되었어요.","t3":"모세가 바다 위로 손을 내밀자, 여호와께서 밤이 새도록 바닷물이 물러가게 하셨다. 무엇으로 그렇게 하셨는지는 21절에 있다. 물이 갈라지고 바다는 마른 땅이 되었다. 이스라엘 자손은 바다 가운데 마른 땅으로 걸어갔고, 물은 그들의 왼쪽과 오른쪽에서 벽이 되었다."},"say":{"who":"choeon","text":"바다가 갈라졌어!"}},{"ref":"출 14:23-28","open":"출 14:26","focus":"chariots","text":{"t1":"애굽 군대가 그 뒤를 따라 바다로 들어왔어요. 하나님의 말씀대로 모세가 다시 손을 뻗자, 바닷물이 돌아와 바로의 군대를 덮었어요.","t2":"애굽 사람들과 바로의 말과 병거와 마병이 뒤쫓아 바다 가운데로 들어왔어요. 새벽에 무슨 일들이 어떤 차례로 일어났는지는 24절부터 27절까지 읽어 봐요. 물이 다시 흘러, 뒤쫓아 들어온 바로의 군대를 다 덮었어요.","t3":"애굽 사람들과 바로의 말과 병거와 마병이 다 뒤쫓아 바다 가운데로 들어왔다. 새벽에 여호와께서 불과 구름 기둥 가운데서 애굽 사람들의 군대를 보시고 그들을 어지럽게 하셨으며, 병거 바퀴를 벗겨 달리기 몹시 어렵게 하셨다. 그때 애굽 사람들이 한 말은 25절에 있다. 여호와께서는 모세에게 바다 위로 손을 내밀어 물이 애굽 사람들과 병거와 마병 위로 되돌아오게 하라고 하셨다. 모세가 손을 내밀자 새벽이 되어 바다가 제 힘을 되찾았고, 애굽 사람들은 물을 거슬러 도망했으나 여호와께서 그들을 바다 가운데 엎으셨다. 물이 다시 흘러 병거와 기병을 덮었고, 뒤쫓아 바다에 들어간 바로의 군대는 하나도 남지 않았다."},"say":{"who":"onwoo","text":"이 대목은 성경이 적은 만큼만 읽자. 14장 26절부터 28절이야."}},{"ref":"출 14:29-31","focus":"shore","text":{"t1":"이스라엘 자손은 마른 땅이 된 바다 가운데를 지나갔고, 그날 하나님이 이스라엘을 구원하셨어요. 그 일을 본 백성이 어떻게 했는지는 31절에서 찾아봐요.","t2":"이스라엘 자손은 바다 가운데 마른 땅으로 지나갔고, 물은 좌우에서 벽이 되어 있었어요. 그날 여호와께서 애굽 사람의 손에서 이스라엘을 구원하셨어요. 그 뒤 백성이 여호와를 경외하고 여호와와 모세를 믿게 된 까닭은 31절에서 찾아봐요.","t3":"이스라엘 자손은 바다 가운데 마른 땅으로 지나갔고 물은 좌우에서 벽이 되어 있었다. 그날 여호와께서 이렇게 애굽 사람의 손에서 이스라엘을 구원하셨고, 이스라엘은 바닷가에서 죽은 애굽 사람들을 보았다. 그 일을 보고 백성이 어떻게 되었는지는 31절에 있다."},"say":{"who":"hyu","text":"이스라엘 자손은 마른 땅으로 지나갔어. 그날 있었던 일을 순서대로 일지에 적어 둘게."}}],"gates":{"t1":[{"type":"find","ref":"출 14:10","prompt":"성경책에서 출애굽기 14장 10절을 찾아 읽어 보세요.","confirm":{"prompt":"이스라엘 자손이 몹시 두려워서 누구에게 부르짖었나요?","options":[{"label":"여호와","ok":true},{"label":"애굽 왕 바로","basis":"출 5:15"},{"label":"아론","basis":"본문에 없음"}]},"inStory":"여호와라는 이름은 이야기 곳곳에 나오지만, 두려워하던 백성이 여호와께 부르짖은 일은 8~10세 이야기 글에 없고 14:10에서만 안다"},{"type":"multi","ref":"출 14:31","prompt":"성경책에서 출애굽기 14장 31절을 찾아 읽어 보세요.","confirm":{"prompt":"여호와께서 하신 큰 일을 본 백성이 한 일을 모두 고르세요.","options":[{"label":"여호와를 경외했어요","ok":true},{"label":"여호와께 노래했어요","basis":"출 15:1"},{"label":"여호와를 믿었어요","ok":true},{"label":"모세를 원망했어요","basis":"출 15:24"},{"label":"모세를 믿었어요","ok":true}]}}],"t2":[{"type":"find","ref":"출 14:15-16","prompt":"성경책에서 출애굽기 14장 15절과 16절을 읽어 보세요.","confirm":{"prompt":"하나님이 처음에 모세에게 지팡이를 든 손을 바다 위로 뻗으라고 하신 까닭은 무엇인가요?","options":[{"label":"바다를 갈라 백성이 그 가운데 마른 땅으로 건너가게 하시려고","ok":true},{"label":"바닷물로 애굽 진을 막는 담을 쌓게 하시려고","basis":"본문에 없음"},{"label":"물이 다시 흘러 애굽 군대와 병거를 덮게 하시려고","basis":"출 14:26"}]}},{"type":"order","ref":"출 14:23-27","prompt":"성경책에서 출애굽기 14장 23절부터 27절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["애굽 군대가 이스라엘의 뒤를 따라 바다로 들어왔다","여호와께서 애굽 군대를 혼란에 빠뜨리시고 병거 바퀴를 벗기셨다","애굽 사람들이 이스라엘 앞에서 도망하자고 했다","모세에게 다시 손을 바다 위로 내밀라는 여호와의 말씀이 있었다","모세가 손을 내밀자 바다가 제 힘을 되찾았다"]}],"t3":[{"type":"find","refs":["출 14:18","출 14:25"],"prompt":"출애굽기 14장 18절과 25절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 애굽 사람들을 두고 무엇을 알 수 있는가?","options":[{"label":"하나님은 애굽 사람들이 하나님을 여호와인 줄 알게 되리라고 하셨고, 바다 가운데서 애굽 사람들은 여호와께서 이스라엘 편에서 싸우신다며 도망하자고 했다","ok":true},{"label":"하나님은 애굽 사람들이 끝내 하나님을 알지 못하리라고 하셨고, 바다 가운데서 애굽 사람들은 이스라엘을 곧 붙잡겠다며 서로 북돋웠다","basis":"본문에 없음"},{"label":"하나님은 애굽 사람들이 이스라엘 자손을 두려워하게 되리라고 하셨고, 바다 가운데서 애굽 사람들은 바로를 떠나 이스라엘 편에 서겠다고 했다","basis":"본문에 없음"}]}},{"type":"match","refs":["출 14:7","출 14:10","출 14:13"],"prompt":"출애굽기 14장 7절, 10절, 13절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"출 14:7","text":"바로가 가려 뽑은 병거 육백 대와 애굽의 모든 병거를 이끌고 나섰다"},{"ref":"출 14:10","text":"뒤에 이른 애굽 사람들을 보고 백성이 몹시 두려워 여호와께 부르짖었다"},{"ref":"출 14:13","text":"모세가 겁내지 말고 그대로 서서 여호와께서 이루실 구원을 보라고 했다"}],"after":"세 곳을 이으면, 바로는 가려 뽑은 병거 육백 대와 애굽의 모든 병거를 이끌고 뒤쫓았고, 뒤에 이른 그들을 본 백성은 몹시 두려워 부르짖었으며, 모세는 겁내지 말고 여호와의 구원을 보라고 했다."}]},"cards":[{"ref":"출 14:14","title":"여호와께서 싸우신다"},{"ref":"출 14:22","title":"좌우에 벽이 된 물"}],"close":{"t1":{"kind":"prayer","text":"하나님, 이스라엘 자손이 바다 가운데 마른 땅으로 지나간 이야기를 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 출애굽기 14장 13절부터 22절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"출 14:1-31에서 새로 알게 된 사실을 한 가지 적어 보자."}},"quests":[{"part":"handle","name":"손잡이","line":"손잡이를 찾았어! 장막들에서 떨어진 바닷가 모래 위에 있었네.","found":"탐지기가 바닷가에 친 장막들 쪽을 가리켜요.","say":{"who":"hyu","text":"탐지기 바늘이 바닷가의 장막 쪽으로 돌아갔어. 장막 사이로 들어가지는 말고 바깥쪽에서 찾자."},"q":{"t1":{"type":"find","ref":"출 14:3","prompt":"성경책에서 출애굽기 14장 3절을 찾아 읽어 보세요.","confirm":{"prompt":"하나님은 바로가 이스라엘 자손이 어디에 갇혔다고 말할 거라고 하셨나요?","options":[{"label":"광야","ok":true},{"label":"바다 한가운데","basis":"본문에 없음"},{"label":"높은 산골짜기","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"출 14:5-7","prompt":"성경책에서 출애굽기 14장 5절부터 7절까지 읽어 보세요.","confirm":{"prompt":"바로와 신하들이 마음을 바꾸어 병거를 갖추고 나선 까닭은 무엇인가요?","options":[{"label":"이스라엘을 놓아 보내 자기들을 섬기지 않게 한 일을 두고 마음이 변했기 때문에","ok":true},{"label":"모세와 아론이 애굽의 은금 패물을 더 받으러 다시 온다는 말을 들었기 때문에","basis":"본문에 없음"},{"label":"이스라엘이 약속한 날이 지나도 애굽 땅으로 되돌아오지 않았기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["출 14:3","출 14:5"],"prompt":"출애굽기 14장 3절과 5절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 하나님이 바로를 두고 하신 말씀과 바로와 신하들이 한 말은 어떠한가?","options":[{"label":"하나님은 바로가 이스라엘 자손이 광야에 갇혔다고 말하리라 하셨고, 바로와 신하들은 이스라엘을 놓아 보내 자기들을 섬기지 않게 한 일을 두고 어찌하여 그리했느냐고 했다","ok":true},{"label":"하나님은 바로가 이스라엘 자손이 광야에 갇혔다고 말하리라 하셨고, 바로와 신하들은 이스라엘을 놓아 보낸 일을 잘했다고 했다","basis":"본문에 없음"},{"label":"하나님은 바로가 이스라엘 자손이 바다를 건너 멀리 달아났다고 말하리라 하셨고, 바로와 신하들은 이스라엘을 놓아 보내 자기들을 섬기지 않게 한 일을 두고 어찌하여 그리했느냐고 했다","basis":"본문에 없음"}]}}}},{"part":"bulb","name":"전구","line":"전구를 찾았어! 진 뒤쪽 가장자리에 있었네.","found":"탐지기가 진 뒤쪽을 가리켜요.","say":{"who":"choeon","text":"진 뒤쪽이야! 장막 바깥 가장자리를 따라 가 보자."},"q":{"t1":{"type":"find","ref":"출 14:19","prompt":"성경책에서 출애굽기 14장 19절을 찾아 읽어 보세요.","confirm":{"prompt":"구름 기둥은 어디에서 어디로 옮겨 갔나요?","options":[{"label":"이스라엘 진 앞에서 뒤로","ok":true},{"label":"이스라엘 진 뒤에서 앞으로","basis":"본문에 없음"},{"label":"바다 건너편에서 진 한가운데로","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"출 14:19-20","prompt":"성경책에서 출애굽기 14장 19절과 20절을 읽어 보세요.","confirm":{"prompt":"밤새도록 애굽 진이 이스라엘 진에 가까이 오지 못한 까닭은 무엇인가요?","options":[{"label":"구름 기둥이 두 진 사이에 섰고, 한쪽에는 구름과 어둠이 있고 다른 쪽은 밤이 밝았기 때문에","ok":true},{"label":"구름 기둥이 진 뒤로 옮겨 가서, 애굽 진 쪽에 밤새 큰비를 쏟았기 때문에","basis":"본문에 없음"},{"label":"여호와께서 애굽 병거의 바퀴를 벗기셔서 그 군대가 달리기 어려웠기 때문에","basis":"출 14:25"}]}},"t3":{"type":"find","refs":["출 13:21","출 14:19"],"prompt":"출애굽기 13장 21절과 14장 19절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 구름 기둥이 바닷가에서 한 일은 그전과 어떻게 달랐는가?","options":[{"label":"그전에는 여호와께서 낮에 구름 기둥으로 백성 앞에서 길을 인도하셨는데, 바닷가에서는 구름 기둥이 진 앞에서 뒤로 옮겨 갔다","ok":true},{"label":"그전에는 여호와께서 낮에 구름 기둥으로 백성 앞에서 길을 인도하셨는데, 바닷가에서는 구름 기둥이 진 앞에서 바다 위로 옮겨 갔다","basis":"본문에 없음"},{"label":"그전에는 여호와께서 밤에만 불 기둥으로 백성 앞에서 길을 비추셨는데, 바닷가에서는 구름 기둥이 진 앞에서 산 위로 옮겨 갔다","basis":"본문에 없음"}]}}}},{"part":"battery","name":"건전지","line":"건전지를 찾았어! 바닷가 이쪽, 물가에서 조금 떨어진 곳에 있었네.","found":"탐지기가 바닷가 물가 쪽을 가리켜요.","say":{"who":"onwoo","text":"바닷가까지만 가자. 바다 안으로는 들어가지 말자. 우리는 지켜보는 사람이야."},"q":{"t1":{"type":"find","ref":"출 14:22","prompt":"성경책에서 출애굽기 14장 22절을 찾아 읽어 보세요.","confirm":{"prompt":"이스라엘 자손의 왼쪽과 오른쪽에서 물은 무엇이 되었나요?","options":[{"label":"벽","ok":true},{"label":"얼음","basis":"본문에 없음"},{"label":"안개","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"출 14:21-22","prompt":"성경책에서 출애굽기 14장 21절과 22절을 읽어 보세요.","confirm":{"prompt":"모세가 손을 내민 뒤, 밤새도록 바닷물이 물러가 바다가 마른 땅이 된 것은 무엇 때문이었나요?","options":[{"label":"여호와께서 큰 동풍으로 바닷물을 뒤로 물리셨기 때문에","ok":true},{"label":"모세가 지팡이로 바닷물을 내리쳤기 때문에","basis":"본문에 없음"},{"label":"뜨거운 해가 바닷물을 말렸기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["출 10:13","출 14:21"],"prompt":"출애굽기 10장 13절과 14장 21절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 모세가 지팡이와 손을 든 뒤 여호와께서 하신 일은 어떠한가?","options":[{"label":"두 곳 모두 여호와께서 일으키신 동풍이 불었는데, 10장에서는 낮과 밤 내내 분 동풍이 메뚜기 떼를 몰고 왔고, 14장에서는 밤새도록 분 큰 동풍이 바닷물을 뒤로 물려 바다가 마른 땅이 되었다","ok":true},{"label":"10장에서는 모세가 지팡이를 들자 강한 서풍이 불어 메뚜기 떼를 홍해로 몰아갔고, 14장에서는 밤새도록 분 큰 동풍이 바닷물을 뒤로 물려 바다가 마른 땅이 되었다","basis":"출 10:19"},{"label":"10장에서는 낮과 밤 내내 분 동풍이 메뚜기 떼를 몰고 왔고, 14장에서는 모세가 손을 내밀자 밤새도록 구름 기둥이 바닷물을 밀어내어 바다가 마른 땅이 되었다","basis":"본문에 없음"}]}}}}],"mission":{"call":{"t1":"최현 박사예요. 타임머신이 바닷가에 비상 착륙하면서 손잡이와 전구와 건전지가 망가졌어요. 바닷가에서 대신 쓸 재료를 찾아보세요.","t2":"최현 박사예요. 타임머신이 비하히롯 앞 바닷가에 비상 착륙하면서 손잡이와 전구와 건전지가 망가졌어요. 이 시대에는 맞는 부속이 없으니 바닷가에서 구할 수 있는 것으로 대신 만들어야 해요. 재료는 바닷가에 떨어진 것만 줍고, 사람들의 장막과 물건은 가져오지 말아요.","t3":"최현 박사다. 타임머신이 비하히롯 앞 바닷가에 비상 착륙하면서 손잡이, 전구, 건전지가 망가졌다. 이 시대에는 맞는 부속이 없으니 바닷가에서 구할 수 있는 재료로 대신 만들어야 한다. 재료는 바닷가에 떨어진 것만 줍고, 사람들의 장막과 물건은 가져오지 말자. 일이 일어나는 자리에는 다가가지 말자."},"materials":[{"key":"pebble","name":"조약돌","basis":"출 14:2","use":"둥글고 매끈한 조약돌을 붙이면 손잡이 대신 쓸 수 있어요.","how":"장막들에서 멀찍이 떨어진 바닷가에서 조약돌 하나를 줍는다. 장막 사이로 들어가지 않는다.","line":"장막들에서 떨어진 바닷가에서 둥근 조약돌을 찾았어!"},{"key":"sand","name":"고운 모래","basis":"출 14:9","use":"고운 모래를 타임머신 열판으로 녹이면 유리가 되어서 깨진 전구 유리 대신 쓸 수 있어요.","how":"진 뒤쪽 가장자리 바닷가의 고운 모래를 한 줌 뜬다. 장막 사이로 들어가지 않고, 두 진 사이로도 들어가지 않는다.","line":"진 뒤쪽 가장자리에서 고운 모래를 한 줌 떴어!"},{"key":"salt","name":"소금 덩이","basis":"출 14:2","use":"소금을 물에 녹이면 전기가 흐르는 소금물이 되어서 건전지 대신 쓸 수 있어요.","how":"바닷가 이쪽, 물가에서 멀리 떨어진 땅에 하얗게 말라붙은 소금을 조금 긁어 모은다. 바다 쪽으로는 들어가지 않는다.","line":"바닷가 이쪽, 물가에서 멀리 떨어진 곳에서 하얗게 말라붙은 소금 덩이를 찾았어!"}],"companion":{"who":"모세","ref":"출 14:31","when":"after","talks":[{"ask":{"who":"choeon","text":"애굽 사람들이 뒤에 다가왔을 때 백성에게 뭐라고 하셨어요?"},"answer":{"t1":"모세는 백성에게 두려워하지 말라고 했어요. 가만히 서서 여호와께서 그날 그들을 위해 하실 구원을 보라고 했어요.","t2":"모세는 두려워하는 백성에게 겁내지 말고 가만히 서 있으라고 했어요. 그리고 여호와께서 그날 그들을 위해 행하실 구원을 보라고 했어요.","t3":"모세는 백성에게 두려워하지 말고 가만히 서서, 여호와께서 그날 그들을 위하여 행하실 구원을 보라고 말했다."},"ref":"출 14:13","open":"출 14:13"},{"ask":{"who":"hyu","text":"그때 뒤쫓아 온 애굽 사람들을 두고는 뭐라고 하셨어요?"},"answer":{"t1":"모세는 백성이 그날 본 애굽 사람들을 다시는 보지 못할 것이라고 말했어요.","t2":"모세는 백성에게 두려워하지 말라고 하면서 이렇게도 말했어요. 그날 본 애굽 사람들을 다시는 영원히 보지 못할 것이라고 했어요.","t3":"모세는 백성에게, 그날 그들이 본 애굽 사람들을 다시는 영원히 보지 못할 것이라고 말했다."},"ref":"출 14:13","open":"출 14:13"}]},"today":[{"q":"바다가 정말 갈라질 수 있어요?","a":{"t1":"성경은 모세가 바다 위로 손을 내밀자 하나님이 밤새 큰 동풍을 써서 바닷물을 물리셨다고 말해요. 그래서 바다가 마른 땅이 되었다고 해요.","t2":"성경은 모세가 바다 위로 손을 내밀자, 여호와께서 큰 동풍으로 밤이 새도록 바닷물을 뒤로 물리셨다고 기록해요. 물이 갈라지고 바다가 마른 땅이 되어, 이스라엘 자손이 바다 가운데로 걸어갔어요. 성경은 여호와께서 애굽 사람들에게 하신 큰 일을 이스라엘이 보았다고 해요.","t3":"성경은 모세가 바다 위로 손을 내밀자 여호와께서 큰 동풍으로 밤이 새도록 바닷물을 뒤로 물리셨고, 물이 나뉘어 바다 밑이 마른 땅이 되었다고 기록한다(출 14:21). 이스라엘 자손은 바다 가운데 마른 땅으로 걸어갔고 물은 그들의 좌우에서 벽이 되었다(출 14:22). 이스라엘은 여호와께서 애굽 사람들에게 하신 큰 일을 보았다(출 14:31). 성경은 여기까지 말한다."},"refs":["출 14:21-22","출 14:31"]},{"q":"나도 무서울 때가 있는데, 그때 이스라엘 사람들은 어떻게 했어요?","a":{"t1":"이스라엘 사람들은 몹시 두려워서 여호와께 부르짖었어요. 모세는 두려워하지 말라고, 여호와께서 그들을 위해 싸우실 것이라고 했어요.","t2":"애굽 사람들이 뒤따라온 것을 보고 이스라엘 자손은 몹시 두려워하며 여호와께 부르짖었어요. 모세에게는 왜 자기들을 이끌어 내어 광야에서 죽게 하느냐고 따지기도 했어요. 모세는 두려워하지 말고 가만히 서서 여호와의 구원을 보라고 했고, 여호와께서 그들을 위해 싸우실 것이라고 했어요.","t3":"애굽 사람들이 뒤에 이른 것을 보고 이스라엘 자손은 몹시 두려워하여 여호와께 부르짖었고, 모세에게는 어찌하여 자기들을 이끌어 내어 광야에서 죽게 하느냐고 했다(출 14:10-12). 모세는 백성에게 두려워하지 말고 가만히 서서 여호와께서 그날 행하실 구원을 보라고 했고, 여호와께서 그들을 위하여 싸우실 것이니 가만히 있으라고 했다(출 14:13-14). 성경은 이 장면에서 여기까지 말한다."},"refs":["출 14:10-14"]}],"help":{"who":"바닷가에 장막을 친 이스라엘 자손","steps":[{"kind":"do","after":2,"title":"앞으로 나아갈 짐 꾸리기 돕기","basis":"출 14:2","text":{"t1":"하나님은 모세에게 백성을 앞으로 나아가게 하라고 하셨어요. 우리는 진 가장자리의 한 집 식구들 곁에서 짐 꾸리는 일을 도와요.","t2":"하나님은 모세에게 이스라엘 자손을 앞으로 나아가게 하라고 하셨어요. 우리는 바닷가 진 가장자리에 장막을 친 한 집 식구들 곁에서 짐을 꾸리고 나르는 일을 도와요. 짐은 식구들에게 건네고, 우리는 바닷가 이쪽에 남아요. 본문에 적힌 일이 아니라 탐험대 이야기예요.","t3":"이스라엘 자손은 바닷가에 장막을 쳤고(14:2, 14:9), 여호와께서는 모세에게 그들을 앞으로 나아가게 하라고 하셨다(14:15). 탐험대는 진 가장자리의 한 집 식구들 곁에서 짐을 꾸리고 나르는 일을 거든다. 짐은 식구들에게 건네고, 탐험대는 바다로 들어가는 행렬에 끼지 않고 바닷가 이쪽에 남는다. 본문에 적힌 일이 아니라 탐험대 이야기다."},"tasks":["짐 꾸러미 함께 묶기","짐을 함께 들어 옮기기","다 꾸린 짐 식구들에게 건네기"],"done":{"who":"onwoo","text":"짐을 다 건넸어. 우리는 여기 바닷가 이쪽에 남아서 지켜보자."}},{"kind":"stay","after":3,"title":"진 가장자리에서 함께 기다리기","basis":"출 14:19-20","text":{"t1":"구름 기둥이 자리를 옮겨 섰어요. 우리는 진 가장자리에서 이스라엘 자손과 함께 기다려요.","t2":"밤이 되었어요. 우리는 두 진 사이로 가지 않고, 진 가장자리에서 이스라엘 자손과 함께 기다려요.","t3":"밤이 되었다. 탐험대는 두 진 사이로 가지 않고, 진 가장자리에서 이스라엘 자손과 함께 기다린다."},"wait":"진 가장자리에서 기다리기","say":{"who":"hyu","text":"우리는 진 가장자리에 있어. 두 진 사이로는 가지 않을 거야."}},{"kind":"watch","after":4,"title":"곁에서 보기 · 바다 위로 뻗은 손","basis":"출 14:21-22","text":{"t1":"모세가 손을 바다 위로 뻗었어요. 바다가 갈라져 마른 땅이 되었어요. 우리는 바닷가 이쪽에서 지켜봐요.","t2":"모세가 손을 바다 위로 뻗자 물이 갈라지고 바다가 마른 땅이 되었어요. 이스라엘 자손은 그 가운데로 걸어가요. 우리는 함께 건너지 않고 바닷가 이쪽에서 지켜봐요.","t3":"모세가 손을 바다 위로 뻗었고, 물이 나뉘며 바다 밑이 마른 땅으로 드러났다(14:21). 백성은 그 가운데로 걸어 들어갔고, 그들의 왼쪽과 오른쪽에서 물이 벽처럼 섰다(14:22). 탐험대는 함께 건너지 않고 바닷가 이쪽에서 지켜본다."},"say":{"who":"onwoo","text":"우리는 건너지 않아. 바닷가 이쪽에서 지켜보자."}},{"kind":"ask","after":"gates","title":"바다에서 일어난 일은 무슨 뜻이에요?","basis":"출 14:14","by":"모세","ask":{"who":"choeon","text":"바다에서 일어난 일은 무슨 뜻이에요?"},"answer":{"t1":"모세는 백성에게, 여호와께서 그들을 위해 싸우실 것이라고 말했어요. 그러니 백성은 가만히 있으라고 했어요.","t2":"애굽 사람들이 바로 뒤까지 쫓아와 백성이 몹시 두려워할 때, 모세는 백성에게 말했어요. 여호와께서 그들을 위해 싸우실 것이니 그들은 가만히 있으라고 했어요.","t3":"애굽 사람들이 뒤에 이르러 백성이 몹시 두려워할 때, 모세는 백성에게 말했다. 여호와께서 그들을 위하여 싸우실 것이니 그들은 가만히 있으라는 것이었다(14:14)."},"read":{"t1":{"type":"find","ref":"출 14:14","prompt":"성경책에서 출애굽기 14장 14절을 찾아 읽어 보세요.","confirm":{"prompt":"모세는 여호와께서 백성을 위해 무엇을 하실 거라고 했나요?","options":[{"label":"싸우실 것","ok":true},{"label":"양식을 주실 것","basis":"출 16:8"},{"label":"높은 성을 쌓으실 것","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"출 14:30-31","prompt":"성경책에서 출애굽기 14장 30절과 31절을 읽어 보세요.","confirm":{"prompt":"그날 이스라엘이 여호와를 경외하게 되고, 여호와와 모세를 믿게 된 까닭은 무엇인가요?","options":[{"label":"애굽 사람들에게 하신 여호와의 큰 일을 눈으로 보았기 때문에","ok":true},{"label":"모세가 밤새도록 백성을 모아 놓고 오래 타일렀기 때문에","basis":"본문에 없음"},{"label":"바다를 건넌 뒤 그 건너편에서 먹을 양식을 넉넉히 얻었기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["출 14:14","출 14:31"],"prompt":"출애굽기 14장 14절과 31절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 모세가 백성에게 한 말과 그날 백성이 본 것은 어떻게 이어지는가?","options":[{"label":"모세는 여호와께서 그들을 위해 싸우시리라고 했고, 백성은 애굽 사람들에게 내리신 여호와의 큰 일을 보고, 여호와를 경외하게 되었으며 여호와와 그의 종인 모세를 믿었다","ok":true},{"label":"모세는 여호와께서 그들을 위해 싸우시리라고 했고, 백성은 애굽 사람들에게 내리신 여호와의 큰 일을 보고도 자기들의 힘으로 바다를 건넜다고 자랑했다","basis":"본문에 없음"},{"label":"모세는 애굽 사람들이 날이 밝으면 스스로 물러가리라고 했고, 백성은 애굽 사람들에게 내리신 여호와의 큰 일을 보고, 여호와를 경외하게 되었으며 여호와와 그의 종인 모세를 믿었다","basis":"본문에 없음"}]}}},"nt":{"ref":"히 11:29","text":"신약의 히브리서 11장 29절은 그들이 믿음으로 홍해를 마른 땅처럼 건넜고, 애굽 사람들은 그렇게 해 보려다가 물에 빠져 죽었다고 말한다."}}]}},"has3d":true,"epic":true},"OT-12":{"id":"OT-12","era":3,"title":"시내 산에서 주신 열 가지 말씀","ref":"출 19:1-20:21","place":"시내 광야, 시내 산 앞","review":{"required":true,"topics":["구약 사건의 신약적 의미(히 12:18-19)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"출 19:1-2","focus":"camp","text":{"t1":"이스라엘 자손은 애굽 땅에서 나온 뒤 시내 광야에 이르러 산 앞에 장막을 쳤어요. 어디를 떠나 왔는지는 2절에서 찾아봐요.","t2":"이스라엘 자손은 애굽 땅에서 나온 지 셋째 달에 시내 광야에 이르렀어요. 르비딤을 떠나 그 광야에 와서, 산 앞에 장막을 쳤어요.","t3":"이스라엘 자손은 애굽 땅에서 나온 지 셋째 달에 시내 광야에 이르렀다. 그들은 르비딤을 떠나 그 광야에 와서 산 앞에 장막을 쳤다."},"say":{"who":"hyu","text":"여기는 시내 광야야. 산 앞에 장막을 쳤다고 적어 둘게."}},{"ref":"출 19:3-8","open":"출 19:4-6","focus":"moses","text":{"t1":"하나님은 백성이 하나님의 말을 잘 듣고 언약을 지키면 하나님의 소유, 거룩한 백성이 될 거라고 하셨어요. 백성은 여호와께서 명하신 것을 다 하겠다고 대답했어요.","t2":"모세가 하나님 앞에 올라가자 여호와께서 산에서 그를 부르셨어요. 하나님은 애굽 사람에게 하신 일과, 독수리 날개로 업어 백성을 인도해 오신 것을 그들이 보았다고 하셨어요. 하나님의 말을 잘 듣고 언약을 지키면 모든 민족 가운데서 하나님의 소유가 되고, 제사장 나라와 거룩한 백성이 될 것이라고 하셨어요. 모세가 장로들에게 이 말씀을 전하자, 백성은 한목소리로 여호와께서 명하신 것을 다 하겠다고 대답했어요.","t3":"모세가 하나님께로 올라가자, 여호와께서 산에서 모세를 부르시고, 야곱 족속 곧 이스라엘 자손에게 전할 말씀을 주셨다. 여호와께서 애굽 사람에게 하신 일과 독수리 날개로 그들을 업어 자기에게로 인도하신 것을 그들이 보았다고 하셨다. 온 세계가 여호와께 속했으니, 그들이 여호와의 말을 잘 듣고 언약을 지키면 모든 민족 가운데서 여호와의 소유가 되고 여호와께 제사장 나라와 거룩한 백성이 될 것이라고 하셨다. 모세가 와서 장로들을 불러 모으고 여호와께서 명하신 말씀을 모두 전하자, 백성은 한목소리로 여호와께서 명하신 것을 다 행하겠다고 응답했고, 모세는 백성의 말을 여호와께 아뢰었다."},"say":{"who":"onwoo","text":"하나님이 백성에게 전하라고 하신 말씀이 19장 4절부터 6절에 있어. 성경책에서 직접 읽어 보자."}},{"ref":"출 19:9-15","open":"출 19:10-13","focus":"people","text":{"t1":"하나님은 백성이 옷을 빨고 셋째 날을 준비하게 하라고 하셨고, 산 둘레에 경계를 정해 아무도 산에 오르지 말라고 하셨어요. 백성은 옷을 빨았어요.","t2":"하나님은 모세에게 빽빽한 구름 가운데서 임하겠다고 하셨어요. 오늘과 내일 백성을 성결하게 하고 옷을 빨게 하여 셋째 날을 준비하게 하라고 하셨는데, 왜 셋째 날을 준비해야 했는지는 11절에서 찾아봐요. 또 산 둘레에 경계를 정해 아무도 산에 오르거나 경계를 넘지 않게 하라고 하셨고, 모세는 내려와 백성을 성결하게 했어요.","t3":"여호와께서는 모세에게, 빽빽한 구름 가운데서 그에게 임하겠다고 하셨다. 그렇게 하시는 까닭은 9절에 있다. 오늘과 내일 백성을 성결하게 하고 옷을 빨게 하여 셋째 날을 준비하게 하라고 하셨는데, 셋째 날에 여호와께서 온 백성이 보는 앞에서 시내 산에 강림하실 것이기 때문이다. 백성을 위하여 사방에 경계를 정하고, 산에 오르거나 그 경계를 범하는 자는 사람이든 짐승이든 반드시 죽임을 당할 것이라고 이르게 하셨다. 나팔 소리가 길게 울리면 산 앞으로 나아오라고 하셨다. 모세는 산에서 내려와 백성을 성결하게 했고 백성은 자기 옷을 빨았으며, 모세는 셋째 날을 준비하라고 백성에게 일렀다."},"say":{"who":"hyu","text":"오늘, 내일, 그리고 셋째 날. 산 둘레에는 경계가 정해졌어. 날짜와 장소를 적어 둘게."}},{"ref":"출 19:16-25","open":"출 19:21-24","focus":"mountain","text":{"t1":"셋째 날 아침, 나팔 소리가 아주 크게 울렸고 여호와께서 불 가운데 산에 강림하시자 온 산이 크게 흔들렸어요. 그때 산 위에 무엇이 있었는지는 16절에서 찾아봐요.","t2":"셋째 날 아침에 산 위에 우레와 번개와 빽빽한 구름이 있었고 나팔 소리가 매우 커서, 진에 있던 백성이 다 떨었어요. 그 뒤로 무슨 일들이 어떤 차례로 일어났는지는 17절부터 20절까지 읽어 봐요. 여호와께서는 백성이 경계를 넘어 올라오지 않도록 모세에게 내려가서 이르라고 하셨어요.","t3":"셋째 날 아침, 산 위에 있었던 일과 그것을 보고 들은 진의 백성이 어떠했는지는 16절에 있다. 모세는 백성을 이끌고 진 밖으로 나와 하나님을 맞으려 했고, 백성은 산기슭에 섰다. 여호와께서 불 가운데서 강림하셨으므로 시내 산은 연기로 자욱했는데, 그 연기는 가마의 연기처럼 올랐고 온 산이 크게 진동했다. 나팔 소리가 점점 커질 때 모세가 말하자 하나님이 음성으로 대답하셨다. 여호와께서 시내 산 꼭대기에 강림하시고 모세를 그리로 부르시니 모세가 올라갔다. 여호와께서는 백성이 여호와를 보려고 경계를 넘어 들어오다가 많이 죽지 않도록 내려가서 단단히 이르라고 하셨고, 여호와께 가까이 나아오는 제사장들도 몸을 성결하게 하라고 하셨다. 모세는, 산 사방에 경계를 세워 산을 거룩하게 하라고 여호와께서 명하셨으므로 백성이 시내 산에 오르지 못할 것이라고 아뢰었다. 여호와께서는 내려가서 아론과 함께 올라오되 제사장들과 백성은 경계를 넘어 올라오지 못하게 하라고 하셨고, 모세는 백성에게 내려가 그들에게 말했다."},"say":{"who":"choeon","text":"산에서 연기가 오르고 온 산이 흔들려!"}},{"ref":"출 20:1-11","open":"출 20:1-11","focus":"mountain","text":{"t1":"하나님은 백성을 애굽 땅에서 인도해 내신 여호와라고 하셨어요. 다른 신을 두지 말고, 우상을 만들어 절하지 말고, 하나님의 이름을 헛되이 부르지 말고, 안식일을 거룩하게 지키라고 하셨어요.","t2":"하나님이 이 모든 말씀을 하셨어요. 하나님은 그들을 애굽 땅, 종으로 있던 집에서 인도해 내신 여호와라고 하셨어요. 하나님 외에 다른 신들을 두지 말고, 어떤 것의 형상으로도 우상을 만들어 절하거나 섬기지 말라고 하셨어요. 또 여호와의 이름을 헛되이 부르지 말고, 안식일을 기억하여 거룩하게 지키라고 하셨어요.","t3":"하나님이 이 모든 말씀을 하셨다. 하나님은 자신이 그들을 종살이하던 집 애굽 땅에서 이끌어 내신 그들의 하나님 여호와라고 하셨다. 하나님 외에 다른 신들을 두지 말라고 하셨다. 위로 하늘, 아래로 땅, 땅 아래 물속에 있는 어떤 것의 형상으로도 새긴 우상을 만들지 말고, 그것들에게 절하거나 그것들을 섬기지 말라고 하셨다. 여호와는 질투하는 하나님이어서 그를 미워하는 자의 죄는 아버지에게서 자손 삼사 대에 이르도록 갚으시고, 그를 사랑하고 계명을 지키는 이들에게는 천 대에 이르도록 은혜를 베푸신다고 하셨다. 여호와의 이름을 망령되게 부르지 말라고 하셨고, 그렇게 부르는 자를 죄 없다 하지 않으신다고 하셨다. 안식일을 기억하여 거룩하게 지키되, 엿새 동안은 힘써 모든 일을 하고 일곱째 날은 여호와의 안식일이니 아들과 딸, 남종과 여종, 가축, 문 안에 머무는 나그네까지 아무 일도 하지 말라고 하셨다. 여호와께서 엿새 동안 하늘과 땅과 바다, 그리고 그 안의 모든 것을 지으시고 일곱째 날에 쉬셨으므로 안식일에 복을 주시고 그 날을 거룩하게 하셨기 때문이다."},"say":{"who":"onwoo","text":"하나님이 하신 말씀은 우리가 줄여서 말하기보다 성경책에서 직접 읽자. 20장 1절부터 펴 보자."}},{"ref":"출 20:12-17","open":"출 20:12-17","focus":"mountain","text":{"t1":"하나님은 부모를 공경하라고 하셨어요. 사람을 죽이지 말고, 도둑질하지 말고, 거짓으로 증언하지 말고, 이웃의 것을 탐내지 말라고 하셨어요.","t2":"하나님은 부모를 공경하라고 하셨고, 그러면 하나님이 주신 땅에서 오래 살 것이라고 하셨어요. 살인하지 말고, 간음하지 말고, 도둑질하지 말고, 이웃을 두고 거짓으로 증언하지 말라고 하셨어요. 이웃의 집과 이웃이 가진 어떤 것도 탐내지 말라고 하셨어요.","t3":"하나님은 부모를 공경하라고 하셨고, 그리하면 여호와께서 주신 땅에서 생명이 길 것이라고 하셨다. 살인하지 말고, 간음하지 말고, 도둑질하지 말고, 이웃을 두고 거짓으로 증언하지 말라고 하셨다. 이웃의 집을 탐내지 말고, 이웃의 아내나 남종이나 여종이나 소나 나귀나 이웃에게 속한 어떤 것도 탐내지 말라고 하셨다."},"say":{"who":"hyu","text":"12절부터 17절까지 이어지는 말씀이야. 순서를 놓치지 않게 절 번호를 적어 둘게."}},{"ref":"출 20:18-21","focus":"people","text":{"t1":"백성은 산에서 보고 들은 것 때문에 떨며 멀리 섰어요. 모세는 두려워하지 말라고 하고, 하나님이 계신 짙은 어둠 쪽으로 가까이 갔어요.","t2":"온 백성이 우레와 번개와 나팔 소리, 그리고 산에서 오르는 연기를 보고 떨며 멀리 섰어요. 그들은 모세에게, 모세가 말해 주면 듣겠으니 하나님이 직접 말씀하시지 않게 해 달라고 했어요. 모세는 두려워하지 말라고 하며, 하나님이 강림하신 것은 그들을 시험하시고 하나님을 경외하여 죄를 짓지 않게 하시려는 것이라고 했어요. 백성은 멀리 서 있었고, 모세는 하나님이 계신 짙은 어둠 쪽으로 가까이 갔어요.","t3":"온 백성이 우레와 번개와 나팔 소리, 그리고 산에서 오르는 연기를 보았다. 그들은 모세에게, 모세가 말하면 자기들이 듣겠으니 하나님이 자기들에게 말씀하시지 않게 해 달라고 했고, 그러지 않으면 죽을까 두렵다고 했다. 모세는 백성에게 두려워하지 말라고 했는데, 하나님이 강림하신 까닭을 두고 모세가 한 말은 20절에서 직접 읽어 보자. 백성은 멀리 서 있었고, 모세는 하나님이 계신 짙은 어둠 쪽으로 가까이 갔다."},"say":{"who":"choeon","text":"사람들이 멀리 서 있어. 모세만 짙은 어둠 쪽으로 가까이 가고 있어."}}],"gates":{"t1":[{"type":"find","ref":"출 19:2","prompt":"성경책에서 출애굽기 19장 2절을 찾아 읽어 보세요.","confirm":{"prompt":"이스라엘 자손은 시내 광야에 오기 전에 어디를 떠나 왔나요?","options":[{"label":"르비딤","ok":true},{"label":"엘림","basis":"출 16:1"},{"label":"숙곳","basis":"출 13:20"}]}},{"type":"multi","ref":"출 19:16","prompt":"성경책에서 출애굽기 19장 16절을 찾아 읽어 보세요.","confirm":{"prompt":"셋째 날 아침, 산 위에 있었던 것을 모두 고르세요.","options":[{"label":"우레","ok":true},{"label":"무지개","basis":"창 9:13"},{"label":"번개","ok":true},{"label":"빽빽한 구름","ok":true},{"label":"눈보라","basis":"본문에 없음"}]}}],"t2":[{"type":"find","ref":"출 19:10-11","prompt":"성경책에서 출애굽기 19장 10절과 11절을 읽어 보세요.","confirm":{"prompt":"백성이 옷을 빨고 셋째 날을 기다리며 준비해야 했던 까닭은 무엇인가요?","options":[{"label":"셋째 날에 여호와께서 온 백성이 보는 앞에서 시내 산에 내려오실 것이기 때문에","ok":true},{"label":"셋째 날에 애굽 군대가 다시 쫓아와 시내 광야에 이를 것이기 때문에","basis":"본문에 없음"},{"label":"셋째 날에 모세가 산에서 내려와 백성에게 양식을 나누어 줄 것이기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"출 19:16-20","prompt":"성경책에서 출애굽기 19장 16절부터 20절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["산 위에 우레와 번개가 있고 구름이 빽빽했다","모세가 백성을 데리고 진 밖으로 나왔다","백성이 산기슭에 섰다","연기가 가득 오르고 온 산이 크게 흔들렸다","여호와께서 모세를 산꼭대기로 부르셨고 모세가 올라갔다"]}],"t3":[{"type":"find","refs":["출 19:16","출 20:18"],"prompt":"출애굽기 19장 16절과 20장 18절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 산 위의 일을 보고 들은 백성의 모습은 어떠했는가?","options":[{"label":"셋째 날 아침 천둥과 번개와 빽빽한 구름과 아주 큰 나팔 소리에 진에 있던 백성이 모두 떨었고, 또 백성은 천둥과 번개, 나팔 소리, 연기를 보고 떨면서 멀찍이 섰다","ok":true},{"label":"셋째 날 아침 천둥과 번개와 빽빽한 구름과 아주 큰 나팔 소리에 진에 있던 백성이 모두 기뻐하며 환호했고, 나중에 연기를 보고서야 멀찍이 섰다","basis":"본문에 없음"},{"label":"셋째 날 아침에는 산 위가 고요하여 진에 있던 백성이 모두 기다리기만 했고, 나중에 천둥과 번개, 나팔 소리, 연기를 보고 떨면서 멀찍이 섰다","basis":"본문에 없음"}]}},{"type":"match","refs":["출 19:4","출 19:8","출 20:19"],"prompt":"출애굽기 19장 4절, 19장 8절, 20장 19절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"출 19:4","text":"하나님이 독수리 날개로 업듯이 백성을 인도해 오신 것을 그들이 보았다고 하셨다"},{"ref":"출 19:8","text":"백성이 한목소리로 여호와께서 명하신 대로 다 하겠다고 대답했다"},{"ref":"출 20:19","text":"백성이 죽을까 두려워 하나님이 직접 말씀하시지 않게 해 달라고 모세에게 청했다"}],"after":"세 곳을 이으면, 하나님은 백성을 업어 인도해 오셨다고 하셨고, 백성은 처음에 명하신 대로 다 하겠다고 했으며, 나중에는 죽을까 두려워 하나님이 직접 말씀하시지 말고 모세가 대신 말해 달라고 했다."}]},"cards":[{"ref":"출 19:6","title":"제사장 나라, 거룩한 백성"},{"ref":"출 20:2","title":"애굽 땅에서 인도하여 내신 여호와"}],"close":{"t1":{"kind":"prayer","text":"하나님, 시내 산에서 하신 말씀을 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 출애굽기 20장 1절부터 17절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"출 19:1-20:21에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 타임머신이 시내 광야에 비상 착륙하면서 연료통 마개에 금이 갔어요. 진 가장자리에서 대신 쓸 재료를 찾고, 백성이 하는 평범한 일만 도우며, 산 둘레의 경계는 넘지 말아요.","t2":"최현 박사예요. 타임머신이 시내 광야에 비상 착륙하면서 연료통 마개에 금이 갔어요. 이 시대에는 맞는 부속이 없으니 땅에서 구할 수 있는 것으로 대신 만들어야 해요. 산 쪽으로는 가지 말고 진 가장자리에서 찾아요. 백성과 함께 있게 되면 그들이 하는 평범한 일만 돕고, 산 둘레의 경계는 넘지 말아요.","t3":"최현 박사다. 타임머신이 시내 광야에 비상 착륙하면서 연료통 마개에 금이 갔다. 이 시대에는 맞는 부속이 없으니 땅에서 구할 수 있는 재료로 대신 만들어야 한다. 산 쪽으로는 가지 말자. 백성과 함께 있게 되면 그들이 하는 평범한 일만 돕고, 산 둘레의 경계는 넘지 않으며 산에 손대지 않는다."},"materials":[{"key":"soil","name":"흙","basis":"출 19:2","use":"흙을 물에 이겨 빚으면 금 간 연료통 마개 대신 쓸 수 있어요.","how":"산 앞에 친 진의 가장자리, 산 둘레의 경계에서 멀리 떨어진 땅에서 흙 한 줌을 뜬다. 경계 쪽으로는 가지 않고, 사람들의 장막 안으로는 들어가지 않는다.","line":"진 가장자리 땅에서 흙을 한 줌 떴어!"}],"companion":{"who":"모세","ref":"출 20:20","when":"after","talks":[{"ask":{"who":"onwoo","text":"하나님께 올라갔다가 돌아와서 장로들에게 무엇을 전하셨어요?"},"answer":{"t1":"모세는 하나님이 하신 말씀을 장로들에게 전했어요. 하나님의 말을 잘 듣고 언약을 지키면 하나님의 소유가 되고 거룩한 백성이 될 것이라고 하나님이 말씀하셨다고 전했어요.","t2":"모세는 백성의 장로들을 불러 모아, 여호와께 받은 말씀을 모두 전했어요. 백성이 하나님의 말을 잘 듣고 언약을 지키면 모든 민족 가운데서 하나님의 소유가 되고, 제사장 나라와 거룩한 백성이 될 것이라고 하나님이 말씀하셨다고 전했어요.","t3":"모세는 백성의 장로들을 불러 모으고, 여호와께 받은 말씀을 하나도 빼지 않고 그들 앞에 전했다. 그들이 여호와의 말을 잘 듣고 언약을 지키면 모든 민족 가운데서 여호와의 소유가 되고, 여호와께 제사장 나라와 거룩한 백성이 될 것이라고 여호와께서 말씀하셨다고 전한 것이다."},"ref":"출 19:5-7","open":"출 19:5"},{"ask":{"who":"choeon","text":"백성은 왜 산에 올라가면 안 됐어요?"},"answer":{"t1":"모세는 하나님께, 산 둘레에 경계를 세워 산을 거룩하게 하라고 명하셨으니 백성이 산에 오르지 못할 것이라고 말씀드렸어요.","t2":"모세는 여호와께, 백성은 시내 산에 오르지 못할 것이라고 아뢰었어요. 여호와께서 산 둘레에 경계를 세워 산을 거룩하게 하라고 명하셨기 때문이라고 했어요.","t3":"모세는 여호와께, 산 사방에 경계를 세워 산을 거룩하게 하라고 주께서 명하셨으므로 백성이 시내 산에 오르지 못할 것이라고 아뢰었다."},"ref":"출 19:23","open":"출 19:23"}]},"today":[{"q":"하나님은 왜 일곱째 날을 쉬는 날로 지키라고 하셨어요?","a":{"t1":"하나님이 엿새 동안 하늘과 땅과 바다와 그 안의 모든 것을 지으시고 일곱째 날에 쉬셨기 때문이라고 하셨어요. 그래서 그 날에 복을 주시고 거룩하게 하셨다고 하셨어요.","t2":"하나님은 안식일을 기억하여 거룩하게 지키라고 하시며 그 까닭도 말씀하셨어요. 엿새 동안 하늘과 땅과 바다와 그 안의 모든 것을 지으시고 일곱째 날에 쉬셨으므로, 그 날에 복을 주시고 거룩하게 하셨다는 거예요. 창세기 2장에도 하나님이 일곱째 날에 쉬시고 그 날을 거룩하게 하셨다고 적혀 있어요.","t3":"하나님은 안식일을 기억하여 거룩하게 지키라고 하시며, 여호와께서 엿새 동안 하늘과 땅과 바다와 그 안에 있는 모든 것을 지으시고 일곱째 날에 쉬셨으므로 안식일에 복을 주시고 그 날을 거룩하게 하셨다고 까닭을 밝히셨다(출 20:8-11). 창세기도 하나님이 지으시던 일을 마치시고 일곱째 날에 쉬셨으며 그 날을 복 주시고 거룩하게 하셨다고 기록한다(창 2:2-3). 성경은 이 장면에서 여기까지 말한다."},"refs":["출 20:8-11","창 2:2-3"]},{"q":"하나님이 시내 산에서 말씀하시던 날, 백성은 하나님의 모습을 보았어요?","a":{"t1":"백성은 우레와 번개와 연기를 보고 나팔 소리를 들었어요. 뒷날 모세는 그날 백성이 하나님의 음성만 듣고 아무 형상도 보지 못했다고 말했어요.","t2":"백성은 우레와 번개와 나팔 소리와 산에서 오르는 연기를 보고 떨며 멀리 섰고, 모세는 하나님이 계신 짙은 어둠 쪽으로 가까이 갔어요. 뒷날 모세는 백성에게, 호렙 산 불 가운데서 여호와께서 말씀하시던 날 그들이 음성만 듣고 아무 형상도 보지 못했다고 일깨웠어요. 그러니 어떤 형상으로도 우상을 만들지 않도록 깊이 조심하라고 했어요.","t3":"백성은 우레와 번개와 나팔 소리와 산의 연기를 보고 떨며 멀리 섰고, 모세는 하나님이 계신 짙은 어둠으로 가까이 나아갔다(출 20:18-21). 시내 산에서 하나님은 어떤 것의 형상으로도 우상을 만들지 말라고 하셨다(출 20:4). 뒷날 모세는 백성에게, 여호와께서 호렙 산 불 가운데서 말씀하시던 날 그들이 말소리만 들었을 뿐 아무 형상도 보지 못했으니, 스스로 부패하여 어떤 형상으로든 우상을 새겨 만들지 않도록 깊이 삼가라고 일렀다(신 4:12, 4:15-16). 성경은 여기까지 말한다."},"refs":["출 20:18-21","출 20:4","신 4:12","신 4:15-16"]}],"help":{"who":"산 앞에 장막을 친 이스라엘 백성","steps":[{"kind":"do","after":2,"title":"옷 빨기 돕기","basis":"출 19:14","text":{"t1":"모세가 내려와 백성에게 갔어요. 백성은 저마다 옷을 빨았어요. 우리도 옷 빠는 일을 도와요.","t2":"하나님은 오늘과 내일 백성이 옷을 빨고 준비하게 하라고 하셨어요. 모세가 내려와 백성을 성결하게 하자, 백성은 저마다 옷을 빨았어요. 우리는 옷을 빠는 일만 도와요.","t3":"여호와께서는 오늘과 내일 백성을 성결하게 하고 옷을 빨게 하라고 하셨다(19:10). 모세는 산에서 내려와 백성을 성결하게 했고, 백성은 저마다 옷을 빨았다(19:14). 성결하게 하는 일은 모세가 했고, 탐험대는 백성이 옷을 빠는 일만 돕는다."},"tasks":["빨 옷 건네받기","함께 옷 빨기","빤 옷 돌려주기"],"done":{"who":"choeon","text":"옷을 다 빨았어. 이제 셋째 날을 기다리는 거야."}},{"kind":"stay","after":3,"title":"경계 밖 산기슭에 서기","basis":"출 19:17","text":{"t1":"모세가 백성과 함께 진 밖으로 나왔고, 백성은 산기슭에 섰어요. 우리도 경계를 넘지 않고 백성과 함께 서 있어요.","t2":"셋째 날 아침, 하나님을 맞으러 모세가 백성과 함께 진 밖으로 나왔어요. 백성은 산기슭에 섰어요. 우리도 산 둘레의 경계를 넘지 않고, 산에 손대지 않으며, 백성과 함께 서 있어요.","t3":"하나님을 맞으러 모세가 백성과 함께 진 밖으로 나왔고, 백성은 산기슭에 섰다(19:17). 산 둘레에는 경계가 정해져 있어, 아무도 산에 올라가거나 경계를 넘어서는 안 되었다(19:12). 탐험대도 경계를 넘지 않고 산을 만지지 않으며 백성과 함께 선다."},"wait":"경계 밖에서 함께 서 있기","say":{"who":"onwoo","text":"경계 안으로는 들어가지 않을 거야. 산에도 손대지 않아."}},{"kind":"watch","after":6,"title":"곁에서 보기 · 짙은 어둠으로 가는 모세","basis":"출 20:21","text":{"t1":"백성은 멀리 서 있었어요. 모세는 하나님이 계신 짙은 어둠 쪽으로 가까이 갔어요. 우리는 백성과 함께 멀리서 지켜봐요.","t2":"백성은 멀찍이 서 있었어요. 모세는 하나님이 계신 짙은 어둠 쪽으로 가까이 갔어요. 우리는 따라가지 않고 백성과 함께 멀리서 지켜봐요.","t3":"백성은 멀찍이 서 있었고, 모세는 하나님이 계신 짙은 어둠으로 다가갔다(20:21). 탐험대는 따라가지 않고 백성과 함께 멀리서 지켜본다."}},{"kind":"ask","after":"gates","title":"산에 내려오셔서 말씀하신 일은 무슨 뜻이에요?","basis":"출 20:20","by":"모세","ask":{"who":"hyu","text":"하나님이 시내 산에 내려오셔서 말씀하신 일은 무슨 뜻이에요?"},"answer":{"t1":"모세는 백성에게 두려워하지 말라고 했어요. 하나님이 오신 것은 그들을 시험하시고, 하나님을 경외하여 죄를 짓지 않게 하시려는 것이라고 말했어요.","t2":"모세는 떨며 멀리 선 백성에게 두려워하지 말라고 했어요. 하나님이 내려오신 것은 그들을 시험하시려는 것이고, 그들이 하나님을 경외하여 죄를 짓지 않게 하시려는 것이라고 말했어요.","t3":"모세는 떨며 멀리 서서 하나님이 직접 말씀하지 않게 해 달라고 한 백성에게 두려워하지 말라고 했다. 하나님이 강림하신 것은 그들을 시험하시고, 그들이 하나님을 경외하여 죄를 범하지 않게 하시려는 것이라고 말했다(20:20)."},"read":{"t1":{"type":"find","ref":"출 20:20","prompt":"성경책에서 출애굽기 20장 20절을 찾아 읽어 보세요.","confirm":{"prompt":"모세는 하나님이 내려오신 것이 백성을 어떻게 하시려는 것이라고 했나요?","options":[{"label":"하나님을 경외하여 죄를 짓지 않게 하시려고","ok":true},{"label":"백성이 잘못한 것을 꾸짖고 벌을 내리시려고","basis":"본문에 없음"},{"label":"모세를 이스라엘의 왕으로 세우시려고","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"출 19:8-9","prompt":"성경책에서 출애굽기 19장 8절과 9절을 읽어 보세요.","confirm":{"prompt":"하나님이 짙은 구름 속에서 모세에게 오시겠다고 하신 까닭은 무엇인가요?","options":[{"label":"하나님이 모세와 말씀하시는 것을 백성이 듣고, 모세를 영원히 믿게 하시려고","ok":true},{"label":"백성이 짙은 구름 속에 계신 하나님의 모습을 보게 하시려고","basis":"본문에 없음"},{"label":"백성이 산 가까이 오지 못하도록 빽빽한 구름으로 산을 가리시려고","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["출 19:9","출 20:20"],"prompt":"출애굽기 19장 9절과 20장 20절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 하나님이 산에 임하신 까닭을 성경은 무엇이라고 말하는가?","options":[{"label":"하나님은 모세와 말씀하시는 것을 백성이 듣고 모세를 영원히 믿게 하시려고 짙은 구름 속에서 임하신다고 하셨고, 모세는 하나님이 그들을 시험하시고 그들이 하나님을 경외하여 죄를 짓지 않게 하시려고 강림하셨다고 했다","ok":true},{"label":"하나님은 백성이 짙은 구름 속에 계신 하나님의 모습을 눈으로 보게 하시려고 임하신다고 하셨고, 모세는 하나님이 그들의 잘못을 꾸짖고 벌을 내리시려고 강림하셨다고 했다","basis":"본문에 없음"},{"label":"하나님은 백성이 산 가까이 오지 못하도록 빽빽한 구름으로 산을 가리시려고 임하신다고 하셨고, 모세는 하나님이 자기를 온 이스라엘의 왕으로 세우시려고 강림하셨다고 했다","basis":"본문에 없음"}]}}},"nt":{"ref":"히 12:18-19","text":"신약의 히브리서 12장 18~19절은 만질 수 있는 불붙는 산과 검은 구름과 어둠과 폭풍, 나팔 소리와 말씀하시는 소리를 말하고, 그 소리를 들은 사람들이 더 말씀하지 않으시기를 구했다고 적는다. 그러면서 그 편지를 받는 사람들이 이른 곳은 그런 곳이 아니라고 말한다."}}]}},"has3d":false,"epic":false},"OT-13":{"id":"OT-13","era":4,"title":"하늘에서 내린 양식, 만나","ref":"출 16:1-36","place":"엘림과 시내 산 사이의 광야","review":{"required":true,"topics":["구약 사건의 신약적 의미(요 6:31-32)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"출 16:1-3","focus":"camp","text":{"t1":"이스라엘 온 회중이 엘림을 떠나 광야에 왔어요. 백성은 애굽에서는 배불리 먹었는데 이 광야에서는 굶어 죽게 되었다며 모세와 아론을 원망했어요.","t2":"이스라엘 온 회중이 엘림을 떠나, 엘림과 시내 산 사이에 있는 신 광야에 왔어요. 애굽에서 나온 뒤 둘째 달 십오일이었어요. 백성은 모두 그곳에서 모세와 아론을 원망했는데, 무엇이라고 원망했는지는 3절에서 찾아봐요.","t3":"이스라엘 자손의 온 회중은 엘림을 떠나, 애굽에서 나온 뒤 둘째 달 십오일에 엘림과 시내 산 사이에 있는 신 광야에 닿았다. 거기서 온 회중이 모세와 아론을 원망했다. 애굽 땅에서 고기 가마 곁에 앉아 떡을 배부르게 먹을 때 여호와의 손에 죽는 편이 나았겠다고 하며, 두 사람이 자기들을 이 광야로 데리고 나와 온 회중을 굶겨 죽이려 한다고 했다."},"say":{"who":"hyu","text":"여기는 엘림과 시내 산 사이의 광야야. 일지에 적어 둘게."}},{"ref":"출 16:4-5","open":"출 16:4","focus":"moses","text":{"t1":"하나님은 모세에게 하늘에서 양식을 비처럼 내려 주겠다고 하셨어요. 백성이 날마다 나가서 그날 먹을 것을 거두게 하겠다고 하셨어요.","t2":"여호와께서는 모세에게 하늘에서 양식을 비처럼 내려 주겠다고 하셨어요. 백성이 날마다 나가서 그날 먹을 것을 거두게 하겠다고 하셨어요. 여섯째 날에는 거두어 온 것을 준비하면 다른 날 거두던 것의 두 배가 될 것이라고 하셨어요.","t3":"여호와께서는 모세에게, 백성을 위해 하늘에서 양식을 비처럼 내리겠다고 하셨다. 백성이 날마다 나가 그날 쓸 것을 거두게 하여, 그들이 하나님의 율법대로 행하는지 아닌지 시험하겠다고 하셨다. 여섯째 날에 거두어 들인 것을 준비하면 다른 날 거두던 것의 갑절이 될 것이라고도 하셨다."},"say":{"who":"onwoo","text":"하나님이 모세에게 하신 말씀은 출애굽기 16장 4절부터야. 성경책에서 직접 읽어 보자."}},{"ref":"출 16:6-12","open":"출 16:12","focus":"cloud","text":{"t1":"백성이 광야 쪽을 바라보니 구름 속에 여호와의 영광이 나타났어요. 하나님은 백성의 원망을 들으셨다며, 저녁에는 고기를, 아침에는 떡을 먹게 하겠다고 하셨어요.","t2":"모세와 아론은 백성의 원망을 두고 말했는데, 무엇이라고 했는지는 7절과 8절에서 찾아봐요. 아론이 온 회중에게 말할 때 그들이 광야 쪽을 바라보니, 구름 속에 여호와의 영광이 나타났어요. 여호와께서는 모세에게, 백성이 해 질 무렵에는 고기를, 아침에는 떡을 배부르게 먹을 것이라고 전하게 하셨어요.","t3":"모세와 아론은 온 이스라엘 자손에게 해 질 무렵과 아침에 있을 일을 말하고, 백성의 원망을 두고도 말했다. 무엇이라고 했는지는 6절부터 8절까지 직접 읽어 보자. 모세는 아론에게, 온 회중더러 여호와께 가까이 나아오게 하라고 했다. 아론이 온 회중에게 말할 때 그들이 광야 쪽을 바라보니, 구름 속에 여호와의 영광이 나타났다. 여호와께서는 모세에게, 이스라엘 자손의 원망을 들었다고 하셨다."},"say":{"who":"choeon","text":"사람들이 모두 광야 쪽을 바라보고 있어. 저기 구름이 보여."}},{"ref":"출 16:13-15","focus":"manna","text":{"t1":"저녁에 무엇이 와서 진을 덮었고, 아침에 이슬이 마르자 땅 위에 무엇이 있었는지는 13절과 14절에서 찾아봐요. 모세는 그것이 여호와께서 먹으라고 주신 양식이라고 했어요.","t2":"저녁에는 메추라기가 와서 진을 덮었고, 아침에는 진 둘레에 이슬이 있었어요. 이슬이 마르자 광야의 땅 위에 작고 둥글며 서리처럼 가는 것이 있었어요. 이스라엘 자손이 그것을 보고 한 말과 그 까닭은 15절에서 찾아봐요. 모세는 그것이 여호와께서 먹으라고 주신 양식이라고 말했어요.","t3":"그날 해 질 무렵과 이튿날 아침에 있었던 일, 이슬이 걷힌 뒤 광야의 땅 위에 있던 것은 13절과 14절에 있다. 이스라엘 자손은 그것을 보고 서로 이것이 무엇이냐고 물었다. 모세는 여호와께서 그들에게 먹으라고 주신 양식이라고 말했다."},"say":{"who":"choeon","text":"이슬이 마르니까 땅 위에 무언가 있어!"}},{"ref":"출 16:16-21","focus":"omer","text":{"t1":"하나님은 한 사람에 한 오멜씩 거두라고 하셨어요. 모세가 아침까지 남겨 두지 말라고 했는데도 몇몇이 남겨 두자, 벌레가 생기고 고약한 냄새가 났어요.","t2":"여호와께서 명하신 것은, 장막에 있는 사람 수대로 한 사람에 한 오멜씩 거두라는 것이었어요. 많이 거둔 사람도 있고 적게 거둔 사람도 있었지만, 오멜로 되어 보니 많이 거둔 사람도 남지 않았고 적게 거둔 사람도 모자라지 않았어요. 모세는 아침까지 남겨 두지 말라고 했는데, 그 뒤에 몇몇 사람이 한 일과 모세가 노한 까닭은 20절에서 찾아봐요. 백성은 아침마다 거두었고, 해가 뜨거워지면 그것은 녹아 없어졌어요.","t3":"모세는 여호와께서 명하신 바를 전했다. 각 사람이 먹을 만큼, 자기 장막에 있는 사람 수대로 한 명에 한 오멜씩 거두라는 것이었다. 이스라엘 자손이 그렇게 하니 많이 거둔 사람도 적게 거둔 사람도 있었으나, 오멜로 되어 보면 많이 거둔 사람에게 남는 것이 없고 적게 거둔 사람에게 모자라는 것이 없었다. 모세는 아무도 그것을 아침까지 남기지 말라고 했다. 그 뒤에 몇몇이 한 일과 그것이 어떻게 되었는지는 20절에 있다. 무리는 아침마다 각자 먹을 만큼 거두었으며, 해가 뜨겁게 내리쬐면 그것은 스러졌다."},"say":{"who":"hyu","text":"한 사람에 한 오멜씩이야. 아침마다 거둔다고 적어 둘게."}},{"ref":"출 16:22-30","open":"출 16:29","focus":"camp","text":{"t1":"여섯째 날에는 다른 날보다 많이 거두었는데, 한 사람에 몇 오멜씩이었는지는 22절에서 찾아봐요. 일곱째 날은 여호와의 안식일이라서 백성은 쉬었어요.","t2":"여섯째 날에는 백성이 다른 날의 갑절을 거두었어요. 그 뒤로 일곱째 날까지 무슨 일들이 어떤 차례로 있었는지는 23절부터 30절까지 읽어 봐요.","t3":"여섯째 날에는 각 사람이 갑절, 곧 한 사람에 두 오멜씩 거두었고, 회중의 지도자들이 모두 와서 모세에게 알렸다. 모세는 여호와의 말씀을 전했다. 내일은 쉬는 날, 여호와께 거룩한 안식일이니 굽거나 삶을 것은 그날 하고 남는 것은 아침까지 간수하라는 것이었다. 그렇게 아침까지 둔 것이 어떻게 되었는지는 24절에 있다. 모세는 그날이 여호와께 안식일이므로 들에서 그것을 얻지 못할 것이라 했는데, 일곱째 날에 백성 가운데 몇몇이 거두러 나갔으나 얻지 못했다. 여호와께서는 모세에게, 언제까지 계명과 율법을 지키지 않으려느냐고 하시고, 안식일을 주셨으므로 여섯째 날에 이틀 치 양식을 주는 것이니 일곱째 날에는 아무도 자기 처소에서 나오지 말라고 하셨다. 그리하여 백성은 일곱째 날에 안식했다."},"say":{"who":"onwoo","text":"일곱째 날에 대해 하나님이 무엇이라고 하셨는지 16장 29절에서 확인해 보자."}},{"ref":"출 16:31-36","focus":"jar","text":{"t1":"이스라엘 사람들은 그 양식을 만나라고 불렀어요. 이스라엘 자손은 가나안 땅의 경계에 닿을 때까지 사십 년 동안 그것을 먹었어요.","t2":"이스라엘 족속은 그것의 이름을 만나라고 했어요. 만나는 깟씨 같고 희었으며, 맛은 꿀을 섞은 과자 같았어요. 아론은 여호와께서 모세에게 명령하신 그대로, 만나 한 오멜을 항아리에 담아 대대로 간수하게 했어요. 이스라엘 자손은 가나안 땅의 경계에 닿을 때까지 사십 년 동안 만나를 먹었어요.","t3":"이스라엘 족속은 그 이름을 만나라고 했다. 그 생김새와 빛깔과 맛은 31절에 있다. 모세는 여호와께서 명하신 바를 전했다. 애굽에서 인도해 내실 때 광야에서 먹이신 양식을 후손이 볼 수 있도록, 그것을 한 오멜 채워 대대로 간수하라는 것이었다. 모세는 아론에게, 항아리 하나에 만나를 한 오멜 담아서 여호와 앞에 두라고 했다. 아론은 여호와께서 모세에게 명령하신 그대로 증거판 앞에 그것을 두어 보관하게 했다. 이스라엘 자손은 사람이 사는 땅, 곧 가나안 땅의 경계에 닿을 때까지 사십 년 동안 만나를 먹었다. 한 오멜은 에바의 십분의 일이다."},"say":{"who":"hyu","text":"이름은 만나. 사십 년 동안 먹었다고 일지에 적었어."}}],"gates":{"t1":[{"type":"find","ref":"출 16:22","prompt":"성경책에서 출애굽기 16장 22절을 찾아 읽어 보세요.","confirm":{"prompt":"여섯째 날에는 한 사람에 몇 오멜씩 거두었나요?","options":[{"label":"두 오멜","ok":true},{"label":"한 오멜","basis":"출 16:16"},{"label":"세 오멜","basis":"본문에 없음"}]},"inStory":"오멜이라는 말은 이야기에 나오지만(한 사람에 한 오멜), 여섯째 날에 몇 오멜씩 거두었는지는 이야기 글에서 가렸고 16:22에서만 안다"},{"type":"multi","ref":"출 16:31","prompt":"성경책에서 출애굽기 16장 31절을 찾아 읽어 보세요.","confirm":{"prompt":"31절에서 만나는 어떠했다고 하나요? 모두 고르세요.","options":[{"label":"깟씨 같았다","ok":true},{"label":"빛깔이 희었다","ok":true},{"label":"서리처럼 가늘었다","basis":"출 16:14"},{"label":"꿀 섞은 과자 같은 맛이었다","ok":true},{"label":"빛깔이 붉었다","basis":"본문에 없음"}]}}],"t2":[{"type":"find","ref":"출 16:19-20","prompt":"성경책에서 출애굽기 16장 19절과 20절을 읽어 보세요.","confirm":{"prompt":"모세가 몇몇 사람에게 노한 까닭은 무엇인가요?","options":[{"label":"아침까지 남기지 말라는 말을 듣지 않고 그대로 두었다가, 그것에 벌레가 나고 냄새가 났기 때문에","ok":true},{"label":"아침까지 남기지 말라는 말을 듣지 않고 그대로 두었다가, 아무 일이 없자 이웃에게 자랑했기 때문에","basis":"본문에 없음"},{"label":"아침까지 남기지 말라는 말을 듣지 않고 그대로 두었다가, 해가 뜨거워지자 녹아 없어졌기 때문에","basis":"출 16:21"}]}},{"type":"order","ref":"출 16:22-30","prompt":"성경책에서 출애굽기 16장 22절부터 30절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["여섯째 날, 한 사람이 두 오멜씩 거두었다","모세가 다음 날은 쉬는 안식일이라고 일렀다","아침까지 둔 것에 냄새도 벌레도 생기지 않았다","일곱째 날에 몇몇이 들에 나갔지만 아무것도 얻지 못했다","백성이 일곱째 날에 쉬었다"]}],"t3":[{"type":"find","refs":["출 16:20","출 16:24"],"prompt":"출애굽기 16장 20절과 24절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 아침까지 남겨 둔 것은 어떻게 달랐는가?","options":[{"label":"모세의 말을 듣지 않고 아침까지 둔 것에는 벌레가 나고 냄새가 났지만, 안식일을 앞두고 모세가 말한 대로 아침까지 둔 것에는 냄새도 벌레도 없었다","ok":true},{"label":"모세의 말을 듣지 않고 아침까지 둔 것도, 안식일을 앞두고 모세가 말한 대로 아침까지 둔 것도 모두 벌레가 나고 냄새가 나서 먹지 못했다","basis":"본문에 없음"},{"label":"모세의 말을 듣지 않고 아침까지 둔 것에는 아무 일도 없었지만, 안식일을 앞두고 모세가 말한 대로 아침까지 둔 것에는 벌레가 나고 냄새가 났다","basis":"본문에 없음"}]}},{"type":"match","refs":["출 16:5","출 16:22","출 16:29"],"prompt":"출애굽기 16장 5절, 22절, 29절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"출 16:5","text":"여섯째 날에는 거두어 온 것을 준비하라고 하시며, 그것이 다른 날의 두 배가 되리라고 하셨다"},{"ref":"출 16:22","text":"회중의 지도자들이 모두 와서 모세에게 알렸다"},{"ref":"출 16:29","text":"일곱째 날에는 저마다 있는 곳에 머물고 나오지 말라고 하셨다"}],"after":"세 곳을 이으면, 여호와께서 여섯째 날에는 두 배를 얻게 되리라 하셨고, 그날 백성이 갑절을 거두자 지도자들이 모세에게 알렸으며, 여호와께서는 안식일을 주셨으므로 여섯째 날에 이틀 치 양식을 주시니 일곱째 날에는 저마다 있는 곳에 머물라고 하셨다."}]},"cards":[{"ref":"출 16:4","title":"하늘에서 내리는 양식"},{"ref":"출 16:15","title":"여호와께서 주신 양식"}],"close":{"t1":{"kind":"prayer","text":"하나님, 광야에서 백성에게 양식을 주신 이야기를 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 출애굽기 16장 11절부터 21절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"출 16:1-36에서 새로 알게 된 사실을 한 가지 적어 보자."}},"quests":[{"part":"bulb","name":"전구","line":"전구를 찾았어! 진에서 멀찍이 떨어진 광야 땅 위에 있었네.","found":"탐지기가 진 바깥의 광야 쪽을 가리켜요.","say":{"who":"hyu","text":"탐지기 바늘이 진 바깥 광야 쪽으로 돌아갔어. 성경에서 찾은 광야 이름을 일지에 적어 둘게."},"q":{"t1":{"type":"find","ref":"출 16:1","prompt":"성경책에서 출애굽기 16장 1절을 찾아 읽어 보세요.","confirm":{"prompt":"이스라엘 온 회중은 엘림을 떠나 어느 광야에 이르렀나요?","options":[{"label":"신 광야","ok":true},{"label":"수르 광야","basis":"출 15:22"},{"label":"바란 광야","basis":"민 13:3"}]}},"t2":{"type":"find","ref":"출 16:2-3","prompt":"성경책에서 출애굽기 16장 2절과 3절을 읽어 보세요.","confirm":{"prompt":"신 광야에서 온 회중이 모세와 아론을 원망한 까닭은 무엇인가요?","options":[{"label":"애굽에서는 떡을 배불리 먹었는데, 이 광야에서는 온 회중이 굶주려 죽게 되었다고 여겼기 때문에","ok":true},{"label":"모세와 아론이 자기들만 장막에 머물며 먹을 것을 혼자 다 차지했다고 여겼기 때문에","basis":"본문에 없음"},{"label":"마실 물이 없어 자기들과 자녀와 가축이 모두 목말라 죽게 되었다고 여겼기 때문에","basis":"출 17:3"}]}},"t3":{"type":"find","refs":["출 15:27","출 16:1"],"prompt":"출애굽기 15장 27절과 16장 1절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 회중이 신 광야에 이르기 전에 머문 곳은 어떤 곳이었는가?","options":[{"label":"물샘 열둘과 종려나무 일흔 그루가 있는 엘림에 장막을 쳤다가, 엘림을 떠나 시내 산과 엘림 사이에 있는 신 광야로 왔다","ok":true},{"label":"쓴 물만 있어 마실 수 없는 엘림에 장막을 쳤다가, 엘림을 떠나 시내 산과 엘림 사이에 있는 신 광야로 왔다","basis":"출 15:23"},{"label":"물샘 열둘과 종려나무 일흔 그루가 있는 엘림에 장막을 쳤다가, 엘림을 떠나 곧장 시내 산에 이르렀다","basis":"본문에 없음"}]}}}},{"part":"handle","name":"손잡이","line":"손잡이가 여기 있었네! 장막들에서 떨어진 진 가장자리야.","found":"탐지기가 장막이 가득한 진 쪽을 가리켜요.","say":{"who":"choeon","text":"장막이 정말 많아! 진이 끝없이 넓어."},"q":{"t1":{"type":"find","ref":"출 16:13","prompt":"성경책에서 출애굽기 16장 13절을 찾아 읽어 보세요.","confirm":{"prompt":"저녁에 와서 진을 덮은 것은 무엇인가요?","options":[{"label":"메추라기","ok":true},{"label":"메뚜기","basis":"출 10:15"},{"label":"까마귀","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"출 16:11-12","prompt":"성경책에서 출애굽기 16장 11절과 12절을 읽어 보세요.","confirm":{"prompt":"여호와께서 저녁에는 고기를, 아침에는 떡을 주시겠다고 하신 것은 무엇 때문이라고 하셨나요?","options":[{"label":"그들이 여호와가 그들의 하나님인 줄 알게 하시려고","ok":true},{"label":"그들이 모세를 왕으로 세우게 하시려고","basis":"본문에 없음"},{"label":"그들이 애굽으로 돌아가는 길을 알게 하시려고","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["출 16:12","출 16:13"],"prompt":"출애굽기 16장 12절과 13절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 여호와께서 하신 말씀과 그 저녁과 아침에 있었던 일은 어떠한가?","options":[{"label":"여호와께서 저녁에 고기를 먹고 아침에 떡으로 배부르리라 하셨고, 저녁에는 메추라기 떼가 진을 덮었으며 아침에는 진 사방에 이슬이 있었다","ok":true},{"label":"여호와께서 저녁에 고기를 먹고 아침에 떡으로 배부르리라 하셨고, 저녁에는 메뚜기 떼가 진을 덮었으며 아침에는 진 사방에 서리가 있었다","basis":"본문에 없음"},{"label":"여호와께서 아침에만 떡으로 배부르리라 하셨고, 저녁에는 아무 일도 없었으며 아침에는 진 사방에 이슬이 있었다","basis":"본문에 없음"}]}}}},{"part":"battery","name":"건전지","line":"건전지를 찾았어! 진에서 떨어진 빈 땅에 있었네.","found":"탐지기가 진에서 떨어진 광야의 빈 땅을 가리켜요.","say":{"who":"onwoo","text":"진 안쪽으로는 들어가지 말고 보기만 하자. 우리는 지켜보는 사람이야. 이 광야에서 있었던 일은 16장 14절과 15절에서 확인하자."},"q":{"t1":{"type":"find","ref":"출 16:14","prompt":"성경책에서 출애굽기 16장 14절을 찾아 읽어 보세요.","confirm":{"prompt":"이슬이 마른 뒤 광야 땅 위에 있던 것은 어떤 모양이었나요?","options":[{"label":"작고 둥글었어요","ok":true},{"label":"크고 네모났어요","basis":"본문에 없음"},{"label":"길고 뾰족했어요","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"출 16:14-15","prompt":"성경책에서 출애굽기 16장 14절과 15절을 읽어 보세요.","confirm":{"prompt":"이스라엘 자손이 땅 위의 것을 보고 서로 그것이 무엇인지 물은 까닭은 무엇인가요?","options":[{"label":"그것이 무엇인지 몰랐기 때문에","ok":true},{"label":"그것이 하늘에서 내린 양식인 줄 이미 알고 기뻐서","basis":"본문에 없음"},{"label":"서리처럼 가늘어서 서리가 내린 줄 알았기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["출 16:14","출 16:31"],"prompt":"출애굽기 16장 14절과 31절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 땅 위에 있던 그것은 어떤 것이었는가?","options":[{"label":"서리처럼 가늘고 작고 둥근 것이었고, 이스라엘 족속은 그 이름을 만나라 했으며, 깟씨처럼 생겼고 빛깔은 희며 꿀을 섞은 과자 맛이 났다","ok":true},{"label":"서리처럼 가늘고 작고 둥근 것이었고, 이스라엘 족속은 그 이름을 만나라 했으며, 빛깔은 붉고 맛은 쓴 나물 같았다","basis":"본문에 없음"},{"label":"크고 둥근 떡 덩이였고, 이스라엘 족속은 그 이름을 만나라 했으며, 깟씨처럼 희고 꿀을 섞은 과자 맛이 났다","basis":"본문에 없음"}]}}}}],"mission":{"call":{"t1":"최현 박사예요. 타임머신이 광야에 비상 착륙하면서 전구와 손잡이와 건전지가 망가졌어요. 탐지기가 가리키는 곳에서 대신 쓸 재료를 찾아봐요.","t2":"최현 박사예요. 비상 착륙한 곳은 신 광야예요. 전구와 손잡이와 건전지가 망가졌는데, 이 시대에는 우리 부속이 없어요. 탐지기가 가리키는 곳에서 대신 쓸 재료를 하나씩 찾아야 해요.","t3":"최현 박사다. 타임머신이 신 광야에 비상 착륙해 전구, 손잡이, 건전지가 망가졌고 지금은 통신만 이어져 있다. 이 시대에는 부속이 없으니 탐지기가 가리키는 곳마다 재료를 구해 세 부속을 대신 만들어야 한다. 진 가장자리에서 사람들의 평범한 일은 거들 수 있지만, 그 밖의 일에는 손대지 말고 지켜보기만 하자."},"materials":[{"key":"sand","name":"고운 모래","basis":"출 16:1","use":"고운 모래를 녹여 유리로 만들면 깨진 전구 대신 쓸 수 있어요.","how":"진에서 멀찍이 떨어진 광야 땅, 사람이 없는 곳에서 고운 모래를 한 줌 떠 담는다.","line":"진에서 멀찍이 떨어진 광야 땅에서 고운 모래를 한 줌 담았어!"},{"key":"cord","name":"장막 끈 토막","basis":"출 16:16","use":"장막 끈 토막을 단단히 감으면 부러진 손잡이 대신 쓸 수 있어요.","how":"장막들에서 멀리 떨어진 진 가장자리 땅에 끊어져 떨어져 있는 끈 토막 하나를 줍는다. 장막에서 끊어 내지 않는다.","line":"장막들에서 떨어진 진 가장자리에서 장막 끈 토막을 주웠어!"},{"key":"soil","name":"광야의 흙","basis":"출 16:14","use":"흙을 물통의 물로 축축하게 적셔 흙 전지를 만들면 건전지 대신 쓸 수 있어요.","how":"진에서 멀리 떨어진 광야의 빈 땅에서 흙을 한 줌 떠 담는다. 진 안쪽으로는 들어가지 않는다.","line":"진에서 떨어진 광야의 빈 땅에서 흙을 한 줌 담았어!"}],"companion":{"who":"모세","ref":"출 16:2","when":"after","talks":[{"ask":{"who":"choeon","text":"이슬이 마른 뒤 땅 위에 있던 것은 무엇이에요?"},"answer":{"t1":"모세는 그것이 여호와께서 먹으라고 주신 양식이라고 말했어요.","t2":"모세는 이스라엘 자손에게 말했어요. 그것은 여호와께서 그들이 먹도록 주신 양식이라고 했어요.","t3":"모세는 이스라엘 자손에게, 그것은 여호와께서 그들이 먹도록 주신 양식이라고 말했다."},"ref":"출 16:15","open":"출 16:15"},{"ask":{"who":"hyu","text":"일곱째 날에도 거두러 나가요?"},"answer":{"t1":"모세는 그날이 여호와의 안식일이라서 들에서 그것을 얻지 못할 것이라고 말했어요. 엿새 동안은 거두고 일곱째 날에는 없을 것이라고 했어요.","t2":"모세는 그날이 여호와께 안식일이어서 들에서 그것을 얻지 못할 것이라고 말했어요. 엿새 동안은 거두지만, 안식일인 일곱째 날에는 그것이 없을 것이라고 했어요.","t3":"모세는 그날 그것을 먹으라고 하며, 그날은 여호와께 안식일이므로 들에서 그것을 얻지 못할 것이라고 말했다. 엿새 동안은 거두되 안식일인 일곱째 날에는 그것이 없으리라고 했다."},"ref":"출 16:25-26","open":"출 16:26"},{"ask":{"who":"onwoo","text":"만나 한 오멜을 항아리에 담아 두라고 하신 것은 무엇 때문이에요?"},"answer":{"t1":"모세는 여호와께서 그것을 한 오멜 채워 대대로 간수하라고 명하셨다고 전했어요. 광야에서 먹이신 양식을 후손에게 보이기 위해서라고 했어요.","t2":"모세는 여호와께서 그것을 한 오멜 채워 대대로 간수하라고 명하셨다고 전했어요. 애굽에서 인도해 내실 때 광야에서 먹이신 양식을 후손이 볼 수 있게 하려는 것이라고 했어요. 그리고 아론에게, 항아리 하나에 만나를 한 오멜 넣어서 여호와 앞에 두라고 했어요.","t3":"모세는 여호와께서 명하신 것을 전했다. 그것을 한 오멜 채워 대대로 간수하라는 것이었고, 애굽 땅에서 인도해 내실 때 광야에서 먹이신 양식을 후손이 보게 하려는 것이라고 했다. 모세는 또 아론에게, 항아리 하나를 가져다 만나를 한 오멜 넣어서 여호와 앞에 두고 대대로 간수하라고 했다."},"ref":"출 16:32-33","open":"출 16:32"}]},"today":[{"q":"하나님은 왜 광야에서 날마다 만나를 주셨어요?","a":{"t1":"하나님은 백성이 날마다 그날 먹을 것을 거두게 하여, 하나님의 율법대로 행하는지 시험하겠다고 하셨어요. 신명기에서 모세는, 사람은 떡만으로 살지 않고 여호와께서 하시는 모든 말씀으로 산다는 것을 알게 하시려고 만나를 먹이셨다고 말했어요.","t2":"출애굽기 16장 4절에서 하나님은, 백성이 날마다 나가서 그날 먹을 것을 거두게 하여 그들이 하나님의 율법대로 행하는지 시험하겠다고 하셨어요. 신명기 8장 3절에서 모세는, 하나님이 백성을 낮추시고 주리게 하시며 그들도 조상도 알지 못하던 만나를 먹이신 것은 사람이 떡만으로 살지 않고 여호와께서 하시는 모든 말씀으로 산다는 것을 알게 하시려는 것이었다고 말했어요.","t3":"하나님은 백성이 날마다 나가 그날 쓸 것을 거두게 하여, 그들이 하나님의 율법대로 행하는지 시험하겠다고 하셨다(출 16:4). 신명기에서 모세는, 하나님이 사십 년 동안 광야 길을 걷게 하신 것은 그들을 낮추시고 시험하여 그 마음이 어떠한지, 명령을 지키는지 알려 하신 것이며(신 8:2), 그들도 조상도 알지 못하던 만나를 먹이신 것은 사람이 떡만으로 살지 않고 여호와께서 하시는 모든 말씀으로 산다는 것을 알게 하시려는 것이었다고 말했다(신 8:3). 성경은 여기까지 말한다."},"refs":["출 16:4","신 8:2-3"]},{"q":"많이 거둔 사람도 남지 않고 적게 거둔 사람도 모자라지 않았다니, 어떻게 그렇게 돼요?","a":{"t1":"성경은 오멜로 되어 보니 그렇게 되었다고만 적어요. 어떻게 그렇게 되었는지는 성경이 말하지 않아요.","t2":"이스라엘 자손은 많이 거두기도 하고 적게 거두기도 했어요. 그런데 오멜로 되어 보니 많이 거둔 사람도 남는 것이 없고 적게 거둔 사람도 모자라는 것이 없었다고 성경은 적어요. 어떻게 그렇게 되었는지는 성경이 더 말하지 않아요.","t3":"본문은 이스라엘 자손이 많이 거두기도 하고 적게 거두기도 했으나, 오멜로 되어 보니 많이 거둔 이에게 남는 것이 없고 적게 거둔 이에게 모자라는 것이 없어 저마다 먹을 만큼 거두었다고 기록한다(출 16:17-18). 어떻게 그렇게 되었는지는 말하지 않는다. 성경은 여기까지 말한다."},"refs":["출 16:17-18"]}],"help":{"who":"신 광야에 장막을 친 이스라엘 자손","steps":[{"kind":"do","after":0,"title":"짐 내리기 돕기","basis":"출 16:1","text":{"t1":"온 회중이 광야에 머물러요. 우리는 진 가장자리의 한 집 식구들 곁에서 짐을 내리고 나르는 일을 도와요.","t2":"엘림을 떠난 이스라엘 온 회중이 신 광야에 와 있어요. 우리는 진 가장자리의 한 집 식구들 곁에서 짐을 내리고 장막 둘레를 정리하는 일을 도와요. 본문에 적힌 일이 아니라 탐험대 이야기예요.","t3":"엘림을 떠난 이스라엘 온 회중이 신 광야에 와 있다(16:1). 탐험대는 진 가장자리의 한 집 식구들 곁에서 짐을 내리고 장막 둘레를 정리하는 일을 거든다. 본문에 적힌 일이 아니라 탐험대 이야기다."},"tasks":["짐 꾸러미 내려 주기","짐을 장막 곁으로 함께 옮기기","장막 둘레 자리 정리하기"],"done":{"who":"choeon","text":"짐을 다 옮겼어. 이 집 식구들도 여기 진 가장자리에 자리를 잡았어."}},{"kind":"watch","after":2,"title":"곁에서 보기 · 구름 속에 나타난 영광","basis":"출 16:10","text":{"t1":"아론이 회중에게 말할 때, 사람들이 광야 쪽을 보았어요. 구름 속에 여호와의 영광이 나타났어요. 우리는 진 가장자리에서 함께 그쪽을 봐요.","t2":"아론이 회중에게 말하는 동안 사람들이 광야 쪽으로 눈을 돌렸어요. 구름 속에 여호와의 영광이 나타났어요. 우리는 구름 쪽으로 다가가지 않고 진 가장자리에서 함께 봐요.","t3":"아론이 회중에게 말하는 동안 사람들이 광야 쪽으로 눈을 돌렸고, 구름 속에 여호와의 영광이 보였다(16:10). 탐험대는 구름 쪽으로 다가가지 않고 진 가장자리에서 그쪽을 바라본다."},"say":{"who":"choeon","text":"모두 광야 쪽을 보고 있어. 우리도 여기서 보자."}},{"kind":"watch","after":4,"title":"곁에서 보기 · 아침마다 거두는 사람들","basis":"출 16:21","text":{"t1":"사람들은 아침마다 먹을 만큼 거두었어요. 해가 뜨거워지면 그것은 스러졌어요. 우리는 거두지 않고 곁에서 지켜봐요.","t2":"사람들은 아침마다 저마다 먹을 만큼 거두었어요. 해가 뜨겁게 내리쬐면 땅 위의 그것은 스러졌어요. 여호와께서 주신 그 양식은 우리가 거두지도 맛보지도 않고, 곁에서 지켜봐요.","t3":"이스라엘 자손은 아침마다 각자 먹을 만큼 거두었고, 햇볕이 뜨거워지면 그것은 스러졌다(16:21). 여호와께서 주신 그 양식을 탐험대는 거두지도 맛보지도 않는다. 곁에서 지켜볼 뿐이다."},"say":{"who":"onwoo","text":"우리는 거두지 않아. 곁에서 보기만 하자."}},{"kind":"stay","after":5,"title":"일곱째 날, 그 자리에서 함께 쉬기","basis":"출 16:29-30","text":{"t1":"일곱째 날이에요. 여호와께서 그날에는 각자 머무는 곳에 있으라고 하셨어요. 우리도 들로 나가지 않고 그 자리에서 쉬어요.","t2":"여호와께서는 일곱째 날에 아무도 각자 머무는 곳을 떠나 나가지 말라고 하셨어요. 그래서 백성은 일곱째 날에 쉬었어요. 우리도 들로 나가지 않고 그 자리에 머물며 함께 쉬어요.","t3":"여호와께서는 일곱째 날에 아무도 각자 머무는 곳을 떠나 나가지 말라고 하셨고, 백성은 그날 쉬었다. 탐험대도 들로 나가지 않고 그 자리에 머물며 함께 쉰다."},"wait":"그 자리에서 함께 쉬기","say":{"who":"hyu","text":"오늘은 일곱째 날이야. 들에 나가지 않아."}},{"kind":"ask","after":"gates","title":"해 질 무렵과 아침에 주신 것은 무슨 뜻이에요?","basis":"출 16:6-8","by":"모세","ask":{"who":"choeon","text":"해 질 무렵과 아침에 주신 것은 무슨 뜻이에요?"},"answer":{"t1":"모세는 아론과 함께, 저녁이 되면 여호와께서 그들을 애굽에서 이끌어 내셨음을 알게 될 것이라고 말했어요. 아침에는 여호와의 영광을 보게 될 것이라고 했어요.","t2":"모세는 아론과 함께 이스라엘 자손에게 말했어요. 저녁이 되면 여호와께서 그들을 애굽에서 이끌어 내셨음을 알게 되고, 아침에는 여호와의 영광을 보게 될 것이라고 했어요. 모세는 또, 해 질 무렵에는 고기로, 아침에는 떡으로 여호와께서 그들을 넉넉히 먹이실 것이라고 말했어요.","t3":"모세는 아론과 함께 이스라엘 자손 모두에게, 저녁이 되면 그들을 애굽에서 인도해 내신 분이 여호와이심을 알게 되고 아침에는 여호와의 영광을 보게 되리라고 말했다(16:6-7). 모세는 또 해 질 무렵에는 고기로, 아침에는 떡으로 여호와께서 그들을 넉넉히 먹이실 것이라고 말했다(16:8)."},"read":{"t1":{"type":"find","ref":"출 16:12","prompt":"성경책에서 출애굽기 16장 12절을 찾아 읽어 보세요.","confirm":{"prompt":"여호와께서는 그 고기와 떡으로 백성이 무엇을 알게 되리라고 하셨나요?","options":[{"label":"여호와가 그들의 하나님이신 줄","ok":true},{"label":"모세가 그들의 왕인 줄","basis":"본문에 없음"},{"label":"광야에 물이 많은 줄","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"출 16:7-8","prompt":"성경책에서 출애굽기 16장 7절과 8절을 읽어 보세요.","confirm":{"prompt":"모세가, 저녁의 고기와 아침의 떡을 여호와께서 주실 것이라고 하면서 말한 까닭은 무엇인가요?","options":[{"label":"여호와께서 그들이 여호와를 향해 원망하는 말을 들으셨기 때문에","ok":true},{"label":"백성이 원망하던 것을 그치고 여호와께 잘못을 빌었기 때문에","basis":"본문에 없음"},{"label":"백성의 원망이 커서 모세와 아론이 더 다스릴 수 없었기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["출 16:3","출 16:6","출 16:8"],"prompt":"출애굽기 16장 3절, 6절, 8절을 함께 찾아 읽어 보자.","confirm":{"prompt":"세 곳을 이어 읽으면, 백성을 광야로 이끌어 낸 이를 두고 무엇을 알 수 있는가?","options":[{"label":"백성은 모세와 아론이 자기들을 광야로 이끌어 냈다고 원망했지만, 모세와 아론은 저녁에 여호와께서 그들을 애굽에서 인도해 내셨음을 알게 되리라 했고, 모세는 그 원망이 자기들이 아니라 여호와를 향한 것이라고 했다","ok":true},{"label":"백성은 모세와 아론이 자기들을 광야로 이끌어 냈다고 원망했고, 모세와 아론도 저녁이 되면 자기들이 백성을 애굽에서 이끌어 냈음을 알게 되리라 했으며, 모세는 그 원망이 자기들을 향한 것이라고 했다","basis":"본문에 없음"},{"label":"백성은 모세와 아론이 자기들을 광야로 이끌어 냈다고 원망했지만, 모세와 아론은 저녁에 여호와께서 그들을 애굽에서 인도해 내셨음을 알게 되리라 했고, 모세는 그 원망이 여호와가 아니라 아론을 향한 것이라고 했다","basis":"본문에 없음"}]}}},"nt":{"ref":"요 6:31-32","text":"신약의 요한복음 6장 31~32절에서 사람들이 조상들이 먹은 광야의 만나를 말하자, 예수님은 하늘에서 내린 떡을 준 이는 모세가 아니라고 하시며 아버지께서 하늘에서 참 떡을 주신다고 말씀하신다."}}]}},"has3d":true,"epic":false},"OT-14":{"id":"OT-14","era":4,"title":"금송아지","ref":"출 32:1-35","place":"시내 산 아래의 진","review":{"required":true,"topics":["재앙과 심판(출 32:10, 32:26-28, 32:33-35)","구약 사건의 신약적 의미(행 7:39-41)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"출 32:1-4","focus":"people","text":{"t1":"모세가 산에서 내려오는 것이 늦어지자, 백성은 아론에게 자기들을 인도할 신을 만들라고 했어요. 아론은 백성이 가져온 금고리로 송아지 형상을 만들었어요.","t2":"백성은 아론에게 모여들어 자기들을 인도할 신을 만들라고 했는데, 왜 그랬는지는 1절에서 찾아봐요. 아론은 아내와 자녀들의 귀에 있는 금고리를 빼어 가져오라고 했고, 그것을 받아 송아지 형상을 만들었어요. 백성은 그것이 자기들을 애굽에서 인도해 낸 신이라고 말했어요.","t3":"백성은 모세가 산에서 내려오는 것이 더딘 것을 보고 아론에게 모여, 자기들을 인도할 신을 만들라고 했다. 자기들을 애굽 땅에서 이끌어 낸 사람 모세가 어떻게 되었는지 모르겠다는 것이 그들의 말이었다. 아론은 아내와 자녀의 귀에서 금고리를 빼어 가져오게 했고, 모든 백성이 금고리를 가져오자 그것을 받아 부어서 새기는 연장으로 다듬어 송아지 형상을 만들었다. 그들은 이것이 이스라엘을 애굽 땅에서 인도해 낸 신이라고 말했다."},"say":{"who":"hyu","text":"모세는 아직 산 위에 있어. 여기는 산 아래 진이야. 일지에 적어 둘게."}},{"ref":"출 32:5-6","focus":"altar","text":{"t1":"아론은 송아지 앞에 단을 쌓았어요. 다음 날 백성은 제사를 드리고, 먹고 마시며 뛰놀았어요.","t2":"아론은 그것을 보고 송아지 앞에 단을 쌓고, 내일은 여호와의 절일이라고 알렸어요. 이튿날 백성은 일찍 일어나 번제와 화목제를 드렸어요. 그리고 앉아서 먹고 마시다가 일어나 뛰놀았어요.","t3":"아론은 그것을 보고 그 앞에 단을 쌓은 뒤, 내일은 여호와의 절일이라고 선포했다. 이튿날 그들은 일찍 일어나 번제를 드리고 화목제를 드렸으며, 앉아서 먹고 마신 뒤 일어나 뛰놀았다."},"say":{"who":"choeon","text":"송아지 앞에 단이 있어. 사람들이 먹고 마시고 뛰놀고 있어."}},{"ref":"출 32:7-10","open":"출 32:7-8","focus":"mountain","text":{"t1":"하나님은 모세에게 내려가라고 하시며, 백성이 송아지를 만들어 숭배했다고 하셨어요. 하나님은 그들에게 크게 노하셔서 화를 내리겠다고 하셨어요.","t2":"여호와께서는 모세에게 내려가라고 하시며 백성이 부패했다고 하셨는데, 백성이 무엇을 했다고 하셨는지는 8절에서 찾아봐요. 또 이 백성은 목이 곧은 백성이라고 하시며, 그들에게 진노하여 멸하고 모세를 큰 나라가 되게 하겠다고 하셨어요.","t3":"여호와께서는 모세에게 내려가라고 하시며, 모세가 애굽 땅에서 이끌어 낸 백성이 부패했다고 하셨다. 백성이 무엇을 했다고 하셨는지는 8절에서 직접 읽어 보자. 여호와께서는 또 이 백성이 목이 곧은 백성임을 보았다고 하시고, 하시는 대로 두라고 하시며, 그들에게 진노하여 멸하고 모세를 큰 나라가 되게 하겠다고 하셨다."},"say":{"who":"onwoo","text":"하나님이 모세에게 하신 말씀은 출애굽기 32장 7절부터야. 성경책에서 직접 읽어 보자."}},{"ref":"출 32:11-14","focus":"moses","text":{"t1":"모세는 아브라함, 이삭, 이스라엘을 기억해 달라고 하며, 그들에게 하신 맹세를 하나님께 아뢰었어요. 여호와께서는 뜻을 돌이키셔서 그 화를 백성에게 내리지 않으셨어요.","t2":"모세는 여호와께 구했어요. 큰 권능으로 애굽에서 인도해 내신 주의 백성에게 화를 내리지 말아 달라고 했어요. 아브라함과 이삭과 이스라엘을 기억해 달라고 하며, 주께서 그들에게 하늘의 별같이 자손을 많게 하겠다고 맹세하셨다고 아뢰었어요. 여호와께서는 뜻을 돌이키셔서, 말씀하신 그 화를 백성에게 내리지 않으셨어요.","t3":"모세는 자기 하나님 여호와께 구했다. 큰 능력과 강한 손으로 애굽 땅에서 이끌어 내신 주의 백성에게 어찌하여 진노하시느냐고 아뢰고, 애굽 사람들이 여호와가 그 백성을 산에서 죽이고 땅 위에서 없애려고 이끌어 냈다고 말하게 하시겠느냐고 했다. 맹렬한 노를 그치고 뜻을 돌이켜 이 화를 내리지 말아 주시기를 구했으며, 주의 종 아브라함, 이삭, 이스라엘을 기억해 주시기를 구했다. 주께서 그들에게 하늘의 별같이 자손을 많게 하고 허락하신 온 땅을 그 자손에게 영원한 기업으로 주겠다고 맹세하셨다는 것이다. 여호와께서는 뜻을 돌이키셔서, 말씀하신 그 화를 백성에게 내리지 않으셨다."},"say":{"who":"hyu","text":"모세가 여호와께 구했어. 그다음에 일어난 일은 14절에 있어. 순서대로 적어 둘게."}},{"ref":"출 32:15-20","focus":"tablets","text":{"t1":"모세는 두 판을 들고 산에서 내려와, 송아지와 춤추는 것을 보고 크게 노하여 판들을 던져 깨뜨렸어요. 그 뒤에 모세가 송아지를 어떻게 했는지는 20절에서 찾아봐요.","t2":"모세는 증거의 두 판을 손에 들고 산에서 내려왔어요. 그 판은 하나님이 만드셨고, 글자도 하나님이 써서 새기신 것이었어요. 그 뒤에 진 가까이에서 무슨 일들이 어떤 차례로 있었는지는 17절부터 20절까지 읽어 봐요.","t3":"모세는 몸을 돌려 산에서 내려왔다. 손에는 증거의 두 판이 있었는데, 양면 이쪽저쪽에 글자가 있었다. 그 판을 누가 만들고 글자를 누가 새겼는지는 16절에 있다. 여호수아가 백성이 떠드는 소리를 듣고 진에서 싸우는 소리가 난다고 하자, 모세는 이긴 자의 노래도 진 자의 부르짖음도 아니고 자기가 듣기에는 노래하는 소리라고 대답했다. 진에 가까이 와서 송아지와 춤추는 것을 본 모세는 크게 노하여 손에 든 판들을 산 아래로 던져 깨뜨렸다. 그리고 그들이 만든 송아지를 가져다가 불사르고 부수어 가루로 만든 다음, 그 가루를 물에 뿌려 이스라엘 자손이 마시게 했다."},"say":{"who":"choeon","text":"모세가 두 판을 들고 내려왔어."}},{"ref":"출 32:21-29","open":"출 32:26-28","focus":"gate","text":{"t1":"모세는 아론에게, 백성이 어떻게 했기에 그가 그들을 큰 죄에 빠지게 했느냐고 물었어요. 모세가 진 문에서 부르자 레위 자손이 모였고, 그들은 모세의 말대로 했어요.","t2":"모세는 아론에게, 백성이 그에게 어떻게 했기에 그가 그들을 큰 죄에 빠지게 했느냐고 물었어요. 아론은 백성이 신을 만들라고 하기에 금을 받아 불 속에 던지니 이 송아지가 나왔다고 대답했어요. 모세가 진 문에 서서 여호와의 편에 있는 사람은 자기에게 나아오라고 하자 레위 자손이 모두 모였어요. 레위 자손은 모세가 말한 대로 했고, 그날 백성 가운데 삼천 명가량이 죽임을 당했어요.","t3":"모세는 아론에게 물었는데, 무엇을 물었는지는 21절에서 직접 읽어 보자. 아론은 노하지 말라고 하며, 이 백성이 악한 것을 모세가 안다고 했다. 백성이 자기들을 인도할 신을 만들라고 하기에 금이 있는 사람은 빼어 내라고 했고, 가져온 것을 불 속에 던지니 이 송아지가 나왔다고 했다. 모세가 보니 백성이 방자했는데, 아론이 그들을 방자하게 하여 원수의 조롱거리가 되게 한 것이었다. 모세가 진 문에 서서 여호와의 편에 있는 사람은 누구든지 자기에게 나아오라고 하자 레위 자손이 다 모였다. 모세는 그들에게 이스라엘의 하나님 여호와의 말씀을 전했는데, 각자 허리에 칼을 차고 진의 이 문에서 저 문까지 오가라는 것이었다. 레위 자손은 모세가 말한 대로 했고, 그날 백성 가운데 삼천 명가량이 죽임을 당했다. 모세는 그들이 오늘 여호와께 헌신하게 되었으며 여호와께서 복을 내리실 것이라고 말했다."},"say":{"who":"onwoo","text":"모세가 전한 말씀과 그날 일어난 일은 32장 26절부터 28절에 적혀 있어. 성경책에서 확인하자."}},{"ref":"출 32:30-35","open":"출 32:33-34","focus":"moses","text":{"t1":"다음 날 모세는 여호와께 다시 나아가 백성의 죄를 사해 주시기를 구했어요. 여호와께서는 모세에게 백성을 인도하라고 하셨고, 송아지를 만든 일 때문에 백성을 치셨어요.","t2":"이튿날 모세는 백성에게 그들이 큰 죄를 지었다고 말하고, 여호와께 다시 나아갔어요. 모세는 백성의 죄를 사해 주시기를 구하며, 그렇게 하지 않으시려면 주께서 기록하신 책에서 자기 이름을 지워 달라고 했어요. 여호와께서는 누구든지 범죄한 사람을 그 책에서 지우겠다고 하시고, 모세에게 가서 백성을 인도하라고 하셨어요. 그리고 여호와께서는 송아지를 만든 일 때문에 백성을 치셨어요.","t3":"이튿날 모세가 백성에게 한 말은 30절에 있다. 모세는 혹시 백성의 죄를 속할 수 있을까 하여 여호와께 올라가겠다고 했다. 모세는 여호와께 다시 나아가, 이 백성이 자기들을 위해 금으로 신을 만들어 큰 죄를 범했다고 아뢰었다. 그리고 그들의 죄를 사해 주시기를 구하며, 그렇게 하지 않으시려거든 주께서 기록하신 책에서 자기 이름을 지워 달라고 했다. 여호와께서는 누구든지 여호와께 범죄한 사람을 그 책에서 지우겠다고 하셨다. 또 모세에게 이제 가서 말씀하신 곳으로 백성을 인도하라고 하시며, 여호와의 사자가 모세 앞에서 갈 것이나 보응하는 날에는 그들의 죄를 보응하겠다고 하셨다. 여호와께서는 백성을 치셨는데, 아론이 만든 그 송아지를 그들이 만들었기 때문이다."},"say":{"who":"hyu","text":"이튿날 일이야. 모세가 여호와께 다시 나아갔다고 적어 둘게."}}],"gates":{"t1":[{"type":"find","ref":"출 32:2","prompt":"성경책에서 출애굽기 32장 2절을 찾아 읽어 보세요.","confirm":{"prompt":"아론은 누구의 귀에 있는 금고리를 빼어 가져오라고 했나요?","options":[{"label":"아내와 자녀들","ok":true},{"label":"나이 많은 장로들","basis":"본문에 없음"},{"label":"레위 자손들","basis":"본문에 없음"}]}},{"type":"multi","ref":"출 32:20","prompt":"성경책에서 출애굽기 32장 20절을 찾아 읽어 보세요.","confirm":{"prompt":"모세는 그들이 만든 송아지를 어떻게 했나요? 모두 고르세요.","options":[{"label":"불살랐어요","ok":true},{"label":"송아지 앞에 단을 쌓았어요","basis":"출 32:5"},{"label":"부수어 가루로 만들었어요","ok":true},{"label":"아론에게 돌려주었어요","basis":"본문에 없음"},{"label":"가루를 물에 뿌려 백성이 마시게 했어요","ok":true}]}}],"t2":[{"type":"find","ref":"출 32:1-4","prompt":"성경책에서 출애굽기 32장 1절부터 4절까지 읽어 보세요.","confirm":{"prompt":"백성이 아론에게 자기들을 인도할 신을 만들라고 한 까닭은 무엇인가요?","options":[{"label":"산에 오른 모세가 오래도록 내려오지 않자, 자기들을 애굽에서 이끌어 낸 그가 어떻게 되었는지 모르겠다고 여겼기 때문에","ok":true},{"label":"자기들끼리 한 우두머리를 세우고, 그 우두머리를 따라 애굽으로 다시 돌아가려고 했기 때문에","basis":"민 14:4"},{"label":"애굽에서는 고기 가마 곁에서 떡을 배불리 먹었는데, 이 광야에서는 먹을 것이 떨어져 굶주리게 되었기 때문에","basis":"출 16:3"}]}},{"type":"order","ref":"출 32:15-20","prompt":"성경책에서 출애굽기 32장 15절부터 20절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["모세가 두 판을 들고 산에서 내려왔다","여호수아가 진에서 싸우는 소리가 난다고 했다","모세가 노래하는 소리라고 대답했다","모세가 판들을 던져 깨뜨렸다","모세가 송아지를 불살라 가루로 만들었다"]}],"t3":[{"type":"find","refs":["출 32:16","출 32:19"],"prompt":"출애굽기 32장 16절과 19절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 모세가 깨뜨린 판은 어떤 판이었는가?","options":[{"label":"하나님이 만드시고 글자도 하나님이 써서 새기신 판이었는데, 모세가 송아지와 춤추는 것을 보고 크게 노하여 산 아래로 내던져 깨뜨렸다","ok":true},{"label":"모세가 산에서 직접 깎아 만든 돌판이었는데, 모세가 송아지와 춤추는 것을 보고 크게 노하여 산 아래로 내던져 깨뜨렸다","basis":"출 34:4"},{"label":"하나님이 만드신 판이었지만 글자는 모세가 새긴 것이었는데, 모세가 송아지와 춤추는 것을 보고 크게 노하여 산 아래로 내던져 깨뜨렸다","basis":"본문에 없음"}]}},{"type":"match","refs":["출 32:2","출 32:4","출 32:24"],"prompt":"출애굽기 32장 2절, 4절, 24절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"출 32:2","text":"아론이 백성에게, 아내와 자녀들의 귀에 있는 금고리를 빼어 가져오라고 했다"},{"ref":"출 32:4","text":"아론이 그 금을 받아 부어서 송아지 모양을 만들었다"},{"ref":"출 32:24","text":"아론이 모세에게, 금을 불에 던지자 이 송아지가 생겨 나왔다고 대답했다"}],"after":"세 곳을 이으면, 아론은 금고리를 가져오라고 했고 그 금을 받아 부어서 송아지 모양을 만들었는데, 모세가 물을 때에는 금을 불에 던지자 이 송아지가 생겨 나왔다고 대답했다."}]},"cards":[{"ref":"출 32:16","title":"하나님이 만드신 판"},{"ref":"출 32:14","title":"화를 내리지 아니하심"}],"close":{"t1":{"kind":"prayer","text":"하나님, 산 아래에서 있었던 일을 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 출애굽기 32장 1절부터 14절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"출 32:1-35에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 타임머신이 산 아래에 비상 착륙하면서 균형추가 깨졌어요. 균형추 대신 쓸 재료를 찾아봐요.","t2":"최현 박사예요. 비상 착륙 때 균형추가 깨져서 타임머신이 한쪽으로 기울었어요. 이 시대에는 우리 부속이 없으니, 이곳에서 균형추 대신 쓸 재료를 찾아야 해요.","t3":"최현 박사다. 산 아래에 비상 착륙하면서 균형추가 깨져 타임머신이 기울었고 지금은 통신만 이어져 있다. 이 시대에는 부속이 없으니 이곳에서 구할 수 있는 재료로 균형추를 대신 만들어야 한다. 진에서 일어나는 일에는 가까이 가지 말고 지켜보기만 하자."},"materials":[{"key":"gravel","name":"산기슭 자갈","basis":"출 32:1","use":"자갈을 주머니에 가득 담으면 깨진 균형추 대신 쓸 수 있어요.","how":"진에서 떨어진 산기슭 길가에 굴러 있는 작은 자갈을 몇 개 줍는다. 판이 깨진 산 아래 자리와 송아지가 있던 진 안에는 가까이 가지 않는다.","line":"진에서 떨어진 산기슭 길가에서 자갈을 주웠어!"}],"companion":{"who":"모세","ref":"출 32:19","when":"after","talks":[{"ask":{"who":"choeon","text":"산 위에서 여호와께 무엇을 구하셨어요?"},"answer":{"t1":"모세는 주의 백성에게 화를 내리지 말아 달라고 구했어요. 아브라함과 이삭과 이스라엘, 곧 주의 종들을 기억해 달라고 했어요.","t2":"모세는 큰 능력으로 애굽에서 이끌어 내신 주의 백성에게 어찌하여 진노하시느냐고 아뢰었어요. 노를 그치시고 뜻을 돌이켜 이 화를 내리지 말아 달라고 구했어요. 그리고 아브라함과 이삭과 이스라엘, 곧 주의 종들을 기억해 달라고 하며, 주께서 그들의 자손을 하늘의 별처럼 많게 하겠다고 맹세하셨다고 아뢰었어요.","t3":"모세는 큰 능력과 강한 손으로 애굽 땅에서 이끌어 내신 주의 백성에게 어찌하여 진노하시느냐고 아뢰었다. 애굽 사람들이, 여호와가 그 백성을 해치려고, 곧 산에서 죽이고 땅 위에서 없애려고 이끌어 냈다고 말하게 하시겠느냐고 했다. 맹렬한 노를 그치고 뜻을 돌이켜 이 화를 내리지 말아 달라고 구했으며, 아브라함과 이삭과 이스라엘, 곧 주의 종들을 기억해 달라고 했다. 주께서 그들의 자손을 하늘의 별처럼 늘리고 약속하신 온 땅을 그 자손에게 영원한 기업으로 주겠다고 그들에게 맹세하셨다는 것이다."},"ref":"출 32:11-13","open":"출 32:11"},{"ask":{"who":"hyu","text":"산에서 내려오실 때 진에서 들린 소리는 무슨 소리였어요?"},"answer":{"t1":"모세는 그것이 싸움에 이겨서 외치는 소리도, 져서 부르짖는 소리도 아니라고 했어요. 자기에게는 노래하는 소리로 들린다고 말했어요.","t2":"모세는 여호수아에게, 그것은 싸움에 이긴 사람들이 외치는 소리도 아니고 져서 부르짖는 소리도 아니라고 대답했어요. 자기 귀에는 노래하는 소리가 들린다고 했어요.","t3":"모세는 여호수아에게, 그것은 싸움에 이긴 자들이 외치는 소리도 아니고 져서 부르짖는 소리도 아니며, 자기가 듣기에는 노래하는 소리라고 대답했다."},"ref":"출 32:18","open":"출 32:18"},{"ask":{"who":"onwoo","text":"이튿날 여호와께 다시 나아가서는 무엇이라고 하셨어요?"},"answer":{"t1":"모세는 백성이 금으로 신을 만들어 큰 죄를 지었다고 아뢰었어요. 그들의 죄를 사해 주시고, 그렇게 하지 않으시려면 주의 책에서 자기 이름을 지워 달라고 했어요.","t2":"모세는 여호와께 다시 나아가, 이 백성이 금으로 신을 만들어 큰 죄를 지었다고 아뢰었어요. 그리고 그들의 죄를 사해 주시고, 그렇게 하지 않으시려면 주께서 기록하신 책에서 자기 이름을 지워 달라고 했어요.","t3":"모세는 여호와께 다시 나아가, 이 백성이 자기들을 위해 금으로 신을 만들어 큰 죄를 범했다고 아뢰었다. 그리고 이제 그들의 죄를 사해 주시기를 구하며, 그렇게 하지 않으시려거든 주께서 기록하신 책에서 자기 이름을 지워 달라고 했다."},"ref":"출 32:31-32","open":"출 32:32"}]},"today":[{"q":"모세는 왜 하나님이 만드신 판을 깨뜨렸어요?","a":{"t1":"모세는 송아지와 춤추는 것을 보고 크게 노하여 판들을 깨뜨렸어요. 신명기에서 모세는, 백성이 여호와께 죄를 지어 송아지를 만들고 명하신 길을 빨리 떠난 것을 보고 판을 깨뜨렸다고 말했어요.","t2":"출애굽기 32장 19절은, 모세가 진에 가까이 와서 송아지와 춤추는 것을 보고 크게 노하여 손에 든 판들을 산 아래로 던져 깨뜨렸다고 적어요. 신명기 9장 16~17절에서 모세는 그 일을 돌아보며, 백성이 여호와께 죄를 지어 송아지를 부어 만들고 여호와께서 명하신 길을 빨리 떠난 것을 보았기 때문에 두 돌판을 던져 그들 앞에서 깨뜨렸다고 말했어요.","t3":"본문은 모세가 진에 가까이 이르러 송아지와 춤추는 것을 보고 크게 노하여, 손에 든 판들을 산 아래로 던져 깨뜨렸다고 기록한다(출 32:19). 신명기에서 모세는 그 일을 돌아보며, 백성이 여호와께 범죄하여 송아지를 부어 만들고 여호와께서 명하신 길을 빨리 떠난 것을 보았으므로 두 돌판을 손에서 던져 그들의 눈앞에서 깨뜨렸다고 말했다(신 9:16-17). 성경은 여기까지 말한다."},"refs":["출 32:19","신 9:16-17"]},{"q":"깨진 판은 어떻게 되었어요? 판을 다시 받았어요?","a":{"t1":"여호와께서는 모세에게 처음 것과 같은 돌판 둘을 깎아 만들라고 하셨어요. 깨뜨린 처음 판에 있던 말씀을 그 판에 쓰겠다고 하셨어요.","t2":"출애굽기 34장 1절에서 여호와께서는 모세에게, 처음 것과 같은 돌판 둘을 깎아 만들라고 하시고 깨뜨린 처음 판에 있던 말씀을 그 판에 쓰겠다고 하셨어요. 모세는 돌판 둘을 깎아 만들어 시내 산에 올라갔고, 그 판들에는 언약의 말씀, 곧 십계가 기록되었어요. 깨진 조각이 어떻게 되었는지는 이 본문들이 말하지 않아요.","t3":"여호와께서는 모세에게 처음 것과 같은 돌판 둘을 깎아 만들라고 하시며, 모세가 깨뜨린 처음 판에 있던 말씀을 그 판에 쓰겠다고 하셨다(출 34:1). 모세는 그대로 돌판 둘을 깎아 들고 아침 일찍 시내 산에 올랐고(출 34:4), 사십 일 사십 야를 거기 있었으며, 그 판들에는 언약의 말씀 곧 십계가 기록되었다(출 34:28). 깨진 처음 판의 조각이 어떻게 되었는지는 이 본문들이 말하지 않는다."},"refs":["출 34:1","출 34:4","출 34:28"]}],"help":{"who":"모세","steps":[{"kind":"stay","after":1,"title":"잔치에 끼지 않고 산기슭에서 기다리기","basis":"출 32:5-6","text":{"t1":"사람들이 송아지 앞에서 먹고 마시며 뛰놀아요. 우리는 그 잔치에 끼지 않아요. 진에서 떨어진 산기슭에서 모세를 기다려요.","t2":"아론이 송아지 앞에 단을 쌓았고, 이튿날 사람들은 제물을 드린 뒤 먹고 마시며 뛰놀았어요. 우리는 그 잔치에 끼지 않아요. 진에서 떨어진 산기슭에 머물며 모세가 내려오기를 기다려요.","t3":"아론은 송아지 앞에 단을 쌓았고, 이튿날 백성은 번제와 화목제를 드린 뒤 앉아서 먹고 마시고 일어나 뛰놀았다(32:5-6). 탐험대는 금고리를 내지도, 잔치에 끼지도 않는다. 진에서 떨어진 산기슭에 머물며 모세가 내려오기를 기다린다."},"wait":"산기슭에서 기다리기","say":{"who":"hyu","text":"우리는 진 안으로 들어가지 않아. 여기서 기다리자."}},{"kind":"do","after":1,"title":"산기슭에서 일지 정리하기","basis":"출 32:1-6","text":{"t1":"우리는 진에서 떨어진 산기슭에서 모세를 기다려요. 기다리는 동안 본 일을 일지에 차례대로 정리해요.","t2":"우리는 잔치에 끼지 않고, 진에서 떨어진 산기슭에서 모세를 기다려요. 기다리는 동안 지금까지 본 일을 일지에 차례대로 정리해요. 진 안에서 하는 일은 돕지 않으니, 이것은 우리가 스스로 하는 탐험대 이야기예요.","t3":"탐험대는 진에서 떨어진 산기슭에서 모세를 기다리며, 백성이 금고리를 가져오고 아론이 송아지를 만들고 그 앞에서 제사와 잔치가 있었던 일을 일지에 차례대로 적는다. 진 안의 일은 돕지 않으므로, 이 정리는 탐험대가 스스로 하는 일이다. 탐험대 이야기다."},"tasks":["본 일을 차례대로 적기","일이 있었던 곳 적기","성경에서 확인할 장절 표시하기"],"done":{"who":"hyu","text":"다 적었어. 성경책에서 확인할 곳은 32장 1절부터 6절까지야."}},{"kind":"watch","after":4,"title":"곁에서 보기 · 깨진 두 판","basis":"출 32:19","text":{"t1":"모세가 두 판을 들고 산에서 내려왔어요. 우리는 판이 깨진 산 아래 자리에 다가가지 않고 멀리서 지켜봐요.","t2":"모세가 증거의 두 판을 들고 산에서 내려와 진 가까이 왔어요. 송아지와 춤추는 것을 본 모세는 크게 노했어요. 우리는 판이 깨진 산 아래 자리와 진 안에는 다가가지 않고 멀리서 지켜봐요.","t3":"모세는 증거의 두 판을 들고 산에서 내려와 진 가까이 이르렀고, 송아지와 춤추는 모습을 보자 크게 노하여 판들을 산 아래로 내던져 깨뜨렸다(32:19). 탐험대는 판이 깨진 자리와 진 안에 다가가지 않고 멀리서 지켜본다."},"say":{"who":"onwoo","text":"깨진 판에는 손대지 않을 거야."}},{"kind":"ask","after":"gates","title":"송아지를 만든 일은 어떤 일이었어요?","basis":"출 32:30","by":"모세","ask":{"who":"onwoo","text":"백성이 송아지를 만든 일은 어떤 일이었어요?"},"answer":{"t1":"모세는 아론에게, 백성이 그에게 어떻게 했기에 그가 그들을 큰 죄에 빠지게 했느냐고 물었어요. 이튿날에는 백성에게, 그들이 큰 죄를 지었다고 말했어요.","t2":"모세는 진에 내려와 아론에게 물었어요. 이 백성이 그에게 어떻게 했기에 그가 그들을 큰 죄에 빠지게 했느냐고 했어요. 그리고 이튿날 백성에게, 그들이 큰 죄를 지었다고 말했어요.","t3":"모세는 아론에게, 이 백성이 그에게 어떻게 했기에 그가 그들을 큰 죄에 빠지게 했느냐고 물었다(32:21). 이튿날에는 백성에게, 그들이 큰 죄를 범했다고 말했다(32:30)."},"read":{"t1":{"type":"find","ref":"출 32:8","prompt":"성경책에서 출애굽기 32장 8절을 찾아 읽어 보세요.","confirm":{"prompt":"여호와께서는 백성이 무엇을 속히 떠났다고 하셨나요?","options":[{"label":"여호와께서 명하신 길","ok":true},{"label":"애굽으로 가는 길","basis":"본문에 없음"},{"label":"광야의 우물","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"출 32:7-8","prompt":"성경책에서 출애굽기 32장 7절과 8절을 읽어 보세요.","confirm":{"prompt":"여호와께서 백성이 부패했다고 하신 까닭은 무엇인가요?","options":[{"label":"여호와께서 명하신 길을 빨리 떠나, 송아지를 만들어 섬기고 그 앞에 제물을 바쳤기 때문에","ok":true},{"label":"마실 물이 없다며 모세와 다투고, 물을 달라고 하며 여호와를 시험했기 때문에","basis":"출 17:2"},{"label":"안식일인 일곱째 날에도 몇몇이 양식을 거두러 들에 나갔기 때문에","basis":"출 16:27"}]}},"t3":{"type":"find","refs":["출 32:8","출 32:21","출 32:30"],"prompt":"출애굽기 32장 8절, 21절, 30절을 함께 찾아 읽어 보자.","confirm":{"prompt":"세 곳을 이어 읽으면, 송아지를 만든 일을 성경은 무엇이라고 말하는가?","options":[{"label":"여호와께서는 그들이 명하신 길을 빨리 떠나 송아지를 만들어 섬겼다고 하셨고, 모세는 아론에게 왜 백성을 큰 죄에 빠지게 했느냐고 물었으며, 이튿날 백성에게 그들이 큰 죄를 범했다고 말했다","ok":true},{"label":"여호와께서는 그들이 명하신 길을 빨리 떠났다고 하셨고, 모세는 아론에게 왜 백성을 큰 죄에 빠지게 했느냐고 물었으며, 이튿날 백성에게는 그 죄가 작으니 걱정하지 말라고 했다","basis":"본문에 없음"},{"label":"여호와께서는 그들이 명하신 길을 잘 지켰다고 하셨고, 모세는 아론에게 왜 백성을 큰 죄에 빠지게 했느냐고 물었으며, 이튿날 백성에게 그들이 큰 죄를 범했다고 말했다","basis":"본문에 없음"}]}}},"nt":{"ref":"행 7:39-41","text":"신약의 사도행전 7장 39~41절에서 스데반은, 조상들이 모세에게 순종하지 않고 마음이 애굽으로 향하여 아론에게 자기들을 인도할 신들을 만들라고 했으며, 그때 송아지를 만들고 그 우상 앞에 제물을 드렸으며 손수 만든 것을 두고 즐거워했다고 말한다."}}]}},"has3d":false,"epic":false},"OT-15":{"id":"OT-15","era":4,"title":"열두 정탐꾼","ref":"민 13:1-14:38","place":"바란 광야 가데스, 가나안 땅","review":{"required":true,"topics":["재앙과 심판(민 14:11-12, 14:22-23, 14:28-37)","구약 사건의 신약적 의미(히 3:17-19)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"민 13:1-20","open":"민 13:2","focus":"spies","text":{"t1":"하나님은 모세에게 지파마다 한 사람씩, 가나안 땅을 살펴볼 사람을 보내라고 하셨어요. 모세는 바란 광야에서 열두 사람을 보냈어요.","t2":"여호와께서는 모세에게, 이스라엘 자손에게 주시는 가나안 땅을 살펴보도록 지파마다 족장 한 사람씩 보내라고 하셨어요. 모세는 그 명령대로 바란 광야에서 열두 사람을 보냈어요. 그 가운데 유다 지파의 갈렙과 에브라임 지파의 호세아가 있었는데, 모세는 호세아를 여호수아라고 불렀어요. 모세는 그 땅과 거기 사는 사람들과 성읍이 어떠한지 살피고 그 땅의 열매를 가져오라고 했어요.","t3":"여호와께서는 모세에게, 가나안 땅을 살펴보도록 조상의 지파마다 지도자 한 사람씩을 보내라고 하셨다. 모세는 여호와의 명령에 따라 바란 광야에서 그들을 보냈는데, 모두 이스라엘 자손의 우두머리였다. 본문은 르우벤 지파의 삼무아부터 갓 지파의 그우엘까지 열두 사람의 이름을 적는다. 유다 지파의 사람은 여분네의 아들 갈렙, 에브라임 지파의 사람은 눈의 아들 호세아였고, 모세는 호세아를 여호수아라고 불렀다. 모세는 남방 길로 가서 산지로 올라가, 그 땅에 사는 사람들이 강한지 약한지 많은지 적은지, 땅이 좋은지 나쁜지, 성읍이 진영인지 산성인지, 땅이 기름진지 메마른지, 나무가 있는지 없는지 살피라고 했다. 또 담대하라고 하며 그 땅의 열매를 가져오라고 했다. 그때는 포도가 처음 익을 무렵이었다."},"say":{"who":"hyu","text":"여기는 바란 광야야. 지파마다 한 사람씩, 이름이 열둘이야. 일지에 적어 둘게."}},{"ref":"민 13:21-25","focus":"grapes","text":{"t1":"그들은 가나안 땅을 살피며, 에스골 골짜기에서 무언가를 잘라 두 사람이 막대기에 꿰어 멨어요. 무엇이었는지는 23절에서 찾아봐요.","t2":"그들은 올라가서 신 광야에서부터 르홉까지 땅을 살폈고, 헤브론에도 갔어요. 헤브론에는 아낙 자손이 있었어요. 그들이 이른 한 골짜기를 왜 에스골 골짜기라고 부르게 되었는지는 23절과 24절에서 찾아봐요. 그들은 사십 일 동안 땅을 살피고 돌아왔어요.","t3":"그들은 올라가 신 광야에서부터 하맛 어귀의 르홉까지 땅을 탐지했다. 남방으로 올라가 헤브론에 이르렀는데, 거기에는 아낙 자손인 아히만, 세새, 달매가 있었다. 에스골 골짜기에 이르러서는 포도 한 송이가 달린 가지를 잘라 두 사람이 막대기에 꿰어 메었고, 석류와 무화과도 가져왔다. 이스라엘 자손이 그곳에서 포도송이를 잘랐기 때문에 그곳을 에스골 골짜기라 부르게 되었다. 그들이 얼마 동안 땅을 탐지하고 돌아왔는지는 25절에 있다."},"say":{"who":"choeon","text":"두 사람이 막대기에 무언가를 꿰어서 메고 와!"}},{"ref":"민 13:26-29","focus":"report","text":{"t1":"그들은 가데스로 돌아와 그 땅의 열매를 보여 주며, 그 땅에는 정말로 젖과 꿀이 흐른다고 했어요. 그런데 그 땅 사람들은 강하고 성읍은 크고 튼튼하다고 했어요.","t2":"그들은 바란 광야 가데스로 돌아와 모세와 아론과 온 회중에게 보고하고 그 땅의 열매를 보여 주었어요. 그 땅에는 과연 젖과 꿀이 흐른다고 했어요. 그러나 그 땅에 사는 사람들은 강하고 성읍은 튼튼하고 매우 크며, 거기서 아낙 자손도 보았다고 했어요.","t3":"그들은 바란 광야 가데스로 돌아와 모세와 아론, 그리고 이스라엘 자손의 온 회중에게 보고하고 그 땅의 열매를 보였다. 모세에게는, 보낸 땅에 가 보니 과연 젖과 꿀이 흐르며 이것이 그 땅의 열매라고 말했다. 그러나 그 땅에 사는 사람들은 강하고 성읍은 튼튼하고 매우 크며 거기서 아낙 자손을 보았다고 했다. 아말렉 사람은 남방 땅에, 헷 사람과 여부스 사람과 아모리 사람은 산지에, 가나안 사람은 해변과 요단 가에 산다고 했다."},"say":{"who":"hyu","text":"돌아온 곳은 바란 광야 가데스야. 먼저 열매 이야기, 그다음에 그 땅 사람들 이야기. 순서대로 적을게."}},{"ref":"민 13:30-33","focus":"caleb","text":{"t1":"갈렙은 올라가서 그 땅을 차지하자고, 이길 수 있다고 했어요. 하지만 함께 갔던 사람들은 그 백성이 더 강해서 칠 수 없다며, 자기들은 메뚜기 같았다고 했어요.","t2":"갈렙은 모세 앞에서 백성을 조용하게 하고, 곧 올라가서 그 땅을 차지하자고, 능히 이길 수 있다고 말했어요. 그러나 함께 올라갔던 사람들은 그 백성이 자기들보다 강해서 치지 못한다고 했어요. 그들은 이스라엘 자손 앞에서 그 땅을 나쁘게 말하며, 거기서 본 사람들은 키가 크고 자기들은 메뚜기 같았다고 했어요.","t3":"갈렙은 모세 앞에서 백성을 진정시키고, 곧 올라가 그 땅을 차지하자고, 능히 이길 것이라고 말했다. 그러나 함께 올라갔던 사람들은 그 백성이 자기들보다 강하므로 올라가서 칠 수 없다고 했다. 그들은 이스라엘 자손 앞에서 자기들이 살펴본 땅을 악평했다. 그 땅은 거기 사는 사람을 삼키는 땅이고, 거기서 본 백성은 모두 키가 큰 사람들이며, 네피림의 후손인 아낙 자손도 보았다고 했다. 자기들이 보기에도 스스로 메뚜기 같았고 그들이 보기에도 그랬을 것이라고 했다."},"say":{"who":"choeon","text":"갈렙은 올라가자고 하는데, 같이 다녀온 다른 사람들은 못 한다고 해."}},{"ref":"민 14:1-4","focus":"people","text":{"t1":"온 회중이 소리 높여 울었어요. 백성은 모세와 아론에게 원망을 쏟으며, 애굽으로 돌아가자고 서로 말했어요.","t2":"온 회중이 소리를 높여 부르짖었고, 백성은 밤새도록 울었어요. 이스라엘 자손은 모세와 아론을 원망하며, 애굽 땅이나 이 광야에서 죽었더라면 좋았겠다고 했어요. 그리고 지도자 한 사람을 세워 애굽으로 돌아가자고 서로 말했어요.","t3":"온 회중이 소리 높여 부르짖고 백성은 밤새도록 통곡했다. 이스라엘 자손은 모두 모세와 아론을 원망했고, 애굽 땅에서든 이 광야에서든 죽는 편이 좋았겠다고 했다. 어찌하여 여호와가 자기들을 그 땅으로 데려가 칼에 쓰러지게 하느냐며, 아내와 자식들이 사로잡힐 것이니 애굽으로 돌아가는 편이 낫지 않겠느냐고 했다. 그리고 우두머리 한 사람을 세워 애굽으로 돌아가자고 서로 말했다."},"say":{"who":"hyu","text":"밤새도록 우는 소리가 났어. 그다음에 애굽으로 돌아가자는 말이 나왔어. 순서대로 적어 둘게."}},{"ref":"민 14:5-10","focus":"joshua_caleb","text":{"t1":"모세와 아론은 온 회중 앞에 엎드렸고, 여호수아와 갈렙은 옷을 찢으며 여호와를 거역하지 말고 두려워하지 말라고 했어요. 그때 회막에서 여호와의 영광이 나타났어요.","t2":"그 땅을 살피고 온 사람 가운데 여호수아와 갈렙은, 그 땅은 매우 아름다운 땅이며 여호와께서 기뻐하시면 그 땅을 주실 것이라고 말했어요. 여호와를 거역하지 말고 그 땅 백성을 두려워하지 말라고도 했어요. 모세와 아론, 여호수아와 갈렙이 저마다 한 일과 그때 회막에서 일어난 일은 5절부터 10절까지 차례대로 읽어 봐요.","t3":"모세와 아론은 온 회중 앞에 엎드렸다. 그 땅을 살피고 온 사람들 가운데 눈의 아들인 여호수아와 여분네의 아들인 갈렙은 옷을 찢고 온 회중에게 말했다. 자기들이 두루 다니며 살펴본 땅은 매우 아름다운 땅이고, 여호와께서 자기들을 기뻐하시면 그 땅으로 인도해 들이시고 그 땅을 주실 것이라고 했다. 다만 여호와를 거역하지 말고 그 땅 백성을 두려워하지 말라고 했는데, 두려워하지 말라고 한 까닭은 9절에서 직접 읽어 보자. 온 회중이 두 사람을 돌로 치려 할 때, 회막에서 여호와의 영광이 이스라엘 자손 모두에게 나타났다."},"say":{"who":"choeon","text":"여호수아와 갈렙이 옷을 찢었어. 저기 회막 쪽 좀 봐!"}},{"ref":"민 14:11-25","open":"민 14:20-24","focus":"tabernacle","text":{"t1":"모세는 백성의 죄를 사해 주시기를 구했고, 하나님은 모세의 말대로 사하셨어요. 그러나 하나님의 목소리를 듣지 않은 사람들은 조상들에게 맹세하신 땅을 보지 못할 거라고 하셨어요.","t2":"여호와께서는 모세에게, 이 백성이 이적을 보고도 언제까지 여호와를 멸시하고 믿지 않겠느냐고 하셨어요. 모세는 여호와께서 노하기를 더디 하시고 인자가 많으시다고 하신 말씀을 아뢰며, 백성의 죄악을 사해 주시기를 구했어요. 여호와께서는 모세의 말대로 사하셨어요. 그러나 영광과 이적을 보고도 여호와의 목소리를 듣지 않은 사람들은 조상들에게 맹세하신 땅을 보지 못할 것이고, 갈렙은 그 땅으로 인도해 들이겠다고 하셨어요.","t3":"여호와께서는 모세에게, 이 백성이 어느 때까지 여호와를 멸시하며, 그들 가운데 행하신 모든 이적을 보고도 어느 때까지 믿지 않겠느냐고 하셨다. 그리고 전염병으로 쳐서 그들을 멸하고, 모세를 그들보다 크고 강한 나라가 되게 하겠다고 하셨다. 모세는, 그리하시면 애굽 사람들이 듣고 이 땅에 사는 사람들에게 전할 것이며, 여러 나라가 여호와께서 맹세한 땅으로 이 백성을 인도할 능력이 없어서 광야에서 죽였다고 말할 것이라고 아뢰었다. 또 여호와는 쉽게 노하지 않으시고 인자가 크셔서 죄악과 허물을 사하시나 벌 받을 자를 그냥 두지는 않으신다고 하신 말씀을 들어, 주의 크신 인자를 따라 이 백성의 죄악을 사해 주시기를 구했다. 여호와께서는 모세의 말대로 사한다고 하셨다. 그러나 여호와의 영광과 애굽과 광야에서 행하신 이적을 보고도 열 번이나 여호와를 시험하고 그 목소리를 듣지 않은 사람들은 조상들에게 맹세하신 땅을 결코 보지 못할 것이라고 하셨다. 오직 갈렙은 마음이 그들과 달라 여호와를 온전히 따랐으므로 그가 갔던 땅으로 인도해 들이고 그 자손이 그 땅을 차지할 것이라고 하셨다. 그리고 내일 돌이켜 홍해 길을 따라 광야로 들어가라고 하셨다."},"say":{"who":"onwoo","text":"하나님이 모세에게 대답하신 말씀은 민수기 14장 20절부터야. 성경책에서 직접 읽어 보자."}},{"ref":"민 14:26-38","open":"민 14:28-31","focus":"wilderness","text":{"t1":"하나님은 원망한 스무 살 이상의 사람들은 그 땅에 들어가지 못하고, 그 자녀들을 그 땅으로 데리고 들어가겠다고 하셨어요. 땅을 살피러 갔던 사람들 가운데 여호수아와 갈렙은 그 땅에 들어간다고 하셨어요.","t2":"여호와께서는 모세와 아론에게, 백성이 원망하는 말을 들었다고 하셨어요. 스무 살 이상으로 계수된 사람, 곧 원망한 사람은 갈렙과 여호수아 말고는 그 땅에 들어가지 못하고 광야에서 죽을 것이라고 하셨어요. 그들의 자녀들은 사십 년 동안 광야에서 떠돌게 되지만, 사로잡힐 것이라고 하던 그 어린아이들을 그 땅으로 인도해 들이겠다고 하셨어요. 그 땅을 나쁘게 말한 사람들은 재앙으로 여호와 앞에서 죽었고, 여호수아와 갈렙은 살아남았어요.","t3":"여호와께서는 모세와 아론에게, 여호와를 원망하는 이 악한 회중을 어느 때까지 참겠느냐고 하시며 그들의 원망하는 말을 들었다고 하셨다. 그리고 그들의 말이 여호와의 귀에 들린 대로 그들에게 행하겠다고 맹세하셨다. 이십 세 이상으로 계수된 사람, 곧 여호와를 원망한 사람은 모두 광야에서 쓰러지고, 갈렙과 여호수아 두 사람 말고는 살게 하겠다고 맹세하신 땅에 들어가지 못할 것이라고 하셨다. 사로잡힐 것이라고 하던 그들의 어린아이들은 여호와께서 인도해 들이셔서, 그들이 싫어하던 땅을 보게 될 것이라고 하셨다. 자녀들은 그들이 광야에서 다 죽기까지 광야에서 떠돌며 그들의 패역한 죄를 지게 될 것이라고 하셨다. 그 햇수를 무엇에 따라 정하셨는지는 34절에 있다. 모세가 보내어 땅을 살피고 돌아와 그 땅을 악평하여 온 회중이 모세를 원망하게 한 사람들은 재앙으로 여호와 앞에서 죽었고, 탐지하러 갔던 사람들 가운데 여호수아와 갈렙만 살아남았다."},"say":{"who":"hyu","text":"여호수아와 갈렙의 이름을 적어 둘게."}}],"gates":{"t1":[{"type":"find","ref":"민 13:23","prompt":"성경책에서 민수기 13장 23절을 찾아 읽어 보세요.","confirm":{"prompt":"에스골 골짜기에서 두 사람이 막대기에 꿰어 멘 것은 무엇인가요?","options":[{"label":"포도 한 송이가 달린 가지","ok":true},{"label":"커다란 수박","basis":"민 11:5"},{"label":"생선 한 꾸러미","basis":"민 11:5"}]}},{"type":"multi","ref":"민 13:26","prompt":"성경책에서 민수기 13장 26절을 찾아 읽어 보세요.","confirm":{"prompt":"땅을 살피고 온 사람들은 누구에게 그 땅의 열매를 보여 주었나요? 모두 고르세요.","options":[{"label":"모세","ok":true},{"label":"남방 땅의 아말렉 사람","basis":"민 13:29"},{"label":"아론","ok":true},{"label":"온 회중","ok":true},{"label":"헤브론의 아낙 자손","basis":"민 13:22"}]},"inStory":"모세·아론·회중은 이야기 곳곳에 나오지만, 땅을 살피고 온 사람들이 열매를 누구에게 보였는지는 8~10세 이야기 글에서 가렸고 13:26에서만 안다"}],"t2":[{"type":"find","ref":"민 13:23-24","prompt":"성경책에서 민수기 13장 23절과 24절을 읽어 보세요.","confirm":{"prompt":"그 골짜기를 에스골 골짜기라고 부르게 된 까닭은 무엇인가요?","options":[{"label":"그곳에서 포도송이를 잘랐기 때문에","ok":true},{"label":"그 땅에 살던 아모리 사람 에스골의 이름을 따서","basis":"창 14:13"},{"label":"그곳에서 석류와 무화과를 땄기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"민 14:1-10","prompt":"성경책에서 민수기 14장 1절부터 10절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["온 회중이 소리 높여 울었다","백성이 지도자를 세워 애굽으로 가자고 서로 말했다","모세와 아론이 온 회중 앞에 엎드렸다","여호수아와 갈렙이 옷을 찢었다","회막에서 여호와의 영광이 나타났다"]}],"t3":[{"type":"find","refs":["민 13:25","민 14:34"],"prompt":"민수기 13장 25절과 14장 34절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 사십이라는 수는 어떻게 이어지는가?","options":[{"label":"그들은 사십 일 동안 땅을 살피고 돌아왔고, 여호와께서는 그 사십 일의 하루를 한 해로 쳐서 사십 년 동안 그들이 죄악을 지게 하겠다고 하셨다","ok":true},{"label":"그들은 사십 년 동안 땅을 살피고 돌아왔고, 여호와께서는 그 한 해를 하루로 쳐서 사십 일 뒤에 그 땅에 들어가게 하겠다고 하셨다","basis":"본문에 없음"},{"label":"그들은 사십 일 동안 땅을 살피고 돌아왔고, 여호와께서는 그 사십 일을 사십 주로 쳐서 그동안 그들이 광야에 머물게 하겠다고 하셨다","basis":"본문에 없음"}]}},{"type":"match","refs":["출 3:8","민 13:27","민 13:32"],"prompt":"출애굽기 3장 8절, 민수기 13장 27절과 32절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"출 3:8","text":"하나님이 백성을 젖과 꿀이 흐르는 넓은 땅으로 데려가겠다고 하셨다"},{"ref":"민 13:27","text":"땅을 살피고 온 사람들이 그 땅에 과연 젖과 꿀이 흐른다며 그 땅의 열매를 보였다"},{"ref":"민 13:32","text":"갈렙과 함께 다녀온 사람들이 그 땅은 거기 사는 사람을 삼키는 땅이라고 나쁘게 말했다"}],"after":"세 곳을 이으면, 하나님은 떨기나무에서 젖과 꿀이 흐르는 땅으로 데려가겠다고 하셨고, 땅을 살피고 온 사람들도 과연 젖과 꿀이 흐른다고 했지만, 갈렙과 함께 다녀온 사람들은 백성 앞에서 그 땅을 사는 사람을 삼키는 땅이라고 나쁘게 말했다."}]},"cards":[{"ref":"민 14:9","title":"두려워하지 말라"},{"ref":"민 14:24","title":"여호와를 온전히 따른 갈렙"}],"close":{"t1":{"kind":"prayer","text":"하나님, 여호수아와 갈렙의 이야기를 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 민수기 14장 1절부터 10절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"민 13:1-14:38에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 타임머신이 바란 광야에 비상 착륙하면서 안테나가 부러졌어요. 안테나 대신 쓸 재료를 찾아봐요.","t2":"최현 박사예요. 비상 착륙 때 타임머신의 안테나가 부러져서 통신이 자꾸 끊겨요. 이 시대에는 우리 부속이 없으니, 다니는 곳에서 안테나 대신 쓸 재료를 찾아야 해요.","t3":"최현 박사다. 바란 광야에 비상 착륙하면서 안테나가 부러져 통신이 약해졌다. 이 시대에는 부속이 없으니 다니는 곳에서 구할 수 있는 재료로 안테나를 대신 만들어야 한다. 사람들이 하는 일에는 끼어들지 말고, 길을 비켜 주는 것처럼 곁에서 할 수 있는 일만 하자."},"materials":[{"key":"stick","name":"마른 막대기","basis":"민 13:23","use":"마른 막대기를 세워 묶으면 부러진 안테나 대신 쓸 수 있어요.","how":"에스골 골짜기 가장자리, 정탐꾼들이 다녀간 곳에서 멀리 떨어진 땅에 떨어져 있는 마른 막대기 하나를 줍는다. 정탐꾼들이 멘 막대기와 그 짐에는 손대지 않는다.","line":"에스골 골짜기 가장자리 땅에서 마른 막대기를 주웠어!"}],"companion":{"who":"갈렙","ref":"민 13:30","when":"after","talks":[{"ask":{"who":"hyu","text":"그 땅 사람들이 강하고 성읍이 크다는 보고가 나온 뒤에 무엇이라고 했어요?"},"answer":{"t1":"갈렙은 곧 올라가서 그 땅을 차지하자고 했어요. 넉넉히 이길 수 있다고 말했어요.","t2":"갈렙은 모세 앞에서 백성을 진정시키며, 곧 올라가서 그 땅을 차지하자고 말했어요. 자기들이 넉넉히 이길 수 있다고 했어요.","t3":"갈렙은 모세 앞에서 백성을 진정시키고, 곧 올라가 그 땅을 차지하자고 말했다. 자기들이 넉넉히 이길 수 있다는 것이었다."},"ref":"민 13:30","open":"민 13:30"},{"ask":{"who":"choeon","text":"직접 다녀온 그 땅은 어떤 땅이었어요?"},"answer":{"t1":"갈렙은 여호수아와 함께, 두루 다니며 살펴본 그 땅이 매우 좋은 땅이라고 말했어요. 젖과 꿀이 흐르는 땅이라고 했어요.","t2":"갈렙은 여호수아와 함께 온 회중에게, 자기들이 두루 다니며 살펴본 땅은 매우 좋은 땅이라고 말했어요. 여호와께서 자기들을 기뻐하시면 그 땅으로 인도해 들이시고 그 땅을 주실 것이며, 그 땅은 정말 젖과 꿀이 흐르는 땅이라고 했어요.","t3":"갈렙은 여호수아와 함께 이스라엘 자손의 온 회중에게, 자기들이 두루 다니며 살펴본 땅은 매우 좋은 땅이라고 말했다. 여호와께서 자기들을 기뻐하시면 그 땅으로 인도해 들이시고 그것을 주실 것이며, 그 땅은 과연 젖과 꿀이 흐르는 땅이라고 했다."},"ref":"민 14:7-8","open":"민 14:7"}]},"today":[{"q":"같은 땅을 보고 왔는데, 왜 갈렙과 여호수아는 다른 사람들과 말이 달랐어요?","a":{"t1":"여호수아와 갈렙은 여호와께서 자기들과 함께하신다고 말했어요. 하나님은 갈렙이 하나님의 목소리를 듣지 않은 사람들과 마음이 달라서 여호와를 온전히 따랐다고 하셨어요.","t2":"함께 갔던 다른 사람들은 그 땅 백성이 자기들보다 강하다고 했어요. 여호수아와 갈렙은 여호와를 거역하지 말고 그 땅 백성을 두려워하지 말라고 하며, 여호와께서 자기들과 함께하신다고 말했어요. 하나님은 갈렙이 하나님의 목소리를 듣지 않은 사람들과 마음이 달라서 여호와를 온전히 따랐다고 하셨고, 민수기 32장 12절은 여호수아도 갈렙과 함께 여호와를 온전히 따랐다고 적어요. 다른 사람들의 속마음은 성경이 더 말하지 않아요.","t3":"함께 갔던 다른 사람들은 그 백성이 자기들보다 강하다고 했다(민 13:31). 여호수아와 갈렙은 여호와를 거역하지 말고 그 땅 백성을 두려워하지 말라고 하며, 여호와께서 자기들과 함께하신다고 말했다(민 14:9). 여호와께서는 갈렙이 그 마음이 하나님의 목소리를 듣지 않은 그들과 달라 여호와를 온전히 따랐다고 하셨고(민 14:22-24), 뒤에 모세는 갈렙과 여호수아가 여호와를 온전히 따랐으므로 그 땅을 볼 것이라고 하신 여호와의 말씀을 전했다(민 32:11-12). 다른 사람들의 속마음은 성경이 더 말하지 않는다."},"refs":["민 13:31","민 14:9","민 14:22-24","민 32:11-12"]},{"q":"여호수아와 갈렙은 나중에 정말 그 땅에 들어갔어요?","a":{"t1":"네, 들어갔어요. 그 땅에서 여호수아는 갈렙을 축복하고, 정탐꾼들이 다녀왔던 헤브론을 갈렙에게 기업으로 주었어요.","t2":"민수기 26장 65절은, 모압 평지에서 이스라엘 자손을 다시 셀 때 시내 광야에서 센 사람 가운데 갈렙과 여호수아 말고는 한 사람도 남지 않았다고 적어요. 여호수아 14장 13~14절에서 여호수아는 갈렙을 축복하고 헤브론을 그의 기업으로 주었어요. 헤브론은 정탐꾼들이 아낙 자손을 보았던 곳이에요.","t3":"모압 평지에서 이스라엘 자손을 다시 계수했을 때, 모세와 아론이 시내 광야에서 계수한 사람은 갈렙과 여호수아 두 사람 말고는 하나도 남지 않았다(민 26:63-65). 그 뒤 여호수아는 갈렙을 축복하고 헤브론을 그의 기업으로 주었는데, 본문은 그 까닭을 갈렙이 여호와를 온전히 따랐기 때문이라고 적는다(수 14:13-14). 헤브론은 정탐꾼들이 아낙 자손을 보았던 곳이다(민 13:22)."},"refs":["민 26:63-65","수 14:13-14","민 13:22"]}],"help":{"who":"바란 광야 가데스의 이스라엘 자손","steps":[{"kind":"do","after":1,"title":"돌아오는 사람들에게 길 비켜 주기","basis":"민 13:26","text":{"t1":"땅을 살피러 갔던 사람들이 가데스로 돌아와요. 우리는 회중 곁에서 길을 비켜 주며 도와요.","t2":"땅을 살피러 갔던 사람들이 사십 일 만에 바란 광야 가데스로 돌아와요. 우리는 회중 곁에서, 그들이 모세와 아론과 회중에게 갈 수 있도록 길을 비켜 주며 도와요. 본문에 적힌 일이 아니라 탐험대 이야기예요.","t3":"땅을 살피러 갔던 사람들이 돌아와 바란 광야 가데스에 있는 모세와 아론과 온 회중에게 나아온다. 탐험대는 회중 곁에서 그들이 지나갈 길을 비켜 주며 돕는다. 본문에 적힌 일이 아니라 탐험대 이야기다. 그들이 가져온 열매에는 손대지 않는다."},"tasks":["돌아오는 사람들이 오는 쪽 살피기","길가로 비켜서기","회중 뒤쪽으로 물러나 자리 잡기"],"done":{"who":"choeon","text":"길을 비켜 드렸어. 저 사람들이 그 땅에서 열매를 가져왔어."}},{"kind":"watch","after":2,"title":"곁에서 보기 · 그 땅의 열매","basis":"민 13:26","text":{"t1":"땅을 살피고 온 사람들이 그 땅의 열매를 보여 주었어요. 우리는 손대지 않고 곁에서 봐요.","t2":"땅을 살피러 갔던 사람들이 가데스로 돌아와, 모세와 아론과 온 회중에게 그 땅의 열매를 보여 주었어요. 우리는 그 열매에 손대지 않고 곁에서 지켜봐요.","t3":"땅을 살피러 갔던 사람들이 가데스로 돌아와, 모세와 아론과 온 회중 앞에서 보고하며 그 땅의 열매를 보였다(13:26). 탐험대는 그 열매에 손대지 않고 곁에서 본다."},"say":{"who":"hyu","text":"그 땅에서 가져온 열매래. 우리는 손대지 않아."}},{"kind":"watch","after":5,"title":"곁에서 보기 · 옷을 찢은 두 사람","basis":"민 14:5-6","text":{"t1":"모세와 아론이 온 회중 앞에 엎드렸어요. 땅을 살피고 온 두 사람이 옷을 찢었어요. 우리는 회중 사이에 끼지 않고 멀리서 지켜봐요.","t2":"회중은 땅을 살피고 온 두 사람을 돌로 치려고 했어요. 우리는 회중 사이에 끼지 않고 멀리서 지켜봐요.","t3":"모세와 아론은 온 회중 앞에 엎드렸고, 땅을 살핀 사람들 가운데 여호수아와 갈렙은 옷을 찢었다(14:5-6). 온 회중이 두 사람을 돌로 치려 할 때 회막에서 여호와의 영광이 나타났다(14:10). 탐험대는 회중 사이에 끼지 않고 멀리서 본다."},"say":{"who":"onwoo","text":"우리는 여기서 지켜보자. 회중 사이로는 들어가지 않아."}},{"kind":"ask","after":"gates","title":"두 사람이 회중에게 한 말은 무슨 뜻이에요?","basis":"민 14:9","by":"여호수아와 갈렙","ask":{"who":"choeon","text":"여호수아와 갈렙이 옷을 찢고 회중에게 한 말은 무슨 뜻이에요?"},"answer":{"t1":"여호수아와 갈렙은 여호와께 거역하지 말라고 했어요. 그 땅에 사는 사람들을 겁내지 말라고 했어요.","t2":"여호수아와 갈렙은 옷을 찢고 온 회중에게 말했어요. 오직 여호와께 거역하지 말고, 그 땅에 사는 사람들을 겁내지 말라고 했어요.","t3":"여호수아와 갈렙은 옷을 찢고 온 회중을 향해, 오직 여호와께 거역하지 말고 그 땅에 사는 사람들을 겁내지 말라고 했다. 그들은 자기들의 밥이며, 그들을 지켜 주던 것은 떠났고 여호와께서 자기들과 함께하시니 두려워하지 말라는 것이었다(14:9)."},"read":{"t1":{"type":"find","ref":"민 14:9","prompt":"성경책에서 민수기 14장 9절을 찾아 읽어 보세요.","confirm":{"prompt":"여호수아와 갈렙은 누가 자기들과 함께하신다고 했나요?","options":[{"label":"여호와","ok":true},{"label":"모세와 아론","basis":"본문에 없음"},{"label":"함께 다녀온 다른 정탐꾼들","basis":"민 13:31"}]},"inStory":"여호와라는 이름은 이야기 곳곳에 나오지만, 여호수아와 갈렙이 누가 자기들과 함께하신다고 했는지는 8~10세 이야기 글에 없고 14:9에서만 안다"},"t2":{"type":"find","ref":"민 14:6-9","prompt":"성경책에서 민수기 14장 6절부터 9절까지 읽어 보세요.","confirm":{"prompt":"여호수아와 갈렙이 그 땅에 사는 사람들을 겁내지 말라고 한 까닭은 무엇인가요?","options":[{"label":"그 땅 백성의 보호자는 떠났고, 여호와께서 자기들과 함께하시기 때문에","ok":true},{"label":"가나안 사람들이 서로 싸우느라 이스라엘을 막을 힘이 없기 때문에","basis":"본문에 없음"},{"label":"이스라엘 자손에게 그 땅 백성보다 더 많은 군사가 있기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["민 13:2","민 14:9"],"prompt":"민수기 13장 2절과 14장 9절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 그 땅을 두고 하나님이 하신 말씀과 여호수아와 갈렙이 한 말은 무엇인가?","options":[{"label":"하나님은 가나안 땅을 이스라엘에게 주시는 땅이라고 하셨고, 여호수아와 갈렙은 여호와께서 함께하시니 그 땅에 사는 사람들을 겁내지 말라고 했다","ok":true},{"label":"하나님은 가나안 땅을 이스라엘에게 주시는 땅이라고 하셨고, 여호수아와 갈렙은 자기들이 그 땅 사람들보다 키가 크니 겁내지 말라고 했다","basis":"본문에 없음"},{"label":"하나님은 가나안 땅을 이스라엘에게 주시는 땅이라고 하셨고, 여호수아와 갈렙은 그 땅의 성읍들이 작고 약하니 겁내지 말라고 했다","basis":"본문에 없음"}]}}},"nt":{"ref":"히 3:17-19","text":"신약의 히브리서 3장 17~19절은 하나님이 노하신 사람들이 죄를 지어 광야에서 쓰러진 이들이었다고 하고, 그들이 믿지 않았기 때문에 그 안식에 들어가지 못했다고 말한다."}}]}},"has3d":false,"epic":false},"OT-16":{"id":"OT-16","era":4,"title":"느보 산에서 모세의 마지막","ref":"신 34:1-12","place":"모압 평지, 느보 산 비스가 산 꼭대기","review":{"required":true,"topics":["구약 사건의 신약적 의미(히 3:5)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"신 34:1","focus":"mountain","text":{"t1":"모세는 모압 평지를 떠나 느보 산에 올라 비스가 산 꼭대기까지 갔어요. 그 꼭대기가 어느 곳의 맞은편이었는지는 1절에서 찾아봐요.","t2":"모세는 모압 평지를 떠나 느보 산으로 올라갔어요. 여리고 맞은편에 있는 비스가 산의 꼭대기에 다다랐어요.","t3":"모세는 모압 평지를 떠나 느보 산으로 올라갔고, 여리고 건너편에 있는 비스가 산의 꼭대기에 다다랐다."},"say":{"who":"hyu","text":"떠나온 곳은 모압 평지, 올라온 곳은 느보 산이야. 비스가 산 꼭대기라고 적어 둘게."}},{"ref":"신 34:1-3","focus":"land","text":{"t1":"여호와께서는 그곳에서 모세에게 땅을 보여 주셨어요. 길르앗 땅에서 단까지, 유다 땅과 남방까지 보여 주셨어요.","t2":"여호와께서는 모세에게 그 땅을 두루 보여 주셨어요. 어느 땅을 어떤 차례로 보여 주셨는지는 1절부터 3절까지 읽어 봐요.","t3":"여호와께서는 그에게 단에 이르기까지 길르앗 온 땅을 보이시고, 납달리 온 땅, 에브라임과 므낫세의 땅, 서해까지 이르는 유다 온 땅, 남방, 그리고 종려의 성읍 여리고의 골짜기 평지를 소알까지 보이셨다."},"say":{"who":"choeon","text":"모세가 산꼭대기에서 그 땅을 보고 있어."}},{"ref":"신 34:4","open":"신 34:4","focus":"moses","text":{"t1":"하나님은 이 땅이 아브라함, 이삭, 야곱에게 맹세하신 땅이라고 하셨어요. 모세가 눈으로 보게 해 주셨지만, 그 땅으로 건너가지는 못한다고 하셨어요.","t2":"여호와께서는 이 땅이 아브라함, 이삭, 야곱에게 그 후손의 것으로 주겠다고 맹세하신 땅이라고 하셨어요. 모세가 눈으로 그 땅을 보게 하셨지만, 모세는 그리로 건너가지 못한다고 하셨어요.","t3":"여호와께서는 그에게, 이것이 아브라함, 이삭, 야곱에게 그 후손의 것으로 주겠다고 맹세하신 땅이라고 하셨다. 모세의 눈으로 보게는 하셨으나 그가 그리로 건너가지는 못할 것이라고 하셨다."},"say":{"who":"onwoo","text":"하나님이 모세에게 하신 말씀은 신명기 34장 4절이야. 성경책에서 직접 읽어 보자."}},{"ref":"신 34:5-7","focus":"valley","text":{"t1":"하나님은 말씀하신 대로 모압 땅에서 여호와의 종 모세를 부르셨어요. 모세는 그곳 골짜기에 모셔졌지만, 그 자리가 어디인지는 오늘까지 아무도 몰라요.","t2":"여호와의 종 모세는 모압 땅에서, 여호와께서 말씀하신 대로 죽었어요. 벧브올 맞은편 모압 땅의 골짜기에 장사되었고, 성경은 그의 무덤을 아는 사람이 없다고 말해요. 죽을 때 모세는 백이십 세였지만 눈이 흐리지 않았고 기력도 약해지지 않았어요.","t3":"여호와의 종 모세는 모압 땅에서, 여호와께서 말씀하신 대로 죽었다. 그가 어디에 장사되었고 그 묘가 어떻게 되었는지는 6절에 있다. 죽을 때 모세의 나이는 백이십 세였으나 눈이 흐리지 않았고 기력이 줄지 않았다."},"say":{"who":"hyu","text":"하나님이 모세를 부르셨어. 일지에 적어 둘게."}},{"ref":"신 34:8-9","focus":"joshua","text":{"t1":"이스라엘 자손은 모압 평지에서 삼십 일 동안 모세를 위해 울었어요. 모세가 안수한 여호수아에게 지혜의 영이 가득했고, 백성은 여호수아의 말을 따랐어요.","t2":"이스라엘 자손은 모압 평지에서 삼십 일 동안 모세를 위해 애곡했어요. 눈의 아들 여호수아에게는 지혜의 영이 충만했는데, 왜 그랬는지는 9절에서 찾아봐요. 이스라엘 자손은 여호수아의 말에 순종하여, 여호와께서 모세에게 명령하신 그대로 했어요.","t3":"이스라엘 자손은 모압 평지에서 모세를 위해 삼십 일 동안 애곡했고, 그렇게 애곡하는 기간이 끝났다. 눈의 아들 여호수아에게는 지혜의 영이 충만했는데, 모세가 그에게 안수했기 때문이다. 이스라엘 자손은 여호수아의 말에 순종하여 여호와께서 모세에게 명령하신 그대로 행했다."},"say":{"who":"choeon","text":"사람들이 모세를 위해 울고 있어. 삼십 일 동안이래."}},{"ref":"신 34:10-12","focus":"moses","text":{"t1":"그 뒤로 이스라엘에는 모세 같은 선지자가 다시 일어나지 않았어요.","t2":"그 뒤로 이스라엘에는 모세와 같은 선지자가 다시 일어나지 않았어요. 여호와께서는 모세를 얼굴을 마주하여 아셨어요. 여호와께서는 모세를 애굽 땅으로 보내어, 바로와 그 신하들과 온 땅에 이적과 기사를 행하게 하셨어요.","t3":"그 뒤로 이스라엘에는 모세와 같은 선지자가 다시 일어나지 못했다. 여호와께서는 모세를 애굽 땅으로 보내어 바로와 그의 신하 모두와 그 온 땅에 온갖 이적과 기사를 행하게 하셨고, 모세는 온 이스라엘이 보는 앞에서 큰 권능과 위엄을 행했다."},"say":{"who":"onwoo","text":"모세가 어떤 선지자였는지는 신명기 34장 10절부터 12절에 적혀 있어. 성경책에서 확인해 보자."}}],"gates":{"t1":[{"type":"find","ref":"신 34:1","prompt":"성경책에서 신명기 34장 1절을 찾아 읽어 보세요.","confirm":{"prompt":"모세가 오른 비스가 산 꼭대기는 어느 곳의 맞은편에 있었나요?","options":[{"label":"여리고","ok":true},{"label":"헤브론","basis":"본문에 없음"},{"label":"라암셋","basis":"본문에 없음"}]}},{"type":"multi","ref":"신 34:7","prompt":"성경책에서 신명기 34장 7절을 찾아 읽어 보세요.","confirm":{"prompt":"하나님이 모세를 부르셨을 때 모세는 어떠했나요? 모두 고르세요.","options":[{"label":"백이십 세였다","ok":true},{"label":"눈이 흐리지 않았다","ok":true},{"label":"백십 세였다","basis":"창 50:26"},{"label":"기력이 약해지지 않았다","ok":true},{"label":"지팡이 없이는 걷지 못했다","basis":"본문에 없음"}]}}],"t2":[{"type":"find","ref":"신 34:8-9","prompt":"성경책에서 신명기 34장 8절과 9절을 읽어 보세요.","confirm":{"prompt":"여호수아에게 지혜의 영이 가득했던 까닭은 무엇인가요?","options":[{"label":"모세가 그에게 안수했기 때문에","ok":true},{"label":"그가 가나안 땅을 살피고 돌아왔기 때문에","basis":"본문에 없음"},{"label":"이스라엘 자손이 그를 지도자로 뽑았기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"신 34:1-3","prompt":"성경책에서 신명기 34장 1절부터 3절까지 읽고, 여호와께서 모세에게 보이신 땅을 본문에 적힌 차례대로 눌러 보세요.","items":["단까지 이르는 길르앗 온 땅","납달리 온 땅과 에브라임, 므낫세의 땅","서해까지 이르는 유다 온 땅","남방과 여리고 골짜기 평지에서 소알까지"]}],"t3":[{"type":"find","refs":["신 34:1","신 34:5","신 34:6"],"prompt":"신명기 34장 1절, 5절, 6절을 함께 찾아 읽어 보자.","confirm":{"prompt":"세 곳을 이어 읽으면, 모세의 마지막 자리는 어떠한가?","options":[{"label":"모압 평지를 떠나 느보 산 비스가 꼭대기에 올랐고, 모압 땅에서 죽어 벧브올 건너편의 모압 골짜기에 묻혔으며, 그 무덤이 어디인지 지금껏 아는 사람이 없다","ok":true},{"label":"모압 평지를 떠나 느보 산 비스가 꼭대기에 올랐고, 모압 땅에서 죽어 그 산꼭대기에 묻혔으며, 그 무덤은 지금도 누구나 찾아갈 수 있다","basis":"본문에 없음"},{"label":"모압 평지를 떠나 느보 산 비스가 꼭대기에 올랐고, 모압 땅에서 죽어 벧브올 건너편의 모압 골짜기에 묻혔으며, 여호수아가 그 무덤에 돌기둥을 세웠다","basis":"본문에 없음"}]}},{"type":"match","refs":["창 50:24","출 3:8","신 34:4"],"prompt":"창세기 50장 24절, 출애굽기 3장 8절, 신명기 34장 4절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"창 50:24","text":"요셉이 죽기 전에, 하나님이 형제들을 이끌어 내어 세 조상에게 맹세하신 그 땅으로 데려가시리라고 했다"},{"ref":"출 3:8","text":"하나님이 백성을 애굽 사람의 손에서 건져 젖과 꿀이 흐르는 땅으로 데려가겠다고 하셨다"},{"ref":"신 34:4","text":"하나님이 모세에게 그 땅을 눈으로 보게 하셨으나 건너가지는 못한다고 하셨다"}],"after":"세 곳을 이으면, 요셉은 하나님이 세 조상에게 맹세하신 땅으로 데려가시리라 했고, 하나님은 떨기나무에서 백성을 젖과 꿀이 흐르는 땅으로 데려가겠다고 하셨으며, 느보 산에서는 모세에게 그 땅을 보이시되 건너가지는 못한다고 하셨다."}]},"cards":[{"ref":"신 34:4","title":"맹세하신 땅을 보이심"},{"ref":"신 34:10","title":"모세와 같은 선지자"}],"close":{"t1":{"kind":"prayer","text":"하나님, 느보 산에서 있었던 모세의 이야기를 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 신명기 34장 1절부터 12절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"신 34:1-12에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 타임머신이 모압 평지 가까이에 비상 착륙하면서 받침 다리가 부러졌어요. 받침 대신 쓸 재료를 찾아봐요.","t2":"최현 박사예요. 비상 착륙 때 타임머신의 받침 다리가 부러져 몸체가 기울었어요. 이 시대에는 우리 부속이 없으니, 이곳에서 받침 대신 쓸 재료를 찾아야 해요.","t3":"최현 박사다. 모압 평지 가까이에 비상 착륙하면서 받침 다리가 부러져 타임머신이 기울었고 지금은 통신만 이어져 있다. 이 시대에는 부속이 없으니 이곳에서 구할 수 있는 재료로 받침을 대신 만들어야 한다."},"materials":[{"key":"flatstone","name":"넓적한 돌","basis":"신 34:1","use":"넓적한 돌을 괴면 부러진 받침 다리 대신 쓸 수 있어요.","how":"느보 산으로 오르는 길가, 산꼭대기에서 멀리 떨어진 곳에 굴러 있는 넓적한 돌 하나를 주워 온다. 모세가 오른 꼭대기에는 따라 올라가지 않는다.","line":"느보 산으로 오르는 길가에서 넓적한 돌을 찾았어!"}],"companion":null,"today":[{"q":"모세는 왜 그 땅에 들어가지 못했어요?","a":{"t1":"하나님은 모세와 아론이 하나님을 믿지 않고, 이스라엘 자손 앞에서 하나님의 거룩함을 나타내지 않았다고 하셨어요. 그래서 백성을 그 땅으로 데리고 들어가지 못한다고 하셨어요.","t2":"민수기 20장 12절에서 하나님은 모세와 아론에게, 그들이 하나님을 믿지 않고 이스라엘 자손이 보는 앞에서 하나님의 거룩함을 나타내지 않았으므로 이 회중을 하나님이 주신 땅으로 인도해 들이지 못할 것이라고 하셨어요. 신명기 32장 51~52절도, 신 광야 가데스의 므리바 물가에서 있었던 그 일 때문에 모세는 그 땅을 바라보기만 하고 들어가지는 못한다고 적어요.","t3":"하나님은 모세와 아론에게, 그들이 하나님을 믿지 않고 이스라엘 자손의 눈앞에서 하나님의 거룩함을 나타내지 않았으므로 이 회중을 하나님이 주신 땅으로 인도해 들이지 못할 것이라고 하셨다(민 20:12). 신명기도 그 까닭을, 신 광야 가데스의 므리바 물가에서 그들이 하나님께 범죄하여 이스라엘 자손 가운데서 하나님의 거룩함을 나타내지 않은 것이라고 적고, 모세는 그 땅을 바라보기는 하되 들어가지는 못한다고 한다(신 32:51-52). 성경은 여기까지 말한다."},"refs":["민 20:12","신 32:51-52"]},{"q":"하나님이 모세를 부르신 뒤에는 누가 백성을 이끌었어요?","a":{"t1":"모세가 안수한 눈의 아들 여호수아예요. 이스라엘 자손은 여호수아의 말을 따랐어요. 하나님은 모세를 부르신 뒤, 여호수아에게 백성과 함께 요단을 건너 그 땅으로 가라고 하셨어요.","t2":"모세가 안수한 눈의 아들 여호수아예요. 신명기 34장 9절은, 여호수아에게 지혜의 영이 충만했고 이스라엘 자손이 그의 말에 순종했다고 적어요. 여호수아 1장 1~2절에서, 모세가 죽은 뒤 여호와께서는 여호수아에게 이 모든 백성과 함께 일어나 요단을 건너 이스라엘 자손에게 주시는 땅으로 가라고 하셨어요.","t3":"모세가 안수한 눈의 아들 여호수아다. 여호수아에게는 지혜의 영이 충만했고, 이스라엘 자손은 여호와께서 모세에게 명하신 대로 그의 말에 순종했다(신 34:9). 여호와의 종 모세가 죽은 뒤 여호와께서는 모세의 시종인 여호수아에게, 이제 이 모든 백성과 함께 일어나 요단을 건너 이스라엘 자손에게 주시는 땅으로 가라고 하셨다(수 1:1-2)."},"refs":["신 34:9","수 1:1-2"]}],"help":{"who":"모압 평지의 이스라엘 자손","steps":[{"kind":"watch","after":0,"title":"곁에서 보기 · 산에 오르는 모세","basis":"신 34:1","text":{"t1":"모세가 느보 산 꼭대기로 올라가요. 우리는 따라가지 않고 산 아래에서 지켜봐요.","t2":"모세가 느보 산, 여리고가 마주 보이는 비스가 꼭대기로 올라가요. 그 땅을 보이시는 것은 여호와께서 모세에게 하시는 일이에요. 우리는 따라가지 않고 산 아래에서 지켜봐요.","t3":"모세가 느보 산으로 올라가 여리고 건너편 비스가 꼭대기에 이른다. 그곳에서 땅을 보이시는 것은 여호와께서 모세에게 하시는 일이다. 탐험대는 꼭대기로 따라 올라가지 않고 산 아래에서 지켜본다."},"say":{"who":"hyu","text":"우리는 여기 아래에 있자. 꼭대기로는 따라가지 않아."}},{"kind":"stay","after":3,"title":"떨어져서 조용히 기다리기","basis":"신 34:8","text":{"t1":"모압 평지에서 이스라엘 자손이 모세를 위해 울어요. 우리는 사람들 사이에 끼지 않고 떨어져서 조용히 기다려요.","t2":"모압 평지에서 이스라엘 자손이 모세를 위해 애곡해요. 애곡하는 날은 삼십 일 동안 이어져요. 우리는 사람들 사이에 끼지 않고 떨어진 곳에서 조용히 기다려요.","t3":"모압 평지에서 이스라엘 자손이 모세를 두고 애곡한다. 애곡하는 날은 삼십 일 동안 이어진다(34:8). 탐험대는 애곡하는 사람들 사이에 끼지 않고, 떨어진 곳에서 그 날들이 다 지나기를 조용히 기다린다."},"wait":"떨어져서 조용히 기다리기","say":{"who":"choeon","text":"우리는 여기서 조용히 기다리자."}},{"kind":"do","after":4,"title":"애곡을 마친 뒤 자리 정리 돕기","basis":"신 34:8","text":{"t1":"모세를 위해 울던 삼십 일이 끝났어요. 우리는 모압 평지의 한 집 식구들 곁에서 자리를 정리하는 일을 도와요.","t2":"모압 평지에서 이스라엘 자손이 모세를 위해 애곡하던 삼십 일이 끝났어요. 우리는 한 집 식구들 곁에서 짐을 모으고 자리를 정리하는 일을 도와요. 본문에 적힌 일이 아니라 탐험대 이야기예요.","t3":"모압 평지에서 모세를 위한 삼십 일의 애곡이 끝났다(34:8). 탐험대는 한 집 식구들 곁에서 짐을 모으고 자리를 정리하는 일을 거든다. 본문에 적힌 일이 아니라 탐험대 이야기다."},"tasks":["흩어진 짐 한곳에 모으기","앉았던 자리 정리하기","정리한 짐 식구들에게 건네기"],"done":{"who":"hyu","text":"정리를 다 했어. 이제 이스라엘 자손은 여호수아의 말을 따른대."}},{"kind":"ask","after":"gates","title":"모세 같은 선지자가 없었다는 것은 무슨 뜻이에요?","basis":"신 34:10-12","by":"최현 박사","ask":{"who":"onwoo","text":"모세만 한 선지자가 다시 없었다는 것은 무슨 뜻이에요?"},"answer":{"t1":"성경은 그 뒤로 모세만 한 선지자가 이스라엘에 다시 나오지 않았다고 말해요(신 34:10). 하나님은 모세를 애굽 땅에 보내어 이적과 기사를 행하게 하셨다고 해요(신 34:11).","t2":"신명기 34장 10~12절은, 그 뒤로 모세만 한 선지자가 이스라엘에 다시 나오지 않았다고 적어요. 여호와께서는 모세를 애굽 땅에 보내어 바로와 신하들과 애굽 온 땅에 갖가지 이적과 기사를 행하게 하셨고, 모세는 온 이스라엘이 보는 앞에서 큰 권능을 보였다고 해요. 성경은 이 장면에서 여기까지 말해요.","t3":"본문은 그 뒤로 모세만 한 선지자가 이스라엘에 다시 일어나지 않았다고 하고, 모세가 어떤 사람이었는지를 적는다. 여호와께서는 그를 애굽으로 보내시어 바로와 신하들과 애굽 온 땅에 갖가지 이적과 기사를 행하게 하셨고, 그는 온 이스라엘이 보는 앞에서 큰 권능과 위엄을 보였다(신 34:10-12). 성경은 이 장면에서 여기까지 말한다."},"read":{"t1":{"type":"find","ref":"신 34:10","prompt":"성경책에서 신명기 34장 10절을 찾아 읽어 보세요.","confirm":{"prompt":"여호와께서 모세를 어떻게 아셨나요?","options":[{"label":"얼굴을 마주하여","ok":true},{"label":"꿈으로만","basis":"본문에 없음"},{"label":"멀리서 이름만","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"민 12:6-8","prompt":"성경책에서 민수기 12장 6절부터 8절까지 읽어 보세요.","confirm":{"prompt":"여호와께서 모세와는 대면하여 분명히 말씀하신다고 하신 까닭은 무엇인가요?","options":[{"label":"모세는 여호와의 온 집에 충성된 사람이었기 때문에","ok":true},{"label":"모세가 이스라엘에서 나이가 가장 많았기 때문에","basis":"본문에 없음"},{"label":"모세가 말을 가장 잘하는 사람이었기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["출 33:11","신 34:10"],"prompt":"출애굽기 33장 11절과 신명기 34장 10절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 모세만 한 선지자가 다시 없었다는 말은 무엇과 이어지는가?","options":[{"label":"여호와께서는 친구끼리 이야기하듯 얼굴을 마주하고 모세에게 말씀하셨고, 여호와께서 얼굴을 마주하여 아신 모세 같은 선지자는 그 뒤로 다시 나오지 않았다","ok":true},{"label":"여호와께서는 다른 선지자들에게 하시듯 꿈과 환상 속에서만 모세에게 말씀하셨고, 그런 모세 같은 선지자는 그 뒤로 다시 나오지 않았다","basis":"민 12:6"},{"label":"여호와께서는 모세와 얼굴을 마주하지 않으시고 멀리 구름 속에서만 말씀하셨고, 그런 모세 같은 선지자는 그 뒤로 다시 나오지 않았다","basis":"본문에 없음"}]}}},"nt":{"ref":"히 3:5","text":"신약의 히브리서 3장 5절은 모세가 종으로서 하나님의 온 집에 충성했으며, 이는 뒤에 말해질 것들을 증거하기 위한 것이었다고 말한다."}}]}},"has3d":false,"epic":false},"OT-17":{"id":"OT-17","era":5,"title":"라합과 두 정탐꾼","ref":"수 2:1-24","place":"여리고, 라합의 집","review":{"required":false,"topics":[],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"수 2:1","focus":"spies","text":{"t1":"여호수아는 싯딤에서 두 사람을 몰래 보내 여리고를 살펴보게 했어요. 두 사람은 라합이라는 여인의 집에 묵었어요.","t2":"눈의 아들 여호수아는 싯딤에서 두 사람을 정탐꾼으로 몰래 보냈어요. 가서 그 땅과 여리고를 살펴보라고 했어요. 두 사람은 가서 라합이라는 여인의 집에 들어가 묵었어요.","t3":"눈의 아들 여호수아는 싯딤에서 정탐할 사람 둘을 은밀히 보내며, 가서 그 땅과 여리고를 살펴보라고 했다. 두 사람은 가서 라합이라는 기생의 집에 들어가 거기서 묵었다."},"say":{"who":"hyu","text":"여기는 여리고야. 저 두 사람은 싯딤에서 왔어. 일지에 적어 둘게."}},{"ref":"수 2:2-3","focus":"king","text":{"t1":"여리고 왕은 이스라엘 사람들이 들어왔다는 말을 듣고, 라합에게 그 사람들을 내놓으라고 했어요.","t2":"누군가 여리고 왕에게, 이스라엘 자손 몇 사람이 이 밤에 땅을 살피러 들어왔다고 알렸어요. 여리고 왕은 라합에게 사람을 보내어, 집에 들어온 사람들을 끌어내라고 했어요. 그들이 온 땅을 살피러 왔다는 것이었어요.","t3":"어떤 사람이 여리고 왕에게, 이 밤에 이스라엘 자손 가운데 몇 사람이 땅을 살피러 이리로 들어왔다고 알렸다. 여리고 왕은 라합에게 사람을 보내어, 그의 집에 들어간 사람들을 끌어내라고 했다. 그들이 이 온 땅을 살피러 왔다는 것이었다."},"say":{"who":"choeon","text":"여리고 왕이 라합에게 두 사람을 내놓으라고 했어."}},{"ref":"수 2:4-7","focus":"roof","text":{"t1":"라합은 두 사람을 미리 숨겨 두었어요. 쫓는 사람들은 요단으로 가는 길로 따라갔어요.","t2":"라합은 이미 두 사람을 지붕으로 데리고 올라가, 지붕에 널어놓은 삼대 속에 숨겨 두었어요. 라합은 그 사람들이 오기는 했지만 어디서 왔는지 몰랐고, 어두워져 성문을 닫을 때쯤 나갔으니 어디로 갔는지도 모른다고 했어요. 서둘러 따라가면 따라잡을 것이라고도 했어요. 쫓는 사람들은 요단으로 가는 길을 따라 나루턱까지 갔고, 그들이 나가자 성문이 닫혔어요.","t3":"그 여인은 두 사람을 이미 숨겨 두고 있었다. 그는 그 사람들이 자기에게 오기는 했으나 어디서 왔는지 알지 못했고, 날이 어두워 성문을 닫을 때쯤 나갔으니 어디로 갔는지도 알지 못한다고 했으며, 급히 따라가면 따라잡을 것이라고 말했다. 그러나 실제로는 그가 두 사람을 지붕으로 데리고 올라가, 지붕에 벌여 놓은 삼대 속에 숨겨 둔 것이었다. 쫓는 사람들이 성 밖으로 나가자마자 성문이 닫혔다. 그들이 어느 길로 어디까지 쫓아갔는지는 7절에 있다."},"say":{"who":"choeon","text":"쫓는 사람들이 성 밖으로 나갔어. 그러자 곧 성문이 닫혔어!"}},{"ref":"수 2:8-11","open":"수 2:11","focus":"rahab","text":{"t1":"라합은 두 사람에게 와서 여호와에 대해 말했어요. 여호와는 하늘과 땅의 하나님이시라고 했어요.","t2":"두 사람이 눕기 전에 라합이 지붕으로 올라와 말했어요. 여호와께서 이 땅을 이스라엘에게 주신 줄을 안다고 했어요. 그 땅 사람들의 마음이 녹았다고도 했는데, 왜 그랬는지는 10절과 11절에서 찾아봐요. 그리고 이스라엘의 하나님 여호와는 위로 하늘과 아래로 땅의 하나님이시라고 했어요.","t3":"두 사람이 아직 눕기 전에 라합이 지붕 위로 올라와 말했다. 그는 여호와께서 이 땅을 이스라엘에게 주신 줄을 안다고 했고, 자기들이 이스라엘을 몹시 두려워한다고 했다. 이스라엘이 애굽에서 나올 때 여호와께서 그들 앞에서 홍해 물을 마르게 하신 일과, 이스라엘이 요단 저편 아모리 사람의 두 왕 시혼과 옥을 모두 멸한 일을 들었기 때문이라고 했다. 그 소식을 들은 이 땅 사람들이 어떠했는지는 9절과 11절에 있다. 라합은 이스라엘의 하나님 여호와는 위로 하늘과 아래로 땅의 하나님이시라고 말했다."},"say":{"who":"onwoo","text":"라합이 여호와에 대해 무엇이라고 말했는지, 2장 11절에서 확인해 보자."}},{"ref":"수 2:12-14","focus":"rahab","text":{"t1":"라합은 두 사람에게 한 가지를 부탁했는데, 무엇을 부탁했는지는 12절과 13절에 있어요. 두 사람은 라합이 이 일을 남에게 알리지 않으면 그렇게 하겠다고 했어요.","t2":"라합은 자기가 두 사람을 잘 대해 주었으니, 두 사람도 자기 아버지의 집을 잘 대해 달라고 부탁했어요. 부모와 형제자매와 그들에게 딸린 사람을 모두 살려 주겠다고 여호와의 이름으로 맹세하고, 진실한 표를 달라고 했어요. 두 사람은 라합이 이 일을 누설하지 않으면, 여호와께서 이 땅을 주실 때에 라합을 인자하고 진실하게 대하겠다고 대답했어요.","t3":"라합은 자기가 두 사람을 선대했으니 그들도 자기 아버지의 집을 선대하여, 부모와 남녀 형제와 그들에게 딸린 모든 사람을 살려 죽음에서 건져 내겠다고 여호와의 이름으로 맹세하고 진실한 표를 달라고 청했다. 두 사람은 라합이 이 일을 누설하지 않으면 자기들의 생명으로 대신하겠다고까지 말했고, 여호와께서 이 땅을 주실 때에 라합을 인자하고 진실하게 대하겠다고 대답했다."},"say":{"who":"hyu","text":"라합이 부탁했고, 두 사람이 대답했어. 주고받은 말을 순서대로 적어 둘게."}},{"ref":"수 2:15-21","focus":"window","text":{"t1":"라합은 성벽 위에 있는 집의 창에서 두 사람을 줄로 달아 내려 주었어요. 두 사람이 떠난 뒤, 라합은 그들이 말한 대로 창문에 붉은 줄을 맸어요.","t2":"라합은 두 사람을 창에서 줄로 달아 내려 주었는데, 왜 창으로 내려 주었는지는 15절에 있어요. 두 사람은 자기들이 이 땅에 들어올 때 그 창에 붉은 줄을 매고, 부모와 형제와 아버지의 가족을 모두 집에 모으라고 했어요. 라합은 그 말대로 하겠다고 하고 두 사람을 보낸 뒤 붉은 줄을 창문에 맸어요.","t3":"라합은 두 사람을 창에서 줄로 달아 내렸다. 그의 집이 성벽 위에 있어 그가 성벽 위에 살았기 때문이다. 두 사람은 자기들이 이 땅에 들어올 때 자기들을 달아 내린 창에 이 붉은 줄을 매고, 부모와 형제와 아버지의 가족을 다 집에 모으라고 했다. 집 문을 나서 거리로 나가는 사람의 피는 그 사람 자신의 머리로 돌아가고, 라합과 함께 집 안에 있는 사람에게 누가 손을 대면 그 피는 자기들의 머리로 돌아올 것이라고 했다. 또 라합이 이 일을 누설하면 자기들은 그 맹세에서 벗어난다고 했다. 라합은 그 말대로 하겠다고 하고 그들을 보낸 뒤, 붉은 줄을 창문에 맸다."},"say":{"who":"choeon","text":"저 집 창문에 붉은 줄이 매여 있어!"}},{"ref":"수 2:22-24","focus":"spies","text":{"t1":"두 사람은 산에서 사흘을 머문 뒤 강을 건너 여호수아에게 돌아갔어요. 겪은 일을 모두 여호수아에게 알렸어요.","t2":"쫓는 사람들은 길에서 두루 찾았지만 두 사람을 만나지 못했어요. 두 사람은 여호수아에게 돌아가, 여호와께서 그 온 땅을 자기들 손에 주셨고 그 땅에 사는 사람들이 모두 자기들 앞에서 마음이 녹았다고 말했어요.","t3":"두 사람은 쫓는 사람들이 돌아갈 때까지 기다렸고, 쫓는 사람들은 길에서 두루 찾았으나 그들을 만나지 못했다. 그 뒤 두 사람은 강을 건너, 여호수아에게 돌아가 겪은 일을 모두 알렸다. 그들이 여호수아에게 한 말은 24절에서 직접 읽어 보자."},"say":{"who":"hyu","text":"두 사람이 어디를 거쳐 여호수아에게 돌아갔는지 22절과 23절에서 차례대로 찾아 적자."}}],"gates":{"t1":[{"type":"find","ref":"수 2:6","prompt":"성경책에서 여호수아 2장 6절을 찾아 읽어 보세요.","confirm":{"prompt":"라합은 두 사람을 어디에 숨겼나요?","options":[{"label":"지붕 위에 널어 둔 삼대 속","ok":true},{"label":"마당의 우물 속","basis":"삼하 17:18"},{"label":"성문 옆 망대 위","basis":"본문에 없음"}]}},{"type":"multi","ref":"수 2:18","prompt":"성경책에서 여호수아 2장 18절을 찾아 읽어 보세요.","confirm":{"prompt":"두 사람이 이 땅에 들어올 때 라합의 집에 모아 두라고 한 사람을 모두 고르세요.","options":[{"label":"라합의 부모","ok":true},{"label":"여리고 왕의 신하들","basis":"본문에 없음"},{"label":"라합의 형제","ok":true},{"label":"성문을 지키는 사람들","basis":"본문에 없음"},{"label":"라합의 아버지의 가족","ok":true}]}}],"t2":[{"type":"find","ref":"수 2:15-16","prompt":"성경책에서 여호수아 2장 15절과 16절을 읽어 보세요.","confirm":{"prompt":"라합이 두 사람을 창에서 줄로 달아 내려 보낸 것은 무엇 때문이었나요?","options":[{"label":"라합의 집이 성벽 위에 있었기 때문에","ok":true},{"label":"왕이 보낸 사람들이 집 앞에 아직 남아 있었기 때문에","basis":"본문에 없음"},{"label":"두 사람이 밤에는 성문을 지나갈 수 없다고 했기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"수 2:21-23","prompt":"성경책에서 여호수아 2장 21절부터 23절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["라합이 두 사람을 떠나보냈다","두 사람이 산에 이르러 사흘을 머물렀다","두 사람이 산을 내려와 강을 건넜다","두 사람이 여호수아에게 가서 겪은 일을 모두 알렸다"]}],"t3":[{"type":"find","refs":["수 2:7","수 2:22"],"prompt":"여호수아 2장 7절과 22절을 함께 찾아 읽어 보자.","confirm":{"prompt":"쫓는 사람들이 간 길과 두 사람이 머문 곳을 이어 보면, 쫓는 사람들이 두 사람을 만나지 못한 것은 어떻게 된 일인가?","options":[{"label":"쫓는 사람들은 요단으로 가는 길을 따라 나루턱까지 갔고, 두 사람은 산에 가서 사흘을 머물렀다","ok":true},{"label":"쫓는 사람들은 산으로 가는 길을 따라 올라갔고, 두 사람은 요단 나루턱 근처에서 사흘을 숨어 있었다","basis":"본문에 없음"},{"label":"쫓는 사람들은 요단 길로 나가다가 그날 밤 성으로 돌아왔고, 두 사람은 성 근처 들판에 숨어 있었다","basis":"본문에 없음"}]}},{"type":"match","refs":["수 2:1","수 2:15","수 2:23"],"prompt":"여호수아 2장 1절, 15절, 23절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"수 2:1","text":"여호수아가 몰래 두 사람을 보내 그 땅과 여리고를 살피게 했다"},{"ref":"수 2:15","text":"라합이 성벽 위에 있는 자기 집 창에서 두 사람을 줄로 내려 주었다"},{"ref":"수 2:23","text":"두 사람이 산을 떠나 강 건너 여호수아에게 돌아갔다"}],"after":"세 곳을 이으면, 싯딤에서 보낸 두 사람은 성벽 위 라합의 집 창으로 내려와, 산을 떠나 강을 건너 여호수아에게 돌아갔다."}]},"cards":[{"ref":"수 2:11","title":"하늘과 땅의 하나님"},{"ref":"수 2:21","title":"창문에 맨 붉은 줄"}],"close":{"t1":{"kind":"prayer","text":"하나님, 라합과 두 정탐꾼의 이야기를 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 여호수아 2장 8절부터 14절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"수 2:1-24에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 타임머신 계기판의 바늘 하나가 부러졌어요. 여리고 성 밖에서 가늘고 곧은 재료를 찾아봐요.","t2":"최현 박사예요. 비상 착륙 때 계기판 바늘이 부러져서 눈금을 읽을 수가 없어요. 이 시대에는 우리 부속이 없으니, 여리고 성 밖에서 바늘 대신 쓸 가늘고 곧은 재료를 찾아야 해요.","t3":"최현 박사다. 비상 착륙으로 계기판 바늘이 부러졌고 지금은 통신만 이어져 있다. 이 시대에는 부속이 없으니 여리고 성 밖에서 가늘고 곧은 재료를 구해 바늘을 대신 만들어야 한다."},"materials":[{"key":"stone","name":"가는 돌 조각","basis":"수 2:1","use":"가늘고 곧은 돌 조각을 부러진 계기판 바늘 대신 쓸 수 있어요.","how":"성과 성문, 라합의 집 쪽으로는 가지 않는다. 성에서 멀찍이 떨어진 성 밖 땅에서 가늘고 곧은 돌 조각 하나를 줍는다.","line":"가늘고 곧은 돌 조각을 주웠어! 성에서 멀찍이 떨어진 성 밖 땅에 있었네."}],"companion":{"who":"라합","ref":"수 2:1","when":"after","talks":[{"ask":{"who":"hyu","text":"두 사람에게 무엇을 부탁하셨어요?"},"answer":{"t1":"라합은 자기가 두 사람에게 잘해 주었으니, 자기 아버지의 집 식구들을 살려 주겠다고 여호와의 이름으로 맹세해 달라고 부탁했어요.","t2":"라합은 자기가 두 사람을 잘 대해 주었으니, 두 사람도 자기 아버지의 집을 잘 대해 달라고 부탁했어요. 부모와 형제자매와 그들에게 딸린 사람을 모두 살려 주겠다고 여호와의 이름으로 맹세하고, 진실한 표를 달라고 했어요.","t3":"라합은 자기가 두 사람을 선대했으니 그들도 자기 아버지의 집을 선대해 달라고 청했다. 부모와 남녀 형제와 그들에게 딸린 모든 사람을 살려 죽음에서 건져 내겠다고 여호와의 이름으로 맹세하고, 진실한 표를 달라고 했다."},"ref":"수 2:12-13","open":"수 2:12"},{"ask":{"who":"onwoo","text":"두 사람을 내려 보낼 때 어디로 가라고 하셨어요?"},"answer":{"t1":"라합은 두 사람에게, 쫓는 사람들과 마주치지 않게 산으로 가서 사흘 동안 숨어 있으라고 말했어요.","t2":"라합은 쫓는 사람들이 두 사람을 만날까 두렵다고 했어요. 그래서 산으로 가서 사흘 동안 숨어 있다가, 쫓는 사람들이 돌아간 뒤에 길을 가라고 말했어요.","t3":"라합은 쫓는 사람들이 두 사람을 만날까 두렵다며, 산으로 가서 사흘 동안 숨어 있다가 쫓는 사람들이 돌아간 뒤에 갈 길을 가라고 말했다."},"ref":"수 2:16","open":"수 2:16"}]},"today":[{"q":"라합이 창문에 맨 붉은 줄은 무슨 뜻이에요?","a":{"t1":"두 사람은 자기들이 이 땅에 들어올 때 그 창에 붉은 줄을 매어 두라고 라합에게 말했어요. 라합은 그 말대로 붉은 줄을 창문에 맸어요. 성경은 여기까지 말해요.","t2":"두 사람은 자기들이 이 땅에 들어올 때 자기들을 달아 내린 창에 이 붉은 줄을 매고, 가족을 모두 집에 모으라고 라합에게 말했어요. 라합은 그 말대로 하겠다고 하고 붉은 줄을 창문에 맸어요. 성경은 두 사람이 한 말과 라합이 한 일까지 적어요.","t3":"두 사람은 자기들이 이 땅에 들어올 때 자기들을 달아 내린 창에 이 붉은 줄을 매고, 부모와 형제와 아버지의 가족을 다 집에 모으라고 라합에게 말했다(수 2:18). 라합은 그 말대로 하겠다고 하고 두 사람을 보낸 뒤 붉은 줄을 창문에 맸다(수 2:21). 본문은 두 사람이 한 말과 라합이 한 일까지 적고, 붉은 줄이 따로 무엇을 뜻하는지는 풀어 말하지 않는다."},"refs":["수 2:18","수 2:21"]}],"help":{"who":"라합","steps":[{"kind":"watch","after":2,"title":"지켜보기 · 숨겨 준 두 사람","basis":"수 2:6","text":{"t1":"라합은 왕이 보낸 사람들이 오기 전에 두 사람을 숨겼어요. 우리는 숨기는 일에 끼지 않고 멀찍이 바라봐요.","t2":"라합은 이미 두 사람을 지붕으로 데리고 올라가, 지붕 위에 널어 둔 삼대 속에 숨겨 두었어요. 두 사람을 숨긴 것은 라합이 한 일이에요. 우리는 그 일에 끼지 않고 성 밖에서 멀찍이 바라보기만 해요.","t3":"라합은 이미 두 사람을 지붕으로 이끌고 올라가, 지붕 위에 널어 둔 삼대 속에 숨겨 두었다(2:4, 2:6). 두 사람을 숨긴 것은 라합이 한 일이다. 탐험대는 숨기는 일에 끼지 않고 삼대에도 손대지 않으며, 성 밖에서 멀찍이 바라본다."},"say":{"who":"onwoo","text":"두 사람이 어디에 숨었는지는 2장 6절에 적혀 있어."}},{"kind":"watch","after":5,"title":"지켜보기 · 창문의 붉은 줄","basis":"수 2:21","text":{"t1":"라합은 두 사람을 보낸 뒤 붉은 줄을 창문에 맸어요. 우리는 그 줄에 손대지 않고 바라봐요.","t2":"두 사람은 자기들을 달아 내린 그 창에 이 붉은 줄을 매어 두라고 했어요. 라합은 그 말대로 하겠다고 하고, 두 사람을 보낸 뒤 붉은 줄을 창문에 맸어요. 우리는 그 줄에 손대지 않고 바라보기만 해요.","t3":"두 사람은 자기들이 이 땅에 들어올 때, 자기들을 달아 내린 창에 이 붉은 줄을 매어 두라고 했다(2:18). 라합은 그 말대로 하겠다고 하고 두 사람을 떠나보낸 뒤 붉은 줄을 창문에 맸다(2:21). 줄을 매는 것은 라합이 한 일이다. 탐험대는 그 줄에 손대지 않고 바라본다."}},{"kind":"do","after":6,"title":"탐험 일지 정리하기","basis":"수 2:22-24","text":{"t1":"두 사람은 여호수아에게 돌아갔어요. 우리는 성에서 멀찍이 떨어진 곳에서, 그동안 지켜본 것을 탐험 일지에 정리해요.","t2":"두 사람은 여호수아에게 돌아갔어요. 우리는 성에서 멀찍이 떨어진 곳에서, 지켜본 것을 탐험 일지에 정리해요. 본 곳과 본 물건을 적고, 성경에서 다시 읽을 절에 표시해요.","t3":"두 사람은 여호수아에게 돌아가 겪은 일을 모두 알렸다. 탐험대는 성에서 멀찍이 떨어진 곳에서, 지켜본 것을 탐험 일지에 정리한다. 이것은 성경의 사건이 아니라 탐험대의 일이다. 본 곳과 본 물건을 적고, 성경에서 다시 읽을 절에 표시해 둔다."},"tasks":["본 곳 적기","본 물건 적기","다시 읽을 절 표시하기"],"done":{"who":"hyu","text":"본 곳과 본 물건을 다 적었어. 이제 성경에서 하나씩 확인해 보자."}},{"kind":"ask","after":"gates","title":"이 일은 무슨 뜻이에요?","basis":"수 2:9-11","by":"라합","ask":{"who":"choeon","text":"두 사람이 여리고에 온 이 일은 무슨 뜻이에요?"},"answer":{"t1":"라합은 두 사람에게, 여호와께서 이 땅을 이스라엘에게 주신 줄을 안다고 말했어요. 이스라엘의 하나님 여호와는 위로 하늘과 아래로 땅의 하나님이시라고 했어요.","t2":"라합은 두 사람에게, 여호와께서 이 땅을 이스라엘에게 주신 줄을 안다고 말했어요. 여호와께서 홍해의 물을 말리신 일과, 이스라엘이 요단 저편 아모리 사람의 두 왕에게 한 일을 들었다고 했어요. 그리고 이스라엘의 하나님 여호와는 위로 하늘과 아래로 땅의 하나님이시라고 했어요.","t3":"라합은 두 사람에게, 여호와께서 이 땅을 이스라엘에게 주신 줄을 안다고 말했다. 이스라엘이 애굽에서 나올 때 여호와께서 홍해의 물을 말리신 일과, 이스라엘이 요단 저편의 두 아모리 왕 시혼과 옥에게 한 일을 듣고 그 땅 사람들의 마음이 녹았다고 했다. 그리고 이스라엘의 하나님 여호와는 위로 하늘과 아래로 땅의 하나님이시라고 말했다."},"read":{"t1":{"type":"find","ref":"수 2:9","prompt":"성경책에서 여호수아 2장 9절을 찾아 읽어 보세요.","confirm":{"prompt":"라합은 여호와께서 이 땅을 누구에게 주신 줄을 안다고 했나요?","options":[{"label":"두 사람이 속한 이스라엘","ok":true},{"label":"라합이 사는 여리고 사람들","basis":"본문에 없음"},{"label":"요단 저편의 아모리 사람","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"수 2:9-11","prompt":"성경책에서 여호수아 2장 9절부터 11절까지 읽어 보세요.","confirm":{"prompt":"라합이 그 땅 사람들의 마음이 녹았다고 한 까닭은 무엇인가요?","options":[{"label":"여호와께서 홍해를 마르게 하신 일과, 요단 저편 두 왕 시혼과 옥을 이스라엘이 멸한 일을 들었기 때문에","ok":true},{"label":"여호와께서 이스라엘 앞에서 요단의 물을 말리시고, 그들을 모두 건너게 하신 일을 들었기 때문에","basis":"수 5:1"},{"label":"이스라엘에서 온 몇 사람이 밤에 몰래 땅을 살피러 들어왔다는 소식을 들었기 때문에","basis":"수 2:2"}]}},"t3":{"type":"find","refs":["수 2:9","수 2:24"],"prompt":"여호수아 2장 9절과 24절을 함께 찾아 읽어 보자.","confirm":{"prompt":"라합이 지붕에서 두 사람에게 한 말과, 두 사람이 돌아가 여호수아에게 한 말을 이어 읽으면 무엇이 같은가?","options":[{"label":"라합도 두 사람도, 여호와께서 그 땅을 이스라엘에게 주셨고 그 땅 사람들이 이스라엘 앞에서 마음이 녹았다고 말했다","ok":true},{"label":"라합은 그렇게 말했지만, 두 사람은 여리고 성이 높고 그 땅 사람들이 강해서 차지하기 어렵다고 알렸다","basis":"민 13:28"},{"label":"라합도 두 사람도, 홍해 물이 마른 일과 요단 저편의 두 왕 시혼과 옥이 멸망한 일을 들었다고 말했다","basis":"수 2:10"}]}}}}]}},"has3d":false,"epic":false},"OT-18":{"id":"OT-18","era":5,"title":"요단 강을 건너다","ref":"수 3:1-4:24","place":"요단 강과 길갈","review":{"required":false,"topics":[],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"수 3:1-6","focus":"camp","text":{"t1":"이스라엘 백성은 싯딤을 떠나 요단 강가에 와서 묵었어요. 관리들은 언약궤를 따라가되 가까이 가지는 말라고 알렸어요.","t2":"여호수아는 아침 일찍 일어나 이스라엘 사람들과 함께 싯딤을 떠났고, 요단에 이르러서는 건너지 않고 거기서 묵었어요. 사흘 뒤에 관리들이 진을 두루 다니며, 레위 사람 제사장들이 언약궤를 메는 것을 보면 그 뒤를 따르라고 했어요. 언약궤와는 이천 규빗쯤 떨어지고 가까이 가지 말라고 했어요. 여호수아는 백성에게 스스로 성결하게 하라고 했고, 제사장들에게는 언약궤를 메고 백성보다 앞서 건너라고 했어요.","t3":"여호수아는 아침 일찍 일어나 이스라엘 사람들과 함께 싯딤을 떠났고, 요단에 이르러서는 건너지 않고 거기서 묵었다. 그 뒤 관리들이 진 가운데를 두루 다니며, 레위 사람 제사장들이 여호와의 언약궤를 메는 것을 보면 있던 곳을 떠나 그 뒤를 따르라고 명했다. 다만 언약궤와 백성 사이를 이천 규빗쯤 떨어지게 하고 가까이 가지 말라고 했는데, 전에 지나 본 적이 없는 길이니 그렇게 해야 갈 길을 알 것이라고 했다. 여호수아는 백성에게 스스로 성결하게 하라고 했다. 관리들이 언제 진을 다녔고 여호수아가 놀라운 일이 언제 있으리라고 했는지는 2절과 5절에 있다. 또 제사장들에게 언약궤를 메고 백성보다 앞서 건너라고 하자, 그들이 언약궤를 메고 백성 앞에서 나아갔다."},"say":{"who":"hyu","text":"싯딤을 떠나 요단 강가까지 왔어. 여기서 며칠을 묵었는지 성경에서 찾아 일지에 적자."}},{"ref":"수 3:7-13","open":"수 3:7-8","focus":"joshua","text":{"t1":"하나님은 모세와 함께하셨듯이 여호수아와도 함께하심을 백성이 알게 하겠다고 하셨어요. 여호수아는 제사장들이 강물에 발을 디디면 위에서 흘러 내려오던 물이 멈출 거라고 알렸어요.","t2":"하나님은 여호수아에게, 오늘부터 온 이스라엘이 보는 앞에서 그를 크게 하여, 모세와 함께 있었던 것처럼 그와 함께 있는 것을 알게 하겠다고 하셨어요. 언약궤를 멘 제사장들에게는 요단 물가에 이르면 요단에 들어서라고 명하게 하셨어요. 여호수아는 백성을 불러 하나님 여호와의 말씀을 들으라고 했어요. 제사장들이 요단 물에 발을 디디고 멈추어 서면, 위에서 흘러내리던 물이 끊어져 쌓일 것이라고 했어요.","t3":"여호와께서는 여호수아에게, 오늘부터 온 이스라엘이 보는 앞에서 그를 크게 하여, 모세와 함께 있었던 것처럼 그와 함께 있는 것을 그들이 알게 하겠다고 하셨다. 또 언약궤를 멘 제사장들에게 요단 물가에 이르면 요단에 들어서라고 명하게 하셨다. 여호수아는 이스라엘 자손을 불러 하나님 여호와의 말씀을 들으라고 했다. 이 일로 그들이 무엇을 알게 될 것이라고 했는지는 10절에 있다. 온 땅의 주의 언약궤가 그들보다 앞서 요단으로 들어간다고 했다. 그리고 궤를 멘 제사장들이 요단 물에 발을 디디고 멈추어 서면, 위에서 흘러내리던 물이 끊어져 쌓여 설 것이라고 했다."},"say":{"who":"onwoo","text":"하나님이 여호수아에게 하신 말씀은 3장 7절과 8절에 있어. 성경책에서 직접 읽어 보자."}},{"ref":"수 3:14-16","focus":"river","text":{"t1":"곡식을 거두는 때라 강물이 언덕까지 넘쳤어요. 제사장들의 발이 물에 닿자 위에서 흐르던 물이 멈추어 멀리 쌓였어요!","t2":"백성이 요단을 건너려고 장막을 떠날 때, 언약궤를 멘 제사장들이 백성보다 앞서 갔어요. 요단은 그때 언덕까지 넘쳐 있었는데, 왜 그랬는지는 15절에 있어요. 궤를 멘 제사장들이 물가에 발을 담그자, 위에서 흘러내리던 물이 멈추어 멀리 아담이라는 성읍 쪽에 쌓였어요. 염해로 흘러가던 물은 완전히 끊어졌고, 백성은 여리고 앞쪽으로 건넜어요.","t3":"백성이 요단을 건너려고 장막을 떠날 때, 언약궤를 멘 제사장들이 백성보다 앞서 갔다. 요단은 곡식을 거두는 때면 늘 언덕까지 넘쳤다. 궤를 멘 사람들이 요단에 이르러 제사장들의 발이 물가에 잠기자, 위에서 흘러내리던 물이 그쳐 한곳에 일어나 쌓였는데, 그곳이 어디였는지는 16절에 있다. 아라바의 바다 곧 염해 쪽으로 흘러가던 물은 완전히 끊어졌고, 백성은 여리고 앞쪽으로 곧장 건넜다."},"say":{"who":"choeon","text":"강물이 언덕까지 넘치고 있었는데, 위에서 내려오던 물이 멈췄어!"}},{"ref":"수 3:17","focus":"priests","text":{"t1":"제사장들은 궤를 멘 채 강 한가운데의 마른 땅에 서 있었어요. 그동안 온 백성이 마른 땅으로 걸어서 강을 건넜어요.","t2":"제사장들은 여호와의 언약궤를 멘 채 요단 한가운데 마른 땅에 굳게 서 있었어요. 그동안 온 이스라엘 백성이 마른 땅을 걸어 요단을 건넜어요.","t3":"제사장들은 여호와의 언약궤를 멘 채 요단 한가운데의 마른 땅에 굳게 서 있었고, 온 이스라엘 백성은 마른 땅을 밟고 지나 요단을 다 건넜다."},"say":{"who":"choeon","text":"제사장들이 강 한가운데 서 있어. 발밑이 마른 땅이야!"}},{"ref":"수 4:1-9","open":"수 4:2-3","focus":"stones","text":{"t1":"지파마다 한 사람씩 뽑힌 열두 사람이 강 가운데서 돌을 하나씩 가져왔어요. 여호수아는 이 돌들이 표징이 될 거라고 했어요.","t2":"온 백성이 건너기를 마치자, 하나님은 지파마다 한 사람씩 열두 사람을 뽑아, 제사장들의 발이 굳게 섰던 요단 가운데서 돌 열두 개를 가져다가 그날 밤 묵을 곳에 두게 하라고 하셨어요. 여호수아는 열두 사람을 불러 돌을 하나씩 어깨에 메라고 했어요. 훗날 자손이 이 돌들이 무슨 뜻이냐고 물으면, 여호와의 언약궤 앞에서 요단 물이 끊어졌다고 말해 주라고 했어요. 이스라엘 자손은 그대로 했어요.","t3":"온 백성이 요단을 다 건너자 여호와께서 여호수아에게 말씀하셨다. 지파마다 한 사람씩 열두 사람을 뽑아, 요단 가운데 제사장들의 발이 굳게 섰던 곳에서 돌 열둘을 가져다가 그날 밤 묵을 곳에 두게 하라는 것이었다. 여호수아는 열두 사람을 불러, 요단 가운데 여호와의 궤 앞으로 들어가 지파 수대로 돌을 하나씩 어깨에 메라고 했다. 이것이 그들 가운데 표징이 될 것이며, 훗날 자손이 이 돌들의 뜻을 물으면 여호와의 언약궤 앞에서 요단 물이 끊어졌다고 말하라고 했다. 이 돌들이 이스라엘 자손에게 영원한 기념이 될 것이라고 했다. 이스라엘 자손은 여호수아가 명한 대로 돌 열둘을 묵을 곳으로 가져다 두었다."},"say":{"who":"hyu","text":"돌은 열두 개야. 지파 수대로 한 사람이 하나씩 가지고 나왔어. 일지에 적어 둘게."}},{"ref":"수 4:14-18","open":"수 4:16","focus":"river","text":{"t1":"하나님의 말씀대로 제사장들이 요단에서 올라왔어요. 제사장들의 발이 뭍을 밟자 강물이 다시 흘러 언덕까지 넘쳤어요.","t2":"그날 여호와께서 온 이스라엘이 보는 앞에서 여호수아를 크게 하셨어요. 그 뒤 제사장들이 요단에서 올라오기까지 무슨 일이 어떤 차례로 있었는지는 15절부터 18절까지 읽어 봐요. 제사장들이 올라오자 요단 물은 전처럼 언덕까지 넘쳤어요.","t3":"그날 여호와께서 온 이스라엘이 보는 앞에서 여호수아를 크게 하셨으므로, 백성은 여호수아가 살아 있는 동안 모세를 두려워하던 것처럼 그를 두려워했다. 여호와께서는 여호수아에게, 증거궤를 멘 제사장들이 요단에서 올라오도록 명하라고 하셨다. 여호수아가 제사장들에게 요단에서 올라오라고 명하자, 제사장들이 여호와의 언약궤를 메고 요단 한가운데에서 올라왔다. 그들의 발바닥이 뭍을 밟는 그때에 요단 물이 제자리로 도로 흘러, 전과 같이 언덕까지 넘쳤다."},"say":{"who":"choeon","text":"제사장들이 올라오니까 물이 다시 흘러. 또 언덕까지 넘쳐!"}},{"ref":"수 4:19-24","focus":"gilgal","text":{"t1":"백성은 길갈에 진을 쳤고, 여호수아는 요단에서 가져온 돌 열두 개를 거기 세웠어요. 훗날 자손이 물으면 마른 땅으로 요단을 건넌 일을 알려 주라고 했어요.","t2":"첫째 달 곧 정월 십일에 백성은 요단에서 올라와, 여리고 동쪽 경계에 있는 길갈에 진을 쳤어요. 여호수아는 요단에서 가져온 돌 열두 개를 길갈에 세우고 말했어요. 훗날 자손이 이 돌이 무슨 뜻이냐고 물으면, 이스라엘이 마른 땅을 밟고 요단을 건넜다고 알려 주라고 했어요. 여호와께서 홍해를 말리셨던 것처럼 요단 물도 마르게 하여 건너게 하셨다고 했어요.","t3":"첫째 달 곧 정월 십일에 백성은 요단에서 올라와 여리고 동쪽 경계인 길갈에 진을 쳤다. 여호수아는 요단에서 가져온 돌 열두 개를 길갈에 세우고 이스라엘 자손에게 말했다. 훗날 자손이 아버지에게 이 돌이 무슨 뜻이냐고 묻거든, 이스라엘이 이 요단을 마른 땅을 밟고 건넜다는 것을 알려 주라고 했다. 하나님 여호와께서 요단 물을 마르게 하여 건너게 하신 것이 홍해를 말려 건너게 하신 것과 같다고 했다. 그렇게 하신 까닭도 말했는데, 그 말은 24절에 있다."},"say":{"who":"onwoo","text":"이 돌들이 무슨 뜻인지, 여호수아가 한 말을 4장 21절부터 24절에서 확인하자."}}],"gates":{"t1":[{"type":"find","ref":"수 4:5","prompt":"성경책에서 여호수아 4장 5절을 찾아 읽어 보세요.","confirm":{"prompt":"여호수아는 열두 사람에게 돌을 하나씩 어떻게 가지고 나오라고 했나요?","options":[{"label":"어깨에 메고","ok":true},{"label":"머리에 이고","basis":"본문에 없음"},{"label":"나귀 등에 싣고","basis":"본문에 없음"}]}},{"type":"multi","ref":"수 4:14","prompt":"성경책에서 여호수아 4장 14절을 찾아 읽어 보세요.","confirm":{"prompt":"요단을 건넌 날, 여호와께서 여호수아를 어떻게 하셨고 백성은 여호수아를 어떻게 대했나요? 맞는 것을 모두 고르세요.","options":[{"label":"여호와께서 온 이스라엘 앞에서 여호수아를 높여 주셨어요","ok":true},{"label":"여호수아가 지팡이를 들어 강물을 갈랐어요","basis":"본문에 없음"},{"label":"백성은 여호수아가 살아 있는 동안 모세처럼 그를 두려워했어요","ok":true},{"label":"여호수아의 이름이 온 땅에 퍼졌어요","basis":"수 6:27"}]}}],"t2":[{"type":"find","ref":"수 3:5-6","prompt":"성경책에서 여호수아 3장 5절과 6절을 읽어 보세요.","confirm":{"prompt":"여호수아가 백성에게 스스로 성결하게 하라고 한 까닭은 무엇인가요?","options":[{"label":"내일 여호와께서 그들 가운데 놀라운 일을 행하실 것이기 때문에","ok":true},{"label":"내일 제사장들이 여호와께 큰 제사를 드리고 온 백성이 함께 먹을 것이기 때문에","basis":"본문에 없음"},{"label":"셋째 날에 여호와께서 온 백성 앞에서 시내 산에 내려오실 것이기 때문에","basis":"출 19:11"}]}},{"type":"order","ref":"수 4:15-19","prompt":"성경책에서 여호수아 4장 15절부터 19절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["하나님이 여호수아에게 제사장들을 강에서 나오게 하라고 하셨다","여호수아가 그 말씀대로 제사장들에게 명했다","제사장들이 뭍을 밟자 요단 물이 다시 흘렀다","백성이 강에서 올라와 길갈에 진을 쳤다"]}],"t3":[{"type":"find","refs":["수 3:13","수 3:16"],"prompt":"여호수아 3장 13절과 16절을 함께 찾아 읽어 보자.","confirm":{"prompt":"여호수아가 미리 한 말과 그 뒤에 일어난 일을 이어 읽으면 어떠한가?","options":[{"label":"여호수아는 제사장들이 강물에 발을 딛고 서면 위쪽 물이 끊어져 쌓일 것이라고 했고, 그대로 위쪽에서 내려오던 물이 멈추어 멀리 아담 읍 쪽에 쌓였다","ok":true},{"label":"여호수아는 제사장들이 강물에 발을 딛고 서면 위쪽 물이 끊어져 쌓일 것이라고 했고, 그대로 위쪽 물이 멈추어 제사장들 바로 곁에 벽처럼 쌓였다","basis":"본문에 없음"},{"label":"여호수아는 제사장들이 강물에 발을 딛고 서면 위쪽 물이 끊어져 쌓일 것이라고 했고, 그대로 위쪽 물이 멈추어 여리고 성 앞에 쌓였다","basis":"본문에 없음"}]},"inStory":"물이 멈춘 일과 여호수아의 예고는 이야기의 줄기라 낱말이 겹친다. 세 보기는 물이 쌓인 곳으로만 갈리고, 그곳(3:16 아담 읍)은 이야기 글에서 뺐다"},{"type":"match","refs":["수 3:7","수 4:10","수 4:12","수 4:14"],"prompt":"여호수아 3장 7절, 4장 10절, 4장 12절, 4장 14절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"수 3:7","text":"모세와 함께하셨듯이 여호수아와 함께하심을 온 이스라엘이 알게 하겠다고 하셨다"},{"ref":"수 4:10","text":"궤를 멘 제사장들은 명하신 일이 다 끝날 때까지 강 가운데 서 있었고, 백성은 서둘러 건넜다"},{"ref":"수 4:12","text":"르우벤 자손, 갓 자손, 므낫세 반 지파가 모세의 말대로 무장하고 앞서 건넜다"},{"ref":"수 4:14","text":"그날 백성이 여호수아를 모세처럼 두려워했다"}],"after":"네 곳을 이으면, 하나님은 모세와 함께하셨듯 여호수아와 함께하겠다고 하셨고, 요단을 건너는 일은 모세가 명한 대로 이루어졌으며, 그날 백성은 여호수아를 모세처럼 두려워했다."}]},"cards":[{"ref":"수 3:17","title":"마른 땅으로 건넌 요단"},{"ref":"수 4:24","title":"여호와의 손이 능하심"}],"close":{"t1":{"kind":"prayer","text":"하나님, 요단 강에서 하신 일을 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 여호수아 4장 19절부터 24절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"수 3:1-4:24에서 새로 알게 된 사실을 한 가지 적어 보자."}},"quests":[{"part":"lens","name":"렌즈","line":"렌즈를 찾았어! 장막들에서 떨어진 진 가장자리에 있었네.","found":"탐지기가 요단 강가에 친 장막들 쪽을 가리켜요.","say":{"who":"hyu","text":"탐지기 바늘이 강가의 장막 쪽으로 돌아갔어. 장막 사이로 들어가지는 말고 바깥쪽에서 찾자."},"q":{"t1":{"type":"find","ref":"수 3:1","prompt":"성경책에서 여호수아 3장 1절을 찾아 읽어 보세요.","confirm":{"prompt":"여호수아가 이스라엘 사람들과 함께 싯딤을 떠난 것은 하루 중 언제였나요?","options":[{"label":"아침 일찍","ok":true},{"label":"한밤중","basis":"본문에 없음"},{"label":"해가 질 무렵","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"수 3:3-4","prompt":"성경책에서 여호수아 3장 3절과 4절을 읽어 보세요.","confirm":{"prompt":"관리들이 백성에게 언약궤와 이천 규빗쯤 떨어져 따라가라고 한 까닭은 무엇인가요?","options":[{"label":"그래야 갈 길을 알 수 있는데, 전에 그 길을 지나가 본 적이 없었기 때문에","ok":true},{"label":"그래야 적군 눈에 띄지 않는데, 언약궤 앞쪽에 적군이 숨어 있었기 때문에","basis":"본문에 없음"},{"label":"그래야 서로 밀치지 않는데, 백성이 너무 많아 길이 좁았기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["수 3:2","수 3:5"],"prompt":"여호수아 3장 2절과 5절을 함께 찾아 읽어 보자.","confirm":{"prompt":"요단 가에 이른 뒤의 일을 이어 읽으면, 관리들이 진을 두루 다닌 때와 여호수아가 놀라운 일이 있으리라고 한 때는 언제인가?","options":[{"label":"관리들은 사흘 뒤에 진을 두루 다니며 명했고, 여호수아는 여호와께서 내일 놀라운 일을 행하실 것이라고 했다","ok":true},{"label":"관리들은 이레 뒤에 진을 다녔고, 여호수아는 놀라운 일이 그날 밤에 있으리라고 했다","basis":"본문에 없음"},{"label":"관리들은 그날 바로 진을 다녔고, 여호수아는 놀라운 일이 언제 있을지 말하지 않았다","basis":"본문에 없음"}]}}}},{"part":"antenna","name":"안테나","line":"안테나가 여기 있었네! 물이 닿지 않는 언덕 위쪽이야.","found":"탐지기가 물이 닿지 않는 강 언덕 위쪽을 가리켜요.","say":{"who":"choeon","text":"강물이 언덕까지 차올라 있어! 저기 제사장들이 언약궤를 메고 강 쪽으로 가고 있어."},"q":{"t1":{"type":"find","ref":"수 3:4","prompt":"성경책에서 여호수아 3장 4절을 찾아 읽어 보세요.","confirm":{"prompt":"백성은 언약궤와 얼마쯤 떨어져서 따라가야 했나요?","options":[{"label":"이천 규빗쯤","ok":true},{"label":"오백 규빗쯤","basis":"본문에 없음"},{"label":"오천 규빗쯤","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"수 3:14-15","prompt":"성경책에서 여호수아 3장 14절과 15절을 읽어 보세요.","confirm":{"prompt":"그때 요단 강물이 언덕까지 넘쳐 있었던 까닭은 무엇인가요?","options":[{"label":"곡식을 거두는 때에는 요단이 늘 언덕까지 넘쳤기 때문에","ok":true},{"label":"며칠 동안 큰비가 내려 요단 물이 갑자기 불어났기 때문에","basis":"본문에 없음"},{"label":"북쪽 산에서 눈이 녹아 많은 물이 한꺼번에 흘러내렸기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["수 3:12","수 4:4"],"prompt":"여호수아 3장 12절과 4장 4절을 함께 찾아 읽어 보자.","confirm":{"prompt":"돌을 메러 요단 가운데로 들어간 열두 사람은 언제 정해진 사람들인가?","options":[{"label":"물이 끊어지기 전에 여호수아가 지파마다 한 사람씩 뽑으라고 했고, 뒤에 그렇게 미리 세워 둔 열두 사람을 불렀다","ok":true},{"label":"온 백성이 다 건넌 뒤에야 여호수아가 그 자리에서 처음으로 지파마다 한 사람씩 열두 사람을 뽑았다","basis":"본문에 없음"},{"label":"제사장들이 요단에 들어서기 전에 자기들 가운데서 열두 사람을 골라 언약궤 곁에 세워 두었다","basis":"본문에 없음"}]}}}},{"part":"spring","name":"용수철","line":"용수철을 찾았어! 강 아래쪽 언덕 위에 있었네.","found":"탐지기가 강 아래쪽 언덕을 가리켜요.","say":{"who":"onwoo","text":"언덕 위까지만 가자. 강바닥으로 내려가지는 말자. 우리는 지켜보는 사람이야."},"q":{"t1":{"type":"find","ref":"수 3:16","prompt":"성경책에서 여호수아 3장 16절을 찾아 읽어 보세요.","confirm":{"prompt":"염해 쪽으로 흘러가던 요단 물은 어떻게 되었나요?","options":[{"label":"완전히 끊어졌어요","ok":true},{"label":"두 배로 불어났어요","basis":"본문에 없음"},{"label":"멀리 한곳에 쌓였어요","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"수 3:9-10","prompt":"성경책에서 여호수아 3장 9절과 10절을 읽어 보세요.","confirm":{"prompt":"여호수아는 백성이 이 일로 무엇을 알게 될 것이라고 했나요?","options":[{"label":"살아 계신 하나님이 그들 가운데 계셔서, 그 땅의 족속들을 그들 앞에서 반드시 쫓아내실 것","ok":true},{"label":"그 땅의 족속들이 스스로 겁을 먹고, 싸우지도 않고 이스라엘에게 땅을 내어 줄 것","basis":"본문에 없음"},{"label":"온 땅의 주 여호와의 언약궤가 그들보다 먼저 요단에 들어간다는 것","basis":"수 3:11"}]}},"t3":{"type":"find","refs":["수 4:3","수 4:9"],"prompt":"여호수아 4장 3절과 9절을 함께 찾아 읽어 보자.","confirm":{"prompt":"돌 열둘에 대해 하나님이 명하신 것과 여호수아가 한 일을 이어 읽으면, 돌은 어디에 놓였는가?","options":[{"label":"열두 사람이 요단 가운데서 가져온 돌은 그날 밤 묵을 곳에 두었고, 여호수아는 제사장들이 서 있던 강 한가운데 그 자리에도 돌 열둘을 세웠다","ok":true},{"label":"열두 사람이 요단 가운데서 가져온 돌은 그날 밤 묵을 곳에 두었고, 제사장들이 섰던 강 한가운데에는 돌을 하나도 남기지 않았다","basis":"본문에 없음"},{"label":"열두 사람이 요단 가운데서 가져온 돌은 그날 밤 묵을 곳에 두었고, 여호수아는 떠나온 싯딤 쪽 강가에도 돌 열둘을 따로 세웠다","basis":"본문에 없음"}]},"inStory":"돌 열둘을 묵을 곳에 둔 일(4:8)은 이야기에 남아 낱말이 겹친다. 보기를 가르는 것은 요단 가운데에도 돌을 세운 일(4:9)이고, 그것은 이야기 글에서 뺐다"}}}],"mission":{"call":{"t1":"최현 박사예요. 타임머신이 비상 착륙하면서 렌즈와 안테나와 용수철이 망가졌어요. 요단 강가에서 탐지기가 가리키는 곳을 찾아 대신 쓸 재료를 구해 봐요.","t2":"최현 박사예요. 요단 강가에 비상 착륙하면서 렌즈와 안테나와 용수철이 망가졌어요. 이 시대에는 우리 부속이 없으니, 탐지기가 가리키는 곳에서 대신 쓸 재료를 하나씩 찾아야 해요. 사람들 사이로는 들어가지 말고 멀찍이서 찾아봐요.","t3":"최현 박사다. 요단 강가에 비상 착륙하면서 렌즈, 안테나, 용수철이 망가졌고 지금은 통신만 이어져 있다. 이 시대에는 부속이 없으니 탐지기가 가리키는 곳마다 재료를 구해 세 부속을 대신 만들어야 한다."},"materials":[{"key":"clay","name":"강가 진흙","basis":"수 3:15","use":"진흙을 얇게 펴서 말린 뒤 가운데에 바늘구멍을 뚫으면, 바늘구멍 사진기처럼 렌즈 대신 쓸 수 있어요.","how":"장막 사이로 들어가지 않고, 언약궤와 제사장들이 있는 쪽에서 멀리 떨어진 진 가장자리 강가 언덕에서 진흙을 한 덩이 떠 낸다. 강물에는 손대지 않는다.","line":"진흙을 한 덩이 떠 냈어! 장막들에서 떨어진 진 가장자리 강가야."},{"key":"grainear","name":"곡식 이삭","basis":"수 3:15","use":"이삭 끝의 가늘고 긴 까끄라기를 세우면 안테나 대신 쓸 수 있어요.","how":"강바닥 쪽으로 내려가지 않고, 물이 닿지 않는 언덕 위쪽 땅에 떨어져 있는 곡식 이삭 하나를 줍는다.","line":"곡식 이삭을 주웠어! 물이 닿지 않는 언덕 위쪽에 떨어져 있었네."},{"key":"straw","name":"마른 짚","basis":"수 3:15","use":"마른 짚 몇 가닥을 꼬아 둥글게 감으면 용수철 대신 쓸 수 있어요.","how":"강바닥으로 내려가지 않고, 강 아래쪽 언덕 위에 떨어져 있는 마른 짚 몇 가닥을 줍는다.","line":"마른 짚 몇 가닥을 주웠어! 강 아래쪽 언덕 위에 떨어져 있었네."}],"companion":{"who":"여호수아","ref":"수 4:20","when":"after","talks":[{"ask":{"who":"hyu","text":"열두 사람에게는 무엇을 하라고 하셨어요?"},"answer":{"t1":"여호수아는 열두 사람에게, 요단 가운데 여호와의 궤 앞으로 들어가 돌을 하나씩 가지고 나오라고 말했어요. 그 돌들이 표징이 될 것이라고 했어요.","t2":"여호수아는 열두 사람에게, 요단 가운데 여호와의 궤 앞으로 들어가 지파 수대로 돌을 하나씩 어깨에 메라고 말했어요. 이것이 표징이 될 것이라고 했어요. 훗날 자손이 이 돌들의 뜻을 물으면, 여호와의 언약궤 앞에서 요단 물이 끊어졌다고 말해 주라고 했어요.","t3":"여호수아는 열두 사람에게, 요단 가운데 여호와의 궤 앞으로 들어가 이스라엘 자손의 지파 수대로 저마다 돌 하나씩을 어깨에 메라고 말했다. 이것이 그들 가운데 표징이 될 것이며, 훗날 자손이 이 돌들의 뜻을 물으면 언약궤가 요단을 건널 때 그 앞에서 요단 물이 끊어졌다고 말해 주라고 했다. 이 돌들이 이스라엘 자손에게 영원한 기념이 될 것이라고 했다."},"ref":"수 4:5-7","open":"수 4:7"},{"ask":{"who":"choeon","text":"길갈에 세운 이 돌들은 무슨 뜻이에요?"},"answer":{"t1":"여호수아는 훗날 자손이 이 돌의 뜻을 물으면, 이스라엘이 마른 땅을 걸어서 이 요단 강을 건넜다고 알려 주라고 말했어요.","t2":"여호수아는 이스라엘 자손에게 말했어요. 훗날 자손이 아버지에게 이 돌이 무슨 뜻이냐고 묻거든, 이스라엘이 마른 땅을 걸어서 이 요단 강을 건넜다고 알려 주라고 했어요.","t3":"여호수아는 이스라엘 자손에게, 훗날 자손이 아버지에게 이 돌이 무슨 뜻이냐고 묻거든 이스라엘이 마른 땅을 걸어서 이 요단 강을 건넜다는 것을 알게 하라고 말했다."},"ref":"수 4:21-22","open":"수 4:22"}]},"today":[{"q":"흐르던 강물이 어떻게 멈출 수 있었어요?","a":{"t1":"제사장들이 물가에 발을 담그자 위에서 흘러내리던 물이 멈추었어요. 여호수아는 여호와께서 요단 물을 마르게 하셨다고 말했어요. 어떻게 멈추었는지는 성경이 더 말하지 않아요.","t2":"궤를 멘 제사장들이 물가에 발을 담그자, 위에서 흘러내리던 물이 그쳐 아주 멀리 아담이라는 성읍 쪽에 쌓였어요. 여호수아는 하나님 여호와께서 요단 물을 마르게 하셨다고 말했어요. 물이 어떤 방법으로 멈추었는지는 성경이 더 말하지 않아요.","t3":"궤를 멘 제사장들이 물가에 발을 담그자 위에서 흘러내리던 물이 그쳐 아주 멀리 사르단 가까이의 아담 읍 쪽에 쌓였고, 염해로 흘러가던 물은 끊어졌다(수 3:15-16). 여호수아는 하나님 여호와께서 요단 물을 마르게 하여 건너게 하셨다고 말했다(수 4:23). 물이 어떤 방법으로 멈추었는지는 성경이 더 말하지 않는다."},"refs":["수 3:15-16","수 4:23"]},{"q":"길갈에 세운 그 돌들은 지금도 남아 있어요?","a":{"t1":"여호수아는 요단에서 가져온 돌 열두 개를 길갈에 세웠어요. 훗날 자손이 그 뜻을 물으면 알려 주라고 했어요. 성경은 여기까지 말해요.","t2":"여호수아는 요단에서 가져온 돌 열두 개를 길갈에 세웠어요. 그리고 훗날 자손이 이 돌이 무슨 뜻이냐고 물으면, 이스라엘이 마른 땅을 걸어 요단을 건넜다고 알려 주라고 했어요. 그 돌들이 지금도 남아 있는지는 이 본문에 적혀 있지 않아요.","t3":"여호수아는 요단에서 가져온 돌 열두 개를 길갈에 세우고(수 4:20), 훗날 자손이 아버지에게 이 돌의 뜻을 묻거든 이스라엘이 마른 땅을 걸어서 요단을 건넜다는 것을 알게 하라고 했다(수 4:21-22). 그 돌들이 오늘 어디에 있는지, 남아 있는지는 이 본문에 적혀 있지 않다."},"refs":["수 4:20-22"]}],"help":{"who":"요단 강가의 이스라엘 백성","steps":[{"kind":"stay","after":0,"title":"언약궤와 멀찍이 떨어져","basis":"수 3:3-4","text":{"t1":"관리들은 언약궤를 따라가되, 가까이 가지 말고 멀찍이 떨어지라고 했어요. 우리도 언약궤에서 멀리 떨어진 곳에서 기다려요.","t2":"관리들은 진을 다니며, 제사장들이 언약궤를 메고 가는 것을 보거든 그 뒤를 따르되 이천 규빗쯤 떨어지고 가까이 가지 말라고 했어요. 우리도 백성처럼 언약궤에서 멀찍이 떨어진 곳에서 기다려요.","t3":"관리들은 진을 두루 다니며, 제사장들이 언약궤를 메는 것을 보거든 자기 곳을 떠나 그 뒤를 따르되 그 사이를 이천 규빗쯤 두고 가까이 가지 말라고 명했다(3:3-4). 탐험대도 백성처럼 언약궤에서 멀찍이 떨어져, 사람들 사이로 들어가지 않고 기다린다."},"wait":"멀찍이 떨어져 기다리기","say":{"who":"hyu","text":"언약궤 가까이는 가지 않아. 멀리서 기다리자."}},{"kind":"do","after":1,"title":"떠날 짐 꾸리기","basis":"수 3:14","text":{"t1":"백성은 요단을 건너려고 곧 장막을 떠나요. 우리는 진 가장자리의 한 집 식구들 곁에서 짐 꾸리는 일을 도와요.","t2":"제사장들이 언약궤를 메고 앞서가면, 백성은 장막을 떠나 멀찍이 그 뒤를 따라가요. 우리는 언약궤에서 멀리 떨어진 진 가장자리의 한 집 식구들 곁에서, 떠날 짐을 꾸리는 일을 도와요.","t3":"백성은 강을 건너려고 곧 장막을 떠나게 된다(3:14). 탐험대는 언약궤와 제사장들에게서 멀리 떨어진 진 가장자리의 한 집 식구들 곁에서, 떠날 짐을 꾸리는 일을 돕는다. 이것은 성경에 적힌 일이 아니라 탐험대 이야기다. 탐험대는 백성과 함께 강을 건너지는 않는다."},"tasks":["짐 보따리 묶기","짐을 들어 건네주기","장막 앞 자리 정리하기"],"done":{"who":"hyu","text":"짐을 다 꾸렸어. 이 집 식구들은 언약궤 뒤를 멀찍이 따라갈 거야."}},{"kind":"watch","after":3,"title":"멀리서 보기 · 강 가운데 선 제사장들","basis":"수 3:17","text":{"t1":"제사장들은 언약궤를 멘 채 강 한가운데 마른 땅에 서 있었어요. 우리는 강바닥으로 내려가지 않고 언덕에서 바라봐요.","t2":"제사장들이 언약궤를 멘 채 강 한가운데의 마른 땅에 흔들림 없이 서 있고, 그동안 백성이 건너가요. 언약궤를 메는 것은 제사장들의 일이에요. 우리는 강바닥으로 내려가지 않고 언덕에서 바라봐요.","t3":"제사장들이 언약궤를 멘 채 강 한가운데의 마른 땅에 흔들림 없이 서 있는 동안, 온 이스라엘이 마른 땅으로 걸어 건너갔다(3:17). 궤를 메는 것은 제사장들의 일이다(3:6, 3:8). 탐험대는 궤에 다가가지 않고 강바닥으로도 내려가지 않은 채 언덕에서 지켜본다."}},{"kind":"watch","after":4,"title":"멀리서 보기 · 열두 사람이 가져온 돌","basis":"수 4:4-5","text":{"t1":"여호수아는 지파마다 한 사람씩 뽑힌 열두 사람에게, 요단 가운데서 돌을 하나씩 가지고 나오라고 했어요. 우리는 돌을 옮기지 않고 바라봐요.","t2":"여호수아는 지파마다 한 사람씩 뽑아 둔 열두 사람을 불러, 요단 가운데로 들어가 돌을 하나씩 어깨에 메라고 했어요. 돌을 메는 것은 그 열두 사람의 일이에요. 우리는 돌에 손대지 않고 언덕에서 바라봐요.","t3":"여호수아는 이스라엘의 지파마다 한 사람씩, 열두 사람을 불러 요단 한가운데로 들어가 여호와의 궤 앞에서 저마다 돌 하나씩을 어깨에 메라고 했다(4:4-5). 돌을 메는 일은 뽑힌 열두 사람의 몫이다. 탐험대는 돌에 손대지 않고 언덕에서 지켜본다."}},{"kind":"ask","after":"gates","title":"물이 끊어진 일은 무슨 뜻이에요?","basis":"수 4:23-24","by":"여호수아","ask":{"who":"onwoo","text":"요단 물이 끊어지고 모두가 마른 땅으로 건넌 이 일은 무슨 뜻이에요?"},"answer":{"t1":"여호수아는 이 일을 훗날 자손에게 알려 주라고 말했어요. 여호와께서 요단 물을 마르게 하신 것은 홍해를 말리신 것과 같았고, 땅의 모든 백성이 여호와의 손이 강하심을 알게 하시려는 것이라고 했어요.","t2":"여호수아는 훗날 자손에게 이렇게 알려 주라고 했어요. 여호와께서 요단 물을 말리셔서 건너게 하신 것이, 홍해를 말리시고 건너게 하신 것과 같았다는 것이에요. 그것은 땅의 모든 백성이 여호와의 손이 강하심을 알게 하고, 이스라엘이 여호와를 길이 경외하게 하시려는 것이라고 했어요.","t3":"여호수아는 이스라엘 자손에게, 훗날 자손이 이 돌들의 뜻을 물을 때 이것을 알게 하라고 말했다. 여호와께서 그들 앞에서 요단 물을 말리셔서 다 건너게 하신 것이, 홍해를 말리시고 건너게 하신 것과 같았다는 것이다. 이는 땅의 모든 백성이 여호와의 손이 강하심을 알게 하고, 그들이 하나님 여호와를 길이 경외하게 하시려는 것이라고 했다."},"read":{"t1":{"type":"find","ref":"수 4:23","prompt":"성경책에서 여호수아 4장 23절을 찾아 읽어 보세요.","confirm":{"prompt":"여호수아는 요단 물을 마르게 하신 일이 무엇과 같았다고 했나요?","options":[{"label":"홍해를 말리신 일","ok":true},{"label":"반석에서 물이 나오게 하신 일","basis":"본문에 없음"},{"label":"쓴 물을 달게 하신 일","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"수 4:23-24","prompt":"성경책에서 여호수아 4장 23절과 24절을 읽어 보세요.","confirm":{"prompt":"여호수아는 여호와께서 요단 물을 마르게 하신 까닭을 무엇이라고 했나요?","options":[{"label":"온 땅의 백성이 여호와의 손이 강하심을 알고, 이스라엘이 여호와를 영원히 경외하게 하시려고","ok":true},{"label":"이스라엘이 싸우지 않고 그 땅을 차지하고, 그 땅 족속들이 스스로 물러가게 하시려고","basis":"본문에 없음"},{"label":"훗날 자손이 돌들의 뜻을 물을 때, 언약궤 앞에서 물이 끊어진 일을 말해 주게 하시려고","basis":"수 4:6-7"}]}},"t3":{"type":"find","refs":["수 3:10","수 4:24"],"prompt":"여호수아 3장 10절과 4장 24절을 함께 찾아 읽어 보자.","confirm":{"prompt":"물이 끊어지기 전에 여호수아가 한 말과 건넌 뒤에 한 말을 이어 읽으면, 이 일로 누가 무엇을 알게 된다고 했는가?","options":[{"label":"이스라엘은 사시는 하나님이 그들 가운데 계셔서 그 땅의 족속들을 쫓아내실 것을 알게 되고, 땅의 모든 백성은 여호와의 손이 강하심을 알게 된다고 했다","ok":true},{"label":"이스라엘은 사시는 하나님이 그들 가운데 계심을 알게 되지만, 다른 백성은 이 일을 듣지도 알지도 못하게 된다고 했다","basis":"본문에 없음"},{"label":"이스라엘은 그 땅의 족속들이 스스로 물러갈 것을 알게 되고, 땅의 모든 백성은 이스라엘 군대가 강하다는 것을 알게 된다고 했다","basis":"본문에 없음"}]}}}}]}},"has3d":true,"epic":true},"OT-19":{"id":"OT-19","era":5,"title":"여리고 성이 무너지다","ref":"수 6:1-27","place":"여리고","review":{"required":true,"topics":["재앙과 심판(수 6:17, 6:21, 6:24, 6:26)","구약 사건의 신약적 의미(히 11:30)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"수 6:1-5","open":"수 6:2","focus":"city","text":{"t1":"여리고는 굳게 닫혀 아무도 드나들지 못했어요. 하나님은 엿새 동안은 날마다 한 번, 일곱째 날에는 일곱 번 성을 돌라고 여호수아에게 말씀하셨어요.","t2":"여리고는 굳게 닫혔고 드나드는 사람이 없었는데, 왜 그랬는지는 1절에 있어요. 하나님은 여호수아에게, 모든 군사가 엿새 동안 날마다 성을 한 번씩 돌고, 일곱째 날에는 일곱 번 돌며 제사장들이 나팔을 불라고 하셨어요. 나팔을 길게 부는 소리가 들릴 때 백성이 큰 소리로 외치면 성벽이 무너져 내릴 것이라고 하셨어요.","t3":"여리고는 이스라엘 자손 때문에 굳게 닫혀서 드나드는 사람이 없었다. 여호와께서는 여호수아에게, 여리고와 그 왕과 용사들을 그의 손에 넘겨주었다고 하셨다. 모든 군사가 성 둘레를 날마다 한 번씩 엿새 동안 돌고, 제사장 일곱이 양각 나팔 일곱을 들고 언약궤 앞에서 가라고 하셨다. 일곱째 날에는 성을 일곱 번 돌며 제사장들이 나팔을 불라고 하셨다. 제사장들이 양각 나팔을 길게 불어 그 소리가 들리면 백성이 다 큰 소리로 외치라고 하셨고, 그러면 성벽이 무너져 내릴 것이라고 하셨다. 그다음 백성이 어떻게 하라고 하셨는지는 5절에 있다."},"say":{"who":"onwoo","text":"하나님이 여호수아에게 하신 말씀은 6장 2절부터 5절에 있어. 성경책에서 직접 읽어 보자."}},{"ref":"수 6:6-11","focus":"march","text":{"t1":"여호수아는 외치라고 할 때까지 아무 말도 하지 말라고 했어요. 나팔을 부는 제사장들과 언약궤가 성을 한 번 돌았고, 무리는 진으로 돌아와 잤어요.","t2":"여호수아는 제사장들에게 언약궤를 메게 하고, 제사장 일곱은 양각 나팔 일곱을 들고 여호와의 궤 앞에서 가게 했어요. 무장한 사람들이 나팔 부는 제사장들보다 앞에 서고, 후군은 궤 뒤를 따랐어요. 여호수아는 백성에게, 외치라고 명하는 날까지 외치지도 말고 입에서 아무 말도 내지 말라고 했어요. 그날 여호와의 궤가 성을 한 번 돌았고, 무리는 진으로 돌아와 잤어요.","t3":"눈의 아들 여호수아는 제사장들을 불러 언약궤를 메게 하고, 제사장 일곱은 양각 나팔 일곱을 들고 여호와의 궤 앞에서 가라고 했다. 백성에게는 나아가 성을 돌되 무장한 사람들이 여호와의 궤보다 앞서 가라고 했다. 여호수아의 말이 끝나자 제사장 일곱이 양각 나팔 일곱을 들고 나팔을 불며 나아갔고, 여호와의 언약궤가 그 뒤를 따랐다. 무장한 사람들은 나팔 부는 제사장들보다 앞에 섰고 후군은 궤 뒤를 따랐으며, 제사장들은 가면서 나팔을 불었다. 여호수아는 백성에게, 자기가 외치라고 명하는 날까지는 외치지도 말고 소리를 들리게 하지도 말며 입에서 아무 말도 내지 말라고 명했다. 이렇게 여호와의 궤가 성을 한 번 돌았고, 무리는 진으로 돌아와 진에서 잤다."},"say":{"who":"hyu","text":"행렬 순서를 적을게. 무장한 사람들, 나팔 부는 제사장 일곱, 언약궤, 그리고 후군이야."}},{"ref":"수 6:12-14","focus":"march","text":{"t1":"다음 날에도 똑같이 성을 한 바퀴 돈 뒤 진으로 돌아왔어요. 엿새 동안 이렇게 했어요.","t2":"여호수아는 아침 일찍 일어났고, 제사장들은 여호와의 궤를 멨어요. 제사장 일곱이 양각 나팔을 불며 궤 앞에서 갔어요. 둘째 날에도 성을 한 번 돌고 진으로 돌아왔고, 엿새 동안 이렇게 했어요.","t3":"여호수아가 아침 일찍 일어났고 제사장들이 여호와의 궤를 멨다. 제사장 일곱은 양각 나팔 일곱을 들고 여호와의 궤 앞에서 계속 나아가며 나팔을 불었고, 무장한 사람들은 그들보다 앞서 가고 후군은 궤 뒤를 따랐다. 둘째 날에도 성을 한 번 돌고 진으로 돌아왔으며, 엿새 동안 이와 같이 했다."},"say":{"who":"choeon","text":"오늘도 제사장들이 나팔을 불면서 성을 돌고 있어."}},{"ref":"수 6:15-19","focus":"joshua","text":{"t1":"일곱째 날에는 새벽부터 성을 일곱 번 돌았어요. 일곱 번째에 나팔이 울리자, 여호수아는 백성에게 외치라고 했어요.","t2":"일곱째 날에는 새벽 일찍 일어나 같은 방식으로 성을 일곱 번 돌았어요. 일곱 번째로 돌 때 제사장들이 나팔을 불었고, 여호수아는 백성에게 외치라고 했어요. 이 성과 그 안의 모든 것은 여호와께 바치되, 라합과 그 집에 함께 있는 사람은 살리라고 했어요. 왜 라합을 살리라고 했는지는 17절에 있어요.","t3":"일곱째 날 새벽에 그들은 일찍 일어나 같은 방식으로 성을 일곱 번 돌았다. 성을 일곱 번 돈 것은 그날뿐이었다. 일곱 번째로 돌 때 제사장들이 나팔을 불자 여호수아는 백성에게 외치라고 했다. 이 성과 그 안에 있는 것은 모두 여호와께 바쳐야 하되, 기생 라합과 그 집에 함께 있는 사람은 모두 살리라고 했는데, 라합이 이스라엘이 보낸 사자들을 숨겼기 때문이라고 했다. 또 바칠 물건을 스스로 삼가라고 하며, 그것을 취하면 이스라엘 진이 바쳐진 것이 되어 화를 당하게 될까 두렵다고 했다. 은과 금, 동과 철 기구는 다 여호와께 구별된 것이니 여호와의 곳간에 들이라고 했다."},"say":{"who":"onwoo","text":"여호수아가 백성에게 한 말은 6장 16절부터 19절에 있어. 성경책에서 확인하자."}},{"ref":"수 6:20","focus":"wall","text":{"t1":"나팔 소리를 들은 백성이 크게 외치자 성벽이 무너져 내렸어요! 그다음 백성이 어떻게 했는지는 성경에서 찾아봐요.","t2":"백성이 외치고 제사장들이 나팔을 불었어요. 나팔 소리를 들은 백성이 크게 소리 질러 외치자 성벽이 무너져 내렸어요. 그다음 백성이 어떻게 했는지는 20절에 있어요.","t3":"백성은 외쳤고 제사장들은 나팔을 불었다. 백성이 나팔 소리를 듣고 크게 소리 질러 외치자 성벽이 무너져 내렸다. 그다음 백성이 어떻게 했는지는 20절에 있다."},"say":{"who":"choeon","text":"성벽이 무너져 내렸어!"}},{"ref":"수 6:21-25","open":"수 6:25","focus":"rahab","text":{"t1":"정탐했던 두 사람은 맹세한 대로 라합과 그 가족을 이끌어 냈어요. 그 가족을 어디에 두었을까요?","t2":"이스라엘은 성 안에 있는 것을 다 멸했어요. 여호수아는 맹세한 대로 라합의 집 사람들을 살리게 했는데, 그 뒤 무슨 일이 어떤 차례로 있었는지는 22절부터 25절까지 읽어 봐요. 무리는 성을 불살랐어요.","t3":"그들은 성 안에 있는 것을 다 멸하되, 남자와 여자, 젊은이와 늙은이, 소와 양과 나귀를 칼날로 멸했다. 여호수아는 그 땅을 정탐한 두 사람에게, 그 여인의 집에 들어가 맹세한 대로 그와 그에게 딸린 모든 것을 이끌어 내라고 했다. 정탐한 젊은이들이 들어가 라합과 그 부모와 형제와 그에게 딸린 모든 것과 친족까지 다 이끌어 냈다. 무리는 성읍과 그 안의 모든 것을 불로 살랐다. 두 사람이 라합의 집 사람들을 어디에 두었는지, 은과 금, 동과 철 기구는 어떻게 했는지는 23절과 24절에 있다. 여호수아가 기생 라합과 그 아버지의 가족과 그에게 딸린 모든 것을 살렸으므로 라합은 이스라엘 가운데 살았는데, 여호수아가 여리고를 살피려고 보낸 사자들을 그가 숨겼기 때문이다."},"say":{"who":"onwoo","text":"이 대목은 성경이 적은 만큼만 읽자. 6장 21절부터 25절이야."}},{"ref":"수 6:26-27","focus":"joshua","text":{"t1":"여호수아는 이 성을 다시 쌓는 사람은 저주를 받을 거라고 맹세하며 경고했어요. 그 뒤 여호수아가 어떻게 되었는지는 성경에서 찾아봐요.","t2":"그때 여호수아는 맹세로 무리에게 경고했어요. 누구든지 일어나 이 여리고 성을 다시 세우는 사람은 여호와 앞에서 저주를 받을 것이라고 했어요. 그 뒤 여호수아의 이름이 그 온 땅에 퍼졌는데, 왜 그랬는지는 27절에 있어요.","t3":"그때 여호수아는 맹세로 무리에게 경고했다. 누구든지 일어나 이 여리고 성을 다시 세우는 사람은 여호와 앞에서 저주를 받아, 기초를 놓을 때 맏아들을 잃고 문을 세울 때 막내아들을 잃을 것이라고 했다. 여호와께서 여호수아와 함께하셨고, 여호수아의 이름이 그 온 땅에 퍼졌다."},"say":{"who":"hyu","text":"여호수아가 맹세로 한 말을 일지에 적어 둘게."}}],"gates":{"t1":[{"type":"find","ref":"수 6:23","prompt":"성경책에서 여호수아 6장 23절을 찾아 읽어 보세요.","confirm":{"prompt":"정탐했던 두 사람은 라합과 그 가족을 이끌어 내어 어디에 두었나요?","options":[{"label":"이스라엘 진 밖","ok":true},{"label":"여리고 성 안","basis":"본문에 없음"},{"label":"요단 강 건너편","basis":"본문에 없음"}]}},{"type":"multi","ref":"수 6:27","prompt":"성경책에서 여호수아 6장 27절을 찾아 읽어 보세요.","confirm":{"prompt":"여리고 이야기의 맨 끝에서 성경은 여호수아에 대해 무엇을 말하나요? 맞는 것을 모두 고르세요.","options":[{"label":"하나님이 여호수아와 함께 계셨어요","ok":true},{"label":"여호수아가 여리고 성을 다시 쌓았어요","basis":"본문에 없음"},{"label":"여호수아의 이름이 온 땅에 퍼졌어요","ok":true},{"label":"여호수아가 해와 달에게 머무르라고 했어요","basis":"수 10:12"},{"label":"백성이 여호수아를 왕으로 세웠어요","basis":"본문에 없음"}]}}],"t2":[{"type":"find","ref":"수 6:16-17","prompt":"성경책에서 여호수아 6장 16절과 17절을 읽어 보세요.","confirm":{"prompt":"여호수아가 라합과 그 집에 함께 있는 사람은 살리라고 한 까닭은 무엇인가요?","options":[{"label":"라합이 이스라엘이 보낸 사자들을 숨겼기 때문에","ok":true},{"label":"라합이 이스라엘에게 성문을 열어 주었기 때문에","basis":"본문에 없음"},{"label":"라합의 집이 성 밖에 있었기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"수 6:22-25","prompt":"성경책에서 여호수아 6장 22절부터 25절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["여호수아가 두 정탐꾼에게 라합의 집에 들어가라고 했다","두 사람이 라합과 가족과 친족을 모두 이끌어 냈다","두 사람이 라합의 식구들을 이스라엘 진 바깥에 두었다","라합이 이스라엘 가운데 살게 되었다"]}],"t3":[{"type":"find","refs":["수 6:17","수 6:23"],"prompt":"여호수아 6장 17절과 23절을 함께 찾아 읽어 보자.","confirm":{"prompt":"라합에 대해 여호수아가 한 말과 두 사람이 한 일을 이어 읽으면 어떠한가?","options":[{"label":"여호수아는 라합과 그 집에 함께 있는 사람은 모두 살리라고 했고, 두 사람은 라합과 그 부모와 형제와 친족까지 다 이끌어 내어 이스라엘 진 밖에 두었다","ok":true},{"label":"여호수아는 라합과 그 집에 함께 있는 사람은 모두 살리라고 했고, 두 사람은 라합의 식구들을 이스라엘 진 한가운데로 데려갔다","basis":"본문에 없음"},{"label":"여호수아는 라합과 그 집에 함께 있는 사람은 모두 살리라고 했고, 두 사람은 라합의 식구들을 성 안의 다른 집에 두었다","basis":"본문에 없음"}]},"inStory":"라합의 집 사람들을 살리라는 말(6:17)과 그들을 이끌어 낸 일은 이야기에 남아 낱말이 겹친다. 보기를 가르는 것은 그들을 둔 곳(6:23 진 밖)이고, 그것은 이야기 글에서 뺐다"},{"type":"match","refs":["수 2:14","수 6:22","수 6:25"],"prompt":"여호수아 2장 14절, 6장 22절, 6장 25절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"수 2:14","text":"두 사람이 라합에게, 이 일을 누설하지 않으면 그 땅을 받을 때 인자와 진실로 대하겠다고 약속했다"},{"ref":"수 6:22","text":"여호수아가 두 사람에게, 맹세한 대로 라합과 그에게 속한 이들을 이끌어 내라고 했다"},{"ref":"수 6:25","text":"라합은 그 뒤로 이스라엘 백성 가운데서 살게 되었다"}],"after":"세 곳을 이으면, 2장에서 두 사람이 한 약속을 6장에서 여호수아가 그 맹세대로 지키게 했고, 라합은 이스라엘 가운데 살게 되었다."}]},"cards":[{"ref":"수 6:20","title":"무너져 내린 성벽"},{"ref":"수 6:27","title":"여호수아와 함께하심"}],"close":{"t1":{"kind":"prayer","text":"하나님, 여리고에서 있었던 일을 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 여호수아 6장 1절부터 16절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"수 6:1-27에서 새로 알게 된 사실을 한 가지 적어 보자."}},"quests":[{"part":"bulb","name":"전구","line":"전구를 찾았어! 성에서 멀찍이 떨어진 땅 위에 있었네.","found":"탐지기가 굳게 닫힌 여리고 성 쪽을 가리켜요.","say":{"who":"hyu","text":"탐지기 바늘이 여리고 성 쪽으로 돌아갔어. 성이 굳게 닫혀 있다고 일지에 적어 둘게."},"q":{"t1":{"type":"find","ref":"수 6:1","prompt":"성경책에서 여호수아 6장 1절을 찾아 읽어 보세요.","confirm":{"prompt":"여리고 성이 굳게 닫혀 드나드는 사람이 없었던 것은 누구 때문이었나요?","options":[{"label":"이스라엘 자손","ok":true},{"label":"애굽 군대","basis":"본문에 없음"},{"label":"블레셋 사람들","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"수 6:1-2","prompt":"성경책에서 여호수아 6장 1절과 2절을 읽어 보세요.","confirm":{"prompt":"여리고가 굳게 닫혀 드나드는 사람이 없었던 까닭은 무엇인가요?","options":[{"label":"이스라엘 자손 때문에","ok":true},{"label":"애굽 군대가 쳐들어왔기 때문에","basis":"본문에 없음"},{"label":"성 안에 큰 잔치가 열렸기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["수 2:7","수 6:1"],"prompt":"여호수아 2장 7절과 6장 1절을 함께 찾아 읽어 보자.","confirm":{"prompt":"정탐꾼을 쫓던 그 밤의 성문과, 이스라엘이 성을 돌기 전의 여리고를 이어 읽으면 어떠한가?","options":[{"label":"2장에서는 쫓는 사람들이 성 밖으로 나간 뒤 성문을 닫았고, 6장에서는 이스라엘 자손 때문에 여리고가 굳게 닫혀 드나드는 사람이 없었다","ok":true},{"label":"2장에서는 쫓는 사람들이 나간 뒤에도 성문을 열어 두었고, 6장에서는 이스라엘 자손 때문에 여리고가 굳게 닫혀 드나드는 사람이 없었다","basis":"본문에 없음"},{"label":"2장에서는 쫓는 사람들이 나가기 전에 성문을 닫아 그들이 나가지 못했고, 6장에서는 이스라엘 자손 때문에 여리고가 굳게 닫혀 드나드는 사람이 없었다","basis":"본문에 없음"}]}}}},{"part":"battery","name":"건전지","line":"건전지가 여기 있었네! 진 가장자리야.","found":"탐지기가 이스라엘 진 쪽을 가리켜요.","say":{"who":"choeon","text":"진에 장막이 아주 많아. 사람들 물건은 가져가지 않을 거야."},"q":{"t1":{"type":"find","ref":"수 6:8","prompt":"성경책에서 여호수아 6장 8절을 찾아 읽어 보세요.","confirm":{"prompt":"성을 돌 때 제사장 일곱 명은 무엇을 불었나요?","options":[{"label":"양각 나팔","ok":true},{"label":"피리","basis":"본문에 없음"},{"label":"은 나팔","basis":"민 10:2"}]}},"t2":{"type":"find","ref":"수 6:26-27","prompt":"성경책에서 여호수아 6장 26절과 27절을 읽어 보세요.","confirm":{"prompt":"여호수아의 이름이 그 온 땅에 퍼진 까닭은 무엇인가요?","options":[{"label":"여호와께서 그와 함께 계셨기 때문에","ok":true},{"label":"여호수아가 라합의 집 사람들을 살렸기 때문에","basis":"수 6:25"},{"label":"여호수아가 백성에게 외치라고 명했기 때문에","basis":"수 6:16"}]}},"t3":{"type":"find","refs":["수 6:19","수 6:24"],"prompt":"여호수아 6장 19절과 24절을 함께 찾아 읽어 보자.","confirm":{"prompt":"은과 금, 동과 철 기구에 대해 여호수아가 한 말과 무리가 한 일을 이어 읽으면 어떠한가?","options":[{"label":"여호수아는 그것들이 여호와께 구별된 것이니 여호와의 곳간에 들이라고 했고, 무리는 성을 불사르면서도 그 기구들만은 따로 여호와의 집 곳간에 들여놓았다","ok":true},{"label":"여호수아는 그것들이 여호와께 구별된 것이니 여호와의 곳간에 들이라고 했지만, 무리는 그 기구들을 저마다 나누어 가졌다","basis":"본문에 없음"},{"label":"여호수아는 그것들이 여호와께 구별된 것이니 여호와의 곳간에 들이라고 했고, 무리는 그 기구들도 성과 함께 모두 불 속에 던져 넣었다","basis":"본문에 없음"}]}}}},{"part":"handle","name":"손잡이","line":"손잡이를 찾았어! 성벽에서 멀찍이 떨어진 곳에 있었네.","found":"탐지기가 여리고 성벽이 보이는 쪽을 가리켜요.","say":{"who":"onwoo","text":"성벽 가까이는 가지 말자. 여기서 보자. 우리는 지켜보는 사람이야."},"q":{"t1":{"type":"find","ref":"수 6:20","prompt":"성경책에서 여호수아 6장 20절을 찾아 읽어 보세요.","confirm":{"prompt":"성벽이 무너져 내린 뒤 백성은 어떻게 했나요?","options":[{"label":"저마다 곧장 성 안으로 들어갔어요","ok":true},{"label":"모두 진으로 돌아갔어요","basis":"수 6:14"},{"label":"성 둘레를 한 번 더 돌았어요","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"수 6:4-5","prompt":"성경책에서 여호수아 6장 4절과 5절을 읽어 보세요.","confirm":{"prompt":"하나님은 성벽이 무너져 내리면 백성이 어떻게 하라고 하셨나요?","options":[{"label":"저마다 앞으로 올라가라고","ok":true},{"label":"제사장들이 언약궤를 메고 먼저 들어가라고","basis":"본문에 없음"},{"label":"여호수아가 들어갈 때까지 기다렸다가 그 뒤를 따르라고","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["수 6:5","수 6:20"],"prompt":"여호수아 6장 5절과 20절을 함께 찾아 읽어 보자.","confirm":{"prompt":"하나님이 여호수아에게 미리 하신 말씀과 일곱째 날의 일을 이어 읽으면, 성벽이 무너진 뒤 백성은 어떻게 했는가?","options":[{"label":"하나님은 성벽이 무너지면 백성이 저마다 앞으로 올라가라고 하셨고, 그 말씀대로 백성은 저마다 곧장 성으로 올라가 그 성을 차지했다","ok":true},{"label":"하나님은 성벽이 무너지면 제사장들이 언약궤를 메고 먼저 들어가라고 하셨고, 백성은 그 뒤를 따라 성에 들어갔다","basis":"본문에 없음"},{"label":"하나님은 성벽이 무너지면 여호수아를 따라 한 줄로 들어가라고 하셨고, 백성은 여호수아의 뒤를 따라 한 줄로 성에 들어갔다","basis":"본문에 없음"}]}}}}],"mission":{"call":{"t1":"최현 박사예요. 이번에는 전구와 건전지와 손잡이가 망가졌어요. 여리고 성에서 멀찍이 떨어진 곳에서 대신 쓸 재료를 찾아봐요.","t2":"최현 박사예요. 여리고 가까이에 비상 착륙하면서 전구와 건전지와 손잡이가 망가졌어요. 이 시대에는 우리 부속이 없으니, 탐지기가 가리키는 곳에서 대신 쓸 재료를 하나씩 찾아야 해요. 성에는 가까이 가지 말고요.","t3":"최현 박사다. 여리고 가까이에 비상 착륙하면서 전구, 건전지, 손잡이가 망가졌고 지금은 통신만 이어져 있다. 이 시대에는 부속이 없으니 탐지기가 가리키는 곳마다, 성에서 멀찍이 떨어진 곳에서 재료를 구해 세 부속을 대신 만들어야 한다."},"materials":[{"key":"sand","name":"고운 모래","basis":"수 6:22","use":"고운 모래를 녹여 만든 작은 유리알을 전구 대신 쓸 수 있어요.","how":"성에는 다가가지 않는다. 여리고 성에서 멀찍이 떨어진 땅 위에서 고운 모래를 한 줌 담는다. 성에서 나온 것은 줍지 않는다.","line":"고운 모래를 한 줌 담았어! 성에서 멀찍이 떨어진 땅 위야."},{"key":"soil","name":"흙 한 줌","basis":"수 6:11","use":"축축한 흙에 타임머신의 쇠붙이 두 개를 꽂아 만든 흙 전지를 건전지 대신 쓸 수 있어요.","how":"진 안으로 들어가지 않고, 진 가장자리 빈 땅에서 흙을 한 줌 떠 담는다. 사람들의 물건은 가져오지 않는다.","line":"흙을 한 줌 담았어! 이스라엘 진 가장자리야."},{"key":"stone","name":"둥근 돌","basis":"수 6:22","use":"손에 꼭 쥐어지는 둥근 돌을 손잡이 대신 쓸 수 있어요.","how":"성벽 쪽으로는 가지 않는다. 성벽이 보이는 곳에서도 멀찍이 떨어져, 진으로 돌아가는 쪽 땅에 박혀 있던 둥근 돌 하나를 줍는다. 성에서 나온 돌은 줍지 않는다.","line":"둥근 돌을 찾았어! 성벽에서 멀찍이 떨어진 곳에 있었네."}],"companion":{"who":"여호수아","ref":"수 6:6","when":"after","talks":[{"ask":{"who":"hyu","text":"성을 도는 동안 백성은 왜 아무 말도 하지 않았어요?"},"answer":{"t1":"여호수아는 백성에게, 외치라고 하는 날까지는 외치지도 말고 입에서 아무 말도 내지 말라고 명했어요. 그날이 되면 외치라고 했어요.","t2":"여호수아는 백성에게, 외치지도 말고 소리를 내지도 말며 입에서 아무 말도 내지 말라고 명했어요. 자기가 외치라고 명하는 날에 외치라고 했어요.","t3":"여호수아는 백성에게, 외치지도 말고 소리를 들리게 하지도 말며 입에서 아무 말도 내지 말라고 명했다. 그러다가 자기가 외치라고 명하는 날에 외치라고 했다."},"ref":"수 6:10","open":"수 6:10"},{"ask":{"who":"onwoo","text":"여리고 성의 물건은 어떻게 하라고 하셨어요?"},"answer":{"t1":"여호수아는 이 성과 그 안의 모든 것은 여호와께 바쳐야 한다고 말했어요. 바칠 물건에 손대지 말라고 했어요.","t2":"여호수아는 이 성과 그 안의 모든 것은 여호와께 바쳐야 한다고 말했어요. 바칠 물건을 스스로 삼가라고 하며, 그것을 가져가면 이스라엘 진이 화를 당하게 될까 두렵다고 했어요. 은과 금, 동과 철 기구는 여호와께 구별된 것이니 여호와의 곳간에 들이라고 했어요.","t3":"여호수아는 이 성과 그 가운데 있는 모든 것은 여호와께 바쳐야 한다고 말했다. 바칠 물건을 스스로 삼가라고 하며, 바친 뒤에 그 가운데 어느 것이든 가져가면 이스라엘 진이 바쳐진 것이 되어 화를 당하게 될까 두렵다고 했다. 은과 금, 동과 철 기구는 다 여호와께 구별된 것이니 여호와의 곳간에 들이라고 했다."},"ref":"수 6:17-19","open":"수 6:18"}]},"today":[{"q":"소리를 지르면 어떻게 성벽이 무너져요?","a":{"t1":"하나님은 백성이 크게 외치면 성벽이 무너져 내릴 것이라고 여호수아에게 말씀하셨어요. 백성이 외치자 성벽이 무너져 내렸어요. 어떻게 무너졌는지는 성경이 더 말하지 않아요.","t2":"하나님은 여호수아에게, 제사장들이 양각 나팔을 길게 불어 그 소리가 들릴 때 백성이 다 크게 외치면 성벽이 무너져 내릴 것이라고 말씀하셨어요. 백성이 나팔 소리를 듣고 크게 외치자 성벽이 무너져 내렸어요. 어떤 방법으로 무너졌는지는 성경이 더 말하지 않아요.","t3":"여호와께서는 여호수아에게, 제사장들이 양각 나팔을 길게 불어 그 소리가 들릴 때 백성이 다 크게 외치면 성벽이 무너져 내릴 것이라고 하셨다(수 6:5). 일곱째 날 여호수아는 외치라고 하면서 여호와께서 이 성을 주셨다고 말했고(수 6:16), 백성이 나팔 소리를 듣고 크게 외치자 성벽이 무너져 내렸다(수 6:20). 성벽이 어떤 방법으로 무너졌는지는 성경이 말하지 않는다."},"refs":["수 6:5","수 6:16","수 6:20"]},{"q":"라합의 집은 성벽 위에 있었는데, 어떻게 되었어요?","a":{"t1":"라합의 집은 성벽 위에 있었어요. 정탐했던 두 사람은 라합의 집에 들어가 라합과 가족을 이끌어 냈어요. 그 집이 어떻게 되었는지는 이 본문에 적혀 있지 않아요.","t2":"라합의 집은 성벽 위에 있었고, 라합은 성벽 위에 살았어요. 여호수아의 말에 따라 정탐했던 두 사람이 라합의 집에 들어가, 라합과 그 부모와 형제와 친족을 이끌어 내어 이스라엘 진 밖에 두었어요. 성벽이 무너질 때 그 집이 어떻게 되었는지는 이 본문에 적혀 있지 않아요.","t3":"라합의 집은 성벽 위에 있어서 라합은 성벽 위에 살았다(수 2:15). 백성이 외치자 성벽이 무너져 내렸고(수 6:20), 정탐한 두 사람은 여호수아의 말대로 라합의 집에 들어가 라합과 그 부모와 형제와 친족까지 다 이끌어 내어 이스라엘 진 밖에 두었다(수 6:22-23). 성벽이 무너질 때 그 집이 어떻게 되었는지는 이 본문에 적혀 있지 않다."},"refs":["수 2:15","수 6:20","수 6:22-23"]}],"help":{"who":"여리고 앞 이스라엘 진의 백성","steps":[{"kind":"watch","after":1,"title":"멀리서 보기 · 성을 도는 행렬","basis":"수 6:8-9","text":{"t1":"무장한 사람들, 나팔을 부는 제사장 일곱, 언약궤, 그 뒤를 따르는 사람들이 차례로 성을 돌아요. 우리는 행렬에 끼지 않고 멀리서 봐요.","t2":"무장한 사람들이 앞서고, 제사장 일곱이 양각 나팔을 불며 가고, 여호와의 언약궤가 그 뒤를 따르고, 후군이 궤 뒤에서 가요. 궤를 메고 나팔을 부는 것은 제사장들의 일이에요. 우리는 행렬에 끼지 않고 성에서 멀리 떨어져 봐요.","t3":"무장한 사람들이 나팔 부는 제사장들보다 앞서 가고, 제사장 일곱이 양각 나팔 일곱을 잡고 불며 나아가며, 여호와의 언약궤가 그 뒤를 따르고 후군이 궤 뒤에서 걸었다(6:8-9). 궤를 메고 나팔을 부는 것은 제사장들의 일이다(6:6). 탐험대는 행렬에 끼어 성을 돌지 않고, 성에서 멀찍이 떨어져 지켜본다."}},{"kind":"do","after":1,"title":"진의 잠자리 펴기","basis":"수 6:11","text":{"t1":"성을 한 바퀴 돈 무리가 진으로 돌아왔어요. 우리는 진 가장자리의 한 집 식구들 곁에서 잠자리를 펴는 일을 도와요.","t2":"그날 성을 한 번 돈 무리는 진으로 돌아와 진에서 잤어요. 우리는 진 가장자리에 머무는 한 집 식구들 곁에서, 밤을 지낼 잠자리를 펴고 짐을 정리하는 일을 도와요.","t3":"그날 무리는 성을 한 번 돈 뒤 진으로 돌아와 진에서 잤다(6:11). 탐험대는 진 가장자리의 한 집 식구들 곁에서 잠자리를 펴고 짐을 정리하는 일을 돕는다. 이것은 성경에 적힌 일이 아니라 탐험대 이야기다. 성을 도는 일과 외치는 일에는 끼지 않는다."},"tasks":["깔개 펴 주기","짐을 한쪽에 모아 두기","장막 앞 자리 쓸기"],"done":{"who":"choeon","text":"잠자리를 다 폈어. 이제 우리도 진 가장자리에서 함께 밤을 보내자."}},{"kind":"stay","after":1,"title":"진 가장자리에서 하룻밤","basis":"수 6:11","text":{"t1":"무리는 진에서 잤어요. 우리도 진 가장자리에서 함께 밤을 지내요.","t2":"그날 여호와의 궤가 성을 한 번 돌았고, 무리는 진으로 돌아와 진에서 잤어요. 우리도 진 가장자리에 머물며 함께 밤을 보내요.","t3":"그날 여호와의 궤가 성을 한 번 돌았고, 무리는 진으로 돌아와 진에서 잤다(6:11). 탐험대도 진 안으로 들어가지 않고 진 가장자리에 머물며 함께 밤을 보낸다."},"wait":"진 가장자리에서 밤 보내기"},{"kind":"watch","after":3,"title":"멀리서 보기 · 일곱째 날의 나팔","basis":"수 6:15-16","text":{"t1":"일곱째 날, 무리가 성을 일곱 번 돌았어요. 제사장들이 나팔을 부는 동안 우리는 함께 외치지 않고 멀리서 봐요.","t2":"일곱째 날 새벽, 무리는 같은 방식으로 성을 일곱 번 돌았어요. 일곱 바퀴째 돌 때 제사장들이 나팔을 불자 여호수아가 백성에게 외치라고 해요. 외치는 것은 백성이 받은 명령이에요. 우리는 함께 외치지 않고 성에서 멀리 떨어져 봐요.","t3":"일곱째 날 새벽에 무리는 일찍 일어나 같은 방식으로 성을 일곱 번 돌았고, 일곱 번 돈 것은 그날뿐이었다(6:15). 일곱 바퀴째 돌 때 제사장들이 나팔을 불자 여호수아가 백성에게 외치라고 했다(6:16). 외치는 것은 백성이 받은 명령이다. 탐험대는 함께 외치지 않고 성에서 멀찍이 떨어져 지켜본다."},"say":{"who":"onwoo","text":"우리는 외치지 않아. 여기서 지켜보기만 하자."}},{"kind":"ask","after":"gates","title":"성이 무너진 일은 무슨 뜻이에요?","basis":"수 6:16","by":"여호수아","ask":{"who":"choeon","text":"여리고 성벽이 무너진 이 일은 무슨 뜻이에요?"},"answer":{"t1":"여호수아는 일곱째 날 백성에게 외치라고 하면서, 여호와께서 이 성을 그들에게 주셨다고 말했어요.","t2":"일곱 번째로 성을 돌 때 제사장들이 나팔을 불자, 여호수아는 백성에게 외치라고 했어요. 그러면서 여호와께서 이 성을 그들에게 주셨다고 말했어요.","t3":"일곱째 날 일곱 번째로 성을 돌며 제사장들이 나팔을 불자, 여호수아는 백성에게 외치라고 하면서 여호와께서 이 성을 그들에게 주셨다고 말했다."},"read":{"t1":{"type":"find","ref":"수 6:16","prompt":"성경책에서 여호수아 6장 16절을 찾아 읽어 보세요.","confirm":{"prompt":"여호수아는 여호와께서 백성에게 무엇을 주셨다고 했나요?","options":[{"label":"이 성 여리고","ok":true},{"label":"많은 양 떼","basis":"본문에 없음"},{"label":"새 장막","basis":"본문에 없음"}]},"inStory":"여리고는 장면의 성 이름이라 어디에나 나온다. 여호와께서 그 성을 주셨다는 여호수아의 말(6:16)은 8~10세 이야기 글에서 뺐다"},"t2":{"type":"find","ref":"수 6:15-16","prompt":"성경책에서 여호수아 6장 15절과 16절을 읽어 보세요.","confirm":{"prompt":"일곱째 날 여호수아가 백성에게 외치라고 한 까닭은 무엇인가요?","options":[{"label":"여호와께서 이 성을 그들에게 주셨기 때문에","ok":true},{"label":"이른 새벽에 성 사람들을 잠에서 깨우려고","basis":"본문에 없음"},{"label":"성 안의 라합에게 붉은 줄을 매어 두라고 알리려고","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["수 6:2","수 6:16"],"prompt":"여호수아 6장 2절과 16절을 함께 찾아 읽어 보자.","confirm":{"prompt":"하나님이 여호수아에게 하신 말씀과 여호수아가 백성에게 한 말을 이어 읽으면 어떠한가?","options":[{"label":"하나님은 여리고 성과 그 왕과 용맹한 군사들을 여호수아의 손에 넘겨주었다고 하셨고, 여호수아는 일곱째 날 백성에게 여호와께서 이 성을 주셨다고 하며 외치라고 했다","ok":true},{"label":"하나님은 여리고 성과 왕과 용사들을 여호수아의 손에 넘겨주었다고 하셨지만, 여호수아는 백성에게 성을 스스로 힘써 빼앗으라고 하며 외치라고 했다","basis":"본문에 없음"},{"label":"하나님은 여리고 왕만 여호수아의 손에 넘겨주었다고 하셨고, 여호수아는 백성에게 왕을 잡으라고 하며 외치라고 했다","basis":"본문에 없음"}]},"inStory":"하나님이 여리고를 넘겨주셨다는 말씀(6:2)은 이야기에 남아 낱말이 겹친다. 보기를 가르는 것은 일곱째 날 여호수아가 외치라며 한 말(6:16)이고, 그것은 이야기 글에서 뺐다"}},"nt":{"ref":"히 11:30","text":"신약의 히브리서 11장 30절은 믿음으로 칠 일 동안 여리고를 두루 돌았을 때 성이 무너졌다고 말한다. 이 연결은 목사님 감수를 마친 뒤 확정한다."}}]}},"has3d":true,"epic":true},"OT-20":{"id":"OT-20","era":5,"title":"세겜에서 언약을 다시 세움","ref":"수 24:1-28","place":"세겜","review":{"required":false,"topics":[],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"수 24:1","focus":"people","text":{"t1":"여호수아는 이스라엘의 모든 지파를 세겜으로 불러 모으고 몇몇 사람들을 따로 불렀는데, 누구였는지는 성경에서 찾아봐요. 그들은 하나님 앞에 나와 섰어요.","t2":"여호수아는 이스라엘의 모든 지파를 세겜에 모으고, 장로들과 우두머리들과 재판장들과 관리들을 불렀어요. 그들은 하나님 앞에 나와 섰어요.","t3":"여호수아가 이스라엘의 모든 지파를 세겜에 모으고, 이스라엘의 장로들과 우두머리들과 재판장들과 관리들을 부르니 그들이 하나님 앞에 나와 섰다."},"say":{"who":"hyu","text":"여기는 세겜이야. 모든 지파가 모였다고 일지에 적어 둘게."}},{"ref":"수 24:2-4","open":"수 24:2-4","focus":"joshua","text":{"t1":"여호수아는 하나님의 말씀을 전했어요. 옛 조상들은 강 저편에서 다른 신들을 섬겼는데, 하나님이 아브라함에게 하신 일은 3절에서 찾아봐요.","t2":"여호수아는 이스라엘의 하나님 여호와의 말씀을 모든 백성에게 전했어요. 하나님은 옛날에 그들의 조상 데라가 강 저편에 살며 다른 신들을 섬겼다고 하셨어요. 하나님은 강 저편에 있던 아브라함을 데리고 나와 가나안 땅으로 이끄시고 이삭을 주셨다고 하셨어요. 이삭에게는 야곱과 에서를 주셨고, 야곱과 그 자손은 애굽으로 내려갔다고 하셨어요.","t3":"여호수아는 모든 백성에게 이스라엘의 하나님 여호와의 말씀을 전했다. 옛적에 그들의 조상이 강 저편에 살며 다른 신들을 섬겼다고 하셨는데, 그 조상이 누구였는지는 2절에 있다. 하나님은 강 저편에 있던 그들의 조상 아브라함을 데리고 나와 가나안으로 이끄시고 그 온 땅을 두루 다니게 하셨으며, 그 자손을 번성하게 하시려고 이삭을 주셨다고 하셨다. 이삭에게는 야곱과 에서를 주셨고, 에서에게는 세일 산을 소유로 주셨으며, 야곱과 그 자손들은 애굽으로 내려갔다고 하셨다."},"say":{"who":"onwoo","text":"여호수아가 전하는 하나님의 말씀이야. 24장 2절부터 성경책에서 직접 읽어 보자."}},{"ref":"수 24:5-7","open":"수 24:5-7","focus":"joshua","text":{"t1":"하나님은 모세와 아론을 보내 조상들을 애굽에서 이끌어 내셨다고 하셨어요. 뒤쫓던 애굽 사람들은 바다로 덮으셨다고 하셨어요.","t2":"하나님은 모세와 아론을 보내시고 애굽에 재앙을 내리신 뒤에 조상들을 인도해 내셨다고 하셨어요. 그 뒤 홍해에서 무슨 일이 어떤 차례로 있었는지는 6절과 7절에서 읽어 봐요.","t3":"하나님은 모세와 아론을 보내셨고 애굽에 재앙을 내리셨으며, 그 뒤에 그들을 인도해 내셨다고 하셨다. 조상들을 애굽에서 인도해 내어 바다에 이르게 하셨을 때 애굽 사람들이 병거와 마병을 거느리고 홍해까지 뒤쫓았다고 하셨다. 조상들이 여호와께 부르짖자, 하나님이 그들과 애굽 사람들 사이에 흑암을 두시고 바다를 끌어다가 애굽 사람들을 덮으셨다고 하셨다. 하나님이 애굽에서 하신 일을 그들이 눈으로 보았고, 그 뒤 여러 날을 광야에서 지냈다고 하셨다."},"say":{"who":"choeon","text":"우리가 본 홍해 이야기가 나와!"}},{"ref":"수 24:8-13","open":"수 24:11-13","focus":"joshua","text":{"t1":"하나님은 왕벌을 보내 두 아모리 왕을 쫓아내셨고, 그것은 백성의 칼이나 활로 된 일이 아니라고 하셨어요. 수고하지 않은 땅과 짓지 않은 성읍도 주셨다고 하셨어요.","t2":"하나님은 그들을 요단 저편 아모리 사람의 땅으로 인도하여 그 땅을 차지하게 하셨다고 하셨어요. 요단을 건너 여리고에 이르렀을 때에도 싸우러 나온 사람들을 그들의 손에 넘겨주셨다고 하셨어요. 왕벌을 보내어 아모리 사람의 두 왕을 쫓아내신 것은 그들의 칼이나 활로 된 일이 아니라고 하셨어요. 그들이 수고하지 않은 땅과 짓지 않은 성읍을 주셨다고 하셨어요.","t3":"하나님은 그들을 요단 저편에 사는 아모리 사람의 땅으로 인도하셨고, 아모리 사람이 싸우러 나오자 그들의 손에 넘겨주어 그 땅을 차지하게 하셨으며, 아모리 사람을 그들 앞에서 멸하셨다고 하셨다. 모압 왕 십볼의 아들 발락이 이스라엘을 대적하여 브올의 아들 발람을 불러 저주하게 하려 했으나, 하나님이 발람의 말을 들으려 하지 않으셨으므로 발람이 오히려 축복했고 하나님이 그들을 그의 손에서 건져 내셨다고 하셨다. 요단을 건너 여리고에 이르렀을 때에는 여리고 사람과 아모리, 브리스, 가나안, 헷, 기르가스, 히위, 여부스 사람이 싸우러 나왔으나 그들의 손에 넘겨주셨다고 하셨다. 왕벌을 앞서 보내어 아모리 사람의 두 왕을 쫓아내셨으니 그들의 칼이나 활로 한 일이 아니라고 하셨다. 또 그들이 수고하지 않은 땅과 짓지 않은 성읍을 주셔서 그 가운데 살게 하셨고, 심지 않은 포도원과 감람원의 열매를 먹게 하셨다고 하셨다."},"say":{"who":"hyu","text":"요단 저편, 그다음 요단을 건너 여리고. 지나온 곳을 순서대로 적어 둘게."}},{"ref":"수 24:14-15","focus":"joshua","text":{"t1":"여호수아는 백성에게 여호와만 섬기라고 하며, 섬길 이를 오늘 택하라고 했어요. 자기와 자기 집이 섬길 분은 여호와라고 말했어요.","t2":"여호수아는 백성에게 여호와를 경외하며 섬기라고 했어요. 조상들이 강 저편과 애굽에서 섬기던 신들을 치워 버리고 여호와만 섬기라고 했어요. 누구를 섬길지 오늘 택하라고 하면서, 자기와 자기 집은 여호와를 섬기겠다고 말했어요.","t3":"여호수아는 그러므로 이제 여호와를 경외하며 성실하고 진실하게 그분을 섬기라고 했다. 조상들이 강 저편과 애굽에서 섬기던 신들을 치워 버리고 여호와만 섬기라고 했다. 여호와를 섬기는 것이 좋지 않게 보이면 백성이 어떻게 하라고 했는지, 그리고 자기와 자기 집에 대해 무엇이라고 했는지는 15절에 있다."},"say":{"who":"onwoo","text":"여호수아가 자기와 자기 집에 대해 한 말은 24장 15절에 있어. 성경책에서 확인해 보자."}},{"ref":"수 24:16-24","focus":"people","text":{"t1":"백성은 다른 신들을 섬기려고 여호와를 떠나는 일은 결코 없을 거라고 대답했어요. 애굽에서 자기들을 이끌어 내신 여호와를 섬기겠다고 거듭 말했어요.","t2":"백성은 여호와를 버리고 다른 신들을 섬기는 일은 결코 하지 않겠다고 대답했어요. 백성이 왜 그렇게 대답했는지는 17절과 18절에 있어요. 여호수아는 여호와가 거룩하시고 질투하시는 하나님이시니 백성이 여호와를 능히 섬기지 못할 것이라고 했어요. 백성은 아니라고 하며 반드시 여호와를 섬기겠다고 했고, 여호수아는 백성이 스스로 증인이 되었다고 말했어요.","t3":"백성은 여호와를 버리고 다른 신들을 섬기는 일은 결코 하지 않겠다고 대답했다. 여호와께서 자기들과 조상들을 애굽 땅 종 되었던 집에서 인도해 내시고, 눈앞에서 큰 이적들을 행하시며, 지나온 모든 길과 모든 백성 가운데서 지켜 주셨고, 그 땅에 살던 아모리 사람을 쫓아내셨다는 것이 그 까닭이었다. 그러므로 자기들도 여호와를 섬기겠다고 했다. 여호수아는 그들이 여호와를 능히 섬기지 못할 것이라고 했는데, 여호와는 거룩하신 하나님, 질투하시는 하나님이셔서 그들의 허물과 죄를 용서하지 않으실 것이기 때문이라고 했다. 여호와를 버리고 이방 신들을 섬기면, 복을 내리신 뒤에라도 돌이켜 화를 내리시고 멸하실 것이라고 했다. 백성은 아니라고 하며 반드시 여호와를 섬기겠다고 했다. 여호수아가 그들이 여호와를 택하여 섬기겠다고 했으니 스스로 증인이 되었다고 하자, 그들은 자기들이 증인이라고 대답했다. 여호수아는 그들 가운데 있는 이방 신들을 치워 버리고 이스라엘의 하나님 여호와께로 마음을 돌리라고 했고, 백성은 하나님 여호와를 섬기고 그 목소리를 따르겠다고 했다."},"say":{"who":"choeon","text":"백성이 여호와를 섬기겠다고 여러 번 대답했어."}},{"ref":"수 24:25-28","focus":"stone","text":{"t1":"그날 여호수아는 세겜에서 백성과 언약을 세우고, 상수리나무 아래에 큰 돌을 세웠어요. 이 돌이 무엇이 될 거라고 했는지는 27절에 있어요.","t2":"그날 여호수아는 세겜에서 백성과 언약을 세우고, 그들을 위해 율례와 법도를 정해 주었어요. 이 모든 말씀을 하나님의 율법 책에 적고, 큰 돌을 가져다가 여호와의 성소 곁, 상수리나무 아래에 세웠어요. 여호수아는 이 돌이 증거가 될 것이라고 말했어요. 그리고 백성을 저마다 자기 기업으로 돌려보냈어요.","t3":"그날 여호수아는 세겜에서 백성과 언약을 세우고 그들을 위해 율례와 법도를 정해 주었다. 여호수아는 이 모든 말씀을 하나님의 율법 책에 적고, 큰 돌을 가져다가 여호와의 성소 곁, 상수리나무 아래에 세웠다. 그가 모든 백성에게 이 돌을 두고 한 말은 27절에서 직접 읽어 보자. 그러고 나서 백성을 저마다 자기 기업으로 돌려보냈다."},"say":{"who":"choeon","text":"상수리나무 아래에 큰 돌이 세워졌어."}}],"gates":{"t1":[{"type":"find","ref":"수 24:1","prompt":"성경책에서 여호수아 24장 1절을 찾아 읽어 보세요.","confirm":{"prompt":"여호수아는 이스라엘의 모든 지파를 모으고, 또 누구를 불렀나요?","options":[{"label":"장로들과 우두머리들과 재판장들과 관리들","ok":true},{"label":"제사장들과 레위 사람들과 노래하는 사람들","basis":"본문에 없음"},{"label":"이웃 나라에서 온 왕들과 사신들","basis":"본문에 없음"}]}},{"type":"multi","ref":"수 24:3","prompt":"성경책에서 여호수아 24장 3절을 찾아 읽어 보세요.","confirm":{"prompt":"여호수아가 전한 하나님의 말씀에서, 하나님이 아브라함에게 하셨다고 한 일을 모두 고르세요.","options":[{"label":"강 건너편에서 데리고 나오셨어요","ok":true},{"label":"이름을 아브람에서 아브라함으로 바꾸어 주셨어요","basis":"창 17:5"},{"label":"가나안 땅으로 이끄셨어요","ok":true},{"label":"아들 이삭을 주셨어요","ok":true},{"label":"왕의 자리에 앉히셨어요","basis":"본문에 없음"}]}}],"t2":[{"type":"find","ref":"수 24:16-18","prompt":"성경책에서 여호수아 24장 16절부터 18절까지 읽어 보세요.","confirm":{"prompt":"백성이 다른 신들을 섬기지 않고 여호와를 떠나지 않겠다고 한 까닭은 무엇인가요?","options":[{"label":"여호와께서 자기들과 조상들을 애굽에서 이끌어 내시고, 지나온 길에서 지키시고, 그 땅의 아모리 사람을 쫓아내셨기 때문에","ok":true},{"label":"다른 신들을 섬기면 복을 주신 뒤에라도 돌이켜 화를 내리고 멸하실 것이라는 여호수아의 말을 들었기 때문에","basis":"수 24:20"},{"label":"여호와께서 조상 아브라함을 강 건너편에서 데리고 나오시고, 가나안 온 땅을 두루 다니게 하시고, 이삭을 주셨기 때문에","basis":"수 24:3"}]}},{"type":"order","ref":"수 24:5-7","prompt":"성경책에서 여호수아 24장 5절부터 7절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["하나님이 모세와 아론을 애굽에 보내셨다","애굽 사람들이 병거와 마병을 이끌고 홍해까지 뒤쫓았다","조상들이 여호와께 부르짖었다","하나님이 바다로 애굽 사람들을 덮으셨다","백성이 여러 날 광야에서 살았다"]}],"t3":[{"type":"find","refs":["수 24:2","수 24:15"],"prompt":"여호수아 24장 2절과 15절을 함께 찾아 읽어 보자.","confirm":{"prompt":"옛 조상의 일과 여호수아가 한 말을 이어 읽으면, 강 저편에서 다른 신들을 섬긴 조상은 누구이고 여호수아는 백성에게 무엇을 하라고 했는가?","options":[{"label":"조상 데라는 강 저편에서 다른 신들을 섬겼는데, 여호수아는 백성에게 섬길 이를 오늘 택하라고 하며 자기와 자기 집이 섬길 분은 여호와라고 했다","ok":true},{"label":"두 곳 어디에도 그 조상의 이름은 나오지 않고, 여호수아는 백성에게 섬길 이를 오늘 택하라고 했다","basis":"본문에 없음"},{"label":"조상 데라는 강 저편에서 다른 신들을 섬겼는데, 여호수아는 백성이 택할 수 없다고 하며 자기가 대신 정하겠다고 했다","basis":"본문에 없음"}]}},{"type":"match","refs":["수 24:16","수 24:21","수 24:24"],"prompt":"여호수아 24장 16절, 21절, 24절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"수 24:16","text":"백성이 다른 신들을 섬기려고 여호와를 떠나는 일은 결코 없을 것이라고 했다"},{"ref":"수 24:21","text":"백성이 아니라고 하며, 자기들은 반드시 여호와를 섬기겠다고 했다"},{"ref":"수 24:24","text":"백성이 여호와를 섬기고 그 목소리에 귀 기울이겠다고 했다"}],"after":"세 곳을 이으면, 백성은 여호수아의 말에 거듭 여호와를 섬기겠다고 대답했다."}]},"cards":[{"ref":"수 24:15","title":"나와 내 집은"},{"ref":"수 24:27","title":"증거가 된 돌"}],"close":{"t1":{"kind":"prayer","text":"하나님, 세겜에서 백성이 한 대답을 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 여호수아 24장 14절부터 18절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"수 24:1-28에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 타임머신의 회전축 하나가 부러졌어요. 세겜 가까이에서 단단하고 곧은 재료를 찾아봐요.","t2":"최현 박사예요. 세겜 가까이에 비상 착륙하면서 회전축 하나가 부러졌어요. 이 시대에는 우리 부속이 없으니, 회전축 대신 쓸 단단하고 곧은 재료를 찾아야 해요.","t3":"최현 박사다. 세겜 가까이에 비상 착륙하면서 회전축이 부러졌고 지금은 통신만 이어져 있다. 이 시대에는 부속이 없으니 단단하고 곧은 재료를 구해 회전축을 대신 만들어야 한다."},"materials":[{"key":"olive","name":"감람나무 마른 가지","basis":"수 24:13","use":"단단한 감람나무 가지를 부러진 회전축 대신 쓸 수 있어요.","how":"모인 백성 사이와 큰 돌, 상수리나무가 있는 곳으로는 가지 않는다. 세겜 가까운 감람원 가장자리 땅에 떨어져 있는 마른 가지 하나를 줍는다. 나무에서 꺾지 않는다.","line":"감람나무 마른 가지를 주웠어! 감람원 가장자리 땅에 떨어져 있었네."}],"companion":{"who":"여호수아","ref":"수 24:1","when":"after","talks":[{"ask":{"who":"choeon","text":"하나님이 이스라엘에게 무엇을 주셨다고 전하셨어요?"},"answer":{"t1":"여호수아는, 하나님이 이스라엘에게 그들이 수고하지 않은 땅과 짓지 않은 성읍을 주셨다고 말씀하셨다고 전했어요.","t2":"여호수아는, 하나님이 이스라엘에게 그들이 수고하지 않은 땅과 짓지 않은 성읍을 주셔서 그 가운데 살게 하셨다고 말씀하셨다고 전했어요. 심지 않은 포도원과 감람원의 열매도 먹게 하셨다고 말씀하셨다고 했어요.","t3":"여호수아는 이스라엘의 하나님 여호와의 말씀을 전했다. 하나님은 그들이 수고하지 않은 땅과 세우지 않은 성읍을 주셔서 그 가운데 살게 하셨고, 심지 않은 포도원과 감람원의 열매를 먹게 하셨다고 말씀하셨다."},"ref":"수 24:13","open":"수 24:13"},{"ask":{"who":"onwoo","text":"여호와를 어떻게 섬기라고 하셨어요?"},"answer":{"t1":"여호수아는 여호와를 경외하고, 성실하고 진실하게 섬기라고 말했어요. 조상들이 섬기던 신들을 치워 버리고 여호와만 섬기라고 했어요.","t2":"여호수아는 여호와를 경외하고, 성실하고 진실하게 그분을 섬기라고 말했어요. 강 저편과 애굽에서 조상들이 섬기던 신들을 치워 버리고 여호와만 섬기라고 했어요.","t3":"여호수아는 그러므로 이제 여호와를 경외하고, 성실하고 진실하게 그분을 섬기라고 말했다. 강 저편과 애굽에서 조상들이 섬기던 신들을 치워 버리고 여호와만 섬기라고 했다."},"ref":"수 24:14","open":"수 24:14"},{"ask":{"who":"hyu","text":"누구를 섬기겠다고 하셨어요?"},"answer":{"t1":"여호수아는 자기와 자기 집은 여호와를 섬기겠다고 말했어요.","t2":"여호수아는 백성에게, 여호와를 섬기는 것이 좋지 않게 보이면 섬길 이를 오늘 택하라고 말했어요. 그리고 자기와 자기 집은 여호와를 섬기겠다고 했어요.","t3":"여호수아는 백성에게, 여호와를 섬기는 것이 좋지 않게 보이거든 조상들이 강 저편에서 섬기던 신들이든 지금 사는 땅 아모리 사람의 신들이든 섬길 이를 오늘 택하라고 말했다. 그리고 자기와 자기 집은 여호와를 섬기겠다고 했다."},"ref":"수 24:15","open":"수 24:15"}]},"today":[{"q":"백성은 그 약속을 지켰어요?","a":{"t1":"여호수아가 살아 있는 동안, 그리고 그 뒤에 남은 장로들이 사는 동안 이스라엘은 여호와를 섬겼어요. 그 뒤에 자란 다른 세대는 여호와를 알지 못했다고 사사기에 적혀 있어요.","t2":"여호수아서는 여호수아가 살아 있는 동안과, 여호수아 뒤에 살아남아 여호와께서 이스라엘을 위해 하신 일을 아는 장로들이 사는 동안 이스라엘이 여호와를 섬겼다고 적어요. 사사기는 그 세대가 다 세상을 떠난 뒤에 일어난 다른 세대가 여호와를 알지 못했고, 이스라엘 자손이 바알들을 섬겼다고 적어요.","t3":"여호수아서는 이스라엘이 여호수아가 사는 날 동안과, 여호수아 뒤에 살아남아 여호와께서 이스라엘을 위해 하신 모든 일을 아는 장로들이 사는 날 동안 여호와를 섬겼다고 적는다(수 24:31). 사사기는 그 세대가 다 조상에게로 돌아간 뒤에 일어난 다른 세대가 여호와와 그분이 이스라엘을 위해 하신 일을 알지 못했고, 이스라엘 자손이 여호와 앞에서 악을 행하여 바알들을 섬겼다고 적는다(삿 2:10-11)."},"refs":["수 24:31","삿 2:10-11"]}],"help":{"who":"세겜에 모인 이스라엘 백성","steps":[{"kind":"stay","after":0,"title":"모인 백성 가장자리에서","basis":"수 24:1-2","text":{"t1":"이스라엘의 모든 지파가 세겜에 모여 하나님 앞에 섰어요. 우리는 사람들 사이로 들어가지 않고 가장자리에서 함께 들어요.","t2":"여호수아가 이스라엘의 지파들을 모두 세겜에 불러 모으고, 장로들과 우두머리들과 재판장들과 관리들을 불렀어요. 그들이 하나님 앞에 나와 섰어요. 우리는 사람들 사이로 들어가지 않고 가장자리에 머물며 함께 들어요.","t3":"여호수아가 이스라엘의 지파들을 모두 세겜에 불러 모으고 장로와 우두머리와 재판장과 관리들을 부르자, 그들이 하나님 앞에 나와 섰다(24:1). 여호수아가 온 백성에게 말하기 시작했다(24:2). 탐험대는 백성 사이로 들어가지 않고 가장자리에 머물며 함께 듣는다. 백성이 대답할 때에도 함께 대답하지 않는다."},"wait":"가장자리에서 함께 듣기","say":{"who":"onwoo","text":"백성이 대답할 때 우리는 함께 대답하지 않고 듣기만 하자."}},{"kind":"watch","after":6,"title":"곁에서 보기 · 율법 책과 큰 돌","basis":"수 24:25-26","text":{"t1":"여호수아는 하나님의 율법 책에 이 말씀을 모두 적고, 큰 돌을 상수리나무 아래에 세웠어요. 우리는 책과 돌에 손대지 않고 바라봐요.","t2":"그날 여호수아는 세겜에서 백성과 언약을 세웠어요. 하나님의 율법 책에 이 말씀을 모두 적고, 큰 돌을 가져다가 여호와의 성소 곁 상수리나무 아래에 세웠어요. 그것은 여호수아가 한 일이에요. 우리는 책과 돌에 손대지 않고 바라봐요.","t3":"그날 여호수아는 세겜에서 백성과 언약을 세우고 율례와 법도를 정해 주었다(24:25). 그리고 하나님의 율법 책에 이 말씀을 모두 적고, 큰 돌을 가져다가 여호와의 성소 곁, 상수리나무 밑에 세웠다(24:26). 이것은 여호수아가 한 일이다. 탐험대는 책과 돌에 손대지 않고 바라본다."}},{"kind":"do","after":6,"title":"돌아가는 짐 나르기","basis":"수 24:28","text":{"t1":"여호수아는 백성을 저마다 자기 땅으로 돌려보냈어요. 우리는 돌아가는 한 집 식구들 곁에서 짐을 나르는 일을 도와요.","t2":"여호수아는 백성을 저마다 자기가 받은 땅으로 돌려보냈어요. 우리는 큰 돌과 상수리나무에서 떨어진 가장자리에서, 돌아가는 한 집 식구들의 짐을 나르는 일을 도와요.","t3":"여호수아는 백성을 저마다 받은 기업으로 돌려보냈다(24:28). 탐험대는 큰 돌과 상수리나무에서 떨어진 가장자리에서, 돌아갈 채비를 하는 한 집 식구들의 짐을 함께 나른다. 이것은 성경에 적힌 일이 아니라 탐험대 이야기다."},"tasks":["짐 보따리 들어 주기","길 비켜 주기","앉았던 자리 정리하기"],"done":{"who":"onwoo","text":"다 도왔어. 사람들이 저마다 자기 땅으로 돌아가고 있어."}},{"kind":"ask","after":"gates","title":"이 큰 돌은 무슨 뜻이에요?","basis":"수 24:27","by":"여호수아","ask":{"who":"hyu","text":"상수리나무 아래 세운 이 큰 돌은 무슨 뜻이에요?"},"answer":{"t1":"여호수아는 모든 백성에게, 이 돌이 여호와께서 하신 모든 말씀을 들었으니 증거가 될 것이라고 말했어요. 백성이 하나님을 배반하지 않게 하는 증거라고 했어요.","t2":"여호수아는 모든 백성에게 말했어요. 여호와께서 백성에게 하신 말씀을 이 돌이 다 들었으니, 이 돌이 증거가 될 것이라고요. 그래서 이 돌이, 백성이 자기 하나님을 배반하지 않게 하는 증거가 될 것이라고 했어요.","t3":"여호수아는 모든 백성에게, 여호와께서 백성에게 하신 말씀을 이 돌이 다 들었으니 이 돌이 그들에게 증거가 되리라고 말했다. 그러므로 이 돌이, 그들이 자기 하나님을 배반하지 않게 하는 증거가 되리라고 했다."},"read":{"t1":{"type":"find","ref":"수 24:27","prompt":"성경책에서 여호수아 24장 27절을 찾아 읽어 보세요.","confirm":{"prompt":"여호수아는 이 돌이 무엇이 될 것이라고 했나요?","options":[{"label":"증거","ok":true},{"label":"길을 알려 주는 표지","basis":"본문에 없음"},{"label":"왕의 무덤","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"수 24:26-27","prompt":"성경책에서 여호수아 24장 26절과 27절을 읽어 보세요.","confirm":{"prompt":"여호수아가 이 돌이 증거가 될 것이라고 한 까닭은 무엇인가요?","options":[{"label":"여호와께서 백성에게 하신 말씀을 이 돌이 다 들었기 때문에","ok":true},{"label":"여호수아가 그 돌에 모세의 율법을 새겨 써 넣었기 때문에","basis":"수 8:32"},{"label":"그 돌이 요단 가운데서 가져온 열두 돌 가운데 하나였기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["수 24:22","수 24:27"],"prompt":"여호수아 24장 22절과 27절을 함께 찾아 읽어 보자.","confirm":{"prompt":"증인과 증거를 말하는 두 곳을 이어 읽으면, 이날의 언약에는 무엇이 증인과 증거가 되었는가?","options":[{"label":"백성은 여호와를 택해 섬기겠다고 했으므로 자기들이 증인이라고 대답했고, 여호수아는 이 돌도 백성이 하나님을 배반하지 않게 하는 증거가 되리라고 했다","ok":true},{"label":"백성은 여호와를 택해 섬기겠다고 했으므로 자기들이 증인이라고 대답했고, 여호수아는 상수리나무도 그 모든 말을 들었으니 증거가 되리라고 했다","basis":"본문에 없음"},{"label":"백성은 여호와를 택해 섬기겠다고 했으므로 자기들이 증인이라고 대답했고, 여호수아는 율법 책에 적은 말씀이 백성에게 증거가 되리라고 했다","basis":"본문에 없음"}]}}}}]}},"has3d":false,"epic":false},"OT-21":{"id":"OT-21","era":6,"title":"기드온과 미디안 군대","ref":"삿 6:11-16","place":"오브라, 이스라엘의 진과 미디안의 진","review":{"required":false,"topics":[],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"삿 6:11-12","open":"삿 6:12","focus":"gideon","text":{"t1":"기드온은 미디안 사람들 몰래 포도주 틀에서 밀을 떨고 있었어요. 그때 여호와의 사자가 나타나, 여호와께서 기드온과 함께 계신다고 말했어요.","t2":"오브라의 상수리나무 아래에 여호와의 사자가 와서 앉았어요. 요아스의 아들 기드온은 포도주 틀에서 밀을 타작하고 있었는데, 왜 하필 그곳이었는지는 11절에서 찾아봐요. 여호와의 사자는 기드온에게 나타나 그를 큰 용사라 부르며, 여호와께서 함께 계신다고 말했어요.","t3":"아비에셀 사람 요아스에게 딸린 오브라에 여호와의 사자가 와서 상수리나무 아래 앉았다. 요아스의 아들 기드온은 미디안 사람의 눈을 피해 포도주 틀에서 밀을 타작하던 참이었다. 여호와의 사자는 그에게 나타나 그를 큰 용사라 불렀다. 사자가 이어서 한 말은 12절에서 직접 읽어 보자."},"say":{"who":"hyu","text":"오브라는 기드온이 포도주 틀에서 밀을 떨던 곳이야. 일지에 적어 둘게."}},{"ref":"삿 6:13-16","open":"삿 6:16","focus":"gideon","text":{"t1":"하나님은 기드온에게 가서 이스라엘을 구하라고 하셨어요. 기드온이 자기는 가장 작은 사람이라고 하자, 하나님은 반드시 함께하겠다고 하셨어요.","t2":"기드온과 여호와께서 여러 번 말을 주고받았어요. 여호와께서는 기드온을 보내 미디안의 손에서 이스라엘을 구하게 하셨어요. 둘이 무슨 말을 어떤 차례로 주고받았는지는 13절부터 16절까지 읽어 봐요.","t3":"기드온은 여호와께서 함께 계시다면 어째서 이 모든 일이 닥쳤으며, 조상들이 들려준 애굽에서 나오게 하신 기적들은 어디 있느냐고 물었다. 지금은 여호와께서 자기들을 버려 미디안의 손에 넘기셨다고도 했다. 여호와께서는 그를 향하여, 그가 가진 힘으로 가서 미디안의 손에서 이스라엘을 구하라고 하시고 자신이 그를 보낸 것이 아니냐고 하셨다. 기드온이 자기 집안은 므낫세 가운데 가장 약하고 자신은 아버지 집에서 가장 작은 사람이라고 하자, 여호와께서 다시 대답하셨다. 그 대답은 16절에 있다."},"say":{"who":"onwoo","text":"기드온의 말에 하나님이 어떻게 대답하셨는지, 16절에서 직접 읽어 보자."}},{"ref":"삿 7:1-3","open":"삿 7:2","focus":"spring","text":{"t1":"기드온과 백성은 어느 샘 곁에 진을 쳤어요. 하나님이 사람이 너무 많다고 하셔서, 두려워하는 사람들은 돌아가고 만 명이 남았어요.","t2":"기드온과 그를 따르는 백성은 일찍 일어나 하롯 샘 곁에 진을 쳤어요. 미디안의 진은 북쪽 모레 산 앞 골짜기에 있었어요. 여호와께서는 백성이 너무 많다고 하셨는데, 그 까닭은 7장 2절에서 찾아봐요. 두려워 떠는 사람은 돌아가라고 알리자 이만 이천 명이 돌아가고 만 명이 남았어요.","t3":"여룹바알이라고도 하는 기드온과 그를 따르는 온 백성이 일찍 일어나 하롯 샘 곁에 진을 쳤다. 여호와께서는 기드온을 따르는 백성이 너무 많아서 미디안 사람을 그들의 손에 넘겨주지 않겠다고 하셨다. 이스라엘이 제 손으로 자기를 구원했다고 여호와를 거슬러 스스로 자랑할까 해서였다. 두려워 떠는 사람은 길르앗 산을 떠나 돌아가라고 백성에게 알리게 하시니, 많은 사람이 돌아갔다."},"say":{"who":"hyu","text":"돌아간 사람과 남은 사람이 몇 명인지 3절에서 찾아서 일지에 적자."}},{"ref":"삿 7:4-8","open":"삿 7:7","focus":"water","text":{"t1":"하나님은 물가에서 사람들을 시험하시고, 손으로 물을 떠서 핥은 사람들로 이스라엘을 구하겠다고 하셨어요. 몇 명이었는지는 성경에서 찾아봐요.","t2":"여호와께서는 기드온에게 백성을 물가로 데리고 내려가게 하셨어요. 왜 그러셨는지는 4절에 있어요. 손으로 물을 떠 입에 대고 핥아 마신 사람은 삼백 명이었고, 나머지는 모두 무릎을 꿇고 마셨어요. 기드온은 그 삼백 명만 남기고 나머지를 저마다 장막으로 돌려보냈어요.","t3":"여호와께서는 백성이 아직도 많다고 하시고, 그들을 물가로 데리고 내려가면 거기서 기드온을 위해 그들을 시험하겠다고 하셨다. 개가 핥듯이 혀로 물을 핥는 사람과 무릎을 꿇고 마시는 사람을 따로 세우게 하셨고, 손으로 떠서 입에 대고 핥은 사람들로 이스라엘을 구원하겠다고 하셨다. 기드온은 그 사람들만 남겨 두고 이스라엘의 다른 사람들을 각자의 장막으로 돌려보냈다. 처음에 돌아간 사람과 물가에서 남은 사람이 몇 명씩이었는지는 3절과 6절을 이어 읽어 보자."},"say":{"who":"choeon","text":"저 사람들은 손으로 물을 떠서 마셔. 다른 사람들은 무릎을 꿇고 마시고 있어!"}},{"ref":"삿 7:9-15","open":"삿 7:9","focus":"valley","text":{"t1":"그 밤에 기드온은 부하 부라와 함께 미디안 진 가까이 내려갔어요. 거기서 한 사람의 꿈 이야기를 듣고 기드온은 경배했어요.","t2":"그 밤에 여호와께서는 기드온에게 내려가 적의 진을 치라고 하셨고, 내려가기가 두려우면 부하 부라와 함께 가서 그들이 하는 말을 들으라고 하셨어요. 골짜기에는 미디안과 아말렉 사람들, 동방 사람들이 메뚜기 떼처럼 많이 누워 있었어요. 기드온은 한 사람이 동무에게, 보리떡 한 덩어리가 굴러 와서 장막을 쓰러뜨리는 꿈을 꾸었다고 말하는 것을 들었어요. 그 풀이까지 들은 기드온은 경배하고 이스라엘 진으로 돌아왔어요.","t3":"그 밤에 여호와께서는 기드온에게 일어나 내려가서 적진을 치라고 하시며, 그 진을 이미 그의 손에 넘겨주었다고 하셨다. 내려가기가 두려우면 부하 부라와 함께 내려가 그들이 하는 말을 들으라고, 그러면 손에 힘을 얻어 내려가 칠 수 있을 것이라고 하셨다. 미디안과 아말렉 사람들, 그리고 동방의 모든 사람이 진에 누워 있었다. 그 진이 어디에 있었고 얼마나 컸는지는 8절과 12절에 있다. 기드온이 이르렀을 때 한 사람이 동무에게, 보리떡 한 덩이가 미디안의 진 안으로 굴러 와서 어느 장막을 쳐서 쓰러뜨리는 꿈을 꾸었다고 말했다. 동무는 그것이 요아스의 아들인 이스라엘 사람 기드온의 칼이며, 하나님이 미디안과 온 군대를 그의 손에 넘기셨다고 대답했다. 기드온은 꿈과 그 풀이를 듣고 경배한 뒤 이스라엘 진으로 돌아와, 여호와께서 미디안 군대를 넘겨주셨으니 일어나라고 했다."},"say":{"who":"choeon","text":"저 아래에 사람들이 가득 누워 있어! 얼마나 많은지는 12절에서 읽어 보자."}},{"ref":"삿 7:16-18","focus":"jars","text":{"t1":"기드온은 남은 사람들을 세 무리로 나누고, 저마다 나팔 하나와 빈 항아리 하나를 주었어요.","t2":"기드온은 삼백 명을 세 무리로 나누고 저마다 나팔과 빈 항아리를 들게 했어요. 항아리 속에는 횃불을 숨기게 했어요. 자기를 보고 자기가 하는 대로 하라고 했어요. 자기와 함께한 사람들이 나팔을 불면 진 둘레에서 함께 나팔을 불며 외치라고 일렀어요.","t3":"기드온은 남은 사람들을 세 무리로 나누고, 저마다 나팔 하나와 빈 항아리 하나를 나누어 주었다. 자기를 보고 있다가 자기가 진 가에 이르러 하는 대로 똑같이 하라고 했다. 자기와 자기를 따르는 사람들이 나팔을 불면 진 사방에서 그들도 나팔을 불며, 여호와를 위하여 또 기드온을 위하여라고 외치라고 일렀다."},"say":{"who":"hyu","text":"세 무리로 나누었어. 한 사람마다 나팔 하나, 빈 항아리 하나. 항아리 속에 뭘 넣었는지 16절에서 찾아보자."}},{"ref":"삿 7:19-22","focus":"camp","text":{"t1":"기드온의 사람들이 나팔을 불고 항아리를 깨뜨리며 외쳤어요. 미디안 군대는 소리 지르며 달아났어요.","t2":"기드온과 백 명이 이경 초에 진 가에 이르러 나팔을 불고 손에 든 항아리를 깨뜨렸어요. 세 무리가 모두 왼손에 횃불, 오른손에 나팔을 들고 여호와와 기드온의 칼이라고 외쳤어요. 저마다 제자리에 서서 진을 둘러쌌고, 미디안 군대는 부르짖으며 달아났어요. 그 밤에 미디안 진 안에서 무슨 일이 일어났는지는 22절에서 찾아봐요.","t3":"기드온과 그와 함께한 백 명이 이경 초, 보초가 막 바뀐 때에 진 가에 이르러 나팔을 불고 손에 든 항아리를 깨뜨렸다. 세 무리가 저마다 제자리에 서서 진을 에워싸고 여호와와 기드온의 칼이라고 외치자, 온 적군이 뛰고 부르짖으며 달아났다. 그때 그들이 두 손에 무엇을 들고 있었는지, 그 밤에 미디안 진에서 무슨 일이 일어났는지는 20절과 22절에 있다. 적군은 스레라의 벧 싯다까지, 또 답밧 가까이 아벨므홀라의 경계까지 달아났다."},"say":{"who":"choeon","text":"항아리 깨지는 소리야! 진 둘레에서 나팔을 불고 있어."}}],"gates":{"t1":[{"type":"find","ref":"삿 7:7","prompt":"성경책에서 사사기 7장 7절을 찾아 읽어 보세요.","confirm":{"prompt":"기드온은 몇 명의 사람들과 싸우러 갔나요?","options":[{"label":"삼백 명","ok":true},{"label":"만 명","basis":"삿 7:3"},{"label":"이만 이천 명","basis":"삿 7:3"}]}},{"type":"multi","ref":"삿 7:12","prompt":"성경책에서 사사기 7장 12절을 찾아 읽어 보세요.","confirm":{"prompt":"골짜기에 누워 있던 사람들을 모두 고르세요.","options":[{"label":"미디안 사람","ok":true},{"label":"블레셋 사람","basis":"본문에 없음"},{"label":"아말렉 사람","ok":true},{"label":"동방 사람들","ok":true},{"label":"애굽 사람","basis":"본문에 없음"}]},"inStory":"이야기에는 미디안이라는 이름만 나온다. 골짜기에 누운 사람들(아말렉, 동방 사람)은 7:12에서만 안다"}],"t2":[{"type":"find","ref":"삿 6:11-12","prompt":"성경책에서 사사기 6장 11절과 12절을 읽어 보세요.","confirm":{"prompt":"기드온이 포도주 틀에서 밀을 타작한 까닭은 무엇인가요?","options":[{"label":"미디안 사람들이 알지 못하게 하려고","ok":true},{"label":"포도주 틀이 집에서 가장 넓었기 때문에","basis":"본문에 없음"},{"label":"비가 와서 밭에 나갈 수 없었기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"삿 6:13-16","prompt":"성경책에서 사사기 6장 13절부터 16절까지 읽고, 주고받은 말의 차례대로 눌러 보세요.","items":["기드온이, 여호와께서 함께 계시다면 왜 이런 일이 닥쳤느냐고 물었다","여호와께서 그를 보내며 이스라엘을 구하라고 하셨다","기드온이 자기 집은 가장 약하고 자기는 가장 작다고 했다","여호와께서 반드시 기드온과 함께하겠다고 하셨다"]}],"t3":[{"type":"find","refs":["삿 6:12","삿 6:16"],"prompt":"사사기 6장 12절과 16절을 함께 찾아 읽어 보자.","confirm":{"prompt":"여호와의 사자가 처음 나타나 한 말과, 기드온이 대답한 뒤 여호와께서 하신 말씀을 이어 읽으면 무엇이 같은가?","options":[{"label":"여호와의 사자는 여호와께서 기드온과 함께 계신다고 했고, 여호와께서도 반드시 기드온과 함께하겠다고 하셨다","ok":true},{"label":"여호와의 사자는 기드온을 큰 용사라 불렀고, 여호와께서도 기드온을 큰 용사라 부르셨다","basis":"본문에 없음"},{"label":"여호와의 사자는 기드온에게 표징을 구하라고 했고, 여호와께서도 먼저 표징을 보여 주겠다고 하셨다","basis":"본문에 없음"}]}},{"type":"match","refs":["삿 6:14","삿 7:9","삿 7:14"],"prompt":"사사기 6장 14절, 7장 9절, 7장 14절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"삿 6:14","text":"여호와께서 기드온을 보내시며, 미디안의 손에서 이스라엘을 건져 내라고 하셨다"},{"ref":"삿 7:9","text":"그 밤에 하나님이 기드온에게 내려가 적진을 치라고 하시며, 그 진을 그의 손에 넘겼다고 하셨다"},{"ref":"삿 7:14","text":"미디안 진의 한 사람이 꾼 보리떡 꿈을, 그 동무가 기드온의 칼이라고 풀이했다"}],"after":"세 곳을 이으면, 이스라엘을 구하라고 기드온을 보내신 하나님은 그 밤에 적진을 그의 손에 넘겼다고 하셨고, 미디안 진에서도 같은 말이 꿈 풀이로 나왔다."}]},"cards":[{"ref":"삿 6:16","title":"반드시 함께하겠다는 말씀"},{"ref":"삿 7:7","title":"삼백 명으로 구원하심"}],"close":{"t1":{"kind":"prayer","text":"하나님, 기드온의 이야기를 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 사사기 7장 1절부터 8절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"삿 6:11-16, 7:1-22에서 새로 알게 된 사실을 한 가지 적어 보자."}},"quests":[{"part":"gear","name":"톱니바퀴","line":"톱니바퀴를 찾았어! 물가에서 조금 떨어진 땅에 놓여 있었네.","found":"탐지기가 진 곁의 샘 쪽을 가리켜요.","say":{"who":"hyu","text":"탐지기 바늘이 샘 쪽으로 돌아갔어. 물가로는 내려가지 말고 떨어져서 찾자."},"q":{"t1":{"type":"find","ref":"삿 7:1","prompt":"성경책에서 사사기 7장 1절을 찾아 읽어 보세요.","confirm":{"prompt":"기드온과 백성은 어디 곁에 진을 쳤나요?","options":[{"label":"하롯 샘","ok":true},{"label":"요단 강","basis":"수 3:1"},{"label":"엘림의 샘","basis":"출 15:27"}]}},"t2":{"type":"find","ref":"삿 7:4-5","prompt":"성경책에서 사사기 7장 4절과 5절을 읽어 보세요.","confirm":{"prompt":"기드온이 백성을 물가로 데리고 내려간 까닭은 무엇인가요?","options":[{"label":"백성이 아직도 많아서, 하나님이 거기서 그들을 시험하시겠다고 하셨기 때문에","ok":true},{"label":"백성이 너무 많아서, 두려워 떠는 사람은 돌아가라고 알리게 하셨기 때문에","basis":"삿 7:3"},{"label":"백성이 오래 걸어 목이 말라서, 기드온이 물가에서 쉬게 하려고 했기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["삿 7:3","삿 7:6"],"prompt":"사사기 7장 3절과 6절을 함께 찾아 읽어 보자.","confirm":{"prompt":"사람 수가 줄어든 두 번의 일을 이어 읽으면 어떠한가?","options":[{"label":"두려워 떠는 이만 이천 명이 돌아가 만 명이 남았고, 물가에서 손으로 떠 핥아 마신 사람은 삼백 명이었다","ok":true},{"label":"두려워 떠는 만 명이 돌아가 이만 이천 명이 남았고, 물가에서 손으로 떠 핥아 마신 사람은 삼백 명이었다","basis":"본문에 없음"},{"label":"두려워 떠는 이만 이천 명이 돌아가 만 명이 남았고, 물가에서 무릎을 꿇고 마신 사람이 삼백 명이었다","basis":"본문에 없음"}]}}}},{"part":"needle","name":"나침반 바늘","line":"나침반 바늘이 여기 있었네! 저 아래가 다 내려다보여.","found":"탐지기가 아래쪽이 내려다보이는 비탈을 가리켜요.","say":{"who":"onwoo","text":"여기까지만 가자. 아래로는 내려가지 말자. 우리는 지켜보는 사람이야."},"q":{"t1":{"type":"find","ref":"삿 7:8","prompt":"성경책에서 사사기 7장 8절을 찾아 읽어 보세요.","confirm":{"prompt":"기드온이 나머지 사람들을 장막으로 돌려보낼 때, 백성은 손에 무엇을 들었나요?","options":[{"label":"양식과 나팔","ok":true},{"label":"칼과 방패","basis":"본문에 없음"},{"label":"항아리와 횃불","basis":"삿 7:16"}]}},"t2":{"type":"find","ref":"삿 7:10-11","prompt":"성경책에서 사사기 7장 10절과 11절을 읽어 보세요.","confirm":{"prompt":"하나님은 기드온이 미디안 진에 가서 그들의 말을 들으면 어떻게 될 거라고 하셨나요?","options":[{"label":"손에 힘이 생겨 내려가 그 진을 칠 수 있을 것이라고","ok":true},{"label":"미디안 사람들이 스스로 항복하러 올 것이라고","basis":"본문에 없음"},{"label":"부라가 기드온 대신 싸우게 될 것이라고","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["삿 7:8","삿 7:12"],"prompt":"사사기 7장 8절과 12절을 함께 찾아 읽어 보자.","confirm":{"prompt":"미디안 진이 있던 곳과 그 진의 모습을 이어 읽으면 어떠한가?","options":[{"label":"미디안 진은 기드온이 있는 곳 아래 골짜기에 있었고, 거기 누운 사람들은 메뚜기 떼처럼 많았으며 낙타는 바닷가 모래처럼 셀 수 없었다","ok":true},{"label":"미디안 진은 기드온이 있는 곳 아래 골짜기에 있었고, 거기 누운 사람들은 바닷가 모래처럼 많았으며 낙타는 메뚜기 떼처럼 셀 수 없었다","basis":"본문에 없음"},{"label":"미디안 진은 기드온이 있는 곳 아래 골짜기에 있었고, 사람은 많았지만 낙타는 몇 마리 되지 않았다","basis":"본문에 없음"}]}}}},{"part":"screw","name":"나사","line":"나사를 찾았어! 진 바깥쪽 땅에 떨어져 있었어.","found":"탐지기가 장막이 모인 이스라엘 진 쪽을 가리켜요.","say":{"who":"choeon","text":"장막이 정말 많아. 우리는 진 바깥쪽에서만 찾자."},"q":{"t1":{"type":"find","ref":"삿 7:16","prompt":"성경책에서 사사기 7장 16절을 찾아 읽어 보세요.","confirm":{"prompt":"기드온의 사람들이 빈 항아리 속에 감춘 것은 무엇인가요?","options":[{"label":"횃불","ok":true},{"label":"보리떡","basis":"본문에 없음"},{"label":"샘물","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"삿 7:21-22","prompt":"성경책에서 사사기 7장 21절과 22절을 읽어 보세요.","confirm":{"prompt":"미디안 군대가 부르짖으며 달아난 일을 성경은 무엇 때문이라고 적나요?","options":[{"label":"삼백 명이 나팔을 불 때 여호와께서 그 군대가 서로 칼로 치게 하셨기 때문에","ok":true},{"label":"기드온이 미디안 왕 세바와 살문나 두 사람을 먼저 사로잡았기 때문에","basis":"삿 8:12"},{"label":"여호와께서 큰 우박을 하늘에서 내려 달아나는 적군을 치셨기 때문에","basis":"수 10:11"}]}},"t3":{"type":"find","refs":["삿 7:16","삿 7:20"],"prompt":"사사기 7장 16절과 20절을 함께 찾아 읽어 보자.","confirm":{"prompt":"기드온의 사람들이 받은 것과 진 가에서 한 일을 이어 읽으면 어떠한가?","options":[{"label":"저마다 나팔과 빈 항아리를 받고 항아리 안에 횃불을 감추었다가, 진 가에서 항아리를 부수고 왼손에 횃불, 오른손에 나팔을 들고 외쳤다","ok":true},{"label":"저마다 나팔과 빈 항아리를 받고 항아리 안에 횃불을 감추었다가, 진 가에서 항아리를 부수고 왼손에 나팔, 오른손에 횃불을 들고 외쳤다","basis":"본문에 없음"},{"label":"저마다 나팔과 빈 항아리를 받고 항아리 안에 보리떡을 감추었다가, 진 가에서 항아리를 부수고 나팔을 불며 외쳤다","basis":"본문에 없음"}]}}}}],"mission":{"call":{"t1":"최현 박사예요. 타임머신이 비상 착륙하면서 부속 세 개가 망가졌어요. 이곳에서 구할 수 있는 재료로 대신 만들어 봐요.","t2":"최현 박사예요. 타임머신이 비상 착륙하면서 톱니바퀴와 나침반 바늘과 나사가 망가졌어요. 이 시대에는 부속이 없으니 이곳에서 구할 수 있는 재료 세 가지로 대신 만들어야 해요. 탐지기가 가리키는 곳을 따라가 봐요.","t3":"최현이다. 비상 착륙 때 톱니바퀴, 나침반 바늘, 나사가 망가졌다. 이 시대에는 부속을 구할 수 없으니 이곳에서 구할 수 있는 재료 세 가지로 대신 만들어야 한다. 탐지기가 가리키는 곳에서 찾되, 싸움에 딸린 일에는 끼어들지 말고 지켜보기만 하자."},"materials":[{"key":"flatstone","name":"납작한 돌","basis":"삿 7:1","use":"납작한 돌을 톱니바퀴 대신 끼워 쓸 수 있어요.","how":"진 곁 샘의 물가에서 조금 떨어진 땅에 있는 돌을 줍는다. 물가로는 내려가지 않는다.","line":"납작한 돌을 주웠어! 샘 물가에서 조금 떨어진 땅에 있었어."},{"key":"stonesliver","name":"가늘고 긴 돌 조각","basis":"삿 7:8","use":"가늘고 긴 돌 조각을 매끈하게 갈면 나침반 바늘 대신 쓸 수 있어요.","how":"아래쪽이 내려다보이는 비탈의 빈 땅에 놓여 있는 가늘고 긴 돌 조각을 줍는다. 기드온 곁에 남은 사람들과 그들이 손에 든 물건에는 가까이 가지 않고, 아래로는 내려가지 않는다.","line":"가늘고 긴 돌 조각을 주웠어! 아래쪽이 내려다보이는 비탈에 놓여 있었어."},{"key":"clod","name":"흙덩이","basis":"삿 7:1","use":"흙덩이를 꼭꼭 뭉쳐 나사 구멍에 채우면 나사 대신 쓸 수 있어요.","how":"이스라엘 진 바깥쪽 빈 땅에서 흙덩이 하나를 줍는다. 진 안으로는 들어가지 않고, 사람들의 물건은 가져오지 않는다.","line":"흙덩이를 주웠어! 이스라엘 진 바깥쪽 빈 땅에 있었어."}],"companion":{"who":"기드온","ref":"삿 7:1","when":"after","talks":[{"ask":{"who":"hyu","text":"이스라엘을 구원하라는 말씀을 들었을 때, 뭐라고 대답했어요?"},"answer":{"t1":"기드온은 자기 집안은 므낫세에서 가장 약하고, 자기는 아버지 집에서 가장 작은 사람이라고 말했어요.","t2":"기드온은 자기가 무엇으로 이스라엘을 구원하겠느냐고 물었어요. 자기 집안은 므낫세 가운데 가장 약하고, 자기는 아버지 집에서 가장 작은 사람이라고 말했어요.","t3":"기드온은 자기가 무엇으로 이스라엘을 구원할 수 있겠느냐고 되물었다. 그리고 자기 집안은 므낫세 가운데 가장 약하고 자기는 아버지 집에서 가장 작은 사람이라고 말했다."},"ref":"삿 6:15","open":"삿 6:15"},{"ask":{"who":"choeon","text":"꿈 이야기를 듣고 진으로 돌아와서, 사람들에게 뭐라고 했어요?"},"answer":{"t1":"기드온은 사람들에게 일어나라고 했어요. 여호와께서 미디안 군대를 그들의 손에 넘겨주셨다고 말했어요.","t2":"기드온은 이스라엘 진으로 돌아와 사람들에게 일어나라고 했어요. 여호와께서 미디안 군대를 그들의 손에 넘겨주셨다고 말했어요.","t3":"기드온은 꿈과 그 풀이를 듣고 이스라엘 진으로 돌아와, 일어나라고 하며 여호와께서 미디안 군대를 그들의 손에 넘겨주셨다고 말했다."},"ref":"삿 7:15","open":"삿 7:15"},{"ask":{"who":"onwoo","text":"나팔을 불기 전에 함께 갈 사람들에게 무엇을 하라고 일렀어요?"},"answer":{"t1":"기드온은 자기만 보고 자기가 하는 대로 하라고 했어요. 자기가 나팔을 불면 모두 나팔을 불라고 했어요.","t2":"기드온은 자기를 보고 자기가 하는 대로 하라고 했어요. 자기와 함께한 사람들이 나팔을 불면, 진 사방에서 나팔을 불며 외치라고 말했어요.","t3":"기드온은 자기를 보고 있다가 자기가 진 가에 이르러 하는 대로 똑같이 하라고 했다. 자기와 자기를 따르는 사람들이 나팔을 불면 그들도 진 사방에서 나팔을 불며, 여호와를 위하여, 기드온을 위하여라고 외치라고 말했다."},"ref":"삿 7:17-18","open":"삿 7:17"}]},"today":[{"q":"기드온도 무서웠을까요?","a":{"t1":"하나님은 기드온에게, 내려가기가 두려우면 부하 부라와 함께 가라고 하셨어요. 기드온은 부라를 데리고 내려갔어요.","t2":"하나님은 기드온에게 적진으로 내려가라고 하시면서, 내려가기가 두려우면 부하 부라와 함께 가서 그들이 하는 말을 들으라고 하셨어요. 기드온은 부라를 데리고 내려갔어요. 성경은 여기까지 말해요.","t3":"하나님은 기드온에게 일어나 적진으로 내려가라고 하시고, 내려가기가 두려우면 부하 부라와 함께 내려가서 그들이 하는 말을 들으라고 하셨다. 그 말을 들으면 손에 힘을 얻어 내려가 칠 수 있을 것이라고 하셨다. 기드온은 부라를 데리고 진 가로 내려갔다. 성경은 여기까지 말한다."},"refs":["삿 7:9-11"]}],"help":{"who":"하롯 샘 곁에 진을 친 기드온과 백성","steps":[{"kind":"do","after":2,"title":"돌아가는 사람들 길 비켜 주기","basis":"삿 7:3","text":{"t1":"두려워 떠는 사람은 돌아가라는 말에 많은 사람이 진을 떠나요. 우리는 진 바깥쪽에서 돌아가는 사람들의 짐을 들어 주고 길을 비켜 주어요.","t2":"하나님의 말씀대로 두려워 떠는 사람은 돌아가라고 하자, 돌아가는 사람이 이만 이천 명이었어요. 우리는 진 바깥쪽에서, 돌아가는 사람들의 짐을 들어 주고 길을 비켜 주어요.","t3":"하나님은 두려워 떠는 사람은 길르앗 산을 떠나 돌아가게 하라고 하셨고, 돌아간 사람이 많았다(7:3). 탐험대는 진 바깥쪽에서 돌아가는 사람들의 짐을 들어 주고 길을 비켜 준다. 이것은 성경에 적힌 일이 아니라 탐험대 이야기다. 싸움을 준비하는 일에는 끼지 않는다."},"tasks":["짐 들어 주기","길 비켜 주기","길가의 돌 치우기"],"done":{"who":"hyu","text":"돌아가는 사람들이 다 지나갔어. 진에 남은 사람이 몇 명인지는 3절에 있어."}},{"kind":"watch","after":3,"title":"멀리서 보기 · 물가에서 나뉜 사람들","basis":"삿 7:5-6","text":{"t1":"하나님은 기드온에게, 물을 마시는 모습에 따라 사람들을 따로 세우라고 하셨어요. 우리는 물가로 내려가지 않고 멀리서 봐요.","t2":"기드온이 백성을 물가로 데리고 내려가자, 하나님은 혀로 물을 핥는 사람과 무릎을 꿇고 마시는 사람을 따로 세우라고 하셨어요. 누가 함께 갈지는 하나님이 가리키신 일이에요. 우리는 물가로 내려가지 않고 멀리서 봐요.","t3":"기드온이 백성을 물가로 데리고 내려가자, 하나님은 개가 핥듯 혀로 물을 핥는 사람과 무릎을 꿇고 마시는 사람을 따로 세우라고 하셨다(7:4-5). 누가 함께 갈지는 하나님이 가리키시겠다고 하셨다(7:4). 탐험대는 물가로 내려가지 않고 물도 마시지 않은 채 멀리서 지켜본다."}},{"kind":"stay","after":3,"title":"물가에서 남은 사람들 곁에서","basis":"삿 7:8","text":{"t1":"기드온은 물을 핥아 마신 사람들만 남기고 나머지 사람들을 저마다 장막으로 돌려보냈어요. 우리도 남은 사람들 곁, 진 바깥쪽에 머물러요.","t2":"기드온은 나머지 이스라엘 사람들을 저마다 장막으로 돌려보내고 삼백 명만 남겨 두었어요. 미디안의 진은 그 아래쪽 골짜기에 있어요. 우리는 골짜기로 내려가지 않고 진 바깥쪽에 머물러요.","t3":"기드온은 이스라엘의 나머지 사람을 저마다 자기 장막으로 보내고, 물을 핥아 마신 사람들만 곁에 남겨 두었다. 탐험대는 아래쪽으로 내려가지 않고 이스라엘 진 바깥쪽에 머문다."},"wait":"진 바깥쪽에 머물기"},{"kind":"watch","after":5,"title":"멀리서 보기 · 나팔과 빈 항아리","basis":"삿 7:16","text":{"t1":"기드온은 남은 사람들을 세 무리로 나누고, 저마다 나팔과 빈 항아리를 들게 했어요. 우리는 나팔과 항아리에 손대지 않아요.","t2":"기드온은 삼백 명을 세 무리로 나누고, 저마다 나팔 하나와 빈 항아리 하나를 들게 하고 그 항아리 속에 횃불을 넣어 감추게 했어요. 그것은 기드온과 삼백 명이 하는 일이에요. 우리는 그 물건에 손대지 않고, 함께 내려가지도 않아요.","t3":"기드온은 남은 사람들을 세 무리로 나누어, 사람마다 나팔 하나와 빈 항아리 하나를 들게 했다. 이것은 기드온과 그 사람들의 일이다. 탐험대는 그들이 든 물건에 손대지 않고, 미디안 진으로 함께 내려가지도 않은 채 멀리서 지켜본다."},"say":{"who":"onwoo","text":"우리는 내려가지 않아. 여기서 지켜보기만 하자."}},{"kind":"ask","after":"gates","title":"사람 수를 줄이신 일은 무슨 뜻이에요?","basis":"삿 7:2","by":"최현 박사","ask":{"who":"hyu","text":"하나님이 사람 수를 그렇게 줄이신 일은 무슨 뜻이에요?"},"answer":{"t1":"성경은 하나님이 그 까닭을 기드온에게 말씀하셨다고 적어요. 백성이 너무 많으면 이스라엘이 제 손으로 자기를 구원했다고 자랑할까 해서라고 하셨어요(삿 7:2). 그리고 물을 핥아 먹은 적은 사람들로 구원하겠다고 하셨어요(삿 7:7).","t2":"성경은 하나님이 그 까닭을 직접 말씀하셨다고 기록해요. 백성이 너무 많으면 이스라엘이 하나님을 거슬러, 제 손으로 자기를 구원했다고 자랑할까 해서라고 하셨어요(삿 7:2). 그리고 물을 핥아 마신 적은 사람들로 구원하겠다고 하셨어요(삿 7:7).","t3":"성경은 그 까닭을 하나님의 말씀으로 기록한다. 기드온을 따르는 백성이 너무 많으면 이스라엘이 하나님을 거슬러 스스로 자랑하며, 제 손이 자기를 구원했다고 말할까 해서라고 하셨다(삿 7:2). 그리고 물을 핥아 마신 적은 사람들로 구원하고 미디안 사람을 기드온의 손에 넘기겠다고 하셨다(삿 7:7). 성경은 여기까지 말한다."},"read":{"t1":{"type":"find","ref":"삿 7:2","prompt":"성경책에서 사사기 7장 2절을 찾아 읽어 보세요.","confirm":{"prompt":"하나님은 백성이 너무 많으면 이스라엘이 무엇이라고 자랑할까 봐 그러셨나요?","options":[{"label":"제 손이 자기를 구원했다고","ok":true},{"label":"우리가 미디안보다 많다고","basis":"본문에 없음"},{"label":"기드온이 가장 힘이 세다고","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"삿 7:2-3","prompt":"성경책에서 사사기 7장 2절과 3절을 읽어 보세요.","confirm":{"prompt":"하나님이 기드온을 따르는 백성이 너무 많다고 하신 까닭은 무엇인가요?","options":[{"label":"이스라엘이 하나님을 거슬러, 제 손이 자기를 구원했다고 자랑할까 해서","ok":true},{"label":"두려워 떠는 사람이 섞여 있으면, 다른 사람들의 마음까지 약해질까 해서","basis":"신 20:8"},{"label":"진이 너무 커서, 미디안 사람들이 먼저 알아차리고 쳐들어올까 해서","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["삿 7:2","삿 7:7","삿 7:22"],"prompt":"사사기 7장 2절, 7절, 22절을 함께 찾아 읽어 보자.","confirm":{"prompt":"사람 수를 줄이신 까닭과, 삼백 명에게 하신 말씀과, 그날 밤의 일을 이어 읽으면 어떠한가?","options":[{"label":"하나님은 이스라엘이 제 손으로 구원했다고 자랑하지 않게 하시려고 사람 수를 줄이셨고, 삼백 명으로 구원하겠다고 하셨으며, 삼백 명이 나팔을 불 때 여호와께서 적군이 서로 칼로 치게 하셨다","ok":true},{"label":"하나님은 이스라엘이 제 손으로 구원했다고 자랑하지 않게 하시려고 사람 수를 줄이셨고, 삼백 명으로 구원하겠다고 하셨으며, 그날 밤 하늘에서 큰 우박을 내려 적군을 쫓으셨다","basis":"수 10:11"},{"label":"하나님은 이스라엘이 제 손으로 구원했다고 자랑하지 않게 하시려고 사람 수를 줄이셨고, 삼백 명으로 구원하겠다고 하셨으며, 그날 밤 삼백 명이 횃불로 미디안의 장막에 불을 놓았다","basis":"본문에 없음"}]}}}}]}},"has3d":true,"epic":false},"OT-22":{"id":"OT-22","era":6,"title":"삼손","ref":"삿 16:4-31","place":"소렉 골짜기와 블레셋 땅","review":{"required":true,"topics":["재앙과 심판(삿 16:20-21, 16:28-30)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"삿 16:4-5","focus":"delilah","text":{"t1":"삼손은 소렉 골짜기에 있는 들릴라라는 여인을 사랑했어요. 블레셋 방백들은 들릴라에게, 삼손의 힘이 어디서 나는지 알아내면 은을 주겠다고 했어요.","t2":"삼손은 소렉 골짜기의 들릴라라는 여인을 사랑했어요. 블레셋 사람의 방백들이 들릴라에게 올라와, 삼손을 꾀어 그 큰 힘이 어디서 나는지 알아보라고 했어요. 왜 그것을 알아내려 했는지는 5절에 있어요. 알아내면 저마다 은 천백을 주겠다고 했어요.","t3":"그 뒤에 삼손은 소렉 골짜기의 들릴라라는 여인을 사랑했다. 블레셋 사람의 방백들이 들릴라에게 올라와서, 삼손을 꾀어 그 큰 힘이 무엇에서 나오는지, 어떻게 하면 그를 이기고 묶어서 괴롭힐 수 있는지 알아보라고 했다. 그렇게 하면 저마다 은 천백을 주겠다고 했다."},"say":{"who":"hyu","text":"여기는 소렉 골짜기야. 블레셋 방백들이 들릴라를 찾아왔어. 적어 둘게."}},{"ref":"삿 16:6-14","focus":"ropes","text":{"t1":"삼손은 들릴라가 물을 때마다 다른 대답을 했어요. 그대로 해 보아도 삼손은 약해지지 않았어요.","t2":"들릴라는 삼손에게 큰 힘이 어디서 나며 어떻게 하면 묶을 수 있는지 말해 달라고 했어요. 삼손은 세 번 다른 대답을 했고, 들릴라가 그대로 해 보아도 삼손은 매번 풀려났어요. 첫 번째에 무슨 일이 어떤 차례로 있었는지는 6절부터 9절까지 읽어 봐요. 들릴라는 삼손이 자기를 놀리고 거짓말을 했다고 말했어요.","t3":"들릴라는 삼손에게 그 큰 힘이 무엇에서 나오며 어떻게 하면 그를 묶어서 괴롭힐 수 있는지 말해 달라고 했다. 삼손은 세 번 다른 대답을 했고, 들릴라는 그때마다 그대로 해 보았다. 안방에 사람들이 숨어 있었으나, 블레셋 사람이 들이닥쳤다는 말에 삼손은 매번 풀려났다. 삼손이 세 번 무엇이라고 대답했는지는 7절, 11절, 13절에 있다. 들릴라는 삼손이 자기를 놀리고 거짓말을 했다고 했다."},"say":{"who":"choeon","text":"삼손이 이번에도 묶인 것을 끊어 버렸어! 무엇으로 묶었는지는 성경에서 찾아보자."}},{"ref":"삿 16:15-17","open":"삿 16:17","focus":"samson","text":{"t1":"들릴라가 날마다 조르자 삼손은 마침내 다 말했어요. 자기는 나실인이어서 머리를 깎은 적이 없고, 머리가 밀리면 힘이 떠난다고 했어요.","t2":"들릴라는 삼손의 마음이 자기에게 없다고 하며 날마다 그 말로 재촉하고 졸랐어요. 삼손은 마음이 몹시 괴로워서 마침내 속에 있는 것을 다 말했어요. 자기 머리에 삭도를 댄 적이 없다고 했는데, 왜 그런지는 17절에 있어요. 머리가 밀리면 힘이 떠나서 다른 사람처럼 약해진다고 했어요.","t3":"들릴라는 마음이 자기에게 없으면서 어떻게 사랑한다고 하느냐며, 세 번이나 자기를 놀리고 큰 힘이 어디서 나는지 말해 주지 않았다고 했다. 날마다 그 말로 재촉하고 조르니 삼손은 마음이 괴로워 죽을 지경이 되었다. 삼손은 마침내 속에 있는 것을 다 털어놓았다. 자기는 모태에서부터 하나님의 나실인이 되었기에 머리에 삭도를 댄 적이 없으며, 머리가 밀리면 힘이 떠나고 약해져서 다른 사람과 같아진다고 했다."},"say":{"who":"onwoo","text":"삼손이 자기 입으로 뭐라고 말했는지, 17절에서 확인해 보자."}},{"ref":"삿 16:18-20","focus":"hair","text":{"t1":"삼손이 잠든 사이 들릴라는 사람을 불러 삼손의 머리털을 밀게 했어요. 삼손의 힘이 없어졌어요.","t2":"들릴라는 삼손이 다 털어놓은 것을 알고 블레셋 방백들을 불렀고, 방백들은 은을 가지고 올라왔어요. 들릴라는 삼손을 자기 무릎을 베고 자게 한 뒤 사람을 불러 머리털 일곱 가닥을 밀게 했어요. 삼손의 힘이 없어졌어요. 잠에서 깬 삼손은 전처럼 나가서 몸을 떨치겠다고 했지만, 여호와께서 벌써 자기에게서 떠나신 것을 알지 못했어요.","t3":"들릴라는 삼손이 속에 있는 것을 다 털어놓은 것을 보고 블레셋 방백들에게 사람을 보내어, 이번 한 번만 올라오라고 했다. 방백들은 손에 은을 가지고 올라왔다. 들릴라는 삼손이 자기 무릎을 베고 잠들게 한 다음, 사람을 불러서 머리털 일곱 가닥을 밀게 한 뒤 그를 괴롭혀 보았는데, 그의 힘이 없어져 있었다. 블레셋 사람이 들이닥쳤다는 말에 삼손은 잠에서 깼다. 그때 삼손이 한 말과 깨닫지 못한 것은 20절에 있다."},"say":{"who":"hyu","text":"방백들이 은을 들고 다시 올라왔어. 그리고 삼손의 머리털이 밀렸어."}},{"ref":"삿 16:21-22","focus":"prison","text":{"t1":"블레셋 사람들은 삼손을 붙잡아 눈을 멀게 하고 옥에서 맷돌을 돌리게 했는데, 어디로 끌고 갔는지는 성경에서 찾아봐요. 밀린 머리털은 다시 자라기 시작했어요.","t2":"블레셋 사람들은 삼손을 붙잡아 눈을 멀게 하고 가사로 끌고 내려갔어요. 놋줄로 매어 옥에서 맷돌을 돌리게 했어요. 삼손의 머리털은 밀린 뒤에 다시 자라기 시작했어요.","t3":"블레셋 사람들은 그를 붙잡아 눈을 빼고 가사로 끌고 내려가서, 놋줄로 매어 옥에서 맷돌을 돌리게 했다. 그의 머리털은 밀린 뒤에 다시 자라기 시작했다."},"say":{"who":"choeon","text":"삼손이 옥에서 맷돌을 돌리고 있어. 머리털이 다시 자라고 있네."}},{"ref":"삿 16:23-27","focus":"pillars","text":{"t1":"블레셋 사람들은 다곤이라는 자기들의 신에게 제사를 크게 드리며 즐거워했어요. 그들은 삼손을 옥에서 불러내어 사람이 가득한 집의 두 기둥 사이에 세웠어요.","t2":"블레셋 방백들은 자기들의 신이 삼손을 넘겨주었다고 하면서 다곤에게 큰 제사를 올리고 즐거워했어요. 그들은 삼손을 옥에서 불러내어 재주를 부리게 하고 두 기둥 사이에 세웠어요. 삼손은 자기 손을 붙든 소년에게, 집을 버틴 기둥을 찾아 기대게 해 달라고 했어요. 집에는 남녀가 가득했고 지붕에도 삼천 명쯤 있었어요.","t3":"블레셋 방백들은 자기들의 신이 원수 삼손을 넘겨주었다고 하며, 모두 모여서 자기들의 신 다곤에게 큰 제사를 올리고 즐거워했다. 백성도 삼손을 보고, 자기들의 땅을 망치고 많은 사람을 죽인 원수를 그 신이 넘겨주었다며 자기들의 신을 찬송했다. 마음이 즐거워진 그들은 삼손을 옥에서 불러내어 재주를 부리게 하고 두 기둥 사이에 세웠다. 삼손은 자기 손을 붙든 소년에게, 이 집을 버틴 기둥을 찾아 거기에 기댈 수 있게 해 달라고 했다. 집에는 남녀가 가득했고 블레셋의 모든 방백도 거기 있었으며, 지붕에도 삼천 명쯤 되는 남녀가 삼손이 재주 부리는 것을 보고 있었다."},"say":{"who":"hyu","text":"집 안에 블레셋 방백들이 다 있고, 지붕 위에도 삼천 명쯤 있어. 적어 둘게."}},{"ref":"삿 16:28-31","open":"삿 16:28","focus":"samson","text":{"t1":"삼손은 여호와께 이번만 강하게 해 달라고 부르짖고, 두 기둥을 붙들고 힘껏 몸을 굽혔어요. 집이 무너졌고, 하나님이 삼손을 부르셨어요.","t2":"삼손은 여호와께 자기를 생각해 주시고 이번 한 번만 강하게 해 달라고 부르짖었어요. 집을 버틴 가운데 두 기둥을 양손으로 붙들고 힘을 다해 몸을 굽히자, 집이 무너져 그 안의 방백들과 백성을 덮었어요. 삼손도 그들과 함께 죽었어요. 삼손의 형제와 집안사람들이 내려와서 그를 아버지 마노아의 묘지에 장사했어요.","t3":"삼손은 여호와께 부르짖었는데, 무엇을 구했는지는 28절에 있다. 그는 집을 버틴 가운데 두 기둥을 왼손과 오른손으로 하나씩 붙들고, 블레셋 사람과 함께 죽기를 바란다고 말한 뒤 힘을 다해 몸을 굽혔다. 집이 무너져 그 안에 있던 모든 방백과 온 백성을 덮었고, 삼손이 죽을 때 죽인 사람이 살았을 때 죽인 사람보다 더 많았다. 그의 형제와 아버지의 온 집안이 내려와 그의 주검을 가지고 올라가서, 소라와 에스다올 사이에 있는 아버지 마노아의 묘지에 장사했다. 삼손은 이스라엘의 사사로 이십 년을 지냈다."},"say":{"who":"onwoo","text":"삼손이 여호와께 뭐라고 부르짖었는지는 28절에 있어. 성경책에서 직접 읽어 보자."}}],"gates":{"t1":[{"type":"find","ref":"삿 16:21","prompt":"성경책에서 사사기 16장 21절을 찾아 읽어 보세요.","confirm":{"prompt":"블레셋 사람들은 삼손을 붙잡아 어디로 끌고 내려갔나요?","options":[{"label":"가사","ok":true},{"label":"여리고","basis":"본문에 없음"},{"label":"베들레헴","basis":"본문에 없음"}]}},{"type":"multi","ref":"삿 16:12","prompt":"성경책에서 사사기 16장 12절을 찾아 읽어 보세요.","confirm":{"prompt":"들릴라가 두 번째로 삼손을 묶었을 때 있었던 일을 모두 고르세요.","options":[{"label":"들릴라가 새 밧줄로 삼손을 묶었어요","ok":true},{"label":"들릴라가 삼손의 머리털을 베틀에 짰어요","basis":"삿 16:14"},{"label":"삼손이 팔에 묶인 밧줄을 실처럼 끊었어요","ok":true},{"label":"사람들이 안방에 숨어 있었어요","ok":true},{"label":"들릴라가 마르지 않은 줄 일곱으로 삼손을 묶었어요","basis":"삿 16:8"}]}}],"t2":[{"type":"find","ref":"삿 16:4-5","prompt":"성경책에서 사사기 16장 4절과 5절을 읽어 보세요.","confirm":{"prompt":"블레셋 방백들이 삼손의 큰 힘이 어디서 나는지 알아내려 한 까닭은 무엇인가요?","options":[{"label":"삼손을 이겨 묶어서 괴롭게 하려고","ok":true},{"label":"삼손에게 상을 주려고","basis":"본문에 없음"},{"label":"삼손을 자기들의 왕으로 세우려고","basis":"본문에 없음"}]}},{"type":"order","ref":"삿 16:6-9","prompt":"성경책에서 사사기 16장 6절부터 9절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["들릴라가 삼손에게 큰 힘이 어디서 나는지 물었다","삼손이 마르지 않은 줄 일곱으로 묶으면 약해진다고 했다","방백들이 그 줄 일곱을 들릴라에게 가져왔다","들릴라가 그 줄로 삼손을 묶었다","삼손이 그 줄을 불에 탄 실처럼 끊었다"]}],"t3":[{"type":"find","refs":["삿 16:7","삿 16:11","삿 16:13"],"prompt":"사사기 16장 7절, 11절, 13절을 함께 찾아 읽어 보자.","confirm":{"prompt":"들릴라가 물을 때마다 삼손이 한 대답을 이어 읽으면 어떠한가?","options":[{"label":"처음에는 마르지 않은 줄 일곱으로, 다음에는 쓰지 않은 새 밧줄로 묶으면 약해진다고 했고, 그다음에는 머리털 일곱 가닥을 베틀의 날실에 섞어 짜면 된다고 했다","ok":true},{"label":"처음에는 쓰지 않은 새 밧줄로, 다음에는 마르지 않은 줄 일곱으로 묶으면 약해진다고 했고, 그다음에는 머리털을 밀면 된다고 했다","basis":"본문에 없음"},{"label":"처음에는 마르지 않은 줄 일곱으로, 다음에는 쇠사슬로 묶으면 약해진다고 했고, 그다음에는 머리털 일곱 가닥을 베틀의 날실에 섞어 짜면 된다고 했다","basis":"본문에 없음"}]}},{"type":"match","refs":["삿 16:5","삿 16:9","삿 16:18"],"prompt":"사사기 16장 5절, 9절, 18절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"삿 16:5","text":"방백들이 삼손의 힘이 어디서 나는지 알아내면 저마다 은 천백을 주겠다고 했다"},{"ref":"삿 16:9","text":"삼손이 줄을 끊어 버려, 그 힘이 어디서 나는지는 여전히 알 수 없었다"},{"ref":"삿 16:18","text":"삼손이 속마음을 다 털어놓자 방백들이 은을 가지고 다시 들릴라에게 왔다"}],"after":"세 곳을 이으면, 방백들은 은을 걸고 삼손의 힘이 어디서 나는지 알아내려 했고, 처음에는 알지 못했으나 삼손이 다 털어놓자 은을 가지고 왔다."}]},"cards":[{"ref":"삿 16:17","title":"모태에서부터 하나님의 나실인"},{"ref":"삿 16:28","title":"삼손이 여호와께 부르짖음"}],"close":{"t1":{"kind":"prayer","text":"하나님, 삼손의 이야기를 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 사사기 16장 15절부터 22절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"삿 16:4-31에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 비상 착륙 때 타임머신의 무게추가 빠져 버렸어요. 대신 쓸 재료를 이곳에서 하나 찾아봐요.","t2":"최현 박사예요. 비상 착륙 때 타임머신의 균형을 잡아 주는 무게추가 빠져 버렸어요. 이 시대에는 부속이 없으니 이곳에서 대신 쓸 재료를 하나 찾아야 해요. 블레셋 사람들이 있는 곳에는 가까이 가지 말아요.","t3":"최현이다. 비상 착륙 때 타임머신의 균형을 잡는 무게추가 빠졌다. 이 시대에는 부속을 구할 수 없으니 이곳에서 대신 쓸 재료를 하나 찾아야 한다. 블레셋 사람들이 있는 곳에는 가까이 가지 말고 지켜보기만 하자."},"materials":[{"key":"sand","name":"고운 모래","basis":"삿 16:4","use":"고운 모래를 주머니에 담으면 무게추 대신 쓸 수 있어요.","how":"소렉 골짜기의 빈 땅에서 고운 모래를 한 줌 떠 담는다. 들릴라가 있는 집과 블레셋 사람들에게는 가까이 가지 않는다.","line":"고운 모래를 한 줌 담았어! 소렉 골짜기의 빈 땅에서 떴어."}],"companion":null,"today":[{"q":"삼손은 힘이 그렇게 셌는데, 왜 들릴라에게 비밀을 다 말해 버렸어요?","a":{"t1":"들릴라는 날마다 삼손을 조르고 재촉했어요. 삼손은 마음이 몹시 괴로워져서 속에 있는 것을 다 말했어요.","t2":"성경은 들릴라가 날마다 그 말로 삼손을 재촉하고 졸랐다고 기록해요. 삼손은 마음이 괴로워 죽을 지경이 되었고, 마침내 속에 있는 것을 다 털어놓았어요. 성경은 여기까지 말해요.","t3":"들릴라는 삼손의 마음이 자기에게 없다고 하며, 세 번이나 자기를 놀렸다고 말했다. 그리고 날마다 그 말로 재촉하고 졸랐다. 삼손은 마음이 괴로워 죽을 지경이 되었고, 결국 속에 있는 것을 다 털어놓았다. 성경은 여기까지 말한다."},"refs":["삿 16:15-17"]},{"q":"나실인이 뭐예요?","a":{"t1":"삼손은 자기가 어머니 배 속에서부터 하나님의 나실인이어서 머리를 깎은 적이 없다고 했어요. 삼손이 태어나기 전에 여호와의 사자도 삼손의 어머니에게, 아이의 머리에 삭도를 대지 말라고 했어요.","t2":"삼손은 자기가 어머니 배 속에서부터 하나님의 나실인이 되었기 때문에 머리에 삭도를 댄 적이 없다고 말했어요. 삼손이 태어나기 전에 여호와의 사자는 삼손의 어머니에게, 포도주와 독주를 마시지 말고 부정한 것을 먹지 말며 아이의 머리에 삭도를 대지 말라고 했어요. 그 아이는 태에서 나올 때부터 하나님께 바친 나실인이 될 것이라고 했어요.","t3":"삼손은 모태에서부터 하나님의 나실인이 되었기에 머리에 삭도를 대지 않았다고 말했다. 삼손이 태어나기 전에 여호와의 사자는 그의 어머니에게, 포도주와 독주를 마시지 말고 부정한 것을 먹지 말며 아이의 머리에 삭도를 대지 말라고 했다. 그 아이는 태에서 나올 때부터 하나님께 바친 나실인이 될 것이라고 했다. 나실인의 서원을 한 사람이 여호와께 자기를 구별해 드린 동안 머리에 삭도를 대지 않는다는 규례는 민수기 6장에도 있다."},"refs":["삿 16:17","삿 13:4-5","민 6:2-5"]}],"help":{"who":"삼손의 형제와 집안사람들","steps":[{"kind":"do","after":6,"title":"삼손의 집안사람들에게 길 비켜 주기","basis":"삿 16:31","text":{"t1":"삼손의 형제들과 집안사람들이 삼손을 데려가려고 내려왔어요. 우리는 무너진 집에서 멀리 떨어진 길가에서, 그 사람들이 지나갈 길의 돌을 치우고 조용히 비켜 주어요.","t2":"삼손의 형제와 아버지의 온 집안이 삼손을 데려가 장사하려고 내려왔어요. 우리는 무너진 집에서 멀리 떨어진 길가에서, 그 사람들이 지나갈 길의 돌을 치우고 조용히 길을 비켜 주어요.","t3":"삼손의 형제와 아버지의 온 집이 내려가 삼손을 거두어 가지고 올라왔다(16:31). 탐험대는 무너진 집에서 멀리 떨어진 길가에서, 그 사람들이 지나갈 길의 돌을 치우고 조용히 길을 비켜 준다. 이것은 성경에 적힌 일이 아니라 탐험대 이야기다. 탐험대는 무너진 집과 삼손의 몸에 손대지 않는다."},"tasks":["길 위의 돌 치우기","길 한쪽으로 비켜 서기"],"done":{"who":"onwoo","text":"길을 비켜 드렸어. 우리는 여기서 조용히 지켜보자."}},{"kind":"watch","after":6,"title":"멀리서 보기 · 아버지 마노아의 묘로","basis":"삿 16:31","text":{"t1":"삼손의 형제들과 집안사람들이 내려와, 하나님이 부르신 삼손을 아버지 마노아의 묘에 모셨어요. 우리는 멀리서 조용히 봐요.","t2":"삼손의 형제와 아버지의 온 집안이 내려와 삼손을 데리고 올라갔어요. 그리고 소라와 에스다올 사이, 아버지 마노아의 묘지에 장사했어요. 장사하는 것은 그 집안사람들의 일이에요. 우리는 멀리서 조용히 봐요.","t3":"삼손의 형제와 아버지의 온 집이 내려가 삼손의 몸을 거두어 갔다. 그리고 소라와 에스다올 사이에 있는 아버지 마노아의 묘지에 장사했다(16:31). 장사는 그 집안사람들이 한 일이다. 탐험대는 끼어들지 않고 멀리서 조용히 지켜본다."}},{"kind":"ask","after":"gates","title":"머리털과 힘의 일은 무슨 뜻이에요?","basis":"삿 16:17-20","by":"최현 박사","ask":{"who":"onwoo","text":"머리털이 밀리자 삼손의 힘이 없어진 일은 무슨 뜻이에요?"},"answer":{"t1":"삼손은 자기가 하나님의 나실인이어서, 머리가 밀리면 힘이 떠난다고 말했어요(삿 16:17). 성경은 머리털이 밀린 뒤 삼손이, 여호와께서 벌써 그를 떠나셨다는 것을 알지 못했다고 적어요(삿 16:20).","t2":"삼손은 자기가 어머니 배 속에서부터 하나님의 나실인이어서 머리에 삭도를 댄 적이 없고, 머리가 밀리면 힘이 떠나 다른 사람처럼 약해진다고 말했어요(삿 16:17). 성경은 머리털이 밀린 뒤 삼손이 전처럼 나가겠다고 했지만, 여호와께서 벌써 그를 떠나셨다는 것을 알지 못했다고 적어요(삿 16:20). 성경은 여기까지 말해요.","t3":"삼손은 태어나기 전부터 하나님께 바쳐진 나실인이어서 머리에 삭도를 대지 않았고, 머리가 밀리면 힘이 떠나 다른 사람처럼 약해진다고 말했다(삿 16:17). 머리털이 밀린 뒤 삼손은 전처럼 나가서 몸을 떨치겠다고 했으나, 여호와께서 벌써 그를 떠나셨다는 것을 알지 못했다(삿 16:20). 마지막에 삼손은 여호와께 자기를 생각해 주시고 이번만 강하게 해 달라고 부르짖었다(삿 16:28). 여호와께서 왜 떠나셨는지는 이 본문이 말하지 않는다. 성경은 여기까지 말한다."},"read":{"t1":{"type":"find","ref":"삿 16:20","prompt":"성경책에서 사사기 16장 20절을 찾아 읽어 보세요.","confirm":{"prompt":"잠에서 깬 삼손은 무엇을 알지 못했나요?","options":[{"label":"여호와께서 벌써 그에게서 떠나신 것","ok":true},{"label":"해가 이미 졌다는 것","basis":"본문에 없음"},{"label":"들릴라가 집을 떠났다는 것","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"삿 16:17-19","prompt":"성경책에서 사사기 16장 17절부터 19절까지 읽어 보세요.","confirm":{"prompt":"삼손은 왜 자기 머리에 삭도를 댄 적이 없다고 했나요?","options":[{"label":"태어나기 전부터 하나님께 바쳐진 나실인이었기 때문에","ok":true},{"label":"머리털이 길게 자라야 블레셋 사람과 싸울 힘이 나기 때문에","basis":"본문에 없음"},{"label":"스스로 서원하여 머리털을 길게 기르기로 했기 때문에","basis":"민 6:5"}]}},"t3":{"type":"find","refs":["삿 16:17","삿 16:20","삿 16:28"],"prompt":"사사기 16장 17절, 20절, 28절을 함께 찾아 읽어 보자.","confirm":{"prompt":"삼손이 한 말, 삼손이 알지 못한 것, 삼손의 마지막 부르짖음을 이어 읽으면 어떠한가?","options":[{"label":"삼손은 머리가 밀리면 힘이 떠난다고 했고, 머리털이 밀린 뒤 여호와께서 떠나신 것을 알지 못했으며, 마지막에 여호와께 자기를 생각해 주시고 이번만 강하게 해 달라고 부르짖었다","ok":true},{"label":"삼손은 머리가 밀리면 힘이 떠난다고 했고, 머리털이 밀린 뒤 들릴라가 떠난 것을 알지 못했으며, 마지막에 여호와께 이번만 강하게 해 달라고 부르짖었다","basis":"본문에 없음"},{"label":"삼손은 머리가 밀리면 힘이 떠난다고 했고, 머리털이 밀린 뒤 여호와께서 떠나신 것을 알지 못했으며, 마지막에 여호와께 두 눈을 다시 보게 해 달라고 부르짖었다","basis":"본문에 없음"}]}}}}]}},"has3d":false,"epic":false},"OT-23":{"id":"OT-23","era":6,"title":"룻과 나오미","ref":"룻 1:1-22","place":"모압 지방, 유다 베들레헴","review":{"required":false,"topics":[],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"룻 1:1-5","focus":"family","text":{"t1":"흉년이 들어 나오미의 가족은 베들레헴을 떠나 모압으로 갔어요. 거기서 하나님이 나오미의 남편과 두 아들을 부르셨어요.","t2":"사사들이 다스리던 때에 그 땅에 흉년이 들었어요. 유다 베들레헴 사람 엘리멜렉은 아내 나오미와 두 아들 말론과 기룐을 데리고 모압 지방으로 가서 살았어요. 엘리멜렉이 죽은 뒤 두 아들은 모압 여자 오르바와 룻을 아내로 맞았어요. 십 년쯤 지나 두 아들도 죽어, 나오미는 남편과 두 아들을 다 잃었어요.","t3":"사사들이 다스리던 때에 그 땅에 흉년이 들었다. 유다 베들레헴의 한 사람이 아내와 두 아들과 함께 모압 지방으로 가서 머물러 살았다. 그의 이름은 엘리멜렉, 아내는 나오미, 두 아들은 말론과 기룐이며 유다 베들레헴의 에브랏 사람들이었다. 엘리멜렉이 죽고 나오미와 두 아들이 남았는데, 두 아들은 모압 여자를 아내로 맞았고 그 이름은 오르바와 룻이었다. 거기서 산 지 십 년쯤 되어 말론과 기룐도 죽어, 나오미는 남편과 두 아들을 다 여의고 남았다."},"say":{"who":"hyu","text":"베들레헴에서 모압 지방으로 갔어. 엘리멜렉, 나오미, 말론, 기룐. 이름을 적어 둘게."}},{"ref":"룻 1:6-18","open":"룻 1:16","focus":"road","text":{"t1":"나오미는 고향으로 돌아가며 며느리들에게 돌아가라고 했어요. 그러나 룻은 어머니가 가는 곳에 자기도 가겠다며 나오미를 떠나지 않았어요.","t2":"나오미는 두 며느리와 함께 유다 땅으로 돌아가는 길에 올랐는데, 왜 돌아가려 했는지는 6절에 있어요. 길에서 나오미는 며느리들에게 저마다 어머니의 집으로 돌아가라고 했어요. 오르바는 시어머니에게 입 맞추었지만 룻은 나오미를 떠나지 않고 따랐어요. 룻은 어머니가 가는 곳에 자기도 가고, 어머니의 백성이 자기 백성이 되고 어머니의 하나님이 자기 하나님이 되실 것이라고 말했어요.","t3":"나오미는 여호와께서 자기 백성을 돌아보셔서 양식을 주셨다는 말을 모압 지방에서 듣고, 두 며느리와 함께 유다 땅으로 돌아가려고 길을 떠났다. 길에서 나오미는 두 며느리에게 저마다 어머니의 집으로 돌아가라고 하며, 그들이 죽은 이들과 자기를 잘 대한 것처럼 여호와께서 그들을 잘 대해 주시기를 빌었다. 그들은 소리 높여 울며 함께 가겠다고 했으나, 나오미는 그들의 남편이 될 아들이 자기에게 더 없다고 하며 거듭 돌아가라고 했다. 오르바는 시어머니에게 입 맞추었으나 룻은 그를 붙좇았다. 나오미가 동서를 따라 돌아가라고 하자 룻은, 어머니를 떠나라고 강권하지 말아 달라고 하며 어머니가 가는 곳에 자기도 가고 머무는 곳에 자기도 머물겠다고 했다. 어머니의 백성이 자기 백성이 되고 어머니의 하나님이 자기 하나님이 되시며, 어머니가 죽는 곳에서 자기도 죽어 묻히겠다고 했다. 나오미는 룻이 굳게 마음먹은 것을 보고 더 말하지 않았다."},"say":{"who":"onwoo","text":"룻이 나오미에게 한 말은 16절과 17절에 있어. 성경책에서 직접 읽어 보자."}},{"ref":"룻 1:19-22","focus":"bethlehem","text":{"t1":"나오미와 룻이 베들레헴에 이르자 온 성읍이 떠들썩했어요. 그때가 언제였는지는 성경에서 찾아봐요.","t2":"두 사람이 베들레헴에 이르자 온 성읍이 떠들썩해져서, 이 사람이 나오미냐고 했어요. 나오미는 자기를 나오미라 하지 말고 마라라고 부르라고 했어요. 전능자가 자기를 몹시 괴롭게 하셨다는 것이에요. 두 사람이 베들레헴에 이른 때는 보리 추수를 시작할 때였어요.","t3":"두 사람이 길을 가서 베들레헴에 이르자 온 성읍이 그들 때문에 떠들썩해져서, 이 사람이 나오미냐고 했다. 나오미는 자기를 나오미라 하지 말고 마라라고 부르라고 했다. 전능자가 자기를 몹시 괴롭게 하셨고, 자기는 풍족하게 나갔으나 여호와께서 빈손으로 돌아오게 하셨다고 말했다. 나오미는 모압 여인인 며느리 룻과 함께 모압 지방에서 돌아왔는데, 그들이 베들레헴에 이른 때가 언제였는지는 22절에 있다."},"say":{"who":"choeon","text":"온 성읍이 두 사람 때문에 떠들썩해! 사람들이 나오미를 알아보나 봐."}},{"ref":"룻 2:1-7","focus":"field","text":{"t1":"룻은 밭에 나가 이삭을 주웠어요. 그 밭은 보아스라는 사람의 밭이었어요.","t2":"나오미의 남편 엘리멜렉의 친족 가운데 보아스라는 유력한 사람이 있었어요. 룻은 나오미에게 말하고 밭에 나가 이삭을 주웠는데, 우연히 보아스의 밭에 이르렀어요. 그 밭에서 무슨 일이 어떤 차례로 있었는지는 3절부터 6절까지 읽어 봐요.","t3":"나오미의 남편 엘리멜렉의 친족 가운데 유력한 사람이 있었는데 이름이 보아스였다. 모압 여인 룻은 나오미에게, 밭에 나가서 자기에게 은혜를 베푸는 사람을 따라가며 이삭을 줍겠다고 했고 나오미는 가라고 했다. 룻이 가서 베는 사람들을 따라 이삭을 주웠는데, 그 밭은 우연히도 엘리멜렉의 친족인 보아스의 밭이었다. 마침 보아스가 베들레헴에서 와서 베는 사람들에게 여호와께서 함께하시기를 빈다고 인사하자, 그들은 여호와께서 그에게 복 주시기를 빈다고 대답했다. 보아스가 베는 사람들을 거느린 사환에게 이 소녀가 누구의 사람이냐고 묻자, 사환은 그 소녀가 모압 지방에서 나오미를 따라 돌아온 모압 사람이라고 대답했다. 그 소녀가 베는 사람들을 따라 단 사이에서 이삭을 줍게 해 달라고 했으며, 아침부터 와서 잠깐 쉰 것 말고는 지금까지 줍고 있다고 했다."},"say":{"who":"choeon","text":"룻이 베는 사람들 뒤를 따라가면서 이삭을 줍고 있어!"}},{"ref":"룻 2:8-16","open":"룻 2:12","focus":"boaz","text":{"t1":"보아스는 룻에게 다른 밭으로 가지 말고 여기서 이삭을 주우라고 했어요. 식사 때 보아스가 룻에게 무엇을 주었는지는 성경에서 찾아봐요.","t2":"보아스는 룻에게 다른 밭으로 가지 말고 자기 소녀들과 함께 있으라고 했어요. 룻이 엎드려 절하며 이방 여인인 자기에게 어째서 은혜를 베푸느냐고 묻자, 보아스는 룻이 시어머니에게 한 일과 부모와 고국을 떠나온 일을 다 들었다고 했어요. 식사할 때 보아스는 룻에게 볶은 곡식을 주었고 룻은 배불리 먹고 남겼어요. 보아스는 소년들에게 룻이 곡식 단 사이에서도 줍게 하고 꾸짖지 말라고 일렀어요.","t3":"보아스는 룻에게 이삭을 주우러 다른 밭으로 가지 말고 자기 소녀들과 함께 여기 있으라고 했다. 소년들에게 룻을 건드리지 말라고 일러두었으며, 목이 마르면 소년들이 길어 온 물을 마시라고도 했다. 룻이 땅에 엎드려 절하며 이방 여인인 자기를 어찌하여 돌아보느냐고 묻자, 보아스는 남편이 죽은 뒤에 룻이 시어머니에게 한 모든 일과, 부모와 고국을 떠나서 이전에는 알지 못하던 백성에게로 온 일을 자세히 들었다고 대답했다. 그리고 이스라엘의 하나님 여호와, 곧 룻이 그 날개 아래로 보호를 받으러 온 분께서 온전한 상을 주시기를 빌었다. 식사할 때 보아스는 룻을 불러 떡을 먹게 하고 볶은 곡식을 주어, 룻이 배불리 먹고 남겼다. 룻이 다시 이삭을 주우러 일어나자 보아스는 소년들에게, 곡식 단 사이에서도 줍게 하고 책망하지 말며 곡식 줌에서 조금씩 뽑아 흘려 두어 줍게 하라고 일렀다."},"say":{"who":"onwoo","text":"보아스가 룻에게 빌어 준 말은 12절에 있어. 성경책에서 찾아보자."}},{"ref":"룻 2:17-23","focus":"naomi","text":{"t1":"룻은 저녁까지 주운 보리를 나오미에게 보였어요. 나오미는 룻을 돌보아 준 사람에게 여호와의 복이 있기를 빌었어요.","t2":"룻이 저녁까지 주운 것을 떨었더니 보리가 한 에바쯤 되었어요. 룻은 성읍에 들어가 시어머니에게 그것을 보이고, 먹고 남긴 것도 드렸어요. 일하게 해 준 사람이 보아스라는 말을 듣고 나오미는, 그가 자기들에게 어떤 사람인지 말해 주었어요. 룻은 보리 추수와 밀 추수가 끝날 때까지 보아스의 소녀들 가까이에서 이삭을 주웠어요.","t3":"룻이 저녁까지 밭에서 줍고 주운 것을 떨어 보니 보리가 한 에바쯤 되었다. 그것을 가지고 성읍에 들어가 시어머니에게 보이고, 배불리 먹고 남긴 것도 내어 드렸다. 나오미는 오늘 어디서 주웠느냐고 물으며 룻을 돌아본 사람에게 복이 있기를 빌었고, 룻은 일하게 해 준 사람의 이름이 보아스라고 알렸다. 나오미는 여호와의 복이 그에게 있기를 빌었다. 나오미가 그 사람을 두고 한 말과, 룻이 언제까지 누구 곁에서 이삭을 주웠는지는 20절과 23절에 있다. 룻은 시어머니와 함께 살았다."},"say":{"who":"hyu","text":"저녁까지 주운 보리가 한 에바쯤이야. 나오미가 보아스에 대해 한 말은 20절에서 찾아 적자."}},{"ref":"룻 4:13-17","focus":"baby","text":{"t1":"보아스는 룻을 아내로 맞았고, 여호와께서 아기를 갖게 하셔서 룻이 아들을 낳았어요. 아기의 이름은 오벳이고, 오벳은 다윗의 할아버지예요.","t2":"보아스는 룻을 아내로 맞았고, 여호와께서 잉태하게 하셔서 룻이 아들을 낳았어요. 여인들은 나오미에게 여호와를 찬송한다고 말했는데, 왜 찬송했는지는 14절에 있어요. 나오미는 아기를 품에 안고 길렀어요. 이웃 여인들이 아기의 이름을 오벳이라 했는데, 그는 다윗의 아버지인 이새의 아버지예요.","t3":"보아스가 룻을 아내로 맞았고, 여호와께서 잉태하게 하시므로 룻이 아들을 낳았다. 여인들은 나오미에게 여호와를 찬송한다고 하며 그 아이의 이름이 이스라엘에서 유명해지기를 빌었다. 무엇 때문에 찬송했는지는 14절에 있다. 그 아이가 나오미의 생명을 회복시키고 노년에 그를 봉양할 것이며, 나오미를 사랑하는 며느리, 일곱 아들보다 귀한 며느리가 낳은 아이라고 했다. 나오미는 아기를 받아 품에 안고 그를 기르는 사람이 되었다. 이웃 여인들은 나오미에게 아들이 태어났다고 하며 아기의 이름을 오벳이라 지었고, 그는 다윗의 아버지인 이새의 아버지였다."},"say":{"who":"choeon","text":"나오미가 아기를 품에 안고 있어. 이름이 오벳이래!"}}],"gates":{"t1":[{"type":"find","ref":"룻 1:22","prompt":"성경책에서 룻기 1장 22절을 찾아 읽어 보세요.","confirm":{"prompt":"나오미와 룻이 베들레헴에 이른 것은 언제였나요?","options":[{"label":"보리 추수를 시작할 때","ok":true},{"label":"보리 추수를 다 마친 뒤","basis":"룻 2:23"},{"label":"밀 추수를 마칠 때","basis":"룻 2:23"}]}},{"type":"multi","ref":"룻 2:14","prompt":"성경책에서 룻기 2장 14절을 찾아 읽어 보세요.","confirm":{"prompt":"식사할 때 보아스가 룻에게 하라고 하거나 준 것을 모두 고르세요.","options":[{"label":"떡을 초에 찍어 먹으라고 했어요","ok":true},{"label":"소년들이 길어 온 물을 마시라고 했어요","basis":"룻 2:9"},{"label":"볶은 곡식을 주었어요","ok":true},{"label":"포도주를 따라 주었어요","basis":"본문에 없음"},{"label":"꿀을 주었어요","basis":"본문에 없음"}]}}],"t2":[{"type":"find","ref":"룻 1:6-7","prompt":"성경책에서 룻기 1장 6절과 7절을 읽어 보세요.","confirm":{"prompt":"나오미가 모압 지방을 떠나 고향 유다로 돌아가려고 나선 까닭은 무엇인가요?","options":[{"label":"여호와께서 유다 백성을 돌보셔서 먹을 것을 주셨다는 소식을 들었기 때문에","ok":true},{"label":"모압 지방에도 흉년이 들어 더는 먹을 것을 구할 수 없었기 때문에","basis":"본문에 없음"},{"label":"베들레헴의 친척이 사람을 보내 이제 고향으로 돌아오라고 했기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"룻 2:3-6","prompt":"성경책에서 룻기 2장 3절부터 6절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["룻이 베는 사람들을 따라가며 이삭을 주웠다","보아스가 밭에 와서 베는 사람들과 인사를 나누었다","보아스가 일꾼들을 맡은 사환에게 이 소녀가 누구냐고 물었다","사환이 나오미를 따라 모압에서 온 소녀라고 대답했다"]}],"t3":[{"type":"find","refs":["룻 1:22","룻 2:23"],"prompt":"룻기 1장 22절과 2장 23절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 사람이 베들레헴에 온 때와 룻이 이삭을 주운 기간을 이어 읽으면 어떠한가?","options":[{"label":"두 사람은 보리 추수를 시작할 때 베들레헴에 이르렀고, 룻은 보리와 밀의 추수가 끝날 때까지 보아스 집 소녀들 곁에서 이삭을 주웠다","ok":true},{"label":"두 사람은 보리 추수를 시작할 때 베들레헴에 이르렀고, 룻은 보리 추수가 끝나자 곧 이삭 줍기를 그쳤다","basis":"본문에 없음"},{"label":"두 사람은 밀 추수를 마칠 무렵 베들레헴에 이르렀고, 룻은 그 뒤 여러 해 동안 보아스의 밭에서 이삭을 주웠다","basis":"본문에 없음"}]}},{"type":"match","refs":["룻 1:16","룻 2:12","룻 4:17"],"prompt":"룻기 1장 16절, 2장 12절, 4장 17절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"룻 1:16","text":"룻이 나오미의 백성과 나오미의 하나님을 자기 백성과 자기 하나님으로 삼겠다고 했다"},{"ref":"룻 2:12","text":"보아스가 여호와의 날개 아래로 피하러 온 룻에게 온전한 상을 빌었다"},{"ref":"룻 4:17","text":"이웃 여인들이 아기 이름을 오벳이라 했고, 그는 다윗의 아버지 이새의 아버지였다"}],"after":"세 곳을 이으면, 나오미의 하나님을 자기 하나님으로 삼겠다던 모압 여인 룻에게 보아스는 여호와의 상을 빌었고, 룻이 낳은 오벳은 다윗의 할아버지가 되었다."}]},"cards":[{"ref":"룻 1:16","title":"어머니의 하나님이 나의 하나님"},{"ref":"룻 2:12","title":"그 날개 아래"}],"close":{"t1":{"kind":"prayer","text":"하나님, 룻과 나오미의 이야기를 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 룻기 1장 15절부터 22절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"룻 1:1-22, 2:1-23, 4:13-17에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 비상 착륙 때 타임머신 덮개에 틈이 생겼으니, 틈을 막을 재료를 하나 찾아봐요. 룻을 도울 때는 룻이 하는 일만 돕고, 이삭은 줍지 않아요.","t2":"최현 박사예요. 비상 착륙 때 타임머신 덮개에 틈이 생겨서 틈막이가 필요해요. 이 시대에는 부속이 없으니 이곳에서 구할 수 있는 재료로 대신해야 해요. 사람들의 것이나 남의 것은 가져오면 안 되고, 룻을 돕게 되면 룻이 하는 평범한 일만 도와요.","t3":"최현이다. 비상 착륙 때 타임머신 덮개에 틈이 생겼다. 이 시대에는 부속을 구할 수 없으니 이곳에서 틈막이로 쓸 재료를 하나 찾아야 한다. 사람들의 것이나 남의 것은 가져오지 말자. 룻을 돕게 되면 룻이 하는 평범한 일만 돕고, 이삭을 줍거나 밭의 곡식을 가져오지는 않는다."},"materials":[{"key":"soil","name":"흙","basis":"룻 1:7","use":"흙을 물에 개어 바르면 틈막이 대신 쓸 수 있어요.","how":"유다 땅으로 가는 길가의 빈 땅에서 흙을 한 줌 담는다. 나오미와 룻이 있는 곳에서는 떨어져 있고, 밭의 이삭과 곡식 단과 룻이 주운 보리는 가져오지 않는다.","line":"흙을 한 줌 담았어! 유다 땅으로 가는 길가의 빈 땅에서 떴어."}],"companion":{"who":"룻","ref":"룻 1:22","when":"after","talks":[{"ask":{"who":"choeon","text":"나오미 할머니가 돌아가라고 했을 때 뭐라고 대답했어요?"},"answer":{"t1":"룻은 어머니가 가는 곳에 자기도 가겠다고 말했어요. 어머니의 하나님이 자기 하나님이 되실 거라고 했어요.","t2":"룻은 어머니를 떠나라고 강권하지 말아 달라고 말했어요. 어머니가 가는 곳에 자기도 가고, 어머니의 백성이 자기 백성이 되고 어머니의 하나님이 자기 하나님이 되실 것이라고 했어요.","t3":"룻은 어머니를 떠나 돌아가라고 강권하지 말아 달라고 했다. 어머니가 가는 곳에 자기도 가고 머무는 곳에 자기도 머물겠으며, 어머니의 백성이 자기 백성이 되고 어머니의 하나님이 자기 하나님이 되실 것이라고 했다. 어머니가 죽는 곳에서 자기도 죽어 거기 묻히겠다고 했다."},"ref":"룻 1:16-17","open":"룻 1:16"},{"ask":{"who":"hyu","text":"처음 밭에 나갈 때 나오미 할머니에게 뭐라고 했어요?"},"answer":{"t1":"룻은 밭에 가서, 자기에게 은혜를 베푸는 사람을 따라 이삭을 줍겠다고 말했어요.","t2":"룻은 나오미에게 자기를 밭에 가게 해 달라고 했어요. 자기에게 은혜를 베푸는 사람이 있으면 그 사람을 따라가며 이삭을 줍겠다고 말했어요.","t3":"룻은 나오미에게 밭에 가게 해 달라고 하며, 누군가에게 은혜를 입으면 그 사람을 따라가며 이삭을 줍겠다고 말했다."},"ref":"룻 2:2","open":"룻 2:2"},{"ask":{"who":"onwoo","text":"보아스 아저씨가 다른 밭으로 가지 말라고 했을 때, 뭐라고 했어요?"},"answer":{"t1":"룻은 이방 여인인 자기를 어찌하여 돌아보느냐고 물었어요.","t2":"룻은 자기는 이방 여인이라고 했어요. 그런데 보아스가 어찌하여 자기에게 은혜를 베풀고 자기를 돌아보느냐고 물었어요.","t3":"룻은 자기는 이방 여인인데 보아스가 어찌하여 자기에게 은혜를 베풀며 자기를 돌아보느냐고 물었다."},"ref":"룻 2:10","open":"룻 2:10"}]},"today":[{"q":"이삭을 줍는 건 남의 밭에서 곡식을 가져가는 것 아니에요?","a":{"t1":"룻은 베는 사람들을 따라 이삭을 줍게 해 달라고 청했어요. 밭 주인 보아스는 다른 밭으로 가지 말고 여기서 주우라고 했어요.","t2":"룻은 베는 사람들을 따라 곡식 단 사이에서 이삭을 줍게 해 달라고 청했어요. 밭 주인 보아스는 다른 밭으로 가지 말고 자기 밭에 있으라고 했어요. 하나님의 율법에도, 곡식을 벨 때 떨어진 것은 줍지 말고 가난한 사람과 나그네를 위해 남겨 두라는 말씀이 있어요.","t3":"룻은 베는 사람들을 따라 곡식 단 사이에서 이삭을 줍게 해 달라고 청했고, 밭 주인 보아스는 다른 밭으로 가지 말고 자기 밭에 있으라고 했다. 레위기에는 곡식을 벨 때 밭 모퉁이까지 다 베지 말고 떨어진 것을 줍지 말며, 가난한 사람과 나그네를 위해 남겨 두라는 하나님의 말씀이 있다. 신명기에는 밭에서 잊어버린 곡식 단도 다시 가서 가져오지 말고 나그네와 고아와 과부를 위해 두라고 했다. 성경은 여기까지 말한다."},"refs":["룻 2:7-8","레 23:22","신 24:19"]},{"q":"슬퍼서 자기를 마라라고 부르라고 했던 나오미는 그 뒤에 어떻게 되었어요?","a":{"t1":"나중에 룻이 아들을 낳았어요. 여인들은 여호와께서 나오미에게 기업 무를 사람이 없게 하지 않으셨다며 여호와를 찬송했어요. 나오미는 아기를 품에 안고 길렀어요.","t2":"나오미는 전능자가 자기를 몹시 괴롭게 하셨고, 여호와께서 자기를 빈손으로 돌아오게 하셨다고 말했어요. 그 뒤에 룻이 아들을 낳자, 여인들은 여호와께서 나오미에게 기업 무를 사람이 없게 하지 않으셨다고 하며 여호와를 찬송했어요. 나오미는 아기를 품에 안고 기르는 사람이 되었어요.","t3":"나오미는 베들레헴에 돌아와, 전능자가 자기를 몹시 괴롭게 하셨고 여호와께서 자기를 빈손으로 돌아오게 하셨다고 말했다. 그 뒤에 룻이 아들을 낳자, 여인들은 여호와께서 오늘 나오미에게 기업 무를 사람이 없게 하지 않으셨다고 하며 여호와를 찬송했다. 그 아이가 나오미의 생명을 회복시키고 노년을 봉양할 것이라고 했다. 나오미는 아기를 품에 안고 기르는 사람이 되었다. 성경은 여기까지 말한다."},"refs":["룻 1:20-21","룻 4:14-16"]}],"help":{"who":"룻과 나오미","steps":[{"kind":"do","after":4,"title":"떤 보리 챙겨 나르기","basis":"룻 2:17-18","text":{"t1":"룻은 저녁까지 이삭을 줍고, 주운 것을 떨었어요. 보리가 한 에바쯤 되었어요. 룻이 그 보리를 들고 성읍의 시어머니에게 가는 일을 도와요.","t2":"룻은 저녁까지 밭에서 이삭을 주운 뒤 그것을 떨었어요. 보리가 한 에바쯤 되었어요. 룻은 그 보리를 들고 성읍으로 가서 시어머니에게 보이고, 먹고 남긴 것도 드려요. 우리는 이삭을 줍지 않고, 룻이 떤 보리를 챙겨 가는 일만 도와요.","t3":"룻은 저녁이 될 때까지 밭에서 이삭을 주운 뒤 그것을 떨었고, 보리가 한 에바쯤 되었다(2:17). 룻은 그 보리를 들고 성읍으로 가서 시어머니에게 보이고, 식사 때 배불리 먹고 남겨 둔 것도 꺼내 드렸다(2:18). 탐험대는 이삭을 줍지 않고, 룻이 떤 보리를 챙겨 성읍으로 가져가는 일만 돕는다."},"tasks":["룻이 떤 보리를 한데 모으기","보리를 함께 들어 주기","성읍까지 같이 걸어가기"],"done":{"who":"choeon","text":"보리가 한 에바쯤이나 돼. 룻이 이제 시어머니에게 보여 드리러 가."}},{"kind":"ask","after":"gates","title":"보아스의 밭에서 주운 일은 무슨 뜻이에요?","basis":"룻 2:19-20","by":"나오미","ask":{"who":"hyu","text":"룻이 보아스의 밭에서 이삭을 주운 일은 무슨 뜻이 있어요?"},"answer":{"t1":"나오미는 룻을 돌보아 준 그 사람에게 여호와의 복이 있기를 빌었어요. 그 사람은 자기들의 가까운 친족이고, 기업을 무를 사람 가운데 하나라고 말했어요.","t2":"룻이 오늘 일하게 해 준 사람이 보아스라고 하자, 나오미는 그에게 여호와의 복이 있기를 빌었어요. 그리고 그 사람은 자기들의 가까운 친족이며, 자기들의 기업을 무를 사람 가운데 하나라고 말했어요.","t3":"룻이 오늘 일하게 해 준 사람의 이름이 보아스라고 하자, 나오미는 그에게 여호와의 복이 있기를 빌었다. 그리고 그 사람은 자기들의 가까운 친족이며, 자기들의 기업을 무를 사람 가운데 하나라고 말했다."},"read":{"t1":{"type":"find","ref":"룻 2:20","prompt":"성경책에서 룻기 2장 20절을 찾아 읽어 보세요.","confirm":{"prompt":"나오미는 보아스가 자기들에게 어떤 사람이라고 했나요?","options":[{"label":"가까운 친족이며 기업을 무를 사람 가운데 하나","ok":true},{"label":"모압 땅에서 함께 지내던 오랜 이웃 사람","basis":"본문에 없음"},{"label":"베들레헴 성문에 앉은 장로 가운데 하나","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"룻 4:13-14","prompt":"성경책에서 룻기 4장 13절과 14절을 읽어 보세요.","confirm":{"prompt":"룻이 아들을 낳자 여인들이 여호와를 찬송한 까닭은 무엇인가요?","options":[{"label":"여호와께서 오늘 나오미에게 기업 무를 사람이 없게 하지 않으셨기 때문에","ok":true},{"label":"나오미가 모압으로 돌아가지 않고 베들레헴에서 살게 되었기 때문에","basis":"본문에 없음"},{"label":"보아스가 성읍의 장로들을 불러 큰 잔치를 베풀었기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["룻 2:20","룻 4:14"],"prompt":"룻기 2장 20절과 4장 14절을 함께 찾아 읽어 보자.","confirm":{"prompt":"나오미가 보아스에 대해 한 말과, 아기가 태어난 뒤 여인들이 한 말을 이어 읽으면 두 곳에 같은 말이 나온다. 그것은 무엇인가?","options":[{"label":"기업 무를 사람이다. 나오미는 보아스가 그 가운데 하나라고 했고, 여인들은 여호와께서 나오미에게 기업 무를 사람이 없게 하지 않으셨다고 찬송했다","ok":true},{"label":"친족이다. 나오미는 보아스가 자기들의 가까운 친족이라고 했고, 여인들은 아기가 나오미의 친족이 되었다고 찬송했다","basis":"본문에 없음"},{"label":"복이다. 나오미는 보아스에게 여호와의 복이 있기를 빌었고, 여인들은 아기에게 여호와의 복이 있기를 빌었다","basis":"본문에 없음"}]}}}}]}},"has3d":false,"epic":false},"OT-24":{"id":"OT-24","era":6,"title":"한나의 기도와 사무엘을 부르심","ref":"삼상 1:9-28","place":"실로 여호와의 집, 라마","review":{"required":false,"topics":[],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"삼상 1:9-11","open":"삼상 1:11","focus":"hannah","text":{"t1":"한나는 실로에서 울며 여호와께 기도했어요. 아들을 주시면 어떻게 하겠다고 서원했는지는 성경에서 찾아봐요.","t2":"실로에서 먹고 마신 뒤에 한나가 일어났어요. 제사장 엘리는 여호와의 전 문설주 옆에 놓인 의자에 앉아 있었어요. 한나는 마음이 괴로워서 여호와께 기도하며 통곡했어요. 아들을 주시면 그의 평생을 여호와께 드리고 머리에 삭도를 대지 않겠다고 서원했어요.","t3":"그들이 실로에서 먹고 마신 뒤에 한나가 일어났고, 그때 엘리 제사장은 여호와의 전 문설주 옆에 놓인 의자에 앉아 있었다. 한나는 마음이 괴로워 여호와께 기도하며 통곡했다. 그는 만군의 여호와께서 여종의 고통을 돌아보시고 자기를 잊지 않으셔서 아들을 주시기를 구하며 서원했는데, 무엇을 서원했는지는 11절에 있다."},"say":{"who":"hyu","text":"여기는 실로야. 엘리 제사장이 문설주 곁 의자에 앉아 있어. 적어 둘게."}},{"ref":"삼상 1:12-18","focus":"eli","text":{"t1":"한나가 속으로 기도하자 엘리는 한나가 취한 줄로 알았어요. 한나의 대답을 들은 엘리는 평안히 가라고 했어요.","t2":"한나가 오래 기도하는 동안 엘리는 한나의 입을 지켜보았어요. 한나는 속으로 말해서 입술만 움직이고 소리가 들리지 않았어요. 엘리와 한나가 무슨 말을 어떤 차례로 주고받았는지는 13절부터 18절까지 읽어 봐요.","t3":"한나가 여호와 앞에서 오래 기도하는 동안 엘리가 그의 입을 지켜보았다. 한나가 속으로 말하여 입술만 움직이고 소리는 들리지 않았으므로, 엘리는 그가 취한 줄로 생각하고 언제까지 취해 있겠느냐며 포도주를 끊으라고 했다. 한나는 자기는 마음이 슬픈 여자이며, 포도주나 독주를 마신 것이 아니라 여호와 앞에 심정을 쏟아 놓았을 뿐이라고 대답했다. 원통함과 괴로움이 많아서 지금까지 말한 것이니 악한 여자로 여기지 말아 달라고 했다. 엘리는 평안히 가라고 하며 이스라엘의 하나님이 그가 구한 것을 허락하시기를 빌었다. 한나는 가서 음식을 먹었고, 얼굴에 다시는 근심하는 빛이 없었다."},"say":{"who":"choeon","text":"한나는 입술만 움직이고 소리는 안 들려."}},{"ref":"삼상 1:19-28","open":"삼상 1:27","focus":"child","text":{"t1":"여호와께서 한나를 생각하셔서 한나는 아들 사무엘을 낳았어요. 젖을 뗀 뒤 한나는 아이를 데리고 실로 여호와의 집에 갔어요.","t2":"그들은 라마의 집으로 돌아갔고, 여호와께서 한나를 생각하셨어요. 한나는 아들을 낳아 사무엘이라 이름 지었는데, 왜 그렇게 지었는지는 20절에 있어요. 젖을 뗀 뒤에 한나는 어린 아이를 데리고 실로 여호와의 집으로 가서 엘리에게 나아갔어요. 한나는 이 아이를 위해 기도했더니 여호와께서 허락하셨다고 하며, 그의 평생을 여호와께 드린다고 말했어요.","t3":"그들은 아침 일찍 일어나 여호와 앞에 경배하고 라마의 집으로 돌아갔으며, 여호와께서 한나를 생각하셨다. 한나는 잉태하여 때가 되자 아들을 낳고, 여호와께 그를 구했다 하여 이름을 사무엘이라 했다. 엘가나와 온 집이 해마다 드리는 제사를 드리러 올라갈 때 한나는 올라가지 않고, 아이가 젖을 뗄 때까지 기다렸다. 젖을 뗀 뒤에 한나는 수소 세 마리, 가루 한 에바, 포도주 한 가죽부대를 가지고 아이와 함께 실로 여호와의 집으로 올라갔는데, 아이는 어렸다. 그들은 수소를 잡고 아이를 엘리에게 데려갔다. 한나는 자기가 엘리 곁에 서서 여호와께 기도하던 그 여자라고 밝혔다. 한나가 아이를 두고 엘리에게 한 말은 27절과 28절에서 직접 읽어 보자."},"say":{"who":"onwoo","text":"한나가 엘리에게 한 말은 27절과 28절에 있어. 성경책에서 확인해 보자."}},{"ref":"삼상 3:1-7","open":"삼상 3:4","focus":"lamp","text":{"t1":"어린 사무엘은 엘리 곁에서 여호와를 섬겼어요. 여호와께서 부르시자 사무엘은 엘리가 부른 줄 알고 달려갔어요.","t2":"어린 사무엘이 엘리 앞에서 여호와를 섬기던 그때에는 여호와의 말씀이 드물었어요. 엘리는 눈이 어두워져 자기 처소에 누웠고, 사무엘은 하나님의 궤가 있는 여호와의 전 안에 누워 있었어요. 여호와께서 사무엘을 부르시자 사무엘은 엘리에게 달려가서, 부르셔서 왔다고 했어요. 엘리는 부르지 않았으니 다시 누우라고 했고, 두 번째에도 그렇게 했어요.","t3":"어린 사무엘은 엘리 앞에서 여호와를 섬겼다. 그 시절에는 여호와의 말씀이 드물었고 이상도 흔히 보이지 않았다. 눈이 점점 어두워져 잘 보지 못하는 엘리는 자기 처소에 누웠고, 하나님의 등불은 아직 꺼지지 않았으며, 사무엘은 하나님의 궤가 있는 여호와의 전 안에 누워 있었다. 여호와께서 사무엘을 부르시자 그는 자기가 여기 있다고 대답하고 엘리에게 달려가서, 부르셨기에 왔다고 했다. 엘리는 부르지 않았으니 다시 누우라고 했다. 여호와께서 다시 부르셨을 때에도 사무엘은 일어나 엘리에게 갔고, 엘리는 같은 대답을 했다. 이때 사무엘은 여호와를 아직 알지 못했고, 여호와의 말씀이 그에게 나타난 적도 아직 없었다."},"say":{"who":"choeon","text":"사무엘이 일어나서 엘리에게 달려가!"}},{"ref":"삼상 3:8-10","open":"삼상 3:10","focus":"samuel","text":{"t1":"여호와께서 세 번째로 부르시자 엘리는 여호와께서 부르시는 줄 깨달았어요. 다시 부르실 때 사무엘은 말씀하시라고, 주의 종이 듣겠다고 대답했어요.","t2":"여호와께서 세 번째로 부르셨을 때에도 사무엘은 엘리에게 갔어요. 엘리는 사무엘에게, 다시 부르시면 말씀하시라고, 주의 종이 듣겠다고 말하라고 일러 주었는데, 왜 그렇게 일러 주었는지는 8절에 있어요. 사무엘은 가서 자기 자리에 누웠어요. 여호와께서 전처럼 사무엘의 이름을 부르시자 사무엘은 말씀하시라고, 주의 종이 듣겠다고 대답했어요.","t3":"여호와께서 세 번째로 사무엘을 부르셨고, 그는 또 일어나 엘리에게 가서 부르셨기에 왔다고 했다. 엘리는 이 아이를 부르신 분이 여호와이신 줄을 깨닫고, 가서 누웠다가 그분이 부르시면 여호와께 말씀하시기를 청하고 주의 종이 듣겠다고 말하라고 일렀다. 사무엘은 가서 자기 처소에 누웠다. 여호와께서 오셔서 서시고 전과 같이 사무엘의 이름을 거듭 부르시자, 사무엘은 말씀하시라고, 주의 종이 듣겠다고 대답했다."},"say":{"who":"hyu","text":"첫 번째, 두 번째, 세 번째. 세 번째에 엘리가 사무엘에게 할 말을 일러 줬어. 적어 둘게."}},{"ref":"삼상 3:11-18","open":"삼상 3:11-14","focus":"eli","text":{"t1":"여호와께서는 엘리의 집에 대한 일을 사무엘에게 말씀하셨어요. 아침에 사무엘은 그 말씀을 하나도 숨기지 않고 엘리에게 전했어요.","t2":"여호와께서는 사무엘에게, 엘리의 집에 대해 말씀하신 것을 다 이루겠다고 하셨어요. 엘리의 아들들이 저주를 스스로 불러오는데도 엘리가 막지 않았기 때문이라고 하셨어요. 사무엘은 아침까지 누워 있다가 여호와의 집 문을 열었지만, 자기가 받은 이상을 엘리에게 말하기를 두려워했어요. 엘리가 숨기지 말라고 하자 사무엘은 다 말했고, 엘리는 여호와이시니 선하게 여기시는 대로 하실 것이라고 했어요.","t3":"여호와께서는 사무엘에게, 이스라엘 가운데 한 일을 행하겠으며 그것을 듣는 사람마다 두 귀가 울릴 것이라고 하셨다. 엘리의 집을 두고 말씀하신 것을 그날에 처음부터 끝까지 다 이루겠다고 하셨다. 엘리가 아는 죄악, 곧 아들들이 저주를 스스로 불러오는데도 그가 막지 않은 일 때문에 그 집을 영원히 심판하겠다고 이미 그에게 일렀으며, 엘리 집의 죄악은 제물로도 예물로도 영원히 속함을 얻지 못한다고 맹세했다고 하셨다. 사무엘은 아침까지 누워 있다가 여호와의 집 문을 열었지만, 자기가 받은 이상을 엘리에게 말하기를 두려워했다. 엘리가 그를 불러 하나도 숨기지 말라고 하자 사무엘은 낱낱이 말하고 조금도 숨기지 않았다. 엘리는 그분은 여호와이시니 선하게 여기시는 대로 하실 것이라고 말했다."},"say":{"who":"onwoo","text":"하나님이 사무엘에게 하신 말씀은 우리가 지어내면 안 돼. 11절부터 14절까지 성경책에서 읽어 보자."}},{"ref":"삼상 3:19-21","focus":"samuel","text":{"t1":"사무엘은 자랐고, 여호와께서 사무엘과 함께 계셨어요. 온 이스라엘이 사무엘을 무엇으로 알게 되었는지는 성경에서 찾아봐요.","t2":"사무엘이 자라는 동안 여호와께서 그와 함께 계셔서 그의 말이 하나도 땅에 떨어지지 않게 하셨어요. 단에서 브엘세바까지 온 이스라엘이 사무엘이 여호와의 선지자로 세워진 줄을 알았어요. 여호와께서는 실로에서 사무엘에게 여호와의 말씀으로 자기를 나타내셨어요.","t3":"사무엘이 자랄 때 여호와께서 그와 함께 계셔서 그가 한 말이 하나도 땅에 떨어지지 않게 하셨다. 단에서 브엘세바까지 온 이스라엘이, 사무엘이 여호와의 선지자로 세워진 줄을 알았다. 그 뒤 여호와께서 어디에서 어떻게 자기를 나타내셨는지는 21절에 있다."},"say":{"who":"hyu","text":"단에서 브엘세바까지 온 이스라엘이 사무엘을 알게 됐어. 일지에 적었어."}}],"gates":{"t1":[{"type":"find","ref":"삼상 3:5","prompt":"성경책에서 사무엘상 3장 5절을 찾아 읽어 보세요.","confirm":{"prompt":"사무엘이 달려와 자기를 부르셨느냐고 하자, 엘리는 뭐라고 했나요?","options":[{"label":"부르지 않았으니 다시 누우라고 했어요","ok":true},{"label":"어서 일어나 성전 문을 열라고 했어요","basis":"본문에 없음"},{"label":"등불을 끄고 자라고 했어요","basis":"본문에 없음"}]}},{"type":"multi","ref":"삼상 1:11","prompt":"성경책에서 사무엘상 1장 11절을 찾아 읽어 보세요.","confirm":{"prompt":"한나가 아들을 주시면 하겠다고 서원한 것을 모두 고르세요.","options":[{"label":"아이를 평생 여호와께 드리겠다고 했어요","ok":true},{"label":"아이를 엘리의 아들로 삼게 하겠다고 했어요","basis":"본문에 없음"},{"label":"아이의 머리에 삭도를 대지 않겠다고 했어요","ok":true},{"label":"아이를 데리고 먼 나라로 떠나겠다고 했어요","basis":"본문에 없음"}]}}],"t2":[{"type":"find","ref":"삼상 1:19-20","prompt":"성경책에서 사무엘상 1장 19절과 20절을 읽어 보세요.","confirm":{"prompt":"한나가 아들의 이름을 사무엘이라고 한 까닭은 무엇인가요?","options":[{"label":"여호와께 그 아이를 구했기 때문에","ok":true},{"label":"여호와께서 한나를 생각해 주셨기 때문에","basis":"본문에 없음"},{"label":"아이를 평생 여호와께 드리겠다고 서원했기 때문에","basis":"삼상 1:11"}]},"inStory":"아이를 여호와께 구한 일(1:11, 1:27)은 이야기에 남아 낱말이 겹친다. 그것이 이름의 까닭이라는 것(1:20)은 이야기 글에서 뺐고, 맞지 않는 보기 둘(1:19 여호와께서 생각하심, 1:11 서원)도 이야기에 나오는 일이라 이야기만으로는 가려지지 않는다"},{"type":"order","ref":"삼상 1:12-18","prompt":"성경책에서 사무엘상 1장 12절부터 18절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["한나가 길게 기도하는 사이 엘리가 한나의 입을 눈여겨보았다","엘리가 한나를 취한 사람으로 생각했다","한나가 여호와 앞에 마음을 쏟아 놓았을 뿐이라고 대답했다","엘리가 평안히 가라고 하며 한나를 위해 빌었다","한나가 가서 먹었고 얼굴에 근심이 사라졌다"]}],"t3":[{"type":"find","refs":["삼상 1:11","삼상 1:28"],"prompt":"사무엘상 1장 11절과 28절을 함께 찾아 읽어 보자.","confirm":{"prompt":"한나의 서원과 아이를 데려온 날의 말을 이어 읽으면 어떠한가?","options":[{"label":"한나는 아들을 주시면 평생 여호와께 바치겠다고 서원했고, 젖을 뗀 아이를 데려와서 그 말대로 아이를 여호와께 바친다고 했다","ok":true},{"label":"한나는 아들을 주시면 평생 여호와께 바치겠다고 서원했지만, 젖을 뗀 아이를 데려와서는 몇 해 동안만 여호와께 맡긴다고 했다","basis":"본문에 없음"},{"label":"한나는 아들을 주시면 해마다 한 번 여호와의 집에 데려오겠다고 서원했고, 젖을 뗀 아이를 데려와서 그 말대로 하겠다고 했다","basis":"본문에 없음"}]}},{"type":"match","refs":["삼상 1:17","삼상 1:22","삼상 1:27"],"prompt":"사무엘상 1장 17절, 22절, 27절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"삼상 1:17","text":"엘리가, 하나님께서 한나가 구한 것을 들어주시기를 빌었다"},{"ref":"삼상 1:22","text":"한나가 아이가 젖을 떼면 데려가 여호와 앞에 영영 있게 하겠다고 했다"},{"ref":"삼상 1:27","text":"한나가 이 아이를 두고, 여호와께서 자기가 구한 것을 들어주셨다고 말했다"}],"after":"세 곳을 이으면, 엘리는 한나의 기도가 이루어지기를 빌었고, 한나는 젖을 뗀 아이를 여호와 앞에 두겠다고 했으며, 아이를 데려온 날 여호와께서 그 기도를 들어주셨다고 말했다."}]},"cards":[{"ref":"삼상 1:27","title":"기도하여 구한 아이"},{"ref":"삼상 3:10","title":"주의 종이 듣겠나이다"}],"close":{"t1":{"kind":"prayer","text":"하나님, 한나의 기도와 사무엘을 부르신 이야기를 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 사무엘상 3장 1절부터 10절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"삼상 1:9-28, 3:1-21에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 비상 착륙 때 타임머신 받침 하나가 부서졌어요. 대신 받칠 재료를 하나 찾아봐요.","t2":"최현 박사예요. 비상 착륙 때 타임머신을 받치던 받침 하나가 부서졌어요. 이 시대에는 부속이 없으니 이곳에서 대신 쓸 재료를 하나 찾아야 해요. 여호와의 집과 그 안의 것에는 손대지 말아요.","t3":"최현이다. 비상 착륙 때 타임머신을 받치던 받침 하나가 부서졌다. 이 시대에는 부속을 구할 수 없으니 이곳에서 대신 쓸 재료를 하나 찾아야 한다. 실로의 여호와의 집과 거기에 속한 것에는 손대지 말자."},"materials":[{"key":"angularstone","name":"모난 돌","basis":"삼상 1:19","use":"모난 돌을 받침 대신 쓸 수 있어요.","how":"라마로 가는 길가의 빈 땅에서 줍는다. 실로의 여호와의 집과 거기에 속한 것, 제물로 가져온 것에는 손대지 않는다.","line":"모난 돌을 주웠어! 라마로 가는 길가에 있었어."}],"companion":{"who":"사무엘","ref":"삼상 3:21","when":"after","talks":[{"ask":{"who":"choeon","text":"처음에 부르시는 소리를 들었을 때 뭐라고 대답했어요?"},"answer":{"t1":"사무엘은 자기가 여기 있다고 대답했어요. 그리고 엘리에게 달려가서, 엘리가 불러서 왔다고 말했어요.","t2":"사무엘은 자기가 여기 있다고 대답했어요. 그리고 엘리에게 달려가서, 엘리가 자기를 불렀기에 여기 왔다고 말했어요.","t3":"사무엘은 자기가 여기 있다고 대답했다. 그리고 엘리에게 달려가서, 엘리가 자기를 불렀기에 여기 왔다고 말했다."},"ref":"삼상 3:4-5","open":"삼상 3:4"},{"ask":{"who":"hyu","text":"세 번 부르신 뒤에 다시 부르셨을 때는 뭐라고 대답했어요?"},"answer":{"t1":"사무엘은 말씀하시라고, 주의 종이 듣겠다고 대답했어요.","t2":"하나님이 전처럼 사무엘의 이름을 부르셨어요. 그러자 사무엘은 말씀하시라고, 주의 종이 듣겠다고 대답했어요.","t3":"하나님이 전과 같이 그의 이름을 부르셨을 때, 사무엘은 말씀하시라고, 주의 종이 듣겠다고 대답했다."},"ref":"삼상 3:10","open":"삼상 3:10"}]},"today":[{"q":"소리 내지 않고 마음속으로 기도해도 돼요?","a":{"t1":"한나는 속으로 기도해서 입술만 움직이고 소리는 들리지 않았어요. 한나는 나중에, 여호와께서 자기가 구한 것을 허락하셨다고 말했어요.","t2":"성경은 한나가 속으로 말해서 입술만 움직이고 소리는 들리지 않았다고 기록해요. 한나는 여호와 앞에 마음을 쏟아 놓았다고 했어요. 나중에 한나는, 이 아이를 위해 기도했더니 여호와께서 구한 것을 허락하셨다고 말했어요. 성경은 여기까지 말해요.","t3":"성경은 한나가 속으로 말하여 입술만 움직이고 소리는 들리지 않았다고 기록한다. 한나는 엘리에게 자기가 여호와 앞에 심정을 쏟아 놓았다고 대답했다. 그 뒤에 여호와께서 한나를 생각하셨고, 한나는 이 아이를 위해 기도했더니 여호와께서 구한 것을 허락하셨다고 말했다. 성경은 여기까지 말한다."},"refs":["삼상 1:13-15","삼상 1:19-20","삼상 1:27"]},{"q":"사무엘은 왜 하나님이 부르시는 줄 몰랐어요?","a":{"t1":"그때 사무엘은 아직 여호와를 알지 못했어요. 여호와의 말씀이 아직 사무엘에게 나타난 적이 없었어요.","t2":"성경은 그때 사무엘이 아직 여호와를 알지 못했고, 여호와의 말씀이 그에게 나타난 적도 아직 없었다고 기록해요. 그 시절에는 여호와의 말씀이 드물었다고도 해요. 세 번째로 부르셨을 때 엘리가, 아이를 부르신 분이 여호와이심을 깨닫고 사무엘에게 대답할 말을 일러 주었어요.","t3":"성경은 그때 사무엘이 아직 여호와를 알지 못했고, 여호와의 말씀이 그에게 나타난 적도 아직 없었다고 기록한다. 그 시절에는 여호와의 말씀이 드물었고 이상도 흔히 보이지 않았다. 세 번째로 부르셨을 때 엘리는 이 아이를 부르신 분이 여호와이심을 깨닫고 대답할 말을 일러 주었다. 성경은 여기까지 말한다."},"refs":["삼상 3:1","삼상 3:7","삼상 3:8-9"]}],"help":{"who":"실로에 올라온 한나와 그 집 식구들","steps":[{"kind":"watch","after":0,"title":"곁에서 보기 · 한나의 기도","basis":"삼상 1:10-11","text":{"t1":"한나는 마음이 괴로워서 여호와께 기도하며 울었어요. 우리는 끼어들지 않고 떨어진 곳에서 조용히 봐요.","t2":"한나는 괴로운 마음으로 여호와께 기도하며 크게 울었어요. 아들을 주시면 그의 평생을 여호와께 바치겠다고 서원했어요. 기도와 서원은 한나가 여호와께 드린 것이에요. 우리는 끼어들지 않고 떨어진 곳에서 조용히 봐요.","t3":"한나는 괴로운 마음으로 여호와께 기도하며 크게 울었고, 여호와께 서원했다(1:10-11). 기도와 서원은 한나가 여호와 앞에서 한 일이다. 탐험대는 끼어들지 않고, 여호와의 전에서 떨어진 곳에서 조용히 지켜본다."}},{"kind":"do","after":1,"title":"라마로 돌아갈 짐 꾸리기","basis":"삼상 1:19","text":{"t1":"아침이 되면 이 집 식구들은 라마의 집으로 돌아가요. 우리는 여호와의 집에서 떨어진 곳에서, 식구들이 가져갈 짐을 꾸려 두며 도와요.","t2":"실로에 올라온 이 집 식구들은 아침 일찍 경배를 드린 뒤 라마의 집으로 돌아가요. 우리는 여호와의 집에서 떨어진 곳에서, 식구들이 가져갈 짐을 꾸려 두며 도와요. 짐을 꾸리는 것은 우리가 하는 일이에요.","t3":"이 집 식구들은 아침 일찍 경배를 드린 뒤 라마의 집으로 돌아간다(1:19). 탐험대는 여호와의 집과 제물에서 떨어진 곳에서, 식구들이 가져갈 짐을 꾸려 두며 돕는다. 이것은 성경에 적힌 일이 아니라 탐험대 이야기다. 짐을 꾸리는 것은 탐험대의 일이고, 한나와 엘가나에게는 본문에 없는 일을 시키지 않는다. 경배하는 일에는 끼지 않는다."},"tasks":["짐 보따리 묶기","물건 한데 챙기기","떠날 자리 정리하기"],"done":{"who":"choeon","text":"짐을 다 꾸렸어. 이 식구들은 라마로 돌아갈 거야."}},{"kind":"watch","after":2,"title":"곁에서 보기 · 실로로 데려온 아이","basis":"삼상 1:24-25","text":{"t1":"젖을 뗀 뒤 한나는 어린 사무엘을 데리고 실로 여호와의 집으로 갔어요. 가져온 제물에는 우리가 손대지 않아요.","t2":"젖을 뗀 뒤 한나는 수소 세 마리, 가루 한 에바, 포도주 한 부대를 챙겨 어린 아이와 함께 실로 여호와의 집에 갔어요. 그들은 수소를 잡고 아이를 엘리에게 데려갔어요. 제물을 드리는 일에는 우리가 손대지 않고 곁에서 봐요.","t3":"젖을 뗀 뒤 한나는 수소 세 마리, 가루 한 에바, 포도주 한 부대를 챙겨 아이와 함께 실로 여호와의 집으로 올라갔다. 아이는 아직 어렸다(1:24). 그들은 수소를 잡고 아이를 엘리에게 데려갔다(1:25). 제물과 여호와의 집에 속한 일에는 탐험대가 손대지 않고 곁에서 본다."}},{"kind":"ask","after":"gates","title":"사무엘을 부르신 일은 무슨 뜻이에요?","basis":"삼상 3:19-21","by":"최현 박사","ask":{"who":"choeon","text":"하나님이 어린 사무엘을 부르신 일은 무슨 뜻이에요?"},"answer":{"t1":"성경은 사무엘이 자라는 동안 여호와께서 사무엘과 함께 계셨다고 말해요. 온 이스라엘이 사무엘이 여호와의 선지자로 세워진 줄을 알았다고 해요(삼상 3:19-20).","t2":"그 시절에는 여호와의 말씀이 드물었다고 성경은 적어요(삼상 3:1). 사무엘이 자라는 동안 여호와께서 함께 계셔서 그가 한 말이 하나도 헛되이 땅에 떨어지지 않게 하셨고, 단에서 브엘세바까지 온 이스라엘이 사무엘이 여호와의 선지자로 세워진 줄을 알았어요(삼상 3:19-20). 성경은 여기까지 말해요.","t3":"그 시절에는 여호와의 말씀이 드물고 이상도 흔히 보이지 않았다(삼상 3:1). 사무엘이 자랄 때 여호와께서 함께하셔서, 그가 한 말이 하나도 헛되이 땅에 떨어지지 않게 하셨다. 단에서 브엘세바까지 온 이스라엘이 사무엘이 여호와의 선지자로 세워진 줄을 알았다(삼상 3:19-20). 여호와께서는 다시 실로에 나타나셨고, 거기서 말씀으로 자신을 사무엘에게 알리셨다(삼상 3:21). 성경은 여기까지 말한다."},"read":{"t1":{"type":"find","ref":"삼상 3:20","prompt":"성경책에서 사무엘상 3장 20절을 찾아 읽어 보세요.","confirm":{"prompt":"온 이스라엘은 사무엘이 무엇으로 세워진 줄 알았나요?","options":[{"label":"여호와의 선지자","ok":true},{"label":"이스라엘의 왕","basis":"본문에 없음"},{"label":"군대의 장수","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"삼상 3:8-9","prompt":"성경책에서 사무엘상 3장 8절과 9절을 읽어 보세요.","confirm":{"prompt":"엘리가 사무엘에게, 다시 부르시면 말씀하시라고, 주의 종이 듣겠다고 대답하라고 일러 준 까닭은 무엇인가요?","options":[{"label":"부르시는 분이 여호와이심을 엘리가 알아차렸기 때문에","ok":true},{"label":"사무엘이 꿈을 꾸었다고 엘리가 생각했기 때문에","basis":"본문에 없음"},{"label":"엘리가 눈이 어두워 자기 대신 사무엘에게 듣게 하려고","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["삼상 3:1","삼상 3:21"],"prompt":"사무엘상 3장 1절과 21절을 함께 찾아 읽어 보자.","confirm":{"prompt":"이 이야기의 처음과 끝을 이어 읽으면, 여호와의 말씀은 어떻게 되었는가?","options":[{"label":"처음에는 여호와의 말씀이 드물고 이상도 좀처럼 보이지 않았는데, 끝에는 여호와께서 실로에서 말씀으로 자신을 사무엘에게 알리셨다","ok":true},{"label":"처음에는 여호와의 말씀이 드물고 이상도 좀처럼 보이지 않았는데, 끝에는 여호와께서 꿈으로만 사무엘에게 나타나셨다","basis":"본문에 없음"},{"label":"처음에는 여호와의 말씀이 드물고 이상도 좀처럼 보이지 않았는데, 끝에는 여호와께서 실로를 떠나 다른 곳에서만 나타나셨다","basis":"본문에 없음"}]}}}}]}},"has3d":false,"epic":false},"OT-25":{"id":"OT-25","era":7,"title":"백성이 왕을 구하고 사울이 왕이 됨","ref":"삼상 8:4-22","place":"라마, 미스바","review":{"required":true,"topics":["구약 사건의 신약적 의미(행 13:21)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"삼상 8:4-5","focus":"elders","text":{"t1":"이스라엘의 장로들이 라마로 사무엘을 찾아와, 왕을 세워 달라고 했어요. 누구와 같이 해 달라고 했는지는 성경에서 찾아봐요.","t2":"이스라엘의 장로들이 다 모여서 라마로 사무엘을 찾아왔어요. 장로들은 다른 나라들처럼 자기들을 다스릴 왕을 세워 달라고 했어요. 그렇게 해 달라며 무슨 까닭을 댔는지는 5절에서 찾아봐요.","t3":"이스라엘의 장로들이 다 모여서 라마로 사무엘을 찾아갔다. 그들은 사무엘이 늙었고 그의 아들들이 아버지의 행위를 따르지 않는다고 말하며 왕을 세워 달라고 했다. 무엇과 같이 해 달라고 했는지는 5절에 있다."},"say":{"who":"hyu","text":"여기는 라마야. 장로들이 다 모여서 사무엘 앞에 왔어. 일지에 적어 둘게."}},{"ref":"삼상 8:6-9","open":"삼상 8:7","focus":"samuel","text":{"t1":"사무엘은 그 말을 기뻐하지 않았고, 여호와께 기도했어요. 하나님은 백성의 말을 들어주되, 왕이 어떻게 다스릴지 알려 주라고 하셨어요.","t2":"사무엘은 왕을 달라는 그 말을 기뻐하지 않았고, 여호와께 기도했어요. 하나님은 백성의 말을 다 들어주라고 하셨어요. 다만 엄하게 타이르고 왕이 어떻게 다스릴지 알려 주라고 하셨어요.","t3":"왕을 주어 다스리게 해 달라는 말을 사무엘은 기뻐하지 않았고, 여호와께 기도했다. 여호와께서는 백성이 하는 말을 다 들어주되 엄하게 경고하고, 왕이 그들을 어떻게 다스릴지 알려 주라고 하셨다."},"say":{"who":"onwoo","text":"하나님이 사무엘에게 하신 말씀은 우리가 지어내면 안 돼. 7절부터 성경책에서 직접 읽어 보자."}},{"ref":"삼상 8:10-18","focus":"samuel","text":{"t1":"사무엘은 여호와의 말씀을 백성에게 다 전했어요. 왕은 백성의 아들과 딸을 데려다 일을 시키고, 밭과 양 떼에서도 가져갈 것이라고 했어요.","t2":"사무엘은 왕을 구하는 백성에게 여호와의 말씀을 모두 전했어요. 왕은 아들들을 데려다 병거와 말을 맡기고 자기 밭을 갈게 하며, 딸들을 데려다 요리하고 떡을 굽게 할 것이라고 했어요. 가장 좋은 밭과 포도원을 가져가고, 곡식과 양 떼의 십분의 일도 가져갈 것이라고 했어요. 그날에 백성이 왕 때문에 부르짖어도 여호와께서 응답하지 않으실 것이라고 했어요.","t3":"사무엘은 왕을 구하는 백성에게 여호와의 말씀을 모두 전했다. 왕은 아들들을 데려다 병거와 말을 맡기고 병거 앞에서 달리게 하며, 천부장과 오십부장으로 삼고, 자기 밭을 갈고 추수하게 하고, 병기와 병거의 기구를 만들게 할 것이라고 했다. 딸들은 데려다 향료를 만들고 요리하고 떡을 굽게 할 것이라고 했다. 밭과 포도원과 감람원 가운데 가장 좋은 것을 가져다 신하들에게 주고, 곡식과 포도원 소산의 십분의 일과 양 떼의 십분의 일을 가져가며, 노비와 소년과 나귀도 데려다 자기 일을 시킬 것이라고 했다. 백성은 왕의 종이 되고, 그날에 자기들이 택한 왕 때문에 부르짖어도 여호와께서 응답하지 않으실 것이라고 했다."},"say":{"who":"hyu","text":"아들들, 딸들, 밭과 포도원, 곡식, 양 떼. 사무엘이 말한 차례대로 적고 있어."}},{"ref":"삼상 8:19-22","open":"삼상 8:22","focus":"people","text":{"t1":"백성은 사무엘의 말을 듣지 않고, 그래도 왕이 있어야 한다고 했어요. 하나님은 사무엘에게 그들의 말대로 왕을 세우라고 하셨어요.","t2":"백성은 사무엘의 말을 듣지 않고 그래도 왕이 있어야 한다고 했어요. 다른 나라들처럼 되어, 왕이 자기들을 다스리고 앞에 나가 싸워야 한다고 했어요. 사무엘이 그 말을 다 듣고 여호와께 아뢰자, 하나님은 그들의 말을 들어 왕을 세우라고 하셨어요. 사무엘은 사람들을 저마다 자기 성읍으로 돌려보냈어요.","t3":"백성은 사무엘의 말을 받아들이지 않고, 그래도 자기들에게 왕이 있어야 한다고 했다. 그 왕에게 무엇을 바랐는지는 20절에서 읽어 보자. 사무엘은 백성의 말을 다 듣고 여호와께 아뢰었고, 여호와께서는 그들의 말대로 왕을 세우라고 하셨다. 사무엘은 이스라엘 사람들에게 저마다 자기 성읍으로 돌아가라고 했다."},"say":{"who":"choeon","text":"사무엘이 다 말해 줬는데도, 사람들은 왕이 있어야 한대."}},{"ref":"삼상 10:17-19","open":"삼상 10:18","focus":"samuel","text":{"t1":"사무엘은 미스바에서 백성을 여호와 앞에 불러 모았어요. 그리고 지파대로 여호와 앞에 나오라고 했어요.","t2":"사무엘은 미스바에서 백성을 여호와 앞에 불러 모으고 하나님의 말씀을 전했어요. 하나님은 애굽에서 이스라엘을 인도해 내고 괴롭히던 나라들의 손에서 건져 냈다고 하셨어요. 사무엘은 왕을 세워 달라고 한 백성이 하나님께 어떻게 한 것인지도 말했는데, 그 말은 19절에서 읽어 봐요. 그러고는 지파마다 천 명씩 나뉘어 여호와 앞으로 나오라고 했어요.","t3":"사무엘은 미스바에서 백성을 여호와 앞에 불러 모으고, 이스라엘의 하나님 여호와의 말씀을 전했다. 여호와께서는 애굽에서 이스라엘을 인도해 내시고 애굽 사람의 손과 그들을 압제하던 모든 나라의 손에서 구해 내셨다고 하셨다. 사무엘은 이어서 왕을 세우라고 한 백성이 그날 하나님께 어떻게 한 것인지 말했는데, 그 말은 19절에서 직접 읽어 보자. 그러고는 지파별로 천 명씩 여호와 앞으로 나오라고 했다."},"say":{"who":"hyu","text":"이번에는 미스바야. 라마에서 미스바로, 장소가 바뀌었어."}},{"ref":"삼상 10:20-23","open":"삼상 10:22","focus":"saul","text":{"t1":"베냐민 지파에서, 기스의 아들인 사울이 뽑혔지만 사람들은 사울을 찾지 못했어요. 짐 사이에 숨어 있던 사울을 데려오니 누구보다 어깨 위만큼 더 컸어요.","t2":"사무엘이 모든 지파를 가까이 나오게 하여 뽑았더니, 마침내 기스의 아들인 사울이 뽑혔어요. 그 사이에 누가 뽑혔고, 그 뒤에 무슨 일이 어떤 차례로 있었는지는 20절부터 23절까지 읽어 봐요.","t3":"사무엘이 모든 지파를 가까이 나오게 하니 베냐민 지파가 뽑혔고, 베냐민 지파를 가족별로 나오게 하니 마드리의 가족이, 그 가운데서 기스의 아들 사울이 뽑혔다. 그러나 그를 찾아도 만나지 못했다. 사람들이 그 사람이 여기 왔는지 여호와께 다시 여쭈었고, 여호와께서는 그가 짐 사이에 숨었다고 대답하셨다. 사람들이 달려가 그를 데려왔는데, 백성 가운데 선 그는 누구보다도 어깨 위만큼 더 컸다. 그가 숨은 까닭을 성경은 말하지 않는다."},"say":{"who":"choeon","text":"저기서 사람들이 누군가를 데리고 나온다! 백성 가운데 서니까 정말 커."}},{"ref":"삼상 10:24-25","focus":"saul","text":{"t1":"사무엘은 여호와께서 택하신 사람을 보라고 했어요. 그러자 백성이 다 함께 왕 만세를 외쳤어요.","t2":"사무엘은 모든 백성에게, 여호와께서 택하신 사람을 보라고 했어요. 백성 가운데 그와 같은 사람이 없다고 했어요. 모든 백성이 왕의 만세를 외쳤어요. 사무엘은 나라의 제도를 말해 주고 책에 적어 여호와 앞에 둔 뒤, 백성을 집으로 보냈어요.","t3":"사무엘은 모든 백성에게 여호와께서 택하신 사람을 보라고 하며, 온 백성 가운데 그와 견줄 사람이 없다고 했다. 모든 백성이 왕의 만세를 외쳤다. 사무엘은 나라의 제도를 백성에게 말하고 책에 적어 여호와 앞에 두었으며, 모든 백성을 저마다 집으로 돌려보냈다."},"say":{"who":"onwoo","text":"사무엘이 책에 적어서 어디에 두었는지, 25절에서 확인해 보자."}}],"gates":{"t1":[{"type":"find","ref":"삼상 8:5","prompt":"성경책에서 사무엘상 8장 5절을 찾아 읽어 보세요.","confirm":{"prompt":"장로들은 사무엘에게 누구와 같이 왕을 세워 달라고 했나요?","options":[{"label":"다른 모든 나라와 같이","ok":true},{"label":"애굽 사람들과 같이","basis":"본문에 없음"},{"label":"옛 조상들과 같이","basis":"본문에 없음"}]}},{"type":"multi","ref":"삼상 8:13","prompt":"성경책에서 사무엘상 8장 13절을 찾아 읽어 보세요.","confirm":{"prompt":"왕이 백성의 딸들을 데려다 시킬 일이라고 한 것을 모두 고르세요.","options":[{"label":"향료 만들기","ok":true},{"label":"병거 앞에서 달리기","basis":"삼상 8:11"},{"label":"요리하기","ok":true},{"label":"물 긷기","basis":"본문에 없음"},{"label":"떡 굽기","ok":true}]}}],"t2":[{"type":"find","ref":"삼상 8:4-5","prompt":"성경책에서 사무엘상 8장 4절과 5절을 읽어 보세요.","confirm":{"prompt":"장로들이 사무엘에게 왕을 세워 달라고 하면서 말한 까닭은 무엇인가요?","options":[{"label":"사무엘은 늙었고, 그 아들들은 브엘세바에서 사사로 있었기 때문에","basis":"삼상 8:2"},{"label":"사무엘은 늙었고, 그 아들들은 아직 어려서 다스릴 수 없었기 때문에","basis":"본문에 없음"},{"label":"사무엘은 늙었고, 그 아들들은 사무엘이 걸어온 길을 따르지 않았기 때문에","ok":true}]}},{"type":"order","ref":"삼상 10:20-23","prompt":"성경책에서 사무엘상 10장 20절부터 23절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["모든 지파 가운데 베냐민 지파가 뽑혔다","베냐민 지파의 가족들 가운데 마드리의 가족이 뽑혔다","사울이 뽑혔지만 사람들이 그를 찾지 못했다","사람들이 여호와께 그 사람이 여기 왔는지 다시 여쭈었다","사람들이 달려가 사울을 데려오니 누구보다 어깨 위만큼 더 컸다"]}],"t3":[{"type":"find","refs":["삼상 8:5","삼상 8:20"],"prompt":"사무엘상 8장 5절과 20절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳에 공통으로 나오는, 백성이 바란 모습은 무엇인가?","options":[{"label":"다른 나라들을 다스리는 것이다. 5절에서는 나라들 위에 설 왕을, 20절에서는 나라들을 쳐서 이겨 줄 왕을 구했다","basis":"본문에 없음"},{"label":"모든 나라와 같이 되는 것이다. 5절에서는 자기들을 다스릴 왕을, 20절에서는 다스리고 앞서 나가 싸워 줄 왕을 구했다","ok":true},{"label":"사무엘이 다스리던 때와 같이 되는 것이다. 5절에서는 사무엘을 이을 왕을, 20절에서는 사무엘처럼 기도해 줄 왕을 구했다","basis":"본문에 없음"}]}},{"type":"match","refs":["삼상 8:6","삼상 8:22","삼상 10:17"],"prompt":"사무엘상 8장 6절, 8장 22절, 10장 17절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"삼상 8:6","text":"왕을 달라는 말을 사무엘이 기뻐하지 않고 여호와께 기도했다"},{"ref":"삼상 8:22","text":"여호와께서 백성의 말대로 왕을 세우라고 하셨고, 사무엘은 사람들을 저마다 성읍으로 돌려보냈다"},{"ref":"삼상 10:17","text":"미스바에서 사무엘이 백성을 여호와 앞에 불러 모았다"}],"after":"세 곳을 이으면, 사무엘은 왕을 구하는 말을 기뻐하지 않아 여호와께 기도했고, 여호와께서 왕을 세우라고 하시자 사람들을 돌려보냈으며, 그 뒤 미스바로 백성을 불러 여호와 앞에 모았다."}]},"cards":[{"ref":"삼상 8:7","title":"백성의 말을 다 들으라"},{"ref":"삼상 10:24","title":"여호와께서 택하신 사람"}],"close":{"t1":{"kind":"prayer","text":"하나님, 왕을 구한 백성과 사무엘의 이야기를 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 사무엘상 8장 4절부터 22절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"삼상 8:4-22, 10:17-25에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 통신기 덮개에 틈이 생겨 소리가 자꾸 끊기니, 틈을 막을 부드러운 것을 찾아봐요. 사람들 곁에서는 함께 기다리고, 사무엘이 하는 일은 곁에서 보기만 해요.","t2":"최현 박사예요. 비상 착륙 때 통신기 덮개에 틈이 벌어져서 소리가 자꾸 끊겨요. 이 시대에는 맞는 부속이 없으니, 여기 라마에서 구할 수 있는 부드러운 것으로 틈을 막아 봐요. 사람들 곁에서 함께 기다리는 것은 괜찮지만, 사무엘이 하는 일에는 손대지 말고 곁에서 보기만 해요.","t3":"최현 박사다. 비상 착륙 때 통신기 덮개에 틈이 벌어져 소리가 자꾸 끊긴다. 이 시대에는 맞는 부속이 없으니, 라마에서 구할 수 있는 부드러운 것으로 틈을 막아야 한다. 사람들 곁에서 함께 기다리는 것은 괜찮지만, 사무엘이 하는 일에는 손대지 않고 곁에서 보기만 한다."},"materials":[{"key":"wool","name":"양털 한 줌","basis":"삼상 8:17","use":"양털을 뭉쳐서 통신기 덮개의 틈을 막는 솜 대신 쓸 수 있어요.","how":"장로들과 백성이 모인 자리에서 멀리 떨어진 길가 땅에 떨어져 있는 양털 한 줌을 줍는다. 양 떼와 사람들의 물건에는 손대지 않는다.","line":"사람들이 모인 곳에서 멀리 떨어진 길가에서 양털 한 줌을 주웠어!"}],"companion":{"who":"사무엘","ref":"삼상 8:4","when":"after","talks":[{"ask":{"who":"choeon","text":"왕이 다스리게 되면 백성에게 어떻게 할 거라고 말했어요?"},"answer":{"t1":"사무엘은 왕이 백성의 아들과 딸을 데려다 자기 일을 시킬 것이라고 말했어요. 가장 좋은 밭과 포도원도 가져갈 것이라고 했어요.","t2":"사무엘은 왕이 아들들을 데려다 병거와 말을 맡기고 자기 밭을 갈게 할 것이라고 말했어요. 딸들은 데려다 요리하고 떡을 굽게 하고, 가장 좋은 밭과 포도원과 감람원을 가져다 신하들에게 줄 것이라고 했어요. 곡식과 양 떼의 십분의 일도 가져갈 것이라고 했어요.","t3":"사무엘은 왕이 아들들을 데려다 병거와 말을 맡기고 천부장과 오십부장으로 삼으며, 자기 밭을 갈고 추수하게 할 것이라고 말했다. 딸들은 데려다 향료를 만들고 요리하고 떡을 굽게 하며, 밭과 포도원과 감람원 가운데 가장 좋은 것을 가져다 신하들에게 줄 것이라고 했다. 곡식과 양 떼의 십분의 일을 가져가고, 백성은 그의 종이 될 것이라고 했다."},"ref":"삼상 8:11-17","open":"삼상 8:11"},{"ask":{"who":"hyu","text":"사울이 백성 가운데 섰을 때 백성에게 뭐라고 했어요?"},"answer":{"t1":"사무엘은 백성에게 여호와께서 택하신 사람을 보라고 말했어요. 모든 백성 가운데 그와 같은 사람이 없다고 했어요.","t2":"사무엘은 모든 백성에게 여호와께서 택하신 사람을 보라고 말했어요. 온 백성 가운데 그와 견줄 사람이 없다고 했어요.","t3":"사무엘은 모든 백성에게 여호와께서 택하신 사람을 보라고 하며, 온 백성 가운데 그와 견줄 사람이 없다고 말했다."},"ref":"삼상 10:24","open":"삼상 10:24"}]},"today":[{"q":"사울은 왜 짐 사이에 숨었어요?","a":{"t1":"성경은 사울이 왜 숨었는지 말하지 않아요. 사람들이 사울을 찾지 못해 여호와께 여쭈었고, 하나님이 짐 사이에 숨었다고 대답하셨다고만 적혀 있어요.","t2":"성경은 사울이 숨은 까닭을 말하지 않아요. 사울이 뽑혔지만 사람들이 찾지 못했고, 여호와께 다시 여쭈자 하나님이 짐 사이에 숨었다고 대답하셨어요. 사람들이 달려가 사울을 데려왔다고 해요. 성경은 여기까지 말해요.","t3":"성경은 사울이 숨은 까닭을 말하지 않는다. 기스의 아들 사울이 뽑혔으나 사람들이 그를 찾지 못했고, 여호와께 다시 여쭈자 여호와께서 그가 짐 사이에 숨었다고 대답하셨으며, 사람들이 달려가 그를 데려왔다고 적을 뿐이다. 성경은 여기까지 말한다."},"refs":["삼상 10:21-23"]},{"q":"사무엘이 기도했을 때 하나님이 대답하셨어요?","a":{"t1":"네. 백성이 왕을 구하자 사무엘은 여호와께 기도했고, 여호와께서 사무엘에게 말씀하셨다고 성경은 적어요.","t2":"백성이 왕을 구하자 사무엘은 여호와께 기도했고, 여호와께서 사무엘에게 말씀하셨어요. 사무엘이 백성의 말을 다 듣고 여호와께 아뢰었을 때에도 여호와께서 말씀하셨어요. 이 장면에서 성경은 이렇게 적어요.","t3":"백성이 왕을 구하자 사무엘은 여호와께 기도했고, 여호와께서 사무엘에게 말씀하셨다. 사무엘이 백성의 말을 다 듣고 여호와께 아뢰었을 때에도 여호와께서 그에게 말씀하셨다. 이 장면에서 성경은 이렇게 적는다. 기도에 하나님이 언제 어떻게 대답하시는지를 이 본문이 모두 말하지는 않는다."},"refs":["삼상 8:6-7","삼상 8:21-22"]}],"help":{"who":"미스바에 모인 이스라엘 백성","steps":[{"kind":"stay","after":4,"title":"미스바에서 함께 기다리기","basis":"삼상 10:19","text":{"t1":"사무엘이 백성에게 지파대로 여호와 앞에 나오라고 했어요. 우리는 모인 백성의 가장자리에서 함께 기다려요.","t2":"사무엘은 미스바에 모인 백성에게 지파마다 천 명씩 나뉘어 여호와 앞으로 나오라고 했어요. 우리는 그 줄에 끼지 않고, 모인 백성의 가장자리에서 함께 기다려요.","t3":"사무엘은 백성에게 지파별로 천 명씩 여호와 앞으로 나오라고 했다(10:19). 탐험대는 그 줄에 끼지 않고, 모인 백성의 가장자리에서 함께 기다린다."},"wait":"백성 곁에서 기다리기","say":{"who":"hyu","text":"지파마다 나아온대. 우리는 여기 가장자리에서 기다리자."}},{"kind":"watch","after":6,"title":"곁에서 보기 · 책에 적어 여호와 앞에 둔 제도","basis":"삼상 10:25","text":{"t1":"사무엘이 백성에게 나라의 제도를 알려 주고, 그것을 책에 적어 여호와 앞에 두었어요. 사무엘이 하는 일이라서 우리는 곁에서 봐요.","t2":"사무엘은 백성에게 나라의 제도를 알려 주고, 그것을 책에 적어 여호와 앞에 두었어요. 사무엘이 하는 일이고 여호와 앞에 두는 것이라서, 우리는 그 책에 손대지 않고 곁에서 봐요.","t3":"사무엘은 백성에게 나라의 제도를 알려 주고 그것을 책에 적어 여호와 앞에 두었다(10:25). 사무엘이 한 일이고 여호와 앞에 둔 것이므로, 탐험대는 그 책에 손대지 않고 곁에서 본다. 책에 무엇이 적혔는지 성경은 더 말하지 않는다."},"say":{"who":"choeon","text":"책은 사무엘이 적어서 두었어. 우리는 손대지 않아."}},{"kind":"do","after":6,"title":"돌아가는 백성 곁에서 자리 정리하기","basis":"삼상 10:25","text":{"t1":"사무엘이 모든 백성을 저마다 집으로 보냈어요. 우리는 돌아가는 사람들 곁에서 길을 비켜 주고, 우리가 기다리던 자리를 정리하며 도왔어요.","t2":"사무엘은 나라의 제도를 책에 적어 여호와 앞에 둔 뒤, 모든 백성을 저마다 집으로 보냈어요. 우리는 돌아가는 사람들 곁에서 길을 비켜 주고, 우리가 기다리던 가장자리를 정리했어요. 성경에 적힌 일이 아니라 탐험대가 한 일이에요.","t3":"사무엘은 모든 백성을 저마다 집으로 돌려보냈다(10:25). 탐험대는 돌아가는 사람들 곁에서 길을 비켜 주고, 기다리던 가장자리를 정리한다. 성경에 적힌 일이 아니라 탐험대 이야기다. 사무엘이 여호와 앞에 둔 책에는 다가가지 않는다."},"tasks":["길 가장자리로 비켜서기","돌아가는 사람들이 먼저 지나가게 기다리기","우리가 서 있던 가장자리 정리하기"],"done":{"who":"hyu","text":"다들 저마다 집으로 돌아가. 우리가 서 있던 자리도 깨끗하게 정리했어."}},{"kind":"ask","after":"gates","title":"백성이 왕을 구한 일은 무슨 뜻이에요?","basis":"삼상 10:18-19","by":"사무엘","ask":{"who":"choeon","text":"백성이 왕을 구한 일은 무슨 뜻이에요?"},"answer":{"t1":"사무엘은 미스바에서, 하나님이 이스라엘을 애굽에서 이끌어 내셨다고 말씀하셨다고 전했어요. 그런데 백성이 자기들을 구원하신 하나님을 버리고 왕을 세워 달라고 했다고 말했어요.","t2":"사무엘은 미스바에서, 하나님이 이스라엘을 애굽에서 이끌어 내고 괴롭히던 모든 나라의 손아귀에서 건져 내셨다고 말씀하셨다고 전했어요. 그리고 백성이 모든 재난과 고통에서 구원하신 하나님을 그날 버리고, 자기들 위에 왕을 세우라고 했다고 말했어요.","t3":"사무엘은 미스바에서, 이스라엘의 하나님 여호와께서 이스라엘을 애굽에서 이끌어 내고 애굽 사람과, 압제하던 모든 나라의 손아귀에서 건져 내셨다고 말씀하셨다고 전했다. 그리고 백성이 모든 재난과 고통에서 친히 구원하신 하나님을 그날 버리고 자기들 위에 왕을 세우라고 했다고 말했다."},"read":{"t1":{"type":"find","ref":"삼상 8:7","prompt":"성경책에서 사무엘상 8장 7절을 찾아 읽어 보세요.","confirm":{"prompt":"하나님은 백성이 사무엘이 아니라 누구를 버린 것이라고 하셨나요?","options":[{"label":"사무엘의 아들들","basis":"본문에 없음"},{"label":"하나님","ok":true},{"label":"장로들","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"삼상 8:7-8","prompt":"성경책에서 사무엘상 8장 7절과 8절을 읽어 보세요.","confirm":{"prompt":"하나님은 백성이 버린 것이 사무엘이 아니라고 하셨어요. 그렇게 말씀하신 까닭은 무엇인가요?","options":[{"label":"백성이 하나님을 버려서, 하나님이 그들을 다스리는 왕이 되시지 못하게 했기 때문에","ok":true},{"label":"백성이 사무엘의 아들들을 버려서, 그 아들들이 사사로 다스리지 못하게 했기 때문에","basis":"본문에 없음"},{"label":"사무엘이 너무 늙어서, 백성이 사무엘 대신 왕에게 재판을 받으려 했기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["삼상 8:7","삼상 10:19"],"prompt":"사무엘상 8장 7절과 10장 19절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳에 공통으로 나오는, 왕을 구한 일에 대한 말은 무엇인가?","options":[{"label":"백성이 사무엘을 버렸다는 말이다. 라마에서는 장로들이 그렇게 말했고, 미스바에서는 사무엘이 백성을 꾸짖으며 그렇게 말했다","basis":"본문에 없음"},{"label":"백성이 하나님을 버렸다는 말이다. 라마에서는 하나님이 사무엘에게 그렇게 말씀하셨고, 미스바에서는 사무엘이 백성에게 그렇게 말했다","ok":true},{"label":"백성이 사무엘의 말을 듣지 않았다는 말이다. 라마에서는 하나님이 사무엘에게, 미스바에서는 사무엘이 백성에게 그렇게 말했다","basis":"삼상 8:19"}]}}},"nt":{"ref":"행 13:21","text":"신약의 사도행전 13장 21절은 백성이 왕을 구하자 하나님이 사울을 사십 년 동안 주셨다고 말한다. 사울은 베냐민 지파 기스의 아들이라고 적는다."}}]}},"has3d":false,"epic":false},"OT-26":{"id":"OT-26","era":7,"title":"다윗과 골리앗","ref":"삼상 17:1-54","place":"엘라 골짜기","review":{"required":false,"topics":[],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"삼상 17:1-3","focus":"valley","text":{"t1":"블레셋 사람들이 싸우려고 모이자, 사울과 이스라엘 사람들은 엘라 골짜기에 진을 쳤어요. 두 군대는 서로 다른 산에 섰고, 그 사이에 골짜기가 있었어요.","t2":"블레셋 사람들이 싸우려고 군대를 모아 유다 땅 소고에 모였어요. 사울과 이스라엘 사람들도 모여 엘라 골짜기에 진을 치고 맞섰어요. 블레셋 사람은 이쪽 산에, 이스라엘은 저쪽 산에 섰고 그 사이에는 골짜기가 있었어요.","t3":"블레셋 사람들이 싸우려고 군대를 모아 진을 쳤다. 그들이 모인 곳과 진을 친 곳의 이름은 1절에 있다. 사울과 이스라엘 군대도 모여 엘라 골짜기에 진을 치고 블레셋 사람과 맞서 전열을 갖추었다. 블레셋 사람은 한쪽 산에, 이스라엘은 맞은쪽 산에 섰고 둘 사이로 골짜기가 놓여 있었다."},"say":{"who":"hyu","text":"여기는 엘라 골짜기야. 이쪽 산과 저쪽 산에 진이 하나씩 있고, 가운데가 골짜기야. 그려 둘게."}},{"ref":"삼상 17:4-11","focus":"goliath","text":{"t1":"블레셋 진에서 키가 여섯 규빗 한 뼘인 골리앗이 나와, 자기와 싸울 사람 하나를 보내라고 외쳤어요. 사울과 온 이스라엘은 크게 두려워했어요.","t2":"블레셋 진에서 싸움을 거는 사람이 나왔는데, 가드 사람 골리앗이었어요. 키는 여섯 규빗 한 뼘이고, 놋으로 만든 투구와 갑옷을 갖추었어요. 골리앗은 이스라엘 군대를 향해 한 사람을 뽑아 자기에게 내려보내라고 외쳤어요. 사울과 온 이스라엘이 그 말을 듣고 어떠했는지는 11절에서 찾아봐요.","t3":"블레셋 진에서 싸움을 돋우는 사람이 나왔는데, 이름은 골리앗이고 가드 사람이었다. 키는 여섯 규빗 한 뼘이었고, 머리에 놋투구를 쓰고 무게가 놋 오천 세겔 되는 갑옷을 입었으며, 다리에 놋 경갑을 차고 어깨 사이에 놋 단창을 메었다. 창 자루는 베틀 채 같았고 창날은 철 육백 세겔이었으며, 방패 든 사람이 앞서 걸었다. 그는 이스라엘 군대에게 한 사람을 골라 내려보내라고 외치며, 그 사람이 자기를 죽이면 블레셋이 종이 되고 자기가 이기면 이스라엘이 종이 되어 섬겨야 한다고 했다. 사울과 온 이스라엘은 이 말을 듣고 놀라 크게 두려워했다."},"say":{"who":"choeon","text":"저 사람 좀 봐. 머리부터 다리까지 놋으로 덮었고, 앞에는 방패를 든 사람이 걸어가."}},{"ref":"삼상 17:12-23","focus":"david","text":{"t1":"이새는 막내아들 다윗에게, 싸움에 나간 형들에게 먹을 것을 가져다주라고 했어요. 다윗이 진에 와서 형들과 말할 때 골리앗이 나와 또 같은 말을 했어요.","t2":"다윗은 유다 베들레헴 사람 이새의 여덟 아들 가운데 막내였고, 장성한 세 형은 사울과 함께 싸움터에 나가 있었어요. 골리앗은 사십 일 동안 아침저녁으로 나왔어요. 이새는 다윗을 형들이 있는 진으로 보냈는데, 무엇을 하라고 보냈는지는 17절과 18절에서 찾아봐요. 다윗이 진에 와서 형들과 말하고 있을 때 골리앗이 나와 전과 같은 말을 했고, 다윗이 그 말을 들었어요.","t3":"다윗의 아버지는 유다 베들레헴에 사는 에브랏 사람 이새였다. 이새에게는 여덟 아들이 있었고, 장성한 세 아들 엘리압과 아비나답과 삼마는 사울을 따라 싸움터에 나가 있었으며 다윗은 막내였다. 그 블레셋 사람은 사십 일 동안 아침저녁으로 나와 모습을 보였다. 이새는 다윗에게 볶은 곡식 한 에바와 떡 열 덩이를 형들에게, 치즈 열 덩이를 천부장에게 가져다주라고 했다. 이새가 그 밖에 무엇을 시켰는지, 다윗이 길을 떠나기 전에 양을 어떻게 했는지는 17절부터 20절까지 읽어 보자. 다윗은 진영에 이르러 짐을 짐 지키는 사람에게 맡기고 형들에게 달려갔다. 형들과 말하는 동안 골리앗이 블레셋 대열에서 나와 전과 같은 말을 했고, 다윗이 그것을 들었다."},"say":{"who":"hyu","text":"다윗은 베들레헴에서 왔어. 짐은 짐 지키는 사람에게 맡기고 형들에게 달려갔어."}},{"ref":"삼상 17:24-31","focus":"david","text":{"t1":"이스라엘 사람들은 골리앗을 보고 몹시 두려워하며 도망했어요. 다윗이 곁에 있는 사람들에게 골리앗에 대해 묻자, 그 말을 전해 들은 사울이 다윗을 불렀어요.","t2":"이스라엘 사람들은 골리앗 앞에서 도망했는데, 왜 도망했는지는 24절에서 찾아봐요. 다윗은 곁에 선 사람들에게, 이 블레셋 사람이 누구이기에 살아 계신 하나님의 군대를 감히 모욕하느냐고 말했어요. 맏형 엘리압은 그 말을 듣고 다윗에게 화를 냈어요. 누군가 다윗의 말을 사울에게 전했고, 사울이 다윗을 불렀어요.","t3":"이스라엘 사람들은 모두 그를 보자 몹시 두려워하며 그 앞에서 달아났다. 사람들은 그를 죽이는 사람을 왕이 큰 재물로 부하게 하고 딸을 주며 그 아버지의 집을 이스라엘 가운데서 자유롭게 할 것이라고 말했다. 다윗은 곁에 선 사람들에게, 이 블레셋 사람을 죽이고 이스라엘이 받은 치욕을 없애는 사람을 어떻게 대우하는지 묻고, 이 사람이 누구이기에 살아 계신 하나님의 군대를 감히 모욕하느냐고 했다. 맏형 엘리압은 그 말을 듣고 다윗에게 화를 냈다. 엘리압이 무엇이라고 꾸짖었는지는 28절에서 직접 읽어 보자. 다윗은 자기가 무엇을 했느냐고 대답하고 다른 사람에게 돌아서서 같은 말을 했다. 그 말을 들은 사람이 사울에게 알렸고, 사울이 다윗을 불렀다."},"say":{"who":"choeon","text":"사람들이 다 도망가는데, 다윗은 옆 사람들한테 뭔가 묻고 있어."}},{"ref":"삼상 17:32-37","open":"삼상 17:37","focus":"david","text":{"t1":"다윗이 가서 싸우겠다고 하자, 사울은 다윗이 소년이라서 안 된다고 했어요. 다윗은 사자와 곰에게서 건져 주신 여호와께서 이번에도 건져 주실 것이라고 했어요.","t2":"다윗은 사울에게 자기가 가서 저 블레셋 사람과 싸우겠다고 했어요. 사울은 다윗은 소년이고 그 사람은 어려서부터 용사였으니 싸울 수 없다고 했어요. 다윗은 아버지의 양을 지킬 때 사자와 곰이 새끼 양을 물어 가면 따라가서 쳐 건져 냈다고 말했어요. 그리고 사자와 곰의 발톱에서 건져 주신 여호와께서 이 블레셋 사람의 손에서도 건져 주실 것이라고 했고, 사울은 가라고 했어요.","t3":"다윗은 사울에게, 그 사람 때문에 누구도 낙담할 것이 없으며 자기가 가서 저 블레셋 사람과 싸우겠다고 했다. 사울은 다윗이 소년이고 그는 어려서부터 용사이니 싸울 수 없다고 했다. 다윗은 아버지의 양을 지킬 때 사자나 곰이 양 떼에서 새끼를 물어 가면 따라가 쳐서 그 입에서 새끼를 건져 냈고, 달려들면 수염을 잡고 쳐 죽였다고 말했다. 살아 계신 하나님의 군대를 모욕한 이 블레셋 사람도 그 짐승 가운데 하나처럼 될 것이라고 했다. 또 사자와 곰의 발톱에서 자기를 건지신 여호와께서 이 블레셋 사람의 손에서도 건지실 것이라고 했다. 사울은 가라고 하며 여호와께서 함께 계시기를 바란다고 했다."},"say":{"who":"onwoo","text":"다윗이 사울에게 한 말이 길어. 37절을 성경책에서 직접 읽어 보자."}},{"ref":"삼상 17:38-40","focus":"brook","text":{"t1":"다윗은 사울이 입혀 준 것들이 익숙하지 않아 벗고, 막대기와 물매를 들고 시내에서 돌을 골랐어요. 사울이 무엇을 입혀 주었고 돌을 몇 개 골랐는지는 성경에서 찾아봐요.","t2":"사울은 자기 군복으로 다윗을 입혀 주었어요. 그 뒤에 다윗이 무엇을 어떤 차례로 했는지는 38절부터 40절까지 읽어 봐요.","t3":"사울은 다윗에게 자기 군복을 입히고, 머리에 놋투구를 씌우고, 갑옷도 입혔다. 다윗은 군복 위에 칼을 차고 걸어 보았으나 익숙하지 않았고, 사울에게 이것을 입고는 갈 수 없다고 말하고 곧 벗었다. 그는 손에 막대기를 들고 시내에서 매끄러운 돌 다섯 개를 골라 목자의 기구인 주머니에 넣고, 물매를 손에 든 채 그 블레셋 사람에게 나아갔다."},"say":{"who":"choeon","text":"다윗이 이제 무엇을 하는지 잘 지켜보자."}},{"ref":"삼상 17:41-47","open":"삼상 17:45","focus":"david","text":{"t1":"골리앗은 다윗을 보고 업신여겼어요. 다윗은 골리앗이 칼과 창을 가지고 오지만 자기는 만군의 여호와의 이름으로 간다고 말했어요.","t2":"골리앗은 방패 든 사람을 앞세우고 다가오다가, 다윗을 보더니 업신여겼고 자기 신들의 이름을 대며 다윗을 저주했어요. 다윗은 골리앗이 칼과 창과 단창으로 오지만 자기는 오직 만군의 여호와의 이름으로 간다고 말했어요. 골리앗이 다윗을 업신여긴 까닭과 다윗이 이어서 한 말은 42절, 그리고 46절과 47절에서 찾아봐요.","t3":"그 블레셋 사람은 방패 든 사람을 앞세우고 다윗에게 다가오다가, 둘러보고 다윗을 업신여겼다. 다윗이 젊고 얼굴이 붉으며 용모가 아름다웠기 때문이다. 다윗은 그가 칼과 창과 단창으로 오지만 자기는 그가 모욕한 이스라엘 군대의 하나님, 만군의 여호와의 이름으로 간다고 했다. 그날 여호와께서 그를 자기 손에 넘기실 것이며, 온 땅이 이스라엘에게 하나님이 계심을 알게 될 것이라고 했다. 싸움은 여호와께 속한 것이라고 했다. 그 블레셋 사람이 먼저 다윗에게 한 말과, 이 무리가 무엇을 알게 될 것이라고 다윗이 말했는지는 43절과 47절에서 직접 읽어 보자."},"say":{"who":"onwoo","text":"골리앗이 다윗 쪽으로 다가오고 있어."}},{"ref":"삼상 17:48-54","focus":"david","text":{"t1":"다윗이 달려가 물매로 돌을 던지자 골리앗이 땅에 엎드러졌어요. 다윗의 손에는 칼이 없었고, 블레셋 사람들은 도망했어요.","t2":"골리앗이 다가오자 다윗은 그쪽으로 빨리 달려갔어요. 주머니에서 돌을 꺼내 물매로 던지니 돌이 골리앗의 이마를 쳤고, 골리앗은 땅에 엎드러졌어요. 다윗은 물매와 돌로 이겼고 손에는 칼이 없었어요. 다윗이 달려가 골리앗의 칼을 뽑아 그를 죽이자, 블레셋 사람들은 도망했고 이스라엘 사람들이 뒤쫓았어요.","t3":"그 블레셋 사람이 일어나 다가올 때 다윗은 그 대열 쪽으로 빨리 달렸다. 주머니에 손을 넣어 돌을 꺼내 물매로 던지니 돌이 그의 이마를 쳤고, 그는 얼굴을 땅에 대고 엎드러졌다. 다윗은 이렇게 물매와 돌로 그를 이겼으며 손에는 칼이 없었다. 다윗은 달려가 그의 칼을 칼집에서 빼어 그를 죽이고 머리를 베었다. 블레셋 사람들은 자기 용사가 죽은 것을 보고 도망했고, 이스라엘과 유다 사람들은 소리 지르며 에그론 성문까지 쫓아갔다가 돌아와 그들의 진을 노략했다. 다윗은 그 머리를 예루살렘으로 가져갔고, 그의 갑주는 자기 장막에 두었다."},"say":{"who":"hyu","text":"다윗 손에는 칼이 없었어. 물매와 돌이었다고 적어 둘게."}}],"gates":{"t1":[{"type":"find","ref":"삼상 17:4","prompt":"성경책에서 사무엘상 17장 4절을 찾아 읽어 보세요.","confirm":{"prompt":"골리앗은 어느 곳 사람이었나요?","options":[{"label":"가드","ok":true},{"label":"아스돗","basis":"삼상 5:1"},{"label":"베들레헴","basis":"삼상 17:12"}]}},{"type":"multi","ref":"삼상 17:38","prompt":"성경책에서 사무엘상 17장 38절을 찾아 읽어 보세요.","confirm":{"prompt":"사울이 다윗에게 입히거나 씌워 준 것을 모두 고르세요.","options":[{"label":"사울의 군복","ok":true},{"label":"겉옷","basis":"삼상 18:4"},{"label":"놋투구","ok":true},{"label":"허리띠","basis":"삼상 18:4"},{"label":"갑옷","ok":true}]}}],"t2":[{"type":"find","ref":"삼상 17:23-24","prompt":"성경책에서 사무엘상 17장 23절과 24절을 읽어 보세요.","confirm":{"prompt":"이스라엘 사람들이 골리앗 앞에서 도망한 까닭은 무엇인가요?","options":[{"label":"사울 왕이 물러나라고 명령했기 때문에","basis":"본문에 없음"},{"label":"블레셋 군대가 이미 골짜기를 건너왔기 때문에","basis":"본문에 없음"},{"label":"골리앗을 보고 몹시 두려워했기 때문에","ok":true}]}},{"type":"order","ref":"삼상 17:38-40","prompt":"성경책에서 사무엘상 17장 38절부터 40절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["사울이 다윗에게 군복과 갑옷을 입히고 머리에 투구를 씌웠다","다윗이 칼을 차고 시험 삼아 걸어 보았다","다윗이 익숙하지 않아 입고 갈 수 없다고 말하고 벗었다","다윗이 시내에서 매끈한 돌 다섯 개를 골라 주머니에 넣었다","다윗이 물매를 손에 들고 블레셋 사람에게 나아갔다"]}],"t3":[{"type":"find","refs":["삼상 17:20","삼상 17:28"],"prompt":"사무엘상 17장 20절과 28절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 맏형 엘리압이 다윗에게 한 말과 다윗이 진영에 오기 전에 한 일은 어떻게 다른가?","options":[{"label":"엘리압은 들의 양을 버려두고 싸움을 구경하러 왔다고 꾸짖었고, 다윗은 정말로 양을 아무에게도 맡기지 않고 짐만 챙겨 서둘러 왔다","basis":"본문에 없음"},{"label":"엘리압은 들의 양 몇 마리를 누구에게 맡겼느냐며 싸움을 구경하러 왔다고 했지만, 다윗은 떠나기 전에 양을 양 지키는 사람에게 맡기고 이새가 시킨 대로 짐을 가지고 왔다","ok":true},{"label":"엘리압은 들의 양 몇 마리를 누구에게 맡겼느냐며 싸움을 구경하러 왔다고 했지만, 다윗은 떠나기 전에 양 떼를 아버지 이새에게 맡기고 짐을 가지고 왔다","basis":"본문에 없음"}]}},{"type":"match","refs":["삼상 17:11","삼상 17:16","삼상 17:37"],"prompt":"사무엘상 17장 11절, 16절, 37절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"삼상 17:11","text":"골리앗의 말에 사울과 온 이스라엘이 놀라 몹시 두려워했다"},{"ref":"삼상 17:16","text":"골리앗이 사십 일 동안 아침저녁으로 나와 모습을 보였다"},{"ref":"삼상 17:37","text":"사울이 다윗에게 가라고 하며, 여호와께서 함께하시기를 바랐다"}],"after":"세 곳을 이으면, 사십 일 동안 아침저녁으로 나온 골리앗 앞에서 사울과 온 이스라엘은 두려워했지만, 다윗의 말을 들은 사울은 마침내 가라고 하며 여호와께서 함께하시기를 바랐다."}]},"cards":[{"ref":"삼상 17:45","title":"만군의 여호와의 이름으로"},{"ref":"삼상 17:47","title":"전쟁은 여호와께 속한 것"}],"close":{"t1":{"kind":"prayer","text":"하나님, 엘라 골짜기에서 다윗이 한 말을 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 사무엘상 17장 32절부터 50절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"삼상 17:1-54에서 새로 알게 된 사실을 한 가지 적어 보자."}},"quests":[{"part":"gear","name":"톱니바퀴","line":"톱니바퀴를 찾았어! 진 바깥쪽 산비탈에 떨어져 있었네.","found":"탐지기가 이스라엘이 선 산 쪽을 가리켜요.","say":{"who":"hyu","text":"탐지기 바늘이 이스라엘이 선 산 쪽으로 돌아갔어. 건너편 산에는 블레셋 진이 있다고 일지에 적어 둘게."},"q":{"t1":{"type":"find","ref":"삼상 17:1","prompt":"성경책에서 사무엘상 17장 1절을 찾아 읽어 보세요.","confirm":{"prompt":"블레셋 사람들은 싸우려고 군대를 모아 어디에 모였나요?","options":[{"label":"소고","ok":true},{"label":"베들레헴","basis":"삼상 17:12"},{"label":"예루살렘","basis":"삼상 17:54"}]}},"t2":{"type":"find","ref":"삼상 17:8-10","prompt":"성경책에서 사무엘상 17장 8절부터 10절까지 읽어 보세요.","confirm":{"prompt":"골리앗이 이스라엘 군대에게 한 사람을 골라 내려보내라고 한 까닭은 무엇인가요?","options":[{"label":"그 사람과 자기가 싸워서, 지는 쪽의 왕이 이긴 쪽에 땅을 내어 주게 하려고","basis":"본문에 없음"},{"label":"그 사람과 자기가 싸워서, 지는 쪽의 백성이 이긴 쪽의 종이 되게 하려고","ok":true},{"label":"그 사람과 자기가 싸워서, 이기는 사람이 왕의 딸과 많은 재물을 얻게 하려고","basis":"삼상 17:25"}]}},"t3":{"type":"find","refs":["삼상 17:1","삼상 17:19"],"prompt":"사무엘상 17장 1절과 19절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 블레셋 사람들은 처음에 어디에 모여 진을 쳤고, 이새가 다윗을 보낼 무렵 사울과 이스라엘은 그들과 어디에서 무엇을 하고 있었는가?","options":[{"label":"블레셋은 가드에 모였다가 가드 성 앞 들에 진을 쳤고, 이새가 다윗을 보낼 무렵 사울과 이스라엘은 엘라 골짜기에서 그들과 싸우고 있었다","basis":"본문에 없음"},{"label":"블레셋은 유다 땅 소고에 모였다가 소고와 아세가 사이인 에베스담밈에 진을 쳤고, 이새가 다윗을 보낼 무렵 사울과 이스라엘은 엘라 골짜기에서 그들과 싸우고 있었다","ok":true},{"label":"블레셋은 베들레헴 가까이에 모였다가 아세가 언덕에 진을 쳤고, 이새가 다윗을 보낼 무렵 사울과 이스라엘은 엘라 골짜기에서 그들과 싸우고 있었다","basis":"본문에 없음"}]}}}},{"part":"needle","name":"나침반 바늘","line":"나침반 바늘이 여기 있었네! 짐을 둔 곳에서 조금 떨어진 땅이야.","found":"탐지기가 짐 지키는 사람이 있는 쪽을 가리켜요.","say":{"who":"choeon","text":"저기 짐 지키는 사람이 있어. 짐에는 손대지 말자."},"q":{"t1":{"type":"find","ref":"삼상 17:17","prompt":"성경책에서 사무엘상 17장 17절을 찾아 읽어 보세요.","confirm":{"prompt":"아버지 이새는 다윗에게, 형들에게 무엇을 가져다주라고 했나요?","options":[{"label":"치즈 열 덩이","basis":"삼상 17:18"},{"label":"고기와 포도주","basis":"본문에 없음"},{"label":"볶은 곡식과 떡","ok":true}]}},"t2":{"type":"find","ref":"삼상 17:17-20","prompt":"성경책에서 사무엘상 17장 17절부터 20절까지 읽어 보세요.","confirm":{"prompt":"다윗이 아침 일찍 진영으로 간 까닭은 무엇인가요?","options":[{"label":"아버지 이새가 형들에게 먹을 것을 갖다주고 안부를 살피라고 시켰기 때문에","ok":true},{"label":"아버지 이새가 형들에게 먹을 것을 갖다주고 형들을 집으로 데려오라고 시켰기 때문에","basis":"본문에 없음"},{"label":"아버지 이새가 사울 왕에게 먹을 것을 바치고 싸움 소식을 들어 오라고 시켰기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["삼상 17:18","삼상 17:22"],"prompt":"사무엘상 17장 18절과 22절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 다윗이 진영에 와서 짐을 맡기고 한 일은 이새의 어떤 말과 이어지는가?","options":[{"label":"이새는 형들을 데리고 집으로 돌아오라고 했고, 다윗은 형들에게 달려가 집으로 가자고 했다","basis":"본문에 없음"},{"label":"이새는 형들의 안부를 살피라고 했고, 다윗은 형들에게 달려가 안부를 물었다","ok":true},{"label":"이새는 천부장에게 싸움 소식을 물어 오라고 했고, 다윗은 천부장을 찾아 달려갔다","basis":"본문에 없음"}]}}}},{"part":"screw","name":"나사","line":"나사를 찾았어! 시내에서 떨어진 골짜기 가장자리에 있었어.","found":"탐지기가 시내 쪽을 가리켜요.","say":{"who":"onwoo","text":"시내가 보이는 데까지만 가자. 골짜기 가운데로는 내려가지 말자. 우리는 지켜보는 사람이야."},"q":{"t1":{"type":"find","ref":"삼상 17:40","prompt":"성경책에서 사무엘상 17장 40절을 찾아 읽어 보세요.","confirm":{"prompt":"다윗은 시내에서 무엇을 몇 개 골랐나요?","options":[{"label":"큰 돌 한 개","basis":"본문에 없음"},{"label":"매끄러운 돌 다섯 개","ok":true},{"label":"매끄러운 돌 세 개","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"삼상 17:41-42","prompt":"성경책에서 사무엘상 17장 41절과 42절을 읽어 보세요.","confirm":{"prompt":"그 블레셋 사람이 다윗을 업신여긴 까닭은 무엇인가요?","options":[{"label":"다윗이 키가 작고, 목소리가 가늘고, 옷차림이 초라했기 때문에","basis":"본문에 없음"},{"label":"다윗이 젊고, 얼굴이 붉고, 생김새가 아름다웠기 때문에","ok":true},{"label":"다윗이 방패 든 사람도 없이 혼자서 골짜기를 건너왔기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["삼상 17:40","삼상 17:43"],"prompt":"사무엘상 17장 40절과 43절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 다윗이 손에 무엇을 들고 나아갔고, 그 블레셋 사람은 그것을 보고 무엇이라고 하며 어떻게 했는가?","options":[{"label":"다윗은 손에 막대기와 물매를 들고 나아갔고, 블레셋 사람은 다윗을 업신여겼지만 아무 말도 하지 않고 창만 들어 보였다","basis":"본문에 없음"},{"label":"다윗은 손에 막대기와 물매를 들고 나아갔고, 블레셋 사람은 자기를 개로 여겨 막대기를 가지고 왔느냐며 자기 신들의 이름을 대며 다윗을 저주했다","ok":true},{"label":"다윗은 손에 막대기와 물매를 들고 나아갔고, 블레셋 사람은 막대기를 보고 양이나 치러 돌아가라며 사울의 이름을 대며 비웃었다","basis":"본문에 없음"}]}}}}],"mission":{"call":{"t1":"최현 박사예요. 톱니바퀴와 나침반 바늘과 나사가 망가졌으니, 탐지기가 가리키는 곳에서 대신 쓸 재료를 찾아봐요. 다윗이 맡은 일과 싸움에는 끼지 말고 곁에서 봐요.","t2":"최현 박사예요. 비상 착륙 때 톱니바퀴와 나침반 바늘과 나사가 망가져서 타임머신이 떠날 수 없어요. 이 시대에는 우리 부속이 없으니, 엘라 골짜기에서 탐지기가 가리키는 곳마다 대신 쓸 재료를 찾아봐요. 다윗이 맡은 일과 싸움에는 끼지 말고 곁에서 보기만 해요.","t3":"최현 박사다. 비상 착륙으로 톱니바퀴, 나침반 바늘, 나사가 망가졌고 지금은 통신만 이어져 있다. 이 시대에는 부속이 없으니 엘라 골짜기에서 탐지기가 가리키는 곳마다 재료를 구해 세 부속을 대신 만들어야 한다. 다윗이 맡은 일과 싸움에는 끼지 않고 곁에서 보기만 한다."},"materials":[{"key":"flatstone","name":"납작한 돌","basis":"삼상 17:3","use":"납작한 돌의 가장자리에 홈을 내면 톱니바퀴 대신 쓸 수 있어요.","how":"이스라엘이 선 산 쪽으로 가되 진에는 들어가지 않고, 진에서 떨어진 비탈에 굴러 있는 납작한 돌 하나를 줍는다. 시내의 돌에는 손대지 않는다.","line":"이스라엘이 선 산 쪽 비탈에서 납작한 돌을 찾았어!"},{"key":"stick","name":"가는 막대기","basis":"삼상 17:40","use":"곧고 가는 막대기를 나침반 바늘 대신 쓸 수 있어요.","how":"짐 지키는 사람이 있는 쪽으로 가되 짐에서 떨어진 땅에서, 떨어져 있는 가는 막대기 하나를 줍는다. 짐과 사람들의 물건에는 손대지 않는다.","line":"짐 지키는 사람이 있는 쪽 땅에서 가는 막대기를 찾았어!"},{"key":"clay","name":"진흙 한 줌","basis":"삼상 17:2","use":"진흙을 뭉쳐 나사가 빠진 구멍을 메우면 나사 대신 쓸 수 있어요.","how":"시내 쪽으로 가되 시내에는 들어가지 않고, 시내에서 조금 떨어진 골짜기 가장자리에서 진흙을 한 줌 뜬다. 시내의 돌에는 손대지 않는다.","line":"시내 쪽, 시내에서 조금 떨어진 골짜기 가장자리에서 진흙을 한 줌 떴어!"}],"companion":{"who":"다윗","ref":"삼상 17:20","when":"after","talks":[{"ask":{"who":"choeon","text":"모두 무서워하고 있을 때, 사울 왕에게 뭐라고 말했어요?"},"answer":{"t1":"다윗은 그 사람 때문에 아무도 낙담하지 말라고 했어요. 그리고 자기가 가서 저 블레셋 사람과 싸우겠다고 사울에게 말했어요.","t2":"다윗은 사울에게, 그 사람 때문에 누구도 낙담하지 말라고 말했어요. 그리고 왕의 종인 자기가 가서 저 블레셋 사람과 싸우겠다고 했어요.","t3":"다윗은 사울에게, 그 사람 때문에 아무도 마음이 꺾이지 말라고 하며 왕의 종인 자기가 가서 저 블레셋 사람과 싸우겠다고 말했다."},"ref":"삼상 17:32","open":"삼상 17:32"},{"ask":{"who":"hyu","text":"사울 왕이 소년이라서 싸울 수 없다고 했을 때는 뭐라고 대답했어요?"},"answer":{"t1":"다윗은 사자와 곰의 발톱에서 자기를 건져 주신 여호와께서 이 블레셋 사람의 손에서도 건져 주실 것이라고 말했어요.","t2":"다윗은 아버지의 양을 지킬 때 사자나 곰이 와서 새끼 양을 물어 가면, 따라가서 그 입에서 새끼를 건져 냈다고 말했어요. 그리고 사자와 곰의 발톱에서 자기를 건져 주신 여호와께서 이 블레셋 사람의 손에서도 건져 주실 것이라고 했어요.","t3":"다윗은 아버지의 양을 지킬 때 사자나 곰이 양 떼에서 새끼를 물어 가면 따라가 쳐서 그 입에서 건져 냈고, 자기에게 달려들면 수염을 잡고 쳐 죽였다고 말했다. 살아 계신 하나님의 군대를 모욕한 이 블레셋 사람도 그 짐승 가운데 하나처럼 될 것이라고 했다. 그리고 사자와 곰의 발톱에서 자기를 건지신 여호와께서 이 블레셋 사람의 손에서도 건지실 것이라고 했다."},"ref":"삼상 17:34-37","open":"삼상 17:37"},{"ask":{"who":"onwoo","text":"골리앗 앞에 나아갈 때는 누구의 이름으로 간다고 했어요?"},"answer":{"t1":"다윗은 골리앗이 칼과 창을 가지고 오지만, 자기는 만군의 여호와의 이름으로 간다고 말했어요.","t2":"다윗은 그 블레셋 사람이 칼과 창과 단창으로 온다고 말했어요. 그러나 자기는 그가 모욕한 이스라엘 군대의 하나님, 만군의 여호와의 이름으로 간다고 했어요.","t3":"다윗은 그 블레셋 사람이 칼과 창과 단창으로 오지만, 자기는 그가 모욕한 이스라엘 군대의 하나님, 만군의 여호와의 이름으로 간다고 말했다."},"ref":"삼상 17:45","open":"삼상 17:45"}]},"today":[{"q":"다윗은 왜 사울 왕이 입혀 준 갑옷을 입고 가지 않았어요?","a":{"t1":"다윗은 사울의 군복과 갑옷이 익숙하지 않았어요. 그래서 이것을 입고는 갈 수 없다고 사울에게 말하고 벗었다고 성경은 말해요.","t2":"다윗은 군복 위에 칼을 차고 걸어 보았지만 익숙하지 않았어요. 그래서 사울에게, 익숙하지 않아 이것을 입고 갈 수 없다고 말하고 벗었어요. 성경이 말하는 까닭은 여기까지예요.","t3":"성경은 다윗이 군복 위에 칼을 차고 시험 삼아 걸어 보았으나 익숙하지 않았다고 말한다. 다윗은 사울에게 익숙하지 않아 이것을 입고는 갈 수 없다고 말하고 곧 벗었다. 성경이 말하는 까닭은 여기까지다."},"refs":["삼상 17:38-39"]},{"q":"다윗은 골리앗이 무섭지 않았어요?","a":{"t1":"성경은 다윗의 마음이 어땠는지 말하지 않아요. 다윗이 한 말은 적혀 있어요. 사자와 곰의 발톱에서 건져 주신 여호와께서 이번에도 건져 주실 것이라고 했어요.","t2":"성경은 다윗이 무서웠는지 아닌지 말하지 않아요. 다윗이 한 말만 적혀 있어요. 다윗은 사울에게 사자와 곰의 발톱에서 자기를 건지신 여호와께서 이 블레셋 사람의 손에서도 건지실 것이라고 했고, 그 블레셋 사람에게는 전쟁이 여호와께 속한 것이라고 했어요.","t3":"성경은 다윗의 마음이 어떠했는지 말하지 않고, 다윗이 한 말을 적는다. 그는 사자와 곰의 발톱에서 자기를 건지신 여호와께서 이 블레셋 사람의 손에서도 건지실 것이라고 사울에게 말했고, 그 블레셋 사람에게는 전쟁이 여호와께 속한 것이라고 말했다. 성경은 여기까지 말한다."},"refs":["삼상 17:37","삼상 17:47"]}],"help":{"who":"엘라 골짜기에 진을 친 이스라엘 사람들","steps":[{"kind":"watch","after":2,"title":"곁에서 보기 · 다윗이 가져온 짐","basis":"삼상 17:20-22","text":{"t1":"다윗이 아버지 이새가 시킨 대로 먹을 것을 가지고 진에 왔어요. 짐은 짐 지키는 사람에게 맡기고 형들에게 달려갔어요. 다윗이 맡은 일이라서 우리는 짐에 손대지 않고 곁에서 봐요.","t2":"다윗이 먹을 것을 가지고 진영에 왔어요. 그리고 짐을 짐 지키는 사람에게 맡기고, 군대로 달려가 형들을 만났어요. 다윗이 맡아 온 심부름이라서, 우리는 짐을 들어 주지 않고 곁에서 봐요.","t3":"다윗은 먹을 것을 가지고 진영에 이르렀고, 짐을 짐 지키는 사람에게 맡긴 뒤 군대로 달려가 형들을 만났다(17:22). 다윗이 맡아 온 심부름이므로, 탐험대는 짐을 들어 주거나 옮기지 않고 곁에서 본다."},"say":{"who":"choeon","text":"짐은 짐 지키는 사람이 맡았어. 우리는 손대지 말자."}},{"kind":"do","after":2,"title":"짐 지키는 사람 곁에서 자리 둘레 정리하기","basis":"삼상 17:22","text":{"t1":"다윗이 짐을 짐 지키는 사람에게 맡기고 형들에게 달려갔어요. 우리는 짐에는 손대지 않고, 짐 지키는 사람이 머무는 자리 둘레를 정리하며 도왔어요. 싸움에는 끼지 않아요.","t2":"다윗은 가져온 짐을 짐 지키는 사람에게 맡기고 군대로 달려갔어요. 우리는 짐에는 손대지 않고, 짐 지키는 사람이 머무는 자리 둘레를 정리하고 땅을 골랐어요. 군대의 일과 싸움에는 끼지 않아요. 성경에 적힌 일이 아니라 탐험대가 한 일이에요.","t3":"진영에는 짐을 맡아 지키는 사람이 있었다(17:22). 탐험대는 짐에는 손대지 않고, 짐 지키는 사람이 머무는 자리 둘레를 정리하고 땅을 고른다. 성경에 적힌 일이 아니라 탐험대 이야기이며, 다윗이 맡은 심부름과 군대의 일과 싸움에는 끼지 않는다."},"tasks":["짐 지키는 사람이 머무는 자리 둘레 정리하기","그 자리 둘레 땅 고르게 하기","짐 지키는 사람 곁에 함께 서 있기"],"done":{"who":"hyu","text":"짐에는 손대지 않고, 짐 지키는 사람 자리 둘레만 정리했어. 짐은 짐 지키는 사람이 지켜."}},{"kind":"stay","after":5,"title":"이스라엘 쪽 산에서 기다리기","basis":"삼상 17:40","text":{"t1":"다윗이 블레셋 사람에게 나아가요. 우리는 골짜기로 내려가지 않고, 이스라엘이 선 산 쪽에서 기다려요.","t2":"다윗이 막대기와 물매를 들고 블레셋 사람에게 나아가요. 우리는 싸움에 끼지 않아요. 골짜기로 내려가지 않고, 이스라엘이 선 산 쪽에서 기다려요.","t3":"다윗이 그 블레셋 사람에게 나아간다(17:40). 이스라엘은 블레셋과 마주한 산에 서서 전열을 갖추고 있었다(17:3, 17:21). 탐험대는 싸움에 끼지 않고, 두 진 사이의 골짜기로 내려가지 않은 채 이스라엘이 선 산 쪽에서 기다린다."},"wait":"산 쪽에서 기다리기","say":{"who":"onwoo","text":"골짜기로는 내려가지 않아. 우리는 여기서 지켜보는 사람이야."}},{"kind":"ask","after":"gates","title":"칼 없이 이긴 일은 무슨 뜻이에요?","basis":"삼상 17:46-47","by":"다윗","ask":{"who":"onwoo","text":"다윗 님이 칼 없이 물매와 돌로 이긴 일은 무슨 뜻이에요?"},"answer":{"t1":"다윗은 싸우기 전에 골리앗에게, 여호와께서는 칼과 창으로 구원하지 않으신다는 것을 여기 모인 사람들이 알게 될 것이라고 말했어요. 싸움은 여호와께 속한 것이라고 했어요.","t2":"다윗은 싸우기 전에 그 블레셋 사람에게, 이스라엘에게 하나님이 계심을 온 땅이 알게 될 것이라고 말했어요. 또 여호와께서 칼과 창으로 구원하지 않으신다는 것을 여기 모인 무리가 알게 될 것이라고 했어요. 싸움은 여호와께 속한 것이라고 했어요.","t3":"다윗은 싸우기 전에 그 블레셋 사람에게, 이 일로 이스라엘에게 하나님이 계심을 온 땅이 알게 되고, 여호와의 구원이 칼과 창에 달려 있지 않다는 것을 이 무리가 알게 될 것이라고 말했다. 싸움은 여호와께 속한 것이며, 여호와께서 블레셋 사람들을 자기들 손에 넘기실 것이라고 했다."},"read":{"t1":{"type":"find","ref":"삼상 17:47","prompt":"성경책에서 사무엘상 17장 47절을 찾아 읽어 보세요.","confirm":{"prompt":"다윗은 싸움(전쟁)이 누구께 속한 것이라고 했나요?","options":[{"label":"사울 왕","basis":"본문에 없음"},{"label":"여호와","ok":true},{"label":"이스라엘 군대","basis":"본문에 없음"}]},"inStory":"여호와는 장면 곳곳에 나오는 이름일 뿐이다. 싸움이 여호와께 속했다는 다윗의 말은 8~10세 글에서는 17:47을 읽어야 안다(뜻 묻기의 설명은 이 물음 뒤에 나온다)"},"t2":{"type":"find","ref":"삼상 17:45-47","prompt":"성경책에서 사무엘상 17장 45절부터 47절까지 읽어 보세요.","confirm":{"prompt":"다윗은 여호와께서 블레셋 사람들을 자기들 손에 넘기실 것이라고 했어요. 그 까닭을 무엇이라고 말했나요?","options":[{"label":"이스라엘 군대가 블레셋보다 많기 때문이라고","basis":"본문에 없음"},{"label":"싸움은 여호와께 속한 것이기 때문이라고","ok":true},{"label":"다윗이 사울의 칼을 차고 왔기 때문이라고","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["삼상 17:47","삼상 17:50"],"prompt":"사무엘상 17장 47절과 50절을 함께 찾아 읽어 보자.","confirm":{"prompt":"다윗이 싸우기 전에 한 말과, 싸움 뒤에 성경이 적은 것을 이어 읽으면 무엇이 보이는가?","options":[{"label":"다윗은 여호와의 구원이 칼과 창에 달려 있지 않음을 이 무리가 알게 되리라고 했고, 성경은 다윗이 손에 칼 없이 물매와 돌로 그 블레셋 사람을 이겼다고 적는다","ok":true},{"label":"다윗은 블레셋 사람들도 여호와를 섬기게 될 것을 이 무리가 알게 되리라고 했고, 성경은 다윗이 손에 칼 없이 물매와 돌로 그 블레셋 사람을 이겼다고 적는다","basis":"본문에 없음"},{"label":"다윗은 사울 왕이 여호와께서 세우신 왕임을 이 무리가 알게 되리라고 했고, 성경은 다윗이 손에 칼 없이 물매와 돌로 그 블레셋 사람을 이겼다고 적는다","basis":"본문에 없음"}]}}}}]}},"has3d":true,"epic":false},"OT-27":{"id":"OT-27","era":7,"title":"다윗에게 주신 언약","ref":"삼하 7:1-17","place":"왕의 백향목 궁","review":{"required":true,"topics":["구약 사건의 신약적 의미(삼하 7:12-16)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"삼하 7:1-2","focus":"david","text":{"t1":"여호와께서 다윗 왕을 대적들에게서 벗어나 궁에서 평안히 살게 해 주셨어요. 왕은 선지자 나단에게 자기가 사는 궁과 하나님의 궤가 있는 곳을 견주어 말했는데, 궤가 어디에 있다고 했는지는 성경에서 찾아봐요.","t2":"여호와께서 둘레의 모든 대적을 물리쳐 주셔서 다윗 왕이 궁에서 평안히 살던 때였어요. 왕은 선지자 나단에게 말했어요. 자기는 백향목으로 지은 궁에 사는데 하나님의 궤는 휘장 가운데 있다고 했어요.","t3":"여호와께서 둘레의 모든 대적에게서 벗어나게 하셔서 왕이 자기 궁에서 평안히 지내던 때였다. 왕은 선지자 나단에게, 자기는 백향목으로 지은 궁에 사는데 하나님의 궤는 휘장 가운데 있다고 말했다."},"say":{"who":"hyu","text":"여기는 왕의 궁이야. 왕과 선지자 나단, 두 사람이 이야기하고 있어. 일지에 적어 둘게."}},{"ref":"삼하 7:3","focus":"nathan","text":{"t1":"나단은 왕에게, 여호와께서 왕과 함께하시니 마음에 있는 대로 하라고 대답했어요.","t2":"나단은 왕에게, 마음에 있는 것을 다 행하라고 대답했어요. 나단이 왜 그렇게 말했는지는 3절에서 찾아봐요.","t3":"나단은 왕에게, 여호와께서 왕과 함께 계시니 마음에 품은 것을 모두 행하라고 대답했다."},"say":{"who":"choeon","text":"나단이 왕에게, 마음에 있는 대로 하라고 했어."}},{"ref":"삼하 7:4-7","open":"삼하 7:5","focus":"nathan","text":{"t1":"그 밤에 여호와께서 나단에게, 다윗이 하나님이 계실 집을 짓겠느냐고 물으시는 말씀을 주셨어요. 하나님이 그동안 어디에 계시며 다니셨다고 하셨는지는 성경에서 찾아봐요.","t2":"그 밤에 나단에게 여호와의 말씀이 내렸어요. 하나님이 나단에게 무슨 말씀을 어떤 차례로 하셨는지는 4절부터 7절까지 읽어 봐요.","t3":"그 밤에 나단에게 여호와의 말씀이 내렸다. 여호와께서는 가서 그분의 종 다윗에게 전하라고 하셨다. 그때 다윗에게 무엇을 물으셨고, 애굽에서 이스라엘 자손을 인도해 내신 날부터 어디에 거하며 다니셨다고 하셨는지는 5절과 6절에서 직접 읽어 보자. 이스라엘 자손과 함께 다니신 모든 곳에서, 백성을 먹이라고 명하신 어느 지파에게도 어찌하여 백향목 집을 짓지 않았느냐고 말씀하신 적이 없다고 하셨다."},"say":{"who":"onwoo","text":"그 밤에 나단에게 임한 말씀이야. 하나님의 말씀은 우리가 지어내면 안 돼."}},{"ref":"삼하 7:8-11","open":"삼하 7:8","focus":"nathan","text":{"t1":"하나님은 양을 따르던 다윗을 데려다 이스라엘을 다스리게 하셨고, 어디를 가든지 함께 있었다고 하셨어요. 다윗의 이름을 존귀하게 해 주겠다고 하셨어요.","t2":"만군의 여호와께서는 다윗을 목장에서, 양을 따르던 자리에서 데려다 이스라엘의 주권자로 삼았다고 하셨어요. 다윗이 어디를 가든지 함께 있어 대적들을 물리쳤고, 다윗의 이름을 존귀하게 해 주겠다고 하셨어요. 또 백성 이스라엘을 위해 한 곳을 정해 거기 심겠다고 하셨는데, 왜 그러시는지는 10절에서 찾아봐요. 다윗도 둘레의 모든 원수에게서 놓여 평안하게 하겠다고 하셨어요.","t3":"만군의 여호와께서는 다윗을 목장에서, 양을 따르던 자리에서 데려다 그분의 백성 이스라엘의 주권자로 삼으셨다고 하셨다. 다윗이 어디를 가든지 함께 계셔서 그의 모든 대적을 그 앞에서 멸하셨고, 세상의 존귀한 사람들의 이름처럼 그의 이름을 존귀하게 해 주겠다고 하셨다. 또 백성 이스라엘을 위해 한 곳을 정하여 그들을 심고, 자기 곳에 살며 다시 옮기지 않게 하고, 악한 무리가 전처럼, 곧 사사들을 세워 백성을 다스리게 하시던 때처럼 그들을 해치지 못하게 하며, 다윗을 모든 대적에게서 벗어나 평안하게 하겠다고 하셨다."},"say":{"who":"hyu","text":"양을 따르던 목장에서 이스라엘의 주권자로. 말씀에 나온 차례대로 적어 둘게."}},{"ref":"삼하 7:11-13","open":"삼하 7:12","focus":"nathan","text":{"t1":"하나님은 다윗을 위해 집을 이루어 주겠다고 하셨어요. 다윗의 몸에서 날 자식을 세워 그 나라를 굳게 하고, 그가 하나님의 이름을 위해 집을 지을 것이라고 하셨어요.","t2":"여호와께서는 다윗을 위해 집을 이루어 주겠다고 하셨어요. 다윗의 날이 차서 조상들과 함께 잠들 때에, 다윗의 몸에서 날 자식을 그 뒤에 세워 그의 나라를 견고하게 하겠다고 하셨어요. 그가 하나님의 이름을 위해 집을 지을 것이고, 하나님은 그 나라의 왕위를 영원히 견고하게 하겠다고 하셨어요.","t3":"여호와께서는 다윗을 위하여 하실 일도 알리셨다. 다윗의 날이 차서 조상들과 함께 잠들 때에, 그의 몸에서 날 자식이 그의 뒤를 잇게 하여 그 나라를 굳게 세우겠다고 하셨다. 그가 여호와의 이름을 위하여 집을 지을 것이며, 여호와께서는 그 나라의 왕위를 영원히 견고하게 하겠다고 하셨다."},"say":{"who":"onwoo","text":"집을 짓는 사람이 누구라고 하셨는지, 12절과 13절에서 확인해 보자."}},{"ref":"삼하 7:14-16","open":"삼하 7:16","focus":"nathan","text":{"t1":"하나님은 다윗의 뒤에 세울 그 자식의 아버지가 되고, 그는 하나님의 아들이 될 것이라고 하셨어요. 다윗의 집과 나라가 영원히 하나님 앞에서 보전되고, 다윗의 왕위도 영원히 견고할 것이라고 하셨어요.","t2":"하나님은 다윗의 몸에서 날 그 자식의 아버지가 되고, 그는 하나님의 아들이 될 것이라고 하셨어요. 그가 죄를 범하면 징계하겠지만, 사울에게서 은총을 거두신 것처럼 그에게서 거두지는 않겠다고 하셨어요. 다윗의 집과 나라가 하나님 앞에서 영원히 보전되고, 다윗의 왕위가 영원히 견고할 것이라고 하셨어요.","t3":"여호와께서는 그의 아버지가 되시고 그는 여호와의 아들이 될 것이라고 하셨다. 그가 죄를 범하면 사람의 막대기와 사람의 채찍으로 징계하시겠으나, 다윗 앞에서 물리치신 사울에게서 은총을 거두신 것처럼 그에게서 거두지는 않겠다고 하셨다. 다윗의 집과 다윗의 나라가 여호와 앞에서 영원히 보전되고 그의 왕위가 영원히 견고할 것이라고 하셨다."},"say":{"who":"choeon","text":"영원히라는 말이 또 나왔어! 16절에는 두 번이나 있어."}},{"ref":"삼하 7:17","focus":"david","text":{"t1":"나단은 이 모든 말씀을 그대로 다윗에게 전했어요.","t2":"나단은 이 모든 말씀과 이 모든 묵시를 그대로 다윗에게 전했어요.","t3":"나단은 이 모든 말씀과 이 모든 묵시를 받은 그대로 다윗에게 전했다."},"say":{"who":"hyu","text":"나단이 그 밤에 받은 말씀을 다윗에게 다 전했어. 여기까지가 17절이야."}}],"gates":{"t1":[{"type":"find","ref":"삼하 7:2","prompt":"성경책에서 사무엘하 7장 2절을 찾아 읽어 보세요.","confirm":{"prompt":"왕은 나단에게, 하나님의 궤가 어디에 있다고 말했나요?","options":[{"label":"휘장 가운데","ok":true},{"label":"산 위의 굴 속","basis":"본문에 없음"},{"label":"강가의 배 안","basis":"본문에 없음"}]}},{"type":"multi","ref":"삼하 7:6","prompt":"성경책에서 사무엘하 7장 6절을 찾아 읽어 보세요.","confirm":{"prompt":"하나님은 애굽에서 이스라엘 자손을 이끌어 내신 날부터 어디에 계시며 다니셨다고 하셨나요? 모두 고르세요.","options":[{"label":"백향목 궁","basis":"삼하 7:2"},{"label":"장막","ok":true},{"label":"산꼭대기의 성","basis":"본문에 없음"},{"label":"회막","ok":true}]}}],"t2":[{"type":"find","ref":"삼하 7:2-3","prompt":"성경책에서 사무엘하 7장 2절과 3절을 읽어 보세요.","confirm":{"prompt":"나단이 왕에게 마음에 있는 것을 다 행하라고 한 까닭은 무엇인가요?","options":[{"label":"왕이 이미 백향목을 다 모아 두었기 때문에","basis":"본문에 없음"},{"label":"여호와께서 왕과 함께하시기 때문에","ok":true},{"label":"제사장들이 그렇게 하라고 했기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"삼하 7:4-7","prompt":"성경책에서 사무엘하 7장 4절부터 7절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["그날 밤, 나단에게 여호와의 말씀이 왔다","하나님이 나단에게, 가서 다윗에게 전하라고 하셨다","하나님이, 다윗이 하나님 계실 집을 짓겠느냐고 물으셨다","하나님이, 애굽에서 백성을 이끌어 낸 날부터 장막과 회막에 계시며 다니셨다고 하셨다","하나님이, 어느 지파에게도 백향목 집을 왜 안 짓느냐고 하신 적이 없다고 하셨다"]}],"t3":[{"type":"find","refs":["삼하 7:2","삼하 7:6"],"prompt":"사무엘하 7장 2절과 6절을 함께 찾아 읽어 보자.","confirm":{"prompt":"왕이 궤가 휘장 가운데 있다고 한 말과 이어 읽으면, 하나님은 지난날 어디에 거하셨다고 하셨는가?","options":[{"label":"왕은 자기는 백향목 궁에 사는데 궤는 휘장 가운데 있다고 했고, 하나님은 애굽에서 백성을 이끌어 낸 날부터 집이 아니라 장막과 회막에 계시며 다니셨다고 하셨다","ok":true},{"label":"왕은 자기는 백향목 궁에 사는데 궤는 휘장 가운데 있다고 했고, 하나님은 애굽에서 백성을 이끌어 낸 날부터 장막이 아니라 돌로 지은 집들에 계시며 다니셨다고 하셨다","basis":"본문에 없음"},{"label":"왕은 자기는 백향목 궁에 사는데 궤는 휘장 가운데 있다고 했고, 하나님은 애굽에서 백성을 이끌어 낸 날부터 장막이 아니라 성읍마다 지은 궁에 계시며 다니셨다고 하셨다","basis":"본문에 없음"}]}},{"type":"match","refs":["삼하 7:1","삼하 7:3","삼하 7:4"],"prompt":"사무엘하 7장 1절, 3절, 4절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"삼하 7:1","text":"여호와께서 사방의 대적을 물리치시고 왕이 궁에서 평안히 지내게 하셨다"},{"ref":"삼하 7:3","text":"나단이 왕에게, 여호와께서 함께하시니 마음에 품은 일을 하라고 했다"},{"ref":"삼하 7:4","text":"그날 밤 나단이 여호와의 말씀을 받았다"}],"after":"세 곳을 이으면, 다윗이 궁에서 평안히 지내던 때에 나단은 마음에 있는 대로 하라고 했고, 그날 밤 나단은 여호와의 말씀을 받았다."}]},"cards":[{"ref":"삼하 7:9","title":"어디를 가든지 함께"},{"ref":"삼하 7:16","title":"영원히 견고하리라"}],"close":{"t1":{"kind":"prayer","text":"하나님, 다윗에게 하신 말씀을 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 사무엘하 7장 8절부터 17절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"삼하 7:1-17에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 조종 손잡이가 부러졌으니, 깎아서 손잡이로 쓸 나무 조각을 찾아봐요. 궁에 있는 사람들이 하는 일에는 끼지 말고 곁에서 보기만 해요.","t2":"최현 박사예요. 비상 착륙 때 조종 손잡이가 부러졌는데, 이 시대에는 맞는 부속이 없어요. 왕의 궁이 있는 이곳에서 깎아서 손잡이로 쓸 나무 조각을 찾아봐요. 궁에 있는 사람들이 하는 일에는 끼지 말고 곁에서 보기만 해요.","t3":"최현 박사다. 비상 착륙 때 조종 손잡이가 부러졌고, 이 시대에는 맞는 부속이 없다. 왕의 궁이 있는 이곳에서 깎아 손잡이로 쓸 만한 나무 조각을 찾아야 한다. 궁의 물건에는 손대지 말고, 궁에 있는 사람들이 하는 일에는 끼지 않고 곁에서 보기만 하자."},"materials":[{"key":"cedar","name":"백향목 조각","basis":"삼하 7:2","use":"백향목 조각을 깎아서 부러진 조종 손잡이 대신 쓸 수 있어요.","how":"궁 안에는 들어가지 않고, 궁에서 떨어진 길가 땅에 떨어져 있는 작은 백향목 조각 하나를 줍는다. 궁과 사람들의 물건에는 손대지 않는다.","line":"궁에서 떨어진 길가 땅에서 작은 백향목 조각을 주웠어!"}],"companion":{"who":"나단","ref":"삼하 7:2","when":"after","talks":[{"ask":{"who":"choeon","text":"왕이 자기가 사는 궁과 하나님의 궤 이야기를 했을 때, 뭐라고 대답했어요?"},"answer":{"t1":"나단은 여호와께서 왕과 함께 계시니, 마음에 있는 대로 다 하라고 대답했어요.","t2":"나단은 왕에게 대답했어요. 여호와께서 왕과 함께 계시니, 마음에 있는 것을 다 행하라고 했어요.","t3":"나단은 왕에게, 여호와께서 왕과 함께 계시니 마음에 품은 것을 모두 행하라고 대답했다."},"ref":"삼하 7:3","open":"삼하 7:3"},{"ask":{"who":"onwoo","text":"그 밤에 받은 말씀에서, 하나님의 이름을 위해 집을 지을 사람은 누구라고 했어요?"},"answer":{"t1":"나단은 다윗의 몸에서 날 자식이 하나님의 이름을 위해 집을 지을 것이라고 하나님이 말씀하셨다고 전했어요.","t2":"나단은 다윗의 날이 차서 조상들과 함께 잠들 때, 하나님이 다윗의 몸에서 날 자식을 그 뒤에 세우겠다고 말씀하셨다고 전했어요. 그가 하나님의 이름을 위해 집을 지을 것이라고 하셨다고 전했어요.","t3":"나단은 여호와께서, 다윗의 날이 차서 조상들과 함께 잠들 때 그의 몸에서 날 자식을 그의 뒤에 세워 그 나라를 견고하게 하겠다고 말씀하셨다고 전했다. 그가 여호와의 이름을 위하여 집을 지을 것이며, 여호와께서 그 나라의 왕위를 영원히 견고하게 하겠다고 하셨다고 전했다."},"ref":"삼하 7:12-13","open":"삼하 7:12"},{"ask":{"who":"hyu","text":"다윗 왕의 집과 나라는 어떻게 된다고 전했어요?"},"answer":{"t1":"나단은 다윗의 집과 나라가 하나님 앞에서 영원히 보전되고, 다윗의 왕위가 영원히 견고할 것이라고 하나님이 말씀하셨다고 전했어요.","t2":"나단은 하나님이 다윗의 집과 나라가 하나님 앞에서 영원히 보전될 것이라고 말씀하셨다고 전했어요. 그리고 다윗의 왕위가 영원히 견고할 것이라고 하셨다고 전했어요.","t3":"나단은 여호와께서 다윗의 집과 다윗의 나라가 여호와 앞에서 영원히 보전되고, 다윗의 왕위가 영원히 견고할 것이라고 말씀하셨다고 전했다."},"ref":"삼하 7:16-17","open":"삼하 7:16"}]},"today":[{"q":"하나님도 집이 있어야 해요?","a":{"t1":"이 장면에서 하나님은 백성을 애굽에서 인도해 내신 날부터 집에 거하지 않고 장막에 거하며 다니셨다고 하셨어요. 그리고 다윗의 몸에서 날 자식이 하나님의 이름을 위해 집을 지을 것이라고 하셨어요.","t2":"이 장면에서 하나님은 이스라엘 자손을 애굽에서 인도해 내신 날부터 집에 거하지 않고 장막과 회막에 거하며 다니셨다고 하셨어요. 어느 지파에게도 왜 백향목 집을 짓지 않았느냐고 말씀하신 적이 없다고 하셨어요. 그러면서 다윗의 몸에서 날 자식이 하나님의 이름을 위해 집을 지을 것이라고 하셨어요.","t3":"이 장면에서 여호와께서는 이스라엘 자손을 애굽에서 인도해 내신 날부터 그날까지 집에 거하지 않고 장막과 회막에 거하며 다니셨다고 하셨다. 백성을 먹이라고 명하신 어느 지파에게도 어찌하여 백향목 집을 짓지 않았느냐고 말씀하신 적이 없다고 하셨다. 그러면서 다윗의 몸에서 날 자식이 여호와의 이름을 위하여 집을 지을 것이라고 하셨다. 성경은 이 장면에서 여기까지 말한다."},"refs":["삼하 7:5-7","삼하 7:12-13"]}],"help":{"who":"다윗 왕과 선지자 나단","steps":[{"kind":"watch","after":6,"title":"곁에서 보기 · 말씀을 전하는 나단","basis":"삼하 7:17","text":{"t1":"나단이 그 밤에 받은 말씀을 빠짐없이 다윗에게 전해요. 하나님이 나단에게 맡기신 일이라서 우리는 끼어들지 않고 곁에서 봐요.","t2":"나단은 그 밤에 받은 말씀과 묵시를 하나도 빼지 않고 다윗에게 전했어요. 여호와께서 나단에게 가서 전하라고 하신 일이라서, 우리는 끼어들지 않고 곁에서 봐요.","t3":"나단은 그 밤에 받은 말씀과 묵시를 하나도 빼지 않고 다윗에게 전했다(7:17). 여호와께서 나단에게 가서 다윗에게 말하라고 하신 일이므로(7:5), 탐험대는 끼어들지 않고 곁에서 본다."},"say":{"who":"hyu","text":"나단이 받은 말씀을 다윗에게 다 전했어. 우리는 듣기만 했어."}},{"kind":"do","after":6,"title":"들은 일을 탐험 일지에 정리하기","basis":"삼하 7:17","text":{"t1":"나단이 받은 말씀을 다윗에게 다 전했어요. 우리는 본 것을 탐험 일지에 차례대로 적고, 하나님의 말씀은 지어내지 않도록 장절만 적어 두었어요.","t2":"나단은 받은 말씀을 다윗에게 빠짐없이 전했어요. 이 장면에는 우리가 곁에서 도울 사람들의 일이 나오지 않아요. 그래서 우리는 본 것을 탐험 일지에 차례대로 적고, 하나님의 말씀은 지어내지 않도록 장절만 적어 두었어요. 성경에 적힌 일이 아니라 탐험대가 한 일이에요.","t3":"나단은 받은 말씀과 묵시를 그대로 다윗에게 알렸다(7:17). 이 장면에는 탐험대가 곁에서 도울 무리가 나오지 않는다. 탐험대는 본 것을 일지에 차례대로 적고, 하나님의 말씀은 지어내지 않도록 장절만 적어 둔다. 성경에 적힌 일이 아니라 탐험대 이야기다."},"tasks":["본 것을 차례대로 일지에 적기","하나님의 말씀은 장절만 적기(사무엘하 7장 5~16절)","궁의 물건에 손대지 않았는지 살피기"],"done":{"who":"onwoo","text":"일지 정리 끝. 말씀은 우리가 지어내지 않고, 성경책 사무엘하 7장에서 직접 읽자."}},{"kind":"ask","after":"gates","title":"그 밤에 다윗에게 하신 말씀은 무슨 뜻이에요?","basis":"삼하 7:8-11","by":"나단","ask":{"who":"onwoo","text":"그 밤에 하나님이 다윗 왕에게 하신 말씀은 무슨 뜻이에요?"},"answer":{"t1":"나단은 하나님이 양을 따르던 다윗을 데려다 이스라엘을 다스리게 하셨다고 말씀하셨다고 전했어요. 백성 이스라엘에게는 머물러 살 곳을 정해 주시고, 다윗을 위해서는 집을 이루어 주겠다고 하셨다고 전했어요.","t2":"나단은 하나님이 양을 따르던 다윗을 목장에서 데려다 이스라엘의 주권자로 삼으셨고, 다윗이 어디를 가든지 함께 계셨다고 말씀하셨다고 전했어요. 또 백성 이스라엘에게 한 곳을 정해 주겠다고 하셨고, 여호와께서 다윗을 위해 집을 이루어 주겠다고 하셨다고 전했어요.","t3":"나단은 만군의 여호와께서, 양을 따르던 다윗을 목장에서 데려다 백성 이스라엘의 주권자로 삼으셨고 그가 어디를 가든지 함께 계셨다고 말씀하셨다고 전했다. 또 백성 이스라엘을 위해 한 곳을 정하여 그들을 심겠다고 하셨고, 여호와께서 다윗을 위하여 집을 이루겠다고 하셨다고 전했다."},"read":{"t1":{"type":"find","ref":"삼하 7:10","prompt":"성경책에서 사무엘하 7장 10절을 찾아 읽어 보세요.","confirm":{"prompt":"하나님은 백성 이스라엘을 위해 무엇을 정해 주겠다고 하셨나요?","options":[{"label":"머물러 살 한 곳","ok":true},{"label":"싸움에 나갈 큰 군대","basis":"본문에 없음"},{"label":"배를 띄울 넓은 바다","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"삼하 7:10-11","prompt":"성경책에서 사무엘하 7장 10절과 11절을 읽어 보세요.","confirm":{"prompt":"하나님이 백성 이스라엘을 위해 한 곳을 정하여 심겠다고 하신 까닭은 무엇인가요?","options":[{"label":"백성이 자기 곳에 살며 다시 옮겨 다니지 않고, 악한 무리가 전처럼 해치지 못하게 하시려고","ok":true},{"label":"백성이 그곳에 큰 성을 쌓고, 둘레의 다른 나라들을 모두 다스리게 하시려고","basis":"본문에 없음"},{"label":"백성이 해마다 그곳에 모여 제사를 드리고, 절기를 빠짐없이 지키게 하시려고","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["삼하 7:5","삼하 7:11"],"prompt":"사무엘하 7장 5절과 11절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, '집'에 대해 하나님은 무엇을 물으시고 무엇을 하겠다고 하셨는가?","options":[{"label":"다윗에게 왜 아직 백향목 집을 짓지 않았느냐고 꾸짖으셨고, 여호와께서 다윗을 위하여 집을 이루겠다고 하셨다","basis":"본문에 없음"},{"label":"다윗이 하나님이 거하실 집을 짓겠느냐고 물으셨고, 다윗에게 백향목 궁을 하나 더 지어 주겠다고 하셨다","basis":"본문에 없음"},{"label":"다윗이 하나님이 거하실 집을 짓겠느냐고 물으셨고, 여호와께서 다윗을 위하여 집을 이루겠다고 하셨다","ok":true}]}}}}]}},"has3d":false,"epic":false},"OT-28":{"id":"OT-28","era":7,"title":"솔로몬이 성전을 봉헌함","ref":"왕상 8:1-30","place":"예루살렘, 여호와의 전","review":{"required":true,"topics":["구약 사건의 신약적 의미(행 7:47-48)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"왕상 8:1-2","focus":"assembly","text":{"t1":"솔로몬은 여호와의 언약궤를 메어 올리려고 이스라엘의 장로들을 예루살렘으로 불러 모았어요. 칠월 절기에 이스라엘 모든 사람이 솔로몬 왕 앞에 모였어요.","t2":"솔로몬은 이스라엘의 장로들과 지파의 우두머리들과 족장들을 예루살렘으로 불러 모았어요. 무엇을 하려고 불러 모았는지는 1절에서 찾아봐요. 칠월 절기가 되자 이스라엘 모든 사람이 솔로몬 왕 앞으로 모였어요.","t3":"솔로몬은 다윗 성 곧 시온에 있는 여호와의 언약궤를 메고 올라오려고, 이스라엘의 장로들과 모든 지파의 우두머리인 족장들을 예루살렘의 자기에게로 불러 모았다. 이스라엘 모든 사람이 에다님월, 곧 칠월의 절기에 솔로몬 왕에게 모였다."},"say":{"who":"hyu","text":"여기는 예루살렘이야. 칠월 절기에 사람들이 다 모였어. 일지에 적어 둘게."}},{"ref":"왕상 8:3-9","focus":"ark","text":{"t1":"제사장들이 궤를 메고 올라가 지성소 안, 그룹들의 날개 밑에 들여놓았어요. 궤 안에 무엇이 있었는지는 성경에서 찾아봐요.","t2":"장로들이 다 오자 궤를 메고 올라가는 일이 시작되었어요. 누가 무엇을 메었고 그 뒤에 무슨 일이 어떤 차례로 있었는지는 3절부터 9절까지 읽어 봐요. 궤 안에는 모세가 호렙에서 넣은 두 돌판 말고는 아무것도 없었어요.","t3":"이스라엘의 장로들이 다 이르자 제사장들이 궤를 메었고, 제사장과 레위 사람들이 여호와의 궤와 회막과 성막 안의 거룩한 기구들을 모두 메고 올라갔다. 솔로몬 왕과 그 앞에 모인 회중은 궤 앞에서 양과 소로 제사를 드렸는데, 그 수가 많아 적을 수도 셀 수도 없었다. 제사장들은 언약궤를 제자리인 내전 지성소, 그룹들의 날개 아래로 메어 들였다. 그룹들이 날개를 펴서 궤와 채를 덮었고, 채가 길어 그 끝이 내전 앞 성소에서는 보였으나 밖에서는 보이지 않았다. 궤 안에는 두 돌판 말고는 아무것도 없었는데, 이스라엘 자손이 애굽 땅을 떠나온 뒤 여호와께서 그들과 언약을 세우실 때 모세가 호렙에서 넣은 것이다."},"say":{"who":"onwoo","text":"궤가 지나가고 있어. 우리는 멀리서 지켜보자."}},{"ref":"왕상 8:10-11","focus":"cloud","text":{"t1":"제사장들이 성소에서 나오자 여호와의 전이 구름으로 가득 찼어요. 여호와의 영광이 가득해서 제사장들은 서서 섬길 수 없었어요.","t2":"제사장들이 성소에서 나올 때 구름이 여호와의 전에 가득했어요. 제사장들은 그 구름 때문에 서서 섬길 수 없었어요. 여호와의 영광이 여호와의 전에 가득했기 때문이에요.","t3":"제사장들이 성소에서 나올 때 구름이 여호와의 전을 가득 채웠다. 제사장들은 그 구름 때문에 서서 섬기지 못했는데, 여호와의 영광이 여호와의 전에 가득했기 때문이다."},"say":{"who":"choeon","text":"구름이야! 전에 구름이 가득해서 제사장들이 서서 섬기지 못해."}},{"ref":"왕상 8:12-21","open":"왕상 8:18","focus":"solomon","text":{"t1":"솔로몬은 서 있는 온 회중을 축복하며, 여호와께서 다윗에게 하신 말씀을 이루셨다고 했어요. 자기가 다윗을 대신해 여호와의 이름을 위한 전을 지었다고 말했어요.","t2":"솔로몬은 주를 위해 계실 전을 지었다고 아뢰고, 얼굴을 돌려 서 있는 온 회중을 위해 축복했어요. 여호와께서 아버지 다윗에게 입으로 하신 말씀을 손으로 이루셨다고 했어요. 다윗에게 전을 지을 마음이 있었는데, 하나님은 그 마음이 좋다고 하시면서도 다윗이 아니라 그의 아들이 전을 지을 것이라고 하셨다고 했어요. 솔로몬은 자기가 다윗을 대신하여 일어나 전을 짓고, 언약을 넣은 궤를 둘 곳을 마련했다고 말했어요.","t3":"솔로몬은 여호와께서 캄캄한 곳에 머무르시겠다고 말씀하셨다고 하며, 자기가 주를 위하여 계실 전을 지었다고 아뢰었다. 그러고는 얼굴을 돌려 서 있는 이스라엘 온 회중을 위하여 축복했다. 그는 여호와께서 아버지 다윗에게 입으로 약속하신 것을 손으로 이루셨다고 송축했다. 다윗에게는 여호와의 이름을 위한 전을 지으려는 마음이 있었는데, 여호와께서는 그 마음이 좋다고 하시되 다윗은 짓지 못하고 그의 몸에서 날 아들이 지을 것이라고 하셨다고 했다. 솔로몬은 여호와께서 하신 말씀을 그대로 이루셔서, 자기가 다윗의 뒤를 이어 일어나 이스라엘의 왕위에 앉고 전을 지었으며, 여호와의 언약을 넣은 궤를 둘 자리를 거기 마련했다고 말했다."},"say":{"who":"onwoo","text":"하나님이 다윗에게 하신 말씀을 솔로몬이 전하고 있어. 18절과 19절을 성경책에서 직접 읽어 보자."}},{"ref":"왕상 8:22-26","focus":"solomon","text":{"t1":"솔로몬은 하늘과 땅 어디에도 주와 같은 신이 없다고 기도했어요.","t2":"솔로몬은 여호와의 단 앞에서 온 회중을 마주 보고 서서 하늘을 향해 손을 폈어요. 위로 하늘과 아래로 땅에 주와 같은 신이 없다고 기도했어요. 주께서는 온 마음으로 주 앞에서 살아가는 종들에게 언약을 지키시며 은혜를 베풀어 주신다고 했어요. 그리고 아버지 다윗에게 하신 말씀을 지켜 달라고 구했어요.","t3":"솔로몬은 기도를 시작했다. 그는 위로 하늘과 아래로 땅에 주와 같은 신이 없으며, 주께서는 마음을 다해 주 앞에서 살아가는 종들에게는 언약을 지키시며 은혜를 베풀어 주신다고 아뢰었다. 주께서 아버지 다윗에게 하신 말씀을 지키셔서, 입으로 하신 말씀을 손으로 이루신 것이 그날 보는 바와 같다고 했다. 또 다윗의 자손이 자기 길을 삼가 다윗처럼 주 앞에서 행하기만 하면 이스라엘의 왕위에 앉을 사람이 끊어지지 않으리라고 하신 말씀을 지켜 주시고, 다윗에게 하신 말씀이 틀림없이 이루어지기를 구했다."},"say":{"who":"choeon","text":"솔로몬이 기도를 시작해. 어떤 모습인지 22절에서 확인해 보자."}},{"ref":"왕상 8:27-30","open":"왕상 8:27","focus":"solomon","text":{"t1":"솔로몬은 하늘과 하늘들의 하늘도 주님을 모실 수 없는데, 자기가 지은 이 전은 더욱 그렇다고 했어요. 그래도 이곳을 향해 기도할 때 하늘에서 들으시고 용서해 달라고 기도했어요.","t2":"솔로몬은 하나님이 정말로 땅에 머무르시겠느냐고 아뢰었어요. 하늘과 하늘들의 하늘도 주님을 모실 수 없는데, 자기가 지은 이 전은 더욱 그렇다고 했어요. 그래도 주의 이름이 거기 있으리라고 하신 이 전을 밤낮으로 보아 달라고 구했어요.","t3":"솔로몬은 하나님이 정말 땅에 거하시겠느냐고 아뢰며, 하늘과 하늘들의 하늘도 주를 담지 못하는데 자기가 지은 이 전은 더욱 그러하다고 했다. 그러나 종이 드리는 간구와 기도를 살피시고, 그날 주 앞에서 부르짖는 기도를 들어 달라고 구했다. 솔로몬과 이스라엘 백성이 이 전을 향해 기도할 때, 주께서 하늘 거처에서 들으시고 죄를 사하여 주시기를 구했다."},"say":{"who":"onwoo","text":"솔로몬의 기도는 길어. 27절부터 30절까지 성경책에서 천천히 읽어 보자."}},{"ref":"왕상 8:54-61","focus":"solomon","text":{"t1":"기도를 마친 솔로몬은 무릎을 꿇고 있다가 일어나, 큰 소리로 온 회중을 축복했어요. 하나님이 약속하신 선한 말씀이 하나도 빠짐없이 이루어졌다고 했어요.","t2":"솔로몬은 무릎을 꿇고 하늘을 향해 손을 펴고 기도하기를 마치고, 단 앞에서 일어나 큰 소리로 온 회중을 위해 축복했어요. 여호와께서 약속하신 대로 백성에게 평안을 주셨고, 모세를 통해 약속하신 선한 말씀이 하나도 빠짐없이 이루어졌다고 했어요. 하나님이 조상들과 함께 계셨던 것처럼 함께 계시고 떠나지 마시기를 구했어요. 그리고 백성에게, 마음을 온전히 하여 여호와의 법도와 계명을 지키라고 했어요.","t3":"솔로몬은 기도와 간구를 마치고 일어나 서서 큰 목소리로 이스라엘 온 회중을 위하여 축복했다. 그는 여호와께서 약속하신 대로 이스라엘 백성에게 평안을 주셨고, 종 모세를 통해 약속하신 선한 말씀이 하나도 빠짐없이 이루어졌다고 찬송했다. 여호와께서 조상들과 함께 계셨던 것처럼 함께 계시고 떠나지도 버리지도 마시며, 그들의 마음을 주께로 향하게 하셔서 조상들에게 주신 계명과 율례와 법도를 그들이 지키게 되기를 구했다. 그리하여 세상 모든 백성이 여호와만 하나님이시고 그 밖에는 없는 줄을 알게 되기를 바란다고 했다. 그리고 백성에게, 마음을 여호와께 온전히 하여 그날처럼 법도를 행하고 계명을 지키라고 했다."},"say":{"who":"hyu","text":"기도를 마치고 일어나서 축복했어. 기도하던 모습은 54절에서 찾아 적자."}}],"gates":{"t1":[{"type":"find","ref":"왕상 8:9","prompt":"성경책에서 열왕기상 8장 9절을 찾아 읽어 보세요.","confirm":{"prompt":"궤 안에는 무엇이 있었나요?","options":[{"label":"두 돌판","ok":true},{"label":"왕의 면류관","basis":"본문에 없음"},{"label":"양각 나팔","basis":"본문에 없음"}]}},{"type":"multi","ref":"왕상 8:22","prompt":"성경책에서 열왕기상 8장 22절을 찾아 읽어 보세요.","confirm":{"prompt":"22절에 적힌, 솔로몬이 기도를 시작할 때의 모습을 모두 고르세요.","options":[{"label":"여호와의 단 앞에 섰어요","ok":true},{"label":"무릎을 꿇었어요","basis":"왕상 8:54"},{"label":"온 회중을 마주 보고 섰어요","ok":true},{"label":"지성소 안으로 들어갔어요","basis":"본문에 없음"},{"label":"하늘을 향해 손을 폈어요","ok":true}]}}],"t2":[{"type":"find","ref":"왕상 8:1-2","prompt":"성경책에서 열왕기상 8장 1절과 2절을 읽어 보세요.","confirm":{"prompt":"솔로몬이 이스라엘의 장로들과 족장들을 예루살렘으로 불러 모은 까닭은 무엇인가요?","options":[{"label":"실로에 있던 언약궤를 싸움터의 진으로 가져오려고","basis":"삼상 4:3-4"},{"label":"다윗 성에 있던 여호와의 언약궤를 메어 올라오려고","ok":true},{"label":"바알레유다에 있던 하나님의 궤를 옮겨 오려고","basis":"삼하 6:2"}]}},{"type":"order","ref":"왕상 8:3-11","prompt":"성경책에서 열왕기상 8장 3절부터 11절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["장로들이 모두 이르자, 궤를 제사장들이 메었다","솔로몬과 회중이 궤 앞에서 헤아릴 수 없이 많은 양과 소를 드렸다","제사장들이 궤를 지성소 안 그룹들 날개 밑에 들여놓았다","제사장들이 나오자 여호와의 전이 구름으로 가득 찼다"]}],"t3":[{"type":"find","refs":["왕상 8:22","왕상 8:54"],"prompt":"열왕기상 8장 22절과 54절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 솔로몬은 어떤 모습으로 기도했는가?","options":[{"label":"단 앞에서 온 회중을 마주 보고 서서 하늘을 향해 손을 폈고, 기도를 마칠 때에는 무릎을 꿇고 손을 편 채였다가 단 앞에서 일어났다","ok":true},{"label":"단 앞에서 온 회중을 마주 보고 무릎을 꿇은 채 손을 폈고, 기도를 마칠 때에는 엎드려 있다가 일어났다","basis":"본문에 없음"},{"label":"단 앞에서 회중에게 등을 돌리고 엎드려 기도를 시작했고, 기도를 마칠 때에는 앉아 있다가 일어났다","basis":"본문에 없음"}]}},{"type":"match","refs":["왕상 8:9","왕상 8:11","왕상 8:21"],"prompt":"열왕기상 8장 9절, 11절, 21절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"왕상 8:9","text":"궤 안에는 모세가 호렙에서 넣은 두 돌판 말고는 아무것도 없었다"},{"ref":"왕상 8:11","text":"여호와의 영광이 전을 가득 채워 제사장들이 서서 섬길 수 없었다"},{"ref":"왕상 8:21","text":"솔로몬은 조상들과 세우신 언약을 넣은 궤를 위해 한 처소를 마련했다고 말했다"}],"after":"세 곳을 이으면, 솔로몬은 모세가 호렙에서 넣은 두 돌판이 든 언약궤를 위해 처소를 마련했고, 여호와의 영광이 그 성전을 가득 채웠다는 것이 보인다."}]},"cards":[{"ref":"왕상 8:27","title":"하늘들의 하늘이라도"},{"ref":"왕상 8:56","title":"선한 말씀이 다 이루어짐"}],"close":{"t1":{"kind":"prayer","text":"하나님, 솔로몬이 여호와의 전에서 드린 기도를 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 열왕기상 8장 22절부터 30절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"왕상 8:1-30, 8:54-61에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 연료관을 묶던 줄이 끊어졌으니, 꼬아서 줄로 쓸 것을 찾아봐요. 모인 사람들 곁에서 함께 있되, 전과 거룩한 물건에는 다가가지 말아요.","t2":"최현 박사예요. 비상 착륙 때 연료관을 묶던 줄이 끊어졌는데, 이 시대에는 맞는 부속이 없어요. 예루살렘에서 꼬아서 줄 대신 쓸 수 있는 것을 찾아봐요. 모인 사람들 곁에서 함께 있는 것은 괜찮지만, 전과 그 안의 거룩한 물건에는 다가가지 말고 멀리서 보기만 해요.","t3":"최현 박사다. 비상 착륙 때 연료관을 묶던 줄이 끊어졌고, 이 시대에는 맞는 부속이 없다. 예루살렘에서 꼬아 줄 대신 쓸 만한 것을 찾아야 한다. 모인 사람들 곁에서 함께 있되, 전과 그 안의 거룩한 물건에는 가까이 가지 말자."},"materials":[{"key":"grass","name":"마른 풀 줄기","basis":"왕상 8:1","use":"마른 풀 줄기를 꼬아서 끊어진 줄 대신 쓸 수 있어요.","how":"전과 단에서 멀리 떨어진 예루살렘 길가 땅에서, 말라 떨어져 있는 풀 줄기 몇 가닥을 줍는다. 궤와 제물과 전의 기구에는 다가가지 않는다.","line":"전에서 멀리 떨어진 예루살렘 길가에서 마른 풀 줄기를 주웠어!"}],"companion":{"who":"솔로몬","ref":"왕상 8:1","when":"after","talks":[{"ask":{"who":"choeon","text":"전에 구름이 가득했을 때 뭐라고 말했어요?"},"answer":{"t1":"솔로몬은 여호와께서 캄캄한 데 계시겠다고 말씀하셨다고 했어요. 그리고 자기가 주께서 계실 전을 지었다고 아뢰었어요.","t2":"솔로몬은 여호와께서 캄캄한 데 계시겠다고 말씀하셨다고 했어요. 그리고 자기가 주를 위하여 계실 전을 지었으니, 주께서 영원히 계실 곳이라고 아뢰었어요.","t3":"솔로몬은 여호와께서 캄캄한 데 계시겠다고 말씀하셨다고 하며, 자기가 참으로 주를 위하여 계실 전을 지었으니 주께서 영원히 거하실 곳이라고 아뢰었다."},"ref":"왕상 8:12-13","open":"왕상 8:12"},{"ask":{"who":"hyu","text":"아버지 다윗 왕은 전을 짓지 않았어요?"},"answer":{"t1":"솔로몬은 아버지 다윗에게 여호와의 이름을 위해 전을 지을 마음이 있었다고 말했어요. 하나님은 그 마음이 좋다고 하시면서도, 다윗의 아들이 전을 지을 것이라고 하셨다고 했어요.","t2":"솔로몬은 아버지 다윗에게 여호와의 이름을 위하여 전을 지을 마음이 있었다고 말했어요. 하나님은 그 마음이 좋다고 하셨지만, 다윗은 그 전을 짓지 못하고 다윗의 몸에서 날 아들이 지을 것이라고 하셨다고 했어요. 그리고 하나님이 말씀하신 대로, 자기가 다윗을 대신하여 일어나 전을 지었다고 했어요.","t3":"솔로몬은 아버지 다윗에게 여호와의 이름을 위하여 전을 지으려는 마음이 있었다고 말했다. 여호와께서는 그 마음이 좋다고 하시면서도, 다윗은 그 전을 짓지 못하고 그의 몸에서 날 아들이 여호와의 이름을 위하여 전을 지을 것이라고 하셨다고 했다. 그리고 여호와께서 말씀하신 대로 이루셔서, 자기가 다윗을 대신하여 일어나 이스라엘의 왕위에 앉고 전을 지었다고 했다."},"ref":"왕상 8:17-20","open":"왕상 8:18"},{"ask":{"who":"onwoo","text":"기도를 마치고 일어나서 백성에게 뭐라고 했어요?"},"answer":{"t1":"솔로몬은 여호와께서 약속하신 선한 말씀이 하나도 빠짐없이 이루어졌다고 찬송했어요. 그리고 백성에게 마음을 여호와께 온전히 하여 계명을 지키라고 했어요.","t2":"솔로몬은 여호와께서 약속하신 대로 백성에게 평안을 주셨고, 모세를 통해 하신 선한 말씀이 하나도 빠짐없이 이루어졌다고 찬송했어요. 하나님이 조상들과 함께 계셨던 것처럼 함께 계시고 떠나지 마시기를 구했어요. 그리고 백성에게 마음을 여호와께 온전히 하여 법도와 계명을 지키라고 했어요.","t3":"솔로몬은 여호와께서 약속하신 대로 백성 이스라엘에게 태평을 주셨고, 종 모세를 통해 약속하신 선한 말씀이 하나도 빠짐없이 이루어졌다고 찬송했다. 여호와께서 조상들과 함께 계셨던 것처럼 함께 계시고 떠나지도 버리지도 마시기를 구했고, 세상 모든 백성이 여호와만 하나님이시고 그 밖에는 없는 줄 알게 되기를 바란다고 했다. 그리고 백성에게 마음을 여호와께 온전히 하여 그날처럼 법도를 행하고 계명을 지키라고 했다."},"ref":"왕상 8:56-61","open":"왕상 8:56"}]},"today":[{"q":"하나님은 성전 안에만 계세요?","a":{"t1":"솔로몬은 하늘과 하늘들의 하늘도 주님을 모실 수 없는데, 자기가 지은 전은 더욱 그렇다고 기도했어요. 그리고 백성이 이곳을 향해 기도할 때 주께서 계신 하늘에서 들어 달라고 구했어요.","t2":"솔로몬은 하나님이 참으로 땅에 거하시겠느냐고 아뢰었어요. 하늘과 하늘들의 하늘도 주님을 모실 수 없는데, 자기가 지은 이 전은 더욱 그렇다고 했어요. 그리고 종과 백성 이스라엘이 이 전을 향해 기도할 때, 주께서 계신 곳 하늘에서 들어 달라고 구했어요. 성경은 이 장면에서 여기까지 말해요.","t3":"솔로몬은 하나님이 참으로 땅에 거하시겠느냐고 아뢰며, 하늘과 하늘들의 하늘이라도 주를 모시지 못하는데 자기가 지은 이 전은 더욱 그러하다고 기도했다. 그러면서도 종과 주의 백성 이스라엘이 이 전을 향해 기도할 때, 주께서 계신 하늘에서 들으시고 용서해 주시기를 구했다. 성경은 이 장면에서 여기까지 말한다."},"refs":["왕상 8:27","왕상 8:30"]},{"q":"왜 전에 구름이 가득했어요?","a":{"t1":"성경은 구름이 왜 왔는지 따로 말하지 않아요. 제사장들이 그 구름 때문에 서서 섬길 수 없었는데, 여호와의 영광이 전에 가득했기 때문이라고 말해요.","t2":"성경은 제사장들이 성소에서 나올 때 구름이 여호와의 전에 가득했다고 말해요. 제사장들은 그 구름 때문에 서서 섬길 수 없었는데, 여호와의 영광이 그 전에 가득했기 때문이라고 해요. 출애굽기에도 모세 때 구름이 회막을 덮고 여호와의 영광이 성막에 가득해서 모세가 회막에 들어갈 수 없었다고 적혀 있어요.","t3":"성경은 제사장들이 성소에서 나올 때 구름이 여호와의 전에 가득했고, 제사장들이 그 구름 때문에 서서 섬기지 못했으며, 그것은 여호와의 영광이 그 전에 가득했기 때문이라고 말한다. 출애굽기도 모세 때 구름이 회막을 덮고 여호와의 영광이 성막에 가득하여 모세가 회막에 들어가지 못했다고 적는다. 구름이 왜 그때 왔는지는 성경이 따로 말하지 않는다."},"refs":["왕상 8:10-11","출 40:34-35"]}],"help":{"who":"예루살렘에 모인 이스라엘 회중","steps":[{"kind":"do","after":0,"title":"절기에 모여드는 사람들의 보따리 들어 주기","basis":"왕상 8:2","text":{"t1":"칠월 절기에 이스라엘 모든 사람이 솔로몬 왕 앞에 모였어요. 우리는 전에서 멀리 떨어진 길에서, 모여드는 사람들의 보따리를 함께 들어 주며 도왔어요. 궤와 제물에는 다가가지 않아요.","t2":"칠월 절기가 되어 이스라엘 모든 사람이 예루살렘으로, 솔로몬 왕 앞에 모였어요. 우리는 전과 단에서 멀리 떨어진 길에서, 모여드는 사람들의 보따리를 함께 들어 주고 길을 비켜 주었어요. 궤와 제물과 전의 기구에는 다가가지 않아요. 성경에 적힌 일이 아니라 탐험대가 한 일이에요.","t3":"칠월 절기에 이스라엘 모든 사람이 솔로몬 왕 앞에 모였다(8:2). 탐험대는 전과 단에서 멀리 떨어진 예루살렘 길에서, 모여드는 사람들의 보따리를 함께 들어 주고 길을 비켜 준다. 성경에 적힌 일이 아니라 탐험대 이야기다. 궤와 제물과 전의 기구에는 다가가지 않는다."},"tasks":["사람들이 지고 온 보따리 함께 들어 주기","보따리를 길가에 가지런히 내려 주기","뒤에 오는 사람들에게 길 비켜 주기"],"done":{"who":"choeon","text":"사람들이 계속 모여들어. 칠월 절기라서 온 이스라엘이 왕 앞에 모인대."}},{"kind":"watch","after":1,"title":"멀리서 보기 · 궤를 멘 제사장들","basis":"왕상 8:3-6","text":{"t1":"제사장들이 여호와의 궤를 메고 올라가 지성소에 들여놓았어요. 제사장들이 하는 거룩한 일이라서, 우리는 궤와 기구에 다가가지 않고 멀리서 봐요.","t2":"제사장과 레위 사람들이 궤와 회막과 거룩한 기구들을 메어 올려요. 본문이 정한 사람들의 거룩한 일이라서, 우리는 궤와 기구에 손대지 않고 멀리서 봐요.","t3":"제사장들이 궤를 메었고(8:3), 제사장과 레위 사람들이 여호와의 궤와 회막과 거룩한 기구들을 함께 메어 올렸다(8:4). 제사장들은 언약궤를 내전 지성소의 제자리에 들여놓았다(8:6). 본문이 행위자를 정한 거룩한 일이므로, 탐험대는 궤와 기구와 제물에 다가가지 않고 멀리서 본다."},"say":{"who":"onwoo","text":"궤와 기구는 제사장과 레위 사람들이 멨어. 우리는 멀리서 보자."}},{"kind":"stay","after":3,"title":"회중과 함께 서 있기","basis":"왕상 8:14","text":{"t1":"솔로몬이 축복할 때 이스라엘 온 회중이 서 있었어요. 우리도 회중 뒤쪽에서 함께 서 있어요.","t2":"솔로몬이 얼굴을 돌려 이스라엘 온 회중을 위해 축복할 때, 회중은 모두 서 있었어요. 우리도 회중 뒤쪽에서 함께 서서 기다려요.","t3":"솔로몬이 얼굴을 돌려 이스라엘 온 회중을 위하여 축복할 때 온 회중이 서 있었다(8:14). 탐험대도 전과 단에서 멀리 떨어진 회중 뒤쪽에서 함께 서서 기다린다."},"wait":"회중 뒤에서 함께 서 있기","say":{"who":"hyu","text":"회중이 다 서 있어. 우리도 뒤에서 같이 서 있자."}},{"kind":"ask","after":"gates","title":"이 전을 지어 드린 일은 무슨 뜻이에요?","basis":"왕상 8:28-29","by":"솔로몬","ask":{"who":"hyu","text":"솔로몬 왕님, 이 전을 지어 여호와께 드린 일은 무슨 뜻이에요?"},"answer":{"t1":"솔로몬은 이 전이, 여호와의 이름이 그곳에 있을 것이라고 여호와께서 말씀하신 곳이라고 말했어요. 그래서 주의 눈이 밤낮으로 이 전을 보시고, 이곳을 향해 드리는 기도를 들어 달라고 구했어요.","t2":"솔로몬은 기도하면서, 이 전은 여호와의 이름이 그곳에 있을 것이라고 여호와께서 말씀하신 곳이라고 했어요. 주의 눈이 밤낮으로 이 전을 보시고, 이곳을 향해 종이 드리는 기도를 들어 달라고 구했어요.","t3":"솔로몬은 기도하면서, 이 전은 여호와의 이름이 그곳에 있을 것이라고 여호와께서 전에 말씀하신 곳이라고 했다. 그는 종이 기도하며 간구하는 것을 살펴 주시고, 주의 눈이 밤낮으로 이 전을 보시며, 그곳을 향해 종이 드리는 기도를 들어 달라고 구했다."},"read":{"t1":{"type":"find","ref":"왕상 8:29","prompt":"성경책에서 열왕기상 8장 29절을 찾아 읽어 보세요.","confirm":{"prompt":"솔로몬은 주의 눈이 언제 이 전을 보시기를 구했나요?","options":[{"label":"절기 때에만","basis":"본문에 없음"},{"label":"밤낮으로","ok":true},{"label":"안식일에만","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"왕상 8:28-30","prompt":"성경책에서 열왕기상 8장 28절부터 30절까지 읽어 보세요.","confirm":{"prompt":"솔로몬이 주의 눈이 밤낮으로 이 전을 보시기를 구한 까닭은 무엇인가요?","options":[{"label":"솔로몬과 이스라엘 백성이 이곳을 향해 기도할 때, 하늘에서 들으시고 용서해 주시기를 바랐기 때문에","ok":true},{"label":"솔로몬이 이 전에 둔 금과 은과 여러 기구를, 밤낮으로 지켜 주시기를 바랐기 때문에","basis":"본문에 없음"},{"label":"솔로몬과 이스라엘 백성이 이곳에 모여 절기를 지킬 때, 해마다 큰 복을 내려 주시기를 바랐기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["왕상 8:16","왕상 8:29"],"prompt":"열왕기상 8장 16절과 29절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 이 전과 여호와의 이름은 어떻게 이어지는가?","options":[{"label":"여호와께서는 애굽에서 백성을 이끌어 낸 날부터 이름을 둘 집을 지으려고 어느 성읍도 고르지 않으셨다고 하셨고, 솔로몬은 이 전을 다윗의 이름이 영원히 기억될 곳이라고 했다","basis":"본문에 없음"},{"label":"여호와께서는 애굽에서 백성을 이끌어 낸 날부터 이름을 둘 집을 지으려고 어느 성읍도 고르지 않으셨다고 하셨고, 솔로몬은 이 전을 여호와께서 그 이름이 그곳에 있을 것이라고 하신 곳이라고 했다","ok":true},{"label":"여호와께서는 애굽에서 백성을 이끌어 낸 날부터 이름을 둘 성읍을 해마다 새로 고르셨다고 하셨고, 솔로몬은 이 전을 여호와께서 그 이름이 그곳에 있을 것이라고 하신 곳이라고 했다","basis":"본문에 없음"}]}}},"nt":{"ref":"행 7:47-48","text":"신약의 사도행전 7장 47~48절은 솔로몬이 하나님을 위하여 집을 지었다고 말하고, 가장 높으신 분은 손으로 지은 곳에 머무르시지 않는다고 말한다."}}]}},"has3d":false,"epic":false},"OT-29":{"id":"OT-29","era":8,"title":"나라가 둘로 갈라짐","ref":"왕상 12:1-24","place":"온 이스라엘이 모인 곳, 예루살렘","review":{"required":true,"topics":["하나님의 주권과 사람의 책임(왕상 12:15, 12:24)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"왕상 12:1-3","focus":"shechem","text":{"t1":"온 이스라엘이 르호보암을 왕으로 세우려고 한곳에 모였고, 르호보암도 그리로 갔어요. 그곳이 어디인지는 성경에서 찾아봐요.","t2":"솔로몬의 아들 르호보암이 세겜으로 갔어요. 왜 세겜으로 갔는지는 1절에서 찾아봐요. 솔로몬 왕을 피해 애굽에 가 있던 여로보암도 사람들이 불러서 왔어요.","t3":"르호보암이 세겜으로 갔다. 온 이스라엘이 그를 왕으로 세우려고 세겜에 와 있었기 때문이다. 느밧의 아들 여로보암은 전에 솔로몬 왕을 피해 애굽으로 달아나 있었는데, 그 소식을 들었고 사람들이 사람을 보내어 그를 불렀다. 여로보암과 이스라엘의 온 회중이 르호보암에게 와서 말했다."},"say":{"who":"hyu","text":"르호보암이 이리로 왔어. 일지에 적어 둘게."}},{"ref":"왕상 12:4-5","focus":"people","text":{"t1":"백성은 무거운 멍에를 가볍게 해 주면 왕을 섬기겠다고 했어요. 르호보암은 사흘 뒤에 다시 오라고 했어요.","t2":"백성은 왕의 아버지가 메운 무거운 멍에를 가볍게 해 달라고 했어요. 그렇게 해 주면 왕을 섬기겠다고 했어요. 르호보암은 갔다가 사흘 뒤에 다시 오라고 했고, 백성은 돌아갔어요.","t3":"그들은 왕의 아버지가 자기들의 멍에를 무겁게 했으니, 이제 왕은 아버지가 시킨 고된 일과 무거운 멍에를 가볍게 해 달라고 했다. 그렇게 해 주면 자기들이 어떻게 하겠다고 했는지는 4절에 있다. 르호보암은 갔다가 사흘 뒤에 다시 오라고 대답했고, 백성은 물러갔다."},"say":{"who":"choeon","text":"사람들이 왕에게 멍에를 가볍게 해 달라고 말했어."}},{"ref":"왕상 12:6-7","focus":"elders","text":{"t1":"르호보암은 아버지 솔로몬을 모셨던 노인들에게 물었어요. 노인들은 백성을 섬기며 좋은 말로 대답하라고 했어요.","t2":"르호보암 왕은 아버지 솔로몬이 살아 있을 때 그 앞에서 섬기던 노인들과 의논했어요. 노인들은 왕이 오늘 이 백성을 섬기고 좋은 말로 대답하면, 백성이 언제까지나 왕의 종이 될 것이라고 했어요.","t3":"르호보암 왕은 아버지 솔로몬이 살아 있을 때 그 앞에서 섬기던 노인들과 의논하며, 이 백성에게 어떻게 대답하면 좋을지 물었다. 노인들이 왕에게 어떻게 하라고 했고 그러면 어떻게 되리라고 했는지는 7절에서 직접 읽어 보자."},"say":{"who":"hyu","text":"왕이 먼저 노인들에게 물었어. 순서를 적어 둘게."}},{"ref":"왕상 12:8-11","focus":"youngmen","text":{"t1":"그런데 왕은 노인들의 말을 버리고, 함께 자란 젊은 사람들에게 다시 물었어요. 그들은 멍에를 더 무겁게 하겠다고 대답하라고 했어요.","t2":"왕은 노인들이 일러 준 것을 버리고, 자기와 함께 자라서 자기를 모시고 있던 젊은 사람들과 의논했어요. 그들은 아버지가 메운 멍에보다 더 무거운 멍에를 메우겠다고 대답하라고 했어요.","t3":"왕은 노인들이 일러 준 것을 버리고, 자기와 함께 자라나 자기 앞에서 섬기던 젊은 사람들과 의논했다. 그들은 왕에게, 자기 새끼손가락이 아버지의 허리보다 굵다고 대답하라고 했다. 아버지는 무거운 멍에를 메웠으나 자기는 그 멍에를 더 무겁게 하겠고, 아버지는 채찍으로 다스렸으나 자기는 전갈로 다스리겠다고 말하라고 했다."},"say":{"who":"choeon","text":"이번에는 왕과 함께 자란 사람들에게 물었어. 대답이 노인들과 달라."}},{"ref":"왕상 12:12-15","open":"왕상 12:15","focus":"rehoboam","text":{"t1":"사흘 만에 백성이 다시 오자, 왕은 거친 말로 대답하고 백성의 말을 듣지 않았어요. 성경이 이 일을 두고 무엇이라고 말하는지는 15절에서 찾아봐요.","t2":"사흘 만에 백성이 여로보암과 함께 르호보암에게 다시 왔어요. 왕은 노인들의 말을 버리고 젊은 사람들이 일러 준 대로 거친 말로 대답했어요. 왕은 백성의 말을 듣지 않았어요. 성경이 이 일을 두고 왜 이렇게 되었다고 말하는지는 15절에서 찾아봐요.","t3":"왕이 정한 대로 사흘째 되는 날, 백성이 모두 여로보암과 함께 르호보암 앞에 나왔다. 왕은 노인들이 일러 준 것을 버리고 젊은 사람들의 말을 따라 백성에게 거칠게 대답했다. 아버지보다 멍에를 더 무겁게 하고, 채찍 대신 전갈로 다스리겠다고 했다. 왕은 이렇게 백성의 말을 듣지 않았다. 왕의 이 대답을 성경이 무엇이라고 적었는지는 15절을 직접 읽어 보자."},"say":{"who":"onwoo","text":"왕이 백성에게 거칠게 대답했어. 일지에 적어 둘게."}},{"ref":"왕상 12:16-20","focus":"israel","text":{"t1":"온 이스라엘은 왕이 말을 듣지 않자 장막으로 돌아갔고, 여로보암을 왕으로 세웠어요. 다윗의 집을 따른 지파가 어디인지는 성경에서 찾아봐요.","t2":"온 이스라엘은 왕이 자기들의 말을 듣지 않는 것을 보았어요. 그 뒤에 무슨 일이 어떤 차례로 일어났는지는 16절부터 20절까지 읽어 봐요. 다윗의 집을 따른 것은 유다 지파뿐이었어요.","t3":"온 이스라엘은 왕이 자기들의 말을 듣지 않는 것을 보고, 자기들은 다윗과 상관이 없고 이새의 아들에게서 받을 몫이 없다고 대답한 뒤 저마다 장막으로 돌아갔다. 유다의 여러 성읍에 살던 이스라엘 자손은 르호보암이 왕으로 다스렸다. 르호보암 왕이 일꾼들의 감독 아도니람을 보냈으나 온 이스라엘이 그를 돌로 쳐서 죽였고, 왕은 급히 수레에 올라 예루살렘으로 달아났다. 이렇게 이스라엘은 다윗의 집을 배반했다. 온 이스라엘은 여로보암이 돌아왔다는 말을 듣고 그를 모임으로 불러 온 이스라엘의 왕으로 세웠다. 유다 지파 말고는 다윗의 집을 따르는 사람이 없었다."},"say":{"who":"hyu","text":"온 이스라엘이 왕의 대답을 들었어. 일지에 적어 둘게."}},{"ref":"왕상 12:21-24","open":"왕상 12:24","focus":"shemaiah","text":{"t1":"르호보암은 용사들을 모아 이스라엘과 싸우려고 했어요. 하나님이 스마야를 통해 형제와 싸우지 말고 집으로 돌아가라고 하시자, 그들은 그 말씀대로 돌아갔어요.","t2":"르호보암은 예루살렘에 닿자 유다 온 족속과 베냐민 지파에서 용사 십팔만 명을 모았어요. 이스라엘과 싸워 나라를 되찾으려고 했어요. 그때 하나님의 사람 스마야에게 하나님의 말씀이 임했어요. 여호와께서는 올라가지 말고 형제 이스라엘 자손과 싸우지 말며 저마다 집으로 돌아가라고 하셨고, 그들은 그 말씀을 듣고 돌아갔어요.","t3":"르호보암은 예루살렘에 닿자 유다의 온 족속과 베냐민 지파에서 가려 뽑은 용사 십팔만 명을 모아, 이스라엘 족속과 맞서 싸워서 그 나라를 다시 자기 것으로 되찾으려고 했다. 그때 스마야라는 하나님의 사람에게 하나님의 말씀이 임하여, 유다 왕 르호보암에게, 또 유다와 베냐민의 온 족속과 그 밖의 백성에게 전하게 하셨다. 여호와께서는 올라가지 말고 형제인 이스라엘 자손과 맞서 싸우지 말며 저마다 집으로 돌아가라고 하셨다. 그들은 여호와의 말씀에 따라 저마다 돌아갔다."},"say":{"who":"onwoo","text":"하나님이 스마야를 통해 하신 말씀은 24절에 있어. 성경책에서 직접 읽어 보자."}}],"gates":{"t1":[{"type":"find","ref":"왕상 12:1","prompt":"성경책에서 열왕기상 12장 1절을 찾아 읽어 보세요.","confirm":{"prompt":"온 이스라엘이 르호보암을 왕으로 세우려고 모인 곳은 어디인가요?","options":[{"label":"세겜","ok":true},{"label":"헤브론","basis":"삼하 5:3"},{"label":"길갈","basis":"삼상 11:15"}]}},{"type":"multi","ref":"왕상 12:21","prompt":"성경책에서 열왕기상 12장 21절을 찾아 읽어 보세요.","confirm":{"prompt":"르호보암이 용사들을 모은 족속과 지파를 모두 고르세요.","options":[{"label":"레위 지파","basis":"본문에 없음"},{"label":"유다 온 족속","ok":true},{"label":"에브라임 지파","basis":"본문에 없음"},{"label":"베냐민 지파","ok":true}]}}],"t2":[{"type":"find","ref":"왕상 12:1-3","prompt":"성경책에서 열왕기상 12장 1절부터 3절까지 읽어 보세요.","confirm":{"prompt":"르호보암이 세겜으로 간 까닭은 무엇인가요?","options":[{"label":"온 이스라엘이 여호와께 절기를 지키려고 세겜에 모여 있었기 때문에","basis":"본문에 없음"},{"label":"애굽에서 돌아온 여로보암이 그를 세겜으로 불러냈기 때문에","basis":"본문에 없음"},{"label":"온 이스라엘이 그를 왕으로 세우려고 세겜에 와 있었기 때문에","ok":true}]}},{"type":"order","ref":"왕상 12:16-20","prompt":"성경책에서 열왕기상 12장 16절부터 20절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["온 이스라엘이 다윗과 상관이 없다며 저마다 장막으로 돌아갔다","르호보암 왕이 일꾼들의 감독 아도니람을 보냈다","르호보암 왕이 서둘러 수레를 타고 예루살렘으로 달아났다","이스라엘 사람들이 여로보암을 모임으로 불러 왕으로 세웠다"]}],"t3":[{"type":"find","refs":["왕상 12:4","왕상 12:7","왕상 12:14"],"prompt":"열왕기상 12장 4절, 7절, 14절을 함께 찾아 읽어 보자.","confirm":{"prompt":"세 곳을 이어 읽으면, 멍에를 두고 백성과 노인들과 왕은 저마다 무엇을 말했는가?","options":[{"label":"백성은 멍에를 가볍게 해 주면 해마다 예물을 더 바치겠다고 했고, 노인들은 왕이 백성을 섬기고 그들에게 좋게 말해 주면 백성이 언제까지나 왕의 종이 되리라고 했으나, 왕은 멍에를 더 무겁게 하겠다고 대답했다","basis":"본문에 없음"},{"label":"백성은 멍에를 가볍게 해 주면 왕을 섬기겠다고 했고, 노인들은 왕이 백성을 섬기고 그들에게 좋게 말해 주면 백성이 언제까지나 왕의 종이 되리라고 했으나, 왕은 멍에를 더 무겁게 하겠다고 대답했다","ok":true},{"label":"백성은 멍에를 가볍게 해 주면 왕을 섬기겠다고 했고, 노인들은 왕이 좋게 말해 주되 멍에는 그대로 두면 백성이 잠잠해지리라고 했으나, 왕은 멍에를 더 무겁게 하겠다고 대답했다","basis":"본문에 없음"}]}},{"type":"match","refs":["왕상 12:2","왕상 12:17","왕상 12:20"],"prompt":"열왕기상 12장 2절, 17절, 20절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"왕상 12:2","text":"여로보암은 솔로몬 왕을 피해 애굽에 가 있었다"},{"ref":"왕상 12:17","text":"르호보암은 유다의 여러 성읍에 사는 사람들의 왕이 되었다"},{"ref":"왕상 12:20","text":"이스라엘 사람들이 공회로 여로보암을 청해 왕으로 삼았다"}],"after":"세 곳을 이으면, 솔로몬을 피해 애굽에 가 있던 여로보암이 온 이스라엘의 왕이 되었고, 르호보암은 유다의 여러 성읍에 사는 사람들의 왕이 되었다."}]},"cards":[{"ref":"왕상 12:7","title":"백성을 섬기고 좋은 말로 대답하라"},{"ref":"왕상 12:24","title":"형제와 싸우지 말고 돌아가라"}],"close":{"t1":{"kind":"prayer","text":"하나님, 나라가 둘로 갈라진 이야기를 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 열왕기상 12장 1절부터 16절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"왕상 12:1-24에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"얘들아, 비상 착륙 때 계기판 덮개가 찢어졌어요. 덮개 대신 쓸 질긴 천 조각을 찾아 주세요. 백성 곁에서 함께 기다리고 길을 비켜 주는 것은 괜찮지만, 왕과 다른 사람들이 하는 일에는 끼지 말고 곁에서 봐요.","t2":"얘들아, 타임머신이 세겜 가까이에 비상 착륙했어요. 계기판을 덮는 덮개가 찢어져서 먼지가 들어가요. 그 시대에는 우리 부속이 없으니, 질긴 천 조각을 구해서 덮개 대신 쓰면 돼요. 백성 곁에서 함께 기다리고 길을 비켜 주는 것은 괜찮지만, 왕과 다른 사람들이 하는 일에는 끼지 말고 곁에서 보기만 해요.","t3":"타임머신이 세겜 가까이에 비상 착륙했다. 계기판 덮개가 찢어졌으니 덮개 대신 쓸 질긴 천 조각이 필요하다. 사람들의 물건에는 손대지 말고, 길에 떨어진 것만 주워 오기 바란다. 백성 곁에서 함께 기다리고 길을 비켜 주는 것은 괜찮지만, 왕과 다른 사람들이 하는 일에는 끼지 않고 곁에서 보기만 하자."},"materials":[{"key":"tentcloth","name":"장막 천 조각","basis":"왕상 12:16","line":"사람들이 다 떠난 길가에서 해진 장막 천 조각을 찾았어!","use":"질긴 장막 천 조각을 찢어진 계기판 덮개 대신 쓸 수 있어요.","how":"온 이스라엘이 저마다 장막으로 돌아간 뒤, 사람들이 다 떠난 길가에 떨어져 있는 해진 장막 천 조각을 줍는다. 사람들의 장막과 물건에는 손대지 않는다."}],"companion":{"who":"스마야","ref":"왕상 12:22","when":"after","talks":[{"ask":{"who":"onwoo","text":"스마야 님, 하나님은 르호보암 왕이 모은 용사들에게 싸우러 올라가라고 하셨어요?"},"answer":{"t1":"스마야는 여호와께서 올라가지 말라고 말씀하셨다고 전했어요. 형제인 이스라엘 자손과 맞서 싸우지 말라고 하셨다고 했어요.","t2":"스마야는 여호와께서 유다와 베냐민 사람들에게 올라가지 말라고 하셨다고 전했어요. 그들의 형제인 이스라엘 자손과 맞서 싸우지 말라고 말씀하셨다고 했어요.","t3":"스마야는 여호와께서 올라가지 말고, 그들의 형제인 이스라엘 자손과 맞서 싸우지 말라고 말씀하셨다고 전했다."},"ref":"왕상 12:24","open":"왕상 12:24"},{"ask":{"who":"hyu","text":"스마야 님, 그러면 용사들은 어떻게 하라고 하셨어요?"},"answer":{"t1":"스마야는 여호와께서 저마다 집으로 돌아가라고 말씀하셨다고 전했어요.","t2":"스마야는 여호와의 말씀을 전했어요. 여호와께서 저마다 자기 집으로 돌아가라고 하셨다고 했어요.","t3":"스마야는 여호와께서 저마다 자기 집으로 돌아가라고 말씀하셨다고 전했다."},"ref":"왕상 12:24","open":"왕상 12:24"}]},"today":[{"q":"말을 거칠게 하면 어떻게 될까요?","a":{"t1":"르호보암 왕은 백성에게 거친 말로 대답했어요. 온 이스라엘은 왕이 자기들의 말을 듣지 않는 것을 보고 떠나갔어요. 잠언은 부드러운 대답은 분노를 가라앉히고 거친 말은 노여움을 일으킨다고 말해요.","t2":"노인들은 르호보암에게 백성을 섬기고 좋은 말로 대답하라고 일러 주었어요. 그러나 왕은 그 말을 버리고 거친 말로 대답했고, 온 이스라엘은 왕이 자기들의 말을 듣지 않는 것을 보고 장막으로 돌아갔어요. 잠언은 부드러운 대답은 분노를 가라앉히지만 거친 말은 노여움을 일으킨다고 말해요.","t3":"노인들은 왕이 백성을 섬기고 좋은 말로 대답하면 백성이 영원히 왕의 종이 될 것이라고 일러 주었다. 그러나 르호보암은 그 말을 버리고 거칠게 대답했고, 온 이스라엘은 왕이 자기들의 말을 듣지 않는 것을 보고 장막으로 돌아갔다. 잠언은 부드러운 대답은 분노를 가라앉히지만 거친 말은 노여움을 일으킨다고 말한다. 성경은 여기까지 말한다."},"refs":["왕상 12:7","왕상 12:13-16","잠 15:1"]}],"help":{"who":"세겜에 모인 이스라엘 백성","steps":[{"kind":"do","after":1,"title":"물러가는 백성에게 길 비켜 주기","basis":"왕상 12:5","text":{"t1":"르호보암이 사흘 뒤에 다시 오라고 하자 백성이 물러갔어요. 우리는 물러가는 사람들 곁에서 길을 비켜 주며 도왔어요.","t2":"르호보암이 갔다가 사흘 뒤에 다시 오라고 하자, 백성은 물러갔어요. 우리는 왕의 일에는 끼지 않고, 물러가는 사람들 곁에서 길을 비켜 주었어요. 성경에 적힌 일이 아니라 탐험대가 한 일이에요.","t3":"르호보암이 사흘 뒤에 다시 오라고 하자 백성은 물러갔다(12:5). 탐험대는 왕의 일에는 끼지 않고, 물러가는 사람들 곁에서 길을 비켜 준다. 성경에 적힌 일이 아니라 탐험대 이야기다."},"tasks":["길 가장자리로 비켜서기","물러가는 사람들이 먼저 지나가게 기다리기","길에 둔 우리 짐 치우기"],"done":{"who":"onwoo","text":"길을 비켜 줬어. 이제 우리도 사흘 뒤를 기다리자."}},{"kind":"stay","after":1,"title":"사흘 뒤를 함께 기다리기","basis":"왕상 12:5","text":{"t1":"르호보암은 백성에게 갔다가 사흘 뒤에 다시 오라고 했어요. 백성은 물러갔고, 우리도 백성과 함께 기다려요.","t2":"르호보암은 백성에게 갔다가 사흘 뒤에 다시 오라고 대답했고, 백성은 물러갔어요. 우리는 왕의 일에 끼어들지 않고, 백성과 함께 사흘 뒤를 기다려요.","t3":"르호보암은 갔다가 사흘 뒤에 다시 오라고 대답했고, 백성은 물러갔다(12:5). 탐험대는 왕의 일에 끼어들지 않고, 백성과 함께 사흘 뒤를 기다린다."},"wait":"백성과 함께 기다리기","say":{"who":"hyu","text":"사흘 뒤에 다시 오래. 날짜를 적어 둘게."}},{"kind":"watch","after":6,"title":"곁에서 보기 · 하나님의 사람 스마야","basis":"왕상 12:22-24","text":{"t1":"하나님의 말씀이 스마야에게 임했어요. 사람들은 그 말씀을 듣고 저마다 돌아갔어요. 하나님이 스마야에게 맡기신 일이라서 우리는 곁에서 봐요.","t2":"하나님은 스마야에게 말씀하셔서, 르호보암과 유다와 베냐민 사람들에게 전하게 하셨어요. 사람들은 여호와의 말씀을 듣고 그대로 돌아갔어요. 하나님이 스마야에게 맡기신 일이라서, 우리는 끼어들지 않고 곁에서 봐요.","t3":"하나님은 하나님의 사람 스마야에게 말씀하셔서, 르호보암과 유다와 베냐민 사람들과 그 밖의 백성에게 전하게 하셨다(12:22-23). 여호와의 말씀을 들은 그들은 말씀대로 돌아갔다(12:24). 하나님이 스마야에게 맡기신 일이므로, 탐험대는 끼어들지 않고 곁에서 본다."},"say":{"who":"choeon","text":"사람들이 싸우러 가지 않고 집으로 돌아가고 있어."}},{"kind":"ask","after":"gates","title":"나라가 둘로 갈라진 일은 무슨 뜻이에요?","basis":"왕상 12:24","by":"스마야","ask":{"who":"choeon","text":"스마야 님, 나라가 둘로 갈라진 일은 무슨 뜻이에요?"},"answer":{"t1":"스마야는 여호와께서 이 일이 여호와께로부터 난 것이라고 말씀하셨다고 전했어요.","t2":"스마야는 여호와께서 유다와 베냐민 사람들에게 형제와 싸우지 말라고 하셨다고 전했어요. 그러면서 이 일이 여호와께로부터 난 것이라고 말씀하셨다고 했어요.","t3":"스마야는 여호와께서 형제인 이스라엘 자손과 맞서 싸우지 말라고 하시며, 이 일이 여호와 자신에게서 난 것이라고 말씀하셨다고 전했다."},"read":{"t1":{"type":"find","ref":"왕상 12:24","prompt":"성경책에서 열왕기상 12장 24절을 찾아 읽어 보세요.","confirm":{"prompt":"스마야가 전한 말씀에서, 이 일은 누구에게서 난 것이라고 했나요?","options":[{"label":"르호보암 왕의 꾀에서","basis":"본문에 없음"},{"label":"여호와께로부터","ok":true},{"label":"여로보암의 군대에서","basis":"본문에 없음"}]},"inStory":"여호와는 장면 곳곳에 나오는 이름일 뿐이다. 이 일이 여호와께로부터 났다는 말은 8~10세 글에서는 15절과 24절을 읽어야 안다(뜻 묻기의 설명은 이 물음 뒤에 나온다)"},"t2":{"type":"find","ref":"왕상 12:13-15","prompt":"성경책에서 열왕기상 12장 13절부터 15절까지 읽어 보세요.","confirm":{"prompt":"왕이 백성의 말을 듣지 않은 이 일을 두고, 성경은 왜 이렇게 되었다고 말하나요?","options":[{"label":"백성이 미리 꾸민 일이며, 여로보암이 애굽에 있을 때부터 백성과 몰래 짠 꾀를 이루려는 것이라고","basis":"본문에 없음"},{"label":"여호와께로 말미암은 일이며, 여호와께서 전에 아히야를 통해 여로보암에게 하신 말씀을 이루시려는 것이라고","ok":true},{"label":"여호와께로 말미암은 일이며, 여호와께서 전에 스마야를 통해 르호보암에게 하신 말씀을 이루시려는 것이라고","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["왕상 12:15","왕상 12:24"],"prompt":"열왕기상 12장 15절과 24절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳에 같이 나오는 말은 무엇이고, 각각 어떤 자리에서 나온 말인가?","options":[{"label":"이 일이 여호와께로 말미암아 났다는 말이다. 15절에서는 성경이 왕이 백성의 말을 듣지 않은 일을 두고 그렇게 적고, 24절에서는 여호와께서 스마야를 통해 싸우지 말라고 하시며 그렇게 말씀하셨다","ok":true},{"label":"이 일이 르호보암의 꾀로 났다는 말이다. 15절에서는 성경이 왕이 젊은 사람들의 말을 따른 일을 두고 그렇게 적고, 24절에서는 스마야가 왕에게 집으로 돌아가라고 하며 그렇게 말했다","basis":"본문에 없음"},{"label":"이 일이 여호와께로 말미암아 났다는 말이다. 15절에서는 아히야가 여로보암에게 그렇게 말하고, 24절에서는 스마야가 르호보암이 수레를 타고 예루살렘으로 달아난 일을 두고 그렇게 말했다","basis":"본문에 없음"}]}}}}]}},"has3d":false,"epic":false},"OT-30":{"id":"OT-30","era":8,"title":"갈멜 산의 엘리야","ref":"왕상 18:20-39","place":"갈멜 산","review":{"required":false,"topics":[],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"왕상 18:20-21","focus":"people","text":{"t1":"아합 왕이 선지자들을 갈멜 산에 모았고, 엘리야는 백성에게 언제까지 둘 사이에서 머뭇거리겠느냐고 물었어요. 백성이 어떻게 했는지는 성경에서 찾아봐요.","t2":"아합이 이스라엘 모든 자손에게 사람을 보내어 선지자들을 갈멜 산으로 모았어요. 엘리야는 백성에게 가까이 가서 언제까지 둘 사이에서 머뭇거리겠느냐고 물었어요. 누구를 따르라고 했는지, 그 까닭은 무엇이었는지는 21절에서 찾아봐요. 백성은 한 마디도 대답하지 않았어요.","t3":"아합이 이스라엘 모든 자손에게 사람을 보내어 선지자들을 갈멜 산으로 모았다. 엘리야는 모든 백성 앞으로 가까이 가서, 언제까지 둘 사이에서 머뭇거리겠느냐고 물었다. 여호와가 하나님이면 그분을 따르고 바알이 하나님이면 그를 따르라고 했다. 백성은 한 마디도 대답하지 않았다."},"say":{"who":"hyu","text":"여기는 갈멜 산이야. 아합 왕이 선지자들을 이 산으로 모았어. 적어 둘게."}},{"ref":"왕상 18:22-24","focus":"elijah","text":{"t1":"엘리야는 여호와의 선지자는 자기 혼자 남았다고 하면서, 바알 쪽 선지자의 수도 말했어요. 불로 응답하는 신이 하나님이라고 하자, 백성은 그 말이 옳다고 했어요.","t2":"엘리야는 여호와의 선지자는 자기만 남았고 바알의 선지자는 사백오십 명이라고 했어요. 송아지 두 마리를 가져와 한 마리씩 나무 위에 놓되 불은 붙이지 말자고 했어요. 저마다 자기 신의 이름을 불러서, 불로 응답하는 신이 하나님이라고 했어요. 백성은 모두 그 말이 옳다고 대답했어요.","t3":"엘리야는 백성에게, 여호와의 선지자는 자기 혼자 남았으나 바알의 선지자는 사백오십 명이라고 했다. 송아지 두 마리를 가져오게 하여, 그들이 한 마리를 골라 각을 떠서 나무 위에 놓되 불은 붙이지 말고, 자기도 한 마리를 잡아 나무 위에 놓고 불은 붙이지 않겠다고 했다. 그들은 자기들의 신의 이름을 부르고 자기는 여호와의 이름을 부를 것이니, 불로 응답하는 신이 하나님이라고 했다. 백성이 모두 그 말이 옳다고 대답했다."},"say":{"who":"choeon","text":"송아지는 두 마리야. 나무 위에 놓고 불은 붙이지 않기로 했어."}},{"ref":"왕상 18:25-29","focus":"baalprophets","text":{"t1":"바알의 선지자들이 먼저 아침부터 바알의 이름을 불렀어요. 그러나 저녁 소제 드릴 때가 되도록 아무 대답이 없었어요.","t2":"엘리야는 바알의 선지자들에게 먼저 하라고 했어요. 그 뒤에 무슨 일이 어떤 차례로 있었는지는 25절부터 29절까지 읽어 봐요. 저녁 소제 드릴 때가 되어도 아무 대답이 없었어요.","t3":"엘리야는 바알의 선지자들에게, 수가 많으니 먼저 송아지 한 마리를 골라 잡고 그들의 신의 이름을 부르되 불은 붙이지 말라고 했다. 그들은 받은 송아지를 잡아 놓고 바알을 불렀고, 자기들이 쌓은 단 둘레에서 뛰었다. 언제부터 언제까지 불렀고 그동안 무엇이 돌아왔는지는 26절과 29절에서 직접 읽어 보자."},"say":{"who":"choeon","text":"바알을 부르는데 아무 소리도 안 들려."}},{"ref":"왕상 18:30-32","focus":"altar","text":{"t1":"엘리야는 백성을 가까이 오게 하고, 무너진 여호와의 단을 돌로 다시 쌓고 그 둘레에 도랑을 만들었어요. 돌을 몇 개 가져왔는지는 성경에서 찾아봐요.","t2":"엘리야가 백성에게 가까이 오라고 하자 백성이 다 가까이 왔어요. 엘리야는 무너져 있던 여호와의 단을 돌 열두 개로 고쳐 쌓고, 단 둘레에 도랑을 만들었어요. 왜 열두 개였는지는 31절에서 찾아봐요.","t3":"엘리야가 모든 백성에게 가까이 오라고 하자 백성이 다 그에게 가까이 왔다. 그는 무너져 있던 여호와의 단을 고쳐 쌓았다. 엘리야는 여호와의 이름으로 돌들을 쌓아 단을 만들고, 단 둘레에 도랑을 만들었다. 돌을 무엇의 수대로 가져왔고 도랑이 얼마나 컸는지는 31절과 32절에서 직접 읽어 보자."},"say":{"who":"hyu","text":"단 둘레에 도랑을 만들었어. 일지에 그려 둘게."}},{"ref":"왕상 18:33-35","focus":"water","text":{"t1":"엘리야는 나무 위에 송아지를 올리고, 통 네 개의 물을 그 위에 세 번이나 붓게 했어요. 도랑에도 물이 가득 찼어요.","t2":"엘리야는 나무를 벌여 놓고 송아지를 잡아 그 위에 올렸어요. 그리고 통 네 개에 물을 채워 번제물과 나무 위에 부으라고 했어요. 두 번째도, 세 번째도 그렇게 하게 했어요. 물이 단 둘레로 흘렀고 도랑에도 물이 가득 찼어요.","t3":"그는 나무를 벌여 놓고 송아지를 각을 떠서 그 위에 올린 뒤, 통 넷에 물을 채워 와서 번제물과 나무 위에 부으라고 했다. 다시 그렇게 하라고 하여 두 번째로 부었고, 세 번째로 하라고 하여 세 번째로 부었다. 물이 단 둘레로 흘렀고 도랑에도 물이 가득 찼다."},"say":{"who":"choeon","text":"물을 세 번이나 부었어! 도랑까지 물이 가득 찼어."}},{"ref":"왕상 18:36-37","open":"왕상 18:36","focus":"elijah","text":{"t1":"저녁 소제 드릴 때에 엘리야가 나아가 여호와께 기도했어요. 무엇을 구했는지는 성경에서 찾아봐요.","t2":"저녁 소제 드릴 때에 선지자 엘리야가 나아가서 기도했어요. 엘리야는 여호와께 응답해 달라고 거듭 구했는데, 왜 그렇게 구했는지는 36절과 37절에서 직접 읽어 봐요.","t3":"저녁 소제 드릴 때가 되자 엘리야가 앞으로 나아가 기도했다. 엘리야가 여호와를 누구의 하나님이라 부르며 무엇을 알게 해 달라고 구했는지는 36절과 37절에서 직접 읽어 보자."},"say":{"who":"onwoo","text":"엘리야가 앞으로 나아가 기도하고 있어."}},{"ref":"왕상 18:38-39","focus":"fire","text":{"t1":"여호와의 불이 내려 번제물과 나무, 돌과 흙까지 태웠어요. 도랑의 물이 어떻게 되었고, 그것을 본 백성이 엎드려 무엇이라고 말했는지는 성경에서 찾아봐요.","t2":"여호와의 불이 내려왔어요. 불은 번제물과 나무, 돌과 흙을 태웠고 도랑에 있던 물까지 핥아 없앴어요. 모든 백성이 그것을 보고 엎드렸어요. 여호와 그분이 하나님이시라고 거듭 말했어요.","t3":"그러자 여호와의 불이 내려 번제물과 나무와 돌과 흙을 태웠고, 도랑에 있던 물까지 핥았다. 모든 백성이 이를 보고 엎드렸는데, 그때 무엇이라고 말했는지는 39절에서 직접 읽어 보자."},"say":{"who":"choeon","text":"불이 내려왔어! 돌이랑 흙까지 탔어!"}}],"gates":{"t1":[{"type":"find","ref":"왕상 18:22","prompt":"성경책에서 열왕기상 18장 22절을 찾아 읽어 보세요.","confirm":{"prompt":"엘리야는 바알의 선지자가 몇 명이라고 했나요?","options":[{"label":"사백 명","basis":"왕상 18:19"},{"label":"사백오십 명","ok":true},{"label":"칠천 명","basis":"왕상 19:18"}]}},{"type":"multi","ref":"왕상 18:36","prompt":"성경책에서 열왕기상 18장 36절을 찾아 읽어 보세요.","confirm":{"prompt":"엘리야는 기도하며 여호와를 누구의 하나님이라고 불렀나요? 모두 고르세요.","options":[{"label":"아브라함","ok":true},{"label":"모세","basis":"본문에 없음"},{"label":"이삭","ok":true},{"label":"다윗","basis":"본문에 없음"},{"label":"이스라엘(야곱의 다른 이름)","ok":true}]}}],"t2":[{"type":"find","ref":"왕상 18:20-21","prompt":"성경책에서 열왕기상 18장 20절과 21절을 읽어 보세요.","confirm":{"prompt":"엘리야는 백성에게 누구를 따르라고 했고, 그 까닭을 무엇이라고 했나요?","options":[{"label":"아합 왕을 따르라고 했어요. 왕이 선지자들을 불러 모았으니 왕의 말을 들어야 한다고 했어요","basis":"본문에 없음"},{"label":"자기를 따르라고 했어요. 여호와의 선지자는 자기 혼자 남았으니 자기를 따라야 한다고 했어요","basis":"본문에 없음"},{"label":"하나님이신 쪽을 따르라고 했어요. 여호와가 하나님이면 여호와를 따라야 한다고 했어요","ok":true}]}},{"type":"order","ref":"왕상 18:25-29","prompt":"성경책에서 열왕기상 18장 25절부터 29절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["엘리야가 바알 쪽 선지자들에게 먼저 송아지를 고르라고 했다","바알의 선지자들이 바알을 부르며 자기들이 쌓은 단 둘레에서 뛰놀았다","엘리야가 더 크게 불러 보라며 그들을 조롱했다","그들이 저녁 소제 드릴 때까지 불러도 아무 응답이 없었다"]}],"t3":[{"type":"find","refs":["왕상 18:26","왕상 18:29"],"prompt":"열왕기상 18장 26절과 29절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 바알의 선지자들이 부른 동안 무슨 일이 있었는가?","options":[{"label":"아침부터 낮까지만 바알을 불렀어도 소리도 응답도 없었고, 정오가 되자 엘리야가 그들을 멈추게 하고 자기 단을 쌓기 시작했다","basis":"본문에 없음"},{"label":"아침부터 낮까지 바알을 불렀어도 소리도 응답도 없었고, 정오가 지나 저녁 소제 드릴 때까지 불러도 소리도, 응답하는 이도, 돌아보는 이도 없었다","ok":true},{"label":"아침부터 낮까지 바알을 불렀어도 소리도 응답도 없었고, 정오가 지나자 그들은 지쳐서 부르기를 그치고 저마다 산을 내려갔다","basis":"본문에 없음"}]}},{"type":"match","refs":["왕상 18:21","왕상 18:23","왕상 18:24"],"prompt":"열왕기상 18장 21절, 23절, 24절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"왕상 18:21","text":"엘리야의 물음에 백성은 한 마디도 대답하지 않았다"},{"ref":"왕상 18:23","text":"엘리야는 송아지를 나무 위에 놓되 불은 붙이지 말자고 했다"},{"ref":"왕상 18:24","text":"백성이 모두 그 말이 옳다고 대답했다"}],"after":"세 곳을 이으면, 처음에는 한 마디도 대답하지 않던 백성이, 송아지를 나무 위에 두되 불은 붙이지 말고 저마다 신의 이름을 부르자는 엘리야의 말에는 모두 옳다고 대답했다."}]},"cards":[{"ref":"왕상 18:21","title":"어느 때까지 머뭇거리려느냐"},{"ref":"왕상 18:39","title":"여호와 그는 하나님이시로다"}],"close":{"t1":{"kind":"prayer","text":"하나님, 갈멜 산에서 일어난 일을 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 열왕기상 18장 30절부터 39절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"왕상 18:20-39에서 새로 알게 된 사실을 한 가지 적어 보자."}},"quests":[{"part":"gear","name":"톱니바퀴","line":"톱니바퀴를 찾았어! 모여 선 사람들 뒤쪽 땅에 떨어져 있었네.","found":"탐지기가 백성이 모여 선 쪽을 가리켜요.","say":{"who":"hyu","text":"탐지기 바늘이 사람들이 모인 쪽으로 돌아갔어. 뒤쪽에서만 찾자. 일지에 적어 둘게."},"q":{"t1":{"type":"find","ref":"왕상 18:21","prompt":"성경책에서 열왕기상 18장 21절을 찾아 읽어 보세요.","confirm":{"prompt":"엘리야가 언제까지 머뭇거리겠느냐고 물었을 때 백성은 어떻게 했나요?","options":[{"label":"한 마디도 대답하지 않았어요","ok":true},{"label":"모두 산에서 내려갔어요","basis":"본문에 없음"},{"label":"큰 소리로 노래했어요","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"왕상 18:19-20","prompt":"성경책에서 열왕기상 18장 19절과 20절을 읽어 보세요.","confirm":{"prompt":"아합이 이스라엘 자손에게 사람을 보내 선지자들을 갈멜 산에 모은 까닭은 무엇인가요?","options":[{"label":"이세벨이 바알과 아세라의 선지자들을 갈멜 산에 모아 잔치를 열자고 했기 때문에","basis":"본문에 없음"},{"label":"엘리야가 온 이스라엘과 바알과 아세라의 선지자들을 갈멜 산에 모아 달라고 했기 때문에","ok":true},{"label":"백성이 비를 내려 달라고 빌려고 선지자들을 갈멜 산에 모아 달라고 했기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["왕상 18:19","왕상 18:22"],"prompt":"열왕기상 18장 19절과 22절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 엘리야는 어떤 선지자들을 모아 달라고 했고, 갈멜 산에서 무엇이라고 말했는가?","options":[{"label":"사백오십 명의 바알 선지자만 모아 달라고 했고, 갈멜 산에서는 여호와의 선지자로는 자기만 남았는데 바알의 선지자들은 사백오십 명이라고 했다","basis":"본문에 없음"},{"label":"여호와의 선지자 백 명을 모아 달라고 했고, 갈멜 산에서는 여호와의 선지자로는 자기만 남았는데 바알의 선지자들은 사백오십 명이라고 했다","basis":"본문에 없음"},{"label":"바알의 선지자 사백오십 명과 아세라의 선지자 사백 명을 모아 달라고 했고, 갈멜 산에서는 여호와의 선지자로는 자기만 남았는데 바알의 선지자들은 사백오십 명이라고 했다","ok":true}]}}}},{"part":"needle","name":"나침반 바늘","line":"나침반 바늘이 여기 있었네! 단에서 멀찍이 떨어진 산비탈이야.","found":"탐지기가 무너진 단이 멀리 보이는 쪽을 가리켜요.","say":{"who":"choeon","text":"저기 돌이 흩어진 자리가 보여. 우리는 가까이 가지 말자."},"q":{"t1":{"type":"find","ref":"왕상 18:31","prompt":"성경책에서 열왕기상 18장 31절을 찾아 읽어 보세요.","confirm":{"prompt":"엘리야는 돌을 몇 개 가져왔나요?","options":[{"label":"다섯 개","basis":"삼상 17:40"},{"label":"열두 개","ok":true},{"label":"일곱 개","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"왕상 18:25-27","prompt":"성경책에서 열왕기상 18장 25절부터 27절까지 읽어 보세요.","confirm":{"prompt":"엘리야는 바알 쪽 선지자들을 조롱하며 더 큰 소리로 부르라고 했어요. 그때 엘리야는 무엇을 까닭으로 댔나요?","options":[{"label":"바알이 생각에 잠겼거나, 잠깐 나갔거나, 길을 떠났거나, 잠이 들어 깨워야 할지도 모른다고 하며","ok":true},{"label":"바알의 단이 너무 작아서, 바알이 그 단을 찾지 못하고 있을지도 모른다고 하며","basis":"본문에 없음"},{"label":"바알이 송아지가 마음에 들지 않아서, 다른 송아지를 다시 골라 와야 할지도 모른다고 하며","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["왕상 18:31","왕상 18:36"],"prompt":"열왕기상 18장 31절과 36절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳에 같이 나오는 '이스라엘'이라는 이름은 누구의 이름인가?","options":[{"label":"엘리야의 다른 이름이다. 엘리야는 여호와께서 자기에게 이스라엘이라는 이름을 주셨다며 돌을 가져왔고, 기도할 때 자기를 이스라엘이라 부르며 여호와께 아뢰었다","basis":"본문에 없음"},{"label":"야곱의 이름이다. 엘리야는 여호와께서 이스라엘이라 부르겠다고 하신 야곱의 아들들에게서 나온 지파의 수대로 돌을 가져왔고, 기도할 때 여호와를 아브라함, 이삭, 이스라엘의 하나님이라 불렀다","ok":true},{"label":"이스라엘 백성 전체의 이름이다. 엘리야는 이스라엘 열두 지파가 저마다 하나씩 가져온 돌로 단을 쌓았고, 기도할 때 여호와를 아브라함과 이삭과 그 백성 이스라엘의 하나님이라 불렀다","basis":"본문에 없음"}]}}}},{"part":"screw","name":"나사","line":"나사를 찾았어! 사람들 뒤쪽 산비탈에 굴러가 있었어.","found":"탐지기가 단 자리가 멀리 보이는 산비탈을 가리켜요.","say":{"who":"onwoo","text":"여기까지만 가자. 단 가까이로는 가지 말자. 우리는 지켜보는 사람이야."},"q":{"t1":{"type":"find","ref":"왕상 18:38","prompt":"성경책에서 열왕기상 18장 38절을 찾아 읽어 보세요.","confirm":{"prompt":"여호와의 불이 내린 뒤, 도랑에 있던 물은 어떻게 되었나요?","options":[{"label":"물이 단 둘레로 흘러 도랑에 가득했어요","basis":"왕상 18:35"},{"label":"불이 물까지 핥아 없앴어요","ok":true},{"label":"물이 얼음처럼 얼었어요","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"왕상 18:30-32","prompt":"성경책에서 열왕기상 18장 30절부터 32절까지 읽어 보세요.","confirm":{"prompt":"엘리야가 가져온 돌이 열두 개였던 까닭은 무엇인가요?","options":[{"label":"야곱의 아들들에게서 나온 지파의 수대로 가져왔기 때문에","ok":true},{"label":"바알의 선지자들이 쌓은 단의 돌 수와 맞추려고","basis":"본문에 없음"},{"label":"백성이 저마다 하나씩 가져온 돌이 열두 개였기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["왕상 18:32","왕상 18:38"],"prompt":"열왕기상 18장 32절과 38절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 엘리야가 단 둘레에 만든 도랑은 얼마나 컸고, 마지막에 그 도랑은 어떻게 되었는가?","options":[{"label":"곡식 종자 열 세아가 들어갈 만한 도랑이었는데, 여호와의 불이 내려 도랑의 물까지 핥았다","basis":"본문에 없음"},{"label":"물 한 통이 겨우 들어갈 만한 작은 도랑이었는데, 여호와의 불이 내려 도랑의 물까지 핥았다","basis":"본문에 없음"},{"label":"곡식 종자 두 세아가 들어갈 만한 도랑이었는데, 여호와의 불이 내려 도랑의 물까지 핥았다","ok":true}]}}}}],"mission":{"call":{"t1":"얘들아, 갈멜 산에 내렸는데 톱니바퀴와 나침반 바늘과 나사가 빠져 버렸어요. 산에서 대신 쓸 것을 찾아 주세요. 백성 곁에서 함께 기다리고 길을 비켜 주는 것은 괜찮지만, 단과 제물과 거기 쓰이는 물건에는 손대지 말고 곁에서 보기만 해요.","t2":"얘들아, 타임머신이 갈멜 산에 비상 착륙했어요. 톱니바퀴, 나침반 바늘, 나사가 떨어져 나갔어요. 그 시대에는 우리 부속이 없으니, 산에 굴러다니는 돌과 흙으로 대신 만들어 봐요. 백성 곁에서 함께 기다리고 길을 비켜 주는 것은 괜찮지만, 사람들의 물건과 단과 제물에는 손대지 말고 곁에서 보기만 해요.","t3":"타임머신이 갈멜 산에 비상 착륙했다. 톱니바퀴와 나침반 바늘과 나사가 떨어져 나갔으니, 산에서 구할 수 있는 돌과 흙으로 대신 만들어야 한다. 사람들과 그 물건, 단에는 손대지 말고, 단에서 멀리 떨어진 땅에 굴러 있는 것만 줍기 바란다. 백성 곁에서 함께 기다리고 길을 비켜 주는 것은 괜찮지만, 단을 쌓고 제물을 올리고 물을 붓는 일은 곁에서 보기만 한다."},"materials":[{"key":"flatstone","name":"납작한 돌","basis":"왕상 18:20","line":"사람들이 모여 선 뒤쪽 땅에서 납작하고 둥근 돌을 찾았어!","use":"납작하고 둥근 돌을 톱니바퀴 대신 쓸 수 있어요.","how":"백성이 모여 선 곳의 뒤쪽 땅에 굴러 있는 납작한 돌을 줍는다. 단에서 멀리 떨어진 곳이고, 단을 쌓은 돌에는 손대지 않는다."},{"key":"stoneneedle","name":"가늘고 긴 돌 조각","basis":"왕상 18:20","line":"단 자리가 멀리 보이는 산비탈에서 가늘고 긴 돌 조각을 주웠어!","use":"가늘고 긴 돌 조각을 나침반 바늘 대신 쓸 수 있어요.","how":"무너진 단이 멀리 보이기만 하는 산비탈에 떨어져 있는 가늘고 긴 돌 조각을 줍는다. 단 자리 가까이로는 가지 않는다."},{"key":"soil","name":"고운 흙","basis":"왕상 18:20","line":"단 자리가 멀리 보이는 산비탈에서 고운 흙을 한 줌 담았어!","use":"고운 흙을 나사 구멍에 꼭꼭 눌러 채우면 나사 대신 쓸 수 있어요.","how":"단 자리에서 멀리 떨어진 산비탈에서 마른 흙을 한 줌 떠 담는다. 단 둘레의 흙에는 손대지 않는다."}],"companion":{"who":"엘리야","ref":"왕상 18:21","when":"after","talks":[{"ask":{"who":"choeon","text":"엘리야 님, 처음에 백성에게 뭐라고 물으셨어요?"},"answer":{"t1":"엘리야는 백성에게 언제까지 둘 사이에서 머뭇거리겠느냐고 물었어요. 여호와가 하나님이면 여호와를, 바알이 하나님이면 바알을 따르라고 했어요.","t2":"엘리야는 모든 백성에게 언제까지 둘 사이에서 머뭇거리겠느냐고 물었어요. 여호와가 하나님이면 여호와를 따르고, 바알이 하나님이면 바알을 따르라고 했어요.","t3":"엘리야는 모든 백성에게, 언제까지 둘 사이에서 머뭇거리겠느냐고 물었다. 여호와가 하나님이면 그분을 따르고, 바알이 하나님이면 바알을 따르라고 했다."},"ref":"왕상 18:21","open":"왕상 18:21"},{"ask":{"who":"hyu","text":"누가 하나님인지 어떻게 알 수 있다고 하셨어요?"},"answer":{"t1":"엘리야는 저마다 자기 신의 이름을 부르자고 했어요. 그리고 불로 응답하는 신이 하나님이라고 했어요.","t2":"엘리야는 송아지를 나무 위에 놓되 불은 붙이지 말자고 했어요. 바알의 선지자들은 자기들의 신의 이름을 부르고 자기는 여호와의 이름을 부를 테니, 불로 응답하는 신이 하나님이라고 했어요.","t3":"엘리야는 송아지 두 마리를 가져오게 하여 저마다 한 마리씩 나무 위에 놓되 불은 붙이지 말자고 했다. 그들은 자기들의 신의 이름을 부르고 자기는 여호와의 이름을 부를 것이니, 불로 응답하는 신이 하나님이라고 했다."},"ref":"왕상 18:23-24","open":"왕상 18:24"}]},"today":[{"q":"누구를 따를지 망설이는 사람에게 성경은 뭐라고 해요?","a":{"t1":"엘리야는 백성에게 언제까지 둘 사이에서 머뭇거리겠느냐고 물었어요. 여호와가 하나님이면 여호와를 따르라고 했어요. 여호수아도 백성에게 섬길 이를 오늘 택하라고 했어요.","t2":"엘리야는 백성에게 언제까지 둘 사이에서 머뭇거리겠느냐고 물으며, 여호와가 하나님이면 여호와를 따르라고 했어요. 백성은 처음에 대답하지 않았지만, 여호와의 불이 내린 것을 보고 여호와 그분이 하나님이시라고 말했어요. 여호수아도 전에 백성에게 섬길 이를 오늘 택하라고 하며, 자기와 자기 집은 여호와를 섬기겠다고 했어요.","t3":"엘리야는 백성에게 언제까지 둘 사이에서 머뭇거리겠느냐고 물으며, 여호와가 하나님이면 그분을 따르라고 했다. 백성은 한 마디도 대답하지 않았으나, 여호와의 불이 내린 것을 보고 엎드려 여호와 그분이 하나님이시라고 말했다. 여호수아도 전에 백성에게 섬길 이를 오늘 택하라고 하며, 자기와 자기 집은 여호와를 섬기겠다고 했다. 성경은 여기까지 말한다."},"refs":["왕상 18:21","왕상 18:39","수 24:15"]},{"q":"엘리야는 왜 번제물과 나무 위에 물을 붓게 했어요?","a":{"t1":"성경은 그 까닭을 말하지 않아요. 엘리야가 물을 세 번 붓게 했다고만 적어요. 엘리야는 기도할 때, 자기가 주의 말씀대로 이 모든 일을 했다는 것을 알게 해 달라고 구했어요.","t2":"성경은 엘리야가 통 넷에 물을 채워 번제물과 나무 위에 세 번 붓게 했다고 적지만, 그 까닭은 말하지 않아요. 다만 엘리야는 기도하면서, 자기가 주의 말씀대로 이 모든 일을 했다는 것을 오늘 알게 해 달라고 구했어요.","t3":"성경은 엘리야가 번제물과 나무 위에 물을 세 번 붓게 했고 도랑에도 물이 가득 찼다고 적지만, 왜 그렇게 했는지는 말하지 않는다. 다만 엘리야는 기도하면서, 자기가 주의 말씀대로 이 모든 일을 했다는 것을 오늘 알게 해 달라고 구했다. 성경은 여기까지 말한다."},"refs":["왕상 18:33-35","왕상 18:36"]}],"help":{"who":"갈멜 산에 모인 이스라엘 백성","steps":[{"kind":"stay","after":2,"title":"백성 곁에서 기다리기","basis":"왕상 18:26-29","text":{"t1":"바알의 선지자들이 아침부터 바알을 불렀지만 아무 대답이 없었어요. 우리는 그 일을 돕지 않고, 백성 곁에서 함께 기다려요.","t2":"바알의 선지자들은 오래도록 바알을 불렀지만, 아무 소리도 대답도 없었어요. 우리는 그들이 하는 일을 돕지 않아요. 백성 곁에 머물며 함께 기다려요.","t3":"바알의 선지자들이 바알을 부른다. 탐험대는 그들이 하는 일을 돕지 않고, 모인 백성 곁에 머물며 함께 기다린다."},"wait":"백성 곁에서 기다리기","say":{"who":"hyu","text":"우리는 내내 백성 곁에 있었어. 언제부터 언제까지였는지는 성경에서 찾아 적자."}},{"kind":"do","after":3,"title":"가까이 나아가는 백성에게 길 내어 주기","basis":"왕상 18:30","text":{"t1":"엘리야가 가까이 오라고 하자 백성이 다 엘리야에게 나아갔어요. 우리는 뒤쪽에 남아, 앞으로 가는 사람들 곁에서 길을 비켜 주며 도왔어요.","t2":"엘리야가 백성에게 가까이 오라고 하자, 백성이 다 엘리야에게 나아갔어요. 우리는 단 쪽으로 가지 않고 뒤쪽에 남아, 앞으로 가는 사람들이 지나가도록 길을 비켜 주었어요. 성경에 적힌 일이 아니라 탐험대가 한 일이에요.","t3":"엘리야가 가까이 오라고 하자 백성이 다 그에게 나아갔다(18:30). 탐험대는 단 쪽으로 가지 않고 뒤쪽에 남아, 앞으로 나아가는 사람들이 지나가도록 길을 비켜 준다. 성경에 적힌 일이 아니라 탐험대 이야기다."},"tasks":["앞으로 가는 사람들에게 길 비켜 주기","뒤에 오는 사람이 지나가게 기다리기","우리 짐을 뒤쪽 비탈로 옮기기"],"done":{"who":"hyu","text":"백성은 다 엘리야 가까이 갔어. 우리는 뒤쪽에서 지켜볼게."}},{"kind":"watch","after":3,"title":"곁에서 보기 · 엘리야가 고쳐 쌓은 단","basis":"왕상 18:30-32","text":{"t1":"엘리야가 무너져 있던 여호와의 단을 돌로 다시 쌓고, 둘레에 도랑을 만들었어요. 엘리야가 하는 거룩한 일이라서, 우리는 단과 돌에 손대지 않고 멀찍이서 봐요.","t2":"엘리야가 백성을 가까이 오게 하고, 무너진 여호와의 단을 고쳐 쌓았어요. 돌 열두 개로 단을 쌓고 그 둘레에 도랑을 만들었어요. 엘리야가 하는 거룩한 일이라서, 우리는 단과 돌에 손대지 않고 멀찍이서 봐요.","t3":"엘리야는 백성을 가까이 오게 하고 무너진 여호와의 단을 고쳐 쌓았다(18:30). 돌 열두 개로 단을 쌓고 그 둘레에 도랑을 만들었다(18:31-32). 엘리야가 여호와의 이름으로 하는 일이므로, 탐험대는 단과 돌과 도랑에 손대지 않고 멀찍이서 본다."},"say":{"who":"choeon","text":"단은 엘리야가 쌓아. 우리는 돌 하나도 건드리지 않을 거야."}},{"kind":"watch","after":4,"title":"곁에서 보기 · 제물과 나무 위에 부은 물","basis":"왕상 18:33-35","text":{"t1":"엘리야가 통에 물을 채워 와서 제물과 나무 위에 붓게 했어요. 엘리야가 시킨 일이라서 우리는 통과 물에 손대지 않고 멀찍이서 봐요.","t2":"엘리야는 나무를 벌여 놓고 송아지를 올린 뒤, 통 네 개에 물을 채워 와서 제물과 나무 위에 붓게 했어요. 물이 단 둘레로 흐르고 도랑에도 가득 찼어요. 엘리야가 시킨 일이라서, 우리는 통과 물에 손대지 않고 멀찍이서 봐요.","t3":"엘리야는 장작을 벌이고 송아지를 올린 뒤, 통 네 개에 물을 채워 와서 제물과 장작 위에 부으라고 했고, 그렇게 세 번 했다(18:33-34). 누가 물을 부었는지 성경은 말하지 않는다. 엘리야가 시킨 일이므로 탐험대는 통과 물에 손대지 않고 멀찍이서 본다."},"say":{"who":"onwoo","text":"물을 붓는 일에는 끼지 않아. 우리는 멀리서 보기만 하자."}},{"kind":"ask","after":"gates","title":"여호와의 불이 내린 일은 무슨 뜻이에요?","basis":"왕상 18:36-37","by":"엘리야","ask":{"who":"onwoo","text":"엘리야 님, 여호와의 불이 내린 일은 무슨 뜻이에요?"},"answer":{"t1":"엘리야는 기도할 때, 이 백성이 여호와께서 하나님이신 것을 알게 해 달라고 구했어요.","t2":"엘리야는 기도할 때, 여호와께서 이스라엘 가운데서 하나님이신 것과 자기가 주의 종인 것을 오늘 알게 해 달라고 구했어요. 그리고 이 백성이 여호와께서 하나님이신 것을 알게 해 달라고 거듭 구했어요.","t3":"엘리야는 기도할 때, 주께서 이스라엘 가운데서 하나님이신 것과 자기가 주의 종이며 이 모든 일을 주의 말씀에 따라 했다는 것을 오늘 알게 해 달라고 구했다. 또 자기에게 응답해 달라고 거듭 구하며, 이 백성이 주 여호와께서 하나님이신 것과 주께서 그들의 마음을 돌이키신다는 것을 깨닫게 해 달라고 했다."},"read":{"t1":{"type":"find","ref":"왕상 18:39","prompt":"성경책에서 열왕기상 18장 39절을 찾아 읽어 보세요.","confirm":{"prompt":"불이 내린 것을 본 모든 백성은 엎드려 무엇이라고 말했나요?","options":[{"label":"엘리야가 하나님의 사람이라고 했어요","basis":"왕상 17:24"},{"label":"여호와 그분이 하나님이시라고 했어요","ok":true},{"label":"바알이 하나님이라고 했어요","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"왕상 18:36-37","prompt":"성경책에서 열왕기상 18장 36절과 37절을 읽어 보세요.","confirm":{"prompt":"엘리야가 여호와께 응답해 달라고 거듭 구한 까닭은 무엇인가요?","options":[{"label":"이 백성이 여호와가 하나님이심을 알고, 바알의 선지자들도 모두 엘리야를 따르게 되기를 바라서","basis":"본문에 없음"},{"label":"이 백성이 여호와가 하나님이심을 알고, 주께서 그들의 마음을 돌이키신다는 것도 알게 되기를 바라서","ok":true},{"label":"이 백성이 여호와가 하나님이심을 알고, 아합 왕도 자기 잘못을 깨닫고 바알을 버리게 되기를 바라서","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["왕상 18:37","왕상 18:39"],"prompt":"열왕기상 18장 37절과 39절을 함께 찾아 읽어 보자.","confirm":{"prompt":"엘리야의 기도와 백성의 말을 이어 읽으면 무엇을 알 수 있는가?","options":[{"label":"엘리야는 이 백성이 여호와가 하나님이심을 알게 해 달라고 구했고, 불을 본 모든 백성은 엎드려 여호와 그분이 하나님이시라고 거듭 말했다","ok":true},{"label":"엘리야는 이 백성이 여호와가 하나님이심을 알게 해 달라고 구했고, 불을 본 백성은 엎드려 엘리야가 하나님의 사람이라고 말했다","basis":"왕상 17:24"},{"label":"엘리야는 하늘에서 비를 내려 달라고 구했고, 불을 본 모든 백성은 엎드려 여호와 그분이 하나님이시라고 거듭 말했다","basis":"본문에 없음"}]}}}}]}},"has3d":true,"epic":true},"OT-31":{"id":"OT-31","era":8,"title":"요나와 니느웨","ref":"욘 1:1-4:11","place":"욥바, 바다, 니느웨","review":{"required":true,"topics":["구약 사건의 신약적 의미(마 12:41)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"욘 1:1-3","open":"욘 1:2","focus":"jonah","text":{"t1":"하나님은 요나에게 큰 성읍 니느웨로 가서 외치라고 하셨지만, 요나는 여호와의 낯을 피해 욥바에서 배를 탔어요. 그 배가 어디로 가는 배였는지는 성경에서 찾아봐요.","t2":"아밋대의 아들 요나에게 여호와의 말씀이 임했어요. 하나님은 니느웨라는 큰 성읍에 가서 그 성읍을 쳐서 외치라고 하셨는데, 왜 그러셨는지는 2절에서 찾아봐요. 그러나 요나는 여호와의 낯을 피하려고 욥바로 내려가, 뱃삯을 내고 다시스로 가는 배에 올랐어요.","t3":"아밋대의 아들 요나에게 여호와의 말씀이 임했다. 여호와께서는 일어나 큰 성읍 니느웨로 가서 그 성읍을 쳐서 외치라고 하셨다. 그 성읍의 악이 여호와 앞에까지 올라왔기 때문이다. 그러나 요나는 욥바로 내려가 뱃삯을 내고 배에 올랐다. 무엇을 피해 어디로 가려 했는지는 3절에 있다."},"say":{"who":"hyu","text":"여기는 욥바야. 요나가 배에 올랐어. 적어 둘게."}},{"ref":"욘 1:4-12","focus":"ship","text":{"t1":"여호와께서 큰 바람을 보내셔서 배가 거의 부서지게 되었어요. 제비를 뽑으니 요나가 뽑혔고, 요나는 자기를 바다에 던지라고 했어요.","t2":"여호와께서 바다에 큰 바람을 보내셔서 폭풍이 일었고 배가 거의 부서지게 되었어요. 그 배 안에서 무슨 일이 어떤 차례로 일어났는지는 4절부터 12절까지 읽어 봐요.","t3":"여호와께서 바다 위에 큰 바람을 보내시니 큰 폭풍이 일어 배가 거의 부서지게 되었다. 뱃사람들은 두려워하여 저마다 자기 신을 부르고, 배를 가볍게 하려고 짐을 바다에 던졌다. 요나는 배 밑층에 내려가 누워 깊이 잠들어 있었다. 선장이 그에게 와서, 일어나 그의 하나님께 구하라고 했다. 사람들이 이 재앙이 누구 때문인지 알려고 제비를 뽑으니 요나가 뽑혔다. 요나는 자기가 히브리 사람이며, 하늘의 하나님 여호와 곧 바다와 육지를 지으신 분을 경외하는 사람이라고 대답했다. 요나가 여호와의 낯을 피하고 있다고 이미 말했으므로 사람들은 크게 두려워했다. 바다가 점점 사나워지자 그들은 어떻게 해야 바다가 잔잔해지겠느냐고 물었고, 요나는 이 큰 폭풍이 자기 때문인 줄 안다며 자기를 들어 바다에 던지라고 했다."},"say":{"who":"choeon","text":"배가 부서질 것 같아! 그런데 요나는 배 밑층에서 자고 있었어."}},{"ref":"욘 1:13-17","focus":"sea","text":{"t1":"뱃사람들이 요나를 바다에 던지자 바다가 곧 잔잔해졌어요. 여호와께서 준비하신 큰 물고기가 요나를 삼켰고, 요나는 사흘 밤낮을 물고기 배 속에 있었어요.","t2":"사람들은 힘껏 노를 저어 육지로 돌아가려 했지만, 바다가 더 사나워져서 할 수 없었어요. 그들은 여호와께 부르짖은 뒤 요나를 들어 바다에 던졌고, 바다가 곧 잔잔해졌어요. 그 사람들은 여호와를 크게 두려워하여 제물을 드리고 서원을 했어요. 여호와께서 큰 물고기를 준비하셔서 요나를 삼키게 하셨고, 요나는 사흘 낮과 밤을 물고기 배 속에 있었어요.","t3":"그 사람들은 힘써 노를 저어 배를 육지로 돌리려 했으나, 바다가 점점 더 사나워져서 할 수 없었다. 그들은 여호와께 부르짖어, 이 사람의 생명 때문에 자기들을 멸망시키지 마시고 죄 없는 피를 자기들에게 돌리지 말아 달라고 구했다. 그리고 요나를 들어 바다에 던지니 바다가 곧 잔잔해졌다. 그 사람들은 여호와를 몹시 두려워하게 되어, 여호와께 제물을 바치고 서원을 했다. 여호와께서 큰 물고기를 준비하셔서 요나를 삼키게 하셨고, 요나는 사흘 낮과 사흘 밤을 물고기 배 속에 있었다."},"say":{"who":"choeon","text":"바다가 잔잔해졌어. 그리고 큰 물고기가 요나를 삼켰어."}},{"ref":"욘 2:1-10","focus":"fish","text":{"t1":"요나는 물고기 배 속에서 구원은 여호와께로부터 온다고 기도했어요. 여호와께서 명하시자 물고기가 요나를 육지에 토해 냈어요.","t2":"요나는 물고기 배 속에서 하나님 여호와께 기도했어요. 괴로울 때 여호와께 부르짖었더니 대답해 주셨다고 했어요. 감사하는 목소리로 제사를 드리고 서원을 갚겠다고 했고, 구원은 여호와께로부터 온다고 했어요. 여호와께서 물고기에게 명하시자 물고기가 요나를 육지에 토해 냈어요.","t3":"요나는 물고기 배 속에서 그의 하나님 여호와께 기도했다. 고난 가운데 여호와께 부르짖었더니 대답하셨고, 스올의 배 속에서 부르짖었더니 자기 목소리를 들으셨다고 했다. 주께서 자기를 깊은 바다 가운데 던지셔서 큰 물이 자기를 둘렀고 파도와 물결이 자기 위로 넘쳤으며 바다풀이 머리를 감쌌으나, 여호와께서 자기 생명을 구덩이에서 건지셨다고 했다. 그는 감사하는 목소리로 제사를 드리고 서원을 갚겠다고 했으며, 구원은 여호와께로부터 온다고 했다. 여호와께서 그 물고기에게 명하시니 물고기가 요나를 육지에 토했다."},"say":{"who":"onwoo","text":"요나의 기도는 요나서 2장에 길게 적혀 있어. 성경책에서 직접 읽어 보자."}},{"ref":"욘 3:1-5","open":"욘 3:2","focus":"nineveh","text":{"t1":"하나님이 다시 말씀하시자 요나는 니느웨에 가서, 사십 일 뒤에 니느웨가 무너질 것이라고 외쳤어요. 니느웨 사람들은 하나님을 믿고 굵은 베를 입었어요.","t2":"여호와의 말씀이 두 번째로 요나에게 임했어요. 하나님은 니느웨로 가서 하나님이 명하신 것을 선포하라고 하셨고, 요나는 그 말씀대로 갔어요. 요나는 성에 들어가 하루 길을 걸으며 사십 일이 지나면 니느웨가 무너진다고 외쳤어요. 니느웨 백성은 하나님을 믿고 금식을 선포했고, 큰 사람부터 작은 사람까지 굵은 베를 입었어요.","t3":"여호와의 말씀이 두 번째로 요나에게 임했다. 여호와께서는 일어나 큰 성읍 니느웨로 가서 여호와께서 명하신 것을 그들에게 선포하라고 하셨다. 이번에 요나가 어떻게 니느웨로 갔는지는 3절에 있다. 니느웨는 사흘 길이 되는 매우 큰 성읍이었다. 요나는 성에 들어가 하루 길을 걸으며 사십 일이 지나면 니느웨가 무너진다고 외쳤다. 니느웨 백성은 하나님을 믿고 금식을 선포했으며, 큰 사람부터 작은 사람까지 굵은 베를 입었다."},"say":{"who":"hyu","text":"이번에는 요나가 니느웨로 갔어. 사십 일이라고 외쳤어. 적어 둘게."}},{"ref":"욘 3:6-10","focus":"king","text":{"t1":"니느웨 왕도 굵은 베를 입고, 모두 악한 길에서 떠나라고 했어요. 하나님은 그들이 돌이킨 것을 보시고 재앙을 내리지 않으셨어요.","t2":"그 소식을 들은 니느웨 왕은 보좌에서 일어나 왕의 옷을 벗고, 굵은 베를 입고 재에 앉았어요. 왕은 사람도 짐승도 먹지 말고 마시지 말며, 힘써 부르짖고 저마다 악한 길에서 떠나라고 선포했어요. 하나님은 그들이 악한 길에서 돌이켜 떠난 것을 보시고, 내리겠다고 하신 재앙을 내리지 않으셨어요.","t3":"그 소식이 니느웨 왕에게 들리자, 왕은 보좌에서 일어나 왕의 옷을 벗고 굵은 베를 입고 재에 앉았다. 왕과 대신들은 조서를 내려, 사람도 짐승도, 소 떼도 양 떼도 아무것도 먹지 말고 물도 마시지 말며, 사람과 짐승이 다 굵은 베를 입고 힘써 부르짖으며, 저마다 악한 길과 손으로 행한 강포에서 떠나라고 했다. 하나님이 뜻을 돌이키시고 진노를 그치셔서 자기들이 멸망하지 않게 하실지 누가 알겠느냐고 했다. 하나님은 뜻을 돌이키셔서, 그들에게 내리겠다고 하신 재앙을 내리지 않으셨다. 하나님이 무엇을 보고 그렇게 하셨는지는 10절에 있다."},"say":{"who":"choeon","text":"왕도 보좌에서 일어나 굵은 베를 입고 재에 앉았어."}},{"ref":"욘 4:1-5","open":"욘 4:4","focus":"booth","text":{"t1":"요나가 몹시 싫어하며 성을 내자, 하나님은 성내는 것이 옳으냐고 물으셨어요. 요나는 성 동쪽에 초막을 짓고 앉아 성읍이 어떻게 되는지 보려고 했어요.","t2":"요나는 이 일을 몹시 싫어하고 성내며 여호와께 기도했어요. 자기가 다시스로 달아났던 것은, 하나님이 은혜롭고 자비로우시며 재앙을 내리지 않으시는 분인 줄 알았기 때문이라고 했어요. 여호와께서는 요나가 성내는 것이 옳으냐고 물으셨어요. 요나는 성 동쪽으로 나가 초막을 짓고 그 그늘에 앉아, 성읍이 어떻게 되는지 보려고 했어요.","t3":"요나는 이 일을 몹시 싫어하고 성내며 여호와께 기도했다. 자기가 고국에 있을 때 이미 이렇게 될 것이라고 말하지 않았느냐고 했고, 그래서 서둘러 달아났다고 했다. 주께서 은혜로우시고 자비로우시며 노하기를 더디 하시고 인애가 크셔서, 뜻을 돌이켜 재앙을 내리지 않으시는 하나님이신 줄 알았기 때문이라고 했다. 요나는 이제 자기 생명을 거두어 달라고 구하며, 사는 것보다 죽는 것이 낫다고 했다. 여호와께서는 그가 성내는 것이 옳으냐고 물으셨다. 요나는 성에서 나가 성 동쪽에 초막을 짓고 그 그늘 아래 앉아, 성읍이 어떻게 되는지 보려고 했다."},"say":{"who":"hyu","text":"요나가 성 동쪽에 초막을 지었어. 자리를 적어 둘게."}},{"ref":"욘 4:6-11","open":"욘 4:10-11","focus":"gourd","text":{"t1":"하나님은 박 넝쿨로 요나에게 그늘을 주셨다가, 이튿날 벌레가 갉아 먹게 하여 시들게 하셨어요. 하나님은 요나가 박 넝쿨을 아꼈는데 하나님이 큰 성읍 니느웨를 아끼는 것이 옳지 않으냐고 하셨어요.","t2":"하나님 여호와께서는 박 넝쿨 하나를 마련하셔서 요나의 머리 위에 그늘이 지게 하셨고, 요나는 몹시 기뻐했어요. 이튿날 새벽에 하나님이 벌레를 마련하셔서 박 넝쿨을 갉아 먹게 하시니 넝쿨이 시들었어요. 해가 뜰 무렵에는 하나님이 뜨거운 동쪽 바람을 마련하셨으며, 해가 요나의 머리에 내리쬐었어요. 하나님은 요나가 수고하지도 않은 박 넝쿨을 아꼈는데, 하나님이 큰 성읍 니느웨를 아끼는 것이 옳지 않으냐고 하셨어요.","t3":"하나님 여호와께서는 박 넝쿨 하나를 마련하셔서 요나 위를 가리게 하셨다. 그의 머리에 그늘이 지게 하여 괴로움을 면하게 하시려는 것이었고, 요나는 박 넝쿨 때문에 몹시 기뻐했다. 이튿날 새벽에 하나님이 벌레를 마련하셔서 박 넝쿨을 갉아 먹게 하시니 곧 시들었다. 해가 뜰 무렵 하나님이 뜨거운 동쪽 바람을 마련하셨으며, 해가 요나의 머리에 내리쬐니 요나는 기운을 잃고 사는 것보다 죽는 것이 낫다고 했다. 하나님이 박 넝쿨 때문에 성내는 것이 옳으냐고 물으시자, 요나는 성내어 죽기까지 하더라도 옳다고 대답했다. 여호와께서는, 요나가 수고하지도 기르지도 않았고 하룻밤 사이에 났다가 하룻밤 사이에 없어진 박 넝쿨을 아꼈는데, 큰 성읍 니느웨를 여호와께서 아끼는 것이 마땅하지 않으냐고 하셨다."},"say":{"who":"onwoo","text":"요나서는 하나님의 말씀으로 끝나. 4장 10절과 11절을 성경책에서 직접 읽어 보자."}}],"gates":{"t1":[{"type":"find","ref":"욘 1:3","prompt":"성경책에서 요나서 1장 3절을 찾아 읽어 보세요.","confirm":{"prompt":"요나가 욥바에서 탄 배는 어디로 가는 배였나요?","options":[{"label":"다시스","ok":true},{"label":"니느웨","basis":"욘 3:3"},{"label":"애굽","basis":"본문에 없음"}]}},{"type":"multi","ref":"욘 1:8","prompt":"성경책에서 요나서 1장 8절을 찾아 읽어 보세요.","confirm":{"prompt":"배에 있던 무리가 요나에게 물은 것을 모두 고르세요.","options":[{"label":"무슨 일을 하며 사는지","ok":true},{"label":"몇 살인지","basis":"본문에 없음"},{"label":"어디서 왔는지","ok":true},{"label":"뱃삯을 냈는지","basis":"욘 1:3"},{"label":"어느 민족 사람인지","ok":true}]}}],"t2":[{"type":"find","ref":"욘 1:1-2","prompt":"성경책에서 요나서 1장 1절과 2절을 읽어 보세요.","confirm":{"prompt":"하나님이 요나에게 니느웨로 가서 그 성읍을 쳐서 외치라고 하신 까닭은 무엇인가요?","options":[{"label":"니느웨 사람들이 요나를 보고 싶어 했기 때문에","basis":"본문에 없음"},{"label":"니느웨의 악이 하나님 앞에까지 올라왔기 때문에","ok":true},{"label":"니느웨에 큰 배가 많았기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"욘 1:4-12","prompt":"성경책에서 요나서 1장 4절부터 12절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["여호와께서 바다에 큰 바람을 보내셨다","뱃사람들이 두려워 저마다 자기 신을 부르고 짐을 바다에 던졌다","선장이 잠든 요나에게 와서 그의 하나님께 구하라고 했다","사람들이 제비를 뽑으니 요나가 뽑혔다","요나가 자기를 들어 바다에 던지라고 했다"]}],"t3":[{"type":"find","refs":["욘 1:2-3","욘 3:2-3"],"prompt":"요나서 1장 2~3절과 3장 2~3절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 니느웨로 가라는 말씀에 요나는 처음과 두 번째에 어떻게 했는가?","options":[{"label":"처음에는 여호와의 낯을 피해 다시스로 가는 배를 탔고, 두 번째에는 말씀대로 일어나 니느웨로 갔다","ok":true},{"label":"처음에는 여호와의 낯을 피해 애굽으로 가는 배를 탔고, 두 번째에는 말씀대로 일어나 니느웨로 갔다","basis":"본문에 없음"},{"label":"처음에는 여호와의 낯을 피해 다시스로 가는 배를 탔고, 두 번째에는 말씀을 듣고도 한참 머뭇거리다가 니느웨로 갔다","basis":"본문에 없음"}]}},{"type":"match","refs":["욘 1:17","욘 4:6","욘 4:7","욘 4:8"],"prompt":"요나서 1장 17절, 4장 6절, 7절, 8절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"욘 1:17","text":"큰 물고기가 요나를 삼키도록 여호와께서 미리 마련해 두셨다"},{"ref":"욘 4:6","text":"하나님이 박 넝쿨로 요나의 머리 위를 가려 그늘을 주셨다"},{"ref":"욘 4:7","text":"하나님이 준비하신 벌레가 이튿날 새벽 박 넝쿨을 갉아 먹어 시들게 했다"},{"ref":"욘 4:8","text":"해 뜰 무렵 하나님이 뜨거운 동쪽 바람을 준비하셨고, 해가 요나의 머리에 내리쬐었다"}],"after":"네 곳을 이으면, 요나의 이야기 내내 하나님이 큰 물고기와 박 넝쿨과 벌레와 뜨거운 동풍을 마련하셨다는 것이 보인다."}]},"cards":[{"ref":"욘 2:9","title":"구원은 여호와께로서"},{"ref":"욘 4:11","title":"큰 성읍 니느웨를 아끼심"}],"close":{"t1":{"kind":"prayer","text":"하나님, 요나와 니느웨의 이야기를 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 요나서 3장 1절부터 10절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"욘 1:1-4:11에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"얘들아, 욥바 가까이에 내렸는데 공기 거르개가 막혀 버렸어요. 거르개 대신 쓸 부드러운 털 뭉치를 찾아 주세요. 사람들이 하는 일에는 끼지 말고 곁에서 보기만 해요.","t2":"얘들아, 타임머신이 욥바 가까이에 비상 착륙했어요. 바람을 거르는 거르개가 막혀서 바꿔야 해요. 그 시대에는 우리 부속이 없으니, 부드러운 털 뭉치를 구해서 거르개 대신 쓰면 돼요. 함께 기다리는 것은 괜찮지만, 사람들이 하는 일에는 끼지 말고 곁에서 보기만 해요.","t3":"타임머신이 욥바 가까이에 비상 착륙했다. 공기 거르개가 막혔으니 거르개 대신 쓸 부드러운 털 뭉치가 필요하다. 짐승에게서 직접 뜯지 말고, 땅에 떨어진 것만 주워 오기 바란다. 함께 기다리는 것은 괜찮지만, 사람들이 하는 일에는 끼지 않고 곁에서 보기만 하자."},"materials":[{"key":"wool","name":"양털","basis":"욘 3:7","line":"니느웨 성 밖 길가에서 떨어진 양털 한 줌을 주웠어!","use":"양털을 뭉쳐서 막힌 공기 거르개 대신 쓸 수 있어요.","how":"니느웨 성 밖 길가에 떨어져 있는 양털을 한 줌 줍는다. 양 떼와 사람들의 물건에는 손대지 않는다."}],"companion":{"who":"요나","ref":"욘 4:5","when":"after","talks":[{"ask":{"who":"hyu","text":"요나 님, 배에서 사람들이 누구냐고 물었을 때 뭐라고 대답하셨어요?"},"answer":{"t1":"요나는 자기가 히브리 사람이라고 대답했어요. 자기는 하늘의 하나님이신 여호와를 경외하는데, 그분이 바다와 땅을 지으셨다고 했어요.","t2":"요나는 자기가 히브리 사람이라고 대답했어요. 자기는 하늘의 하나님이신 여호와를 경외하는 사람이고, 그분은 바다와 마른 땅을 지으신 분이라고 했어요.","t3":"요나는 자기가 히브리 사람이라고 대답했다. 그리고 자기가 경외하는 분은 하늘의 하나님이신 여호와이며, 그분이 바다와 마른 땅을 지으셨다고 했다."},"ref":"욘 1:9","open":"욘 1:9"},{"ask":{"who":"choeon","text":"물고기 배 속에서 무엇이라고 기도하셨어요?"},"answer":{"t1":"요나는 괴로울 때 여호와께 부르짖었더니 대답해 주셨다고 기도했어요. 구원은 여호와께로부터 온다고 했어요.","t2":"요나는 괴로움 속에서 여호와께 부르짖었더니 대답해 주셨고, 스올의 배 속에서 부르짖을 때 자기 목소리를 들으셨다고 기도했어요. 감사하는 목소리로 제사를 드리고 서원을 갚겠다고 했고, 구원은 여호와께로부터 온다고 했어요.","t3":"요나는 고난 가운데 여호와께 부르짖었더니 대답하셨고, 스올의 배 속에서 부르짖었더니 자기 목소리를 들으셨다고 기도했다. 또 여호와께서 자기 생명을 구덩이에서 건지셨다고 했다. 그는 감사하는 목소리로 제사를 드리고 서원을 갚겠다고 했으며, 구원은 여호와께로부터 온다고 했다."},"ref":"욘 2:2-9","open":"욘 2:2"}]},"today":[{"q":"하나님을 피해서 숨을 수 있어요?","a":{"t1":"요나는 여호와를 피하려고 다시스로 가는 배를 탔어요. 그런데 여호와께서 바다에 큰 바람을 보내셨어요. 시편은 하늘에 가도, 바다 끝에 가도 주께서 거기 계신다고 노래해요.","t2":"요나는 여호와의 낯을 피하려고 다시스로 가는 배를 탔지만, 여호와께서 바다에 큰 바람을 보내셨어요. 시편 139편은 주의 앞을 떠나 어디로 피할 수 있겠느냐고 묻고, 하늘에 올라가도 바다 끝에 가서 살아도 주께서 거기 계셔서 인도하신다고 노래해요.","t3":"요나는 여호와의 낯을 피하여 다시스로 가려고 배에 올랐으나, 여호와께서 바다 위에 큰 바람을 보내셨다. 시편 139편은 주의 앞을 떠나 어디로 피하겠느냐고 묻고, 하늘에 올라가도, 스올에 자리를 펴도, 바다 끝에 가서 살아도 주께서 거기 계셔서 주의 손이 인도하고 붙드신다고 노래한다. 성경은 여기까지 말한다."},"refs":["욘 1:3-4","시 139:7-10"]}],"help":{"who":"니느웨 백성과 요나","steps":[{"kind":"watch","after":4,"title":"곁에서 보기 · 굵은 베를 입은 니느웨 백성","basis":"욘 3:5","text":{"t1":"니느웨 사람들이 하나님을 믿고, 음식을 끊고 굵은 베를 입었어요. 니느웨 사람들이 하는 일이라서 우리는 끼지 않고 곁에서 봐요.","t2":"니느웨 백성은 하나님을 믿고 금식하자고 알렸고, 큰 사람부터 작은 사람까지 굵은 베를 입었어요. 니느웨 사람들이 하나님 앞에서 하는 일이라서, 우리는 끼지 않고 곁에서 봐요.","t3":"니느웨 백성은 하나님을 믿고 금식하자고 알렸으며, 큰 사람부터 작은 사람까지 굵은 베를 입었다(3:5). 니느웨 사람들이 하나님 앞에서 하는 일이므로, 탐험대는 끼지 않고 곁에서 본다."},"say":{"who":"hyu","text":"큰 사람도 작은 사람도 굵은 베를 입었어. 적어 둘게."}},{"kind":"stay","after":6,"title":"성 동쪽에서 기다리기","basis":"욘 4:5","text":{"t1":"요나가 성 동쪽에 초막을 짓고 앉아, 성읍에 무슨 일이 생기는지 보려고 했어요. 우리도 성 동쪽에서 함께 기다려요.","t2":"요나는 성에서 나가 동쪽에 초막을 지어 그늘에 앉아, 성읍에 무슨 일이 생기는지 보려고 했어요. 우리도 끼어들지 않고 성 동쪽에서 함께 기다려요.","t3":"요나는 성에서 나가 동쪽에 초막을 지어 그늘에 앉아, 성읍에 무슨 일이 생기는지 보려고 했다(4:5). 탐험대도 끼어들지 않고 성 동쪽에서 함께 기다린다."},"wait":"성 동쪽에서 기다리기","say":{"who":"onwoo","text":"우리는 요나 곁에서 기다리기만 해. 그 뒤의 일은 성경을 읽으며 보자."}},{"kind":"do","after":7,"title":"머문 자리 정리하기","basis":"욘 4:5","text":{"t1":"우리는 성 동쪽에서 요나 곁에 머물렀어요. 이제 떠나기 전에, 우리가 머문 자리를 정리해 아무것도 남기지 않아요.","t2":"우리는 성 동쪽에서 요나 곁에 머물며 기다렸어요. 요나의 초막과 박 넝쿨에는 손대지 않고, 우리가 머문 자리만 정리해서 이 시대에 아무것도 남기지 않아요. 성경에 적힌 일이 아니라 탐험대가 하는 일이에요.","t3":"요나는 성 동쪽에 초막을 짓고 그 그늘에 앉아 있었다(4:5). 탐험대는 요나의 초막과 박 넝쿨에는 손대지 않고, 머문 자리만 정리해 이 시대에 아무것도 남기지 않는다. 성경에 적힌 일이 아니라 탐험대 이야기다."},"tasks":["떨어뜨린 물건이 없는지 살피기","우리가 쓴 도구 챙기기","앉았던 자리 고르게 해 두기"],"done":{"who":"onwoo","text":"아무것도 남기지 않았어. 과거에는 우리 물건을 하나도 두고 가지 않아."}},{"kind":"ask","after":"gates","title":"니느웨에 재앙이 내리지 않은 일은 무슨 뜻이에요?","basis":"욘 4:2","by":"요나","ask":{"who":"choeon","text":"요나 님, 니느웨에 재앙이 내리지 않은 일은 무슨 뜻이에요?"},"answer":{"t1":"요나는 기도하면서, 여호와께서 은혜롭고 자비로우셔서 재앙을 내리지 않으시는 하나님이신 줄 알았다고 말했어요.","t2":"요나는 여호와께 기도하면서, 여호와께서 은혜롭고 자비로우시며 화를 더디 내시고 인애가 크신 분이라고 했어요. 그리고 재앙을 내리지 않으시는 하나님이신 줄 알았다고 했어요.","t3":"요나는 여호와께 기도하면서, 주께서 은혜롭고 자비로우시며 화를 더디 내시고 인애가 크셔서, 뜻을 돌이키시고 재앙을 내리지 않으시는 하나님이신 줄 알았다고 했다. 그는 그것 때문에 처음에 서둘러 다시스로 달아났다고 했다."},"read":{"t1":{"type":"find","ref":"욘 4:11","prompt":"성경책에서 요나서 4장 11절을 찾아 읽어 보세요.","confirm":{"prompt":"하나님은 니느웨에 좌우를 가리지 못하는 사람이 몇 명 넘게 있다고 하셨나요?","options":[{"label":"사십 명","basis":"본문에 없음"},{"label":"삼천 명","basis":"본문에 없음"},{"label":"십이만 명","ok":true}]}},"t2":{"type":"find","ref":"욘 4:10-11","prompt":"성경책에서 요나서 4장 10절과 11절을 읽어 보세요.","confirm":{"prompt":"하나님이 니느웨를 아끼는 것이 마땅하다고 하시며 드신 까닭은 무엇인가요?","options":[{"label":"좌우를 가리지 못하는 사람이 십이만 명이 넘고 가축도 많은 큰 성읍이기 때문에","ok":true},{"label":"금과 은이 많고 성벽이 높아서 둘레의 여러 나라가 부러워하는 큰 성읍이기 때문에","basis":"본문에 없음"},{"label":"요나가 태어난 고향이고 요나의 친척들도 많이 사는 큰 성읍이기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["욘 3:10","욘 4:11"],"prompt":"요나서 3장 10절과 4장 11절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 니느웨에 재앙이 내리지 않은 일을 두고 성경은 무엇을 말하는가?","options":[{"label":"하나님은 니느웨 왕이 금식을 선포한 것을 보시고 재앙을 내리지 않으셨고, 왕이 다스리는 그 큰 성읍을 아끼는 것이 마땅하지 않으냐고 요나에게 물으셨다","basis":"본문에 없음"},{"label":"하나님은 니느웨 사람들이 악한 길을 버리고 돌아선 것을 보시고 재앙을 내리지 않으셨고, 사람과 가축이 많은 그 큰 성읍을 아끼는 것이 마땅하지 않으냐고 요나에게 물으셨다","ok":true},{"label":"하나님은 니느웨 사람들이 악한 길을 버리고 돌아선 것을 보시고 재앙을 내리지 않으셨고, 요나가 그 성읍에서 수고했으니 아끼는 것이 마땅하지 않으냐고 물으셨다","basis":"본문에 없음"}]}}},"nt":{"ref":"마 12:41","text":"신약의 마태복음 12장 41절은 니느웨 사람들이 요나가 전한 말을 듣고 회개했다고 말한다."}}]}},"has3d":false,"epic":false},"OT-32":{"id":"OT-32","era":8,"title":"북 이스라엘이 사로잡혀 감","ref":"왕하 17:1-23","place":"사마리아, 앗수르","review":{"required":true,"topics":["재앙과 심판(왕하 17:6-7, 17:18-23)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"왕하 17:1-2","focus":"hoshea","text":{"t1":"호세아가 이스라엘의 왕이 되어 사마리아에서 아홉 해 동안 다스렸어요. 호세아는 여호와 보시기에 악을 행했어요.","t2":"엘라의 아들 호세아가 이스라엘의 왕이 되어 사마리아에서 아홉 해를 다스렸어요. 호세아는 여호와 보시기에 악을 행했어요. 하지만 그전의 이스라엘 왕들과 같지는 않았어요.","t3":"유다 왕 아하스가 다스린 지 십이 년째 되던 해, 엘라의 아들인 호세아가 이스라엘의 왕이 되어 사마리아에서 다스렸다. 몇 해를 다스렸는지는 1절에 있다. 그는 여호와 보시기에 악을 행했으나, 그전의 이스라엘 왕들과 같지는 않았다."},"say":{"who":"hyu","text":"여기는 사마리아야. 이스라엘의 왕은 호세아. 적어 둘게."}},{"ref":"왕하 17:3-4","focus":"assyria","text":{"t1":"앗수르 왕이 쳐들어오자 호세아는 조공을 바쳤어요. 그러다 조공을 그치자, 앗수르 왕이 호세아를 옥에 가두었어요.","t2":"앗수르 왕 살만에셀이 올라와 호세아를 치자, 호세아는 그의 신하가 되어 조공을 바쳤어요. 그런데 앗수르 왕은 나중에 호세아를 옥에 가두었는데, 왜 그랬는지는 4절에서 찾아봐요.","t3":"앗수르 왕 살만에셀이 올라와 호세아를 치니, 호세아는 그의 신하가 되어 조공을 바쳤다. 그러나 호세아는 사자들을 애굽 왕 소에게 보냈고, 해마다 하던 것과 달리 앗수르 왕에게 조공을 바치지 않았다. 앗수르 왕은 호세아가 배반한 것을 알고 그를 잡아 옥에 가두었다."},"say":{"who":"choeon","text":"앗수르 왕이 호세아 왕을 옥에 가두었어."}},{"ref":"왕하 17:5-6","focus":"samaria","text":{"t1":"앗수르 왕은 사마리아를 에워싼 뒤 차지했고, 이스라엘 사람들은 앗수르로 끌려갔어요. 몇 해 동안 에워쌌는지는 성경에서 찾아봐요.","t2":"앗수르 왕이 다시 올라왔고, 끝내 이스라엘 사람들은 사로잡혀 갔어요. 그사이에 무슨 일이 어떤 차례로 있었는지는 5절과 6절에서 읽어 봐요.","t3":"앗수르 왕은 올라와 그 온 땅을 두루 다니고, 사마리아로 올라와 삼 년 동안 에워쌌다. 마침내 앗수르 왕은 사마리아를 차지하고 이스라엘 사람들을 사로잡아 앗수르 땅으로 끌고 가서, 할라와 고산 강가의 하볼과 메대 사람들의 여러 고을에 두었다. 그때가 호세아가 다스린 지 몇째 해였는지는 6절에 있다."},"say":{"who":"hyu","text":"앗수르 왕이 또 올라왔어. 우리는 멀리서 지켜보자."}},{"ref":"왕하 17:7-12","focus":"highplaces","text":{"t1":"성경은 이 일이, 이스라엘 자손이 자기들을 애굽에서 이끌어 내신 여호와께 죄를 지었기 때문이라고 말해요. 그들은 다른 신들을 받들고 우상을 섬겼어요.","t2":"성경은 이 일이 일어난 까닭을 말해요. 이스라엘 자손이 자기들을 애굽에서 인도해 내신 하나님 여호와께 죄를 짓고 다른 신들을 경외했기 때문이에요. 그들은 모든 성읍에 산당을 세우고, 산 위와 푸른 나무 아래마다 목상과 아세라상을 세웠어요. 여호와께서 하지 말라고 명하신 우상 섬기는 일도 했어요.","t3":"이 일이 왜 일어났는지 성경이 처음 밝히는 말은 7절에서 직접 읽어 보자. 그들은 여호와께서 이스라엘 자손 앞에서 몰아내신 이방 사람들의 규례를 따랐고, 이스라엘의 왕들이 세운 율례도 따랐다. 또 하나님 여호와를 거슬러 몰래 옳지 않은 일을 하고, 망대에서 견고한 성까지 모든 성읍에 산당을 세웠으며, 산 위마다 푸른 나무 아래마다 목상과 아세라상을 세우고 산당마다 분향했다. 여호와께서 하지 말라고 명하신 우상 섬기는 일도 했다."},"say":{"who":"choeon","text":"산 위에도, 푸른 나무 아래에도 목상을 세웠대. 성경에 그렇게 적혀 있어."}},{"ref":"왕하 17:13-17","open":"왕하 17:13","focus":"prophets","text":{"t1":"여호와께서는 선지자들을 통해 악한 길에서 돌이키라고 하셨지만, 그들은 듣지 않았어요. 명령을 버리고 송아지 형상을 만들고 바알을 섬겼어요.","t2":"여호와께서는 선지자와 선견자들을 통해 이스라엘과 유다를 경계하셨어요. 악한 길에서 돌이켜 하나님의 명령과 율례를 지키라고 하셨어요. 그러나 그들은 듣지 않고 조상들처럼 목을 굳게 했어요. 여호와의 언약을 버리고, 송아지 형상 둘과 아세라 목상을 만들고, 하늘의 해와 달과 별을 숭배하고 바알을 섬겼어요.","t3":"여호와께서는 모든 선지자와 선견자를 통해 이스라엘과 유다를 경계하셔서, 악한 길에서 돌이켜 조상들에게 명하시고 선지자들을 통해 전하신 모든 율법대로 명령과 율례를 지키라고 하셨다. 그러나 그들은 듣지 않고, 하나님 여호와를 믿지 않던 조상들처럼 목을 굳게 했다. 여호와의 율례도, 조상들과 맺으신 언약도, 경계하신 말씀도 버리고 헛된 것을 따랐으며, 본받지 말라고 하신 둘레의 이방 사람들을 본받았다. 하나님 여호와의 모든 명령을 버리고 송아지 형상 둘을 부어 만들고 아세라 목상을 만들었으며, 하늘의 해와 달과 별을 숭배하고 바알을 섬겼다. 자녀를 불 가운데로 지나가게 하고 복술과 사술을 행하여, 여호와 보시기에 악을 행하고 그분을 노하시게 했다."},"say":{"who":"onwoo","text":"여호와께서 선지자들을 통해 하신 말씀은 13절에 있어. 성경책에서 직접 읽어 보자."}},{"ref":"왕하 17:18-20","focus":"judah","text":{"t1":"여호와께서는 크게 노하셔서 이스라엘을 그 앞에서 쫓아내셨고, 유다 지파만 남았어요. 그런데 유다도 하나님의 명령을 지키지 않았어요.","t2":"여호와께서는 이스라엘에게 크게 노하셔서 그들을 그 앞에서 쫓아내셨고, 유다 지파만 남았어요. 그런데 유다도 하나님 여호와의 명령을 지키지 않고 이스라엘 사람들이 세운 율례를 따랐어요. 여호와께서는 이스라엘의 온 족속을 버리시고, 노략하는 사람들의 손에 넘기셨어요.","t3":"그래서 여호와께서는 이스라엘에게 크게 노하셔서 그들을 그 앞에서 제하셨고, 유다 지파 말고는 남은 지파가 없었다. 유다도 하나님 여호와의 명령을 지키지 않고 이스라엘 사람들이 세운 율례를 따랐다. 여호와께서는 이스라엘의 온 족속을 버리시고 괴롭게 하시며 노략하는 자들의 손에 넘기셔서, 마침내 그 앞에서 쫓아내셨다."},"say":{"who":"hyu","text":"남은 지파는 유다뿐이야. 일지에 적어 둘게."}},{"ref":"왕하 17:21-23","focus":"exile","text":{"t1":"이스라엘은 여로보암을 왕으로 세운 뒤, 그가 이끈 죄에서 떠나지 않았어요. 그래서 여호와께서 선지자들을 통해 하신 말씀대로, 이스라엘은 앗수르로 사로잡혀 갔어요.","t2":"여호와께서 이스라엘을 다윗의 집에서 찢어 나누셨을 때, 그들은 느밧의 아들 여로보암을 왕으로 세웠어요. 그 뒤 여로보암과 이스라엘 자손이 어떻게 했는지는 21절과 22절에서 찾아봐요. 마침내 여호와께서는 선지자들을 통해 하신 말씀대로 이스라엘을 그 앞에서 쫓아내셨어요. 이스라엘은 고향에서 앗수르로 사로잡혀 갔어요.","t3":"여호와께서 다윗의 집에서 이스라엘을 찢어 나누시자 그들은 느밧의 아들 여로보암을 왕으로 세웠고, 여로보암은 이스라엘을 몰아 여호와를 떠나게 하여 큰 죄를 짓게 했다. 이스라엘 자손은 여로보암이 지은 모든 죄를 따라 행하며 거기서 떠나지 않았다. 마침내 여호와께서 하신 일과, 그것이 무엇을 따른 것이었는지는 23절에서 직접 읽어 보자. 이스라엘은 고향에서 앗수르로 사로잡혀 갔고, 성경은 그것이 오늘까지 이르렀다고 적는다."},"say":{"who":"choeon","text":"이스라엘 사람들이 고향을 떠나 앗수르로 끌려가고 있어."}}],"gates":{"t1":[{"type":"find","ref":"왕하 17:5","prompt":"성경책에서 열왕기하 17장 5절을 찾아 읽어 보세요.","confirm":{"prompt":"앗수르 왕은 사마리아를 몇 해 동안 에워쌌나요?","options":[{"label":"삼 년","ok":true},{"label":"구 년","basis":"왕하 17:1"},{"label":"사십 년","basis":"본문에 없음"}]}},{"type":"multi","ref":"왕하 17:6","prompt":"성경책에서 열왕기하 17장 6절을 찾아 읽어 보세요.","confirm":{"prompt":"앗수르 왕이 사로잡은 이스라엘 사람들을 데려다 둔 곳을 모두 고르세요.","options":[{"label":"할라","ok":true},{"label":"애굽","basis":"왕하 17:4"},{"label":"고산 강가의 하볼","ok":true},{"label":"다시스","basis":"욘 1:3"},{"label":"메대 사람의 여러 고을","ok":true}]}}],"t2":[{"type":"find","ref":"왕하 17:3-4","prompt":"성경책에서 열왕기하 17장 3절과 4절을 읽어 보세요.","confirm":{"prompt":"앗수르 왕이 호세아를 옥에 가둔 까닭은 무엇인가요?","options":[{"label":"호세아가 사마리아에 성을 높이 쌓고 군사를 모아서, 앗수르 왕이 그가 싸우려는 것을 알았기 때문에","basis":"본문에 없음"},{"label":"호세아가 애굽 왕 소에게도 사자들을 보냈고 해마다 하던 조공을 그쳐서, 앗수르 왕이 그가 배반한 것을 알았기 때문에","ok":true},{"label":"호세아가 유다 왕 아하스에게 사자들을 보내 함께 싸우자고 해서, 앗수르 왕이 그가 배반한 것을 알았기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"왕하 17:5-6","prompt":"성경책에서 열왕기하 17장 5절과 6절을 읽고, 일어난 차례대로 눌러 보세요.","items":["앗수르 왕이 이스라엘 온 땅을 두루 다녔다","앗수르 왕이 사마리아로 올라와 그 성을 에워쌌다","호세아가 다스린 지 아홉째 해, 사마리아가 앗수르 왕의 손에 들어갔다","앗수르 왕이 이스라엘 사람들을 붙잡아 앗수르로 데려갔다","끌려간 사람들을 할라와 하볼과 메대 사람의 고을들에 두었다"]}],"t3":[{"type":"find","refs":["왕하 17:1","왕하 17:6"],"prompt":"열왕기하 17장 1절과 6절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 앗수르 왕이 사마리아를 차지한 해는 호세아가 다스린 햇수 가운데 어느 해인가?","options":[{"label":"호세아가 다스린 일곱째 해다. 1절은 호세아가 칠 년 동안 다스렸다고 하고, 6절은 그 칠 년째에 사마리아가 앗수르 왕의 손에 들어갔다고 한다","basis":"본문에 없음"},{"label":"호세아가 다스린 마지막 해다. 1절은 호세아가 구 년 동안 다스렸다고 하고, 6절은 그 구 년째에 사마리아가 앗수르 왕의 손에 들어갔다고 한다","ok":true},{"label":"호세아가 다스린 셋째 해다. 1절은 호세아가 삼 년 동안 다스렸다고 하고, 6절은 그 삼 년째에 사마리아가 앗수르 왕의 손에 들어갔다고 한다","basis":"본문에 없음"}]}},{"type":"match","refs":["왕하 17:2","왕하 17:18","왕하 17:21"],"prompt":"열왕기하 17장 2절, 18절, 21절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"왕하 17:2","text":"호세아는 악을 행했지만 그전의 이스라엘 왕들과 같지는 않았다"},{"ref":"왕하 17:18","text":"여호와께서 크게 노하셔서 이스라엘을 그 앞에서 쫓아내시니 유다 지파만 남았다"},{"ref":"왕하 17:21","text":"다윗의 집에서 나뉜 뒤 이스라엘은 여로보암을 왕으로 세웠다"}],"after":"세 곳을 이으면, 다윗의 집에서 나뉜 이스라엘은 여로보암을 왕으로 세웠고, 호세아는 악을 행했으나 그전 왕들과 같지는 않았으며, 여호와께서 이스라엘을 그 앞에서 쫓아내시니 유다 지파만 남았다."}]},"cards":[{"ref":"왕하 17:7","title":"애굽에서 인도하여 내신 하나님 여호와"},{"ref":"왕하 17:13","title":"돌이켜 악한 길에서 떠나라"}],"close":{"t1":{"kind":"prayer","text":"하나님, 이스라엘이 사로잡혀 간 이야기를 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 열왕기하 17장 7절부터 14절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"왕하 17:1-23에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"얘들아, 사마리아 가까이에 내렸는데 균형을 잡아 주던 추가 떨어져 나갔어요. 추 대신 쓸 고운 모래를 조금 찾아 주세요. 이곳 사람들에게 일어나는 일에는 끼어들지 말고 멀리서 보기만 해요.","t2":"얘들아, 타임머신이 사마리아 가까이에 비상 착륙했어요. 기계가 기울지 않게 잡아 주던 균형추가 떨어져 나갔어요. 그 시대에는 우리 부속이 없으니, 고운 모래를 주머니에 담아 추 대신 쓰면 돼요. 이곳 사람들에게 일어나는 일에는 끼어들지 말고, 멀리서 보기만 해요.","t3":"타임머신이 사마리아 가까이에 비상 착륙했다. 균형추가 떨어져 나갔으니, 고운 모래를 작은 주머니에 담아 추 대신 써야 한다. 사람들과 그 물건에는 손대지 말고, 사람들과 멀리 떨어진 곳에서 모래만 떠 오기 바란다. 이곳 사람들에게 일어나는 일에는 끼어들지 않고 멀리서 보기만 하자."},"materials":[{"key":"sand","name":"고운 모래","basis":"왕하 17:6","line":"사람들과 멀리 떨어진 강가에서 고운 모래를 한 줌 떴어!","use":"고운 모래를 작은 주머니에 담아 떨어진 균형추 대신 쓸 수 있어요.","how":"사람들이 있는 곳에서 멀리 떨어진 강가에서 물가의 고운 모래를 한 줌 떠 담는다. 사람들과 그 물건에는 손대지 않는다."}],"companion":null,"today":[{"q":"성경에서 말하는 우상은 어떤 거예요?","a":{"t1":"이스라엘은 송아지 형상을 부어 만들고, 목상과 아세라상을 세웠어요. 여호와께서는 이런 일을 하지 말라고 명하셨어요.","t2":"이스라엘은 송아지 형상 둘을 부어 만들고, 산 위와 푸른 나무 아래마다 목상과 아세라상을 세웠어요. 여호와께서는 우상 섬기는 일을 하지 말라고 명하셨어요. 출애굽기 20장의 말씀에도 자기를 위하여 새긴 우상을 만들지 말라고 하셨어요.","t3":"성경은 이스라엘이 송아지 형상 둘을 부어 만들고, 산 위와 푸른 나무 아래마다 목상과 아세라상을 세웠으며, 하늘의 해와 달과 별을 숭배하고 바알을 섬겼다고 적는다. 여호와께서는 우상 섬기는 일을 하지 말라고 명하셨다. 출애굽기 20장에서도 자기를 위하여 새긴 우상이나 어떤 형상도 만들지 말고, 그것들에게 절하거나 그것들을 섬기지 말라고 하셨다. 성경은 여기까지 말한다."},"refs":["왕하 17:10","왕하 17:12","왕하 17:16","출 20:4-5"]}],"help":{"who":"사마리아의 이스라엘 사람들","steps":[{"kind":"watch","after":2,"title":"멀리서 보기 · 사로잡혀 가는 이스라엘","basis":"왕하 17:6","text":{"t1":"앗수르 왕이 사마리아를 차지하고 이스라엘 사람들을 앗수르로 데려갔어요. 우리는 끼어들지 않고 멀리서 봐요.","t2":"이스라엘 사람들이 붙잡혀 앗수르로 끌려가요. 우리는 이 일에 끼어들지 않고, 사람들에게 다가가지 않은 채 멀리서 봐요.","t3":"사마리아는 앗수르 왕의 손에 들어갔고, 이스라엘 사람들은 붙잡혀 앗수르로 끌려가 여러 고을에 머물게 되었다. 탐험대는 이 일에 끼어들지 않고, 사람들에게 다가가지 않은 채 멀리서 본다. 이 일이 왜 일어났는지는 이어지는 본문이 말한다."},"say":{"who":"hyu","text":"사람들이 끌려간 곳의 이름은 6절에 있어. 우리는 멀리서 보기만 하자."}},{"kind":"do","after":6,"title":"멀리서 본 일을 일지에 정리하기","basis":"왕하 17:23","text":{"t1":"이스라엘이 고향을 떠나 앗수르로 사로잡혀 갔어요. 우리는 멀리서 본 일을 탐험 일지에 차례대로 정리했어요.","t2":"이스라엘은 고향을 떠나 앗수르로 사로잡혀 갔어요. 사로잡혀 가는 사람들의 일에는 우리가 끼어들지 않아요. 우리는 멀리서 본 일을 탐험 일지에 차례대로 정리하고, 성경이 그 까닭을 말하는 곳을 적어 두었어요. 성경에 적힌 일이 아니라 탐험대가 한 일이에요.","t3":"이스라엘은 고향을 떠나 앗수르로 사로잡혀 갔다(17:23). 사로잡혀 가는 사람들의 일에는 탐험대가 끼어들지 않는다. 탐험대는 멀리서 본 일을 일지에 차례대로 정리하고, 성경이 그 까닭을 말하는 장절을 적어 둔다. 성경에 적힌 일이 아니라 탐험대 이야기다."},"tasks":["멀리서 본 차례대로 일지에 적기","까닭을 읽을 곳 '열왕기하 17장 7~23절' 적어 두기","사람들에게 다가가지 않았는지 살피기"],"done":{"who":"hyu","text":"일지에 적었어. 왜 이런 일이 일어났는지는 성경이 말하는 만큼만 읽자."}},{"kind":"ask","after":"gates","title":"이스라엘이 사로잡혀 간 일은 무슨 뜻이에요?","basis":"왕하 17:7-23","by":"최현 박사","ask":{"who":"onwoo","text":"박사님, 이스라엘이 앗수르로 사로잡혀 간 일은 무슨 뜻이에요?"},"answer":{"t1":"성경은 이 일이, 이스라엘 자손이 자기들을 애굽에서 이끌어 내신 여호와께 죄를 짓고 다른 신들을 섬겼기 때문에 일어났다고 말해요(왕하 17:7). 여호와께서는 선지자들을 통해 돌이키라고 하셨지만, 그들은 듣지 않았어요(17:13-14).","t2":"성경은 이 일이, 이스라엘 자손이 애굽에서 이끌어 내신 하나님 여호와께 죄를 짓고 다른 신들을 받들었기 때문에 일어났다고 적어요(왕하 17:7). 여호와께서는 선지자와 선견자들을 통해 악한 길에서 돌이키라고 경계하셨지만, 그들은 듣지 않고 목을 굳게 했어요(17:13-14). 그래서 여호와께서 선지자들로 하신 말씀대로 그 앞에서 이스라엘을 제하셨다고 적어요(17:23).","t3":"성경은 이 일이, 이스라엘 자손이 자기들을 애굽에서 이끌어 내신 하나님 여호와께 죄를 짓고 다른 신들을 받들었기 때문에 일어났다고 적는다(왕하 17:7). 여호와께서는 모든 선지자와 선견자를 통해 악한 길에서 돌이키라고 경계하셨으나, 그들은 듣지 않고 조상들처럼 목을 굳게 했다(17:13-14). 그래서 여호와께서 그 종 선지자들로 하신 말씀대로 그 앞에서 이스라엘을 제하셨다(17:23). 성경은 여기까지 말한다."},"read":{"t1":{"type":"find","ref":"왕하 17:14","prompt":"성경책에서 열왕기하 17장 14절을 찾아 읽어 보세요.","confirm":{"prompt":"이스라엘 자손은 말씀을 듣지 않고 누구처럼 목을 굳게 했나요?","options":[{"label":"여호와를 모르던 애굽 사람들","basis":"본문에 없음"},{"label":"여호와를 믿지 않던 조상들","ok":true},{"label":"둘레에 살던 다른 나라 사람들","basis":"왕하 17:15"}]}},"t2":{"type":"find","ref":"왕하 17:21-23","prompt":"성경책에서 열왕기하 17장 21절부터 23절까지 읽어 보세요.","confirm":{"prompt":"성경은 이스라엘이 여호와 앞에서 쫓겨난 일이 무엇 때문이라고 말하나요?","options":[{"label":"백성이 여로보암을 버리고 다시 다윗의 집으로 돌아가 그 왕을 따랐기 때문이라고","basis":"본문에 없음"},{"label":"여로보암이 지은 성읍들을 백성이 버리고 저마다 다른 땅으로 흩어졌기 때문이라고","basis":"본문에 없음"},{"label":"여로보암이 지은 죄들을 백성이 그대로 따라 하며 거기서 떠나지 않았기 때문이라고","ok":true}]}},"t3":{"type":"find","refs":["왕하 17:7","왕하 17:23"],"prompt":"열왕기하 17장 7절과 23절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 이스라엘이 사로잡혀 간 일을 성경은 어떻게 말하는가?","options":[{"label":"이스라엘 자손이 애굽에서 이끌어 내신 여호와께 죄를 짓고 다른 신들을 받들었기 때문에 이 일이 일어났고, 여호와께서는 그 종 선지자들로 하신 말씀대로 그 앞에서 이스라엘을 제하셨다","ok":true},{"label":"이스라엘 자손이 애굽으로 다시 돌아가려 했기 때문에 이 일이 일어났고, 여호와께서는 그 종 선지자들로 하신 말씀대로 그 앞에서 이스라엘을 제하셨다","basis":"본문에 없음"},{"label":"이스라엘 자손이 애굽에서 이끌어 내신 여호와께 죄를 짓고 다른 신들을 받들었기 때문에 이 일이 일어났고, 여호와께서는 앗수르 왕이 청한 대로 그 앞에서 이스라엘을 제하셨다","basis":"본문에 없음"}]}}}}]}},"has3d":false,"epic":false},"OT-33":{"id":"OT-33","era":9,"title":"히스기야의 기도와 앗수르","ref":"왕하 18:13-19:37","place":"예루살렘, 여호와의 전","review":{"required":true,"topics":["재앙과 심판(왕하 19:7, 19:28, 19:35-37)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"왕하 18:13-16","focus":"hezekiah","text":{"t1":"히스기야 왕 때에 앗수르 왕 산헤립이 쳐들어와서 유다의 튼튼한 성읍들을 빼앗았어요. 히스기야는 앗수르 왕에게 은과 금을 주었어요.","t2":"히스기야 왕 제십사년, 앗수르의 왕 산헤립이 올라와서 유다의 튼튼한 성읍들을 빼앗았어요. 히스기야는 라기스에 있는 앗수르 왕에게 사람을 보내어, 떠나 돌아가 달라고 하며 왕이 지우는 것을 감당하겠다고 했어요. 앗수르 왕은 은 삼백 달란트와 금 삼십 달란트를 내라고 했고, 히스기야는 여호와의 전과 왕궁 곳간의 은을 다 주었어요.","t3":"히스기야 왕 제십사년, 앗수르의 왕 산헤립이 올라와서 유다의 견고한 성읍들을 모두 쳐서 빼앗았다. 유다 왕 히스기야는 라기스로 사람을 보내어, 자기가 잘못했다고 하며 떠나 돌아가 달라고, 왕이 지우는 것을 감당하겠다고 했다. 앗수르 왕은 은 삼백 달란트와 금 삼십 달란트를 정했다. 히스기야는 여호와의 전에 있던 은과 왕궁 곳간의 은을 모두 내주었고, 여호와의 전 문에서 벗긴 금과 자기가 기둥들에 입혔던 금까지 주었다."},"say":{"who":"hyu","text":"히스기야 왕 십사년, 앗수르 왕의 이름은 산헤립. 일지에 적어 둘게."}},{"ref":"왕하 18:17-25","focus":"rabshakeh","text":{"t1":"앗수르 왕은 큰 군대를 예루살렘으로 보냈어요. 앗수르 왕이 보낸 랍사게는 히스기야가 무엇을 믿고 있느냐고 물었어요.","t2":"앗수르 왕은 다르단과 랍사리스와 랍사게를 큰 군대와 함께 라기스에서 예루살렘으로 보냈어요. 그들은 윗못 수도 곁, 세탁자의 밭에 있는 큰 길에 섰어요. 엘리야김과 셉나와 요아가 그들에게 나가자, 랍사게는 히스기야가 누구를 믿고 앗수르 왕을 거역하느냐고 물었어요.","t3":"앗수르 왕은 다르단과 랍사리스와 랍사게를 큰 군대와 함께 라기스에서 예루살렘으로 보내어 히스기야 왕을 치게 했다. 그들은 윗못 수도 곁, 세탁자의 밭에 있는 큰 길에 이르러 섰고, 왕을 부르자 힐기야의 아들 엘리야김, 서기관 셉나, 아삽의 아들인 사관 요아가 나갔다. 랍사게는 앗수르 왕의 말이라며, 히스기야가 누구를 믿고 거역하느냐고 물었다. 애굽을 믿는 것은 상한 갈대 지팡이에 기대는 것과 같다고 했고, 여호와를 믿는다고 하겠지만 히스기야가 그 산당과 제단을 없애지 않았느냐고 했다."},"say":{"who":"choeon","text":"큰 군대가 예루살렘 앞 큰 길에 와서 섰어. 성에서 세 사람이 나갔어."}},{"ref":"왕하 18:26-37","focus":"wall","text":{"t1":"랍사게는 성 위의 백성이 다 듣도록 유다 말로 크게 외치며, 여호와께서 건지신다는 히스기야의 말에 귀 기울이지 말라고 했어요. 백성은 한 마디도 대답하지 않았어요.","t2":"엘리야김과 셉나와 요아는 성 위의 백성이 듣지 않도록 아람 말로 해 달라고 했어요. 그러나 랍사게는 일어서서 유다 말로 크게 외쳤어요. 히스기야에게 속지 말고, 여호와께서 건지신다는 말도 듣지 말라고 했어요. 백성은 잠잠했는데, 왜 한 마디도 대답하지 않았는지는 36절에서 찾아봐요.","t3":"엘리야김과 셉나와 요아는 자기들이 알아들으니 아람 말로 하고, 성 위에 있는 백성이 듣는 데서 유다 말로 하지 말아 달라고 했다. 그러나 랍사게는 일어서서 유다 말로 크게 외쳤다. 히스기야에게 속지 말고 앗수르 왕에게 항복하고 나오라고 했고, 여러 나라의 신들 가운데 누가 자기 땅을 앗수르 왕에게서 건졌느냐고 했다. 그가 여호와와 이 성을 두고 무엇이라고 했는지는 30절과 35절에 있다. 백성은 잠잠하여 한 마디도 대답하지 않았는데, 왕이 대답하지 말라고 명했기 때문이다. 세 사람은 옷을 찢고 히스기야에게 가서 랍사게의 말을 전했다."},"say":{"who":"choeon","text":"저 사람이 크게 외치는데 성 위의 사람들은 아무 대답도 안 해."}},{"ref":"왕하 19:1-7","open":"왕하 19:6","focus":"isaiah","text":{"t1":"히스기야 왕이 그 말을 듣고 무엇을 했는지는 성경에서 찾아봐요. 왕이 보낸 사람들에게 선지자 이사야는 여호와께서 두려워하지 말라고 하셨다고 전했어요.","t2":"히스기야 왕은 그 말을 듣고 옷을 찢고, 굵은 베를 두르고 여호와의 전으로 들어갔어요. 엘리야김과 셉나와 제사장들 가운데 장로들을 아모스의 아들인 선지자 이사야에게 보내어, 남아 있는 사람들을 위해 기도해 달라고 했어요. 이사야는 여호와의 말씀을 전했어요. 여호와께서는 앗수르 왕의 신하들에게 들은 말 때문에 두려워하지 말라고 하셨고, 앗수르 왕을 자기 나라로 돌아가게 하겠다고 하셨어요.","t3":"히스기야 왕은 듣고 옷을 찢고, 굵은 베를 두르고 여호와의 전으로 들어갔다. 엘리야김과 셉나와 제사장들 가운데 장로들에게 굵은 베를 입혀 아모스의 아들인 선지자 이사야에게 보내어, 랍사게가 살아 계신 하나님을 훼방했으니 남아 있는 사람들을 위해 기도해 달라고 했다. 이사야는 여호와의 말씀을 전했다. 여호와께서는 앗수르 왕의 신하들이 여호와를 능욕한 말 때문에 두려워하지 말라고 하셨다. 또 앗수르 왕이 풍문을 듣고 자기 나라로 돌아가게 하고, 그 나라에서 칼에 죽게 하겠다고 하셨다."},"say":{"who":"onwoo","text":"이사야가 전한 여호와의 말씀은 19장 6절과 7절에 있어. 성경책에서 직접 읽어 보자."}},{"ref":"왕하 19:8-19","open":"왕하 19:15","focus":"letter","text":{"t1":"앗수르 왕이 다시 사람을 보내 편지를 전했어요. 히스기야는 여호와의 전에 올라가 그 편지를 여호와 앞에 펼쳐 놓고 기도했어요.","t2":"앗수르 왕은 다시 히스기야에게 사자들을 보내어, 히스기야가 믿는 하나님이 예루살렘을 앗수르 왕에게 넘기지 않으신다는 말에 속지 말라고 했어요. 히스기야는 편지를 받아 읽고 여호와의 전에 올라가서 그것을 여호와 앞에 펴 놓았어요. 그리고 여호와만 홀로 하나님이시라고 아뢰며, 앗수르 왕의 손에서 구원해 달라고 기도했어요.","t3":"랍사게는 돌아가 립나에서 싸우고 있는 앗수르 왕을 만났다. 앗수르 왕은 구스 왕 디르하가가 싸우러 나온다는 말을 듣고 다시 히스기야에게 사자들을 보내어, 네가 믿는 하나님이 예루살렘을 넘겨주지 않는다는 말에 속지 말라고 했다. 히스기야는 사자의 손에서 편지를 받아 읽고 여호와의 전에 올라가 그것을 여호와 앞에 펴 놓고 기도했다. 그는 여호와만 천하 만국에 홀로 하나님이시며 하늘과 땅을 지으신 분이라고 아뢰었다. 앗수르 왕들이 불에 던진 여러 나라의 신들은 사람의 손으로 만든 나무와 돌일 뿐이라고 했다. 그리고 이제 구원해 주셔서 천하 만국이 여호와만 홀로 하나님이신 줄 알게 해 달라고 구했다."},"say":{"who":"choeon","text":"왕이 편지를 들고 여호와의 전으로 올라갔어. 편지를 펴 놓고 기도해."}},{"ref":"왕하 19:20-34","open":"왕하 19:34","focus":"isaiah","text":{"t1":"이사야는 여호와께서 히스기야의 기도를 들으셨다고 전했어요. 여호와께서는 앗수르 왕이 이 성에 이르지 못할 것이며, 이 성을 지켜 구원하겠다고 하셨어요.","t2":"아모스의 아들인 선지자 이사야가 히스기야 왕에게 여호와의 말씀을 전했어요. 여호와께서는 히스기야가 앗수르 왕 산헤립 때문에 드린 기도를 들었다고 하셨어요. 앗수르 왕은 이 성에 이르지 못하고 화살도 쏘지 못한 채 오던 길로 돌아갈 것이라고 하셨어요. 여호와께서 이 성을 보호하여 구원하겠다고 하셨어요.","t3":"아모스의 아들인 이사야가 히스기야 왕에게 사람을 보내어 이스라엘의 하나님 여호와의 말씀을 전했다. 여호와께서는 히스기야가 앗수르 왕 산헤립 때문에 드린 기도를 들었다고 하셨고, 앗수르 왕을 오던 길로 돌이키겠다고 하셨다. 앗수르 왕은 이 성에 이르지 못하고, 화살을 쏘지도 방패를 세우지도 토성을 쌓지도 못한 채 오던 길로 돌아갈 것이라고 하셨다. 앗수르 왕이 누구를 훼방했다고 하셨는지, 이 성을 두고 마지막에 무엇이라고 하셨는지는 22절과 34절에서 직접 읽어 보자."},"say":{"who":"onwoo","text":"여호와께서 이 성을 두고 하신 말씀은 32절부터 34절에 있어. 우리가 지어내지 말고 성경책에서 읽자."}},{"ref":"왕하 19:35-37","focus":"camp","text":{"t1":"그날 밤, 여호와의 사자가 앗수르 군대의 진을 쳤어요. 앗수르 왕 산헤립은 떠나서 니느웨로 돌아갔어요.","t2":"그날 밤, 여호와의 사자가 나와, 앗수르 진에 있던 군사 십팔만 오천 명을 쳤어요. 아침 일찍 일어나 보니 그들은 모두 죽어 있었어요. 앗수르 왕 산헤립은 떠나 돌아가서 니느웨에 머물렀어요.","t3":"그날 밤, 여호와의 사자가 나와, 앗수르 진에 있던 군사 십팔만 오천 명을 쳤다. 아침 일찍 일어나 보니 그들은 모두 죽어 있었다. 앗수르 왕 산헤립은 떠나 돌아가서 니느웨에 머물렀다. 그가 자기 신 니스록에게 경배하고 있을 때 아드람멜렉과 사레셀이 그를 칼로 쳐 죽이고 아라랏 땅으로 달아났고, 그의 아들 에살핫돈이 뒤를 이어 왕이 되었다."},"say":{"who":"hyu","text":"밤에 일어난 일이고, 산헤립이 돌아간 곳은 니느웨야. 순서대로 적어 둘게."}}],"gates":{"t1":[{"type":"find","ref":"왕하 18:14","prompt":"성경책에서 열왕기하 18장 14절을 찾아 읽어 보세요.","confirm":{"prompt":"히스기야 왕이 앗수르 왕에게 사람을 보낸 곳은 어디였나요?","options":[{"label":"라기스","ok":true},{"label":"립나","basis":"왕하 19:8"},{"label":"니느웨","basis":"왕하 19:36"}]}},{"type":"multi","ref":"왕하 19:1","prompt":"성경책에서 열왕기하 19장 1절을 찾아 읽어 보세요.","confirm":{"prompt":"히스기야 왕이 랍사게의 말을 전해 듣고 한 일을 모두 고르세요.","options":[{"label":"옷을 찢었어요","ok":true},{"label":"굵은 베를 입었어요","ok":true},{"label":"편지를 여호와 앞에 펼쳐 두었어요","basis":"왕하 19:14"},{"label":"여호와의 전에 들어갔어요","ok":true},{"label":"성 위에 올라가 랍사게에게 대답했어요","basis":"본문에 없음"}]}}],"t2":[{"type":"find","ref":"왕하 18:28-36","prompt":"성경책에서 열왕기하 18장 28절부터 36절까지 읽어 보세요.","confirm":{"prompt":"랍사게가 유다 말로 크게 외칠 때, 성 위의 백성이 한 마디도 대답하지 않은 까닭은 무엇인가요?","options":[{"label":"왕이 대답하지 말라고 명령했기 때문에","ok":true},{"label":"랍사게의 말을 알아듣지 못했기 때문에","basis":"본문에 없음"},{"label":"모두 성 안 깊은 곳에 숨어 있었기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"왕하 19:8-15","prompt":"성경책에서 열왕기하 19장 8절부터 15절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["랍사게가 립나에서 싸우고 있는 앗수르 왕을 만났다","구스 왕 디르하가가 싸우러 나온다는 소식이 앗수르 왕에게 들렸다","앗수르 왕이 사자들을 다시 보내 히스기야에게 말을 전하게 했다","히스기야가 사자에게서 편지를 받아 읽었다","히스기야는 그 편지를 펴 놓고 여호와께 기도했다"]}],"t3":[{"type":"find","refs":["왕하 18:30","왕하 19:10","왕하 19:34"],"prompt":"열왕기하 18장 30절, 19장 10절, 19장 34절을 함께 찾아 읽어 보자.","confirm":{"prompt":"랍사게의 말과 앗수르 왕의 편지, 그리고 이사야가 전한 여호와의 말씀을 이어 읽으면 무엇이 보이는가?","options":[{"label":"앗수르 쪽은 여호와께서 이 성을 건지신다는 말을 듣지 말고, 하나님이 이 성을 넘기지 않으신다는 말에 속지 말라고 했지만, 여호와께서는 이 성을 지켜 구원하시겠다고 하셨다","ok":true},{"label":"앗수르 쪽은 여호와께서 건지신다는 말을 듣지 말고 하나님의 말에 속지 말라고 했지만, 여호와께서는 애굽 왕의 군대를 보내어 이 성을 지키게 하시겠다고 하셨다","basis":"본문에 없음"},{"label":"랍사게는 여호와께서 건지신다는 말은 옳지만 히스기야는 믿지 말라고 했고, 앗수르 왕의 편지는 하나님의 말에 속지 말라고 했으며, 여호와께서는 이 성을 지켜 구원하시겠다고 하셨다","basis":"본문에 없음"}]}},{"type":"match","refs":["왕하 18:14","왕하 18:17","왕하 19:33","왕하 19:36"],"prompt":"열왕기하 18장 14절, 17절, 19장 33절, 36절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"왕하 18:14","text":"히스기야가 앗수르 왕에게 떠나 돌아가 달라고 청했다"},{"ref":"왕하 18:17","text":"앗수르 왕이 큰 군대를 라기스에서 예루살렘으로 보냈다"},{"ref":"왕하 19:33","text":"여호와께서 앗수르 왕이 이 성에 이르지 못하고 오던 길로 돌아가리라고 하셨다"},{"ref":"왕하 19:36","text":"산헤립은 니느웨로 돌아가 거기 머물렀다"}],"after":"네 곳을 이으면, 히스기야가 떠나 달라고 청한 뒤에도 앗수르 왕은 큰 군대를 보냈지만, 여호와께서는 그가 오던 길로 돌아가리라고 하셨고 산헤립은 니느웨로 돌아갔다."}]},"cards":[{"ref":"왕하 19:15","title":"홀로 하나님이신 여호와"},{"ref":"왕하 19:34","title":"이 성을 보호하여 구원하시겠다는 말씀"}],"close":{"t1":{"kind":"prayer","text":"하나님, 히스기야가 편지를 하나님 앞에 펴 놓고 기도한 이야기를 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 열왕기하 19장 14절부터 19절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"왕하 18:13-19:37에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"여기는 예루살렘이에요. 비상 착륙하면서 냉각수가 다 새어 버렸어요. 기계를 식힐 물을 구해 주세요.","t2":"타임머신이 유다의 예루살렘 가까이에 비상 착륙했어요. 냉각수가 새어 나가서 기계가 뜨거워지고 있어요. 이 시대에는 냉각수가 없으니, 그곳에서 구할 수 있는 물로 대신 채워야 해요.","t3":"타임머신은 예루살렘 가까이에 비상 착륙했다. 냉각수가 새어 나가 기관이 달아오르고 있다. 이 시대에는 냉각수가 없으니 그곳에서 얻을 수 있는 물로 대신 채워야 한다. 성 위의 백성 곁에서 거들 일이 있어도, 왕과 신하들과 군사들의 일에는 끼어들지 말고 지켜보아야 한다."},"materials":[{"key":"poolwater","name":"윗못 물","basis":"왕하 18:17","use":"윗못 수도의 물을 냉각수 대신 쓸 수 있어요.","how":"앗수르 사람들이 서 있던 큰 길에서 멀리 떨어진 곳까지 수도를 따라가서, 흐르는 물을 가져간 빈 통에 조금 받았다. 다른 사람이 길어 둔 물에는 손대지 않았다.","line":"물을 받았어! 큰 길에서 멀리 떨어진 윗못 수도에서 떴어."}],"companion":{"who":"이사야","ref":"왕하 19:2","when":"after","talks":[{"ask":{"who":"choeon","text":"이사야 선지자님, 히스기야 왕이 보낸 사람들에게 뭐라고 전하셨어요?"},"answer":{"t1":"이사야는 여호와께서 앗수르 사람들이 한 말 때문에 두려워하지 말라고 하셨다고 전했어요.","t2":"이사야는 신하들에게, 그들의 주인에게 여호와의 말씀을 전하라고 했어요. 여호와께서 앗수르 왕의 신하들이 여호와를 욕한 말 때문에 두려워하지 말라고 하셨고, 앗수르 왕이 소문을 듣고 자기 나라로 돌아가게 하겠다고 하셨다고 전했어요.","t3":"이사야는 신하들에게, 그들의 주인에게 여호와의 말씀을 이렇게 알리라고 했다. 여호와께서는 앗수르 왕의 신하들이 여호와를 능욕한 말 때문에 두려워하지 말라고 하셨다. 또 앗수르 왕에게 한 영을 두어, 그가 풍문을 듣고 본국으로 돌아가게 하고 그 나라에서 칼에 쓰러지게 하겠다고 하셨다고 전했다."},"ref":"왕하 19:6-7","open":"왕하 19:6"},{"ask":{"who":"hyu","text":"히스기야 왕이 편지를 펴 놓고 기도한 다음에는 무엇을 전하셨어요?"},"answer":{"t1":"이사야는 여호와께서 히스기야의 기도를 들으셨다고 전했어요. 앗수르 왕은 이 성에 들어오지 못하고, 여호와께서 이 성을 지켜 구원하시겠다고 하셨다고 전했어요.","t2":"이사야는 히스기야에게 사람을 보내어, 여호와께서 산헤립 때문에 드린 기도를 들으셨다고 전했어요. 앗수르 왕은 이 성에 이르지 못하고 화살도 쏘지 못한 채 오던 길로 돌아갈 것이라고 하셨대요. 여호와께서 자신과 종 다윗을 위하여 이 성을 지켜 구원하시겠다고 하셨다고 전했어요.","t3":"이사야는 히스기야에게 기별하여, 이스라엘의 하나님 여호와께서 산헤립 때문에 드린 기도를 들으셨다고 전했다. 여호와께서는 앗수르 왕이 이 성에 이르지 못하고, 화살을 쏘지도 방패를 세우지도 토성을 쌓지도 못한 채 오던 길로 돌아가리라고 하셨다. 또 자신을 위하여, 그리고 자신의 종 다윗을 위하여 이 성을 지켜 구원하시겠다고 하셨다고 전했다."},"ref":"왕하 19:20-34","open":"왕하 19:34"},{"ask":{"who":"onwoo","text":"전하신 말씀 가운데 징조에 관한 것도 있었어요? 성경책에서 찾아보고 싶어요."},"answer":{"t1":"이사야는 여호와께서 징조를 말씀하셨다고 전했어요. 올해와 다음 해에는 저절로 난 것을 먹고, 셋째 해에는 심고 거두어 먹게 된다고 하셨대요.","t2":"이사야는 여호와께서 징조를 말씀하셨다고 전했어요. 올해에는 저절로 자라난 것을, 다음 해에는 거기서 다시 난 것을 먹고, 셋째 해에는 심고 거두며 포도원을 가꾸어 그 열매를 먹게 된다고 하셨어요. 또 유다 집안에서 피하여 남은 사람들이 다시 아래로 뿌리를 내리고 위로 열매를 맺을 것이라고 하셨다고 전했어요.","t3":"이사야는 여호와께서 보이실 징조를 말씀하셨다고 전했다. 그해에는 저절로 자라난 것을, 이듬해에는 거기서 다시 난 것을 먹고, 셋째 해에는 심고 거두며 포도원을 가꾸어 그 열매를 먹으리라는 것이었다. 또 유다 집안에서 피하여 남은 사람들이 다시 아래로 뿌리를 내리고 위로 열매를 맺을 것이며, 남은 사람들이 예루살렘과 시온 산에서 나올 것이라고 하셨다. 여호와의 열심이 이 일을 이루시리라고 하셨다고 전했다."},"ref":"왕하 19:29-31","open":"왕하 19:29"}]},"today":[{"q":"하나님은 사람이 드리는 기도를 들으세요?","a":{"t1":"이사야는 여호와께서 히스기야의 기도를 들으셨다고 전했어요. 히스기야가 병들었을 때에도 여호와께서 그의 기도를 들으셨다고 하셨어요.","t2":"열왕기하는 히스기야가 앗수르 왕의 편지를 여호와 앞에 펴 놓고 기도하자, 여호와께서 그 기도를 들으셨다는 말씀을 이사야가 전했다고 적어요. 히스기야가 병들었을 때에도 여호와께서는 그의 기도를 듣고 눈물을 보셨다고 하셨어요. 성경이 이 두 일에서 말하는 것은 여기까지예요.","t3":"열왕기하 19장에서 이사야는, 히스기야가 산헤립 때문에 드린 기도를 여호와께서 들으셨다는 말씀을 전했다. 20장에서도 여호와께서는 이사야를 다시 보내어, 병든 히스기야에게 그의 기도를 듣고 눈물을 보았으니 그를 낫게 하겠다고 하셨다. 이 두 본문은 히스기야의 기도에 대해 말한다. 성경은 여기까지 말한다."},"refs":["왕하 19:20","왕하 20:1","왕하 20:5"]},{"q":"사람이 나무나 돌로 만든 것도 신이 될 수 있어요?","a":{"t1":"히스기야는 기도하면서, 그런 신들은 신이 아니라 사람이 손으로 만든 나무와 돌이라고 아뢰었어요. 그리고 여호와는 하늘과 땅을 지으신 분이라고 아뢰었어요.","t2":"히스기야는 여호와께 기도하면서, 앗수르 왕들이 여러 나라의 신들을 불에 던져 없앤 것은 그것들이 신이 아니라 사람의 손으로 만든 나무와 돌이었기 때문이라고 아뢰었어요. 그리고 여호와만 천하 만국에 홀로 하나님이시며 하늘과 땅을 지으셨다고 아뢰었어요.","t3":"히스기야의 기도에 따르면, 앗수르 왕들이 여러 나라의 신들을 불에 던져 없앤 것은 그것들이 신이 아니고 사람의 손으로 만든 나무와 돌일 뿐이었기 때문이다. 히스기야는 여호와만 천하 만국에 홀로 하나님이시고 하늘과 땅을 지으신 분이라고 아뢰며, 천하 만국이 이것을 알게 해 달라고 구했다. 성경은 여기까지 말한다."},"refs":["왕하 19:15","왕하 19:18-19"]}],"help":{"who":"예루살렘 성 위의 백성","steps":[{"kind":"do","after":1,"title":"성 위의 백성 곁에서 자리 내어 주기","basis":"왕하 18:26","text":{"t1":"성 위에는 백성이 있어요. 성경에 적힌 일은 아니지만, 우리는 그 곁에서 사람들이 앉고 지나다닐 자리를 내어 주며 도와요.","t2":"앗수르 군대가 큰 길에 와 서 있고, 성 위에는 백성이 있어요. 이것은 성경에 적힌 일이 아니라 탐험대가 곁에서 거드는 일이에요. 우리는 백성이 앉고 지나다닐 자리를 내어 주며 조용히 도와요.","t3":"앗수르 군대가 윗못 수도 곁 큰 길에 와 서 있고, 성 위에는 백성이 있다(18:26). 탐험대는 그 곁에서 백성이 앉고 지나다닐 자리를 내어 주며 조용히 거든다. 본문에 적힌 일이 아니라 탐험대의 일이며, 왕의 신하들과 랍사게가 나누는 말에는 끼지 않는다."},"tasks":["지나다니는 사람에게 비켜서기","앉을 자리 내어 드리기","백성 곁에 조용히 서기"],"done":{"who":"hyu","text":"자리를 다 내어 드렸어. 이제 성 위 사람들 곁에 조용히 있자."}},{"kind":"stay","after":2,"title":"성 위에서 함께 잠잠히","basis":"왕하 18:36","text":{"t1":"랍사게가 성 위의 백성에게 유다 말로 크게 외쳤어요. 백성은 한 마디도 대답하지 않아요. 우리도 그들 곁에서 함께 잠잠히 있어요.","t2":"랍사게가 성 위의 백성이 다 듣도록 유다 말로 크게 외쳤어요. 백성은 잠잠하고 한 마디도 대답하지 않아요. 우리도 성 위의 백성 곁에서 아무 말도 하지 않고 함께 있어요.","t3":"랍사게는 성 위의 백성이 듣는 데서 유다 말로 크게 외쳤다(18:26-28). 백성은 잠잠했고 한 마디도 대답하지 않았다(18:36). 탐험대도 성 위의 백성 곁에서 아무 말 없이 함께 머문다."},"wait":"함께 잠잠히 있기","say":{"who":"choeon","text":"우리도 아무 말 안 할게. 성 위의 사람들 곁에 가만히 있자."}},{"kind":"watch","after":3,"title":"곁에서 보기 · 굵은 베를 입고 가는 사람들","basis":"왕하 19:2","text":{"t1":"엘리야김과 셉나와 제사장들 가운데 장로들이 굵은 베를 입고 선지자 이사야에게 가요. 히스기야 왕이 보낸 사람들이에요. 우리는 따라가지 않고 곁에서 봐요.","t2":"히스기야 왕은 엘리야김과 셉나와 제사장들 가운데 장로들을 굵은 베 차림으로 선지자 이사야에게 보냈어요. 이사야에게 왕의 말을 전하는 일은 왕이 보낸 사람들이 해요. 우리는 따라가지 않고 곁에서 봐요.","t3":"히스기야는 엘리야김과 서기관 셉나, 제사장 가운데 장로들을 굵은 베를 입힌 채 선지자 이사야에게 보냈다(19:2). 이사야에게 왕의 말을 전하는 일은 왕이 보낸 사람들의 일이다. 탐험대는 따라가지 않고 곁에서 본다."},"say":{"who":"hyu","text":"굵은 베를 입은 사람들이 이사야에게 갔어. 누가 갔는지 일지에 적어 둘게."}},{"kind":"ask","after":"gates","title":"성 위에서 들은 말의 뜻","basis":"왕하 19:21-28","by":"이사야","ask":{"who":"onwoo","text":"이사야 선지자님, 랍사게가 성 위의 사람들에게 외친 말은 하나님 앞에서 어떤 말이었어요?"},"answer":{"t1":"이사야는 여호와께서 앗수르 왕을 두고 하신 말씀을 전했어요. 앗수르 왕이 꾸짖고 훼방한 분은 이스라엘의 거룩하신 분이라고 하셨대요. 그 교만한 말이 여호와께 들렸으니 그를 오던 길로 돌려보내겠다고 하셨다고 전했어요.","t2":"이사야는 여호와께서 앗수르 왕을 두고 하신 말씀을 히스기야에게 전했어요. 앗수르 왕이 소리를 높여 꾸짖고 훼방한 상대는 이스라엘의 거룩하신 분이라고 하셨어요. 그리고 그가 여호와께 품은 분노와 교만한 말이 여호와의 귀에 들렸으니, 그를 오던 길로 돌려보내겠다고 하셨다고 전했어요.","t3":"이사야는 여호와께서 앗수르 왕을 두고 하신 말씀을 히스기야에게 전했다(19:20-21). 여호와께서는 앗수르 왕이 누구를 꾸짖고 훼방했으며 누구를 향해 소리를 높였느냐고 물으시고, 이스라엘의 거룩하신 분께 그리하였다고 하셨다(19:22). 또 그가 여호와께 품은 분노와 교만한 말이 여호와의 귀에 들렸으므로 그를 오던 길로 돌려보내겠다고 하셨다고 전했다(19:28)."},"read":{"t1":{"type":"find","ref":"왕하 19:22","prompt":"성경책에서 열왕기하 19장 22절을 찾아 읽어 보세요.","confirm":{"prompt":"앗수르 왕이 소리를 높여 훼방한 상대는 누구라고 하셨나요?","options":[{"label":"이스라엘의 거룩하신 분","ok":true},{"label":"구스 왕 디르하가","basis":"왕하 19:9"},{"label":"애굽 왕 바로","basis":"왕하 18:21"}]}},"t2":{"type":"find","ref":"왕하 19:27-28","prompt":"성경책에서 열왕기하 19장 27절과 28절을 읽어 보세요.","confirm":{"prompt":"여호와께서 앗수르 왕을 오던 길로 돌려보내겠다고 하신 까닭은 무엇인가요?","options":[{"label":"앗수르 왕이 여호와께 품은 분노와 교만한 말이 여호와의 귀에 들렸기 때문에","ok":true},{"label":"히스기야가 왕궁 곳간과 여호와의 전에 있던 은을 앗수르 왕에게 다 주었기 때문에","basis":"왕하 18:15"},{"label":"앗수르 왕이 예루살렘에 들어가 여호와의 전의 기구들을 모두 가져가려 했기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["왕하 18:35","왕하 19:4","왕하 19:22"],"prompt":"열왕기하 18장 35절, 19장 4절, 19장 22절을 함께 찾아 읽어 보자.","confirm":{"prompt":"세 곳을 이어 읽으면, 랍사게와 앗수르 왕의 말은 누구를 향한 것이었다고 성경은 말하는가?","options":[{"label":"랍사게는 여호와께서도 예루살렘을 건지지 못하신다고 했고, 히스기야는 그것을 살아 계신 하나님을 훼방한 말이라고 했으며, 여호와께서도 앗수르 왕이 이스라엘의 거룩하신 분을 훼방했다고 하셨다","ok":true},{"label":"랍사게는 예루살렘 백성이 히스기야를 믿고 버틸 수 없다고 했고, 히스기야는 그것을 살아 계신 하나님을 훼방한 말이라고 했으며, 여호와께서는 앗수르 왕이 시온의 백성을 업신여겼다고 하셨다","basis":"본문에 없음"},{"label":"랍사게는 여호와께서도 예루살렘을 건지지 못하신다고 했고, 히스기야는 그것을 살아 계신 하나님을 훼방한 말이라고 했으며, 여호와께서는 앗수르 왕이 유다 왕 히스기야를 꾸짖었다고 하셨다","basis":"본문에 없음"}]}}}}]}},"has3d":false,"epic":false},"OT-34":{"id":"OT-34","era":9,"title":"요시야와 율법책","ref":"왕하 22:1-23:3","place":"예루살렘, 여호와의 전","review":{"required":false,"topics":[],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"왕하 22:1-2","focus":"josiah","text":{"t1":"요시야가 왕이 되어 예루살렘을 다스렸어요. 요시야는 여호와께서 보시기에 바르게 행했어요.","t2":"요시야는 여덟 살에 왕이 되어 예루살렘에서 삼십일 년 동안 다스렸어요. 그는 여호와께서 보시기에 바르게 행했고, 조상 다윗의 길을 따라 걸으며 왼쪽으로도 오른쪽으로도 치우치지 않았어요.","t3":"요시야는 여덟 살에 왕위에 올라 예루살렘에서 삼십일 년 동안 다스렸다. 어머니의 이름은 여디다로, 보스갓 사람 아다야의 딸이다. 요시야는 여호와께서 보시기에 바르게 행했고, 조상 다윗이 걸은 모든 길을 따르며 왼쪽으로도 오른쪽으로도 치우치지 않았다."},"say":{"who":"hyu","text":"여기는 예루살렘이야. 요시야가 몇 살에 왕이 되었는지 1절에서 찾아서 일지에 적자."}},{"ref":"왕하 22:3-7","focus":"temple","text":{"t1":"요시야 왕은 서기관 사반을 여호와의 전에 보냈어요. 백성이 드린 은을 일꾼들에게 주어 여호와의 전의 낡은 곳을 고치게 했어요.","t2":"요시야 왕 십팔년에 왕은 서기관 사반을 여호와의 전에 보냈어요. 대제사장 힐기야에게 가서 백성이 여호와의 전에 드린 은을 세어, 일을 감독하는 사람들에게 맡기라고 했어요. 그 은을 목수와 건축자와 미장이에게 주고, 나무와 다듬은 돌을 사서 여호와의 전을 고치게 했어요.","t3":"요시야 왕 십팔년에 왕은 므술람의 손자요 아살리야의 아들인 서기관 사반을 여호와의 전에 보냈다. 대제사장 힐기야에게 올라가서, 문을 지키는 사람들이 백성에게서 거둔 은을 세어 여호와의 전의 일을 감독하는 사람들에게 맡기라고 했다. 그 은을 목수와 건축자와 미장이에게 주고, 나무와 다듬은 돌을 사서 전의 낡은 곳을 고치게 하라는 것이었다. 맡긴 은은 따로 셈하지 않았는데, 그들이 진실하게 일했기 때문이다."},"say":{"who":"choeon","text":"여호와의 전에서 일하는 일꾼들이 있어. 어떤 일꾼들인지는 6절에서 찾아보자."}},{"ref":"왕하 22:8-10","focus":"book","text":{"t1":"대제사장 힐기야가 율법책을 여호와의 전에서 찾았어요. 힐기야는 그 책을 사반에게 주었고, 사반은 왕 앞에서 그 책을 읽었어요.","t2":"대제사장 힐기야는 서기관 사반에게, 여호와의 전에서 율법책을 발견했다고 말하고 그 책을 주었어요. 사반은 왕에게 돌아갔어요. 사반이 왕에게 무엇을 어떤 차례로 했는지는 9절과 10절에서 읽어 봐요.","t3":"대제사장 힐기야는 서기관 사반에게, 자기가 여호와의 전에서 율법책을 발견했다고 말하고 그 책을 건넸다. 사반은 왕에게 돌아가, 왕의 신하들이 전에 있던 은을 쏟아 일을 감독하는 사람들에게 넘겼다고 보고했고, 제사장 힐기야가 자기에게 책을 주었다고 알렸다. 그 책이 처음에 누구 손에서, 그 뒤에는 누구 앞에서 읽혔는지는 8절과 10절에 있다."},"say":{"who":"choeon","text":"힐기야가 책을 사반에게 건넸어. 사반이 그 책을 가지고 왕에게 가."}},{"ref":"왕하 22:11-13","focus":"josiah","text":{"t1":"왕은 율법책의 말을 듣자 곧 자기 옷을 찢었어요. 그리고 힐기야와 신하들에게, 이 책에 적힌 말씀을 두고 여호와께 여쭈어 보라고 했어요.","t2":"왕은 율법책의 말을 듣자 곧 자기 옷을 찢었어요. 왕은 제사장 힐기야와 아히감과 악볼과 서기관 사반과 아사야에게, 자기와 백성과 온 유다를 위하여 이 책의 말씀에 대하여 여호와께 여쭈어 보라고 했어요. 왕은 여호와의 진노가 크다고 했는데, 그 까닭은 13절에서 찾아봐요.","t3":"왕은 율법책의 말을 듣자 곧 자기 옷을 찢었다. 왕은 제사장 힐기야와 사반의 아들 아히감, 미가야의 아들 악볼, 서기관 사반, 그리고 아사야에게 명했다. 가서 자기와 백성과 온 유다를 위하여, 발견한 이 책의 말씀에 대하여 여호와께 여쭈어 보라는 것이었다. 왕은 여호와께서 내리신 진노가 크다고 말했는데, 그 까닭은 13절에 있다."},"say":{"who":"hyu","text":"왕이 옷을 찢었어. 일지에 적어 둘게."}},{"ref":"왕하 22:14-17","open":"왕하 22:16","focus":"huldah","text":{"t1":"힐기야와 신하들은 예루살렘에 사는 여선지 훌다에게 갔어요. 훌다는 여호와께서 그 책에 적힌 말대로 이곳에 재앙을 내리겠다고 하셨다고 전했어요.","t2":"힐기야와 아히감과 악볼과 사반과 아사야는 여선지 훌다에게 갔어요. 훌다는 살룸의 아내이고 예루살렘 둘째 구역에 살았어요. 훌다는 여호와의 말씀을 전했는데, 여호와께서는 유다 왕이 읽은 책의 모든 말대로 이곳과 여기 사는 사람들에게 재앙을 내리겠다고 하셨어요. 이 백성이 여호와를 버리고 다른 신에게 분향했기 때문이라고 하셨어요.","t3":"제사장 힐기야와 아히감과 악볼과 사반과 아사야는 여선지 훌다에게 가서 이야기했다. 훌다는 예복을 맡은 살룸의 아내인데, 살룸은 할하스의 손자요 디과의 아들이다. 훌다는 예루살렘 둘째 구역에 살았다. 훌다는 이스라엘의 하나님 여호와의 말씀을 전했다. 여호와께서는 유다 왕이 읽은 책의 모든 말대로 이곳과 여기 사는 사람들에게 재앙을 내리겠다고 하셨다. 이 백성이 여호와를 버리고 다른 신에게 분향하며 자기들 손으로 한 모든 일로 여호와를 노엽게 했기 때문이며, 이곳을 향한 진노가 꺼지지 않을 것이라고 하셨다."},"say":{"who":"onwoo","text":"훌다가 전한 여호와의 말씀은 16절과 17절에 있어. 지어내지 말고 성경책에서 직접 읽어 보자."}},{"ref":"왕하 22:18-20","open":"왕하 22:19","focus":"huldah","text":{"t1":"여호와께서는 요시야 왕에게도 말씀을 주셨어요. 왕이 그 말을 듣고 여호와 앞에서 자기를 낮추고 옷을 찢고 울었으므로, 여호와께서도 왕의 말을 들었다고 하셨어요.","t2":"훌다는 여호와께 여쭈라고 사람들을 보낸 유다 왕에게 주시는 말씀도 전했어요. 왕이 이곳에 대한 말을 듣고 마음이 부드러워져 여호와 앞에서 자기를 낮추고 옷을 찢고 울었으므로, 여호와께서도 왕의 말을 들었다고 하셨어요. 왕은 이곳에 내릴 재앙을 눈으로 보지 않을 것이라고 하셨어요. 사람들은 돌아가 왕에게 그대로 알렸어요.","t3":"훌다는 여호와께 여쭈라고 그들을 보낸 유다 왕에게 주시는 말씀도 전했다. 이곳과 여기 사는 사람들이 빈 터가 되고 저주가 되리라는 말을 왕이 듣고, 마음이 부드러워져 여호와 앞에서 자기를 낮추고 옷을 찢고 통곡했으므로 여호와께서도 왕의 말을 들었다고 하셨다. 그러므로 왕은 조상들에게 돌아가 평안히 묘실에 들어갈 것이며, 이곳에 내릴 모든 재앙을 눈으로 보지 않을 것이라고 하셨다. 보냄을 받은 사람들은 왕에게 돌아가 그대로 보고했다."},"say":{"who":"onwoo","text":"왕에게 주신 말씀은 19절과 20절이야. 같이 찾아서 읽어 보자."}},{"ref":"왕하 23:1-3","focus":"covenant","text":{"t1":"왕은 모든 백성과 함께 여호와의 전에 올라가 언약책의 말씀을 읽어 들려주었어요. 그리고 왕이 여호와 앞에 언약을 세웠고, 백성도 다 그 언약을 따르기로 했어요.","t2":"왕은 유다와 예루살렘의 모든 장로를 모았어요. 그리고 유다 사람들과 예루살렘 주민과 제사장들과 선지자들, 어린 사람부터 나이 든 사람까지 모든 백성과 함께 여호와의 전에 올라갔어요. 왕은 여호와의 전에서 찾아낸 언약책의 말씀을 모두 읽어 들려주었어요. 왕은 대 위에 서서 마음을 다해 여호와를 따르고 그 계명을 지키겠다고 여호와 앞에서 언약을 세웠고, 백성도 다 그 언약을 따르기로 했어요.","t3":"왕은 사람을 보내어 유다와 예루살렘의 장로들을 모두 자기 앞으로 불러 모았다. 왕이 여호와의 전에 올라갈 때 유다 사람들과 예루살렘 주민, 제사장들과 선지자들, 어린 사람부터 나이 든 사람까지 모든 백성이 함께했다. 왕은 여호와의 전에서 찾아낸 언약책의 말씀을 모두 읽어 그들에게 들려주었다. 왕은 대 위에 선 채 언약을 여호와 앞에서 세웠고, 백성도 다 그 언약을 따르기로 했다. 그 언약이 무엇을 하겠다는 것이었는지는 3절에서 직접 읽어 보자."},"say":{"who":"choeon","text":"어린 사람도 어른도 다 모였어. 왕이 책을 읽어 준 다음 대 위에 서서 언약을 세우고 있어."}}],"gates":{"t1":[{"type":"find","ref":"왕하 22:1","prompt":"성경책에서 열왕기하 22장 1절을 찾아 읽어 보세요.","confirm":{"prompt":"요시야는 몇 살에 왕이 되었나요?","options":[{"label":"여덟 살","ok":true},{"label":"열두 살","basis":"왕하 21:1"},{"label":"서른 살","basis":"삼하 5:4"}]}},{"type":"multi","ref":"왕하 22:6","prompt":"성경책에서 열왕기하 22장 6절을 찾아 읽어 보세요.","confirm":{"prompt":"여호와의 전을 고치도록 은을 받을 사람을 모두 고르세요.","options":[{"label":"목수","ok":true},{"label":"문을 지키는 사람","basis":"왕하 22:4"},{"label":"건축자","ok":true},{"label":"군사","basis":"본문에 없음"},{"label":"미장이","ok":true}]}}],"t2":[{"type":"find","ref":"왕하 22:3-7","prompt":"성경책에서 열왕기하 22장 3절부터 7절까지 읽어 보세요.","confirm":{"prompt":"여호와의 전을 고치는 일을 맡은 사람들에게 넘긴 은을 따로 셈하지 않은 까닭은 무엇인가요?","options":[{"label":"그들이 진실하게 일했기 때문에","ok":true},{"label":"은이 너무 많아 셀 수 없었기 때문에","basis":"본문에 없음"},{"label":"왕이 일을 서둘러 마치라고 명했기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"왕하 22:8-13","prompt":"성경책에서 열왕기하 22장 8절부터 13절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["힐기야가 율법책을 발견했다며 사반에게 건넸다","사반이 왕에게 돌아가 은을 넘긴 일을 알렸다","사반이 왕 앞에서 그 책을 읽었다","왕이 책의 말을 듣고 옷을 찢었다","왕이 신하들에게 여호와께 여쭈어 보라고 명했다"]}],"t3":[{"type":"find","refs":["왕하 22:8","왕하 22:10","왕하 23:2"],"prompt":"열왕기하 22장 8절, 10절, 23장 2절을 함께 찾아 읽어 보자.","confirm":{"prompt":"세 곳을 이어 읽으면, 여호와의 전에서 발견된 책의 말씀은 누구에게까지 읽혔는가?","options":[{"label":"서기관 사반이 먼저 읽었고, 다음에 왕 앞에서 읽혔으며, 끝에는 왕이 여호와의 전에 함께 올라간 모든 백성에게 읽어 들려주었다","ok":true},{"label":"서기관 사반은 책을 읽지 않고 왕에게 가져갔고, 왕이 혼자 그 책을 읽었으며, 끝에는 왕이 함께 올라간 모든 백성에게 읽어 들려주었다","basis":"본문에 없음"},{"label":"서기관 사반이 먼저 읽었고, 다음에 여선지 훌다의 집에서 읽혔으며, 끝에는 왕이 함께 올라간 모든 백성에게 읽어 들려주었다","basis":"본문에 없음"}]}},{"type":"match","refs":["왕하 22:3","왕하 22:14","왕하 23:1"],"prompt":"열왕기하 22장 3절, 14절, 23장 1절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"왕하 22:3","text":"왕이 서기관 사반에게 여호와의 전에 가라고 했다"},{"ref":"왕하 22:14","text":"왕이 보낸 다섯 사람이 여선지 훌다를 찾아갔다"},{"ref":"왕하 23:1","text":"왕이 사람을 보내 장로들을 모두 자기에게 불러 모았다"}],"after":"세 곳을 이으면, 왕은 처음에 사반을 여호와의 전으로 보냈고, 책의 말씀을 들은 뒤에는 사람들을 훌다에게 보내 여쭈었으며, 그 뒤에 장로들을 불러 모았다."}]},"cards":[{"ref":"왕하 22:2","title":"좌우로 치우치지 않은 왕"},{"ref":"왕하 23:3","title":"마음을 다하고 성품을 다하여"}],"close":{"t1":{"kind":"prayer","text":"하나님, 요시야 왕이 율법책의 말씀을 들은 이야기를 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 열왕기하 23장 1절부터 3절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"왕하 22:1-23:3에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"여기는 예루살렘이에요. 부속을 꽉 끼워 두던 쐐기가 빠져서 기계가 흔들려요. 쐐기 대신 쓸 단단한 조각을 찾아 주세요.","t2":"타임머신이 유다의 예루살렘에 비상 착륙했어요. 부속을 고정하던 쐐기가 빠져서 기계가 덜컹거려요. 이 시대에는 맞는 쐐기가 없으니, 그곳에서 구할 수 있는 단단한 조각으로 대신해야 해요.","t3":"타임머신은 예루살렘에 비상 착륙했다. 부속을 고정하던 쐐기가 빠져 기계가 흔들린다. 이 시대에는 맞는 쐐기가 없으니 그곳에서 얻을 수 있는 단단한 조각을 찾아 대신 끼워야 한다. 왕과 제사장, 일꾼들의 일에는 끼어들지 말고, 남의 물건에는 손대지 말아야 한다."},"materials":[{"key":"flatstone","name":"납작한 돌 조각","basis":"왕하 22:1","use":"납작하고 단단한 돌 조각을 빠진 쐐기 대신 끼워 쓸 수 있어요.","how":"돌을 찾을 때는 여호와의 전 쪽으로 가지 않았다. 전에서 멀리 떨어진 예루살렘 길가 땅에 굴러 있던 납작한 돌 조각 하나를 주웠다. 일하는 사람들이 쓰는 재목과 다듬은 돌에는 손대지 않았다.","line":"납작한 돌 조각을 주웠어! 여호와의 전에서 멀리 떨어진 길가 땅에 굴러 있었어."}],"companion":{"who":"훌다","ref":"왕하 22:14","when":"after","talks":[{"ask":{"who":"hyu","text":"훌다 선지자님, 왕이 보낸 사람들에게 뭐라고 전하셨어요?"},"answer":{"t1":"훌다는 여호와께서 그 책에 적힌 말대로 이곳에 재앙을 내리시겠다고 하셨다고 전했어요. 백성이 여호와를 버리고 다른 신에게 분향했기 때문이라고 하셨대요.","t2":"훌다는 사람들에게, 그들을 보낸 사람에게 여호와의 말씀을 알리라고 했어요. 여호와께서 유다 왕이 읽은 책의 모든 말대로 이곳과 여기 사는 사람들에게 재앙을 내리시겠다고 하셨다는 것이에요. 이 백성이 여호와를 버리고 다른 신에게 분향하여 여호와를 노엽게 했기 때문이라고 하셨다고 전했어요.","t3":"훌다는 이스라엘의 하나님 여호와의 말씀이라며, 그들을 보낸 사람에게 이렇게 알리라고 했다. 여호와께서는 유다 왕이 읽은 책의 모든 말대로 이곳과 그 주민에게 재앙을 내리시겠다고 하셨다. 이 백성이 여호와를 버리고 다른 신들에게 분향하며 자기 손으로 한 모든 일로 여호와를 노엽게 했으므로, 이곳을 향한 진노가 꺼지지 않으리라고 하셨다고 전했다."},"ref":"왕하 22:15-17","open":"왕하 22:16"},{"ask":{"who":"choeon","text":"요시야 왕에게는 뭐라고 전하셨어요?"},"answer":{"t1":"훌다는 왕이 여호와 앞에서 자기를 낮추고 울었으므로 여호와께서도 왕의 말을 들으셨다고 전했어요. 왕은 이곳에 내릴 재앙을 눈으로 보지 않을 것이라고 하셨대요.","t2":"훌다는 여호와께 물으라고 사람들을 보낸 유다 왕에게 전할 말씀도 일렀어요. 왕이 이곳에 대한 말씀을 듣고 마음이 부드러워져 여호와 앞에서 자기를 낮추고 옷을 찢고 울었으므로, 여호와께서도 왕의 말을 들으셨다고 하셨어요. 그래서 왕은 평안히 묘실에 들어가고, 이곳에 내릴 재앙을 눈으로 보지 않을 것이라고 하셨다고 전했어요.","t3":"훌다는 여호와께 묻게 하려고 사람들을 보낸 유다 왕에게 전할 여호와의 말씀도 일렀다. 이곳과 그 주민이 빈 터가 되고 저주가 되리라는 말씀을 왕이 듣고, 마음이 부드러워져 여호와 앞에서 자기를 낮추고 옷을 찢고 울었으므로 여호와께서도 왕의 말을 들으셨다고 하셨다. 그러므로 왕을 조상들에게로 돌아가 평안히 묘실에 들게 하시고, 이곳에 내리실 모든 재앙을 왕이 눈으로 보지 않게 하시리라고 하셨다고 전했다."},"ref":"왕하 22:18-20","open":"왕하 22:19"}]},"today":[{"q":"어린 나이에도 하나님을 찾을 수 있어요?","a":{"t1":"요시야는 여덟 살에 왕이 되었고, 여호와께서 보시기에 바르게 행했어요. 역대하는 요시야가 아직 어릴 때 하나님을 찾기 시작했다고 적어요.","t2":"열왕기하는 요시야가 여덟 살에 왕이 되었고, 여호와 보시기에 바르게 행하여 왼쪽으로도 오른쪽으로도 치우치지 않았다고 적어요. 역대하는 그가 왕이 된 지 팔 년째, 아직 어릴 때에 조상 다윗의 하나님을 찾기 시작했다고 적어요. 또 요시야가 언약책을 읽어 줄 때 어린 사람부터 나이 든 사람까지 모든 백성이 함께 있었어요.","t3":"열왕기하는 요시야가 여덟 살에 왕위에 올랐고 여호와 보시기에 정직하게 행하여 좌우로 치우치지 않았다고 기록한다. 역대하는 그가 즉위한 지 팔 년, 아직 어렸을 때 조상 다윗의 하나님을 찾기 시작했다고 기록한다. 또 왕이 언약책을 읽어 들려줄 때 백성은 나이를 가리지 않고 모두 함께 있었다. 성경은 여기까지 말한다."},"refs":["왕하 22:1-2","대하 34:3","왕하 23:2"]},{"q":"율법책이 왜 성전에서 발견됐어요? 잃어버렸던 거예요?","a":{"t1":"성경은 힐기야가 여호와의 전에서 율법책을 발견했다고만 말해요. 어떻게 거기 있었는지는 말하지 않아요.","t2":"성경은 대제사장 힐기야가 여호와의 전에서 율법책을 발견했다고 적어요. 그 책이 왜, 언제부터 거기 있었는지는 말하지 않아요. 다만 요시야 왕은 조상들이 이 책의 말씀을 듣지 않고 그대로 행하지 않았다고 말했어요.","t3":"본문은 힐기야가 여호와의 전에서 율법책을 발견했다고만 기록하고, 그 책이 어떻게 그곳에 있었는지는 말하지 않는다. 요시야는 조상들이 이 책의 말씀을 듣지 않고 거기 기록된 대로 행하지 않았다고 말했다. 성경은 여기까지 말한다."},"refs":["왕하 22:8","왕하 22:13"]}],"help":{"who":"예루살렘의 백성","steps":[{"kind":"watch","after":1,"title":"곁에서 보기 · 전을 고치는 일꾼들","basis":"왕하 22:5-6","text":{"t1":"은을 받은 일꾼들이 여호와의 전의 낡은 곳을 고쳐요. 우리는 나무와 돌에 손대지 않고 곁에서 봐요.","t2":"백성이 드린 은은 일을 감독하는 사람들에게 맡겨졌고, 목수, 건축자, 미장이가 그 은을 받아 여호와의 전을 고쳐요. 나무와 다듬은 돌도 그 일을 하려고 사들인 것이에요. 우리는 손대지 않고 곁에서 봐요.","t3":"백성이 여호와의 전에 바친 은은 일을 감독하는 사람들에게 맡겨졌고, 목수, 건축자, 미장이가 그 은을 받아 전의 낡은 곳을 고친다(22:5-6). 나무와 다듬은 돌도 그 일을 하려고 산 것이다. 탐험대는 일꾼들의 일과 재료에 손대지 않고 곁에서 본다."},"say":{"who":"choeon","text":"나무랑 돌은 일꾼들 거야. 우리는 손대지 말고 보기만 하자."}},{"kind":"do","after":6,"title":"함께 올라가는 길 거들기","basis":"왕하 23:2","text":{"t1":"어린 사람부터 나이 든 사람까지 모든 백성이 왕과 함께 여호와의 전으로 올라가요. 성경에 적힌 일은 아니지만, 우리는 그 곁에서 함께 걸으며 길을 거들어요.","t2":"나이를 가리지 않고 모든 백성이 왕과 함께 여호와의 전으로 올라가요. 이것은 성경에 적힌 일이 아니라 탐험대가 곁에서 거드는 일이에요. 우리는 길을 비켜 주고, 나이 든 사람과 어린 사람 곁에서 천천히 함께 걸어요.","t3":"유다 사람들과 예루살렘 주민, 제사장들과 선지자들, 나이를 가리지 않고 모든 백성이 왕과 함께 여호와의 전으로 올라간다(23:2). 탐험대는 그 곁에서 길을 비켜 주고 나이 든 사람과 어린 사람의 걸음을 거든다. 본문에 적힌 일이 아니라 탐험대의 일이며, 왕과 제사장들의 일과 언약책에는 손대지 않는다."},"tasks":["길 가운데서 비켜서기","나이 든 분 곁에서 천천히 걷기","어린아이가 무리를 놓치지 않게 곁에 있기"],"done":{"who":"choeon","text":"어린 사람도 나이 든 사람도 다 함께 올라왔어."}},{"kind":"stay","after":6,"title":"모인 백성 곁에서 함께 듣기","basis":"왕하 23:2","text":{"t1":"어린 사람부터 나이 든 사람까지 모든 백성이 왕과 함께 여호와의 전에 올라갔어요. 왕이 언약책의 말씀을 읽어 들려줘요. 우리도 백성 곁에서 함께 들어요.","t2":"유다 사람들과 예루살렘 주민, 제사장들과 선지자들, 어린 사람부터 나이 든 사람까지 모두 왕과 함께 여호와의 전에 올라갔어요. 왕이 전에서 찾아낸 언약책의 말씀을 모두 읽어 들려줘요. 우리도 모인 백성 곁에서 조용히 함께 들어요.","t3":"유다 사람들과 예루살렘 주민, 제사장들과 선지자들, 나이를 가리지 않고 모든 백성이 왕과 함께 여호와의 전에 올라갔다(23:2). 왕은 전에서 찾아낸 언약책의 말씀을 모두 읽어 무리에게 들려준다. 탐험대도 모인 백성 곁에서 조용히 함께 듣는다."},"wait":"백성 곁에서 함께 듣기","say":{"who":"onwoo","text":"누가 함께 올라왔는지는 23장 2절에 있어. 우리는 조용히 곁에서 듣자."}},{"kind":"watch","after":6,"title":"곁에서 보기 · 대 위에서 세운 언약","basis":"왕하 23:3","text":{"t1":"왕은 대 위에 선 채 여호와 앞에서 언약을 세워요. 백성도 다 그 언약을 따르기로 해요. 우리는 끼어들지 않고 곁에서 봐요.","t2":"왕은 대 위에 선 채 여호와 앞에서 언약을 세워요. 백성도 다 그 언약을 따르기로 해요. 언약을 세우는 일은 본문이 왕이 했다고 적은 일이에요. 우리는 끼어들지 않고 곁에서 봐요.","t3":"왕은 대 위에 선 채 여호와 앞에서 언약을 세운다(23:3). 백성도 다 그 언약을 따르기로 한다. 언약을 세우는 일은 본문이 왕이 했다고 적은 일이다. 탐험대는 끼어들지 않고 곁에서 본다."},"say":{"who":"hyu","text":"왕은 대 위에 서 있어. 백성도 다 따르기로 했다고 일지에 적어 둘게."}},{"kind":"ask","after":"gates","title":"왕이 세운 언약은 무슨 뜻이에요?","basis":"왕하 23:3","by":"최현 박사","ask":{"who":"choeon","text":"왕이 대 위에서 세운 언약은 무슨 뜻이에요?"},"answer":{"t1":"성경은 왕이 여호와 앞에서, 마음을 다해 여호와를 따르고 이 책에 적힌 언약의 말씀을 이루겠다고 언약을 세웠다고 적어요. 백성도 다 그 언약을 따르기로 했어요(23:3).","t2":"요시야 왕은 율법책의 말씀을 듣고, 조상들이 이 책의 말씀을 듣지 않고 그대로 행하지 않았다고 말했어요(22:13). 대 위에서 세운 언약은 마음과 성품을 다해 여호와를 따르고 계명·법도·율례를 지켜, 이 책에 적힌 언약의 말씀을 이루겠다는 것이었어요(23:3). 백성도 다 그 언약을 따르기로 했어요.","t3":"요시야는 율법책의 말을 듣고, 조상들이 이 책의 말씀을 듣지 않고 거기 적힌 대로 행하지 않았다고 말했다(22:13). 대 위에서 여호와 앞에 세운 언약은 마음과 성품을 다하여 여호와를 따르고 그분의 계명·법도·율례를 지켜, 이 책에 적힌 언약의 말씀을 이루겠다는 것이었다(23:3). 백성도 다 그 언약을 따르기로 했다. 성경은 이 언약에 대해 이만큼 말한다."},"read":{"t1":{"type":"find","ref":"왕하 23:3","prompt":"성경책에서 열왕기하 23장 3절을 찾아 읽어 보세요.","confirm":{"prompt":"왕은 언약을 세우며 여호와의 무엇을 지키겠다고 했나요?","options":[{"label":"계명과 법도와 율례","ok":true},{"label":"제사장들이 새로 정한 규칙","basis":"본문에 없음"},{"label":"앗수르 왕과 맺은 약속","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"왕하 22:11-13","prompt":"성경책에서 열왕기하 22장 11절부터 13절까지 읽어 보세요.","confirm":{"prompt":"요시야 왕이 여호와의 진노가 크다고 말한 까닭은 무엇인가요?","options":[{"label":"조상들이 이 책의 말씀을 듣지 않고, 거기 적힌 대로 행하지 않았기 때문에","ok":true},{"label":"일을 감독하는 사람들에게 맡긴 은을 따로 셈하지 않았기 때문에","basis":"왕하 22:7"},{"label":"조상들이 여호와의 전을 오래 고치지 않고 버려두었기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["왕하 22:13","왕하 23:3"],"prompt":"열왕기하 22장 13절과 23장 3절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 왕이 세운 언약은 조상들이 한 일과 어떻게 다른가?","options":[{"label":"왕은 조상들이 이 책의 말씀을 듣지 않고 행하지 않았다고 말했고, 이 책에 적힌 언약의 말씀을 이루겠다고 언약을 세웠다","ok":true},{"label":"왕은 조상들이 이 책의 말씀을 듣지 않고 행하지 않았다고 말했고, 해마다 이 책을 여호와의 전에서 한 번씩 읽겠다고 언약을 세웠다","basis":"본문에 없음"},{"label":"왕은 조상들이 이 책의 말씀을 듣지 않았다고 말했고, 그러니 이 책의 말씀을 고쳐 새 법을 세우겠다고 언약을 세웠다","basis":"본문에 없음"}]}}}}]}},"has3d":false,"epic":false},"OT-35":{"id":"OT-35","era":9,"title":"예루살렘이 무너지고 바벨론으로 끌려감","ref":"왕하 25:1-21","place":"예루살렘, 여리고 평지, 하맛 땅","review":{"required":true,"topics":["재앙과 심판(왕하 25:7, 25:9-10, 25:21)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"왕하 25:1-2","focus":"siege","text":{"t1":"바벨론 왕이 모든 군대를 데리고 와서 예루살렘 성을 빙 둘러 에워쌌어요. 그 왕의 이름은 성경에서 찾아봐요.","t2":"시드기야 왕 구년 열째 달 십일에 바벨론 왕 느부갓네살이 모든 군대를 이끌고 예루살렘을 치러 올라왔어요. 그들은 진을 치고 성 둘레에 토성을 쌓았어요. 성은 시드기야 왕 십일년까지 에워싸여 있었어요.","t3":"시드기야 왕 구년 열째 달 십일에 바벨론 왕 느부갓네살이 모든 군대를 이끌고 예루살렘을 치려고 올라왔다. 그들은 진을 치고 성 사방에 토성을 쌓았다. 성은 시드기야 왕 십일년까지 에워싸여 있었다."},"say":{"who":"hyu","text":"시드기야 왕 구년 열째 달 십일. 바벨론 군대가 예루살렘을 에워쌌어. 날짜를 적어 둘게."}},{"ref":"왕하 25:3-4","focus":"wall","text":{"t1":"성 안에는 먹을 것이 다 떨어졌어요. 성벽에 구멍이 뚫렸고, 군사들은 밤중에 성을 빠져나가 달아났어요.","t2":"넷째 달 구일에는 성 안에 기근이 심해서 백성의 양식이 다 떨어졌어요. 성벽에 구멍이 뚫리자 군사들은 모두 밤을 타서, 두 성벽 사이 왕의 동산 옆에 있는 문으로 달아나 아라바 쪽 길로 갔어요.","t3":"넷째 달 구일에는 성 안에 기근이 심하여 그 땅 백성의 양식이 다 떨어졌다. 갈대아 사람들이 성을 에워싸고 있는 가운데 성벽에 구멍이 뚫렸고, 군사들은 모두 밤을 타서, 두 성벽 사이 왕의 동산 옆에 있는 문 길로 달아나 아라바 쪽 길로 갔다."},"say":{"who":"choeon","text":"밤중에 군사들이 두 성벽 사이에 있는 문으로 빠져나가고 있어."}},{"ref":"왕하 25:5-7","focus":"zedekiah","text":{"t1":"갈대아 군사가 시드기야 왕을 뒤쫓아 여리고 평지에서 붙잡았어요. 왕은 사슬에 묶여 바벨론으로 끌려갔어요.","t2":"갈대아 군사가 왕을 뒤쫓아 여리고 평지에서 따라잡았어요. 그때 왕 곁의 군사들이 어떻게 되었는지는 5절에서 찾아봐요. 갈대아 군사는 왕을 붙잡아 바벨론 왕에게 끌고 갔고, 거기서 왕은 심문을 받았어요. 시드기야의 아들들은 죽임을 당했고, 시드기야는 두 눈을 잃은 채 사슬에 묶여 바벨론으로 끌려갔어요.","t3":"갈대아 군사가 왕을 뒤쫓아 여리고 평지에서 따라잡자, 왕의 군사는 모두 그를 떠나 흩어졌다. 갈대아 군사는 왕을 붙잡아 바벨론 왕에게 끌고 갔고, 거기서 그를 심문했다. 그들은 시드기야의 아들들을 그가 보는 앞에서 죽였고, 시드기야의 두 눈을 뽑은 뒤 사슬로 묶어 바벨론으로 끌고 갔다."},"say":{"who":"hyu","text":"왕이 붙잡힌 곳은 여리고 평지야. 일지에 적어 둘게."}},{"ref":"왕하 25:8-10","focus":"temple","text":{"t1":"바벨론 왕의 신하 느부사라단이 와서 여러 곳을 불살랐고, 갈대아 군대는 예루살렘의 성벽을 헐었어요. 무엇 무엇을 불살랐는지는 성경에서 찾아봐요.","t2":"바벨론 왕 느부갓네살 십구년 다섯째 달 칠일에, 바벨론 왕의 신하 느부사라단이 예루살렘에 왔어요. 그 뒤에 예루살렘에서 어떤 일이 어떤 차례로 일어났는지는 9절과 10절에서 읽어 봐요.","t3":"바벨론 왕 느부갓네살 십구년 다섯째 달 칠일에, 바벨론 왕의 신하로 시위대를 거느린 느부사라단이 예루살렘에 왔다. 그를 따르는 갈대아 온 군대는 예루살렘을 사방으로 둘러싼 성벽을 헐었다. 느부사라단이 예루살렘에서 무엇을 불살랐는지는 9절에 있다."},"say":{"who":"choeon","text":"바벨론 왕의 신하가 왔어. 우리는 멀리 떨어져서 보자."}},{"ref":"왕하 25:11-12","focus":"people","text":{"t1":"느부사라단은 성에 남아 있던 백성을 사로잡아 갔어요. 가난한 사람들은 그 땅에 남겨서 포도원을 가꾸고 농사를 짓게 했어요.","t2":"느부사라단은 성 안에 남아 있던 백성과 바벨론 왕에게 항복한 사람들과 그 밖에 남은 무리를 모두 사로잡아 갔어요. 가난한 백성은 그 땅에 남겨 두어 포도원을 가꾸는 사람과 농부가 되게 했어요.","t3":"느부사라단은 성 안에 남아 있던 백성과 바벨론 왕에게 항복한 사람들과 그 밖에 남은 무리를 모두 사로잡아 갔다. 다만 가난한 백성은 그 땅에 남겨 두어 포도원을 가꾸는 사람과 농부가 되게 했다."},"say":{"who":"onwoo","text":"누가 끌려가고 누가 남았는지는 11절과 12절에 있어. 성경책에서 확인해 보자."}},{"ref":"왕하 25:13-17","focus":"bronze","text":{"t1":"갈대아 사람들은 여호와의 전에 있던 놋기둥 둘과 놋바다를 깨뜨려서, 놋을 바벨론으로 가져갔어요. 느부사라단은 금과 은으로 만든 그릇들도 가져갔어요.","t2":"갈대아 사람들은 여호와의 전에 있던 놋기둥 둘과 받침들과 놋바다를 깨뜨려서, 놋을 바벨론으로 가져갔어요. 가마와 부삽과 불집게와 숟가락, 섬길 때 쓰던 놋그릇도 모두 가져갔어요. 느부사라단은 금으로 만든 것과 은으로 만든 것도 가져갔어요. 솔로몬이 여호와의 전을 위해 만든 기둥 둘과 바다와 받침들은 그 놋의 무게를 헤아릴 수 없었어요.","t3":"갈대아 사람들은 가마와 부삽과 불집게와 숟가락, 섬길 때 쓰던 놋그릇을 모두 가져갔다. 여호와의 전의 놋기둥과 받침들과 놋바다, 그리고 금과 은으로 만든 그릇이 어떻게 되었는지는 13절과 15절에서 직접 읽어 보자. 솔로몬이 여호와의 전을 위해 만든 기둥 둘과 바다 하나와 받침들은 그 놋의 무게를 헤아릴 수 없었다. 기둥 하나는 높이가 십팔 규빗이고 꼭대기에는 높이 삼 규빗의 놋머리가 있었으며, 머리를 두른 그물과 석류도 다 놋이었다."},"say":{"who":"hyu","text":"가져가는 기구가 정말 많아. 하나씩 일지에 적어 둘게."}},{"ref":"왕하 25:18-21","open":"왕하 25:21","focus":"exile","text":{"t1":"느부사라단은 대제사장과 여러 사람을 잡아 바벨론 왕에게 데려갔어요. 이렇게 유다는 사로잡혀 자기 땅을 떠났어요.","t2":"느부사라단은 대제사장 스라야, 부제사장 스바냐, 전 문지기 세 사람, 그리고 성 안에 있던 사람들을 잡아 하맛 땅에 있던 바벨론 왕에게 데려갔어요. 바벨론 왕은 거기서 그들을 죽였어요. 이렇게 유다는 사로잡혀 자기 땅을 떠났어요.","t3":"느부사라단은 대제사장 스라야, 부제사장 스바냐, 그리고 전 문지기 세 사람을 붙잡았다. 또 성 안에서 군사를 거느린 내시 한 사람, 왕의 시종 다섯 사람, 백성을 군사로 모으는 장관의 서기관 한 사람, 그리고 백성 육십 명을 잡았다. 느부사라단이 그들을 하맛 땅에 있던 바벨론 왕에게 데려가자, 바벨론 왕은 거기서 그들을 쳐 죽였다. 이렇게 유다는 사로잡혀 자기 땅을 떠났다."},"say":{"who":"onwoo","text":"이 이야기의 마지막 문장은 21절에 있어. 성경책에서 직접 읽어 보자."}}],"gates":{"t1":[{"type":"find","ref":"왕하 25:1","prompt":"성경책에서 열왕기하 25장 1절을 찾아 읽어 보세요.","confirm":{"prompt":"예루살렘을 치려고 모든 군대를 이끌고 온 바벨론 왕의 이름은 무엇인가요?","options":[{"label":"느부갓네살","ok":true},{"label":"느부사라단","basis":"왕하 25:8"},{"label":"산헤립","basis":"왕하 18:13"}]}},{"type":"multi","ref":"왕하 25:9","prompt":"성경책에서 열왕기하 25장 9절을 찾아 읽어 보세요.","confirm":{"prompt":"느부사라단이 불사른 것을 모두 고르세요.","options":[{"label":"여호와의 전","ok":true},{"label":"예루살렘을 둘러싼 성벽","basis":"왕하 25:10"},{"label":"왕궁","ok":true},{"label":"포도원","basis":"본문에 없음"},{"label":"예루살렘의 집들","ok":true}]}}],"t2":[{"type":"find","ref":"왕하 25:4-6","prompt":"성경책에서 열왕기하 25장 4절부터 6절까지 읽어 보세요.","confirm":{"prompt":"시드기야 왕이 여리고 평지에서 붙잡힐 때 왕 곁에 군사가 없었던 까닭은 무엇인가요?","options":[{"label":"갈대아 군사가 쫓아와 따라잡자, 왕의 군사들이 모두 왕을 떠나 흩어졌기 때문에","ok":true},{"label":"갈대아 군사가 쫓아와 따라잡자, 왕의 군사들이 모두 사로잡혀 끌려갔기 때문에","basis":"본문에 없음"},{"label":"갈대아 군사가 쫓아와 따라잡자, 왕의 군사들이 모두 갈대아 편으로 넘어갔기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"왕하 25:8-13","prompt":"성경책에서 열왕기하 25장 8절부터 13절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["바벨론 왕의 신하 느부사라단이 왔다","느부사라단이 여호와의 전과 왕궁과 집들을 불살랐다","갈대아 군대가 예루살렘 사방의 성벽을 헐었다","성 안에 남은 백성이 사로잡혀 갔다","갈대아 사람들이 여호와의 전의 놋을 깨뜨려 바벨론으로 가져갔다"]}],"t3":[{"type":"find","refs":["왕하 25:9","왕하 25:13","왕하 25:15"],"prompt":"열왕기하 25장 9절, 13절, 15절을 함께 찾아 읽어 보자.","confirm":{"prompt":"세 곳을 이어 읽으면, 여호와의 전은 어떻게 되었는가?","options":[{"label":"느부사라단이 전을 불살랐고, 갈대아 사람들은 놋기둥과 받침과 놋바다는 깨뜨려 놋만 실어 갔으며, 금과 은으로 만든 그릇도 가져갔다","ok":true},{"label":"느부사라단은 왕궁과 집들만 불살랐고, 갈대아 사람들은 놋기둥과 받침과 놋바다는 깨뜨려 놋만 실어 갔으며, 금과 은으로 만든 그릇도 가져갔다","basis":"본문에 없음"},{"label":"느부사라단은 전의 문들만 불살랐고, 갈대아 사람들은 놋기둥과 놋바다를 통째로 바벨론에 옮겨 갔으며, 금과 은으로 만든 그릇도 가져갔다","basis":"본문에 없음"}]}},{"type":"match","refs":["왕하 25:1","왕하 25:4","왕하 25:10"],"prompt":"열왕기하 25장 1절, 4절, 10절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"왕하 25:1","text":"바벨론 군대가 진을 치고 성 둘레에 토성을 쌓았다"},{"ref":"왕하 25:4","text":"성벽에 구멍이 뚫리자 군사들이 밤중에 빠져나갔다"},{"ref":"왕하 25:10","text":"느부사라단을 따르는 군대가 성벽을 사방으로 헐었다"}],"after":"세 곳을 이으면, 토성으로 에워싸인 성의 성벽에 구멍이 뚫려 군사들이 빠져나갔고, 뒤에는 느부사라단을 따르는 군대가 성벽을 사방으로 헐었다."}]},"cards":[{"ref":"왕하 25:9","title":"불살라진 여호와의 전"},{"ref":"왕하 25:21","title":"사로잡혀 본토를 떠난 유다"}],"close":{"t1":{"kind":"prayer","text":"하나님, 예루살렘이 무너진 이야기를 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 열왕기하 25장 8절부터 12절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"왕하 25:1-21에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"여기는 예루살렘 가까이예요. 전선을 묶어 두던 끈이 끊어졌어요. 끈 대신 쓸 질긴 것을 찾아 주세요.","t2":"타임머신이 유다의 예루살렘 가까이에 비상 착륙했어요. 전선을 묶어 두던 끈이 끊어져서 줄이 늘어졌어요. 이 시대에는 맞는 끈이 없으니, 그곳에서 구할 수 있는 질긴 것으로 대신 묶어야 해요.","t3":"타임머신은 예루살렘 가까이에 비상 착륙했다. 전선을 묶어 두던 끈이 끊어졌다. 이 시대에는 맞는 끈이 없으니 그곳에서 얻을 수 있는 질긴 것으로 대신 묶어야 한다. 군사들의 일에는 끼어들지 말고 떨어진 곳에서 지켜보아야 한다. 그 땅에 남은 사람들을 곁에서 거들게 되어도 그들의 물건을 가져오지 않고, 포도원 안과 여호와의 전의 기구에는 손대지 않는다."},"materials":[{"key":"vine","name":"포도 덩굴","basis":"왕하 25:12","use":"질긴 포도 덩굴을 끊어진 끈 대신 쓸 수 있어요.","how":"포도원 안에는 들어가지 않았다. 포도원 밖 길가에 떨어져 있던 마른 포도 덩굴 한 가닥을 주웠다. 아무에게서도 가져오지 않았다.","line":"포도 덩굴을 주웠어! 포도원 밖 길가에 떨어져 있었어."}],"companion":null,"today":[{"q":"끌려간 사람들은 그 뒤에 어떻게 되었어요?","a":{"t1":"역대하는 끌려간 사람들이 바사 나라가 다스릴 때까지 바벨론 왕과 그 자손의 종이 되었다고 적어요. 열왕기하의 마지막에는 사로잡혀 가 있던 유다 왕 여호야긴이 옥에서 풀려났다고 적어요.","t2":"역대하는 칼을 피한 사람들이 바벨론으로 끌려가 바사 나라가 다스릴 때까지 바벨론 왕과 그 자손의 종이 되었다고 적어요. 열왕기하의 마지막 부분은, 여호야긴 왕이 바벨론에 끌려간 지 서른일곱 해째에 바벨론 왕이 그를 옥에서 풀어 주고 평생 자기 앞에서 먹게 했다고 적어요.","t3":"역대하는 칼에서 벗어난 사람들이 바벨론으로 사로잡혀 가서, 바사 나라가 다스릴 때까지 갈대아 왕과 그 자손의 종이 되었다고 기록한다. 열왕기하는, 여호야긴 왕이 끌려간 지 서른일곱 해째에 바벨론 왕 에윌므로닥이 그를 옥에서 내어 높여 주고, 죄수의 옷을 바꾸게 하며 평생 자기 앞에서 먹게 했다는 기록으로 끝난다. 성경은 여기까지 말한다."},"refs":["대하 36:20","왕하 25:27-30"]}],"help":{"who":"그 땅에 남은 가난한 백성","steps":[{"kind":"stay","after":4,"title":"남은 사람들 곁에 머물기","basis":"왕하 25:12","text":{"t1":"많은 사람이 사로잡혀 갔어요. 가난한 사람들은 그 땅에 남았어요. 우리는 남은 사람들 곁에 함께 머물러요.","t2":"느부사라단은 성 안에 남아 있던 백성을 사로잡아 갔지만, 가난한 백성은 그 땅에 남겨 두었어요. 그들은 포도원을 가꾸고 농사를 지을 사람들이에요. 우리는 남은 사람들 곁에 조용히 머물러요.","t3":"성 안에 남아 있던 백성과 항복한 사람들과 남은 무리는 사로잡혀 갔고(25:11), 가난한 백성은 그 땅에 남아 포도원을 가꾸는 사람과 농부가 되었다(25:12). 탐험대는 남은 사람들 곁에 조용히 머문다. 그들의 물건은 가져오지 않는다."},"wait":"남은 사람들 곁에 머물기","say":{"who":"choeon","text":"남은 사람들 곁에 조용히 있자. 그들의 물건에는 손대지 않을게."}},{"kind":"do","after":4,"title":"남은 사람들 곁에서 밭일 거들기","basis":"왕하 25:12","text":{"t1":"가난한 사람들은 그 땅에 남아 포도원을 가꾸고 농사를 짓게 되었어요. 성경에 적힌 일은 아니지만, 우리는 그 곁에서 밭일을 조금 거들어요.","t2":"느부사라단은 가난한 백성을 그 땅에 남겨 포도원을 가꾸는 사람과 농부가 되게 했어요. 이것은 성경에 적힌 일이 아니라 탐험대가 곁에서 거드는 일이에요. 우리는 포도원 안에는 들어가지 않고, 밭에서 돌을 골라내는 일을 조금 거들어요.","t3":"가난한 백성은 그 땅에 남겨져 포도원을 가꾸는 사람과 농부가 되었다(25:12). 탐험대는 그 곁에서 밭의 돌을 골라내는 일을 조금 거든다. 본문에 적힌 일이 아니라 탐험대의 일이다. 포도원 안에는 들어가지 않고, 그들의 물건을 가져오지 않는다."},"tasks":["밭의 돌 골라내기","흙덩이 잘게 부수기","골라낸 돌 밭 가로 옮기기"],"done":{"who":"choeon","text":"밭이 조금 정리됐어. 포도원 안에는 들어가지 않았어."}},{"kind":"watch","after":5,"title":"곁에서 보기 · 실려 가는 여호와의 전 기구","basis":"왕하 25:13-15","text":{"t1":"갈대아 사람들이 여호와의 전의 놋기둥과 놋바다를 깨뜨려 놋을 가져가요. 우리는 전의 기구에 손대지 않고 멀리서 봐요.","t2":"갈대아 사람들이 여호와의 전의 놋기둥과 받침과 놋바다를 깨뜨려 놋을 바벨론으로 가져가요. 섬길 때 쓰던 그릇들도 가져가요. 우리는 여호와의 전 기구에 손대지 않고 멀리서 봐요.","t3":"갈대아 사람들과 시위대 장관이 여호와의 전의 기구들을 바벨론으로 가져간다. 섬길 때 쓰던 놋그릇도 가져간다(25:14). 탐험대는 그 기구에 손대지 않고 멀리서 본다."},"say":{"who":"onwoo","text":"가져간 것은 13절부터 15절까지 적혀 있어. 우리는 손대지 않고 멀리서 보자."}},{"kind":"ask","after":"gates","title":"유다가 자기 땅을 떠난 일은 무슨 뜻이에요?","basis":"왕하 24:20","by":"최현 박사","ask":{"who":"hyu","text":"예루살렘이 무너지고 유다가 자기 땅을 떠난 일은 무슨 뜻이에요?"},"answer":{"t1":"이 장면의 본문은 그 뜻을 따로 말하지 않아요. 바로 앞에서 열왕기하는 여호와께서 예루살렘과 유다에게 진노하셨다고 적어요. 요시야 때 훌다는, 백성이 여호와를 버리고 다른 신에게 분향했다는 여호와의 말씀을 전했어요.","t2":"이 장면의 본문(열왕기하 25장 1절부터 21절)은 그 뜻을 따로 말하지 않아요. 바로 앞 24장 20절은 여호와께서 예루살렘과 유다에게 진노하셔서 그들을 그 앞에서 쫓아내시기에 이르렀다고 적어요. 요시야 때 여선지 훌다는, 백성이 여호와를 버리고 다른 신에게 분향했으므로 이곳에 재앙을 내리시겠다는 여호와의 말씀을 전했어요.","t3":"이 장면의 본문은 그 뜻을 따로 말하지 않는다. 바로 앞의 열왕기하 24장 20절은 여호와께서 예루살렘과 유다에게 진노하셔서 그들을 그 앞에서 쫓아내시기에 이르렀다고 기록한다. 요시야 때 훌다는, 이 백성이 여호와를 버리고 다른 신들에게 분향했으므로 이곳에 재앙을 내리시겠다는 말씀을 전했다(22:15-17). 그리고 25장 21절은 유다가 사로잡혀 본토를 떠났다고 적는다. 성경은 여기까지 말한다."},"read":{"t1":{"type":"find","ref":"왕하 24:20","prompt":"성경책에서 열왕기하 24장 20절을 찾아 읽어 보세요.","confirm":{"prompt":"여호와께서 누구에게 진노하셨다고 적혀 있나요?","options":[{"label":"예루살렘과 유다","ok":true},{"label":"바벨론과 갈대아","basis":"렘 50:13"},{"label":"앗수르와 애굽","basis":"본문에 없음"}]},"inStory":"예루살렘과 유다는 장면의 곳과 나라 이름이라 이야기에 늘 나온다. 여호와께서 그들에게 진노하셨다는 것은 24:20에서만 안다"},"t2":{"type":"find","ref":"왕하 22:15-17","prompt":"성경책에서 열왕기하 22장 15절부터 17절까지 읽어 보세요.","confirm":{"prompt":"훌다가 전한 말씀에서, 여호와께서 이곳에 재앙을 내리시겠다고 하신 까닭은 무엇인가요?","options":[{"label":"백성이 여호와를 버리고 다른 신들에게 향을 피워 여호와를 노엽게 했기 때문에","ok":true},{"label":"바벨론 왕이 예루살렘을 빼앗아 자기 땅으로 삼으려 했기 때문에","basis":"본문에 없음"},{"label":"요시야 왕이 여호와의 전에서 찾은 율법책을 읽지 않고 감추었기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["왕하 22:16-17","왕하 24:20","왕하 25:21"],"prompt":"열왕기하 22장 16절과 17절, 24장 20절, 25장 21절을 함께 찾아 읽어 보자.","confirm":{"prompt":"세 곳을 이어 읽으면, 성경은 유다가 자기 땅을 떠난 일에 대해 무엇을 말하는가?","options":[{"label":"훌다는 백성이 여호와를 버렸으므로 이곳에 재앙이 내리리라는 말씀을 전했고, 열왕기하는 여호와의 진노가 그들을 그 앞에서 쫓아내시기에 이르렀다고 적으며, 유다는 사로잡혀 본토를 떠났다","ok":true},{"label":"훌다는 이곳에 재앙이 결코 내리지 않으리라는 말씀을 전했고, 열왕기하는 시드기야의 군사들이 흩어진 탓에 그들이 쫓겨나게 되었다고 적으며, 유다는 사로잡혀 본토를 떠났다","basis":"본문에 없음"},{"label":"훌다는 요시야 왕이 율법책을 읽지 않았으므로 재앙이 내리리라고 전했고, 열왕기하는 바벨론 왕의 진노가 유다를 쫓아냈다고 적으며, 유다는 사로잡혀 본토를 떠났다","basis":"본문에 없음"}]}}}}]}},"has3d":false,"epic":false},"OT-36":{"id":"OT-36","era":9,"title":"사자 굴의 다니엘","ref":"단 6:1-28","place":"다리오 왕의 나라, 다니엘의 집, 사자 굴","review":{"required":false,"topics":[],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"단 6:1-3","focus":"daniel","text":{"t1":"다리오 왕은 나라를 다스릴 사람들을 세우고 그 위에 총리 셋을 두었는데, 다니엘이 그 가운데 한 사람이었어요. 다스릴 사람을 몇 명 세웠는지는 성경에서 찾아봐요.","t2":"다리오는 나라를 다스릴 사람 백이십 명을 세우고 그 위에 총리 셋을 두었는데, 다니엘이 그 가운데 하나였어요. 왕은 다니엘을 세워 온 나라를 다스리게 하려고 했는데, 그 까닭은 3절에서 찾아봐요.","t3":"다리오는 방백(나라를 다스리도록 세운 사람) 백이십 명을 세워 온 나라를 다스리게 하고, 그 위에 총리 셋을 두었다. 다니엘이 그 가운데 하나였다. 방백들이 맡은 일을 총리들에게 알리게 해서, 왕이 손해를 보지 않게 하려는 것이었다. 다니엘은 민첩한 마음을 지녀 다른 총리들과 방백들보다 뛰어났으므로, 왕은 그를 세워 온 나라를 다스리게 하려고 했다."},"say":{"who":"hyu","text":"총리는 셋, 그 가운데 한 사람이 다니엘이야. 일지에 적어 둘게."}},{"ref":"단 6:4-9","focus":"decree","text":{"t1":"다니엘의 허물을 찾지 못한 총리들과 다스리는 사람들은, 삼십 일 동안 왕 말고 다른 누구에게 무엇을 구하는 사람은 사자 굴에 넣는 법을 세워 달라고 했어요. 왕은 그 글에 도장을 찍었어요.","t2":"총리들과 다스리는 사람들은 나라 일에서 다니엘을 고소할 틈을 찾으려 했지만 찾지 못했어요. 다니엘이 충성되어 아무 허물이 없었기 때문이에요. 그 뒤에 그들이 어떻게 했는지는 5절부터 9절까지 차례대로 읽어 봐요.","t3":"총리들과 방백들은 나라 일에서 다니엘을 고소할 틈을 찾으려 했으나 아무 틈도 허물도 찾지 못했다. 그가 충성되어 그릇함도 허물도 없었기 때문이다. 그들은 다니엘의 하나님의 율법에 관한 일이 아니면 고소할 틈을 얻지 못하겠다고 말했다. 그래서 모여 왕에게 나아가, 이제부터 삼십 일 동안 왕 말고 어떤 신이나 사람에게 무엇이든 구하는 사람은 사자 굴에 던져 넣는다는 금령을 세워 달라고 했다. 또 메대와 바사의 고치지 못하는 규례를 따라 그 조서에 도장을 찍어, 다시 고치지 못하게 해 달라고 했다. 다리오 왕은 조서에 도장을 찍어 금령을 내렸다."},"say":{"who":"choeon","text":"사람들이 왕 앞에 모였어. 왕이 글에 도장을 찍었어."}},{"ref":"단 6:10","focus":"window","text":{"t1":"다니엘은 그 글에 도장이 찍힌 것을 알고도 집에 돌아갔어요. 예루살렘 쪽으로 창이 열린 방에서, 전에 하던 대로 무릎 꿇어 기도하고 하나님께 감사했어요.","t2":"다니엘은 조서에 도장이 찍힌 것을 알고도 자기 집으로 돌아갔어요. 그의 방에는 예루살렘 쪽으로 열린 창이 있었어요. 다니엘은 거기서 전에 하던 대로 하루 세 번 무릎을 꿇고 기도하며 하나님께 감사했어요.","t3":"다니엘은 조서에 도장이 찍힌 것을 알고도 자기 집으로 돌아가, 예루살렘 쪽으로 창이 열린 자기 방에서 기도했다."},"say":{"who":"hyu","text":"창은 예루살렘 쪽으로 열려 있어. 하루에 몇 번 기도했는지는 10절에서 찾아서 적자."}},{"ref":"단 6:11-15","focus":"king","text":{"t1":"그 사람들이 다니엘이 기도한 일을 왕에게 알리자, 왕은 몹시 근심하며 해가 질 때까지 다니엘을 건져 내려고 애썼어요. 그러나 그들은 왕이 세운 법은 고칠 수 없다고 말했어요.","t2":"그 사람들은 모여서 다니엘이 자기 하나님께 기도하며 구하는 것을 발견했어요. 그들은 왕에게 나아가, 사로잡혀 온 유다 사람 다니엘이 금령을 돌아보지 않고 하루 세 번 기도한다고 알렸어요. 왕은 몹시 근심하며 해가 질 때까지 다니엘을 건져 내려고 힘썼어요. 그러나 그들은 다시 와서, 왕이 세운 금령은 고칠 수 없다고 말했어요.","t3":"그 사람들은 함께 모여, 다니엘이 자기 하나님께 기도하며 구하고 있는 것을 찾아냈다. 그들은 왕에게 나아가 금령에 도장을 찍지 않았느냐고 물었고, 왕은 그 일이 메대와 바사의 고치지 못하는 규례대로 확실하다고 대답했다. 그 뒤에 그들이 다니엘을 두고 무엇이라고 아뢰었는지, 왕이 그 말을 듣고 어떠했고 해가 질 때까지 무엇을 했는지, 그 무리가 다시 와서 무엇이라고 했는지는 13절부터 15절까지 이어 읽어 보자."},"say":{"who":"choeon","text":"해가 지고 있어. 그 사람들이 다시 모여 왕에게 가."}},{"ref":"단 6:16-18","open":"단 6:16","focus":"den","text":{"t1":"왕의 명령으로 다니엘은 사자 굴에 던져졌고, 왕은 다니엘이 늘 섬기는 하나님이 그를 구해 주실 것이라고 말했어요. 사람들은 돌을 굴려다가 굴 어귀를 막았어요.","t2":"왕이 명하자 사람들이 다니엘을 끌고 와서 사자 굴에 던져 넣었어요. 왕은 다니엘에게, 그가 늘 섬기는 하나님이 그를 구해 주실 것이라고 말했어요. 돌을 굴려다가 굴 어귀를 막았고, 왕은 자기 도장과 귀인들의 도장을 찍어 봉했어요. 왕은 궁으로 돌아가 밤새도록 아무것도 먹지 않았고 잠도 자지 않았어요.","t3":"왕이 명하자 사람들이 다니엘을 끌고 와서 사자 굴에 던져 넣었다. 돌을 굴려다가 굴 어귀를 막았고, 왕은 자기 도장과 귀인들의 도장을 찍어 봉했다. 다니엘에게 내린 처분을 바꾸지 못하게 하려는 것이었다. 그때 왕이 다니엘에게 한 말과, 궁으로 돌아간 왕이 그 밤을 어떻게 보냈는지는 16절과 18절에 있다."},"say":{"who":"onwoo","text":"왕이 다니엘에게 한 말은 16절에 있어. 성경책에서 확인해 보자."}},{"ref":"단 6:19-23","open":"단 6:22","focus":"den","text":{"t1":"이튿날 새벽 왕이 급히 사자 굴로 가서 부르자, 다니엘은 하나님이 천사를 보내 사자들의 입을 막으셨다고 대답했어요. 굴에서 올라온 다니엘의 몸은 조금도 상하지 않았어요.","t2":"이튿날 새벽에 왕은 일어나 급히 사자 굴로 갔어요. 굴 가까이에 이르러 슬픈 소리로 다니엘을 부르며, 하나님이 사자들에게서 그를 구하실 수 있었느냐고 물었어요. 다니엘은 하나님이 천사를 보내어 사자들의 입을 막으셔서 사자들이 자기를 해치지 않았다고 대답했어요. 왕은 몹시 기뻐하며 다니엘을 굴에서 올리게 했고, 다니엘의 몸은 조금도 상하지 않았어요.","t3":"이튿날 왕은 새벽에 일어나 급히 사자 굴로 갔다. 다니엘이 있는 굴 가까이에 이르러, 살아 계신 하나님의 종 다니엘을 부르며 그가 항상 섬기는 하나님이 사자들에게서 그를 구원하실 수 있었느냐고 물었다. 왕이 어떤 소리로 불렀는지, 다니엘이 무엇이라고 대답했고 그 대답을 들은 왕이 어떠했는지, 굴에서 올린 다니엘의 몸이 어떠했고 본문이 그 까닭을 무엇이라고 적는지는 20절부터 23절까지 직접 읽어 보자."},"say":{"who":"onwoo","text":"다니엘이 왕에게 한 대답은 22절에 있어. 우리가 덧붙이지 말고 성경책에서 읽어 보자."}},{"ref":"단 6:24-28","open":"단 6:26","focus":"decree","text":{"t1":"다리오 왕은 온 땅에 글을 보내어, 자기 나라 사람들은 모두 다니엘의 하나님을 두려워하며 떨라고 했어요. 그분은 살아 계신 하나님이시고, 다니엘을 사자의 입에서 구하셨다고 썼어요.","t2":"왕의 명으로 다니엘을 참소한 사람들과 그 아내와 자식들이 사자 굴에 던져졌어요. 그 뒤 다리오 왕은 온 땅의 모든 백성에게 조서를 내려, 자기 나라 사람들은 모두 다니엘의 하나님 앞에서 떨고 두려워하라고 했어요. 왕이 왜 그렇게 하라고 했는지는 26절과 27절에서 찾아봐요. 다니엘은 다리오 왕 때와 바사 사람 고레스 왕 때에 형통했어요.","t3":"왕의 명령으로 다니엘을 참소한 사람들이 끌려왔고, 그들은 처자들과 함께 사자 굴에 던져졌다. 그들이 굴 바닥에 닿기도 전에 사자들이 그들을 움켰다. 그 뒤 다리오 왕은 온 땅의 모든 백성과 나라와 말이 다른 사람들에게 조서를 내렸다. 자기 나라가 다스리는 곳의 사람들은 모두 다니엘의 하나님 앞에서 떨고 두려워해야 한다고 했다. 그분은 살아 계신 하나님이시고 영원히 변하지 않으시며, 그 나라는 망하지 않고 그 권세는 끝이 없다고 썼다. 또 그분이 어떤 일을 하시는 분이며 다니엘에게 무엇을 하셨다고 썼는지는 27절에 있다. 다니엘은 다리오 왕이 다스리던 때와 바사 사람 고레스 왕이 다스리던 때에 형통했다."},"say":{"who":"hyu","text":"다리오 왕의 조서는 온 땅의 모든 백성에게 보낸 거야. 일지에 적어 둘게."}}],"gates":{"t1":[{"type":"find","ref":"단 6:1","prompt":"성경책에서 다니엘 6장 1절을 찾아 읽어 보세요.","confirm":{"prompt":"다리오 왕은 나라를 다스릴 방백을 몇 명 세웠나요?","options":[{"label":"백이십 명","ok":true},{"label":"세 명","basis":"단 6:2"},{"label":"칠십 명","basis":"민 11:16"}]}},{"type":"multi","ref":"단 6:20","prompt":"성경책에서 다니엘 6장 20절을 찾아 읽어 보세요.","confirm":{"prompt":"왕이 다니엘이 있는 굴 가까이에 와서 한 일을 모두 고르세요.","options":[{"label":"슬픈 목소리로 다니엘을 불렀어요","ok":true},{"label":"밤새 아무것도 먹지 않았어요","basis":"단 6:18"},{"label":"다니엘을 살아 계신 하나님의 종이라고 불렀어요","ok":true},{"label":"굴 안으로 내려갔어요","basis":"본문에 없음"},{"label":"다니엘의 하나님이 그를 사자들에게서 구하실 수 있었느냐고 물었어요","ok":true}]}}],"t2":[{"type":"find","ref":"단 6:1-3","prompt":"성경책에서 다니엘 6장 1절부터 3절까지 읽어 보세요.","confirm":{"prompt":"다리오 왕이 다니엘을 세워 온 나라를 다스리게 하려고 한 까닭은 무엇인가요?","options":[{"label":"다니엘이 마음이 민첩하여 다른 총리들과 방백들보다 뛰어났기 때문에","ok":true},{"label":"총리 셋 가운데 다니엘에게만 방백들이 일을 보고하게 되어 있었기 때문에","basis":"본문에 없음"},{"label":"다니엘이 총리들과 방백들 가운데 가장 나이가 많았기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"단 6:4-9","prompt":"성경책에서 다니엘 6장 4절부터 9절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["총리들과 방백들은 다니엘의 허물을 찾으려 했으나 찾지 못했다","그들은 다니엘의 하나님의 율법에 관한 일 말고는 틈이 없다고 했다","그들이 모여 왕에게 나아갔다","그들이 왕에게 한 금령을 세워 달라고 했다","다리오 왕이 그 글에 도장을 찍었다"]}],"t3":[{"type":"find","refs":["단 6:9","단 6:14","단 6:15"],"prompt":"다니엘 6장 9절, 14절, 15절을 함께 찾아 읽어 보자.","confirm":{"prompt":"세 곳을 이어 읽으면, 왕이 해가 질 때까지 애썼는데도 다니엘을 건져 내지 못한 정황은 어떠한가?","options":[{"label":"왕은 이미 금령의 조서에 도장을 찍었고, 해가 질 때까지 다니엘을 건지려고 힘을 다했지만, 그 무리는 왕이 세운 금령과 법도는 고칠 수 없다고 말했다","ok":true},{"label":"왕은 이미 금령의 조서에 도장을 찍었고, 해가 질 때까지 다니엘을 건지려고 힘을 다했지만, 그 무리는 총리와 방백들이 모두 그 일에 반대한다고 말했다","basis":"본문에 없음"},{"label":"왕은 이미 금령의 조서에 도장을 찍었고, 해가 질 때까지 금령을 고치려고 애썼지만, 다니엘이 스스로 사자 굴로 가겠다고 하며 왕을 말렸다","basis":"본문에 없음"}]}},{"type":"match","refs":["단 6:3","단 6:5","단 6:28"],"prompt":"다니엘 6장 3절, 5절, 28절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"단 6:3","text":"민첩한 마음을 지녀 다른 총리들과 방백들보다 뛰어났다"},{"ref":"단 6:5","text":"고소하려는 사람들이, 그의 하나님의 율법에 관한 일이 아니면 틈을 얻지 못하겠다고 말했다"},{"ref":"단 6:28","text":"다리오와 고레스가 다스리던 때에 형통했다"}],"after":"세 곳을 이으면, 다니엘은 뛰어났고 그를 고소하려는 사람들조차 그의 하나님의 율법에 관한 일 말고는 틈을 찾지 못했으며, 다니엘은 다리오와 고레스가 다스리던 때에 형통했다."}]},"cards":[{"ref":"단 6:10","title":"전에 하던 대로 하루 세 번"},{"ref":"단 6:26","title":"사시는 하나님"}],"close":{"t1":{"kind":"prayer","text":"하나님, 다니엘이 전에 하던 대로 기도한 이야기를 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 다니엘 6장 16절부터 23절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"단 6:1-28에서 새로 알게 된 사실을 한 가지 적어 보자."}},"quests":[{"part":"lens","name":"렌즈","line":"렌즈를 찾았어! 다니엘의 집에서 조금 떨어진 곳에 놓여 있었네.","found":"탐지기가 창이 예루살렘 쪽으로 열린 다니엘의 집 쪽을 가리켜요.","say":{"who":"hyu","text":"탐지기 바늘이 다니엘의 집 쪽으로 돌아갔어. 창이 예루살렘 쪽으로 열려 있다고 일지에 적어 둘게."},"q":{"t1":{"type":"find","ref":"단 6:10","prompt":"성경책에서 다니엘 6장 10절을 찾아 읽어 보세요.","confirm":{"prompt":"다니엘은 하루에 몇 번 기도했나요?","options":[{"label":"세 번","ok":true},{"label":"한 번","basis":"본문에 없음"},{"label":"일곱 번","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"단 6:7-10","prompt":"성경책에서 다니엘 6장 7절부터 10절까지 읽어 보세요.","confirm":{"prompt":"다니엘이 자기 집에서 기도한 일이 금령을 어긴 일이 되는 까닭은 무엇인가요?","options":[{"label":"금령은 삼십 일 동안 왕 말고 다른 누구에게 빌어도 사자 굴에 넣는다는 것이었는데, 다니엘은 자기 하나님께 기도하며 감사했기 때문에","ok":true},{"label":"금령은 삼십 일 동안 자기 집에 돌아가지 말고 왕궁에 머물라는 것이었는데, 다니엘은 조서를 알고도 자기 집으로 돌아가 기도했기 때문에","basis":"본문에 없음"},{"label":"금령은 삼십 일 동안 예루살렘 쪽을 향해 기도하는 사람을 사자 굴에 넣는다는 것이었는데, 다니엘은 예루살렘 쪽으로 창을 열고 기도했기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["단 6:10","단 6:13"],"prompt":"다니엘 6장 10절과 13절을 함께 찾아 읽어 보자.","confirm":{"prompt":"다니엘이 하루 세 번 기도한 일을 10절과 13절은 각각 어떻게 말하는가?","options":[{"label":"10절은 다니엘이 금령을 알고도 전에 하던 대로 무릎 꿇어 기도하고 하나님께 감사했다고 적고, 13절에서 고소한 사람들은 그가 왕과 금령을 돌아보지 않고 기도한다고 아뢰었다","ok":true},{"label":"10절은 다니엘이 금령을 알고 나서 전과 달리 무릎을 꿇지 않고 선 채로 기도했다고 적고, 13절에서 고소한 사람들은 그가 왕과 금령을 돌아보지 않고 기도한다고 아뢰었다","basis":"본문에 없음"},{"label":"10절은 다니엘이 금령을 알고도 전에 하던 대로 무릎 꿇어 기도했다고 적고, 13절에서 고소한 사람들은 그가 다른 총리들을 해치게 해 달라고 하루 세 번 기도한다고 아뢰었다","basis":"본문에 없음"}]}}}},{"part":"spring","name":"용수철","line":"용수철을 찾았어! 굴 어귀에서 멀찍이 떨어진 땅 위에 있었어.","found":"탐지기가 사자 굴 어귀 쪽을 가리켜요.","say":{"who":"onwoo","text":"굴 가까이는 가지 말자. 우리는 지켜보는 사람이야."},"q":{"t1":{"type":"find","ref":"단 6:17","prompt":"성경책에서 다니엘 6장 17절을 찾아 읽어 보세요.","confirm":{"prompt":"굴 어귀를 막은 돌에는 누구의 도장을 찍어 봉했나요?","options":[{"label":"왕의 도장과 귀인들의 도장","ok":true},{"label":"왕의 도장 하나만","basis":"단 6:9"},{"label":"다니엘의 도장","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"단 6:16-17","prompt":"성경책에서 다니엘 6장 16절과 17절을 읽어 보세요.","confirm":{"prompt":"굴 어귀를 막은 돌에 왕의 도장과 귀인들의 도장을 찍어 봉한 까닭은 무엇인가요?","options":[{"label":"다니엘에게 내린 처분을 바꾸지 못하게 하려고","ok":true},{"label":"사자들이 굴 밖으로 나오지 못하게 하려고","basis":"본문에 없음"},{"label":"굴이 어디 있는지 사람들에게 알리려고","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["단 6:16","단 6:18","단 6:19"],"prompt":"다니엘 6장 16절, 18절, 19절을 함께 찾아 읽어 보자.","confirm":{"prompt":"세 곳을 이어 읽으면, 다니엘이 굴에 있던 밤에 왕은 어떠했는가?","options":[{"label":"굴에 넣을 때 다니엘에게 그가 늘 섬기는 하나님이 구원하시리라고 말했고, 궁에 돌아가 밤새 금식하며 풍악을 그치게 하고 잠을 자지 않았으며, 새벽이 되자 급히 굴로 갔다","ok":true},{"label":"굴에 넣을 때 다니엘에게 아무 말도 하지 않았고, 궁에 돌아가 밤새 잔치를 열고 풍악을 울리며 편히 잤으며, 새벽이 되자 급히 굴로 갔다","basis":"본문에 없음"},{"label":"굴에 넣을 때 다니엘에게 그가 늘 섬기는 하나님이 구원하시리라고 말했고, 궁에 돌아가 밤새 신하들과 나라 일을 의논하며 잠을 자지 않았으며, 새벽이 되자 급히 굴로 갔다","basis":"본문에 없음"}]}}}},{"part":"antenna","name":"안테나","line":"안테나를 찾았어! 왕궁과 사자 굴이 건너다보이는 빈터에 있었네.","found":"탐지기가 왕궁과 사자 굴 사이 쪽을 가리켜요.","say":{"who":"choeon","text":"저기 왕궁이 보여. 굴에서 떨어진 쪽에서만 찾자."},"q":{"t1":{"type":"find","ref":"단 6:23","prompt":"성경책에서 다니엘 6장 23절을 찾아 읽어 보세요.","confirm":{"prompt":"이튿날 새벽 사자 굴 앞에서 다니엘의 대답을 들은 왕은 어떠했나요?","options":[{"label":"몹시 기뻐했어요","ok":true},{"label":"몹시 근심했어요","basis":"단 6:14"},{"label":"크게 노했어요","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"단 6:19-23","prompt":"성경책에서 다니엘 6장 19절부터 23절까지 읽어 보세요.","confirm":{"prompt":"굴에서 올린 다니엘의 몸이 조금도 상하지 않은 까닭을 본문은 무엇이라고 적나요?","options":[{"label":"다니엘이 자기 하나님을 의뢰했기 때문에","ok":true},{"label":"사자들이 이미 배불리 먹었기 때문에","basis":"본문에 없음"},{"label":"왕이 몰래 사자들을 묶어 두게 했기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["단 6:20","단 6:23"],"prompt":"다니엘 6장 20절과 23절을 함께 찾아 읽어 보자.","confirm":{"prompt":"새벽에 굴에 이른 왕이 다니엘을 부를 때와 다니엘의 대답을 들은 뒤, 왕의 마음은 어떻게 달랐는가?","options":[{"label":"20절은 왕이 슬픈 소리로 다니엘을 불렀다고 적고, 23절은 다니엘의 대답을 들은 왕이 몹시 기뻐했다고 적는다","ok":true},{"label":"20절은 왕이 노한 소리로 다니엘을 불렀다고 적고, 23절은 다니엘의 대답을 들은 왕이 몹시 부끄러워했다고 적는다","basis":"본문에 없음"},{"label":"20절은 왕이 담담한 목소리로 다니엘을 불렀다고 적고, 23절은 다니엘의 대답을 들은 왕이 몹시 놀라 두려워했다고 적는다","basis":"본문에 없음"}]}}}}],"mission":{"call":{"t1":"여기는 다리오 왕이 다스리는 나라예요. 비상 착륙하면서 렌즈가 깨지고 용수철이 끊어지고 안테나가 부러졌어요. 대신 쓸 재료 세 가지를 찾아 주세요.","t2":"타임머신이 다리오 왕이 다스리는 나라에 비상 착륙했어요. 렌즈가 깨지고 용수철이 끊어지고 안테나가 부러져서 통신만 겨우 이어져 있어요. 이 시대에는 그런 부속이 없으니, 그곳에서 구할 수 있는 재료 세 가지로 대신 만들어야 해요.","t3":"타임머신은 다리오 왕이 다스리는 나라에 비상 착륙했다. 렌즈가 깨지고 용수철이 끊어지고 안테나가 부러져 통신만 겨우 이어져 있다. 이 시대에는 맞는 부속이 없으니 그곳에서 얻을 수 있는 재료 세 가지로 대신 만들어야 한다. 탐지기가 가리키는 곳으로 가되, 어떤 일에도 끼어들지 말고 떨어진 곳에서 지켜보아야 한다."},"materials":[{"key":"leaf","name":"마른 잎","basis":"단 6:10","use":"마른 잎에 작은 구멍을 뚫으면 렌즈 대신 쓸 수 있어요.","how":"다니엘의 집이 건너다보이는 빈터 땅에 떨어져 있던 마른 잎 하나를 주웠다. 집과 창에는 다가가지 않았다.","line":"마른 잎을 주웠어! 다니엘의 집이 건너다보이는 빈터에 떨어져 있었어."},{"key":"twig","name":"가는 나뭇가지","basis":"단 6:17","use":"휘었다가 다시 펴지는 가는 나뭇가지를 용수철 대신 쓸 수 있어요.","how":"굴 어귀에서 멀찍이 떨어진 땅 위에 떨어져 있던 가는 나뭇가지 하나를 주웠다. 굴 가까이에는 가지 않았다.","line":"가는 나뭇가지를 주웠어! 굴 어귀에서 멀찍이 떨어진 땅 위에 있었어."},{"key":"grass","name":"마른 풀 줄기","basis":"단 6:18-19","use":"마른 풀 줄기 여러 가닥을 꼬아서 안테나 줄 대신 쓸 수 있어요.","how":"왕궁과 사자 굴이 건너다보이는 빈터, 굴에서 떨어진 땅에 떨어져 있던 마른 풀 줄기 몇 가닥을 주웠다. 왕궁 쪽으로는 가지 않았다.","line":"마른 풀 줄기를 주웠어! 왕궁과 사자 굴이 건너다보이는 빈터에 있었어."}],"companion":{"who":"다니엘","ref":"단 6:2-3","when":"after","talks":[{"ask":{"who":"hyu","text":"다니엘 님, 왕이 새벽에 굴에 와서 불렀을 때 맨 처음 뭐라고 대답하셨어요?"},"answer":{"t1":"다니엘은 먼저 왕에게 오래오래 사시라고 인사했어요.","t2":"다니엘은 왕의 물음에 먼저 이렇게 대답했어요. 왕이 오래오래 사시기를 바란다고요.","t3":"다니엘은 왕에게 먼저, 왕이 영원히 살기를 바란다고 아뢰었다."},"ref":"단 6:21","open":"단 6:21"},{"ask":{"who":"choeon","text":"사자들은 왜 다니엘 님을 해치지 않았어요?"},"answer":{"t1":"다니엘은 하나님이 천사를 보내어 사자들의 입을 막으셨다고 말했어요. 그래서 사자들이 자기를 해치지 않았다고 했어요.","t2":"다니엘은 왕에게, 자기 하나님이 천사를 보내어 사자들의 입을 막으셨다고 말했어요. 그래서 사자들이 자기를 상하게 하지 않았다고 했어요.","t3":"다니엘은 왕에게, 자기 하나님이 천사를 보내셔서 사자들의 입을 봉하셨고 그래서 사자들이 자기를 상하게 하지 않았다고 말했다."},"ref":"단 6:22","open":"단 6:22"},{"ask":{"who":"onwoo","text":"다니엘 님은 왕에게 잘못한 일이 있었어요?"},"answer":{"t1":"다니엘은 왕 앞에서도 해를 끼친 일이 없다고 말했어요.","t2":"다니엘은 하나님 앞에서 자기에게 죄가 없음이 밝히 드러났다고 말했어요. 그리고 왕 앞에서도 해를 끼친 일이 없다고 말했어요.","t3":"다니엘은 하나님 앞에서 자기의 죄 없음이 분명히 드러났다고 말했다. 또 왕 앞에서도 자기는 해를 끼친 일이 없다고 아뢰었다."},"ref":"단 6:22","open":"단 6:22"}]},"today":[{"q":"다니엘은 왜 예루살렘 쪽으로 열린 창에서 기도했어요?","a":{"t1":"다니엘 6장은 그 까닭을 말하지 않아요. 솔로몬은 자기가 지은 성전을 두고, 백성이 사로잡혀 간 땅에서 이 성과 성전 쪽을 향해 기도하면 들어 달라고 구했어요. 두 이야기가 이어진다고 성경이 직접 말하지는 않아요.","t2":"다니엘 6장은 다니엘이 예루살렘 쪽으로 열린 창에서 기도했다고만 적고, 까닭은 말하지 않아요. 솔로몬은 자기가 지은 성전을 두고 드린 기도에서, 백성이 사로잡혀 간 땅에서 주께 돌아와 조상에게 주신 땅과 택하신 성과 성전 쪽을 향해 기도하면 하늘에서 들어 달라고 구했어요. 다니엘 6장이 이 기도와 이어진다고 성경이 직접 말하지는 않아요.","t3":"다니엘 6장은 다니엘이 예루살렘 쪽으로 열린 창에서 기도했다고 기록할 뿐, 그 까닭은 말하지 않는다. 솔로몬은 자기가 지은 성전을 두고 드린 기도에서, 백성이 사로잡혀 간 적국의 땅에서 온 마음으로 돌아와 조상에게 주신 땅과 택하신 성과 성전 있는 쪽을 향해 기도하면 하늘에서 들어 달라고 구했다. 다니엘 6장이 이 기도를 가리킨다고 성경이 직접 말하지는 않는다. 성경은 여기까지 말한다."},"refs":["단 6:10","왕상 8:48-49"]},{"q":"다니엘은 기도하면 사자 굴에 던져진다는 것을 알고 있었어요?","a":{"t1":"다니엘은 그 금령에 왕의 도장이 찍힌 것을 알았어요. 그래도 집에 돌아가 전에 하던 대로 하루 세 번 기도했어요.","t2":"금령은 삼십 일 동안 왕 말고 다른 신이나 사람에게 구하는 사람을 사자 굴에 던져 넣는다는 것이었어요. 성경은 다니엘이 그 글에 왕의 도장이 찍힌 것을 알았지만, 자기 집에 가서 전에 하던 대로 기도했다고 적어요. 그때 다니엘의 속마음은 적지 않아요.","t3":"금령의 내용은 삼십 일 동안 왕 외에 어느 신이나 사람에게 구하는 자를 사자 굴에 던져 넣는다는 것이었다. 성경은 다니엘이 그 글에 왕의 도장이 찍혔음을 알았으나, 자기 집에 가서 전에 하던 대로 하루 세 번 무릎을 꿇고 기도하며 하나님께 감사했다고 기록한다. 그때 다니엘이 무엇을 생각했는지는 적지 않는다. 성경은 여기까지 말한다."},"refs":["단 6:7-10"]}],"help":{"who":"다니엘","steps":[{"kind":"watch","after":2,"title":"곁에서 보기 · 창이 열린 방의 기도","basis":"단 6:10","text":{"t1":"다니엘이 집에 돌아가 전에 하던 대로 무릎을 꿇고 기도해요. 우리는 집에 다가가지 않고 빈터에서 멀리 봐요.","t2":"다니엘은 조서에 도장이 찍힌 것을 알고도 집에 돌아가, 예루살렘 쪽으로 창이 열린 방에서 전에 하던 대로 기도하며 하나님께 감사해요. 기도는 다니엘이 하는 일이에요. 우리는 집에 다가가지 않고 빈터에서 멀리 봐요.","t3":"다니엘이 집에 돌아가 예루살렘 쪽으로 창이 열린 방에서 기도한다. 본문은 그 기도의 말을 적지 않는다. 탐험대는 집과 창에 다가가지 않고 빈터에서 멀리 본다."},"say":{"who":"choeon","text":"다니엘이 집에 돌아갔어. 우리는 집 쪽으로 가지 말고 멀리서만 보자."}},{"kind":"stay","after":4,"title":"새벽까지 기다리기","basis":"단 6:18-19","text":{"t1":"왕은 궁으로 돌아가 아무것도 먹지 않고 잠도 자지 않아요. 우리도 굴에서 멀리 떨어진 빈터에서 새벽을 기다려요.","t2":"굴 어귀는 돌로 막히고 도장으로 봉해졌어요. 왕은 궁으로 돌아가 금식하며 잠을 자지 않아요. 우리는 굴에 다가가지 않고, 멀리 떨어진 빈터에서 새벽을 기다려요.","t3":"굴 어귀는 돌로 막혀 왕과 귀인들의 도장으로 봉해졌다(6:17). 왕은 궁으로 돌아갔다. 탐험대는 굴에 다가가지 않고, 멀리 떨어진 빈터에서 새벽이 오기를 기다린다."},"wait":"빈터에서 새벽 기다리기","say":{"who":"onwoo","text":"굴 가까이는 가지 않을 거야. 여기서 새벽까지 기다리자."}},{"kind":"do","after":5,"title":"일지에 그날의 때 적기","basis":"단 6:14-19","text":{"t1":"이건 탐험대의 일이에요. 우리는 빈터에서 탐험 일지를 펴고, 해 질 때와 밤과 새벽에 있었던 일을 차례대로 적어요.","t2":"이것은 성경에 적힌 일이 아니라 탐험대의 일이에요. 우리는 굴에서 멀리 떨어진 빈터에서 탐험 일지를 펴고, 해가 질 때까지와 밤새와 이튿날 새벽에 있었던 일을 성경책을 보며 차례대로 적어요.","t3":"탐험대는 굴에서 떨어진 빈터에서 탐험 일지를 편다. 해가 질 때까지(6:14), 밤새(6:18), 이튿날 새벽(6:19)에 있었던 일을 성경책을 보며 차례대로 적는다. 본문에 적힌 일이 아니라 탐험대의 일이며, 굴과 돌과 도장에는 다가가지 않는다."},"tasks":["해 질 때의 일 적기(6장 14절)","밤의 일 적기(6장 18절)","새벽의 일 적기(6장 19절)"],"done":{"who":"hyu","text":"해 질 때, 밤, 새벽. 때를 차례대로 다 적었어."}},{"kind":"ask","after":"gates","title":"사자 굴에서 건져진 일은 무슨 뜻이에요?","basis":"단 6:25-27","by":"최현 박사","ask":{"who":"choeon","text":"다니엘이 사자 굴에서 상하지 않고 올라온 일은 무슨 뜻이에요?"},"answer":{"t1":"다니엘 6장 끝에서 다리오 왕은 온 땅에 조서를 내렸어요. 다니엘의 하나님은 살아 계신 하나님이시고, 다니엘을 사자의 입에서 건져 내셨다고 썼어요(6:26-27).","t2":"다니엘 6장 끝에서 다리오 왕은 온 땅의 모든 백성에게 조서를 내렸어요. 자기 나라 사람들은 모두 다니엘의 하나님을 떨며 두려워하라고 했고, 그분은 살아 계신 하나님이시며 영원히 변하지 않으신다고 썼어요. 그분은 구원하시고 건져 내시는 분으로서 다니엘을 사자의 입에서 건져 내셨다고 썼어요(6:26-27).","t3":"다니엘 6장 끝에서 다리오 왕은 온 땅의 모든 백성과 나라와 말이 다른 사람들에게 조서를 내렸다(6:25). 왕은 자기 나라 사람들은 모두 다니엘의 하나님을 떨며 두려워해야 한다고 했고, 그분이 살아 계신 하나님이시며 영원히 변하지 않으시고, 그 나라는 망하지 않으며 그 권세는 끝이 없다고 썼다(6:26). 또 그분은 구원하시고 건져 내시며 하늘과 땅에서 이적과 기사를 베푸시는 분으로서 다니엘을 사자의 입에서 건져 내셨다고 썼다(6:27). 성경은 여기까지 말한다."},"read":{"t1":{"type":"find","ref":"단 6:27","prompt":"성경책에서 다니엘 6장 27절을 찾아 읽어 보세요.","confirm":{"prompt":"다리오 왕은 하나님이 하늘과 땅에서 무엇을 행하시는 분이라고 썼나요?","options":[{"label":"이적과 기사","ok":true},{"label":"전쟁에서 이기는 일","basis":"본문에 없음"},{"label":"큰 궁전을 짓는 일","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"단 6:25-27","prompt":"성경책에서 다니엘 6장 25절부터 27절까지 읽어 보세요.","confirm":{"prompt":"다리오 왕이 자기 나라 사람들에게 다니엘의 하나님을 떨며 두려워하라고 한 까닭은 무엇인가요?","options":[{"label":"그분은 살아 계신 하나님이시고 영원히 변하지 않으시며, 다니엘을 사자의 입에서 건져 내셨기 때문에","ok":true},{"label":"다니엘을 고소한 사람들이 왕의 명으로 아내와 자식들과 함께 사자 굴로 던져졌기 때문에","basis":"단 6:24"},{"label":"바사 사람 고레스 왕이 다니엘의 하나님을 두려워하라는 조서를 먼저 내렸기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["단 6:22","단 6:23","단 6:27"],"prompt":"다니엘 6장 22절, 23절, 27절을 함께 찾아 읽어 보자.","confirm":{"prompt":"세 곳을 이어 읽으면, 다니엘이 상하지 않은 일을 다니엘과 본문과 다리오 왕은 각각 어떻게 말하는가?","options":[{"label":"다니엘은 하나님이 천사를 보내 사자들의 입을 봉하셨다고 했고, 본문은 그가 자기 하나님을 믿고 의지했기 때문이라고 적으며, 다리오 왕은 하나님이 다니엘을 사자의 입에서 건져 내셨다고 썼다","ok":true},{"label":"다니엘은 하나님이 천사를 보내 사자들의 입을 봉하셨다고 했고, 본문은 왕이 밤새 금식하며 빌었기 때문이라고 적으며, 다리오 왕은 하나님이 다니엘을 사자의 입에서 건져 내셨다고 썼다","basis":"본문에 없음"},{"label":"다니엘은 하나님이 천사를 보내 사자들의 입을 봉하셨다고 했고, 본문은 그가 그날 밤 잠들지 않고 깨어 있었기 때문이라고 적으며, 다리오 왕은 하나님이 다니엘을 온 나라 위에 세우셨다고 썼다","basis":"본문에 없음"}]}}}}]}},"has3d":true,"epic":false},"OT-37":{"id":"OT-37","era":10,"title":"고레스의 조서와 성전을 다시 지음","ref":"스 1:1-11","place":"바사 왕 고레스의 나라, 바벨론, 유다 예루살렘","review":{"required":false,"topics":[],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"스 1:1-4","open":"스 1:1","focus":"cyrus","text":{"t1":"바사 왕 고레스가 왕이 된 첫해에, 여호와께서 고레스의 마음을 움직이셨어요. 왕은 온 나라에 조서를 내려, 하나님의 백성은 예루살렘으로 올라가 여호와의 전을 지으라고 했어요.","t2":"바사 왕 고레스가 다스린 첫해에 여호와께서 고레스 왕의 마음을 움직이셨어요. 왜 그렇게 하셨는지는 1절에서 찾아봐요. 왕은 온 나라에 알리고 조서도 내려, 하나님의 백성은 누구든지 유다 예루살렘으로 올라가 여호와의 전을 지으라고 했어요.","t3":"바사 왕 고레스의 원년에, 여호와께서는 고레스 왕의 마음을 움직이셨다. 무엇을 이루시려고 그러셨는지는 1절에 있다. 고레스는 온 나라에 알리고 글로도 내렸다. 그 조서에서 고레스는 하늘의 하나님 여호와께서 세상 모든 나라를 자기에게 주셨고 유다 예루살렘에 전을 지으라고 자기에게 명하셨다고 했다. 그 백성 된 사람은 누구든지 예루살렘으로 올라가 여호와의 전을 지으라고 했고, 그들이 머물러 살던 곳의 사람들은 은과 금과 물건과 짐승으로 돕고 하나님의 전을 위한 예물도 기쁘게 드리라고 했다."},"say":{"who":"onwoo","text":"고레스 왕이 온 나라에 조서를 내렸어. 일지에 적어 둘게."}},{"ref":"스 1:5-6","focus":"people","text":{"t1":"유다와 베냐민의 족장들, 제사장들, 레위 사람들, 그리고 하나님이 마음을 움직이신 사람들이 모두 올라가려고 일어났어요. 둘레에 사는 사람들은 은그릇과 금과 짐승으로 도왔어요.","t2":"유다와 베냐민의 족장들, 제사장들, 레위 사람들이 일어났어요. 하나님이 마음을 움직이셔서 올라가 예루살렘에 여호와의 전을 지으려는 사람들도 모두 일어났어요. 그 둘레의 사람들은 은그릇과 금과 물건과 짐승과 보물로 돕고 예물도 기쁘게 드렸어요.","t3":"유다와 베냐민의 족장들, 제사장들, 레위 사람들, 그리고 하나님께 마음이 감동되어 올라가 예루살렘에 여호와의 전을 지으려는 사람들이 모두 일어났다. 그 둘레의 사람들은 은그릇과 금, 그 밖의 물건, 짐승, 보물로 그들을 도왔고 그 밖에 예물도 기쁘게 드렸다."},"say":{"who":"hyu","text":"일어난 사람들을 적어 둘게. 유다와 베냐민의 족장들, 제사장들, 레위 사람들."}},{"ref":"스 1:7-11","focus":"vessels","text":{"t1":"고레스 왕은 느부갓네살이 옛날에 예루살렘에서 가져간 여호와의 전 그릇들을 꺼냈어요. 세스바살이 그 그릇들을 모두 예루살렘으로 가지고 왔어요.","t2":"느부갓네살이 옛날에 예루살렘에서 가져다가 자기 신들의 당에 둔 여호와의 전 그릇들이 있었어요. 그 그릇들이 누구의 손을 거쳐 어디로 갔는지는 7절부터 11절까지 차례대로 읽어 봐요.","t3":"고레스 왕은 여호와의 전 그릇들을 꺼냈다. 느부갓네살이 옛적에 예루살렘에서 가져다가 자기 신들의 당에 둔 것이다. 고지기 미드르닷을 시켜 그것을 꺼내 세어서 유다 목백 세스바살에게 넘기게 했다. 본문은 금반 서른, 은반 천, 칼 스물아홉, 금대접 서른, 은대접 사백열, 그 밖의 그릇 천을 적고, 금그릇과 은그릇이 모두 오천사백이라고 한다. 사로잡혔던 사람들이 바벨론에서 예루살렘으로 올라올 때 세스바살이 그 그릇들을 다 가지고 왔다."},"say":{"who":"choeon","text":"금그릇이랑 은그릇이 정말 많아! 하나하나 세어서 넘겨주고 있어."}},{"ref":"스 3:8-11","focus":"foundation","text":{"t1":"예루살렘에 온 지 이 년째 이월에 스룹바벨과 예수아와 돌아온 사람들이 일을 시작했고, 건축자들이 여호와의 전 기초를 놓았어요. 그때 제사장과 레위 사람이 한 일은 성경에서 찾아봐요.","t2":"예루살렘에 있는 하나님의 전에 이른 지 이 년째 이월에 스룹바벨과 예수아와 돌아온 사람들이 일을 시작했어요. 스무 살 이상인 레위 사람들을 세워 일을 감독하게 했어요. 건축자들이 여호와의 전 기초를 놓을 때, 예복을 입은 제사장들은 나팔을, 아삽 자손인 레위 사람들은 제금을 들고 여호와를 찬송했어요. 모든 백성도 큰 소리로 즐겁게 외쳤는데, 그 까닭은 11절에서 찾아봐요.","t3":"스룹바벨(스알디엘의 아들)과 예수아(요사닥의 아들), 그 형제인 제사장들과 레위 사람들이 여호와의 전 일을 시작했고, 스무 살 이상인 레위 사람들을 세워 그 일을 감독하게 했다. 건축자들이 전의 기초를 놓을 때, 예복을 입은 제사장들은 나팔을, 아삽 자손인 레위 사람들은 제금을 들고 섰다. 그들은 이스라엘 왕 다윗이 정한 대로 여호와를 찬송했고, 모든 백성은 큰 소리로 외쳤다. 그 일을 언제 시작했고 또 누가 함께했는지, 제사장들과 레위 사람들이 서로 화답하며 무엇이라고 찬송했는지는 8절과 11절에서 직접 읽어 보자."},"say":{"who":"choeon","text":"기초가 놓이고 있어! 사람들이 큰 소리로 외치고 있어."}},{"ref":"스 3:12-13","focus":"elders","text":{"t1":"첫 성전을 보았던 노인들은 큰 소리로 울었고, 다른 많은 사람은 기뻐서 외쳤어요. 그 소리가 멀리까지 들렸어요.","t2":"제사장들, 레위 사람들, 족장들 가운데에는 첫 성전을 보았던 노인이 여럿 있었어요. 그들은 이 전의 기초가 놓이는 것을 보고 큰 소리로 울었고, 또 여러 사람은 기뻐서 크게 외쳤어요. 백성이 외치는 소리가 멀리까지 들려서, 기뻐하는 소리와 우는 소리를 가려낼 수 없었어요.","t3":"제사장들, 레위 사람들, 족장들 가운데에는 첫 성전을 보았던 노인이 여럿 있었다. 그들은 이제 이 전의 기초가 놓이는 것을 보고 큰 소리로 울었고, 또 많은 사람은 기뻐하며 크게 외쳤다. 백성이 크게 외쳐 그 소리가 멀리까지 들렸으므로, 사람들은 기뻐 외치는 소리와 우는 소리를 가려낼 수 없었다."},"say":{"who":"hyu","text":"우는 소리와 기뻐 외치는 소리가 함께 들려. 어느 쪽 소리인지 가려낼 수 없다고 일지에 적어 둘게."}},{"ref":"스 6:14-15","focus":"temple","text":{"t1":"유다의 장로들은 선지자 학개와 스가랴의 권면을 받아 전을 잘 지어 나갔어요. 전을 다 지은 날은 다리오 왕 육년 아달월 삼일이었어요.","t2":"유다 사람의 장로들은 선지자 학개와 스가랴가 권면하여 전 짓는 일을 잘 해 나갔어요. 이스라엘 하나님의 명령을 따르고, 바사의 왕 고레스, 다리오, 아닥사스다가 내린 조서를 따라 전을 지었어요. 전을 다 지은 날은 다리오 왕 육년 아달월 삼일이었어요.","t3":"유다 사람의 장로들은 선지자 학개와 스가랴(잇도의 손자)가 권면하였으므로 전 짓는 일이 잘되어 갔다. 그들은 이스라엘 하나님의 명령을 따르고, 바사의 왕 고레스, 다리오, 아닥사스다가 내린 조서를 따라 전을 지어 마쳤다. 전 짓는 일을 마친 날은 다리오 왕 육년 아달월 삼일이었다."},"say":{"who":"hyu","text":"전을 다 지은 날짜가 적혀 있어. 다리오 왕 육년 아달월 삼일. 일지에 적어 둘게."}},{"ref":"스 6:16-18","focus":"dedication","text":{"t1":"이스라엘 자손과 제사장들, 레위 사람들, 그 밖에 사로잡혔던 사람들의 자손이 기쁘게 하나님의 전 봉헌식을 했어요. 제사장과 레위 사람을 세워서, 예루살렘에서 하나님 섬기는 일을 맡게 했어요.","t2":"이스라엘 자손과 제사장들, 레위 사람들, 그 밖에 사로잡혔던 사람들의 자손이 기쁘게 하나님의 전 봉헌식을 했어요. 수소 백 마리와 숫양 이백 마리와 어린 양 사백 마리를 드렸고, 이스라엘 지파의 수대로 숫염소 열두 마리를 온 이스라엘을 위한 속죄제로 드렸어요. 그리고 모세의 책에 적힌 대로 제사장과 레위 사람을 차례대로 세워서, 예루살렘에서 하나님 섬기는 일을 맡게 했어요.","t3":"이스라엘 자손과 제사장들, 레위 사람들, 그 밖에 사로잡혔던 사람들의 자손이 기쁘게 하나님의 전 봉헌식을 했다. 봉헌식에서 수소 백 마리, 숫양 이백 마리, 어린 양 사백 마리를 드렸고, 이스라엘 지파의 수대로 숫염소 열두 마리를 온 이스라엘을 위한 속죄제로 드렸다. 또 제사장은 분반을 따라, 레위 사람은 반차를 따라 세워서 예루살렘에서 하나님 섬기는 일을 맡게 했는데, 모세의 책에 적힌 대로 한 것이다."},"say":{"who":"onwoo","text":"모세의 책에 적힌 대로 했대. 그 말이 적힌 곳을 성경책에서 찾아보자."}}],"gates":{"t1":[{"type":"find","ref":"스 1:1","prompt":"성경책에서 에스라 1장 1절을 찾아 읽어 보세요.","confirm":{"prompt":"여호와께서 고레스의 마음을 움직이신 것은 누구의 입으로 하신 말씀을 이루시려는 것이었나요?","options":[{"label":"예레미야","ok":true},{"label":"학개","basis":"스 6:14"},{"label":"모세","basis":"본문에 없음"}]}},{"type":"multi","ref":"스 3:10","prompt":"성경책에서 에스라 3장 10절을 찾아 읽어 보세요.","confirm":{"prompt":"기초를 놓을 때 제사장과 레위 사람이 한 일을 모두 고르세요.","options":[{"label":"제사장들이 나팔을 들었어요","ok":true},{"label":"제사장들이 기초 돌을 날랐어요","basis":"본문에 없음"},{"label":"레위 사람들이 제금을 잡았어요","ok":true},{"label":"율법책을 읽고 그 뜻을 풀어 주었어요","basis":"느 8:8"},{"label":"다윗이 정한 대로 여호와를 찬송했어요","ok":true}]}}],"t2":[{"type":"find","ref":"스 1:1-4","prompt":"성경책에서 에스라 1장 1절부터 4절까지 읽어 보세요.","confirm":{"prompt":"여호와께서 고레스 왕의 마음을 움직이신 까닭은 무엇인가요?","options":[{"label":"예레미야를 통해 하신 말씀이 이루어지게 하시려고","ok":true},{"label":"고레스가 여호와께 제사를 드리며 구했기 때문에","basis":"본문에 없음"},{"label":"유다 백성이 왕에게 돌려보내 달라고 청했기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"스 1:5-11","prompt":"성경책에서 에스라 1장 5절부터 11절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["유다와 베냐민의 족장들, 제사장들, 레위 사람들이 올라가려고 일어났다","둘레 사람들이 은그릇, 금, 짐승으로 도왔다","고레스 왕이 여호와의 전 그릇들을 꺼냈다","고지기 미드르닷이 그릇을 세어 세스바살에게 넘겼다","세스바살이 그 그릇들을 다 가지고 예루살렘으로 왔다"]}],"t3":[{"type":"find","refs":["스 1:3","스 3:8"],"prompt":"에스라 1장 3절과 3장 8절을 함께 찾아 읽어 보자.","confirm":{"prompt":"고레스의 조서와 3장 8절을 이어 읽으면 무엇이 보이는가?","options":[{"label":"조서는 그 백성 된 사람은 누구든지 예루살렘으로 올라가 여호와의 전을 지으라고 했고, 사로잡혔다가 돌아온 사람들은 예루살렘에 이른 지 이 년째 이월에 그 일을 시작했다","ok":true},{"label":"조서는 그 백성 된 사람은 누구든지 예루살렘으로 올라가 여호와의 전을 지으라고 했고, 사로잡혔다가 돌아온 사람들은 예루살렘에 이른 그해 칠월에 곧바로 그 일을 시작했다","basis":"본문에 없음"},{"label":"조서는 그 백성 된 사람은 누구든지 예루살렘으로 올라가 여호와의 전을 지으라고 했고, 사로잡혔다가 돌아온 사람들은 조서가 내린 지 이십 년째 되는 해에 그 일을 시작했다","basis":"본문에 없음"}]}},{"type":"match","refs":["스 3:10","스 6:14","스 6:18"],"prompt":"에스라 3장 10절, 6장 14절, 6장 18절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"스 3:10","text":"다윗이 정한 대로 여호와를 찬송했다"},{"ref":"스 6:14","text":"하나님의 명령과 세 왕의 조서를 따라 전을 다 지었다"},{"ref":"스 6:18","text":"모세의 책에 적힌 대로 제사장과 레위 사람을 세워 하나님을 섬기게 했다"}],"after":"세 곳을 이으면, 기초를 놓을 때의 찬송은 다윗이 정한 대로, 전 짓는 일은 하나님의 명령과 왕들의 조서를 따라, 섬기는 일은 모세의 책에 적힌 대로 했다."}]},"cards":[{"ref":"스 3:11","title":"그 인자하심이 영원하시도다"},{"ref":"스 6:16","title":"즐거이 행한 봉헌식"}],"close":{"t1":{"kind":"prayer","text":"하나님, 예루살렘에 하나님의 전을 다시 지은 이야기를 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 에스라 3장 8절부터 13절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"스 1:1-11, 3:8-13, 6:14-18에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 비상 착륙 때 통신기 받침이 헐거워져서 소리가 자꾸 끊겨요. 둘레에서 부드러운 것을 찾아 틈을 메워 주세요.","t2":"최현 박사예요. 여기는 바사 왕 고레스의 나라예요. 비상 착륙 때 통신기 받침이 헐거워져서 소리가 자꾸 끊겨요. 이 시대에는 맞는 부속이 없으니 그 자리에서 구할 수 있는 부드러운 것으로 틈을 메워야 해요.","t3":"최현 박사다. 여기는 바사 왕 고레스의 나라다. 비상 착륙 때 통신기 받침이 헐거워져 소리가 자꾸 끊긴다. 이 시대에는 맞는 부속이 없으니, 그 자리에서 구할 수 있는 부드러운 것으로 받침의 틈을 메워 흔들림을 막아야 한다."},"materials":[{"key":"fur","name":"짐승 털","basis":"스 1:6","use":"짐승 털을 뭉쳐서 헐거워진 통신기 받침의 틈을 메우는 완충재 대신 쓸 수 있어요.","how":"짐승들이 지나간 길가 땅에 떨어진 털 뭉치를 줍는다. 짐승에게 다가가거나 사람들이 주고받는 물건에 손대지 않는다.","line":"짐승 털을 찾았어! 짐승들이 지나간 길가 땅에 떨어져 있었어."}],"companion":null,"today":[{"q":"예레미야의 입으로 하신 말씀은 어떤 말씀이었어요?","a":{"t1":"에스라 1장 1절은 그 말씀이 무엇인지 적지 않아요. 역대하 36장은 같은 일을 적으면서 칠십 년을 함께 말해요. 예레미야서에는 바벨론에서 칠십 년이 차면 백성을 이곳으로 돌아오게 하겠다는 여호와의 말씀이 있어요.","t2":"에스라 1장 1절은 예레미야의 입으로 하신 말씀이 무엇인지 따로 적지 않아요. 역대하 36장 21절은 땅이 황폐하여 칠십 년을 지낸 일을 두고 예레미야의 입으로 하신 말씀이 이루어졌다고 적고, 바로 다음 절에서 고레스의 조서를 이야기해요. 예레미야 29장 10절에는 바벨론에서 칠십 년이 차면 백성을 이곳으로 돌아오게 하겠다고 하신 여호와의 말씀이 있어요.","t3":"에스라 1:1은 그 말씀의 내용을 적지 않는다. 역대하 36:21은 땅이 황폐하여 안식하며 칠십 년을 지낸 일을 두고 예레미야의 입으로 하신 여호와의 말씀이 이루어졌다고 하고, 이어지는 36:22-23은 고레스의 조서를 에스라 1장과 거의 같은 말로 적는다. 예레미야 25:11-12와 29:10에는 칠십 년에 대한 여호와의 말씀이 있고, 29:10은 바벨론에서 칠십 년이 차면 백성을 이곳으로 돌아오게 하겠다고 한다. 성경은 여기까지 말한다."},"refs":["스 1:1","대하 36:21-23","렘 25:11-12","렘 29:10"]},{"q":"하나님은 다른 나라 왕의 마음도 움직이세요?","a":{"t1":"에스라서는 여호와께서 바사 왕 고레스의 마음을 움직이셨다고 적어요. 같은 책에는 여호와께서 앗수르 왕의 마음을 돌이키셔서 하나님의 전 짓는 일을 돕게 하셨다는 말씀도 있어요.","t2":"에스라서는 여호와께서 바사 왕 고레스의 마음을 움직이셨다고 적어요. 같은 책에는 여호와께서 앗수르 왕의 마음을 돌이키셔서 하나님의 전 짓는 일을 돕게 하셨다는 말씀도 있어요. 에스라도 여호와께서 왕이 예루살렘에 있는 여호와의 전을 아름답게 꾸미려는 마음을 품게 하셨다고 찬송했어요.","t3":"에스라 1:1은 여호와께서 바사 왕 고레스의 마음을 감동시키셨다고 적는다. 같은 책 6:22는 여호와께서 앗수르 왕의 마음을 돌이켜 그들이 하나님의 전 일을 하는 손을 힘 있게 하셨다고 하고, 7:27에서 에스라는 여호와께서 왕으로 하여금 예루살렘에 있는 여호와의 전을 아름답게 꾸미려는 마음을 품게 하셨다고 송축한다. 이 책은 이런 일을 여호와께서 하셨다고 적을 뿐, 어떻게 하셨는지는 말하지 않는다."},"refs":["스 1:1","스 6:22","스 7:27"]}],"help":{"who":"사로잡혔다가 돌아온 백성","steps":[{"kind":"do","after":1,"title":"길 떠날 짐 묶기 거들기","basis":"스 1:5","text":{"t1":"예루살렘으로 올라가려는 사람들이 일어났어요. 성경에 적힌 일은 아니지만, 우리는 그 곁에서 사람들이 자기 짐 보따리를 묶는 일만 거들어요. 둘레 사람들이 건네는 물건과 예물에는 손대지 않아요.","t2":"하나님이 마음을 움직이신 사람들이 예루살렘으로 올라가려고 일어났어요. 이것은 성경에 적힌 일이 아니라 탐험대가 곁에서 거드는 일이에요. 둘레 사람들이 건네는 은그릇과 금과 짐승, 예물에는 손대지 않고, 길 떠날 사람들이 자기 짐 보따리를 묶는 것만 거들어요.","t3":"유다와 베냐민의 족장들, 제사장들, 레위 사람들, 그리고 하나님께 마음이 감동된 사람들이 예루살렘으로 올라가려고 일어났다(1:5). 탐험대는 그 곁에서 길 떠날 사람들이 자기 짐 보따리를 묶는 일을 거든다. 본문에 적힌 일이 아니라 탐험대의 일이다. 둘레 사람들이 건네는 물건과 짐승, 하나님의 전을 위한 예물(1:6), 여호와의 전 그릇에는 손대지 않는다."},"tasks":["짐 보따리 끈 묶기","묶은 보따리 한곳에 모으기","길 떠날 자리 정리하기"],"done":{"who":"hyu","text":"짐을 다 묶었어. 주고받는 물건이랑 예물에는 손대지 않았어."}},{"kind":"watch","after":2,"title":"곁에서 보기 · 세어서 넘기는 그릇","basis":"스 1:8","text":{"t1":"고레스 왕이 여호와의 전 그릇들을 꺼냈어요. 고지기 미드르닷이 그릇을 세어 세스바살에게 넘겨요. 우리는 그릇에 손대지 않고 곁에서 봐요.","t2":"고지기 미드르닷이 여호와의 전 그릇들을 세어 세스바살에게 넘겨요. 그릇을 세고 넘기는 일은 본문이 정한 사람들이 해요. 우리는 손대지 않고 곁에서 봐요.","t3":"고레스 왕은 고지기 미드르닷을 시켜 여호와의 전 그릇을 꺼내 세어 세스바살에게 넘기게 했다(1:8). 세스바살은 유다의 목백이다. 이 그릇은 느부갓네살이 예전에 예루살렘에서 가져가 자기 신들의 당에 둔 것이다(1:7). 탐험대는 여호와의 전 그릇에 손대지 않고 곁에서 본다."},"say":{"who":"hyu","text":"그릇을 센 사람은 미드르닷, 받은 사람은 세스바살. 일지에 적어 둘게."}},{"kind":"watch","after":3,"title":"곁에서 보기 · 기초를 놓을 때의 찬송","basis":"스 3:10","text":{"t1":"건축자들이 여호와의 전 기초를 놓고, 제사장과 레위 사람이 여호와를 찬송해요. 우리는 기초 돌에 손대지 않고 곁에서 봐요.","t2":"건축자들이 여호와의 전 기초를 놓을 때, 예복 차림의 제사장들은 나팔을, 레위 사람들(아삽 자손)은 제금을 잡고 서서 다윗이 정한 대로 여호와를 찬송해요. 찬송을 맡은 일은 제사장들과 레위 사람들이 해요. 우리는 곁에서 봐요.","t3":"건축자들이 여호와의 전 기초를 놓는다. 예복 차림의 제사장들은 나팔을, 레위 사람들(아삽 자손)은 제금을 잡고 서서, 이스라엘 왕 다윗이 정한 대로 여호와를 찬송한다. 이 일은 본문이 제사장들과 레위 사람들이 했다고 적은 일이다. 탐험대는 기초 돌과 악기에 손대지 않고 곁에서 본다."},"say":{"who":"onwoo","text":"찬송을 맡은 사람들이야. 우리는 조용히 곁에서 보자."}},{"kind":"stay","after":4,"title":"백성 곁에 함께 서 있기","basis":"스 3:11-13","text":{"t1":"기초가 놓인 것을 보고 백성이 크게 외쳐요. 첫 성전을 보았던 노인들은 큰 소리로 울어요. 우리는 백성 곁에 함께 서 있어요.","t2":"모든 백성이 여호와께 찬송하며 크게 외쳐요. 첫 성전을 보았던 노인들은 큰 소리로 울고, 여러 사람은 기뻐 외쳐요. 우리는 끼어들지 않고 백성 곁에 함께 서 있어요.","t3":"모든 백성이 여호와의 전 기초가 놓인 것을 보고 여호와께 찬송하며 크게 외친다(3:11). 첫 성전을 보았던 노인들은 이 전의 기초가 놓이는 것을 보고 큰 소리로 울고, 여러 사람은 기뻐 외친다(3:12). 탐험대는 끼어들지 않고 백성 곁에 함께 서 있다. 그 소리는 멀리까지 들린다."},"wait":"백성 곁에 서 있기","say":{"who":"choeon","text":"우는 사람도 있고 기뻐 외치는 사람도 있어. 우리는 곁에 가만히 서 있을게."}},{"kind":"ask","after":"gates","title":"기초가 놓였을 때 부른 찬송의 뜻","basis":"스 3:11","by":"최현 박사","ask":{"who":"onwoo","text":"전의 기초가 다시 놓인 일은 무슨 뜻이에요?"},"answer":{"t1":"에스라서는 여호와께서 예레미야를 통해 하신 말씀을 이루시려고 고레스의 마음을 움직이셨다고 적어요. 기초가 놓이자 제사장들과 레위 사람들은, 여호와는 선하시고 이스라엘을 향한 그분의 인자하심은 영원하다고 찬송했어요.","t2":"에스라서는 여호와께서 예레미야를 통해 하신 말씀을 이루시려고 고레스의 마음을 움직이셨고, 고레스가 예루살렘에 여호와의 전을 지으라는 조서를 내렸다고 적어요(1:1-3). 전의 기초가 놓이자 제사장들과 레위 사람들은 여호와께 감사하며, 여호와는 선하시고 이스라엘을 향한 그분의 인자하심은 영원하다고 서로 화답하며 찬송했어요(3:11). 모든 백성도 기초가 놓인 것을 보고 여호와께 찬송했어요.","t3":"에스라서는 여호와께서 예레미야를 통해 하신 말씀을 이루시려고 고레스 왕의 마음을 감동시키셨고, 고레스가 예루살렘에 여호와의 전을 지으라는 조서를 내렸다고 기록한다(1:1-3). 전의 기초가 놓일 때 제사장들과 레위 사람들은 여호와께 감사드리며, 주는 선하시고 이스라엘을 향한 그분의 인자하심은 영원하다고 서로 화답하며 찬송했다(3:11). 모든 백성도 기초가 놓인 것을 보고 여호와께 찬송하며 크게 외쳤다. 성경은 이 일에 대해 이만큼 말한다."},"read":{"t1":{"type":"find","ref":"스 3:11","prompt":"성경책에서 에스라 3장 11절을 찾아 읽어 보세요.","confirm":{"prompt":"제사장들과 레위 사람들은 찬송하며, 여호와의 무엇이 영원하다고 했나요?","options":[{"label":"인자하심","ok":true},{"label":"성벽","basis":"본문에 없음"},{"label":"금과 은","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"스 3:10-11","prompt":"성경책에서 에스라 3장 10절과 11절을 읽어 보세요.","confirm":{"prompt":"모든 백성이 크게 외치며 여호와께 찬송한 까닭은 무엇인가요?","options":[{"label":"여호와의 전 기초가 놓인 것을 보았기 때문에","ok":true},{"label":"고레스 왕이 예루살렘에 왔기 때문에","basis":"본문에 없음"},{"label":"전을 다 지어 봉헌식을 했기 때문에","basis":"스 6:16"}]}},"t3":{"type":"find","refs":["스 1:1","스 3:11"],"prompt":"에스라 1장 1절과 3장 11절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 전의 기초가 다시 놓인 일에 대해 성경은 무엇을 말하는가?","options":[{"label":"이 일은 여호와께서 예레미야를 통해 하신 말씀을 이루시려고 고레스의 마음을 움직이신 데서 시작되었고, 기초가 놓이자 제사장들과 레위 사람들은 여호와의 선하심과 영원한 인자하심을 찬송했다","ok":true},{"label":"이 일은 여호와께서 고레스와 맺으신 언약을 이루시려고 그의 마음을 움직이신 데서 시작되었고, 기초가 놓이자 제사장들과 레위 사람들은 여호와의 선하심과 영원한 인자하심을 찬송했다","basis":"본문에 없음"},{"label":"이 일은 여호와께서 고레스의 꿈에 보이신 일을 이루시려고 그의 마음을 움직이신 데서 시작되었고, 기초가 놓이자 제사장들과 레위 사람들은 여호와께서 이 전을 영원히 지키시리라고 찬송했다","basis":"본문에 없음"}]}}}}]}},"has3d":false,"epic":false},"OT-38":{"id":"OT-38","era":10,"title":"에스더","ref":"에 4:1-17","place":"수산 궁, 대궐 문 앞 성중 광장","review":{"required":false,"topics":[],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"에 4:1-3","focus":"mordecai","text":{"t1":"모르드개는 일어난 일을 모두 알고 성 안에 나가 크게 울었는데, 그때 어떤 차림이었는지는 성경에서 찾아봐요. 왕의 명령이 전해진 곳마다 유다인들도 크게 슬퍼하며 금식했어요.","t2":"모르드개는 일어난 일을 모두 알고 옷을 찢었어요. 굵은 베를 입고 재를 뒤집어쓰고 성 안으로 나가 큰 소리로 울었어요. 모르드개는 대궐 문 앞까지만 갔는데, 왜 그랬는지는 2절에서 찾아봐요. 왕의 명령이 이른 도마다 유다인이 크게 슬퍼하며 금식하고 울부짖었어요.","t3":"모르드개는 일어난 일을 모두 알고 자기 옷을 찢었다. 굵은 베를 입고 재를 뒤집어쓴 채 성 가운데로 나가 큰 소리로 통곡했다. 그는 대궐 문 앞까지만 갔는데, 굵은 베를 입은 사람은 대궐 문 안으로 들어갈 수 없었기 때문이다. 왕의 명령과 조서가 이른 도마다 유다인이 크게 애통하며 금식하고 울며 부르짖었고, 굵은 베를 입고 재 위에 누운 사람이 많았다."},"say":{"who":"choeon","text":"저분이 크게 울고 있어. 무슨 일일까?"}},{"ref":"에 4:4-9","focus":"hathach","text":{"t1":"왕후 에스더가 이 일을 듣고 맨 처음 한 일은 성경에서 찾아봐요. 에스더가 내시 하닥을 보내자, 모르드개는 유다인을 없애라는 조서의 초본을 주며 에스더가 왕에게 나아가 민족을 위해 구하게 해 달라고 했어요.","t2":"에스더의 시녀와 내시가 와서 이 일을 알리자 왕후는 몹시 근심했어요. 모르드개에게 입을 옷을 보냈지만 모르드개는 받지 않았어요. 에스더는 내시 하닥을 보내 무슨 일이며 무슨 까닭인지 알아보게 했어요. 모르드개는 하만이 유다인을 없애려고 한 일을 말하고, 조서의 초본을 주며 에스더가 왕에게 나아가 자기 민족을 위해 구하게 해 달라고 했어요.","t3":"에스더의 시녀와 내시가 와서 알리자 왕후는 몹시 근심했다. 굵은 베를 벗기려고 모르드개에게 입을 옷을 보냈으나 그는 받지 않았다. 에스더는 왕이 자기를 가까이에서 섬기게 한 내시 하닥을 불러, 무슨 일이며 무슨 까닭인지 알아보게 했다. 하닥은 모르드개가 있는 대궐 문 앞 성중 광장으로 갔다. 모르드개는 자기가 당한 모든 일과 하만에 관한 일을 말했는데, 그 내용은 7절에 있다. 또 수산 궁에서 내려진, 유다인을 진멸하라는 조서의 초본을 하닥에게 주어 에스더에게 보이고 알리게 했다. 그리고 에스더가 왕에게 나아가 자기 민족을 위해 간절히 구하도록 부탁하게 했다. 하닥은 돌아와서 에스더에게 모르드개의 말을 전했다."},"say":{"who":"hyu","text":"하닥이 간 곳은 대궐 문 앞 성중 광장이야. 모르드개가 조서의 초본을 건넸어. 일지에 적어 둘게."}},{"ref":"에 4:10-12","focus":"esther","text":{"t1":"에스더는 하닥을 시켜, 부르지 않았는데 왕에게 나아가면 죽게 되고 왕이 금홀을 내밀어야만 산다는 법이 있다고 대답했어요. 그리고 자기는 왕에게 부름을 받지 못한 지 삼십 일이 되었다고 했어요.","t2":"에스더는 하닥을 시켜 모르드개에게 대답했어요. 남자든 여자든 부르지 않았는데 안뜰에 들어가 왕 앞에 나아가면 죽이는 법이 있고, 왕이 금홀을 내밀어야만 산다고 했어요. 에스더는 자기가 왕에게 부름을 받지 못한 지 벌써 삼십 일이라고 했어요.","t3":"에스더는 하닥에게 모르드개에게 전할 말을 주었다. 왕의 신하들과 각 도의 백성이 다 아는 대로, 남자든 여자든 부름 없이 안뜰로 들어가 왕 앞에 나아가는 사람은 죽이는 법 하나뿐이고, 왕이 금홀을 내밀어 주는 사람만 산다는 것이었다. 그리고 자기가 부름을 받아 왕 앞에 나아가지 못한 지가 벌써 삼십 일이라고 했다. 에스더의 말은 모르드개에게 전해졌다."},"say":{"who":"onwoo","text":"에스더가 말한 법은 에스더 4장 11절에 있어. 성경책에서 읽어 보자."}},{"ref":"에 4:13-14","focus":"mordecai","text":{"t1":"모르드개는 왕궁에 있다고 혼자만 피할 수 있다고 생각하지 말라고 다시 전했어요. 에스더가 왕후가 된 일을 두고 모르드개가 무엇이라고 했는지는 성경에서 찾아봐요.","t2":"모르드개가 에스더에게 회답했어요. 왕궁에 있다고 해서 모든 유다인 가운데 혼자만 피할 수 있다고 생각하지 말라고 했어요. 왜 그렇게 말했는지는 14절에서 찾아봐요. 에스더가 왕후의 자리를 얻은 것이 이때를 위한 것인지 누가 알겠느냐고 했어요.","t3":"모르드개는 에스더에게 이렇게 회답하게 했다. 왕궁에 있다고 해서 모든 유다인 가운데 홀로 화를 면하리라고 생각하지 말라는 것이었다. 이때에 에스더가 입을 다물고 있으면 유다인은 다른 곳에서 놓임과 구원을 얻겠지만 에스더와 그 아버지의 집은 멸망할 것이라고 했다. 에스더가 왕후의 자리에 오른 일을 두고 모르드개가 무엇이라고 덧붙였는지는 14절에서 직접 읽어 보자."},"say":{"who":"hyu","text":"말을 전하는 사람이 두 사람 사이를 오가고 있어. 이번에는 모르드개의 회답이야. 13절과 14절이라고 적어 둘게."}},{"ref":"에 4:15-17","focus":"esther","text":{"t1":"에스더는 수산의 유다인을 다 모아 사흘 동안 자기를 위해 금식해 달라고 하고, 그런 뒤에 왕에게 나아가겠다고 했어요. 모르드개는 가서 에스더가 말한 대로 다 했어요.","t2":"에스더가 모르드개에게 회답했어요. 수산에 있는 유다인을 다 모아 자기를 위해 금식하되, 사흘 동안 밤낮으로 먹지도 마시지도 말아 달라고 했어요. 자기도 시녀들과 함께 그렇게 금식한 뒤에 규례를 어기고 왕에게 나아가겠다고 했고, 죽게 되면 죽겠다고 했어요. 모르드개는 가서 에스더가 말한 대로 다 했어요.","t3":"에스더는 모르드개에게 회답하게 했다. 가서 수산에 있는 유다인을 모두 모으고 자기를 위해 금식하되, 사흘 동안 밤에도 낮에도 먹지도 마시지도 말아 달라는 것이었다. 자기도 시녀들과 함께 그렇게 금식하겠다고 했는데, 그런 다음에 무엇을 하겠다고 했는지는 16절에서 직접 읽어 보자. 모르드개는 가서 에스더가 시킨 대로 모두 했다."},"say":{"who":"choeon","text":"에스더가 사흘 동안 먹지도 마시지도 않겠대. 시녀들도 함께래."}},{"ref":"에 7:1-6","focus":"banquet","text":{"t1":"왕과 하만이 에스더의 잔치에 왔을 때, 에스더는 자기와 자기 민족을 살려 달라고 왕에게 구했어요. 그리고 대적은 하만이라고 말했어요.","t2":"왕과 하만이 왕후 에스더의 잔치에 왔어요. 둘째 날 잔치에서 왕은 에스더에게 소원이 무엇인지 다시 물으며, 나라의 절반이라도 들어주겠다고 했어요. 에스더가 무엇을 구했고 왕과 무슨 말을 어떤 차례로 주고받았는지는 3절부터 6절까지 읽어 봐요.","t3":"왕과 하만이 다시 왕후 에스더의 잔치에 왔다. 이 둘째 날 잔치 자리에서 왕은 에스더에게 소청이 무엇이냐고 다시 묻고, 나라의 절반이라도 그대로 해 주겠다고 했다. 에스더는 왕이 좋게 여긴다면 자기의 생명과 자기의 민족을 자기에게 달라고 구했다. 에스더가 자기와 자기 민족이 어떤 처지에 놓였다고 했는지는 4절에서 직접 읽어 보자. 아하수에로 왕이 감히 그런 일을 마음에 품은 자가 누구이며 어디 있느냐고 묻자, 에스더는 대적과 원수가 바로 이 악한 하만이라고 했다. 하만은 왕과 왕후 앞에서 두려워했다."},"say":{"who":"choeon","text":"잔치 자리에 왕과 하만이 왔어. 왕이 에스더에게 무엇을 원하는지 묻고 있어."}},{"ref":"에 7:7-10","focus":"king","text":{"t1":"왕은 노하여 후원으로 나갔다가 돌아왔어요. 사람들이 하만의 얼굴을 쌌고, 그 뒤에 왕의 노가 그쳤어요.","t2":"왕은 노하여 잔치 자리에서 일어나 왕궁 후원으로 나갔어요. 하만은 왕이 자기에게 화를 내리기로 한 줄 알고 왕후 에스더에게 살려 달라고 구했어요. 내시 하르보나는 하만이 모르드개를 달려고 준비한 높이 오십 규빗의 나무가 하만의 집에 서 있다고 왕에게 아뢰었어요. 왕은 하만을 그 나무에 달라고 했고, 그대로 된 뒤에 왕의 노가 그쳤어요.","t3":"왕은 노하여 잔치 자리에서 일어나 왕궁 후원으로 나갔다. 하만은 왕이 자기에게 화를 내리기로 마음을 정한 줄 알고, 일어서서 왕후 에스더에게 자기 생명을 구했다. 왕이 후원에서 잔치 자리로 돌아왔을 때 하만은 에스더가 앉은 걸상 위에 엎드려 있었다. 왕은 하만이 궁 안 자기 앞에서 왕후에게까지 함부로 하려 하느냐고 말했고, 그 말이 떨어지자 사람들이 하만의 얼굴을 가렸다. 왕을 모시는 내시 하르보나는, 왕을 위해 충성된 말로 알린 모르드개를 달려고 하만이 높이 오십 규빗 되는 나무를 준비했는데 그것이 지금 하만의 집에 서 있다고 아뢰었다. 왕은 하만을 거기에 달라고 명했다. 사람들은 하만이 모르드개를 달려고 준비한 그 나무에 하만을 달았고, 왕의 노가 그쳤다."},"say":{"who":"hyu","text":"왕이 후원으로 나갔다가 다시 잔치 자리로 돌아왔어. 일어난 일을 순서대로 적어 둘게."}}],"gates":{"t1":[{"type":"find","ref":"에 4:1","prompt":"성경책에서 에스더 4장 1절을 찾아 읽어 보세요.","confirm":{"prompt":"모르드개는 옷을 찢고 무엇을 입었나요?","options":[{"label":"굵은 베","ok":true},{"label":"왕의 옷","basis":"에 6:11"},{"label":"갑옷","basis":"본문에 없음"}]},"inStory":"굵은 베는 관문 뒤에 얻는 재료(굵은 베 실, 탐험대 이야기)의 이름에만 남는다. 모르드개가 옷을 찢고 무엇을 입었는지는 4:1에서만 안다"},{"type":"multi","ref":"에 4:4","prompt":"성경책에서 에스더 4장 4절을 찾아 읽어 보세요.","confirm":{"prompt":"왕후 에스더가 모르드개의 일을 전해 듣고 한 일과, 그때 모르드개가 한 일을 모두 고르세요.","options":[{"label":"왕후가 몹시 근심했어요","ok":true},{"label":"에스더가 잔치를 베풀었어요","basis":"에 7:1"},{"label":"에스더가 모르드개에게 입을 옷을 보냈어요","ok":true},{"label":"에스더가 광장에 나가 모르드개를 만났어요","basis":"본문에 없음"},{"label":"모르드개는 그 옷을 받지 않았어요","ok":true}]}}],"t2":[{"type":"find","ref":"에 4:1-2","prompt":"성경책에서 에스더 4장 1절과 2절을 읽어 보세요.","confirm":{"prompt":"모르드개가 대궐 문 앞까지만 간 까닭은 무엇인가요?","options":[{"label":"굵은 베를 입은 사람은 대궐 문 안으로 들어갈 수 없었기 때문에","ok":true},{"label":"왕이 모르드개를 궁에서 내보내라고 명했기 때문에","basis":"본문에 없음"},{"label":"에스더가 궁으로 오지 말라고 전했기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"에 7:1-7","prompt":"성경책에서 에스더 7장 1절부터 7절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["왕과 하만이 에스더가 베푼 잔치에 다시 왔다","에스더가 자기 생명과 자기 민족을 달라고 왕에게 구했다","에스더가 대적과 원수는 하만이라고 말했다","왕이 노하여 일어나 후원으로 나갔다","하만이 왕후 앞에서 살려 달라고 빌었다"]}],"t3":[{"type":"find","refs":["에 4:7","에 7:4"],"prompt":"에스더 4장 7절과 7장 4절을 함께 찾아 읽어 보자.","confirm":{"prompt":"에스더가 잔치에서 자기와 자기 민족이 팔렸다고 한 말은 무엇과 이어지는가?","options":[{"label":"유다인을 없애려고 하만이 왕의 창고에 은을 내겠다고 했고, 에스더는 자기와 자기 민족이 팔려서 멸망당하게 되었다고 왕에게 말했다","ok":true},{"label":"유다인을 없애려고 하만이 각 도의 방백들에게 은을 나누어 주었고, 에스더는 자기와 자기 민족이 팔려서 멸망당하게 되었다고 왕에게 말했다","basis":"본문에 없음"},{"label":"유다인을 없애려고 하만이 왕의 창고에 은을 내겠다고 했고, 에스더는 그 은보다 더 많은 은을 내겠으니 자기 민족을 살려 달라고 왕에게 말했다","basis":"본문에 없음"}]}},{"type":"match","refs":["에 4:6","에 4:9","에 4:12","에 4:17"],"prompt":"에스더 4장 6절, 9절, 12절, 17절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"에 4:6","text":"하닥이 광장으로 모르드개를 찾아갔다"},{"ref":"에 4:9","text":"하닥이 에스더에게 돌아가 모르드개가 한 말을 알렸다"},{"ref":"에 4:12","text":"에스더의 말이 모르드개에게 전해졌다"},{"ref":"에 4:17","text":"모르드개는 에스더가 시킨 대로 모두 행했다"}],"after":"네 곳을 이으면, 하닥이 광장과 에스더 사이를 오가며 두 사람의 말을 서로 전했고, 끝내 모르드개는 에스더가 시킨 대로 했다."}]},"cards":[{"ref":"에 4:14","title":"이 때를 위함이 아닌지"},{"ref":"에 4:16","title":"죽으면 죽으리이다"}],"close":{"t1":{"kind":"prayer","text":"하나님, 에스더와 모르드개의 이야기를 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 에스더 4장 10절부터 17절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"에 4:1-17, 7:1-10에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 비상 착륙 때 안테나 줄이 끊어졌어요. 실이 될 만한 것을 찾아서 줄을 이어 주세요.","t2":"최현 박사예요. 여기는 수산이에요. 비상 착륙 때 안테나 줄이 끊어져서 통신이 약해요. 이 시대에는 맞는 부속이 없으니 그 자리에서 구할 수 있는 질긴 실로 줄을 이어야 해요.","t3":"최현 박사다. 여기는 수산이다. 비상 착륙 때 안테나 줄이 끊어져 통신이 약하다. 맞는 부속이 없으니 그 자리에서 구할 수 있는 질긴 실을 여러 가닥 꼬아 줄을 이어야 한다."},"materials":[{"key":"thread","name":"굵은 베 실","basis":"에 4:1","use":"굵은 베 실을 여러 가닥 꼬아서 끊어진 안테나 줄 대신 쓸 수 있어요.","how":"성 안 길가 땅에 떨어진 굵은 베 실오라기를 줍는다. 사람이 입은 옷에는 손대지 않고, 대궐 문 안으로는 들어가지 않는다.","line":"굵은 베 실을 찾았어! 성 안 길가 땅에 떨어져 있었어."}],"companion":{"who":"모르드개","when":"after","ref":"에 4:1-2","talks":[{"ask":{"who":"choeon","text":"에스더 왕후에게 무엇을 부탁했어요?"},"answer":{"t1":"모르드개는 에스더가 왕에게 나아가 자기 민족을 위해 간절히 구하라고 부탁했어요.","t2":"모르드개는 유다인을 없애라는 조서의 초본을 하닥에게 주어 에스더에게 보여 주게 했어요. 그리고 에스더가 왕에게 나아가 그 앞에서 자기 민족을 위해 간절히 구하라고 부탁했어요.","t3":"모르드개는 수산 궁에서 내린, 유다인을 진멸하라는 조서의 초본을 하닥에게 주어 에스더에게 보이고 알리게 했다. 그리고 하닥을 통해, 에스더가 왕에게 나아가 그 앞에서 자기 민족을 위해 간절히 구하라고 부탁했다."},"ref":"에 4:8","open":"에 4:8"},{"ask":{"who":"hyu","text":"에스더 왕후는 왕궁에 있으니까 괜찮은 거 아니었어요?"},"answer":{"t1":"모르드개는 에스더에게, 왕궁에 있다고 혼자만 피할 수 있다고 생각하지 말라고 전했어요.","t2":"모르드개는 에스더에게, 왕궁에 있다고 해서 모든 유다인 가운데 혼자만 피할 수 있으리라고 생각하지 말라고 회답했어요.","t3":"모르드개는 에스더에게, 왕궁에 있으니 모든 유다인 가운데 홀로 화를 면하리라고 생각하지 말라고 회답했다."},"ref":"에 4:13","open":"에 4:13"}]},"today":[{"q":"에스더는 왜 죽게 되면 죽겠다고 했어요?","a":{"t1":"에스더는 부르지 않았는데 왕에게 나아가면 죽이는 법이 있다고 말했어요. 그 규례를 어기고 왕에게 나아가겠다고 하면서, 죽게 되면 죽겠다고 했어요.","t2":"에스더서 4장 11절을 보면, 부름을 받지 않고 안뜰에 들어가 왕에게 나아가는 사람은 왕이 금홀을 내밀지 않으면 죽이는 법이 있었어요. 에스더는 사흘 동안 금식한 뒤에 그 규례를 어기고 왕에게 나아가겠다고 하면서 그렇게 말했어요. 그때 에스더의 마음이 어떠했는지는 성경에 적혀 있지 않아요.","t3":"에스더 4:11에서 에스더는 부름 없이 안뜰에 들어가 왕에게 나아가는 사람은 죽이는 법 하나뿐이고 왕이 금홀을 내밀어야만 산다고 전했다. 4:16에서는 자기와 시녀들이 금식한 뒤에 규례를 어기고 왕에게 나아가겠다고 하면서, 죽으면 죽겠다고 했다. 성경은 에스더의 말을 이만큼 적고, 그때 에스더의 속마음은 적지 않는다."},"refs":["에 4:11","에 4:16"]},{"q":"금식은 왜 하는 거예요?","a":{"t1":"에스더서에는 유다인들이 크게 슬퍼하며 금식했다고 적혀 있어요. 에스더는 왕에게 나아가기 전에 자기를 위해 사흘 동안 금식해 달라고 했어요. 에스라서에는 하나님 앞에서 스스로 낮추고 평탄한 길을 구하려고 금식했다는 말이 있어요.","t2":"에스더서에는 왕의 조서가 이른 곳마다 유다인이 크게 슬퍼하며 금식했다고 적혀 있어요. 에스더는 왕에게 나아가기 전에, 수산의 유다인을 다 모아 자기를 위해 사흘 밤낮 먹지도 마시지도 말고 금식해 달라고 했어요. 에스라서에서 에스라는 하나님 앞에서 스스로 낮추고 평탄한 길을 구하려고 금식을 선포했고, 하나님이 그 간구를 들으셨다고 적었어요.","t3":"에스더 4:3은 왕의 조서가 이른 도마다 유다인이 크게 애통하며 금식했다고 하고, 4:16에서 에스더는 자기를 위해 사흘 밤낮 먹지도 마시지도 말고 금식해 달라고 했다. 에스라 8:21-23에서 에스라는 하나님 앞에서 스스로 낮추고 평탄한 길을 구하려고 금식을 선포했고, 금식하며 간구하자 하나님이 들어주셨다고 적는다. 에스더서는 에스더를 위해 금식해 달라고 한 데까지만 적는다."},"refs":["에 4:3","에 4:16","스 8:21-23"]}],"help":{"who":"모르드개","steps":[{"kind":"stay","after":1,"title":"광장에서 함께 기다리기","basis":"에 4:6-9","text":{"t1":"하닥이 대궐 문 앞 광장의 모르드개에게 왔다가, 그 말을 가지고 에스더에게 돌아갔어요. 우리는 광장에서 모르드개 곁에 머물며 기다려요.","t2":"에스더가 보낸 내시 하닥이 대궐 문 앞 광장으로 모르드개를 찾아왔어요. 하닥은 모르드개의 말과 조서 초본을 가지고 에스더에게 돌아갔어요. 우리는 하닥을 따라가지 않고, 광장에서 모르드개 곁에 머물며 기다려요.","t3":"하닥은 대궐 문 앞 광장으로 모르드개를 찾아와 그의 말을 듣고 조서 초본을 받아, 에스더에게 돌아가 그 말을 전했다. 탐험대는 하닥을 따라가지 않는다. 광장에서 모르드개 곁에 머물며 에스더의 대답을 기다린다."},"wait":"광장에서 기다리기","say":{"who":"onwoo","text":"하닥이 오가는 길은 따라가지 말자. 여기 광장에서 기다리자."}},{"kind":"do","after":4,"title":"모여 오는 사람들에게 길 비켜 주기","basis":"에 4:16-17","text":{"t1":"모르드개가 에스더의 말대로 수산의 유다인을 모으러 가요. 성경에 적힌 일은 아니지만, 우리는 금식에는 끼지 않고 모여 오는 사람들에게 길을 비켜 주며 도와요.","t2":"모르드개는 가서 에스더가 말한 대로 수산의 유다인을 모아요. 이것은 성경에 적힌 일이 아니라 탐험대가 곁에서 거드는 일이에요. 우리는 금식에는 끼지 않고, 모여 오는 사람들이 지나가도록 길을 비켜 주고 자리를 내어 줘요.","t3":"에스더는 수산의 유다인을 다 모아 자기를 위해 금식해 달라고 했고, 모르드개는 가서 그 말대로 다 행했다. 탐험대는 그 곁에서 모여 오는 사람들이 지나가도록 길을 비켜 주고 자리를 내어 준다. 본문에 적힌 일이 아니라 탐험대의 일이며, 금식과 왕궁의 일에는 끼지 않는다."},"tasks":["길 가운데서 비켜서기","지나가는 사람들에게 자리 내어 주기","떠들지 않고 조용히 기다리기"],"done":{"who":"onwoo","text":"사람들이 다 지나갔어. 금식은 그 사람들이 하는 일이니까 우리는 곁에서 보자."}},{"kind":"watch","after":4,"title":"곁에서 보기 · 에스더의 말대로 하는 모르드개","basis":"에 4:16-17","text":{"t1":"에스더는 수산의 유다인을 모아 자기를 위해 금식해 달라고 했고, 모르드개는 그 말대로 다 해요. 금식하는 일에 우리는 끼지 않고 곁에서 봐요.","t2":"에스더는 수산의 유다인을 모두 모아 사흘 밤낮 자기를 위해 금식해 달라고 했어요. 모르드개는 가서 그 말대로 다 해요. 금식은 그 사람들이 하는 일이에요. 우리는 끼지 않고 곁에서 봐요.","t3":"에스더는 수산의 유다인을 모두 모아 자기를 위해 사흘 밤낮 금식해 달라고 했다. 모르드개는 가서 에스더가 시킨 대로 다 한다. 금식은 본문이 그 사람들이 한다고 적은 일이다. 탐험대는 끼지 않고 곁에서 본다."},"say":{"who":"hyu","text":"모르드개가 에스더의 말대로 하러 갔어. 일지에 적어 둘게."}},{"kind":"ask","after":"gates","title":"에스더가 왕에게 구한 일은 무슨 뜻이에요?","basis":"에 4:14","by":"모르드개","ask":{"who":"onwoo","text":"모르드개 님, 에스더 왕후가 자기 민족을 위해 왕에게 구한 일은 무슨 뜻이 있어요?"},"answer":{"t1":"모르드개는 에스더가 이때에 잠잠하면 유다인은 다른 데서 구원을 얻겠지만 에스더와 그 집안은 망할 것이라고 했어요. 에스더가 왕후가 된 것이 이런 때를 위한 것인지 누가 알겠느냐고도 했어요.","t2":"모르드개는 이때에 에스더가 잠잠하면 유다인은 다른 데서 놓임과 구원을 얻겠지만, 에스더와 그 아버지의 집은 멸망할 것이라고 말했어요. 그리고 에스더가 왕후의 자리에 오른 것이 이런 때를 위한 것인지 누가 알겠느냐고 말했어요.","t3":"모르드개는 이때 에스더가 입을 다물고 있으면 유다인은 다른 곳에서 놓임과 구원을 얻겠지만 에스더와 그 아버지의 집은 멸망할 것이라고 했다. 그리고 에스더가 왕후의 자리를 얻은 것이 이런 때를 위함이 아닌지 누가 알겠느냐고 말했다."},"read":{"t1":{"type":"find","ref":"에 4:14","prompt":"성경책에서 에스더 4장 14절을 찾아 읽어 보세요.","confirm":{"prompt":"모르드개는 에스더가 왕후의 자리를 얻은 것이 어떤 때를 위함인지 누가 아느냐고 했나요?","options":[{"label":"이 때","ok":true},{"label":"잔치 때","basis":"본문에 없음"},{"label":"전쟁 때","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"에 4:13-14","prompt":"성경책에서 에스더 4장 13절과 14절을 읽어 보세요.","confirm":{"prompt":"모르드개가 에스더에게, 왕궁에 있다고 홀로 화를 면하리라 생각하지 말라고 한 까닭은 무엇인가요?","options":[{"label":"에스더가 이때에 잠잠하면 유다인은 다른 데서 구원을 얻겠지만, 에스더와 그 아버지의 집은 멸망할 것이기 때문에","ok":true},{"label":"에스더가 이때에 잠잠하면 유다인은 아무도 구원을 얻지 못하고, 에스더도 그들과 함께 멸망할 것이기 때문에","basis":"본문에 없음"},{"label":"왕이 에스더를 부르지 않은 지 삼십 일이 되어 곧 에스더를 왕후의 자리에서 내쫓을 것이기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["에 4:8","에 4:14","에 4:16"],"prompt":"에스더 4장 8절, 14절, 16절을 함께 찾아 읽어 보자.","confirm":{"prompt":"세 곳을 이어 읽으면, 에스더가 왕에게 나아가기로 하기까지 무엇이 있었는가?","options":[{"label":"모르드개는 왕에게 나아가 민족을 위해 간절히 구하라고 부탁했고, 왕후의 자리가 이런 때를 위한 것인지 누가 알겠느냐고 했으며, 에스더는 금식한 뒤에 규례를 어기면서까지 왕 앞에 나아가겠다고 했다","ok":true},{"label":"모르드개는 왕에게 나아가 민족을 위해 간절히 구하라고 부탁했고, 왕후의 자리가 이런 때를 위한 것인지 누가 알겠느냐고 했으며, 에스더는 금식한 뒤에 왕이 부를 때까지 기다렸다가 나아가겠다고 했다","basis":"본문에 없음"},{"label":"모르드개는 왕에게 나아가 민족을 위해 간절히 구하라고 부탁했고, 왕후의 자리가 이런 때를 위한 것인지 누가 알겠느냐고 했으며, 에스더는 금식한 뒤에 왕에게 글을 먼저 올려 허락을 받고 나아가겠다고 했다","basis":"본문에 없음"}]}}}}]}},"has3d":false,"epic":false},"OT-39":{"id":"OT-39","era":10,"title":"느헤미야의 성벽과 율법책 낭독","ref":"느 2:11-20","place":"예루살렘, 골짜기 문, 수문 앞 광장","review":{"required":false,"topics":[],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"느 2:11-16","focus":"wall","text":{"t1":"느헤미야는 예루살렘에 온 지 사흘 만에, 밤에 몇 사람과 함께 골짜기 문으로 나가 성벽을 살펴보았어요. 성벽은 다 무너져 있었고 성문은 불에 타 있었어요.","t2":"느헤미야는 예루살렘에 이르러 사흘을 머문 뒤, 밤에 일어나 몇 사람과 함께 나갔어요. 하나님이 예루살렘을 위해 하게 하신 일을 누구에게 알렸는지는 12절과 16절에서 찾아봐요. 골짜기 문으로 나가 분문까지 가면서 보니 성벽은 다 무너져 있었고 성문은 불에 타 있었어요. 샘문과 왕의 못까지 갔을 때에는 타고 간 짐승이 지나갈 자리가 없었어요.","t3":"느헤미야는 예루살렘에 이르러 사흘을 지냈다. 그는 자기 하나님이 마음을 움직여 예루살렘을 위해 하게 하신 일을 누구에게도 말하지 않은 채, 밤에 일어나 몇 사람과 함께 나갔다. 짐승은 그가 탄 것 하나뿐이었다. 그 밤에 그가 어느 문으로 나가 어디를 지나며 무엇을 보았고, 어떻게 살핀 뒤 어디로 들어왔는지는 13절부터 15절까지 직접 읽어 보자. 방백들은 그가 어디에 갔고 무엇을 했는지 알지 못했다. 그는 그때까지 유다 사람들에게도, 제사장들과 귀인들과 방백들에게도, 그 밖에 일하는 사람들에게도 그 일을 알리지 않았다."},"say":{"who":"choeon","text":"밤인데 몇 사람이 성 밖으로 나가고 있어. 성벽이 다 무너져 있고 성문은 불에 탔어."}},{"ref":"느 2:17-18","focus":"nehemiah","text":{"t1":"느헤미야는 예루살렘 성을 다시 쌓자고 하며, 하나님의 선한 손이 자기를 도우신 일을 들려주었어요. 사람들은 일어나 건축하자고 하며 힘을 냈어요.","t2":"그 뒤에 느헤미야는 사람들에게 말했어요. 예루살렘이 황폐하고 성문이 불탔으니, 성을 다시 쌓아 더는 수치를 당하지 말자고 했어요. 사람들은 일어나 건축하자고 하며 모두 힘을 내어 이 좋은 일을 하려고 했는데, 무엇을 듣고 그렇게 했는지는 18절에서 찾아봐요.","t3":"그 뒤에 느헤미야는 그들에게 말했다. 자기들이 당한 어려움은 그들도 보는 바와 같아서 예루살렘은 황폐하고 성문은 불탔으니, 예루살렘 성을 다시 쌓아 더는 수치를 당하지 말자는 것이었다. 또 하나님의 선한 손이 자기를 도우신 일과 왕이 자기에게 한 말을 전했다. 그 말을 들은 사람들이 무엇이라고 하며 어떻게 했는지는 18절에 있다."},"say":{"who":"hyu","text":"밤에 성벽을 살펴본 다음에야 사람들에게 말했어. 순서를 일지에 적어 둘게."}},{"ref":"느 2:19-20","focus":"enemies","text":{"t1":"산발랏과 도비야와 게셈은 이 말을 듣고 비웃었어요. 느헤미야는 하늘의 하나님이 자기들을 잘되게 하실 것이라고 대답했어요.","t2":"호론 사람 산발랏, 암몬 사람 도비야, 아라비아 사람 게셈은 이 말을 듣고 업신여기며 비웃었어요. 왕을 배반하려는 것이냐고 했어요. 느헤미야는 하늘의 하나님이 형통하게 하실 것이니 그분의 종인 자기들이 일어나 건축하겠다고 대답했어요.","t3":"호론 사람 산발랏, 종이었던 암몬 사람 도비야, 아라비아 사람 게셈은 그 말을 듣고 그들을 업신여기며 비웃었다. 하는 일이 무엇이냐, 왕을 배반하려는 것이냐고 했다. 느헤미야는 하늘의 하나님이 자기들을 형통하게 하실 것이니 그분의 종인 자기들이 일어나 건축하겠다고 대답했다. 그리고 그들에게는 예루살렘에서 아무 몫도, 권리도, 기억될 것도 없다고 했다."},"say":{"who":"onwoo","text":"느헤미야가 뭐라고 대답했는지는 느헤미야 2장 20절에 있어. 성경책에서 확인해 보자."}},{"ref":"느 6:15-16","focus":"wall","text":{"t1":"성벽 쌓는 일이 며칠 만에 끝났는지는 성경에서 찾아봐요. 대적들은 이 일을 하나님이 이루신 것을 알고 두려워했어요.","t2":"성벽 쌓는 일은 오십이 일 만인 엘룰월 이십오일에 끝났어요. 모든 대적과 둘레의 이방 사람들은 이 소식을 듣고 모두 두려워하며 낙담했어요. 왜 그랬는지는 16절에서 찾아봐요.","t3":"성벽 쌓는 일이 며칠 만에, 어느 날에 끝났는지는 15절에 있다. 모든 대적과 둘레의 이방 사람들은 이 소식을 듣고 모두 두려워하며 스스로 낙담했다. 이 일을 하나님이 이루셨다는 것을 그들이 알았기 때문이다."},"say":{"who":"choeon","text":"저것 봐! 무너져 있던 성벽이 다 쌓였어."}},{"ref":"느 8:1-3","focus":"square","text":{"t1":"수문 앞 광장에 모인 모든 백성은 학사 에스라에게 모세의 율법책을 가져와 달라고 청했고, 에스라는 새벽부터 정오까지 율법책을 읽었어요. 그때가 어느 달이었는지는 성경에서 찾아봐요.","t2":"칠월이 되자 모든 백성이 한꺼번에 수문 앞 광장에 모였어요. 그리고 학사 에스라에게 모세의 율법책을 가져와 달라고 청했어요. 칠월 일일에 제사장 에스라는 율법책을 들고 남자와 여자, 알아들을 만한 모든 사람 앞에 나왔어요. 그는 새벽부터 정오까지 읽었고, 백성은 모두 율법책에 귀를 기울였어요.","t3":"이스라엘 자손이 자기들의 성읍에 살고 있었는데, 칠월이 되자 모든 백성이 한꺼번에 수문 앞 광장에 모였다. 칠월 일일에 제사장 에스라는 율법책을 들고 남자와 여자, 알아들을 만한 모든 회중 앞에 나왔다. 백성이 먼저 에스라에게 무엇을 청했는지, 에스라가 얼마 동안 읽었고 백성이 어떻게 들었는지는 1절과 3절에서 직접 읽어 보자."},"say":{"who":"hyu","text":"여기는 수문 앞 광장이야. 사람들이 한꺼번에 많이 모였어."}},{"ref":"느 8:4-8","focus":"ezra","text":{"t1":"에스라가 책을 펴자 모든 백성이 일어섰고, 레위 사람들은 백성이 율법을 깨닫도록 뜻을 풀어 주었어요. 에스라가 무엇 위에 섰는지는 성경에서 찾아봐요.","t2":"학사 에스라는 이 일을 위해 만든 나무 강단에 섰어요. 에스라가 책을 편 뒤에 무슨 일이 어떤 차례로 있었는지, 레위 사람들이 율법책의 뜻을 풀어 준 까닭은 무엇인지는 5절부터 8절까지 읽어 봐요.","t3":"학사 에스라는 이 일을 위해 따로 만든 나무 강단에 섰다. 본문은 그 오른쪽에 선 여섯 사람과 왼쪽에 선 일곱 사람의 이름을 적는다. 에스라는 모든 백성보다 높은 곳에 서 있었고, 그들이 보는 앞에서 책을 폈다. 책을 펼 때 백성이 어떻게 했는지, 에스라가 여호와를 송축하자 백성이 어떻게 응답했는지는 5절과 6절에서 직접 읽어 보자. 예수아와 바니와 세레뱌를 비롯한 사람들과 레위 사람들은 제자리에 서 있는 백성에게 율법을 깨닫게 했다. 그들은 하나님의 율법책을 읽고 그 뜻을 풀어 주어, 백성이 읽어 주는 것을 다 깨닫게 했다."},"say":{"who":"choeon","text":"에스라가 책을 펴고 있어. 우리는 가장자리에서 조용히 보자."}},{"ref":"느 8:9-12","focus":"people","text":{"t1":"율법의 말씀을 듣고 우는 백성에게, 느헤미야와 에스라와 레위 사람들은 오늘은 여호와의 성일이니 울지 말라고 했어요. 백성은 돌아가서 먹고 마셨고, 음식을 나누어 주며 크게 기뻐했어요.","t2":"백성은 율법의 말씀을 듣고 모두 울었어요. 총독 느헤미야와 에스라와 레위 사람들은 백성에게 슬퍼하지도 울지도 말라고 했는데, 그 까닭은 9절부터 11절까지 읽어 봐요. 느헤미야는 가서 기름진 것을 먹고 단것을 마시며 준비하지 못한 사람에게 나누어 주라고 했어요. 백성은 돌아가서 먹고 마셨고, 음식을 나누어 주며 크게 기뻐했어요.","t3":"백성은 율법의 말씀을 듣고 모두 울었다. 총독 느헤미야와 제사장이며 학사인 에스라와 백성을 가르치던 레위 사람들이 그 백성에게 무엇이라고 했는지, 느헤미야가 또 무엇을 하라고 했는지는 9절과 10절에서 직접 읽어 보자. 레위 사람들은 백성을 진정시켰다. 모든 백성은 돌아가서 먹고 마셨고, 음식을 나누어 주며 크게 기뻐했다."},"say":{"who":"onwoo","text":"백성이 왜 크게 기뻐했는지는 느헤미야 8장 12절 끝에 적혀 있어. 성경책에서 확인해 보자."}}],"gates":{"t1":[{"type":"find","ref":"느 8:1","prompt":"성경책에서 느헤미야 8장 1절을 찾아 읽어 보세요.","confirm":{"prompt":"모든 백성이 수문 앞 광장에 모여 율법책을 가져와 달라고 한 것은 어느 달이었나요?","options":[{"label":"칠월","ok":true},{"label":"엘룰월","basis":"느 6:15"},{"label":"아달월","basis":"스 6:15"}]}},{"type":"multi","ref":"느 8:6","prompt":"성경책에서 느헤미야 8장 6절을 찾아 읽어 보세요.","confirm":{"prompt":"에스라가 여호와를 송축할 때 백성이 한 일을 모두 고르세요.","options":[{"label":"손을 들었어요","ok":true},{"label":"나팔을 들고 찬송했어요","basis":"스 3:10"},{"label":"아멘 아멘 하고 응답했어요","ok":true},{"label":"왕 만세를 외쳤어요","basis":"삼상 10:24"},{"label":"엎드려 얼굴을 땅에 대고 경배했어요","ok":true}]}}],"t2":[{"type":"find","ref":"느 2:17-18","prompt":"성경책에서 느헤미야 2장 17절과 18절을 읽어 보세요.","confirm":{"prompt":"사람들이 일어나 건축하자고 하며 힘을 낸 까닭은 무엇인가요?","options":[{"label":"느헤미야가 성을 다시 쌓자고 하며, 하나님이 선한 손으로 자기를 도우신 일과 왕이 한 말을 전했기 때문에","ok":true},{"label":"느헤미야가 성을 다시 쌓자고 하며, 왕이 보낸 군대 장관과 마병이 성벽을 대신 쌓아 줄 것이라고 전했기 때문에","basis":"본문에 없음"},{"label":"느헤미야가 성을 다시 쌓자고 하며, 성을 쌓지 않으면 왕이 그들을 벌할 것이라고 전했기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"느 8:1-6","prompt":"성경책에서 느헤미야 8장 1절부터 6절까지 읽고, 일어난 차례대로 눌러 보세요.","items":["백성이 한꺼번에 수문 앞 광장에 모여 율법책을 가져와 달라고 청했다","칠월 일일, 에스라가 책을 들고 모인 사람들 앞에 나왔다","에스라가 책을 펴자 백성이 다 일어섰다","에스라가 크신 하나님을 높여 송축했다","백성이 엎드려 여호와께 경배했다"]}],"t3":[{"type":"find","refs":["느 1:3","느 2:13"],"prompt":"느헤미야 1장 3절과 2장 13절을 함께 찾아 읽어 보자.","confirm":{"prompt":"느헤미야가 전해 들은 소식과 예루살렘에 와서 밤에 직접 본 것을 이어 읽으면 무엇이 보이는가?","options":[{"label":"먼저 예루살렘 성이 헐리고 성문들이 불탔다는 말을 들었고, 예루살렘에 와서 밤에 직접 살펴보니 정말 성벽은 다 무너졌고 성문은 불에 타 있었다","ok":true},{"label":"먼저 예루살렘 성은 무사하고 성 밖의 마을들만 헐렸다는 말을 들었고, 예루살렘에 와서 밤에 직접 살펴보니 성벽은 다 무너졌고 성문은 불에 타 있었다","basis":"본문에 없음"},{"label":"먼저 예루살렘 성을 벌써 다시 쌓았다는 말을 들었고, 예루살렘에 와서 밤에 직접 살펴보니 성벽은 다 무너졌고 성문은 불에 타 있었다","basis":"본문에 없음"}]}},{"type":"match","refs":["느 1:4","느 2:12","느 2:18","느 6:16"],"prompt":"느헤미야 1장 4절, 2장 12절, 2장 18절, 6장 16절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"느 1:4","text":"소식을 듣고 여러 날 울며 슬퍼했고, 금식하며 하나님께 기도했다"},{"ref":"느 2:12","text":"하나님이 그의 마음에 두신 일을 아무에게도 말하지 않고 밤에 나갔다"},{"ref":"느 2:18","text":"선한 손으로 하나님이 자기를 도우신 일을 사람들에게 들려주었다"},{"ref":"느 6:16","text":"대적들이 이 일을 하나님이 이루신 줄 알고 두려워했다"}],"after":"네 곳을 이으면, 느헤미야는 소식을 듣고 하나님께 기도했고, 하나님이 그의 마음에 두신 일을 처음에는 아무에게도 말하지 않다가 하나님이 도우신 일을 사람들에게 들려주었으며, 일이 끝나자 대적들도 하나님이 이루신 줄 알았다."}]},"cards":[{"ref":"느 2:20","title":"하늘의 하나님이 형통케 하시리니"},{"ref":"느 8:10","title":"여호와를 기뻐하는 것이 힘"}],"close":{"t1":{"kind":"prayer","text":"하나님, 예루살렘 성벽과 율법책 읽은 이야기를 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 느헤미야 8장 1절부터 12절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"느 2:11-20, 6:15-16, 8:1-12에서 새로 알게 된 사실을 한 가지 적어 보자."}},"quests":[{"part":"gear","name":"톱니바퀴","line":"톱니바퀴를 찾았어! 골짜기 문 밖, 무너진 성벽에서 조금 떨어진 땅에 있었네.","found":"탐지기가 골짜기 문 쪽을 가리켜요.","say":{"who":"hyu","text":"탐지기 바늘이 골짜기 문 쪽으로 돌아갔어. 느헤미야 일행이 지나가는 길에서는 떨어져서 찾자. 일지에 적어 둘게."},"q":{"t1":{"type":"find","ref":"느 2:13","prompt":"성경책에서 느헤미야 2장 13절을 찾아 읽어 보세요.","confirm":{"prompt":"느헤미야는 밤에 골짜기 문을 나서서 용정을 지나 어느 문까지 갔나요?","options":[{"label":"분문","ok":true},{"label":"수문","basis":"느 8:1"},{"label":"양문","basis":"느 3:1"}]}},"t2":{"type":"find","ref":"느 2:12-16","prompt":"성경책에서 느헤미야 2장 12절부터 16절까지 읽어 보세요.","confirm":{"prompt":"방백들이 느헤미야가 어디에 갔고 무엇을 했는지 알지 못한 까닭은 무엇인가요?","options":[{"label":"느헤미야가 그 일을 아무에게도 말하지 않고 밤에 몇 사람과만 나갔기 때문에","ok":true},{"label":"방백들이 그때 왕의 조서를 받으러 강 서편 총독들에게 가 있었기 때문에","basis":"본문에 없음"},{"label":"느헤미야가 유다 사람들에게만 그 일을 알리고 방백들에게는 알리지 않았기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["느 2:13","느 2:15"],"prompt":"느헤미야 2장 13절과 15절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳을 이어 읽으면, 느헤미야가 밤에 성벽을 살핀 길은 어떠했는가?","options":[{"label":"골짜기 문으로 나가 용정을 지나 분문까지 가며 무너진 성벽과 불탄 성문을 보았고, 시내를 따라 올라가며 살핀 뒤 다시 골짜기 문으로 들어왔다","ok":true},{"label":"골짜기 문으로 나가 샘문을 지나 수문까지 가며 무너진 성벽과 불탄 성문을 보았고, 왕의 못을 돌아 다시 골짜기 문으로 들어왔다","basis":"본문에 없음"},{"label":"골짜기 문으로 나가 용정을 지나 분문까지 가며 무너진 성벽과 불탄 성문을 보았고, 성 밖에서 밤을 지낸 뒤 아침에 분문으로 들어왔다","basis":"본문에 없음"}]}}}},{"part":"needle","name":"나침반 바늘","line":"나침반 바늘이 여기 있었네! 성벽이 올려다보이는 비탈이야.","found":"탐지기가 성벽 쪽을 가리켜요.","say":{"who":"choeon","text":"성벽에는 손대지 말자. 이 비탈에서만 찾자."},"q":{"t1":{"type":"find","ref":"느 6:15","prompt":"성경책에서 느헤미야 6장 15절을 찾아 읽어 보세요.","confirm":{"prompt":"성벽 쌓는 일은 며칠 만에 끝났나요?","options":[{"label":"오십이 일","ok":true},{"label":"칠 일","basis":"본문에 없음"},{"label":"사흘","basis":"느 2:11"}]}},"t2":{"type":"find","ref":"느 6:15-16","prompt":"성경책에서 느헤미야 6장 15절과 16절을 읽어 보세요.","confirm":{"prompt":"성벽 일이 끝났다는 소식에 대적과 둘레의 이방 사람들이 두려워하며 낙담한 까닭은 무엇인가요?","options":[{"label":"이 일을 하나님이 이루셨다는 것을 그들이 알았기 때문에","ok":true},{"label":"성벽 위에 군사가 많이 서 있는 것을 보았기 때문에","basis":"본문에 없음"},{"label":"바사 왕이 그들을 벌하겠다고 했기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["느 2:18","느 6:15"],"prompt":"느헤미야 2장 18절과 6장 15절을 함께 찾아 읽어 보자.","confirm":{"prompt":"느헤미야의 말을 들은 사람들이 하자고 나선 일은 어떻게 되었는가?","options":[{"label":"사람들은 함께 일어나 성을 짓자며 그 좋은 일에 힘을 냈고, 그 일은 오십이 일 만인 엘룰월 이십오일에 끝났다","ok":true},{"label":"사람들은 성 짓는 일을 바사 왕의 사람들에게 맡기자고 했고, 그 일은 오십이 일 만에 끝났다","basis":"본문에 없음"},{"label":"사람들은 함께 일어나 성을 짓자며 힘을 냈고, 그 일은 칠 일 만에 끝났다","basis":"본문에 없음"}]}}}},{"part":"screw","name":"나사","line":"나사를 찾았어! 광장 가장자리에 굴러가 있었어.","found":"탐지기가 수문 앞 광장 쪽을 가리켜요.","say":{"who":"onwoo","text":"광장 가장자리까지만 가자. 우리는 지켜보는 사람이야."},"q":{"t1":{"type":"find","ref":"느 8:4","prompt":"성경책에서 느헤미야 8장 4절을 찾아 읽어 보세요.","confirm":{"prompt":"학사 에스라는 무엇 위에 섰나요?","options":[{"label":"나무 강단","ok":true},{"label":"성벽 꼭대기","basis":"본문에 없음"},{"label":"큰 바위","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"느 8:7-8","prompt":"성경책에서 느헤미야 8장 7절과 8절을 읽어 보세요.","confirm":{"prompt":"레위 사람들이 율법책을 읽어 주며 뜻을 풀어 준 까닭은 무엇인가요?","options":[{"label":"백성이 읽어 주는 것을 다 깨닫게 하려고","ok":true},{"label":"백성이 율법책을 외워서 시험을 보게 하려고","basis":"본문에 없음"},{"label":"에스라가 목이 쉬어 더 읽을 수 없었기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["느 8:1","느 8:3","느 8:5"],"prompt":"느헤미야 8장 1절, 3절, 5절을 함께 찾아 읽어 보자.","confirm":{"prompt":"세 곳을 이어 읽으면, 율법책을 대하는 백성의 모습은 어떠했는가?","options":[{"label":"백성이 먼저 에스라에게 율법책을 가져오라고 청했고, 새벽부터 정오까지 귀를 기울였으며, 에스라가 책을 펼 때 모두 일어섰다","ok":true},{"label":"에스라가 먼저 백성을 불러 모아 율법책을 듣게 했고, 백성은 새벽에 잠깐 듣다가 정오가 되기 전에 모두 돌아갔다","basis":"본문에 없음"},{"label":"백성이 먼저 에스라에게 율법책을 가져오라고 청했고, 정오부터 저녁까지 귀를 기울였으며, 에스라가 책을 펼 때 모두 소리 내어 따라 읽었다","basis":"본문에 없음"}]}}}}],"mission":{"call":{"t1":"최현 박사예요. 비상 착륙 때 타임머신의 톱니바퀴와 나침반 바늘과 나사가 망가졌어요. 탐지기가 가리키는 곳에서 대신 쓸 것을 하나씩 찾고, 사람들을 도울 때는 그들이 하는 평범한 일만 도와요.","t2":"최현 박사예요. 타임머신이 예루살렘에 비상 착륙하면서 톱니바퀴와 나침반 바늘과 나사가 망가졌어요. 이 시대에는 맞는 부속이 없으니, 탐지기가 가리키는 곳에서 구할 수 있는 것으로 하나씩 대신 만들어야 해요. 그곳 사람들을 돕게 되면 그들이 하는 평범한 일만 돕고, 성벽 쌓는 일이나 율법책과 강단에는 손대지 말아요.","t3":"최현 박사다. 여기는 예루살렘이다. 비상 착륙 때 타임머신의 톱니바퀴, 나침반 바늘, 나사가 망가졌다. 맞는 부속이 없으니 탐지기가 가리키는 세 곳에서 구할 수 있는 것으로 하나씩 대신 만들어야 한다. 그곳 사람들을 돕게 되면 본문이 그들이 했다고 적은 평범한 일만 돕자. 성벽 쌓는 일과 율법책, 나무 강단에는 손대지 않는다."},"materials":[{"key":"charcoal","name":"숯 조각","basis":"느 2:13","use":"숯 조각은 깎기 쉬워서, 둥글게 다듬고 가장자리에 홈을 내면 톱니바퀴 대신 쓸 수 있어요.","how":"골짜기 문 밖, 무너진 성벽에서 조금 떨어진 땅에 떨어진 숯 조각을 줍는다. 불탄 성문과 무너진 성벽에는 손대지 않고, 느헤미야 일행이 지나는 길에는 다가가지 않는다.","line":"숯 조각을 찾았어! 골짜기 문 밖, 무너진 성벽에서 조금 떨어진 땅에 있었네."},{"key":"stonechip","name":"얇은 돌 조각","basis":"느 6:15","use":"얇고 길쭉한 돌 조각을 다듬으면 나침반 바늘 대신 쓸 수 있어요.","how":"성벽이 올려다보이는 비탈 땅에 굴러 있던 얇은 돌 조각을 줍는다. 성벽에는 손대지 않는다.","line":"얇은 돌 조각을 찾았어! 성벽이 올려다보이는 비탈에 있었네."},{"key":"twig","name":"마른 나뭇가지","basis":"느 8:1","use":"마른 나뭇가지를 깎아 끝을 뾰족하게 하면 나사 대신 박는 나무못으로 쓸 수 있어요.","how":"수문 앞 광장 가장자리 땅에 떨어진 작은 마른 나뭇가지를 줍는다. 광장 가운데로는 들어가지 않는다.","line":"마른 나뭇가지를 찾았어! 광장 가장자리 땅에 떨어져 있었어."}],"companion":{"who":"느헤미야","when":"after","ref":"느 8:9","talks":[{"ask":{"who":"choeon","text":"밤에 성벽을 살펴본 다음에 사람들에게 뭐라고 했어요?"},"answer":{"t1":"느헤미야는 예루살렘이 황폐하고 성문이 불탔으니, 성을 다시 쌓아 더는 수치를 당하지 말자고 말했어요.","t2":"느헤미야는 사람들에게, 자기들이 겪는 어려움을 그들도 보고 있다고 말했어요. 예루살렘이 황폐하고 성문이 불탔으니 예루살렘 성을 다시 쌓아 더는 수치를 당하지 말자고 했어요.","t3":"느헤미야는 자기들이 당한 곤경을 그들도 보고 있다고 말하고, 예루살렘이 황폐하고 성문이 불탔으니 예루살렘 성을 다시 쌓아 다시는 수치를 받지 말자고 했다."},"ref":"느 2:17","open":"느 2:17"},{"ask":{"who":"hyu","text":"비웃는 사람들에게는 뭐라고 대답했어요?"},"answer":{"t1":"느헤미야는 하늘의 하나님이 자기들을 잘되게 하실 것이니, 그분의 종인 자기들이 일어나 성을 쌓겠다고 대답했어요.","t2":"느헤미야는 하늘의 하나님이 자기들을 형통하게 하실 것이니, 그분의 종인 자기들이 일어나 건축하겠다고 대답했어요. 그리고 비웃는 사람들에게는 예루살렘에서 아무 몫도, 권리도, 기억될 것도 없다고 말했어요.","t3":"느헤미야는 하늘의 하나님이 자기들을 형통하게 하실 것이므로 그분의 종인 자기들이 일어나 건축하겠다고 대답했다. 그리고 비웃는 그들에게는 예루살렘에서 아무 기업도, 권리도, 기억될 것도 없다고 했다."},"ref":"느 2:20","open":"느 2:20"}]},"today":[{"q":"성벽을 어떻게 오십이 일 만에 다 쌓았어요?","a":{"t1":"느헤미야 3장에는 제사장들과 여러 사람이 저마다 한 부분씩 맡아 성벽을 쌓은 일이 적혀 있어요. 느헤미야는 백성이 마음을 들여 일했다고 적었어요.","t2":"느헤미야 3장에는 대제사장과 제사장들, 여리고 사람들, 금장색과 상고들까지 많은 사람이 저마다 한 부분씩 맡아 성벽과 문을 쌓고 고친 일이 적혀 있어요. 느헤미야는 백성이 마음을 들여 일했다고 적었어요. 대적들은 이 일을 하나님이 이루셨다는 것을 알았다고 해요.","t3":"느헤미야 3장은 대제사장 엘리아십과 제사장들, 여리고 사람들, 금장색과 상고들처럼 많은 사람이 저마다 맡은 부분을 쌓거나 고친 일을 차례로 적는다. 4:6은 백성이 마음을 들여 일했다고 하고, 6:16은 대적들이 이 일을 하나님이 이루신 줄 알았다고 한다. 오십이 일 만에 마친 일에 대해 성경은 이만큼 말한다."},"refs":["느 3:1-2","느 3:32","느 4:6","느 6:16"]}],"help":{"who":"수문 앞 광장에 모였던 백성의 한 집","steps":[{"kind":"watch","after":0,"title":"곁에서 보기 · 밤에 성벽을 살피는 일행","basis":"느 2:12-13","text":{"t1":"밤에 느헤미야가 몇 사람과 함께 골짜기 문으로 나가 성벽을 살펴요. 우리는 따라가지 않고 멀리서 봐요.","t2":"느헤미야는 밤에 몇 사람과 함께 골짜기 문으로 나가 무너진 성벽을 살펴요. 성벽을 살피는 일은 느헤미야 일행이 해요. 우리는 따라가지 않고 멀리서 봐요.","t3":"느헤미야는 하나님이 그의 마음에 두신 일을 누구에게도 말하지 않은 채, 밤에 두어 사람과 함께 나가 무너진 성벽을 살핀다. 탐험대는 그 일행을 따라가지 않고, 길에서 떨어진 곳에서 멀리 본다."},"say":{"who":"onwoo","text":"느헤미야 일행은 따라가지 말자. 어느 문으로 나갔는지는 2장 13절에 있어."}},{"kind":"stay","after":4,"title":"광장 가장자리에서 함께 듣기","basis":"느 8:3","text":{"t1":"에스라가 수문 앞 광장에서 율법책을 읽어요. 모든 백성이 귀를 기울여요. 우리도 광장 가장자리에서 함께 들어요.","t2":"에스라가 수문 앞 광장에서 남자와 여자, 알아들을 만한 모든 사람 앞에서 율법책을 읽어요. 모든 백성이 귀를 기울여요. 우리는 모인 사람들 사이로 들어가지 않고, 광장 가장자리에서 함께 들어요.","t3":"에스라가 수문 앞 광장에서 남자와 여자, 알아들을 만한 모든 사람 앞에서 율법책을 읽는다. 탐험대는 모인 백성 사이로 끼어들지 않고, 광장 가장자리에서 함께 귀를 기울인다."},"wait":"가장자리에서 함께 듣기","say":{"who":"onwoo","text":"우리는 여기 가장자리에서 들을게. 가운데로는 들어가지 말자."}},{"kind":"do","after":6,"title":"준비하지 못한 사람에게 나누어 주기","basis":"느 8:10-12","text":{"t1":"느헤미야가 가서 먹고 마시고, 준비하지 못한 사람에게 나누어 주라고 했어요. 우리는 이 집 식구들이 음식을 나누어 주는 일을 도와요.","t2":"광장에서 돌아간 백성은 느헤미야가 말한 대로 먹고 마시며, 준비하지 못한 사람에게 음식을 나누어 줘요. 우리는 이 집 식구들 곁에서 나누어 줄 몫을 나르는 일을 도와요.","t3":"느헤미야는 백성에게 가서 기름진 것을 먹고 단것을 마시며, 준비하지 못한 사람에게는 나누어 주라고 했다(8:10). 모든 백성은 돌아가서 먹고 마셨고, 음식을 나누며 크게 기뻐했다(8:12). 탐험대는 이 집 식구들이 준비하지 못한 사람에게 몫을 나누어 주는 일을 돕는다."},"tasks":["나누어 줄 음식 들어 주기","준비하지 못한 사람에게 가져가기","몫을 건네주기"],"done":{"who":"choeon","text":"준비하지 못한 사람에게도 몫이 갔어. 다들 크게 기뻐하고 있어."}},{"kind":"ask","after":"gates","title":"먹고 나누며 기뻐한 일은 무슨 뜻이에요?","basis":"느 8:9-10","by":"느헤미야","ask":{"who":"onwoo","text":"느헤미야 님, 울던 백성에게 먹고 마시고 나누어 주라고 한 것은 무슨 뜻이에요?"},"answer":{"t1":"느헤미야는 오늘은 여호와의 성일이라며 슬퍼하지도 울지도 말라고 했어요. 여호와를 기뻐하는 것이 그들의 힘이라고 말했어요.","t2":"느헤미야는 에스라와 레위 사람들과 함께, 오늘은 하나님 여호와의 성일이라고 하며 슬퍼하지도 울지도 말라고 했어요. 그리고 가서 기름진 것을 먹고 단것을 마시며 준비하지 못한 사람에게 나누어 주라고 했어요. 여호와를 기뻐하는 것이 그들의 힘이라고 했어요.","t3":"느헤미야는 에스라와 백성을 가르치던 레위 사람들과 함께, 오늘은 그들의 하나님 여호와의 성일이라고 하며 슬퍼하지도 울지도 말라고 했다. 또 가서 기름진 것을 먹고 단것을 마시며 준비하지 못한 사람에게 나누어 주라고 했고, 이날은 주께 거룩한 날이니 근심하지 말라고 했다. 여호와를 기뻐하는 것이 그들의 힘이라고 말했다."},"read":{"t1":{"type":"find","ref":"느 8:10","prompt":"성경책에서 느헤미야 8장 10절을 찾아 읽어 보세요.","confirm":{"prompt":"느헤미야는 무엇이 백성의 힘이라고 했나요?","options":[{"label":"여호와를 기뻐함","ok":true},{"label":"높은 성벽","basis":"본문에 없음"},{"label":"많은 군사","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"느 8:9-11","prompt":"성경책에서 느헤미야 8장 9절부터 11절까지 읽어 보세요.","confirm":{"prompt":"느헤미야와 에스라와 레위 사람들이 백성에게 슬퍼하지도 울지도 말라고 한 까닭은 무엇인가요?","options":[{"label":"오늘은 여호와의 성일이고, 여호와를 기뻐함이 그들의 힘이기 때문에","ok":true},{"label":"오늘은 율법책을 다 읽은 날이고, 이제 더 들을 말씀이 남아 있지 않기 때문에","basis":"본문에 없음"},{"label":"울음소리가 멀리 들리면 산발랏과 도비야가 다시 비웃을 것이기 때문에","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["느 8:9","느 8:10","느 8:12"],"prompt":"느헤미야 8장 9절, 10절, 12절을 함께 찾아 읽어 보자.","confirm":{"prompt":"세 곳을 이어 읽으면, 율법의 말씀을 듣고 울던 백성은 어떻게 되었는가?","options":[{"label":"율법의 말씀을 들으며 모두 울었는데, 느헤미야와 에스라와 레위 사람들이 성일이니 울지 말라 했고, 느헤미야가 먹고 마시며 나누어 주라고 하자, 백성은 들은 말씀을 밝히 깨달아 그대로 하며 크게 즐거워했다","ok":true},{"label":"율법의 말씀을 들으며 모두 울었는데, 느헤미야와 에스라와 레위 사람들이 성일이니 울지 말라 했고, 느헤미야가 먹고 마시며 나누어 주라고 하자, 백성은 성벽이 다 쌓였기 때문에 크게 즐거워했다","basis":"본문에 없음"},{"label":"율법의 말씀을 들으며 모두 울었는데, 느헤미야와 에스라와 레위 사람들이 율법책을 다 읽었으니 울지 말라 했고, 느헤미야가 먹고 마시며 나누어 주라고 하자, 백성은 대적들이 물러간 것을 알고 크게 즐거워했다","basis":"본문에 없음"}]}}}}]}},"has3d":true,"epic":false},"OT-40":{"id":"OT-40","era":10,"title":"말라기, 약속을 기다림","ref":"말 3:1","place":"여호와께서 말라기로 이스라엘에게 하신 말씀. 말씀 속에 호렙이 나온다","review":{"required":true,"topics":["구약 사건의 신약적 의미(말 3:1, 4:2, 4:5-6)","재앙과 심판(말 4:1, 4:3, 4:6)"],"status":"미감수"},"sources":"없음(성경 본문만 사용)","beats":[{"ref":"말 3:1","open":"말 3:1","focus":"word","text":{"t1":"만군의 여호와께서 앞으로 일어날 일을 말씀하셨어요.","t2":"만군의 여호와께서 말씀하셨어요. 자기의 사자를 보내겠고, 그 사자가 여호와 앞에서 길을 준비할 것이라고 하셨어요. 또 백성이 찾는 주께서 갑자기 그 전에 임하실 것이며, 곧 백성이 사모하는 언약의 사자가 올 것이라고 하셨어요.","t3":"만군의 여호와께서는 자기의 사자를 보내겠다고 하셨고, 이어서 앞으로 있을 일을 말씀하셨다."},"say":{"who":"onwoo","text":"이 대목은 모두 여호와께서 하신 말씀이야. 우리가 지어내면 안 되니까 성경책에서 직접 읽어 보자."}},{"ref":"말 4:1","open":"말 4:1","focus":"word","text":{"t1":"여호와께서는 뜨거운 풀무불 같은 날이 올 것이라고 하셨어요. 교만한 사람과 악을 행하는 사람은 그날에 지푸라기 같을 것이라고 하셨어요.","t2":"만군의 여호와께서는 뜨겁게 타는 풀무불 같은 날이 올 것이라고 하셨어요.","t3":"만군의 여호와께서는 맹렬한 풀무불 같은 날이 이를 것이라고 하셨다. 교만한 사람과 악을 행하는 사람은 모두 초개, 곧 지푸라기 같을 것이며, 다가오는 그날이 그들을 살라 뿌리도 가지도 남기지 않을 것이라고 하셨다."},"say":{"who":"hyu","text":"말씀에 풀무불 같은 날이 나와. 일지에 적어 둘게."}},{"ref":"말 4:2-3","open":"말 4:2","focus":"word","text":{"t1":"여호와의 이름을 경외하는 사람들에게는 의로운 해가 떠오를 것이라고 하셨어요. 그들이 무엇처럼 뛸 것이라고 하셨는지는 성경에서 찾아봐요.","t2":"여호와께서는 그 이름을 경외하는 사람들이 나가서 외양간을 나온 송아지처럼 뛸 것이라고 하셨어요. 그들에게 무엇이 떠올라 무엇을 비출 것이라고 하셨는지는 2절에서 찾아봐요. 또 여호와께서 정하신 날에 악인은 그들의 발바닥 밑의 재와 같을 것이라고 하셨어요.","t3":"여호와께서는 그 이름을 경외하는 이들에게는 의로운 해가 떠올라 치료하는 광선을 비출 것이며, 그들이 나가서 외양간에서 나온 송아지처럼 뛸 것이라고 하셨다. 또 그들이 악인을 밟을 것이며, 여호와께서 정하신 날에 악인이 그들의 발바닥 밑의 재와 같을 것이라고 하셨다. 본문은 이것이 만군의 여호와의 말씀이라고 적는다."},"say":{"who":"choeon","text":"여호와의 이름을 경외하는 사람들에게 하신 말씀이야. 일지에 적어 둘게."}},{"ref":"말 4:4","open":"말 4:4","focus":"word","text":{"t1":"여호와께서는 모세에게 명하신 법을 기억하라고 하셨어요. 호렙에서 온 이스라엘을 위해 주신 법이에요.","t2":"여호와께서는 백성에게 기억해야 할 것을 말씀하셨어요.","t3":"여호와께서는 백성에게 기억할 것을 말씀하셨다. 무엇을 기억하라고 하셨는지는 4절에서 직접 읽어 보자."},"say":{"who":"hyu","text":"호렙과 모세라는 이름이 나와. 일지에 적어 둘게."}},{"ref":"말 4:5","open":"말 4:5","focus":"word","text":{"t1":"여호와께서는 선지자 엘리야를 보내겠다고 하셨어요. 여호와의 크고 두려운 날이 오기 전에 보내겠다고 하셨어요.","t2":"여호와께서는 선지자 엘리야를 백성에게 보내겠다고 하셨어요. 여호와의 크고 두려운 날이 오기 전에 보내겠다고 하셨어요.","t3":"여호와께서는 선지자 엘리야를 그들에게 보내겠다고 하셨다. 언제 보내시겠다고 하셨는지는 5절에 있다."},"say":{"who":"choeon","text":"엘리야라는 이름이 나왔어! 선지자 엘리야를 보내겠다고 하셨대."}},{"ref":"말 4:6","open":"말 4:6","focus":"word","text":{"t1":"여호와께서는 엘리야가 와서 마음을 돌이키게 할 것이라고 하셨어요.","t2":"여호와께서는 엘리야가 아버지의 마음을 자녀에게로, 자녀들의 마음을 아버지에게로 돌이키게 할 것이라고 하셨어요.","t3":"마지막으로 여호와께서는 엘리야가 와서 할 일을 말씀하셨다."},"say":{"who":"onwoo","text":"말라기는 4장 6절에서 끝나. 성경책을 펴서 그 절까지 직접 읽어 보자."}}],"gates":{"t1":[{"type":"find","ref":"말 4:2","prompt":"성경책에서 말라기 4장 2절을 찾아 읽어 보세요.","confirm":{"prompt":"여호와의 이름을 경외하는 사람들은 무엇처럼 뛸 것이라고 하셨나요?","options":[{"label":"외양간을 나온 송아지","ok":true},{"label":"바위 위의 산양","basis":"본문에 없음"},{"label":"사슴","basis":"사 35:6"}]}},{"type":"multi","ref":"말 3:1","prompt":"성경책에서 말라기 3장 1절을 찾아 읽어 보세요.","confirm":{"prompt":"말라기 3장 1절에서 여호와께서 하신 말씀을 모두 고르세요.","options":[{"label":"사자를 보내겠다고 하셨어요","ok":true},{"label":"모세의 법을 기억하라고 하셨어요","basis":"말 4:4"},{"label":"그 사자가 앞서 길을 준비할 거라고 하셨어요","ok":true},{"label":"선지자 엘리야를 보내겠다고 하셨어요","basis":"말 4:5"},{"label":"주께서 갑자기 그 전에 오실 거라고 하셨어요","ok":true}]}}],"t2":[{"type":"find","ref":"말 4:2-3","prompt":"성경책에서 말라기 4장 2절과 3절을 읽어 보세요.","confirm":{"prompt":"여호와의 이름을 경외하는 사람들이 외양간을 나온 송아지처럼 뛰게 되는 것은 무엇 때문이라고 하셨나요?","options":[{"label":"의로운 해가 떠올라 치료하는 빛을 비추기 때문에","ok":true},{"label":"밝은 달이 떠올라 어두운 밤길을 비추기 때문에","basis":"본문에 없음"},{"label":"큰 별이 떠올라 캄캄한 들판을 환히 비추기 때문에","basis":"본문에 없음"}]}},{"type":"order","ref":"말 4:1-5","prompt":"성경책에서 말라기 4장 1절부터 5절까지 읽고, 말씀이 나오는 차례대로 눌러 보세요.","items":["교만한 사람과 악한 일을 하는 사람은 지푸라기 같으리라고 하셨다","이름을 경외하는 이들은 외양간을 나온 송아지처럼 뛰리라고 하셨다","호렙에서 모세에게 명하신 법을 기억하라고 하셨다","크고 두려운 날 전에 선지자 엘리야를 보내겠다고 하셨다"]}],"t3":[{"type":"find","refs":["말 3:1","말 4:5"],"prompt":"말라기 3장 1절과 4장 5절을 함께 찾아 읽어 보자.","confirm":{"prompt":"두 곳에서 여호와께서 보내시겠다고 하신 이는 각각 무엇을 하거나 언제 오는가?","options":[{"label":"3장 1절의 사자는 여호와보다 앞서 길을 준비하고, 4장 5절의 선지자 엘리야는 크고 두려운 여호와의 날 전에 온다","ok":true},{"label":"3장 1절의 사자는 여호와의 날이 지난 뒤에 오고, 4장 5절의 선지자 엘리야는 호렙에서 모세의 법을 새로 받는다","basis":"본문에 없음"},{"label":"3장 1절의 사자는 무너진 성벽을 다시 쌓고, 4장 5절의 선지자 엘리야는 여호와의 전을 새로 짓는다","basis":"본문에 없음"}]}},{"type":"match","refs":["말 3:1","말 4:1","말 4:2"],"prompt":"말라기 3장 1절, 4장 1절, 4장 2절을 찾아 읽고, 구절마다 맞는 내용을 이어 보자.","pairs":[{"ref":"말 3:1","text":"그들이 사모하는 언약의 사자가 오리라"},{"ref":"말 4:1","text":"풀무불 같은 날이 오면 교만한 사람과 악한 사람은 지푸라기 같으리라"},{"ref":"말 4:2","text":"그 이름을 경외하는 이들에게는 의로운 해가 떠오르고 치료하는 빛이 비치리라"}],"after":"세 곳을 이으면, 여호와께서는 언약의 사자가 오리라고 하셨고, 풀무불 같은 날에 교만한 사람과 악한 사람은 지푸라기 같겠지만 그 이름을 경외하는 이들에게는 의로운 해가 떠오르리라고 하셨다."}]},"cards":[{"ref":"말 3:1","title":"길을 예비할 사자"},{"ref":"말 4:2","title":"의로운 해"}],"close":{"t1":{"kind":"prayer","text":"하나님, 말라기에 적힌 하나님의 말씀을 성경에서 읽고 기억하게 해 주세요. 예수님의 이름으로 기도합니다. 아멘."},"t2":{"kind":"practice","text":"이번 주에 말라기 4장 1절부터 6절까지 소리 내어 읽어 보세요."},"t3":{"kind":"note","prompt":"말 3:1, 4:1-6에서 새로 알게 된 사실을 한 가지 적어 보자."}},"mission":{"call":{"t1":"최현 박사예요. 비상 착륙 때 타임머신의 가는 공기 관 하나가 찌그러졌어요. 속이 빈 가는 대롱을 찾아 주세요.","t2":"최현 박사예요. 비상 착륙 때 타임머신의 가는 공기 관 하나가 찌그러져서 바람이 잘 통하지 않아요. 이 시대에는 맞는 부속이 없으니, 그 자리에서 구할 수 있는 속이 빈 가는 것으로 대신해야 해요.","t3":"최현 박사다. 비상 착륙 때 타임머신의 가는 공기 관 하나가 찌그러져 바람이 통하지 않는다. 맞는 부속이 없으니 그 자리에서 구할 수 있는, 속이 빈 가는 대롱으로 대신해야 한다."},"materials":[{"key":"straw","name":"지푸라기","basis":"말 4:1","use":"속이 빈 지푸라기 몇 가닥을 묶으면 찌그러진 공기 관 대신 쓸 수 있어요.","how":"타임머신이 내린 자리 둘레 땅에 흩어진 지푸라기 몇 가닥을 줍는다.","line":"지푸라기를 찾았어! 타임머신이 내린 자리 둘레 땅에 흩어져 있었어."}],"companion":null,"today":[{"q":"말라기는 누구예요?","a":{"t1":"말라기 1장 1절은 이 책이 여호와께서 말라기를 통해 이스라엘에게 하신 말씀이라고 적어요. 말라기가 어디 사람인지, 언제 말씀을 전했는지는 이 책에 적혀 있지 않아요.","t2":"말라기 1장 1절은 이 책이 여호와께서 말라기를 통해 이스라엘에게 하신 말씀이라고 소개해요. 이 책은 말라기의 집안이나 고향, 말씀을 전한 때와 곳은 적지 않아요. 성경은 여기까지 말해요.","t3":"말라기 1:1은 이 책을 여호와께서 말라기로 말미암아 이스라엘에게 하신 말씀이라고 소개한다. 이 책은 말라기의 집안이나 고향, 말씀을 전한 때와 곳을 적지 않는다. 성경은 여기까지 말한다."},"refs":["말 1:1"]},{"q":"호렙은 어떤 곳이에요?","a":{"t1":"말라기 4장 4절은 여호와께서 호렙에서 모세에게 명하신 법을 기억하라고 하셨다고 적어요. 호렙은 모세가 양 떼를 치다가 이른 하나님의 산이에요. 모세는 여호와께서 호렙 산에서 이스라엘과 언약을 세우셨다고 말했어요.","t2":"말라기 4장 4절은 여호와께서 호렙에서 온 이스라엘을 위해 모세에게 명하신 법을 기억하라고 하셨다고 적어요. 출애굽기 3장 1절에서 호렙은 모세가 장인 이드로의 양 떼를 이끌고 이른 하나님의 산이에요. 신명기 5장 2절에서 모세는 여호와께서 호렙 산에서 이스라엘과 언약을 세우셨다고 말했어요.","t3":"말라기 4:4는 여호와께서 호렙에서 온 이스라엘을 위해 모세에게 명하신 법, 곧 율례와 법도를 기억하라고 하셨다고 적는다. 호렙은 출애굽기 3:1에서 모세가 이드로의 양 떼를 이끌고 이른 하나님의 산으로 나온다. 신명기 4:10과 5:2에서 모세는 이스라엘이 호렙 산에서 여호와 앞에 섰던 날과, 여호와께서 그곳에서 이스라엘과 언약을 세우신 일을 말한다."},"refs":["말 4:4","출 3:1","신 4:10","신 5:2"]}],"help":{"who":"돕는 상대 없음(이 장면은 만군의 여호와의 말씀뿐이다)","steps":[{"kind":"stay","after":5,"title":"마지막 절에 머물기","basis":"말 4:6","text":{"t1":"말라기는 4장 6절에서 끝나요. 우리는 성경책을 덮지 않고 이 마지막 절을 한 번 더 읽으며 머물러요.","t2":"말라기는 엘리야가 아버지와 자녀의 마음을 서로에게로 돌이키게 하리라는 말씀이 적힌 4장 6절로 끝나요. 우리는 성경책을 덮지 않고, 이 마지막 절을 한 번 더 읽으며 잠시 머물러요.","t3":"말라기는 4장 6절의 말씀으로 끝난다. 탐험대는 성경책을 덮지 않고 이 마지막 절을 한 번 더 읽으며 잠시 머문다. 이 말씀 뒤의 일은 이 범위에 적혀 있지 않다."},"wait":"마지막 절에 머물기","say":{"who":"onwoo","text":"성경책은 덮지 말자. 마지막 절을 한 번 더 천천히 읽자."}},{"kind":"do","after":5,"title":"마지막 절을 일지에 옮겨 적기","basis":"말 4:6","text":{"t1":"이건 탐험대의 일이에요. 우리는 펴 둔 성경책을 보며, 말라기의 마지막 절인 4장 6절을 탐험 일지에 옮겨 적어요.","t2":"이것은 성경에 적힌 일이 아니라 탐험대의 일이에요. 우리는 펴 둔 성경책을 보며 말라기의 마지막 절인 4장 6절을 탐험 일지에 또박또박 옮겨 적고, 장과 절도 함께 적어 둬요.","t3":"탐험대는 펴 둔 성경책을 보며 말라기의 마지막 절(4:6)을 탐험 일지에 옮겨 적는다. 본문에 적힌 일이 아니라 탐험대의 일이다. 말씀의 뜻을 풀이하는 말은 덧붙이지 않고, 장과 절을 함께 적어 둔다."},"tasks":["성경책에서 말라기 4장 6절 펴기","마지막 절을 일지에 옮겨 적기","장과 절 적어 두기"],"done":{"who":"hyu","text":"말라기 4장 6절, 일지에 다 옮겨 적었어."}},{"kind":"ask","after":"gates","title":"말라기의 마지막 말씀은 무슨 뜻이에요?","basis":"말 4:5-6","by":"최현 박사","ask":{"who":"choeon","text":"엘리야를 보내시겠다는 말라기의 마지막 말씀은 무슨 뜻이에요?"},"answer":{"t1":"말라기는 여호와께서 크고 두려운 날 전에 선지자 엘리야를 보내시겠다고 하셨다고 적어요. 엘리야는 아버지와 자녀의 마음을 서로에게로 돌이키게 할 것이라고 하셨어요. 그 엘리야가 누구인지는 말라기에 적혀 있지 않아요.","t2":"말라기 4장 5절과 6절은 여호와께서 크고 두려운 날이 오기 전에 선지자 엘리야를 보내시겠다고 하신 말씀이에요. 엘리야는 아버지의 마음을 자녀에게로, 자녀의 마음을 아버지에게로 돌이키게 할 것이고, 돌이키지 않으면 여호와께서 오셔서 저주로 그 땅을 치실까 한다고 하셨어요. 말라기는 그 엘리야가 누구인지는 더 말하지 않아요.","t3":"말라기 4:5-6에서 여호와께서는 크고 두려운 여호와의 날이 이르기 전에 선지자 엘리야를 보내시겠다고 하셨다. 엘리야는 아버지의 마음을 자녀에게로, 자녀들의 마음을 그 아버지에게로 돌이키게 할 것이며, 돌이키지 않으면 여호와께서 와서 저주로 그 땅을 치실까 한다고 하셨다. 말라기는 3:1의 사자와 이 엘리야가 누구인지 풀이하지 않는다. 성경은 여기까지 말한다."},"read":{"t1":{"type":"find","ref":"말 4:6","prompt":"성경책에서 말라기 4장 6절을 찾아 읽어 보세요.","confirm":{"prompt":"엘리야는 누구의 마음을 누구에게로 돌이키게 할 것이라고 하셨나요?","options":[{"label":"아버지의 마음은 자녀에게로, 자녀의 마음은 아버지에게로","ok":true},{"label":"왕의 마음은 백성에게로, 백성의 마음은 왕에게로","basis":"본문에 없음"},{"label":"제사장의 마음은 성전으로, 백성의 마음은 제사장에게로","basis":"본문에 없음"}]}},"t2":{"type":"find","ref":"말 4:5-6","prompt":"성경책에서 말라기 4장 5절과 6절을 읽어 보세요.","confirm":{"prompt":"아버지와 자녀의 마음을 돌이켜야 하는 까닭으로 여호와께서는 무엇을 말씀하셨나요?","options":[{"label":"돌이키지 않으면 여호와께서 오셔서 저주로 그 땅을 치실까 한다고 하셨어요","ok":true},{"label":"돌이키지 않으면 엘리야가 다시 하늘로 돌아가 버린다고 하셨어요","basis":"본문에 없음"},{"label":"돌이키지 않으면 크고 두려운 날이 더 빨리 온다고 하셨어요","basis":"본문에 없음"}]}},"t3":{"type":"find","refs":["말 4:4","말 4:5","말 4:6"],"prompt":"말라기 4장 4절, 5절, 6절을 함께 찾아 읽어 보자.","confirm":{"prompt":"말라기의 마지막 세 절을 이어 읽으면, 여호와께서는 무엇을 하라고 하시고 무엇을 하시겠다고 하셨는가?","options":[{"label":"호렙에서 모세에게 명하신 법을 기억하라고 하셨고, 크고 두려운 날 전에 선지자 엘리야를 보내시겠다고 하셨으며, 그가 아버지와 자녀의 마음을 서로에게 돌아서게 하리라고 하셨다","ok":true},{"label":"호렙에서 모세에게 명하신 법을 기억하라고 하셨고, 크고 두려운 날 전에 선지자 엘리야를 보내시겠다고 하셨으며, 그가 흩어진 백성을 예루살렘으로 다시 모으리라고 하셨다","basis":"본문에 없음"},{"label":"호렙에서 모세가 쳐서 물을 낸 반석을 기억하라고 하셨고, 크고 두려운 날 전에 선지자 엘리야를 보내시겠다고 하셨으며, 그가 백성을 다시 호렙 산으로 이끌어 가리라고 하셨다","basis":"본문에 없음"}]}}}}]}},"has3d":false,"epic":false}},"threads":{"intro":{"title":"비상 착륙","rv":1,"why":"탐험대 이야기(창작). 비상 착륙의 까닭을 낡은 부속으로 두었다.","scenes":[{"art":"fly","who":"narr","text":"시간 속을 달리는 타임머신, 덜컹이."},{"art":"shake","who":"narr","text":"덜컹! 덜컹! 낡은 부속이 하나씩 떨어져 나가요."},{"art":"dark","who":"narr","text":"계기판의 불 열 개가 모두 꺼졌어요."},{"art":"land","who":"doctor","text":"얘들아, 들리니? 나 최현 박사야. 통신은 살아 있어!"},{"art":"land","who":"doctor","text":"덜컹이를 고쳐야 집에 돌아올 수 있어. 그 시대에는 우리 부속이 없으니, 그곳의 평범한 재료로 대신 만들자."},{"art":"land","who":"onwoo","text":"사건이 일어나는 자리의 물건에는 손대지 말자. 떨어진 것만 줍고, 본 것은 성경책에서 꼭 확인하자."}],"rule":"과거에는 아무것도 남기지 않아요. 가져오는 것은 사진과 기록, 그리고 고치고 만들고 기르는 데 쓸 평범한 재료뿐이에요. 기념품은 가져오지 않아요."},"blueprints":[{"id":"oil","n":1,"shadow":"미끄러운 것","part":"회전축 기름","icon":"drop","problem":"회전축이 뻑뻑해서 끼익 소리가 나. 미끄러운 기름이 필요해.","ask":"성경에 '나의 기름'을 말한 나무가 나와. 어느 나무인지 찾아볼래?","find":{"type":"find","ref":"삿 9:8-9","prompt":"성경책에서 사사기 9장 8절과 9절을 찾아 읽어 보세요.","confirm":{"prompt":"요담의 이야기에서 '나의 기름'을 말한 나무는 무엇인가요?","options":[{"label":"감람나무","ok":true},{"label":"무화과나무","basis":"삿 9:11"},{"label":"포도나무","basis":"삿 9:13"}]}},"found":"감람나무구나! 노아의 방주 이야기에 감람나무 잎이 나와. 창세기 8장 11절이야. 그 장면에 가면 떨어진 가지를 찾을 수 있을 거야.","ref":"창 8:11","want":{"name":"감람나무 잔가지","scenes":["OT-03"]},"got":"잔가지 하나로는 기름이 안 나. 뒤칸 온실에 꽂아서 기르자!","rv":2,"why":"새 성경 물음(삿 9:8-9). 요담의 이야기는 아비멜렉 사건 속에 있어 8~9절만 읽게 했다. '방주 이야기에 감람나무 잎이 나온다'는 말이 OT-03의 11~13세 순서 맞추기 항목과 닿는다(13.9)."},{"id":"belt","n":2,"shadow":"꼬아서 질긴 것","part":"구동 줄","icon":"rope","problem":"바퀴를 돌리던 줄이 끊어졌어. 꼬아서 질긴 줄이 필요해.","ask":"잠언에 손으로 부지런히 일하는 사람이 구한 것이 적혀 있어. 무엇인지 찾아볼래?","find":{"type":"find","ref":"잠 31:13","prompt":"성경책에서 잠언 31장 13절을 찾아 읽어 보세요.","confirm":{"prompt":"그 사람이 구해서 손으로 일한 것은 무엇인가요?","options":[{"label":"양털과 삼","ok":true},{"label":"세마포와 자색 옷","basis":"잠 31:22"},{"label":"금과 은","basis":"본문에 없음"}]}},"found":"양털이면 꼬아서 줄을 만들 수 있어! 양 떼가 있는 장면에서 떨어진 양털을 찾아보자.","ref":"잠 31:13","want":{"name":"양털","match":"양털"},"got":"양털을 구했구나! 작업대에서 실을 뽑아 줄을 만들자.","rv":2,"why":"새 성경 물음(잠 31:13). 양털로 만든 줄이 기계의 구동 줄이 되는 것은 탐험대의 가상 기술이다."}],"greenhouse":{"open":"뒤칸 문이 열렸어요! 여기는 온실이에요.","doctor":"덜컹이가 시간을 건널 때마다 온실의 시간도 함께 흘러. 장면을 하나 다녀오면 조금 자라 있을 거야.","plant":"잔가지 꽂기","water":"물 주기","turn":"화분 돌리기","stages":[{"at":0,"key":"twig","name":"잔가지","say":"잔가지를 화분에 꽂았어요."},{"at":1,"key":"leaf","name":"새 잎","say":"새 잎이 하나 났어요!"},{"at":2,"key":"root","name":"뿌리","say":"뿌리가 내렸어요. 이제 혼자 설 수 있어요."},{"at":4,"key":"young","name":"어린 나무","say":"어린 나무가 됐어요."},{"at":8,"key":"branch","name":"가지 뻗은 나무","say":"가지가 여러 갈래로 뻗었어요."},{"at":12,"key":"flower","name":"꽃 핀 나무","say":"작은 꽃이 피었어요."},{"at":16,"key":"fruit","name":"열매 맺은 나무","say":"열매가 열렸어요! 기름을 짤 수 있겠어요."}],"lean":"나무가 창 쪽으로 기울었어요. 화분을 돌려 주면 다음에는 곧게 자라요.","press":{"label":"기름 짜기","hint":"천천히 눌러요. 세게만 누르면 씨가 깨져 탁해져요.","done":"기름이 모였어요! 회전축에 바르자 끼익 소리가 사라졌어요."},"rv":2,"why":"과거의 잔가지를 가져와 기르는 것(규칙서 13.11). 잔가지를 꽂아 기를 수 있는지와 자라는 차례는 원예 사실로 확인이 필요하다. 기름은 '기계 기름'으로만 부르고 성막의 기름과 잇지 않는다."},"bench":{"open":"작업대 불이 켜졌어요!","spin":{"title":"실 잣기","lead":"양털을 그냥 당기면 끊어져요. 빙글빙글 돌린 다음에 당겨 보세요.","twist":"돌리기","pull":"당기기","snap":"툭! 끊어졌어요. 더 돌린 다음에 당겨요.","ok":"실이 길어졌어요!","done":"실 한 타래가 됐어요."},"ply":{"title":"끈 꼬기","lead":"실 두 가닥을 꼬아 끈을 만들어요. 어느 쪽으로 꼬아야 풀리지 않을까요?","same":"실을 꼰 쪽과 같은 쪽으로","opp":"실을 꼰 쪽과 반대쪽으로","bad":"스르르 풀려 버렸어요. 다른 쪽으로 꼬아 봐요.","done":"풀리지 않는 끈이 됐어요! 꼬임이 힘이에요."},"fit":{"title":"구동 줄 끼우기","btn":"덜컹이에 끼우기","done":"바퀴가 돌아요! 계기판 불이 하나 켜졌어요."},"knot":{"title":"매듭 줄 만들기","lead":"남은 끈에 같은 간격으로 매듭을 지어요. 재는 줄이 돼요.","btn":"매듭 짓기","done":"매듭 줄이 생겼어요! 휴가 허리에 찼어요."},"rv":1,"why":"탐험대 이야기(창작). 실을 꼰 쪽과 반대로 꼬아야 끈이 풀리지 않는다는 것은 일반 사실로 확인이 필요하다."},"measure":{"title":"재 보기","lead":"매듭 줄로는 길이를 잴 수 있어요. 성경에 크기가 적힌 것을 재 볼까요?","self":{"btn":"덜컹이 재 보기","done":"덜컹이의 키는 매듭 일곱 개만큼이에요."},"ark":{"after":"OT-03","btn":"방주 재 보기","find":{"type":"find","ref":"창 6:15","prompt":"성경책에서 창세기 6장 15절을 찾아 읽어 보세요.","confirm":{"prompt":"방주의 길이는 몇 규빗인가요?","options":[{"label":"삼백 규빗","ok":true},{"label":"백 규빗","basis":"본문에 없음"},{"label":"오백 규빗","basis":"본문에 없음"}]}},"done":"길이 삼백, 너비 오십, 높이 삼십 규빗. 한 규빗은 어른 팔꿈치에서 손끝까지쯤이에요(어림). 방주는 덜컹이를 백 대 넘게 한 줄로 세운 것보다 길어요.","rv":2,"why":"새 성경 물음(창 6:15). 규빗의 길이와 '덜컹이 백 대'는 어림이다."},"rv":1,"why":"탐험대 이야기(창작)."},"cards":[{"match":"감람나무 잔가지","why":"회전축에 바를 미끄러운 기름이 필요해서.","era":"홍수 뒤에 비둘기가 감람나무 새 잎을 물고 돌아왔어요. 모세는 백성이 들어갈 좋은 땅에 감람나무가 있다고 말했어요.","refs":["창 8:11","신 8:8"],"fix":"다 자라면 회전축 기름","make":"온실의 나무","rv":1,"why2":"재료 카드의 풀어 쓴 글."},{"match":"양털","why":"바퀴를 돌릴 꼬아서 질긴 줄이 필요해서.","era":"성경에는 양을 치는 사람들이 여럿 나와요. 양털과 삼을 구해 손으로 부지런히 일하는 사람 이야기도 있어요.","refs":["출 3:1","잠 31:13"],"fix":"구동 줄","make":"매듭 줄","rv":1,"why2":"재료 카드의 풀어 쓴 글."}],"notes":[{"id":"olive-land","after":"OT-03","q":"이 나무가 자라는 땅은 어디일까?","closeAfter":"OT-20","a":"여호수아가 전한 말씀 속에, 백성이 심지 않은 감람원의 열매를 먹고 있다는 말이 나와요.","ref":"수 24:13","rv":2,"why":"하나님의 말씀을 풀어 옮겼다(수 24:13). 온실의 나무와 그 땅의 감람을 잇는 것은 탐험대 이야기다."},{"id":"shepherds","after":"OT-09","q":"양 치는 사람이 성경에 또 나올까?","closeAfter":"OT-26","a":"다윗은 아버지의 양을 지키던 사람이었어요. 일지의 '양을 치던 사람들'을 펴 보세요.","ref":"삼상 17:34-35","rv":1,"why":"수첩 물음(탐험대 이야기)과 본문의 사실."}],"shepherds":{"title":"양을 치던 사람들","lead":"성경에 양을 치던 사람으로 적힌 사람들이에요. 장절을 성경책에서 직접 찾아 읽어 보세요.","rv":1,"why":"장절과 본문의 사실만 적었다.","list":[{"after":"OT-02","who":"아벨","ref":"창 4:2","text":"아벨은 양을 치는 사람이었어요."},{"after":"OT-08","who":"야곱의 아들들","ref":"창 37:12","text":"요셉의 형들은 아버지의 양 떼를 쳤어요."},{"after":"OT-09","who":"모세","ref":"출 3:1","text":"모세는 장인의 양 떼를 쳤어요."},{"after":"OT-26","who":"다윗","ref":"삼상 17:34-35","text":"다윗은 아버지의 양을 지켰고, 사자나 곰이 새끼를 물어 가면 따라가서 건져 냈다고 말했어요."},{"after":"OT-27","who":"다윗","ref":"삼하 7:8","text":"여호와께서는 양을 따르던 다윗을 데려다가 백성의 주권자로 삼았다고 하셨어요.","rv":2,"why":"하나님의 말씀을 풀어 옮겼다."}]},"lamb":{"title":"어린 양의 기록","lead":"성경이 어린 양을 두고 적은 곳들이에요. 모으는 것이 아니라 읽은 것을 적어 두는 기록이에요. 장절을 성경책에서 직접 찾아 읽어 보세요.","rv":3,"why":"구약의 제물과 그리스도의 연결(규칙서 3.5). 대표 결정 6차로 감수 전에 모든 나이에 연다. 차례, 8~10세 표현, 신약 장절을 여는 때를 감수가 정해야 한다.","list":[{"after":"OT-02","ref":"창 4:4","text":"아벨은 양 떼의 첫 새끼를 제물로 드렸고, 하나님은 아벨의 제물을 받으셨어요."},{"after":"OT-06","ref":"창 22:7-8","text":"이삭이 번제에 쓸 어린 양이 어디 있는지 묻자, 아브라함은 하나님이 마련하실 것이라고 대답했어요."},{"after":"OT-06","ref":"창 22:13","text":"아브라함은 뿔이 수풀에 걸린 숫양을 아들 대신 번제로 드렸어요."},{"after":"OT-10","ref":"출 12:5-7","text":"흠 없는 어린 양을 준비하고, 그 피를 집 문에 발랐어요."},{"after":"OT-10","ref":"출 12:13","text":"하나님은 그 피를 보고 그 집을 넘어가겠다고 하셨어요.","why":"하나님의 말씀을 풀어 옮겼다."},{"after":"OT-33","ref":"사 53:7","text":"이사야서는 어린 양처럼 끌려가면서도 입을 열지 않은 이를 말해요.","why":"이사야 53장의 '그'가 누구인지는 풀이다."}],"nt":{"after":"OT-10","title":"신약에서 이어 읽기","list":[{"ref":"요 1:29","text":"요한은 예수님이 오시는 것을 보고, 세상의 죄를 없애는 하나님의 어린 양이라고 말했어요."},{"ref":"고전 5:7","text":"바울은 그리스도가 우리의 유월절 양으로 희생되셨다고 썼어요."}],"rv":3,"why":"그리스도와의 연결. 신약 한글 본문은 대조하지 못했다(KJV만). 유월절 장면 뒤에 열리게 했는데, 여는 때는 대표와 감수가 정한다."}}}};
